#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/spi.h>

// Define constants
#define SPI0_BASE 0
#define GPIO8 8
#define GPIO10 10
#define GPIO9 9
#define GPIO11 11
#define MCP3008_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_MODE0 0
#define SPI_MODE1 1
#define SPI_MODE2 2
#define SPI_MODE3 3
#define SPI_MODE4 4
#define SPI_MODE5 5
#define SPI_MODE6 6
#define SPI_MODE7 7

// Define error codes
#define SPI_ERROR -1
#define SPI_OK 0

// Define structure for SPI device
struct spi_device {
    int fd;
    int mode;
};

// Function to initialize SPI device
int init_spi(struct spi_device *device) {
    int ret = 0;
    int err = 0;

    // Open SPI device
    device->fd = spi_open(SPI0_BASE, GPIO8, GPIO10, GPIO9, GPIO11, SPI_SPEED, SPI_MODE);
    if (device->fd < 0) {
        printf("Error opening SPI device\n");
        return -1;
    }

    // Set SPI mode
    ret = spi_set_mode(device->fd, SPI_MODE);
    if (ret < 0) {
        printf("Error setting SPI mode\n");
        err = 1;
    }

    return err;
}

// Function to read from SPI device
int read_spi(struct spi_device *device) {
    int ret = 0;
    int err = 0;
    unsigned char data[3];

    // Read from SPI device
    ret = spi_xfer(device->fd, NULL, NULL, 1, data, 3);
    if (ret < 0) {
        printf("Error reading from SPI device\n");
        err = 1;
    }

    return err;
}

// Function to close SPI device
void close_spi(struct spi_device *device) {
    if (device->fd >= 0) {
        spi_close(device->fd);
        device->fd = -1;
    }
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    close_spi((struct spi_device *)NULL);
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize GPIO pins
    int gpio8 = gpioGet(GPIO8);
    int gpio10 = gpioGet(GPIO10);
    int gpio9 = gpioGet(GPIO9);
    int gpio11 = gpioGet(GPIO11);

    // Initialize SPI device
    struct spi_device device;
    device.mode = SPI_MODE0;
    if (init_spi(&device) != 0) {
        printf("Failed to initialize SPI device\n");
        return 1;
    }

    while (1) {
        // Read from SPI device
        if (read_spi(&device) != 0) {
            printf("Failed to read from SPI device\n");
            break;
        }

        // Read raw ADC value
        unsigned char adc_value = device.data[0];
        int adc_value_int = (adc_value & 0x3FF);

        // Print ADC value and timestamp
        printf("%d %d\n", (int)time(NULL), adc_value_int);

        // Sleep for 1 second
        sleep(1);
    }

    // Close SPI device
    close_spi(&device);

    return 0;
}

