#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDRESS 0x49
#define I2C_ADDRESS2 0x4A
#define GAIN 4.096
#define RATE 128
#define CHANNEL 0
#define TIME 500
#define BUFFER_SIZE 16

int main(int argc, char **argv) {
    int i, j;
    int adc;
    unsigned int result;
    unsigned int current;
    struct pigpio *gpio;
    struct i2c_config i2c_config;
    struct i2c_handle i2c_handle;
    struct i2c_handle i2c_handle2;

    // Initialize the GPIO library
    gpio = pigpio_init();
    if (gpio == -1) {
        perror("pigpio_init");
        return 1;
    }

    // Configure GPIO2 and GPIO3 as SDA and SCL for I2C
    if (gpio->gpio_fsel(2, PI_INPUT) == -1) {
        perror("gpio_fsel");
        return 1;
    }
    if (gpio->gpio_fsel(3, PI_INPUT) == -1) {
        perror("gpio_fsel");
        return 1;
    }

    // Configure I2C
    i2c_config.i2c_addr = I2C_ADDRESS;
    i2c_config.i2c_addr2 = I2C_ADDRESS2;
    i2c_config.i2c_freq = 100000;
    i2c_config.i2c_mode = I2C_MODE_MASTER;
    i2c_config.i2c_timeout = 10;
    i2c_config.i2c_speed = I2C_SPEED_100KHZ10;

    // Create I2C handles
    if (i2c_init(&i2c_config, &i2c_handle) == -1) {
        perror("i2c_init");
        return 1;
    }
    if (i2c_init2(&i2c_config, &i2c_handle2) == -1) {
        perror("i2c_init2");
        return 1;
    }

    while (1) {
        // Read the current from the sensor
        if (i2c_read(i2c_handle, I2C_ADDRESS, &result, 2) == -1) {
            perror("i2c_read");
            continue;
        }
        if (i2c_read(i2c_handle2, I2C_ADDRESS2, &result, 2) == -1) {
            perror("i2c_read");
            continue;
        }

        // Check if the sensor is present
        if (result[0] == 0x00) {
            printf("Sensor not found\n");
            continue;
        }

        // Convert the result to amperes
        current = (result[0] * GAIN / (RATE * 0.000016) / 65536.0);

        // Log the current value
        printf("%.2f A\n", current);

        // Sleep for 500ms
        sleep(TIME / 1000.0);
    }

    // Clean up
    i2c_close(i2c_handle);
    i2c_close(i2c_handle2);
    pigpio_close(gpio);

    return 0;
}

