#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <signal.h>

#define GPIO4 4
#define GPIO27 27
#define I2C_ADDRESS 0x49
#define ADC_CHANNEL 0
#define DEBOUNCE_TIME 50
#define FIRE_THRESHOLD 60
#define LOG_FILE "fire_log.txt"

int main() {
    int gpio, i2c, adc, ret;
    int fire_detected = 0;
    int flame_detected = 0;
    int temperature_exceeded = 0;
    int log_fd = -1;
    int buzzer_state = 0;
    struct sigaction sa;

    // Initialize GPIO
    if (gpio = gpioInitialise()) {
        fprintf(stderr, "Error initializing GPIO\n");
        exit(1);
    }

    // Initialize I2C
    if ((i2c = gpioGetFd(GPIO4)) < 0) {
        fprintf(stderr, "Error getting I2C handle for GPIO4\n");
        gpioTerminate();
        exit(1);
    }

    // Configure I2C
    if (gpioI2CSetClock(i2c, 100000) < 0) {
        fprintf(stderr, "Error setting I2C clock\n");
        gpioTerminate();
        exit(1);
    }

    // Configure ADC
    if ((adc = gpioGetFd(GPIO4)) < 0) {
        fprintf(stderr, "Error getting ADC handle for GPIO4\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioI2COpen(i2c, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioI2CAvailableBits(adc, ADC_CHANNEL) < 0) {
        fprintf(stderr, "Error configuring ADC channel\n");
        gpioTerminate();
        exit(1);
    }

    // Set up signal handler
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler\n");
        gpioTerminate();
        exit(1);
    }

    while (1) {
        // Read flame sensor
        int flame_value = 0;
        for (int i = 0; i < DEBOUNCE_TIME; i++) {
            if (gpioRead(adc, GPIO4) == 1) {
                flame_value = 1;
                break;
            }
        }

        // Read temperature sensor
        int temperature_value = 0;
        if (gpioI2CRead(i2c, ADC_CHANNEL, &temperature_value) < 0) {
            if (errno == EIO) {
                // Ignore I2C error, continue
            } else {
                fprintf(stderr, "Error reading temperature sensor\n");
                gpioTerminate();
                exit(1);
            }
        }

        // Check for fire condition
        if (flame_value && temperature_value > FIRE_THRESHOLD) {
            fire_detected = 1;
            temperature_exceeded = 1;
        } else if (flame_value) {
            flame_detected = 1;
        } else if (temperature_value > FIRE_THRESHOLD) {
            temperature_exceeded = 1;
        }

        // Log events
        if (fire_detected && temperature_exceeded) {
            if (log_fd < 0) {
                if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
                    fprintf(stderr, "Error opening log file\n");
                    gpioTerminate();
                    exit(1);
                }
            }
            fprintf(log_fd, "%d %d\n", time(NULL), temperature_value);
            close(log_fd);
            log_fd = -1;
        } else if (flame_detected) {
            if (log_fd >= 0) {
                fprintf(log_fd, "Flame detected!\n");
                close(log_fd);
                log_fd = -1;
            }
        } else if (temperature_exceeded) {
            if (log_fd >= 0) {
                fprintf(log_fd, "%d\n", temperature_value);
                close(log_fd);
                log_fd = -1;
            }
        }

        // Activate buzzer
        if (fire_detected && temperature_exceeded) {
            if (!buzzer_state) {
                gpioWrite(GPIO27, 1);
                buzzer_state = 1;
                sleep(2);
                gpioWrite(GPIO27, 0);
                buzzer_state = 0;
            }
        }
    }

    // Clean up
    gpioTerminate();
    gpioI2CClose(i2c);
    if (log_fd >= 0) {
        close(log_fd);
    }
    gpioI2CClose(i2c);
    gpioTerminate();
    return 0;
}

