// Structure to hold sensor data
typedef struct {
    uint16_t ox;
    uint16_t red;
} sensor_data_t;

// Function to convert OX value to CO concentration in ppm
uint16_t co_to_ppm(uint16_t ox) {
    return (ox * 10);
}

// Function to read sensor data from I2C bus
sensor_data_t read_sensor_data(pigpio_t *gpio) {
    sensor_data_t data;
    uint8_t buffer[4];

    // Initialize I2C bus
    if (gpio_i2c_open(gpio, I2C_ADDRESS, 100000) < 0) {
        printf("I2C initialization failed\n");
        exit(1);
    }

    // Read 4 bytes from I2C bus
    if (gpio_i2c_read(gpio, I2C_ADDRESS, buffer, 4) < 0) {
        printf("I2C read failed\n");
        gpio_i2c_close(gpio);
        exit(1);
    }

    // Extract OX and RED values from 4-byte response
    data.ox = (buffer[0] << 8) | buffer[1];
    data.red = (buffer[2] << 8) | buffer[3];

    gpio_i2c_close(gpio);
    return data;
}

// Function to write data to file
void write_to_file(const char *filename, const char *data) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        printf("File I/O error\n");
        exit(1);
    }

    fprintf(file, "%s\n", data);
    fclose(file);
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    printf("Received signal %d, exiting...\n", sig);
    exit(0);
}

