        printf("File I/O error\n");
        pigpio_close(gpio);
        exit(1);
    }

    while (1) {
        // Read sensor data
        sensor_data_t data = read_sensor_data(gpio);

        // Convert OX value to CO concentration in ppm
        uint16_t co_ppm = co_to_ppm(data.ox);

        // Check if CO ppm value exceeds alert threshold
        if (co_ppm >= ALERT_THRESHOLD) {
            write_to_file("alert_log.txt", "CO ppm alert: ");
            write_to_file("alert_log.txt", "%d\n", co_ppm);
        }

        // Write CO ppm value to co_log.txt
        write_to_file("co_log.txt", "%d\n", co_ppm);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanly close files and pigpio
    fclose(co_log_file);
    fclose(alert_log_file);
    pigpio_close(gpio);

    return 0;
}

