#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>

#define I2C_ADDRESS 0x1A
#define I2C_ADDRESS2 0x1B
#define GPIO2 2
#define GPIO3 3
#define SAMPLE_INTERVAL 100
#define SAMPLE_RATE 100
#define FILE_NAME "audio_log.txt"

int main(int argc, char **argv) {
    int i, j, fd, fd2, i2c_fd, i2c_fd2;
    unsigned char buf[2];
    unsigned int sample1, sample2;
    unsigned long timestamp;
    double avg;
    struct stat sb;
    struct sigaction sa;
    struct sigaction sa2;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO as output
    gpioSetMode(GPIO2, PI_OUTPUT);
    gpioSetMode(GPIO3, PI_OUTPUT);

    // Set GPIO as output
    gpioWrite(GPIO2, 0);
    gpioWrite(GPIO3, 0);

    // Create I2C handles
    i2c_fd = pigpioOpen(1, PI_I2C, NULL);
    if (i2c_fd < 0) {
        perror("pigpioOpen");
        return 1;
    }

    i2c_fd2 = pigpioOpen(1, PI_I2C, NULL);
    if (i2c_fd2 < 0) {
        perror("pigpioOpen");
        return 1;
    }

    // Set I2C addresses
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, I2C_ADDRESS2) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(i2c_fd, I2C_SET_CLOCK, 400000) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ioctl(i2c_fd2, I2C_SET_CLOCK, 400000) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set I2C bit-banging
    pigpioSetBitBangedClock(i2c_fd, 1);
    pigpioSetBitBangedClock(i2c_fd2, 1);

    // Set GPIO as input
    gpioSetMode(GPIO2, PI_INPUT);
    gpioSetMode(GPIO3, PI_INPUT);

    // Create file
    fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigintHandler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    sa2.sa_handler = sigtermHandler;
    sa2.sa_flags = SA_RESTART;
    sigemptyset(&sa2.sa_mask);
    if (sigaction(SIGTERM, &sa2, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Read from microphones
        if (read(i2c_fd, buf, 2) < 0) {
            printf("Error reading from I2C device 1\n");
            printf("Error value: -999.0 dB\n");
            fwrite(&(-999.0), sizeof(double), 1, fd);
            sleep(1);
            continue;
        }
        if (read(i2c_fd2, buf, 2) < 0) {
            printf("Error reading from I2C device 2\n");
            printf("Error value: -999.0 dB\n");
            fwrite(&(-999.0), sizeof(double), 1, fd);
            sleep(1);
            continue;
        }

        // Convert to voltage
        sample1 = (buf[0] << 8) | buf[1];
        sample2 = (buf[2] << 8) | buf[3];

        // Compute average
        avg = (sample1 + sample2) / 2.0;

        // Convert to decibels
        avg = 20 * log10(avg / 32767.0);

        // Append to file
        timestamp = time(NULL);
        fwrite(&timestamp, sizeof(unsigned long), 1, fd);
        fwrite(&avg, sizeof(double), 1, fd);

        // Sleep
        sleep(SAMPLE_INTERVAL / 1000.0);
    }

    // Clean up
    pigpioCleanUp();
    close(fd);
    close(i2c_fd);
    close(i2c_fd2);

    return 0;
}

void sigintHandler(int sig) {
    // Close I2C handles
    close(i2c_fd);
    close(i2c_fd2);

    // Close file
    close(fd);

    // Terminate program
    exit(0);
}

void sigtermHandler(int sig) {
    // Close I2C handles
    close(i2c_fd);
    close(i2c_fd2);

    // Close file
    close(fd);

    // Terminate program
    exit(0);
}

