#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

#define BUFFER_SIZE 100
#define LED_PIN 17
#define ADC_CHANNEL 0
#define I2C_ADDRESS 0x4A
#define I2C_SDA GPIO2
#define I2C_SCL GPIO3
#define CURRENT_THRESHOLD 50.0

int gpio = -1;
int adc = -1;
int buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_size = 0;
int led = -1;

void init_gpio() {
    if (gpio == -1) {
        gpio = gpioInitialise();
        if (gpio < 0) {
            printf("Failed to initialize GPIO\n");
            exit(1);
        }
    }
    gpioSetMode(I2C_SDA, GPIO_MODE_INPUT);
    gpioSetMode(I2C_SCL, GPIO_MODE_INPUT);
    gpioSetPullUpDowntime(I2C_SDA, GPIO_PULLUP_DISABLE);
    gpioSetPullUpDowntime(I2C_SCL, GPIO_PULLUP_DISABLE);
}

void init_adc() {
    if (adc == -1) {
        adc = gpioGetFd(I2C_SDA);
        if (adc < 0) {
            printf("Failed to get I2C file descriptor\n");
            exit(1);
        }
        gpioSetMode(adc, GPIO_MODE_OUTPUT);
        gpioSetLevel(adc, GPIO_HIGH);
        gpioSetMode(I2C_SCL, GPIO_MODE_OUTPUT);
        gpioSetLevel(I2C_SCL, GPIO_LOW);
        gpioSetMode(I2C_SDA, GPIO_MODE_INPUT);
        gpioSetPullUpDowntime(I2C_SDA, GPIO_PULLUP_DISABLE);
        gpioSetPullUpDowntime(I2C_SCL, GPIO_PULLUP_DISABLE);
    }
}

void read_adc() {
    if (gpio == -1 || adc == -1) {
        printf("GPIO or ADC not initialized\n");
        return;
    }
    unsigned char reg = 0;
    int status = i2cGetReg(adc, I2C_ADDRESS, &reg);
    if (status < 0) {
        printf("Failed to read I2C register\n");
        return;
    }
    if (reg & 0x80) {
        printf("Sensor not present\n");
        return;
    }
    unsigned int raw = (reg & 0x3F) << 8 | reg;
    int current = (raw * 2.5) / 4096.0;
    if (buffer_size < BUFFER_SIZE) {
        buffer[buffer_index] = current;
        buffer_size++;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    } else {
        buffer[buffer_index] = current;
    }
    if (buffer_size > 1) {
        double avg = 0;
        for (int i = 0; i < buffer_size; i++) {
            avg += buffer[i];
        }
        avg /= buffer_size;
        if (avg > CURRENT_THRESHOLD) {
            gpioSetLevel(led, GPIO_HIGH);
        } else {
            gpioSetLevel(led, GPIO_LOW);
        }
    }
}

void cleanup() {
    if (gpio != -1) {
        gpioRelease(gpio);
        gpio = -1;
    }
    if (adc != -1) {
        gpioRelease(adc);
        adc = -1;
    }
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    init_gpio();
    init_adc();
    signal(SIGINT, sigint_handler);
    while (1) {
        read_adc();
        usleep(100000);
    }
    cleanup();
    return 0;
}

