#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>
#include <time.h>

#define I2C_ADDRESS 0x29
#define I2C Bus 1
#define CSV_FILE "color_log.csv"

int main(int argc, char *argv[]) {
    int fd;
    struct timespec delay;
    struct itimerval it;
    struct sigaction sa;
    struct stat sb;
    struct i2c_msg msg;
    struct i2c_file *file;
    char buffer[256];
    char filename[256];
    char timestamp[20];
    int i, j, r, g, b, clear;

    // Initialize signal handling
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Wait for at least 3ms after power-on
    usleep(3000000);

    // Open I2C file
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    if ((file = fopen(CSV_FILE, "w")) == NULL) {
        perror("fopen");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Check if file exists and create header row if not
    if (fstat(fd, &sb) < 0) {
        perror("fstat");
        fclose(file);
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (fstat(fd, &sb) < 0) {
        perror("fstat");
        fclose(file);
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (fseek(file, 0, SEEK_SET) < 0) {
        perror("fseek");
        fclose(file);
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (fscanf(file, "%*[^,],%*[^,],%*[^,],%*[^,]\n") < 0) {
        fprintf(file, "timestamp,clear,red,green,blue\n");
        fclose(file);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C driver
    if (i2c_init(I2C Bus, I2C_ADDRESS) < 0) {
        perror("i2c_init");
        fclose(file);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Wait for sensor to stabilize
    for (i = 0; i < 3; i++) {
        if (i2c_read(fd, &msg, 1) < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C read failed\n");
            } else {
                perror("i2c_read");
            }
            break;
        }
        usleep(100000);
    }

    // Main loop
    while (1) {
        // Read sensor values
        if (i2c_read(fd, &msg, 1) < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C read failed\n");
            } else {
                perror("i2c_read");
            }
            break;
        }
        clear = msg.data[0];
        r = msg.data[1];
        g = msg.data[2];
        b = msg.data[3];

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL));

        // Write to CSV file
        if (fprintf(file, "%s,%d,%d,%d,%d\n", timestamp, clear, r, g, b) < 0) {
            perror("fprintf");
            break;
        }

        // Wait for 1 second
        struct timeval tv;
        gettimeofday(&tv, NULL);
        tv.tv_sec += 1;
        tv.tv_usec = 0;
        nanosleep(&tv, NULL);
    }

    // Close I2C file
    if (i2c_close(fd) < 0) {
        perror("i2c_close");
    }

    // Close CSV file
    if (fclose(file) < 0) {
        perror("fclose");
    }

    // Clean up
    gpioTerminate();
    return 0;
}

