#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <signal.h>

#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_MOTOR 17
#define GPIO_LOG 16

#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000
#define SPI_DATA 0x00

#define FILE_NAME "current_log.csv"

int main() {
    int gpio_ce0, gpio_sclk, gpio_mosi, gpio_miso, gpio_motor, gpio_log;
    int fd;
    struct stat sb;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;
    unsigned char spi_buf[3];
    unsigned char spi_buf2[3];
    unsigned int adc_value;
    unsigned int current;
    int retry = 0;
    int overcurrent = 0;

    // Initialize GPIO
    gpio_ce0 = gpioGetConLevel(GPIO_CE0);
    gpio_sclk = gpioGetConLevel(GPIO_SCLK);
    gpio_mosi = gpioGetConLevel(GPIO_MOSI);
    gpio_miso = gpioGetConLevel(GPIO_MISO);
    gpio_motor = gpioGetConLevel(GPIO_MOTOR);
    gpio_log = gpioGetConLevel(GPIO_LOG);

    // Set GPIO modes
    gpioSetMode(GPIO_CE0, GPIO_MODE_OUTPUT);
    gpioSetMode(GPIO_SCLK, GPIO_MODE_OUTPUT);
    gpioSetMode(GPIO_MOSI, GPIO_MODE_OUTPUT);
    gpioSetMode(GPIO_MISO, GPIO_MODE_INPUT);
    gpioSetMode(GPIO_MOTOR, GPIO_MODE_OUTPUT);
    gpioSetMode(GPIO_LOG, GPIO_MODE_INPUT);

    // Set GPIO levels
    gpioWrite(GPIO_CE0, 0);
    gpioWrite(GPIO_SCLK, 1);
    gpioWrite(GPIO_MOSI, 1);
    gpioWrite(GPIO_MOTOR, 0);
    gpioWrite(GPIO_LOG, 0);

    // Open file
    fd = open(FILE_NAME, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa_int.sa_handler = sigint_handler;
    sa_term.sa_handler = sigterm_handler;
    sigemptyset(&sa);
    sigaddset(&sa, SIGINT);
    sigaddset(&sa, SIGTERM);
    sigaction(SIGINT, &sa_int, NULL);
    sigaction(SIGTERM, &sa_term, NULL);

    while (1) {
        // Wait for SPI to settle
        usleep(100000);

        // Check if SPI is ready
        if (gpioRead(GPIO_MISO) == 0) {
            // Read SPI
            gpioWrite(GPIO_CE0, 1);
            gpioWrite(GPIO_SCLK, 1);
            gpioWrite(GPIO_MOSI, 1);
            gpioWrite(GPIO_MOTOR, 0);
            gpioWrite(GPIO_LOG, 0);
            gpioRead(GPIO_MISO, spi_buf);
            gpioWrite(GPIO_CE0, 0);
            gpioWrite(GPIO_SCLK, 0);
            gpioWrite(GPIO_MOSI, 0);
            gpioWrite(GPIO_MOTOR, 0);
            gpioWrite(GPIO_LOG, 0);

            // Check for errors
            if (gpioRead(GPIO_MISO) != spi_buf[0]) {
                retry++;
                if (retry > 2) {
                    printf("SPI error\n");
                    break;
                }
                continue;
            }
            retry = 0;

            // Read ADC value
            gpioWrite(GPIO_CE0, 1);
            gpioWrite(GPIO_SCLK, 1);
            gpioWrite(GPIO_MOSI, 1);
            gpioWrite(GPIO_MOTOR, 0);
            gpioWrite(GPIO_LOG, 0);
            gpioRead(GPIO_MISO, spi_buf2);
            gpioWrite(GPIO_CE0, 0);
            gpioWrite(GPIO_SCLK, 0);
            gpioWrite(GPIO_MOSI, 0);
            gpioWrite(GPIO_MOTOR, 0);
            gpioWrite(GPIO_LOG, 0);

            // Check for errors
            if (gpioRead(GPIO_MISO) != spi_buf2[0]) {
                retry++;
                if (retry > 2) {
                    printf("ADC error\n");
                    break;
                }
                continue;
            }
            retry = 0;

            // Convert ADC value to current
            adc_value = spi_buf2[0] * 0.5;
            current = adc_value * 0.0005;

            // Check for overcurrent
            if (current > 10.0) {
                overcurrent = 1;
                gpioWrite(GPIO_MOTOR, 0);
                printf("Overcurrent detected, disabling motor\n");
                sleep(1);
                gpioWrite(GPIO_MOTOR, 1);
                printf("Motor re-enabled\n");
                overcurrent = 0;
            }

            // Write to file
            if (fwrite(&current, sizeof(unsigned int), 1, fd) < 0) {
                perror("write");
                break;
            }

            // Flush file
            fflush(fd);
        }

        // Check if file is full
        if (fstat(fd, &sb) < 0) {
            perror("fstat");
            break;
        }
        if (sb.st_size >= 1024) {
            printf("File is full, truncating\n");
            truncate(FILE_NAME, 0);
            ftruncate(fd, 0);
        }
    }

    // Close file
    if (close(fd) < 0) {
        perror("close");
    }

    // Release GPIO
    gpioWrite(GPIO_CE0, 0);
    gpioWrite(GPIO_SCLK, 0);
    gpioWrite(GPIO_MOSI, 0);
    gpioWrite(GPIO_MOTOR, 0);
    gpioWrite(GPIO_LOG, 0);

    return 0;
}

void sigint_handler(int sig) {
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    exit(0);
}

void sigterm_handler(int sig) {
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    gpioWrite(GPIO_CE0, 0);
    gpioWrite(GPIO_SCLK, 0);
    gpioWrite(GPIO_MOSI, 0);
    gpioWrite(GPIO_MOTOR, 0);
    gpioWrite(GPIO_LOG, 0);
    exit(0);
}

