#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x1D
#define I2C Bus 1

int main(int argc, char **argv) {
    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "libgpiod initialization failed\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = pigpio_open(I2C Bus, I2C_ADDRESS, PI_MMAP);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C open failed: %d\n", errno);
        gpiod_cleanup();
        return 1;
    }

    // Open log file
    char log_file[] = "pressure_log.csv";
    struct stat sb;
    if (stat(log_file, &sb) != 0) {
        if (mkdir(log_file, 0644) != 0) {
            fprintf(stderr, "Failed to create log file: %d\n", errno);
            pigpio_close(i2c_fd);
            gpiod_cleanup();
            return 1;
        }
    }
    FILE *log_file_ptr = fopen(log_file, "a");
    if (log_file_ptr == NULL) {
        fprintf(stderr, "Failed to open log file: %d\n", errno);
        pigpio_close(i2c_fd);
        gpiod_cleanup();
        return 1;
    }

    // Write header row
    fprintf(log_file_ptr, "timestamp,pressure\n");
    fflush(log_file_ptr);

    while (1) {
        // Read pressure from sensor
        uint8_t reg = pigpio_i2c_read(i2c_fd, I2C_ADDRESS, 0x00, 1);
        if (reg < 0) {
            fprintf(stderr, "I2C read failed: %d\n", errno);
            continue;
        }

        // Check for sensor-absent conditions
        if (reg == 0x00) {
            fprintf(stderr, "Sensor not found\n");
            continue;
        }

        // Calculate pressure
        uint16_t pressure = (reg & 0x3F) << 8 | (reg >> 5);

        // Convert pressure to kPa
        double pressure_kPa = pressure / 4.0;

        // Append to log file
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", time_info);
        fprintf(log_file_ptr, "%s,%f\n", timestamp, pressure_kPa);
        fflush(log_file_ptr);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C handle and log file
    pigpio_close(i2c_fd);
    fclose(log_file_ptr);

    // Clean up
    gpiod_cleanup();

    return 0;
}

