#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_CE GPIO_8
#define SPI_SCLK GPIO_11
#define SPI_MOSI GPIO_10
#define SPI_MISO GPIO_9
#define GPIO_SHUT_DOWN GPIO_27
#define ADC_CHANNEL 0
#define LOG_FILE "current_log.txt"

int main() {
    int spi_fd, gpio_fd;
    int adc_value;
    struct timespec ts;
    struct stat sb;
    int overcurrent = 0;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI
    if ((spi_fd = spiOpen(SPI_CE, SPI_SCLK, SPI_MOSI, SPI_MISO, SPI_MODE_0, SPI_SPEED) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((gpio_fd = open(LOG_FILE, O_RDWR | O_APPEND | O_CREAT, 0644) < 0) {
        perror("open");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        if ((adc_value = spiXfer(spi_fd, NULL, NULL, 1, 1000) < 0) {
            perror("spiXfer");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }

        // Check ADC value
        if (adc_value < 0 || adc_value > 1023) {
            perror("Invalid ADC value");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate current
        int current = (adc_value * 5.0 / 1023) * 16.0 / 1000.0;

        // Check for overcurrent
        if (current > 10) {
            overcurrent = 1;
            gpioWrite(GPIO_SHUT_DOWN, 1);
            printf("OVERCURRENT\n");
            break;
        }

        // Log current
        if (fstat(gpio_fd, &sb) < 0) {
            perror("fstat");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }
        if (fwrite(&ts.tv_sec, sizeof(ts.tv_sec), 1, gpio_fd) < 0) {
            perror("fwrite");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }
        if (fwrite(&current, sizeof(current), 1, gpio_fd) < 0) {
            perror("fwrite");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }
        if (fsync(gpio_fd) < 0) {
            perror("fsync");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }

        // Sleep
        nanosleep(&ts, NULL);
    }

    // Close log file
    if (close(gpio_fd) < 0) {
        perror("close");
        return 1;
    }

    // Close SPI
    if (close(spi_fd) < 0) {
        perror("close");
        return 1;
    }

    // Terminate GPIO
    gpioTerminate();

    // Call cleanup function
    pigpio_cleanup();

    return 0;
}

