    if (gpioMode(SPI_SCK, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(SPI_MOSI, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(SPI_MISO, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(GPIO_ALARM, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(GPIO_OUTPUT, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO_ALARM, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open("co_log.txt", O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Map log file
    struct stat sb;
    if (fstat(log_fd, &sb) < 0) {
        perror("fstat");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    void* log_ptr = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, log_fd, 0);
    if (log_ptr == MAP_FAILED) {
        perror("mmap");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up alarm
    struct itimerspec timer;
    timer.it_value.tv_sec = 1;
    timer.it_value.tv_nsec = 0;
    timer.it_interval.tv_sec = 1;
    timer.it_interval.tv_nsec = 0;
    if (ioctl(log_fd, FIONREAD, &timer) < 0) {
        perror("ioctl");
        munmap(log_ptr, sb.st_size);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Turn off alarm
        gpioWrite(GPIO_ALARM, 0);

        // Read SPI
        unsigned char data[3];
        if (gpioTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, data, 3, 100) < 0) {
            perror("gpioTransfer");
            sleep(1);
            continue;
        }

        // Check for errors
        if (data[0] & 0x80) {
            printf("SPI error\n");
            sleep(1);
            continue;
        }

        // Read voltage
        float voltage = (data[0] * 3.3f / 65535.0f);
        if (voltage > 2.5f) {
            gpioWrite(GPIO_ALARM, 1);
        } else {
            gpioWrite(GPIO_ALARM, 0);
        }

        // Log data
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        char log_str[20];
        sprintf(log_str, "%s,Voltage: %.2fV", timestamp, voltage);
        fwrite(log_str, strlen(log_str), 1, log_ptr);

        // Turn on alarm
        gpioWrite(GPIO_ALARM, 1);
    }

    // Clean up
    munmap(log_ptr, sb.st_size);
    close(log_fd);
    gpioTerminate();
    return 0;
