        FILE *log_file = fopen(FILE_NAME, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            continue;
        }
        fprintf(log_file, "%s %d\n", timestamp, pressure);
        fclose(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    adcsample_close(adc_fd);
    i2c_close(i2c_fd);
    pigpio_close(gpio_fd);

    return 0;
}
```

This code initializes the necessary GPIO pins, I2C bus, and ADC on the Raspberry Pi 4 Model B. It then enters a loop where it reads the pressure data from the Melexis MLX90830 sensor, validates the data, converts it to pressure, and logs it to a file. The program continues to run until it is interrupted by a SIGINT (Ctrl-C). The resources are cleaned up on exit.

