#include <stdbool.h>

// Define constants
#define I2C_ADDRESS 0x1E
#define I2C_BUFFER_SIZE 2
#define LOG_FILE "biometric_log.csv"

// Define structures
typedef struct {
    uint16_t ir;
    uint16_t red;
} sensor_data_t;

// Function to handle I2C read error
void i2c_error_handler(int fd, int error) {
    if (error == -1) {
        printf("I2C read error\n");
    } else {
        printf("I2C error: %d\n", error);
    }
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    if (i2c_read(fd, I2C_ADDRESS, &data.ir, sizeof(data.ir)) != sizeof(data.ir)) {
        i2c_error_handler(fd, -1);
        return (sensor_data_t){0, 0};
    }
    if (i2c_read(fd, I2C_ADDRESS, &data.red, sizeof(data.red)) != sizeof(data.red)) {
        i2c_error_handler(fd, -1);
        return (sensor_data_t){0, 0};
    }
    return data;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(file, "%d,%d,%d,0\n", time(NULL), data.ir, data.red);
    fclose(file);
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    int fd = -1;
    if (i2c_open(I2C_ADDRESS, &fd) == -1) {
        printf("Error opening I2C handle\n");
        return;
