#include <errno.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define LOG_FILE "flow_log.csv"

int main(int argc, char **argv) {
    int spi_fd, adc_fd;
    int adc_value;
    double flow_rate;
    struct timespec ts;
    struct stat sb;
    char log_line[256];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI device
    if ((spi_fd = spiOpen(0, SPI_MODE, SPI_SPEED, SPI_CHANNEL)) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Open ADC device
    if ((adc_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("open");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    if (access(LOG_FILE, F_OK) == -1) {
        if (mkdir(LOG_FILE, 0755) < 0) {
            perror("mkdir");
            close(adc_fd);
            close(spi_fd);
            gpioTerminate();
            return 1;
        }
    }
    if ((sb.st_mode = fstatat(0, LOG_FILE, &sb)) < 0) {
        perror("fstatat");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        if (read(adc_fd, &adc_value, sizeof(adc_value)) < sizeof(adc_value)) {
            perror("read");
            continue;
        }

        // Check for sensor-absent conditions
        if (adc_value == 0 || adc_value == 4095) {
            continue;
        }

        // Calculate flow rate
        flow_rate = (adc_value / 4096.0) * 1000.0;

        // Validate flow rate
        if (flow_rate < 0.0 || flow_rate > 5.0) {
            fprintf(stderr, "Error: out-of-range flow rate: %f\n", flow_rate);
            continue;
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Format log line
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S.%u,%f,%.1f", &ts, flow_rate);

        // Append to log file
        if (fopen(LOG_FILE, "a") == NULL) {
            perror("fopen");
            continue;
        }
        fprintf(LOG_FILE, "%s\n", log_line);
        fclose(LOG_FILE);

        // Flush log file
        if (fsync(LOG_FILE) < 0) {
            perror("fsync");
        }
    }

    // Close SPI device
    if (close(spi_fd) < 0) {
        perror("close");
    }

    // Close ADC device
    if (close(adc_fd) < 0) {
        perror("close");
    }

    // Terminate GPIO
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
    }

    return 0;
}

