#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>
#include <syslog.h>

#define I2C_ADDRESS 0x68
#define I2C Bus 1
#define I2C_TIMEOUT 100
#define I2C_RETRY 5
#define CSV_FILE "environmental_data.csv"

int main() {
    int fd;
    int ret;
    unsigned char i2c_buf[7];
    struct timespec ts;
    struct timespec last_ts;
    struct stat sb;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    fd = pigpioOpen(I2C Bus, I2C_ADDRESS, I2C_TIMEOUT);
    if (fd < 0) {
        perror("pigpioOpen");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    if ((ret = open(CSV_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("open");
        return 1;
    }

    while (1) {
        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Check if it's been more than 5 seconds since the last reading
        if (time(NULL) - last_ts.tv_sec > 5) {
            last_ts = ts;
        }

        // Issue high-precision measurement command
        if ((ret = pigpioIoctl(fd, 0x80, NULL)) < 0) {
            if (errno == EIO) {
                // Wait for 5 seconds and retry
                sleep(5);
                continue;
            } else {
                perror("pigpioIoctl");
                return 1;
            }
        }

        // Wait for conversion to complete
        if ((ret = pigpioIoctl(fd, 0x81, NULL)) < 0) {
            if (errno == EIO) {
                // Wait for 5 seconds and retry
                sleep(5);
                continue;
            } else {
                perror("pigpioIoctl");
                return 1;
            }
        }

        // Read 6-byte result
        if ((ret = pigpioIoctl(fd, 0x82, i2c_buf)) < 0) {
            if (errno == EIO) {
                // Wait for 5 seconds and retry
                sleep(5);
                continue;
            } else {
                perror("pigpioIoctl");
                return 1;
            }
        }

        // Apply calibration formulas
        unsigned char pressure = (i2c_buf[0] << 8) | i2c_buf[1];
        unsigned char temperature = (i2c_buf[2] << 8) | i2c_buf[3];
        unsigned char crc = i2c_buf[4];
        unsigned char raw_temperature = (temperature >> 4);
        unsigned char raw_pressure = (pressure >> 4);

        // Convert to Celsius and pascals
        float celsius = (raw_temperature - 273.15) * 0.01;
        float pascals = raw_pressure * 0.01;

        // Log data
        if (fscanf(CSV_FILE, "%*s") == 0) {
            fprintf(CSV_FILE, "%ld,%f,%f\n", ts.tv_sec, celsius, pascals);
        } else {
            fprintf(CSV_FILE, ",%f,%f\n", celsius, pascals);
        }

        // Display data
        printf("Timestamp: %ld, Temperature: %.2f°C, Pressure: %.2f Pa\n", ts.tv_sec, celsius, pascals);

        // Close I2C file descriptor
        pigpioClose(fd);
        fd = -1;
    }

    // Close log file
    if (close(CSV_FILE) < 0) {
        perror("close");
        return 1;
    }

    return 0;
}

