#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000
#define SPI_CS 18
#define ADC_CHANNEL 0
#define FILE_NAME "moisture_log.txt"

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize the SPI library
    if (gpioSetupSPI(SPI_CS, SPI_MODE, SPI_SPEED) < 0) {
        perror("gpioSetupSPI");
        gpioTerminate();
        return 1;
    }

    // Open the log file for writing
    FILE *log_file = fopen(FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read the ADC value
        unsigned int adc_value = 0;
        if (gpioGetRaw(SPI_CS, ADC_CHANNEL, &adc_value) < 0) {
            perror("gpioGetRaw");
            gpioTerminate();
            return 1;
        }

        // Check if the ADC value is within the valid range
        if (adc_value < 0 || adc_value > 1023) {
            printf("Invalid ADC value: %u\n", adc_value);
            continue;
        }

        // Get the current time
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", time_info);

        // Append the timestamp and ADC value to the log file
        fprintf(log_file, "%s,%u\n", timestamp, adc_value);

        // Sleep for 60 seconds before taking the next reading
        sleep(60);
    }

    // Close the log file
    fclose(log_file);

    // Terminate the GPIO library
    gpioTerminate();

    return 0;
}

