#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <json-c/json.h>

// Define constants
#define GPIO_CE 8
#define GPIO_MISO 9
#define GPIO_MOSI 10
#define GPIO_SCLK 11
#define GPIO_LED 17
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define LED_PIN GPIO_LED
#define LED_HIGH 1
#define LED_LOW 0
#define HYST 5
#define READ_INTERVAL 5000
#define JSON_FILE "water_levels.json"

// Define the JSON structure
typedef struct {
    char timestamp[32];
    int level;
} water_level;

// Function to initialize the GPIO pins
void init_gpio() {
    int gpio = gpioGetConLevel(GPIO_CE);
    if (gpio != 0) {
        printf("Error: GPIO %d is not available\n", GPIO_CE);
        exit(1);
    }

    gpio = gpioSetup(GPIO_CE, GPIO_MODE_OUTPUT);
    if (gpio < 0) {
        printf("Error: Unable to set GPIO %d to output mode\n", GPIO_CE);
        exit(1);
    }

    gpio = gpioSetup(GPIO_MISO, GPIO_MODE_INPUT);
    if (gpio < 0) {
        printf("Error: Unable to set GPIO %d to input mode\n", GPIO_MISO);
        exit(1);
    }

    gpio = gpioSetup(GPIO_MOSI, GPIO_MODE_OUTPUT);
    if (gpio < 0) {
        printf("Error: Unable to set GPIO %d to output mode\n", GPIO_MOSI);
        exit(1);
    }

    gpio = gpioSetup(GPIO_SCLK, GPIO_MODE_OUTPUT);
    if (gpio < 0) {
        printf("Error: Unable to set GPIO %d to output mode\n", GPIO_SCLK);
        exit(1);
    }

    gpio = gpioSetup(GPIO_LED, GPIO_MODE_OUTPUT);
    if (gpio < 0) {
        printf("Error: Unable to set GPIO %d to output mode\n", GPIO_LED);
        exit(1);
    }

    gpio = gpioWrite(GPIO_LED, LED_LOW);
    if (gpio < 0) {
        printf("Error: Unable to set GPIO %d to low\n", GPIO_LED);
        exit(1);
    }
}

// Function to read the analog output of the DFRobot Gravity Analog Water Level Sensor
int read_sensor() {
    int ret = pigpioRead(SPI0, GPIO_MISO, SPI_MODE, SPI_SPEED, 0);
    if (ret < 0) {
        printf("Error: Unable to read from SPI0\n");
        return -1;
    }

    return ret;
}

// Function to write the JSON data to the file
void write_json(water_level *data) {
    FILE *file = fopen(JSON_FILE, "a");
    if (file == NULL) {
        printf("Error: Unable to open file %s\n", JSON_FILE);
        return;
    }

    fprintf(file, "[\n");
    struct tm *time = localtime(&time_t);
    strftime(data->timestamp, sizeof(data->timestamp), "%Y-%m-%d %H:%M:%S.%06d", time);
    fprintf(file, "{\"timestamp\":\"%s\",\"level\":%d}", data->timestamp, data->level);
    if (ferror(file)) {
        printf("Error: Unable to write to file %s\n", JSON_FILE);
        fclose(file);
        return;
    }
    fprintf(file, "\n");
    fclose(file);
}

// Function to handle the main loop
void main_loop() {
    int level;
    water_level data;
    struct timespec sleep_time;
    struct timespec last_read;

    // Initialize the GPIO pins
    init_gpio();

    // Initialize the last read time
    clock_gettime(CLOCK_REALTIME, &last_read);

    while (1) {
        // Read the sensor
        level = read_sensor();
        if (level < 0) {
            continue;
        }

        // Convert the analog value to a percentage
        level = (level * 100) / 1023;

        // Check if the level has changed
        if (clock_gettime(CLOCK_REALTIME, &last_read) != last_read) {
            // Write the data to the JSON file
            data.level = level;
            write_json(&data);

            // Update the last read time
            last_read = clock_gettime(CLOCK_REALTIME);

            // Check if the level exceeds the threshold
            if (level > 75) {
