#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <time.h>

#define SPI0_BASE 0x3F200000
#define SPI0_CE 8
#define SPI0_MOSI 10
#define SPI0_MISO 9
#define SPI0_SCK 11
#define ADC_BASE 0x30000000
#define ADC_CHANNEL 0
#define ADC_WIDTH 10
#define LOG_FILE "soil_moisture.log"

int main(int argc, char *argv[]) {
    int spi_fd, adc_fd;
    unsigned char adc_value;
    unsigned int adc_value_10bit;
    unsigned int moisture_percentage;
    struct timespec ts;
    struct sigaction sa;
    struct stat sb;

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    // Open SPI0
    if ((spi_fd = open("/dev/spi0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening SPI0: %s\n", strerror(errno));
        return 1;
    }

    // Configure SPI0
    if (ioctl(spi_fd, SPI_IOC_SET_MODE, SPI0_CE, 0, SPI_MODE_0) < 0) {
        fprintf(stderr, "Error configuring SPI0: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Open ADC
    if ((adc_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening ADC: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure ADC
    if (ioctl(adc_fd, ADC_SET_CHANNEL, ADC_CHANNEL) < 0) {
        fprintf(stderr, "Error configuring ADC: %s\n", strerror(errno));
        close(adc_fd);
        close(spi_fd);
        return 1;
    }

    if (ioctl(adc_fd, ADC_SET_WIDTH, ADC_WIDTH) < 0) {
        fprintf(stderr, "Error configuring ADC: %s\n", strerror(errno));
        close(adc_fd);
        close(spi_fd);
        return 1;
    }

    // Open log file
    if ((sb.st_dev = stat(LOG_FILE, &sb)) < 0) {
        if (errno == ENOENT) {
            if (mkdir(LOG_FILE, 0755) < 0) {
                fprintf(stderr, "Error creating log file: %s\n", strerror(errno));
                close(adc_fd);
                close(spi_fd);
                return 1;
            }
        } else {
            fprintf(stderr, "Error accessing log file: %s\n", strerror(errno));
            close(adc_fd);
            close(spi_fd);
            return 1;
        }
    }

    if ((fd = open(LOG_FILE, O_RDWR | O_CREAT, 0644)) < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(adc_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        if (read(adc_fd, &adc_value, 1) < 1) {
            fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
            close(adc_fd);
            close(spi_fd);
            close(fd);
            return 1;
        }

        // Convert ADC value to 10-bit value
        adc_value_10bit = (adc_value[0] << 8) | adc_value[1];

        // Calculate moisture percentage
        moisture_percentage = (adc_value_10bit / 1023.0) * 100;

        // Log data
        if (write(fd, &ts.tv_sec, sizeof(ts.tv_sec)) < 1) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(adc_fd);
            close(spi_fd);
            close(fd);
            return 1;
        }
        if (write(fd, &moisture_percentage, sizeof(moisture_percentage)) < 1) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(adc_fd);
            close(spi_fd);
            close(fd);
            return 1;
        }

        // Sleep for 1 second
        nanosleep(&ts, NULL);
    }

    // Cleanup
    close(adc_fd);
    close(spi_fd);
    close(fd);

    // Call ADC's call() cleanup routine
    if (ioctl(adc_fd, ADC_CALL, 0) < 0) {
        fprintf(stderr, "Error calling ADC's call() cleanup routine: %s\n", strerror(errno));
    }

    return 0;
}

void sigint_handler(int sig) {
    // Close SPI handle
    close(spi_fd);

    // Flush and close log file
    if (fsync(fd) < 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
    close(fd);

