        moisture_percentage = (adc_value_10bit / 1023.0) * 100;

        // Log data
        if (write(fd, &ts.tv_sec, sizeof(ts.tv_sec)) < 1) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(adc_fd);
            close(spi_fd);
            close(fd);
            return 1;
        }
        if (write(fd, &moisture_percentage, sizeof(moisture_percentage)) < 1) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(adc_fd);
            close(spi_fd);
            close(fd);
            return 1;
        }

        // Sleep for 1 second
        nanosleep(&ts, NULL);
    }

    // Cleanup
    close(adc_fd);
    close(spi_fd);
    close(fd);

    // Call ADC's call() cleanup routine
    if (ioctl(adc_fd, ADC_CALL, 0) < 0) {
        fprintf(stderr, "Error calling ADC's call() cleanup routine: %s\n", strerror(errno));
    }

    return 0;
}

void sigint_handler(int sig) {
    // Close SPI handle
    close(spi_fd);

    // Flush and close log file
    if (fsync(fd) < 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
    close(fd);

    // Call ADC's call() cleanup routine
    if (ioctl(adc_fd, ADC_CALL, 0) < 0) {
        fprintf(stderr, "Error calling ADC's call() cleanup routine: %s\n", strerror(errno));
    }

    // Exit
    exit(0);
}
