#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define SPI_MODE_0 0
#define SPI_SPEED_1MHZ 1000000
#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_CHANNEL 0

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI device
    int spi_fd = spiOpen(GPIO_CE0, GPIO_SCLK, GPIO_MOSI, GPIO_MISO, SPI_MODE_0, SPI_SPEED_1MHZ);
    if (spi_fd < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Open ADC device
    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        perror("open");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Map ADC memory
    void* adc_map = mmap(NULL, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, adc_fd, 0);
    if (adc_map == MAP_FAILED) {
        perror("mmap");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set ADC channel
    if (ioctl(adc_fd, ADC_SET_CHANNEL, GPIO_CHANNEL) < 0) {
        perror("ADC_SET_CHANNEL");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set ADC gain
    if (ioctl(adc_fd, ADC_SET_GAIN, 1) < 0) {
        perror("ADC_SET_GAIN");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE_0) < 0) {
        perror("SPI_SET_MODE");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_SET_SPEED, SPI_SPEED_1MHZ) < 0) {
        perror("SPI_SET_SPEED");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI clock polarity
    if (ioctl(spi_fd, SPI_SET_CLOCK_Polarity, 0) < 0) {
        perror("SPI_SET_CLOCK_Polarity");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI open
    if (ioctl(spi_fd, SPI_SET_OPEN, 1) < 0) {
        perror("SPI_SET_OPEN");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode
    if (gpioMode(GPIO_CE0, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO as output
    if (gpioWrite(GPIO_CE0, 1) < 0) {
        perror("gpioWrite");
        munmap(adc_map, 1024);
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = *(int*)adc_map;
        if (adc_value == 0 || adc_value == 1023) {
            printf("ADC value is stuck or wiring fault\n");
            break;
        }

        // Calculate timestamp
        time_t now = time(NULL);
        printf("%d %d %d\n", now, now, adc_value);

        // Delay
        sleep(5);
    }

    // Release resources
    munmap(adc_map, 1024);
    close(adc_fd);
    close(spi_fd);
    gpioWrite(GPIO_CE0, 0);
    gpioMode(GPIO_CE0, GPIO_MODE_INPUT);
    gpioTerminate();

    return 0;
}

