#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/spi/spidev.h>
#include <signal.h>
#include <unistd.h>

#define SPI_MODE_0 0
#define SPI_SPEED_1000000 1000000
#define SPI_BIT_PER_WORD 8
#define SPI_CE0 0
#define SPI_CS0 1
#define SPI_DEVICE "/dev/spidev0.0"

int main() {
    int fd;
    struct spi_ioc_transfer tr;
    struct spi_ioc_transfer tr2;
    int ret;
    int moisture;
    int i;

    // Initialize signal handlers
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Open the SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Configure the SPI device
    ret = ioctl(fd, SPI_IOC_SET_MODE, SPI_MODE_0);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, SPI_IOC_SET_SPEED, SPI_SPEED_1000000);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, SPI_IOC_SET_BIT_MODE, SPI_BIT_PER_WORD);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Create the transfer structure
    memset(&tr, 0, sizeof(tr));
    tr.tx { .buf = (unsigned char[]) { 0x00, 0x00, 0x00 }, .len = 3, .flags = SPI_CSB };
    tr2.tx { .buf = (unsigned char[]) { 0x00, 0x00, 0x00 }, .len = 3, .flags = SPI_CSB };

    // Main loop
    while (1) {
        // Read from the SPI device
        ret = ioctl(fd, SPI_IOC_READ, &tr);
        if (ret < 0) {
            perror("ioctl");
            close(fd);
            return 1;
        }

        // Extract the ADC value
        moisture = (tr.tx[0] & 0x3F) * 100 / 1023;

        // Clamp the value to the 0-100% range
        moisture = (moisture < 0) ? 0 : (moisture > 100) ? 100 : moisture;

        // Print the moisture level
        printf("%d%%\n", moisture);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    close(fd);
    return 0;
}

