#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CE 8
#define SPI_CS 9
#define SPI_DATA 10
#define NUM_SENSORS 4
#define CSV_FILE "environmental_data.csv"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI device
    int spi_fd = spiOpen(SPI_CE, SPI_CS, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    int csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("open");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Map SPI memory
    void *mem = mmap(NULL, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(csv_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Define SPI transfer function
    void (*spi_transfer)(void) = spiXfer;

    // Define SPI transfer callback
    void (*spi_callback)(void) = spiCallback;

    // Define SPI callback function
    void spiCallback(void) {
        // Read voltage from sensors
        unsigned char data[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            int result = spiTransfer(spi_fd, data + i, 1);
            if (result < 0) {
                perror("spiTransfer");
                return;
            }
        }

        // Calculate and log voltage values
        for (int i = 0; i < NUM_SENSORS; i++) {
            double voltage = (data[i] * 3.3 / 65535.0);
            fprintf(csv_fd, "%f,%d\n", time(NULL), voltage);
        }
    }

    // Set up SPI transfer
    spiTransfer = spiXfer;
    spiTransfer(spi_fd, NULL, NULL, spi_callback, spi_transfer);

    // Main loop
    while (1) {
        // Check for SIGINT or SIGTERM
        if (killpg(0, 0) == -1) {
            break;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    munmap(mem, 1024);
    close(csv_fd);
    close(spi_fd);
    gpioTerminate();

    return 0;
}

