#define I2C_ADDRESS 0x1D
#define I2C_SPEED 400000

// Maximum allowed SpO2 and heart rate values
#define MAX_SPO2 100
#define MAX_HR 100

// Log file name
#define LOG_FILE "health_log.txt"

// I2C handle
pigpio i2c;

// Function to initialize I2C
void init_i2c() {
    if (i2cInit(1, I2C_SPEED) != 0) {
        syslog(LOG_ERR, "I2C initialization failed");
        exit(1);
    }
}

// Function to read Part ID register
uint8_t read_part_id() {
    uint8_t data;
    if (i2cWrite(1, I2C_ADDRESS, 0x00, 1, &data) != 0) {
        syslog(LOG_ERR, "I2C write failed");
        exit(1);
    }
    return data;
}

// Function to read SpO2 and heart rate values
void read_values() {
    uint8_t data;
    if (i2cWrite(1, I2C_ADDRESS, 0x02, 1, &data) != 0) {
        syslog(LOG_ERR, "I2C write failed");
        exit(1);
    }
    uint8_t spo2 = (data >> 4) & 0x0F;
    uint8_t hr = data & 0x0F;
    if (spo2 < 0x03 || hr > 0xFF) {
        syslog(LOG_ERR, "Invalid SpO2 or heart rate value");
        exit(1);
    }
    if (spo2 < 95) {
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            syslog(LOG_ERR, "Failed to open log file");
            exit(1);
        }
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
        fprintf(log_file, "%s SpO2: %d, HR: %d\n", timestamp, spo2, hr);
        fclose(log_file);
    }
}

int main() {
    // Initialize I2C
    init_i2c();

    // Read Part ID register
    uint8_t part_id = read_part_id();
    if (part_id != 0x55) {
        syslog(LOG_ERR, "Part ID mismatch");
        exit(1);
    }

    // Main loop
    while (1) {
        read_values();
        usleep(1000000); // Wait 1 second
    }

    // Clean up
    i2cClose(1);
    return 0;
}

