#define SPI_CE0 18
#define SPI_MOSI 23
#define SPI_MISO 24
#define SPI_SCK 25
#define CSV_FILE "analog_log.csv"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetupSPI(0, SPI_MODE, SPI_SPEED, SPI_CE0, SPI_MOSI, SPI_MISO, SPI_SCK) < 0) {
        perror("gpioSetupSPI");
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    struct stat sb;
    if (stat(CSV_FILE, &sb) != 0) {
        if (mkdir(CSV_FILE, 0644) < 0) {
            perror("mkdir");
            gpioTerminate();
            return 1;
        }
    }
    if (fopen(CSV_FILE, "w") == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(stdout, "Timestamp,Channel,Voltage\n");
    fprintf(CSV_FILE, "Timestamp,Channel,Voltage\n");

    struct timeval start;
    gettimeofday(&start, NULL);
    while (1) {
        // Read from SPI
        unsigned char data[3];
        int ret = gpioReadSPI(0, data, 3);
        if (ret < 0) {
            if (ret == -2) {
                // Retry read
                sleep(0.1);
                ret = gpioReadSPI(0, data, 3);
                if (ret < 0) {
                    // Log error
                    fprintf(stderr, "SPI read error\n");
                    break;
                }
            } else {
                // Log error
                fprintf(stderr, "SPI read error: %d\n", ret);
                break;
            }
        }

        // Convert data to voltage
        float voltage[3];
        for (int i = 0; i < 3; i++) {
            voltage[i] = (data[i] * 3.3f) / 65535.0f;
        }

        // Log data
        struct tm* now = localtime(&start.tv_sec);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", now);
        fprintf(stdout, "%s,0,%f\n", timestamp, voltage[0]);
        fprintf(CSV_FILE, "%s,0,%f\n", timestamp, voltage[0]);
        fprintf(stdout, "%s,1,%f\n", timestamp, voltage[1]);
        fprintf(CSV_FILE, "%s,1,%f\n", timestamp, voltage[1]);
        fprintf(stdout, "%s,2,%f\n", timestamp, voltage[2]);
        fprintf(CSV_FILE, "%s,2,%f\n", timestamp, voltage[2]);

        // Sleep
        sleep(0.5);
    }

    // Close CSV file
    fclose(CSV_FILE);

    // Clean up
    gpioTerminate();
    return 0;
}

