int spi_mosi_pin = 10;
int spi_miso_pin = 11;
int gpio_buzzer_pin = 24;

int main() {
    // Initialize the GPIO library
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Initialize the SPI library
    if (gpio_init_spi(&spi_handle, spi_ce_pin, spi_sck_pin, spi_mosi_pin, spi_miso_pin, spi_mode, spi_clock_speed) < 0) {
        perror("gpio_init_spi");
        gpio_cleanup();
        return 1;
    }

    // Set the SPI mode and clock speed
    if (gpio_spi_set_mode(spi_handle, spi_mode) < 0) {
        perror("gpio_spi_set_mode");
        gpio_cleanup();
        return 1;
    }
    if (gpio_spi_set_clock(spi_handle, spi_clock_speed) < 0) {
        perror("gpio_spi_set_clock");
        gpio_cleanup();
        return 1;
    }

    // Set the GPIO pin as output for the buzzer
    if (gpio_mode(gpio_buzzer_pin, PI_OUTPUT) < 0) {
        perror("gpio_mode");
        gpio_cleanup();
        return 1;
    }

    // Set the initial state of the buzzer to low
    if (gpio_write(gpio_buzzer_pin, 0) < 0) {
        perror("gpio_write");
        gpio_cleanup();
        return 1;
    }

    // Define the ADC channel
    int adc_channel = 0;

    // Main loop
    while (1) {
        // Read the ADC value
        int adc_value = 0;
        if (gpio_spi_read(spi_handle, adc_channel, &adc_value) < 0) {
            perror("gpio_spi_read");
            gpio_cleanup();
            return 1;
        }

        // Check if the ADC value is below the threshold
        if (adc_value < threshold) {
            // Turn off the buzzer
            gpio_write(gpio_buzzer_pin, 0);
        } else {
            // Turn on the buzzer
            gpio_write(gpio_buzzer_pin, 1);
        }

        // Sleep for 500ms
        sleep(0.5);
    }

    // Clean up
    gpio_cleanup();
    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Close the SPI handle
    gpio_spi_close(spi_handle);

    // Reset the GPIO states to a safe condition
    gpio_write(gpio_buzzer_pin, 0);

    // Cleanup the GPIO library
    gpio_cleanup();

    // Exit the program
    exit(0);
}

// Register the signal handler
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
}

int main() {
    // Register the signal handler
    sigaction(SIGINT, &sigaction_handler, NULL);

    // Run the program
    return main();
}
