int pump_duration = DEFAULT_PUMP_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;

int spi_fd = -1;
int gpio_fd = -1;
int relay_fd = -1;

void init_spi() {
    int ret;
    struct spi_ioc_transfer tr;

    ret = pigpio_init();
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_init failed: %s", strerror(errno));
        exit(1);
    }

    ret = pigpio_spi_open(SPI_CE0, SPI_MODE_0, SPI_SPEED_0, &spi_fd);
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_spi_open failed: %s", strerror(errno));
        pigpio_cleanup();
        exit(1);
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx { .len = 1, .buf = &tr.buf, .flags = PI_MMAP | PI_MREMAP_F_DONOTMAP };
    ret = pigpio_spi_xfer(&tr);
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_spi_xfer failed: %s", strerror(errno));
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        exit(1);
    }
}

void cleanup_spi() {
    if (spi_fd != -1) {
        pigpio_spi_close(spi_fd);
        pigpio_spi_release(spi_fd);
        spi_fd = -1;
    }
    pigpio_cleanup();
}

