    int ret;

    ret = pigpio_init();
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_init failed: %s", strerror(errno));
        exit(1);
    }

    ret = pigpio_gpio_fsel(GPIO_PUMP, PI_INPUT);
