    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_gpio_fsel failed: %s", strerror(errno));
        pigpio_cleanup();
        exit(1);
    }

    ret = pigpio_gpio_mode(GPIO_RELAY, PI_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_gpio_mode failed: %s", strerror(errno));
        pigpio_cleanup();
        exit(1);
