    int ret;
    unsigned char buf[3];

    ret = pigpio_spi_xfer(&tr, buf, 3, 100);
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_spi_xfer failed: %s", strerror(errno));
        return;
    }

    int moisture = (buf[0] * 256 + buf[1]) / 16;
    syslog(LOG_INFO, "Moisture level: %d%%", moisture);

    if (moisture < threshold) {
        syslog(LOG_INFO, "Moisture level too low, activating pump");
        activate_pump();
    }
}

void activate_pump() {
    int ret;

    ret = pigpio_gpio_write(GPIO_RELAY, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_gpio_write failed: %s", strerror(errno));
        return;
    }

    sleep(pump_duration);
    ret = pigpio_gpio_write(GPIO_RELAY, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "pigpio_gpio_write failed: %s", strerror(errno));
        return;
    }
}

void sleep_and_read() {
    sleep(sleep_interval);
    read_moisture();
}

int main(int argc, char **argv) {
    int c;

    while ((c = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (c) {
        case 't':
            threshold = atoi(optarg);
            break;
        case 'd':
            pump_duration = atoi(optarg);
            break;
        case 's':
            sleep_interval = atoi(optarg);
            break;
        default:
            syslog(LOG_ERR, "Invalid option: %c", c);
            return 1;
        }
    }

    init_spi();
    init_gpio();

    while (1) {
        read_moisture();
        sleep_and_read();
    }

    cleanup_spi();
    cleanup_gpio();

    return 0;
}

