#define I2C_FILE "/dev/i2c-1"
#define I2C_ADDRESS 0x70
#define SAMPLING_INTERVAL 100

int main() {
    int fd, status;
    unsigned char dummy;
    unsigned char sample;
    struct i2c_msg msg;
    struct i2c_file *file;

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    // Open I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Check if I2C file descriptor is valid
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        exit(1);
    }

    while (1) {
        // Perform dummy read to discard previous conversion result
        msg.msg_name = (void *)I2C_FILE;
        msg.msg_iov = (struct iovec *)malloc(sizeof(struct iovec));
        msg.msg_iovlen = 1;
        msg.msg_iov[0].iov_base = &dummy;
        msg.msg_control = NULL;
        msg.msg_nbytes = 0;
        if (write(fd, &msg, sizeof(msg)) < 0) {
            perror("write");
            close(fd);
            exit(1);
        }

        // Read current 8-bit sample
        msg.msg_name = (void *)I2C_FILE;
        msg.msg_iov = (struct iovec *)malloc(sizeof(struct iovec));
        msg.msg_iovlen = 1;
        msg.msg_iov[0].iov_base = &sample;
        msg.msg_control = NULL;
        msg.msg_nbytes = 1;
        if (read(fd, &sample, 1) < 0) {
            perror("read");
            close(fd);
            exit(1);
        }

        // Print sample value
        printf("%u\n", sample);

        // Wait for sampling interval
        usleep(SAMPLING_INTERVAL * 1000);
    }

    // Clean up
    free(msg.msg_iov);
    close(fd);
    return 0;
}

