#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>

#define BUFFER_SIZE 100
#define SAMPLE_RATE 1
#define THRESHOLD 500
#define GPIO_PIN 27
#define I2C_ADDRESS 0x4A

// Structure to hold the circular buffer
typedef struct {
    float values[BUFFER_SIZE];
    int head;
    int tail;
} Buffer;

// Function to initialize the GPIO pin
void init_gpio(pigpio *gpio) {
    if (gpio->set_mode(GPIO_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", GPIO_PIN);
        exit(1);
    }
}

// Function to initialize the I2C handle
void init_i2c(pigpio *gpio) {
    if (gpio->i2c_open(I2C_BUS1, I2C_ADDRESS, NULL) != 0) {
        syslog(LOG_ERR, "Failed to open I2C bus 1 on address %d", I2C_ADDRESS);
        exit(1);
    }
}

// Function to read a single sample from the ADC
int read_adc(pigpio *gpio) {
    unsigned int value;
    if (gpio->i2c_read(I2C_BUS1, 0x00, &value, 1) != 0) {
        syslog(LOG_ERR, "Failed to read from ADC");
        return -1;
    }
    return value;
}

// Function to convert a voltage reading to magnetic field strength
float voltage_to_magnetic(float voltage) {
    return (voltage / 0.5) * 1000;
}

// Function to update the buffer
void update_buffer(Buffer *buffer) {
    if (buffer->tail == BUFFER_SIZE) {
        buffer->tail = 0;
    }
    buffer->values[buffer->tail] = voltage_to_magnetic(read_adc(NULL));
    buffer->tail++;
}

// Function to check the threshold
void check_threshold(Buffer *buffer) {
    float sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer->values[i];
    }
    float average = sum / BUFFER_SIZE;
    if (average > THRESHOLD) {
        gpio = pigpio_get();
        gpio->gpio_write(GPIO_PIN, PI_HIGH);
        syslog(LOG_INFO, "Threshold exceeded, GPIO %d set high", GPIO_PIN);
    }
}

// Function to handle SIGINT and SIGTERM
void sig_handler(int sig) {
    pigpio *gpio = pigpio_get();
    gpio->gpio_write(GPIO_PIN, PI_LOW);
    gpio->i2c_close(I2C_BUS1);
    gpio->close();
    syslog(LOG_INFO, "Received signal %d, shutting down", sig);
    exit(0);
}

int main() {
    pigpio *gpio = pigpio_get();
    if (gpio == NULL) {
        syslog(LOG_ERR, "Failed to get pigpio handle");
        exit(1);
    }

    // Initialize GPIO pin
    init_gpio(gpio);

    // Initialize I2C handle
    init_i2c(gpio);

    // Initialize buffer
    Buffer buffer;
    buffer.head = 0;
    buffer.tail = 0;

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        try {
            // Read a sample from the ADC
            int value = read_adc(gpio);

            // Check for out-of-range voltage
            if (value < 0 || value > 65535) {
                syslog(LOG_ERR, "Out-of-range voltage reading %d", value);
                continue;
            }

            // Update the buffer
            update_buffer(&buffer);

            // Check the threshold
            check_threshold(&buffer);
        } catch (const std::exception &e) {
            syslog(LOG_ERR, "Error: %s", e.what());
        }
    }

    return 0;
}

