#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define RELAY_PIN 18
#define RELAY_DURATION 10000
#define LOG_FILE "watering_events.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize SPI
    if (gpioSetupSPI(0, SPI_MODE, SPI_SPEED) < 0) {
        perror("gpioSetupSPI");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up relay pin as output
    if (gpioMode(RELAY_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set relay pin high to deactivate pump
    gpioWrite(RELAY_PIN, 0);

    // Main loop
    while (1) {
        // Read ADC value
        unsigned int adc_value = 0;
        if (gpioReadSPI(0, ADC_CHANNEL, &adc_value) < 0) {
            perror("gpioReadSPI");
            continue;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            printf("Invalid ADC value: %u\n", adc_value);
            continue;
        }

        // Check if value is below threshold
        if (adc_value < 300) {
            // Activate pump
            gpioWrite(RELAY_PIN, 1);
            printf("Watering event at %s\n", ctime(&time(NULL)));

            // Log event
            char log_message[256];
            sprintf(log_message, "%s %u\n", ctime(&time(NULL)), adc_value);
            write(log_fd, log_message, strlen(log_message));

            // Wait for RELAY_DURATION seconds
            sleep(RELAY_DURATION / 1000);

            // Deactivate pump
            gpioWrite(RELAY_PIN, 0);
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    gpioTerminate();
    close(log_fd);
    return 0;
}

