#define SPI_SPEED 1000000
#define SPI_CE0 17
#define SPI_MOSI 23
#define SPI_MISO 24
#define SPI_SCK 25
#define SPI_CS 0

int main() {
    int spi_fd;
    int ret;
    struct timespec ts;
    struct timespec last_ts;
    int i;
    int adc_value;
    int intensity;
    char error_message[256];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        return 1;
    }

    // Set up SPI
    if ((ret = gpioSetMode(SPI_CE0, GPIO_MODE_OUTPUT) < 0) || (ret = gpioSetLevel(SPI_CE0, 0) < 0)) {
        printf("Error setting SPI CE0\n");
        gpioTerminate();
        return 1;
    }

    if ((ret = gpioSetMode(SPI_MOSI, GPIO_MODE_OUTPUT) < 0) || (ret = gpioSetMode(SPI_MISO, GPIO_MODE_INPUT) < 0)) {
        printf("Error setting SPI MOSI and MISO\n");
        gpioTerminate();
        return 1;
    }

    if ((ret = gpioSetMode(SPI_SCK, GPIO_MODE_OUTPUT) < 0) || (ret = gpioSetLevel(SPI_SCK, 0) < 0)) {
        printf("Error setting SPI SCK\n");
        gpioTerminate();
        return 1;
    }

    if ((ret = gpioSetMode(SPI_CS, GPIO_MODE_OUTPUT) < 0) || (ret = gpioSetLevel(SPI_CS, 0) < 0)) {
        printf("Error setting SPI CS\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI device
    if ((spi_fd = spiOpen(SPI_CE0, SPI_MODE_0, SPI_SPEED, SPI_CS) < 0)) {
        printf("Error opening SPI device\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Check if it's time to read the sensor
        if (ts.tv_sec != last_ts.tv_sec) {
            last_ts = ts;

            // Set chip enable
            gpioSetLevel(SPI_CE0, 1);

            // Read ADC value
            if ((ret = spiTransfer(&adc_value, NULL, NULL, NULL, 1) < 0)) {
                printf("Error reading ADC value\n");
                gpioSetLevel(SPI_CE0, 0);
                continue;
            }

            // Map ADC value to intensity
            intensity = (adc_value / 1023) * 100;

            // Set chip disable
            gpioSetLevel(SPI_CE0, 0);

            // Print result
            printf("%ld %d %d\n", ts.tv_sec, adc_value, intensity);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close SPI device
    if (spiClose(spi_fd) < 0) {
        printf("Error closing SPI device\n");
    }

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

