#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define I2C_ADDRESS 0x49
#define ADC_CHANNEL 0
#define GPIO_PIN 17
#define LED_GPIO 17
#define LED_PIN GPIO_PIN
#define ADC_GAIN 4096
#define THRESHOLD 100.0

int main(int argc, char *argv[]) {
    int i2c_fd, adc_fd, gpio_fd;
    unsigned char adc_value;
    unsigned int gpio_value;
    unsigned int threshold;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Initialize GPIO
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Set up GPIO pin as output
    gpio_set_mode(LED_PIN, GPIO_MODE_OUTPUT);
    gpio_value = 0;
    gpio_write(LED_PIN, gpio_value);

    // Initialize I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADC
    if ((adc_fd = open("/dev/mem", O_RDWR | O_SYNC)) < 0) {
        perror("open");
        close(i2c_fd);
        return 1;
    }

    if (mmap(0, 0x100, PROT_READ | PROT_WRITE, MAP_SHARED, adc_fd, 0) == MAP_FAILED) {
        perror("mmap");
        close(adc_fd);
        close(i2c_fd);
        return 1;
    }

    // Set up ADC configuration
    unsigned int adc_config = 0;
    adc_config |= (1 << ADC_CHANNEL);
    adc_config |= (1 << ADC_GAIN);
    if (ioctl(adc_fd, ADC_SET_CONFIG, adc_config) < 0) {
        perror("ioctl");
        munmap((void *)-1, 0);
        close(adc_fd);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        munmap((void *)-1, 0);
        close(adc_fd);
        close(i2c_fd);
        return 1;
    }

    sa_int.sa_handler = sigint_handler;
    sa_int.sa_flags = SA_RESTART;
    sigemptyset(&sa_int.sa_mask);
    if (sigaction(SIGTERM, &sa_int, NULL) < 0) {
        perror("sigaction");
        munmap((void *)-1, 0);
        close(adc_fd);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read ADC value
        if (read(i2c_fd, &adc_value, 1) < 1) {
            perror("read");
            munmap((void *)-1, 0);
            close(adc_fd);
            close(i2c_fd);
            return 1;
        }

        // Calculate magnetic field strength
        unsigned int voltage = (adc_value * ADC_GAIN) / 1024;
        unsigned int gauss = (voltage * 1000) / 0.024;

        // Check if threshold is exceeded
        if (gauss > threshold) {
            gpio_value = 1;
            gpio_write(LED_PIN, gpio_value);
            sleep(1);
            gpio_value = 0;
            gpio_write(LED_PIN, gpio_value);
        }

        // Print magnetic field strength
        printf("%u\n", gauss);

        // Sleep for 100ms
        sleep(0.1);
    }

    // Clean up
    gpio_write(LED_PIN, 0);
    munmap((void *)-1, 0);
    close(adc_fd);
    close(i2c_fd);
    gpio_cleanup();
    return 0;
}

void sigint_handler(int sig) {
    gpio_write(LED_PIN, 0);
    munmap((void *)-1, 0);
    close(adc_fd);
    close(i2c_fd);
    exit(0);
}

