#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <libgpiod.h>
#include <libgpiod-mqtt.h>
#include <libgpiod-mqtt-callbacks.h>

#define SPI0_BASE 0
#define SPI0_MOSI 10
#define SPI0_MISO 9
#define SPI0_SCK 11
#define SPI0_CS 8
#define GPIO17 17
#define RELAY_PIN GPIO17
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_SUBSCRIBE_TOPIC "pump_control"
#define RELAY_TOPIC "pump"

int main(int argc, char **argv) {
    int spi_fd;
    int gpio_fd;
    int relay_state = RELAY_LOW;
    int moisture_level = 0;
    int hysteresis_threshold = 5;
    int hysteresis_threshold_high = 10;
    int mqtt_client_id = "soil_moisture_client";
    char mqtt_topic[] = MQTT_TOPIC;
    char mqtt_subscribe_topic[] = MQTT_SUBSCRIBE_TOPIC;
    char relay_topic[] = RELAY_TOPIC;
    struct gpiod_context *ctx;
    struct gpiod_mqtt_client *mqtt_client;
    struct gpiod_mqtt_callback *mqtt_callback;
    struct gpiod_mqtt_callback *mqtt_callback2;

    // Initialize logging
    openlog("soil_moisture_logger", LOG_PID, LOG_DAEMON);

    // Initialize GPIO
    gpio_init();
    gpio_set_mode(RELAY_PIN, GPIO_MODE_OUTPUT);
    gpio_set_level(RELAY_PIN, RELAY_LOW);

    // Initialize SPI
    spi_fd = spi_open(SPI0_BASE, SPI0_MOSI, SPI0_MISO, SPI0_SCK, SPI0_CS);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI interface");
        return 1;
    }

    // Initialize MQTT
    mqtt_client = gpiod_mqtt_client_new(MQTT_BROKER, MQTT_PORT, mqtt_client_id, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return 1;
    }

    mqtt_callback = gpiod_mqtt_callback_new(mqtt_client, mqtt_topic, mqtt_subscribe_topic, mqtt_topic, NULL);
    if (!mqtt_callback) {
        syslog(LOG_ERR, "Failed to create MQTT callback");
        gpiod_mqtt_client_free(mqtt_client);
        return 1;
    }

    mqtt_callback2 = gpiod_mqtt_callback_new(mqtt_client, mqtt_topic, mqtt_topic, NULL);
    if (!mqtt_callback2) {
        syslog(LOG_ERR, "Failed to create MQTT callback");
        gpiod_mqtt_callback_free(mqtt_callback);
        gpiod_mqtt_client_free(mqtt_client);
        return 1;
    }

    // Subscribe to MQTT topic
    gpiod_mqtt_client_subscribe(mqtt_client, mqtt_subscribe_topic, mqtt_callback2);

    // Initialize SPI transfer
    struct gpiod_transfer transfer;
    transfer.tx_desc = (void *) &moisture_level;
    transfer.rx_desc = (void *) &moisture_level;
    transfer.num_desc = 1;
    transfer.flags = GPIOD_TRANSFER_BLOCKING;
    transfer.callback = gpiod_spi_transfer_callback;
    transfer.user_data = spi_fd;

    // Start SPI transfer
    if (gpiod_spi_transfer(ctx, &transfer) < 0) {
        syslog(LOG_ERR, "Failed to start SPI transfer");
        gpiod_mqtt_callback_free(mqtt_callback2);
        gpiod_mqtt_client_free(mqtt_client);
        return 1;
    }

    // Main loop
    while (1) {
        // Read moisture level
        if (gpiod_spi_transfer(ctx, &transfer) < 0) {
            syslog(LOG_ERR, "Failed to read moisture level");
            break;
        }

        // Apply hysteresis control
        if (moisture_level < hysteresis_threshold) {
            if (relay_state == RELAY_LOW) {
                gpio_set_level(RELAY_PIN, RELAY_HIGH);
                relay_state = RELAY_HIGH;
            }
        } else if (moisture_level > hysteresis_threshold_high) {
            if (relay_state == RELAY_HIGH) {
                gpio_set_level(RELAY_PIN, RELAY_LOW);
                relay_state = RELAY_LOW;
            }
        }

        // Publish moisture level
        if (gpiod_mqtt_publish(mqtt_client, mqtt_topic, (char *) &moisture_level, 1) < 0) {
            syslog(LOG_ERR, "Failed to publish moisture level");
            break;
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    gpio_set_level(RELAY_PIN, RELAY_LOW);
    gpio_close(gpio_fd);
    spi_close(spi_fd);
    gpiod_mqtt_callback_free(mqtt_callback2);
    gpiod_mqtt_client_free(mqtt_client);
    gpiod_context_free(ctx);

    return 0;
}

static int gpiod_spi_transfer_callback(struct gpiod_transfer *transfer) {
    int ret = gpiod_spi_transfer(transfer->ctx, transfer);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read moisture level");
        return ret;
    }
    return 0;
}

static int gpiod_mqtt_publish(struct gpiod_mqtt_client *client, const char *topic, const void *data, size_t size) {
    int ret = gpiod_mqtt_publish(client, topic, data, size);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to publish moisture level");
        return ret;
    }
    return 0;
}

