#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define SPI_DEVICE 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CSV_FILE "sensor_data.csv"

// Define signal handlers
void sigint_handler(int sig) {
    gpio_close(SPI_DEVICE);
    pigpio_close();
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_close(SPI_DEVICE);
    pigpio_close();
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open SPI device
    if (gpio_export(SPI_DEVICE) < 0) {
        perror("gpio_export");
        return 1;
    }
    if (gpio_fsel(SPI_DEVICE, GPIO_FSEL_MODE1) < 0) {
        perror("gpio_fsel");
        return 1;
    }
    if (gpio_setmode(SPI_DEVICE, GPIO_MODE_SPI) < 0) {
        perror("gpio_setmode");
        return 1;
    }
    if (gpio_clock(SPI_DEVICE, SPI_CLOCK_PCLK0, SPI_CLOCK_PCLK0) < 0) {
        perror("gpio_clock");
        return 1;
    }
    if (gpio_setbits(SPI_DEVICE, GPIO_RCK, 1) < 0) {
        perror("gpio_setbits");
        return 1;
    }
    if (gpio_setbits(SPI_DEVICE, GPIO_MOSI, 1) < 0) {
        perror("gpio_setbits");
        return 1;
    }
    if (gpio_setbits(SPI_DEVICE, GPIO_MISO, 0) < 0) {
        perror("gpio_setbits");
        return 1;
    }
    if (gpio_setbits(SPI_DEVICE, GPIO_SCK, 0) < 0) {
        perror("gpio_setbits");
        return 1;
    }

    // Open SPI device
    int spi_fd = spi_open(SPI_DEVICE, SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        perror("spi_open");
        return 1;
    }

    // Open CSV file
    int csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("open");
        return 1;
    }

    // Define SPI transfer function
    void (*transfer_func)(void) = spi_xfer;
    void (*transfer_func2)(void) = spi_xfer;

    // Main loop
    while (1) {
        // Read SPI data
        int data[3];
        if (spi_xfer(SPI_DEVICE, data, 3, 1000) < 0) {
            perror("spi_xfer");
            return 1;
        }

        // Convert 10-bit values to voltages
        float voltage[3];
        for (int i = 0; i < 3; i++) {
            voltage[i] = (data[i] * 3.3 / 1024.0);
        }

        // Append timestamped line to CSV file
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(csv_fd, "%s,%f,%f,%f\n", timestamp, voltage[0], voltage[1], voltage[2]);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close SPI device and CSV file
    close(spi_fd);
    close(csv_fd);

    // Release SPI device
    gpio_fsel(SPI_DEVICE, GPIO_FSEL_MODE0);
    gpio_unexport(SPI_DEVICE);

    // Shutdown pigpio
    pigpio_close();

    return 0;
}

