#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define MAX_LOG_LINE 256
#define MAX_LOG_FILE "tamper_log.csv"
#define MAX_ADC_READS 10
#define MAX_I2C_READS 10

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI0
    int spi_fd = spiOpen(0, 0, 0);
    if (spi_fd < 0) {
        perror("spiOpen");
        return 1;
    }

    // Open I2C
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Open CSV file
    int csv_fd = open(MAX_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (csv_fd < 0) {
        perror("open");
        return 1;
    }

    // Set up SPI
    spiSetClockDivider(spi_fd, 1000000);
    spiSetMode(spi_fd, SPI_MODE0);

    // Set up I2C
    if (ioctl(i2c_fd, I2C_SLAVE, 0x4A) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set up BH1750
    if (ioctl(i2c_fd, I2C_SLAVE, 0x39) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set up MAX9814
    if (gpioMode(17, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        return 1;
    }
    if (gpioWrite(17, 0) < 0) {
        perror("gpioWrite");
        return 1;
    }

    // Set up MCP3008
    if (gpioMode(23, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        return 1;
    }

    // Set up timer
    struct itimerval it;
    it.it_value.tv_sec = 5;
    it.it_value.tv_usec = 0;
    it.it_interval.tv_sec = 5;
    it.it_interval.tv_usec = 0;
    if (setitimer(ITIMER_REAL, &it, NULL) < 0) {
        perror("setitimer");
        return 1;
    }

    while (1) {
        // Read MCP3008
        int adc_value = 0;
        if (spiXfer(spi_fd, NULL, &adc_value, NULL, 1) < 0) {
            perror("spiXfer");
            printf("ADC read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }

        // Read BH1750
        uint16_t bh1750_value;
        if (ioctl(i2c_fd, I2C_SLAVE, 0x39) < 0) {
            perror("ioctl");
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, 0x4A) < 0) {
            perror("ioctl");
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, 0x39) < 0) {
            perror("ioctl");
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }
        bh1750_value = (bh1750_value >> 8) | (bh1750_value << 8);
        if (bh1750_value & 0x8000) {
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }

        // Convert BH1750 value to lux
        uint16_t light_level = (bh1750_value * 1000) / 1.2;

        // Convert ADC value to decibels
        float sound_level_db = 20 * log10(adc_value / 65535.0);

        // Log data
        char log_line[MAX_LOG_LINE];
        sprintf(log_line, "%s,%f,%f,%d\n", ctime(&time(NULL)), sound_level_db, light_level, errno);
        if (write(csv_fd, log_line, strlen(log_line)) < 0) {
            perror("write");
            printf("Error writing to CSV file\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }

        // Release I2C
        if (ioctl(i2c_fd, I2C_SLAVE, 0x39) < 0) {
            perror("ioctl");
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, 0x4A) < 0) {
            perror("ioctl");
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }
    }

    // Release SPI
    if (spiClose(spi_fd) < 0) {
        perror("spiClose");
    }

    // Release I2C
    if (close(i2c_fd) < 0) {
        perror("close");
    }

    // Close CSV file
    if (close(csv_fd) < 0) {
        perror("close");
    }

    // Clean up GPIO
    if (gpioCleanUp() < 0) {
        perror("gpioCleanUp");
    }

    return 0;
}

