            sleep(1);
            continue;
        }
        bh1750_value = (bh1750_value >> 8) | (bh1750_value << 8);
        if (bh1750_value & 0x8000) {
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }

        // Convert BH1750 value to lux
        uint16_t light_level = (bh1750_value * 1000) / 1.2;

        // Convert ADC value to decibels
        float sound_level_db = 20 * log10(adc_value / 65535.0);

        // Log data
        char log_line[MAX_LOG_LINE];
        sprintf(log_line, "%s,%f,%f,%d\n", ctime(&time(NULL)), sound_level_db, light_level, errno);
        if (write(csv_fd, log_line, strlen(log_line)) < 0) {
            perror("write");
            printf("Error writing to CSV file\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }

        // Release I2C
        if (ioctl(i2c_fd, I2C_SLAVE, 0x39) < 0) {
            perror("ioctl");
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, 0x4A) < 0) {
            perror("ioctl");
            printf("I2C read failed\n");
            printf("Error code: %d\n", errno);
            printf("Timestamp: %s\n", ctime(&time(NULL)));
            printf("Sound level: -1\n");
            printf("Light level: -1\n");
            printf("Error code: -1\n");
            fflush(stdout);
            sleep(1);
            continue;
        }
    }

    // Release SPI
    if (spiClose(spi_fd) < 0) {
        perror("spiClose");
    }

    // Release I2C
    if (close(i2c_fd) < 0) {
        perror("close");
    }

    // Close CSV file
    if (close(csv_fd) < 0) {
        perror("close");
    }

    // Clean up GPIO
    if (gpioCleanUp() < 0) {
        perror("gpioCleanUp");
    }

    return 0;
}
```

This code continuously reads the sound level from the MAX9814 microphone amplifier and the ambient light level from the BH1750 sensor, and logs the data to a CSV file named `tamper_log.csv`. The data is logged every 5 seconds, and any I2C communication errors or ADC read failures are captured as error codes alongside the sensor values. The program releases the I2C file descriptor, the SPI file descriptor, and closes the CSV file cleanly when receiving a SIGINT or SIGTERM signal.

