#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/resource.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RELAY_PIN 17
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define THRESHOLD 30
#define READ_INTERVAL 60

int main(int argc, char *argv[]) {
    int fd;
    int relay_state = RELAY_LOW;
    struct timeval last_read;
    struct timeval timeout;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up relay pin as output
    if (gpioMode(17, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Set relay to low
    if (gpioWrite(17, RELAY_LOW) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if ((fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode
    if (spiSetMode(SPI_CHANNEL, SPI_MODE_8BIT) < 0) {
        perror("spiSetMode");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI clock polarity and phase
    if (spiSetClockPolarity(SPI_CHANNEL, SPI_POLARITY_HIGH) < 0) {
        perror("spiSetClockPolarity");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (spiSetClockPhase(SPI_CHANNEL, SPI_PHASE_EDGE) < 0) {
        perror("spiSetClockPhase");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI data direction
    if (spiSetDataDirection(SPI_CHANNEL, SPI_DATA_8BIT) < 0) {
        perror("spiSetDataDirection");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI transfer timeout
    timeout.tv_sec = READ_INTERVAL;
    timeout.tv_usec = 0;
    if (select(SPI_CHANNEL, NULL, NULL, NULL, &timeout) < 0) {
        perror("select");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGPIPE, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }
    sa_int.sa_handler = sigintHandler;
    sa_int.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa_int, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }
    sa_term.sa_handler = sigtermHandler;
    sa_term.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa_term, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        struct timeval now;
        struct timeval diff;
        struct timespec sleep_time;
        int ret;

        // Get current time
        gettimeofday(&now, NULL);

        // Calculate time since last read
        diff.tv_sec = now.tv_sec - last_read.tv_sec;
        diff.tv_usec = now.tv_usec - last_read.tv_usec;
        if (diff.tv_sec < 0) {
            diff.tv_sec += 1000000;
            diff.tv_usec -= 1000000;
        }
        if (diff.tv_usec < 0) {
            diff.tv_sec--;
            diff.tv_usec += 1000000;
        }

        // Check if time since last read is greater than or equal to read interval
        if (diff.tv_sec >= READ_INTERVAL) {
            // Reset last read time
            last_read = now;

            // Read from SPI
            ret = spiXfer(SPI_CHANNEL, NULL, NULL, 1, 0);
            if (ret < 0) {
                // Retry up to three times
                for (int i = 0; i < 3; i++) {
                    ret = spiXfer(SPI_CHANNEL, NULL, NULL, 1, 0);
                    if (ret >= 0) {
                        break;
                    }
                }
                if (ret < 0) {
                    perror("spiXfer");
                    close(fd);
                    gpioTerminate();
                    return 1;
                }
            }

            // Check if SPI transfer was successful
            if (ret < 0) {
                perror("spiXfer");
                close(fd);
                gpioTerminate();
                return 1;
            }

            // Read data from SPI
            unsigned char data[3];
            ret = spiXfer(SPI_CHANNEL, data, NULL, 3, 0);
            if (ret < 0) {
                perror("spiXfer");
                close(fd);
                gpioTerminate();
                return 1;
            }

            // Check if data is valid
            if (data[0] < 0 || data[0] > 255) {
                perror("Invalid data");
                close(fd);
                gpioTerminate();
                return 1;
            }

            // Calculate moisture level
            int moisture_level = (data[0] * 100) / 1023;

            // Check if moisture level is below threshold
            if (moisture_level < THRESHOLD) {
                // Turn on relay
                relay_state = RELAY_HIGH;
                gpioWrite(17, RELAY_HIGH);
            } else {
                // Turn off relay
                gpioWrite(17, RELAY_LOW);
            }
        }

        // Sleep until next read
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000;
        nanosleep(&sleep_time, NULL);
    }

    // Turn off relay
    gpioWrite(17, RELAY_LOW);

    // Close SPI
    if (spiClose(SPI_CHANNEL) < 0) {
        perror("spiClose");
        return 1;
    }

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

void sigintHandler(int sig) {
    // Turn off relay
    gpioWrite(17, RELAY_LOW);
    // Close SPI
    if (spiClose(SPI_CHANNEL) < 0) {
        perror("spiClose");
    }
    // Terminate GPIO
    gpioTerminate();
    exit(0);
}

void sigtermHandler(int sig) {
    // Turn off relay
    gpioWrite(17, RELAY_LOW);
    // Close SPI
    if (spiClose(SPI_CHANNEL) < 0) {
        perror("spiClose");
    }
    // Terminate GPIO
    gpioTerminate();
    exit(0);
}

