#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 18
#define MCP3008_CHANNEL 0
#define CO2_THRESHOLD 700
#define LOG_FILE "air_quality.log"

// Function to read MCP3008 ADC value
int read_mcp3008(int fd) {
    unsigned char data[3];
    int ret = ioctl(fd, 0x04, data);
    if (ret < 0) {
        return ret;
    }
    return (data[MCP3008_CHANNEL] & 0x3F) * 1000 / 3;
}

// Function to convert ADC value to CO2 concentration
float convert_adc_to_co2(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0; // Invalid value
    }
    return (adc_value / 3.0) * 0.21; // Assuming 0.21 ppm/ADC value
}

// Function to log data to file
void log_data(float co2, int fan_state) {
    time_t now = time(NULL);
    struct tm* ltm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(log_file, "%s,%f,%d\n", timestamp, co2, fan_state);
    fclose(log_file);
}

// Function to activate/deactivate fan
void activate_fan(int fan_state) {
    if (fan_state) {
        printf("Activating fan...\n");
        gpio_set_high(SPI_CS);
    } else {
        printf("Deactivating fan...\n");
        gpio_set_low(SPI_CS);
    }
}

