#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define GPIO_PIN 8
#define GPIO_VALVE 17
#define LOG_FILE "irrigation.log"

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Set up the SPI interface
    if (gpioSetMode(GPIO_PIN, SPI_MODE) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        gpioTerminate();
        return 1;
    }
    if (gpioClock(0, SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to set SPI clock");
        gpioTerminate();
        return 1;
    }

    // Open the SPI device
    if (gpioOpen(0, GPIO_PIN, SPI_MODE) < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read three successive samples from the ADC
        uint16_t sample1, sample2, sample3;
        if (gpioRead(0, &sample1) < 0 || gpioRead(0, &sample2) < 0 || gpioRead(0, &sample3) < 0) {
            syslog(LOG_ERR, "Failed to read ADC sample");
            continue;
        }

        // Compute the average of the three raw ADC values
        uint16_t average = (sample1 + sample2 + sample3) / 3;

        // Set the position of the solenoid valve
        uint8_t duty_cycle = (average / 1024) * 100;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;
        if (gpioWrite(GPIO_VALVE, duty_cycle) < 0) {
            syslog(LOG_ERR, "Failed to set solenoid valve position");
            continue;
        }

        // Log the data
        fprintf(log_file, "%d %d %d %d %d\n", (int)time(NULL), sample1, sample2, sample3, duty_cycle);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpioClose(0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    // Set the solenoid valve to 0
    gpioWrite(GPIO_VALVE, 0);
    // Close the SPI interface
    gpioClose(0);
    // Close the log file
    fclose(log_file);
    // Terminate the driver library
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    // Set the solenoid valve to 0
    gpioWrite(GPIO_VALVE, 0);
    // Close the SPI interface
    gpioClose(0);
    // Close the log file
    fclose(log_file);
    // Terminate the driver library
    gpioTerminate();
    exit(0);
}

