#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_CH 0
#define SPI_RETRIES 5
#define SPI_BACKOFF 100
#define MAX_READ_ATTEMPTS 5

int main(int argc, char **argv) {
    int spi_fd;
    int retry_count = 0;
    int retry_delay = 1;
    struct timespec delay;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec sleep_time;
    struct stat sb;
    char filename[] = "soil_data.txt";
    char buffer[10];
    int adc_value;
    int moisture_percentage;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI file
    if ((spi_fd = spiOpen(SPI_CS, SPI_MODE, SPI_SPEED)) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Create log file
    if (mkdir(filename, 0777) == -1) {
        perror("mkdir");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI command bytes
    uint8_t command[2] = {0x00, 0x01};

    // Set up SPI channel
    if (spiSelect(SPI_CH, spi_fd) < 0) {
        perror("spiSelect");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI mode and channel
    if (spiXfer(command, NULL, NULL, 2, spi_fd) < 0) {
        perror("spiXfer");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI speed
    if (spiSetClock(spi_fd, SPI_SPEED) < 0) {
        perror("spiSetClock");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI mode
    if (spiSetMode(spi_fd, SPI_MODE) < 0) {
        perror("spiSetMode");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI clock polarity and phase
    if (spiSetClockPolarity(spi_fd, SPI_POLARITY_HIGH) < 0) {
        perror("spiSetClockPolarity");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (spiSetClockPhase(spi_fd, SPI_PHASE_EDGE) < 0) {
        perror("spiSetClockPhase");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI CS pin as output
    if (gpioMode(SPI_CS, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI CS pin as high
    if (gpioWrite(SPI_CS, 1) < 0) {
        perror("gpioWrite");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigHandler);
    signal(SIGTERM, sigHandler);

    // Main loop
    while (1) {
        // Record start time
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Read ADC value
        for (int i = 0; i < MAX_READ_ATTEMPTS; i++) {
            if (spiXfer(NULL, NULL, NULL, 1, spi_fd) < 0) {
                if (retry_count < SPI_RETRIES) {
                    retry_count++;
                    sleep(&delay);
                    delay.tv_sec = retry_delay;
                    delay.tv_nsec = 0;
                    nanosleep(&delay, NULL);
                } else {
                    moisture_percentage = -1;
                    break;
                }
            } else {
                break;
            }
        }

        if (retry_count >= SPI_RETRIES) {
            moisture_percentage = -1;
            continue;
        }

        // Read ADC value
        if (spiXfer(NULL, buffer, 1, spi_fd) < 0) {
            moisture_percentage = -1;
            continue;
        }

        // Convert ADC value to moisture percentage
        adc_value = (int)buffer[0];
        moisture_percentage = (adc_value * 100) / 1023;

        // Log reading
        if (moisture_percentage >= 0) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            FILE *log_file = fopen(filename, "a");
            if (log_file == NULL) {
                perror("fopen");
                moisture_percentage = -1;
                continue;
            }
            fprintf(log_file, "%s %d\n", timestamp, moisture_percentage);
            fclose(log_file);
        }

        // Set SPI CS pin as low
        if (gpioWrite(SPI_CS, 0) < 0) {
            perror("gpioWrite");
            moisture_percentage = -1;
            continue;
        }

        // Sleep for 5 seconds
        clock_gettime(CLOCK_REALTIME, &end_time);
        sleep_time.tv_sec = 5;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpioWrite(SPI_CS, 1);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

void sigHandler(int sig) {
    gpioWrite(SPI_CS, 1);
    gpioTerminate();
    exit(0);
}

