#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/mount.h>
#include <sys/statvfs.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define RELAY_PIN 18
#define LOG_FILE "air_quality.log"

// Function to initialize the SPI interface
int init_spi(void) {
    int fd;
    struct spi_iodev spi;
    struct spi_device *spi_dev;

    // Initialize the SPI interface
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    // Create the SPI device
    spi_dev = spi_create_device(&spi, SPI_MODE, SPI_SPEED, SPI_CHANNEL);
    if (spi_dev == NULL) {
        perror("spi_create_device");
        gpioTerminate();
        return -1;
    }

    // Open the SPI file descriptor
    fd = spi_open(spi_dev);
    if (fd < 0) {
        perror("spi_open");
        spi_destroy_device(spi_dev);
        gpioTerminate();
        return -1;
    }

    return fd;
}

// Function to read the ADC value from the MCP3008
int read_adc(int fd) {
    unsigned int adc_value;
    int ret;

    // Read the ADC value
    ret = spi_xfer(fd, NULL, &adc_value, 1, 1000);
    if (ret < 0) {
        perror("spi_xfer");
        return -1;
    }

    return adc_value;
}

// Function to calculate the AQI value
int calculate_aqi(int adc_value) {
    int aqi = 0;

    // Map the ADC value to the AQI value
    if (adc_value < 350) {
        aqi = (adc_value * 100) / 1024;
    } else if (adc_value < 700) {
        aqi = (adc_value - 350) * 50 / 350;
    } else if (adc_value < 1050) {
        aqi = 100 + ((adc_value - 700) * 50 / 350);
    } else {
        aqi = 500;
    }

    return aqi;
}

// Function to log the timestamp and AQI to the log file
void log_aqi(int aqi) {
    time_t now;
    struct tm *timeinfo;

    // Get the current timestamp
    time(&now);
    timeinfo = localtime(&now);

    // Log the timestamp and AQI to the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %d\n", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, aqi);
    fclose(log_file);
}

// Function to activate the ventilation fan
void activate_fan(void) {
    // Activate the ventilation fan
    gpioWrite(RELAY_PIN, 1);
}

// Function to deactivate the ventilation fan
void deactivate_fan(void) {
    // Deactivate the ventilation fan
    gpioWrite(RELAY_PIN, 0);
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    // Deactivate the ventilation fan
    deactivate_fan();

    // Close the SPI interface
    close(init_spi());

    // Close the log file
    remove(LOG_FILE);

    // Terminate the driver library
    exit(0);
}

// Function to handle the SIGTERM signal
void sigterm_handler(int sig) {
    // Deactivate the ventilation fan
    deactivate_fan();

    // Close the SPI interface
    close(init_spi());

    // Close the log file
    remove(LOG_FILE);

    // Terminate the driver library
    exit(0);
}

int main() {
    int fd;
    int aqi;
    int retry = 0;

    // Initialize the SPI interface
    fd = init_spi();
    if (fd < 0) {
        perror("init_spi");
        return -1;
    }

    // Initialize the fan
    deactivate_fan();

    // Loop indefinitely
    while (1) {
        // Read the ADC value
        aqi = read_adc(fd);
        if (aqi < 0) {
            retry++;
            if (retry < 3) {
                // Retry the SPI read
                sleep(1);
                aqi = read_adc(fd);
                if (aqi < 0) {
                    retry++;
                    if (retry < 3) {
                        // Re-initialize the SPI interface
                        fd = init_spi();
                        if (fd < 0) {
                            perror("init_spi");
                            return -1;
                        }
                        retry = 0;
                    } else {
                        // Log the error and exit
                        log_aqi(-1);
                        return -1;
                    }
                }
            } else {
                // Log the error and exit
                log_aqi(-1);
                return -1;
            }
        }

        // Calculate the AQI value
        aqi = calculate_aqi(aqi);

        // Log the timestamp and AQI to the log file
        log_aqi(aqi);

        // Activate the ventilation fan if the AQI exceeds 100
        if (aqi > 100) {
            activate_fan();
        } else {
            deactivate_fan();
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Handle SIGINT and SIGTERM signals
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}

