                    if (retry < 3) {
                        // Re-initialize the SPI interface
                        fd = init_spi();
                        if (fd < 0) {
                            perror("init_spi");
                            return -1;
                        }
                        retry = 0;
                    } else {
                        // Log the error and exit
                        log_aqi(-1);
                        return -1;
                    }
                }
            } else {
                // Log the error and exit
                log_aqi(-1);
                return -1;
            }
        }

        // Calculate the AQI value
        aqi = calculate_aqi(aqi);

        // Log the timestamp and AQI to the log file
        log_aqi(aqi);

        // Activate the ventilation fan if the AQI exceeds 100
        if (aqi > 100) {
            activate_fan();
        } else {
            deactivate_fan();
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Handle SIGINT and SIGTERM signals
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}
```

This code initializes the SPI interface, reads the ADC value from the MCP3008, calculates the AQI value, logs the timestamp and AQI to the log file, activates the ventilation fan if the AQI exceeds 100, and deactivates the fan otherwise. It also handles errors and retries the SPI read up to three times if the read fails. The program also handles SIGINT and SIGTERM signals to perform a graceful shutdown.

