#define GPIO_MISO 9
#define GPIO_SCLK 11
#define GPIO_CE0 8
#define GPIO_M1_EN 18
#define GPIO_M2_EN 24
#define GPIO_M1_DIR 23
#define GPIO_M2_DIR 25
#define GPIO_M1_FWD 26
#define GPIO_M2_FWD 27
#define GPIO_M1_BWD 28
