#define GPIO_M1_DIR PWM 32
#define GPIO_M2_DIR PWM 33
#define GPIO_M1_FWD PWM 34
#define GPIO_M2_FWD PWM 35
#define GPIO_M1_BWD PWM 36
#define GPIO_M2_BWD PWM 37

// Define structures
typedef struct {
    int fd;
    void* mmap_base;
    size_t size;
} spi_file;

// Define functions
void init_spi(pigpio* gpio, int channel, int speed, int mosi, int miso, int sclk, int ce0) {
    gpio->spi_open(channel, mosi, miso, sclk, ce0, SPI_MODE);
    gpio->spi_set_speed(channel, speed);
}

void cleanup_spi(pigpio* gpio, spi_file* spi) {
    gpio->spi_close(spi->fd);
    munmap(spi->mmap_base, spi->size);
    close(spi->fd);
}

void init_pwm(pigpio* gpio, int pin, int freq, int duty_cycle) {
    gpio-> pwm_set_mode(pin, PWM_MODE_DUTYCYCLE);
    gpio-> pwm_set_frequency(pin, freq);
    gpio-> pwm_set_duty_cycle(pin, duty_cycle);
}

void cleanup_pwm(pigpio* gpio, int pin) {
    gpio-> pwm_close(pin);
}

void init_gpio(pigpio* gpio, int pin, int mode) {
    gpio-> gpio_mode(pin, mode);
}

void cleanup_gpio(pigpio* gpio, int pin) {
    gpio-> gpio_close(pin);
}

void handle_sigint(int sig) {
    cleanup_spi(gpio, spi);
    cleanup_pwm(gpio, GPIO_M1_PWM);
    cleanup_pwm(gpio, GPIO_M2_PWM);
    cleanup_pwm(gpio, GPIO_M1_DIR);
    cleanup_pwm(gpio, GPIO_M2_DIR);
    cleanup_pwm(gpio, GPIO_M1_FWD);
    cleanup_pwm(gpio, GPIO_M2_FWD);
    cleanup_pwm(gpio, GPIO_M1_BWD);
    cleanup_pwm(gpio, GPIO_M2_BWD);
    exit(0);
}

void handle_sigterm(int sig) {
    cleanup_spi(gpio, spi);
    cleanup_pwm(gpio, GPIO_M1_PWM);
    cleanup_pwm(gpio, GPIO_M2_PWM);
    cleanup_pwm(gpio, GPIO_M1_DIR);
    cleanup_pwm(gpio, GPIO_M2_DIR);
    cleanup_pwm(gpio, GPIO_M1_FWD);
    cleanup_pwm(gpio, GPIO_M2_FWD);
    cleanup_pwm(gpio, GPIO_M1_BWD);
    cleanup_pwm(gpio, GPIO_M2_BWD);
    exit(0);
}

int main() {
    pigpio* gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    spi_file spi;
    spi.fd = gpio->spi_open(SPI_CHANNEL, GPIO_MOSI, GPIO_MISO, GPIO_SCLK, GPIO_CE0, SPI_MODE);
    if (spi.fd == -1) {
        printf("Failed to open SPI device\n");
        return 1;
    }

    spi.size = gpio->spi_get_size(SPI_CHANNEL);
    spi.mmap_base = mmap(NULL, spi.size, PROT_READ | PROT_WRITE, MAP_SHARED, spi.fd, 0);
    if (spi.mmap_base == MAP_FAILED) {
        printf("Failed to map SPI device\n");
        return 1;
    }

    init_spi(gpio, SPI_CHANNEL, SPI_SPEED, GPIO_MOSI, GPIO_MISO, GPIO_SCLK, GPIO_CE0);

    int motor1_speed = 0;
    int motor2_speed = 0;
    int motor1_direction = 0;
    int motor2_direction = 0;

    while (1) {
        // Read potentiometer values
        int pot1_value = gpio->spi_read(SPI_CHANNEL, 0);
        int pot2_value = gpio->spi_read(SPI_CHANNEL, 1);

        // Map potentiometer values to speed values
        motor1_speed = (pot1_value * 100) / 1023;
        motor2_speed = (pot2_value * 100) / 1023;

        // Set motor speeds
        init_pwm(gpio, GPIO_M1_PWM, 1000, motor1_speed);
        init_pwm(gpio, GPIO_M2_PWM, 1000, motor2_speed);

        // Set motor directions
        init_gpio(gpio, GPIO_M1_DIR, PWM_MODE_HIGH);
        init_gpio(gpio, GPIO_M2_DIR, PWM_MODE_HIGH);

        // Accelerate motors
        for (int i = 0; i < 100; i++) {
            init_pwm(gpio, GPIO_M1_FWD, 1000, motor1_speed);
            init_pwm(gpio, GPIO_M2_FWD, 1000, motor2_speed);
            usleep(10);
        }

        // Hold constant speed phase
        init_pwm(gpio, GPIO_M1_PWM, 1000, motor1_speed);
        init_pwm(gpio, GPIO_M2_PWM, 1000, motor2_speed);
        usleep(2000000);

        // Decelerate motors
        for (int i = 0; i < 100; i++) {
            init_pwm(gpio, GPIO_M1_BWD, 1000, motor1_speed);
            init_pwm(gpio, GPIO_M2_BWD, 1000, motor2_speed);
            usleep(10);
        }

        // Pause for 5 seconds
        usleep(5000000);

        // Reverse motor directions
        init_gpio(gpio, GPIO_M1_DIR, PWM_MODE_LOW);
        init_gpio(gpio, GPIO_M2_DIR, PWM_MODE_LOW);

        // Reverse motor speeds
        motor1_direction = !motor1_direction;
        motor2_direction = !motor2_direction;

        if (motor1_direction) {
            init_pwm(gpio, GPIO_M1_FWD, 1000, motor1_speed);
            init_pwm(gpio, GPIO_M2_FWD, 1000, motor2_speed);
        } else {
            init_pwm(gpio, GPIO_M1_BWD, 1000, motor1_speed);
            init_pwm(gpio, GPIO_M2_BWD, 1000, motor2_speed);
        }

        // Delay for a short time
        usleep(100000);

        // Repeat cycle
    }

    cleanup_spi(gpio, spi);
    cleanup_pwm(gpio, GPIO_M1_PWM);
    cleanup_pwm(gpio, GPIO_M2_PWM);
    cleanup_pwm(gpio, GPIO_M1_DIR);
    cleanup_pwm(gpio, GPIO_M2_DIR);
    cleanup_pwm(gpio, GPIO_M1_FWD);
    cleanup_pwm(gpio, GPIO_M2_FWD);
    cleanup_pwm(gpio, GPIO_M1_BWD);
    cleanup_pwm(gpio, GPIO_M2_BWD);
    pigpio_close(gpio);
    return 0;
}

