// Function to initialize the SPI driver
int init_spi() {
    int ret = pigpio_init();
    if (ret < 0) {
        printf("Error initializing pigpio: %d\n", ret);
        return ret;
    }

    // Set up SPI mode
    ret = pigpio_spi_set_mode(SPI_CS, PI_SPI_MODE_MASTER);
    if (ret < 0) {
        printf("Error setting SPI mode: %d\n", ret);
        pigpio_cleanup();
        return ret;
    }

    // Set up SPI clock
    ret = pigpio_spi_set_clock(SPI_SCLK, 1000000);
    if (ret < 0) {
        printf("Error setting SPI clock: %d\n", ret);
        pigpio_cleanup();
        return ret;
    }

    // Set up SPI data
    ret = pigpio_spi_set_mode(SPI_MOSI, PI_SPI_MODE_MASTER);
    if (ret < 0) {
        printf("Error setting SPI data: %d\n", ret);
        pigpio_cleanup();
        return ret;
    }

    ret = pigpio_spi_set_mode(SPI_MISO, PI_SPI_MODE_MASTER);
