    ret = init_spi();
    if (ret < 0) {
        printf("Error initializing SPI driver: %d\n", ret);
        pigpio_cleanup();
        return ret;
    }

    // Create a signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Calibrate the ambient noise level
    calibrate_noise();

    while (1) {
        // Check if the sound level exceeds the threshold
        if (check_sound_level()) {
            // Turn on the LED
            pigpio_write(LED_PIN_NUMBER, 1);
        } else {
            // Turn off the LED
