#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <sys/time.h>

#define GPIO_CE0 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BIT_PER_WORD 8
#define SPI_CLOCK 1000000
#define GPIO_FILE "audio_log.txt"

int main() {
    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Configure GPIO
    gpioSetMode(GPIO_CE0, PI_INPUT);
    gpioSetPullUpDnMode(GPIO_CE0, PI_PUD_UP);
    gpioSetMode(GPIO_MOSI, PI_INPUT);
    gpioSetMode(GPIO_MISO, PI_INPUT);
    gpioSetMode(GPIO_SCLK, PI_INPUT);
    gpioSetDirection(GPIO_CE0, PI_OUTPUT);
    gpioWrite(GPIO_CE0, 0);

    // Configure SPI
    int spidev = open(SPI_DEVICE, O_RDWR | O_NONBLOCK);
    if (spidev < 0) {
        perror("open");
        return 1;
    }
    if (ioctl(spidev, SPI_IOC_SET_MODE, SPI_MODE) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ioctl(spidev, SPI_IOC_SET_BIT_PER_WORD, SPI_BIT_PER_WORD) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ioctl(spidev, SPI_IOC_SETClock, SPI_CLOCK) < 0) {
        perror("ioctl");
        return 1;
    }

    // Open log file
    int log_fd = open(GPIO_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Main loop
    struct timespec deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &deadline);
    deadline.tv_nsec += 1000;
    while (1) {
        // Toggle CE0
        gpioWrite(GPIO_CE0, 1);
        usleep(10);
        gpioWrite(GPIO_CE0, 0);
        usleep(10);

        // Read ADC
        uint8_t adc_value;
        if (ioctl(spidev, SPI_IOC_READ, &adc_value) < 0) {
            perror("ioctl");
            return 1;
        }

        // Get current time
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        uint64_t timestamp_ns = now.tv_sec * 1000000000 + now.tv_nsec;

        // Write to log file
        char log_line[20];
        sprintf(log_line, "%llu|%u\n", timestamp_ns, adc_value);
        if (write(log_fd, log_line, strlen(log_line)) < 0) {
            perror("write");
            return 1;
        }

        // Sleep until next deadline
        deadline.tv_nsec -= 1000;
        if (deadline.tv_nsec < 0) {
            deadline.tv_sec++;
            deadline.tv_nsec = 1000000000;
        }
        nanosleep(&deadline, NULL);
    }

    // Release resources
    gpioRelease(gpio);
    close(spidev);
    close(log_fd);

    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(GPIO_CE0, 0);
    close(STDIN_FILENO);
    exit(0);
}

void sigterm_handler(int sig) {
    gpioWrite(GPIO_CE0, 0);
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    exit(0);
}

