#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/statvfs.h>
#include <syslog.h>

#define SPI_CE0 18
#define SPI_SCK 23
#define SPI_MOSI 24
#define SPI_MISO 25
#define ADC_CHANNEL 0
#define SPI_CLOCK 1000000
#define FILE_NAME "gas_log.txt"

int main() {
    int spi_fd, adc_fd;
    unsigned char spi_buf[3];
    unsigned int adc_value;
    unsigned int voltage;
    unsigned int ppm;
    struct sigaction sa;
    struct stat sb;
    struct statvfs st;
    char filename[256];
    char timestamp[20];
    char voltage_str[10];
    char ppm_str[10];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI interface
    if ((spi_fd = spiOpen(SPI_CE0, SPI_SCK, SPI_MOSI, SPI_MISO, SPI_CLOCK, 0)) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Set up ADC interface
    if ((adc_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("open");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up ADC channel
    if (ioctl(adc_fd, 0x00, &adc_value) < 0) {
        perror("ioctl");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI transfer
    if (spiXfer(spi_fd, spi_buf, 0, 3, SPI_XFER_READ) < 0) {
        perror("spiXfer");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up file logging
    if (mkdir("/var/log", 0777) < 0) {
        perror("mkdir");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        if (ioctl(adc_fd, 0x00, &adc_value) < 0) {
            usleep(100000);
            continue;
        }

        // Calculate voltage
        voltage = (adc_value * 3.3) / 4096;

        // Calculate PPM
        ppm = (adc_value * 1000) / 4096;

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));

        // Format voltage and PPM
        sprintf(voltage_str, "%.2f", voltage);
        sprintf(ppm_str, "%.2f", ppm);

        // Print to console
        printf("%s %s %s PPM\n", timestamp, voltage_str, ppm_str);

        // Append to file
        sprintf(filename, "/var/log/%s", FILE_NAME);
        if (fopen(filename, "a") < 0) {
            perror("fopen");
            continue;
        }
        fprintf(filename, "%s %s %s PPM\n", timestamp, voltage_str, ppm_str);
        fclose(filename);

        // Check SPI initialization error
        if (gpioGetIOPin(SPI_CE0, GPIO_IS_HIGH) < 0) {
            perror("gpioGetIOPin");
            continue;
        }

        // Check SPI transfer failure
        if (spiXfer(spi_fd, spi_buf, 0, 3, SPI_XFER_READ) < 0) {
            perror("spiXfer");
            continue;
        }
    }

    // Clean up
    gpioTerminate();
    close(adc_fd);
    close(spi_fd);
    return 0;
}

void sigint_handler(int sig) {
    gpioTerminate();
    close(adc_fd);
    close(spi_fd);
    exit(0);
}

