        // Apply the Kalman filter
        apply_kalman_filter(&filter, x, y, z);

        // Print the filtered values
        printf("%.2f %.2f %.2f\n", filter.x, filter.y, filter.z);

        // Sleep for 0.1 seconds
        sleep(0.1);
    }

