#include <sys/statvfs.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define FILE_NAME "magnetic_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open file for writing
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Map file to memory
    struct stat sb;
    if (fstat(fd, &sb) < 0) {
        perror("fstat");
        close(fd);
        gpioTerminate();
        return 1;
    }
    void* map = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Define constants
    const float sensor1_min = -100.0f;
    const float sensor1_max = 100.0f;
    const float sensor2_min = -100.0f;
    const float sensor2_max = 100.0f;
    const float sensor3_min = -100.0f;
    const float sensor3_max = 100.0f;

    // Define signal handler for SIGINT
    void sigint_handler(int sig) {
        gpioTerminate();
        close(fd);
        munmap(map, sb.st_size);
        exit(0);
    }

    // Register signal handler
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read GPIO states
        int sensor1 = gpioGet(GPIO4);
        int sensor2 = gpioGet(GPIO17);
        int sensor3 = gpioGet(GPIO27);

        // Check for errors
        if (sensor1 < 0 || sensor2 < 0 || sensor3 < 0) {
            printf("Error reading GPIO\n");
            continue;
        }

        // Convert states to magnetic field strengths
        float sensor1_mT = (sensor1 == 1) ? sensor1_max : (sensor1 == 0) ? sensor1_min : 0.0f;
        float sensor2_mT = (sensor2 == 1) ? sensor2_max : (sensor2 == 0) ? sensor2_min : 0.0f;
        float sensor3_mT = (sensor3 == 1) ? sensor3_max : (sensor3 == 0) ? sensor3_min : 0.0f;

        // Check for out-of-range values
        if (sensor1_mT < sensor1_min || sensor1_mT > sensor1_max || sensor2_mT < sensor2_min || sensor2_mT > sensor2_max || sensor3_mT < sensor3_min || sensor3_mT > sensor3_max) {
            printf("Warning: out-of-range value %f\n", sensor1_mT);
            continue;
        }

        // Write to file
        char buffer[256];
        sprintf(buffer, "%f,%f,%f\n", sensor1_mT, sensor2_mT, sensor3_mT);
        write(fd, buffer, strlen(buffer));

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(fd);
    munmap(map, sb.st_size);
    gpioTerminate();

    return 0;
}

