#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

// Define constants
#define SPI_MODE 0
#define SPI_SPEED 500000
#define SPI_CE0 17
#define GPIO_PUMP 17
#define GPIO_MOSI 18
#define GPIO_MISO 19
#define GPIO_SCK 23
#define GPIO_CS 24
#define ADC_CHANNEL 0
#define LOG_FILE "watering.log"

// Define structures
typedef struct {
    int fd;
    int pump;
    int mosi;
    int miso;
    int sck;
    int cs;
    int adc;
} spi_config_t;

// Function prototypes
void init_spi(spi_config_t *config);
void init_adc(spi_config_t *config);
void read_adc(spi_config_t *config);
void drive_pump(spi_config_t *config, bool on);
void log_event(spi_config_t *config, const char *message);
void cleanup(spi_config_t *config);
void sigint_handler(int sig);
void sigterm_handler(int sig);

int main() {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Create log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        log_event(NULL, "Failed to open log file");
        return 1;
    }

    // Initialize GPIO
    gpioInitialise();
    gpioSetMode(GPIO_PUMP, PI_OUTPUT);
    gpioSetMode(GPIO_MOSI, PI_INPUT);
    gpioSetMode(GPIO_MISO, PI_INPUT);
    gpioSetMode(GPIO_SCK, PI_INPUT);
    gpioSetMode(GPIO_CS, PI_INPUT);

    // Initialize SPI
    spi_config_t config;
    config.fd = spiOpen(SPI_CE0, SPI_SPEED, SPI_MODE);
    if (config.fd < 0) {
        log_event(&config, "Failed to open SPI bus");
        return 1;
    }
    config.mosi = gpioGetPin(GPIO_MOSI);
    config.miso = gpioGetPin(GPIO_MISO);
    config.sck = gpioGetPin(GPIO_SCK);
    config.cs = gpioGetPin(GPIO_CS);
    config.pump = gpioGetPin(GPIO_PUMP);
    config.adc = gpioGetPin(ADC_CHANNEL);

    // Initialize ADC
    init_adc(&config);

    // Main loop
    while (1) {
        read_adc(&config);
        drive_pump(&config, config.moisture_level < 30);
        log_event(&config, "Moisture level: %d%%", config.moisture_level);
        sleep(60);
    }

    // Cleanup
    cleanup(&config);
    close(log_fd);
    gpioCleanUp();
    return 0;
}

void init_adc(spi_config_t *config) {
    // Initialize ADC
    int adc_fd = spiXfer(config->cs, config->mosi, config->miso, config->sck, 1);
    if (adc_fd < 0) {
        log_event(&config, "Failed to initialize ADC");
        return;
    }
    config->adc = adc_fd;
}

void read_adc(spi_config_t *config) {
    // Read ADC value
    int adc_value = spiXfer(config->cs, config->mosi, config->miso, config->sck, 1);
    if (adc_value < 0) {
        log_event(&config, "Failed to read ADC value");
        return;
    }
    config->moisture_level = (adc_value / 1024.0) * 100;
}

void drive_pump(spi_config_t *config, bool on) {
    // Drive pump
    if (on) {
        gpioWrite(config->pump, HIGH);
    } else {
        gpioWrite(config->pump, LOW);
    }
}

void log_event(spi_config_t *config, const char *message) {
    // Log event
    char log_message[256];
    sprintf(log_message, "%s %d\n", message, time(NULL));
    write(log_fd, log_message, strlen(log_message));
}

void cleanup(spi_config_t *config) {
    // Cleanup
    gpioCleanUp();
    close(config->adc);
    spiClose(config->fd);
}

void sigint_handler(int sig) {
    // Handle SIGINT
    drive_pump(&config, false);
    cleanup(&config);
    exit(0);
}

void sigterm_handler(int sig) {
    // Handle SIGTERM
    drive_pump(&config, false);
    cleanup(&config);
    exit(0);
}

