#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_ATTEMPTS 10
#define MAX_RECONNECT_DELAY 1
#define MAX_RECONNECT_MAX 60

int gpio = -1;
int reconnect_attempts = 0;
int reconnect_delay = 1;
int reconnect_max_delay = MAX_RECONNECT_MAX;

void reconnect() {
    reconnect_attempts++;
    if (reconnect_attempts > MAX_RECONNECT_ATTEMPTS) {
        printf("Maximum reconnect attempts exceeded. Giving up.\n");
        exit(1);
    }
    sleep(reconnect_delay);
    reconnect_delay *= 2;
    if (reconnect_delay > reconnect_max_delay) {
        reconnect_delay = reconnect_max_delay;
    }
}

void mqtt_callback(int rc, void *arg) {
    if (rc == 0) {
        printf("Connected to MQTT broker.\n");
    } else if (rc == 1) {
        printf("Connection refused. Retrying in %d seconds.\n", reconnect_delay);
        reconnect();
    } else {
        printf("MQTT error: %d\n", rc);
        reconnect();
    }
}

void json_callback(const char *key, const char *value, void *arg) {
    if (strcmp(key, "led_state") == 0) {
        int led_state = atoi(value);
        if (led_state == 0) {
            gpio = 0;
        } else {
            gpio = 1;
        }
        printf("LED state: %d\n", gpio);
    } else {
        printf("Invalid JSON payload. Rejecting message.\n");
        mqtt_callback(2, NULL);
    }
}

void gpio_callback(int gpio, int level, int edge, void *arg) {
    printf("GPIO %d: %d\n", gpio, level);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    struct sigaction sa2;
    sa2.sa_handler = sigterm_handler;
    sa2.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa2, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    if (gpio = pigpio_open(17, PI_OUTPUT) == -1) {
        perror("gpio_open");
        exit(1);
    }

    pigpio_set_mode(gpio, PI_OUTPUT);
    pigpio_pull_up(gpio, PI_PULL_UPDOWN);

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        perror("socket");
        exit(1);
    }

    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(MQTT_PORT);
    inet_pton(AF_INET, MQTT_BROKER, &server.sin_addr);
    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) == -1) {
        perror("connect");
        close(sock);
        exit(1);
    }

    struct sockaddr_in client;
    client.sin_family = AF_INET;
    client.sin_port = htons(MQTT_PORT);
    inet_pton(AF_INET, MQTT_BROKER, &client.sin_addr);
    if (connect(sock, (struct sockaddr *)&client, sizeof(client)) == -1) {
        perror("connect");
        close(sock);
        exit(1);
    }

    struct json_object *json = json_object_new();
    if (json == NULL) {
        perror("json_object_new");
        close(sock);
        exit(1);
    }

    json_object_object_add(json, "client_id", json_object_new_string(MQTT_CLIENT_ID));
    json_object_object_add(json, "topic", json_object_new_string(MQTT_TOPIC));
    json_object_object_add(json, "qos", json_object_new_int(0));

    char buffer[256];
    while (1) {
        char *payload = malloc(256);
        if (read(sock, payload, 256) == -1) {
            perror("read");
            free(payload);
            break;
        }
        payload[read(sock, payload, 256 - 1)] = '\0';
        struct json_object *obj = json_object_parse(payload);
        if (obj == NULL) {
            perror("json_parse");
            free(payload);
            break;
        }
        json_callback("led_state", payload, json);
        json_object_put(obj);
        free(payload);
    }

    json_object_put(json);
    close(sock);
    pigpio_close(gpio);
    exit(0);
}

void sigint_handler(int sig) {
    printf("Received SIGINT. Disconnecting from MQTT.\n");
    close(sock);
    pigpio_close(gpio);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM. Disconnecting from MQTT and shutting down.\n");
    close(sock);
    pigpio_close(gpio);
    exit(0);
}

