#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define GPIO17 17
#define GPIO18 18
#define DELAY 100
#define LED_PIN GPIO18
#define SOUND_PIN GPIO17

// Define a function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    gpioStop(SOUND_PIN);
    gpioStop(LED_PIN);
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %d\n", gpioGetLastError());
        return 1;
    }

    // Set up the alarm LED pin as an output
    if (gpioMode(LED_PIN, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Error setting up LED pin: %d\n", gpioGetLastError());
        gpioTerminate();
        return 1;
    }

    // Set up the sound sensor pin as an input
    if (gpioMode(SOUND_PIN, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "Error setting up sound sensor pin: %d\n", gpioGetLastError());
        gpioTerminate();
        return 1;
    }

    // Set up the alarm LED pin as an output
    if (gpioMode(LED_PIN, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Error setting up LED pin: %d\n", gpioGetLastError());
        gpioTerminate();
        return 1;
    }

    // Set the initial state of the alarm LED to off
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error setting up LED pin: %d\n", gpioGetLastError());
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Read the sound sensor value
        int sound_value = gpioRead(SOUND_PIN);
        if (sound_value < 0) {
            fprintf(stderr, "Error reading sound sensor: %d\n", gpioGetLastError());
            break;
        }

        // Check if the sound level is high (i.e., the sensor is reporting a sound event)
        if (sound_value == 0) {
            // Turn on the alarm LED
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Error setting up LED pin: %d\n", gpioGetLastError());
                break;
            }
            sleep(1); // Turn off the LED after 1 second
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Error setting up LED pin: %d\n", gpioGetLastError());
                break;
            }
        }

        // Print the sound level reading
        printf("%d\n", sound_value);

        // Wait for 100ms before taking the next reading
        usleep(DELAY * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

