    exit = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the GPIO chip
    int chip = gpioGetChipNumber();
    if (chip < 0) {
        perror("gpioGetChipNumber");
        gpioTerminate();
        return 1;
    }

    // Open the GPIO line
    int line = gpioGetLine(chip, GPIO_PIN, GPIO_MODE, GPIO_EDGE_FALLING);
    if (line < 0) {
        perror("gpioGetLine");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!exit) {
        // Read the event
        int event = gpioGetEvent(line);
        if (event < 0) {
            perror("gpioGetEvent");
            continue;
        }

        // Check if the event is a falling edge
        if (event == GPIO_EDGE_FALLING) {
            // Read the event value
            int value = gpioRead(line);
            if (value < 0) {
                perror("gpioRead");
                continue;
            }

            // Append to log file and print to stdout
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL));
            fprintf(log_fd, "%s: Vibration detected\n", timestamp);
            printf("%s: Vibration detected\n", timestamp);

            // Invoke shutdown
            system("sudo shutdown -h now");
        }
    }

    // Clean up
    gpioTerminate();
    close(log_fd);
    return 0;
}
