#include <time.h>
#include <sys/time.h>

#define I2C_ADDRESS 0x76
#define I2C_SPEED 100000
#define FILE_NAME "altitude_log.txt"

int main(int argc, char *argv[]) {
    int i2c_fd;
    int ret;
    struct pigpio *gpio;
    struct timeval tv;
    struct tm *timeinfo;
    struct stat sb;
    char buffer[256];
    char timestamp[32];

    // Initialize pigpio
    gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2c_open(1, I2C_ADDRESS, I2C_SPEED);
    if (i2c_fd < 0) {
        perror("i2c_open");
        pigpio_close(gpio);
        return 1;
    }

    // Check if I2C bus is available
    ret = i2c_read(i2c_fd, I2C_ADDRESS, 0x00, 1, 0);
    if (ret < 0) {
        perror("i2c_read");
        i2c_close(i2c_fd);
        pigpio_close(gpio);
        return 1;
    }

    // Check if sensor is present
    if (ret != 0x55) {
        fprintf(stderr, "BMP280 sensor not found\n");
        i2c_close(i2c_fd);
        pigpio_close(gpio);
        return 1;
    }

    // Open log file
    sb.st_mode = S_IRUSR | S_IWUSR;
    if (access(FILE_NAME, F_OK) == -1) {
        if (mkdir(FILE_NAME, sb.st_mode) == -1) {
            perror("mkdir");
            i2c_close(i2c_fd);
            pigpio_close(gpio);
            return 1;
        }
    }
    if (open(FILE_NAME, O_WRONLY | O_CREAT, sb.st_mode) == -1) {
        perror("open");
        i2c_close(i2c_fd);
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        // Read raw pressure and temperature data
        ret = i2c_read(i2c_fd, I2C_ADDRESS, 0x32, 2, 0);
        if (ret < 0) {
            perror("i2c_read");
            i2c_close(i2c_fd);
            pigpio_close(gpio);
            return 1;
        }

        // Apply compensation to compute altitude
        int16_t pressure = (ret >> 8) & 0xFF;
        int16_t temperature = ret & 0xFF;
        int16_t pressure_compensated = pressure - 0x8000;
        int16_t temperature_compensated = temperature - 0x100;
        float altitude = (pressure_compensated * 0.001) / 256.0 - 44330.0;

        // Convert time to ISO 8601 format
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv));

        // Write altitude and timestamp to log file
        fprintf(FILE_NAME, "%f %s\n", altitude, timestamp);
        fflush(FILE_NAME);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    close(i2c_fd);
    pigpio_close(gpio);
    return 0;
}

