#include <unistd.h>
#include <pigpio.h>
#include <string.h>

#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5
#define SPI_DEVICE 0
#define SPI_CE 8
#define SPI_MOSI 9
#define SPI_MISO 10
#define SPI_SCK 11

float buffer[BUFFER_SIZE];
int buffer_index = 0;
int file_fd = -1;

void sigint_handler(int sig) {
    gpio_close(SPI_CE);
    gpio_close(SPI_MOSI);
    gpio_close(SPI_MISO);
    gpio_close(SPI_SCK);
    close(file_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_close(SPI_CE);
    gpio_close(SPI_MOSI);
    gpio_close(SPI_MISO);
    gpio_close(SPI_SCK);
    close(file_fd);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() == -1) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(SPI_CE, PI_OUTPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_MOSI, PI_OUTPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_MISO, PI_INPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_SCK, PI_OUTPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetLevel(SPI_CE, 0) == -1) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SPI_CE, 0) == -1) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SPI_CE, 1) == -1) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    if (gpioRead(SPI_MISO, &buffer[buffer_index]) == -1) {
        perror("gpioRead");
        gpioTerminate();
        return 1;
    }

    float temperature = (buffer[buffer_index] * 0.0625);
    printf("Temperature: %.2f°C\n", temperature);

    if (fopen("temp_log.dat", "wb+") == -1) {
        perror("fopen");
        printf("Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    file_fd = fileno(fopen("temp_log.dat", "wb+"));
    if (file_fd == -1) {
        perror("fileno");
        printf("Failed to get file descriptor\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        if (usleep(SAMPLE_INTERVAL * 1000000) == -1) {
            perror("usleep");
            gpioTerminate();
            return 1;
        }

        if (gpioRead(SPI_CE, &buffer[buffer_index]) == -1) {
            perror("gpioRead");
            gpioTerminate();
            return 1;
        }

        temperature = (buffer[buffer_index] * 0.0625);
        printf("Temperature: %.2f°C\n", temperature);

        if (fwrite(&temperature, sizeof(float), 1, file_fd) == -1) {
            perror("fwrite");
            gpioTerminate();
            return 1;
        }

        if (fseek(file_fd, -sizeof(float), SEEK_CUR) == -1) {
            perror("fseek");
            gpioTerminate();
            return 1;
        }

        if (buffer_index == BUFFER_SIZE - 1) {
            buffer_index = 0;
        } else {
            buffer_index++;
        }
    }

    gpioTerminate();
    return 0;
}

