#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/systm.h>
#include <sys/param.h>
#include <sys/utsname.h>
#include <time.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDRESS_BH1750 0x23
#define I2C_ADDRESS_MCP3008 0x68
#define SPI_CHANNEL 0
#define FILE_NAME "environmental_log.txt"

int main(int argc, char *argv[]) {
    int i2c_fd, spi_fd;
    struct i2c_msg i2c_msg;
    struct spi_i2c_msg spi_msg;
    struct timespec start_time;
    struct timespec end_time;
    struct timeval tv;
    struct ucontext_t ucontext;
    struct sigaction sa;
    struct sigaction sigint_action, sigterm_action;
    char timestamp[20];
    char light_value[10];
    char sound_value[10];
    int light_value_int;
    int sound_value_int;
    int i, j;
    int light_error, sound_error;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Open SPI bus
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address for BH1750
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS_BH1750) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI mode for MCP3008
    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE0) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI clock speed
    if (ioctl(spi_fd, SPI_SET_CLOCK, 1000000) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI data format
    if (ioctl(spi_fd, SPI_SET_DATA_FORMAT, 0x00) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI data order
    if (ioctl(spi_fd, SPI_SET_DATA_ORDER, 0) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI chip select
    if (ioctl(spi_fd, SPI_SET ChipSelect, 0) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set I2C address for BH1750
    i2c_msg.msg_type = I2C_READ;
    i2c_msg.msg_dir = I2C_READ;
    i2c_msg.addr = I2C_ADDRESS_BH1750;
    i2c_msg.len = 2;
    i2c_msg.buf = (char *)malloc(2);
    if (i2c_msg.buf == NULL) {
        perror("malloc");
        return 1;
    }

    // Read light value from BH1750
    if (i2cSendRecv(i2c_fd, &i2c_msg, NULL, 0) < 0) {
        perror("i2cSendRecv");
        return 1;
    }

    light_error = i2c_msg.err;
    if (light_error != 0) {
        printf("Error reading light value from BH1750\n");
        return 1;
    }

    light_value_int = (light_value[0] << 8) | light_value[1];
    sprintf(light_value, "%d", light_value_int);

    // Set I2C address for MCP3008
    i2c_msg.msg_type = I2C_READ;
    i2c_msg.msg_dir = I2C_READ;
    i2c_msg.addr = I2C_ADDRESS_MCP3008;
    i2c_msg.len = 2;
    i2c_msg.buf = (char *)malloc(2);
    if (i2c_msg.buf == NULL) {
        perror("malloc");
        return 1;
    }

    // Read sound value from MCP3008
    if (i2cSendRecv(i2c_fd, &i2c_msg, NULL, 0) < 0) {
        perror("i2cSendRecv");
        return 1;
    }

    sound_error = i2c_msg.err;
    if (sound_error != 0) {
        printf("Error reading sound value from MCP3008\n");
        return 1;
    }

    sound_value_int = (sound_value[0] << 8) | sound_value[1];
    sprintf(sound_value, "%d", sound_value_int);

    // Record timestamp
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    // Append to log file
    FILE *log_file = fopen(FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    fprintf(log_file, "%s, Light: %s, Sound: %s\n", timestamp, light_value, sound_value);
    fclose(log_file);

    // Release resources
    free(i2c_msg.buf);
    close(i2c_fd);
    close(spi_fd);

    // Restore original signal handlers
    sigemptyset(&sigint_action.sa_mask);
    sigemptyset(&sigterm_action.sa_mask);
    sigemptyset(&ucontext.sa_mask);
    sigemptyset(&ucontext.sa_flags);
    sigemptyset(&ucontext.sa_restorer);
    sigaction(SIGINT, &sigint_action, NULL);
    sigaction(SIGTERM, &sigterm_action, NULL);
    sigaction(SIGALRM, &ucontext, NULL);

    return 0;
}

