    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Open SPI bus
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address for BH1750
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS_BH1750) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI mode for MCP3008
    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE0) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI clock speed
    if (ioctl(spi_fd, SPI_SET_CLOCK, 1000000) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI data format
    if (ioctl(spi_fd, SPI_SET_DATA_FORMAT, 0x00) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI data order
    if (ioctl(spi_fd, SPI_SET_DATA_ORDER, 0) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set SPI chip select
    if (ioctl(spi_fd, SPI_SET ChipSelect, 0) < 0) {
        perror("ioctl");
        return 1;
    }

