#include <syslog.h>

#define GPIO_PIN 17
#define CSV_FILE "flame_events.log"

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set up the GPIO pin as an input with a pull-down resistor
    if (gpioMode(GPIO_PIN, GPIO_IN) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioPullUpDn(GPIO_PIN, GPIO_PUD_DOWN) < 0) {
        perror("gpioPullUpDn");
        exit(1);
    }

    // Open the CSV file for writing
    int fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Log the header row
    fprintf(fd, "timestamp,pin,state\n");

    // Poll the pin every second
    struct timespec ts;
    while (1) {
        // Get the current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Read the pin state
        int state = gpioRead(GPIO_PIN);
        if (state < 0) {
            perror("gpioRead");
            exit(1);
        }

        // Log the reading
        fprintf(fd, "%ld,%d,%d\n", ts.tv_sec, GPIO_PIN, state);

        // Check if the pin is HIGH
        if (state == 1) {
            syslog(LOG_INFO, "Flame detected!");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioCleanse();
    close(fd);
    return 0;
}

