#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <stdint.h>

#define SPI_MODE SPI_MODE0
#define SPI_SPEED 500000
#define SPI_CE0 18
#define I2C_ADDRESS 0x68
#define DAC_ADDRESS 0x60

int main() {
    int spi_fd, i2c_fd;
    int ret;
    unsigned char spi_buf[3];
    unsigned char i2c_buf[3];
    unsigned int adc_value;
    float temperature;
    float dac_voltage;
    struct timespec ts;
    struct stat sb;
    char filename[] = "temperature_log.txt";
    char log_file_path[256];
    char error_message[256];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI interface
    if ((spi_fd = spiOpen(SPI_CE0, SPI_MODE, SPI_SPEED)) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Open I2C interface
    if ((i2c_fd = i2cOpen(I2C_ADDRESS, I2C_SPEED)) < 0) {
        perror("i2cOpen");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((ret = access(filename, F_OK)) != 0) {
        if (ret == -2) {
            // File does not exist, create it
            if ((ret = mkdir(filename, S_IRUSR | S_IWUSR)) < 0) {
                perror("mkdir");
                i2cClose(i2c_fd);
                spiClose(spi_fd);
                gpioTerminate();
                return 1;
            }
        } else if (ret != 0) {
            // File exists, open it
            if ((ret = open(filename, O_RDWR | O_CREAT | O_WRONLY | O_APPEND, S_IRUSR | S_IWUSR)) < 0) {
                perror("open");
                i2cClose(i2c_fd);
                spiClose(spi_fd);
                gpioTerminate();
                return 1;
            }
        }
    }

    while (1) {
        // Read ADC value
        if (spiRead(spi_fd, spi_buf, 3) < 0) {
            perror("spiRead");
            sleep(1);
            continue;
        }

        // Convert ADC value to temperature
        adc_value = (spi_buf[0] << 8) | spi_buf[1];
        temperature = (adc_value / 1024.0) * 100.0;

        // Write to DAC
        if (i2cWrite(i2c_fd, DAC_ADDRESS, 0x00, &dac_voltage) < 0) {
            perror("i2cWrite");
            sleep(1);
            continue;
        }

        // Log data
        if (strftime(log_file_path, sizeof(log_file_path), "%Y-%m-%d %H:%M:%S", &ts) < 0) {
            perror("strftime");
            sleep(1);
            continue;
        }
        if (snprintf(error_message, sizeof(error_message), "%s %d %f %f\n", log_file_path, adc_value, temperature, dac_voltage) < 0) {
            perror("snprintf");
            sleep(1);
            continue;
        }
        if (write(filename, error_message, strlen(error_message)) < 0) {
            perror("write");
            sleep(1);
            continue;
        }

        // Echo data
        printf("%s %d %f %f\n", log_file_path, adc_value, temperature, dac_voltage);
    }

    // Clean up
    if (close(i2c_fd) < 0) {
        perror("close");
    }
    if (close(spi_fd) < 0) {
        perror("close");
    }
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
    }

    return 0;
}

