// Define the GPIO pin numbers for the relays
#define RELAY1 17
#define RELAY2 22
#define RELAY3 23
#define RELAY4 24

// Define the number of relays
#define NUM_RELAYS 4

// Define the sleep time in seconds
#define SLEEP_TIME 1

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Deactivate all relays
    gpioWrite(RELAY1, 0);
    gpioWrite(RELAY2, 0);
    gpioWrite(RELAY3, 0);
    gpioWrite(RELAY4, 0);

    // Release all GPIO lines
    gpioCleanUp();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Install the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Deactivate all relays
    gpioWrite(RELAY1, 0);
    gpioWrite(RELAY2, 0);
    gpioWrite(RELAY3, 0);
    gpioWrite(RELAY4, 0);

    // Loop indefinitely
    while (1) {
        // Activate relay 1
        gpioWrite(RELAY1, 1);
        sleep(SLEEP_TIME);

        // Deactivate relay 1
        gpioWrite(RELAY1, 0);
        sleep(SLEEP_TIME);

        // Activate relay 2
        gpioWrite(RELAY2, 1);
        sleep(SLEEP_TIME);

        // Deactivate relay 2
