        // Activate relay 4
        gpioWrite(RELAY4, 1);
        sleep(SLEEP_TIME);

        // Deactivate relay 4
        gpioWrite(RELAY4, 0);
        sleep(SLEEP_TIME);
    }

    // Release all GPIO lines
    gpioCleanUp();

    // Finalize the GPIO library
