        perror("gpioInitialise");
        return 1;
    }

    // Initialize SPI
    if (gpioSetMode(SPI_CE, PI_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClock(SPI_CE, SPI_SPEED) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = 0;
        if (gpioGetValue(SPI_CE) < 0) {
            perror("gpioGetValue");
            continue;
        }
        if (gpioWrite(SPI_CE, 0x00) < 0) {
            perror("gpioWrite");
            continue;
        }
        if (gpioWrite(SPI_CE, 0x01) < 0) {
            perror("gpioWrite");
            continue;
        }
        if (gpioRead(SPI_CE, &adc_value) < 0) {
            perror("gpioRead");
            continue;
        }
        gpioWrite(SPI_CE, 0x00);

        // Check if value exceeds threshold
        if (adc_value > 500) {
            // Turn on LED
            gpioWrite(LED_GPIO, 1);
            sleep(DEBOUNCE_DELAY);
            gpioWrite(LED_GPIO, 0);

            // Log event
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s %d\n", timestamp, adc_value);
        }

        // Sleep for sample rate
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    gpioTerminate();
    close(log_fd);
    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(SPI_CE, 0x00);
    gpioTerminate();
    exit(0);
}
