#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_BASE 0x3F200000
#define GPIO_PIN 26
#define GPIO_LED 16
#define ADC_BASE 0x43
#define ADC_CHANNEL 0
#define CLAP_DEBOUNCE 50
#define LED_ON_TIME 500

int main() {
    // Initialize GPIO
    int gpio = pigpio_init();
    if (gpio < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Set GPIO mode to input
    gpio_mode_t mode = GPIO_MODE_INPUT;
    if (gpio BCM_to physical(GPIO_PIN) < 0) {
        perror("BCM_to_physical");
        return 1;
    }
    if (gpio_mode(GPIO_PIN, mode) < 0) {
        perror("gpio_mode");
        return 1;
    }

    // Set GPIO pull-up resistor
    gpio_pull_up_dnpull_t pull_up = GPIO_PULL_UP_DNPULL_DISABLE;
    if (gpio_pull_up_dnpull(GPIO_PIN, pull_up) < 0) {
        perror("gpio_pull_up_dnpull");
        return 1;
    }

    // Initialize ADC
    int adc = open("/dev/gpiod/adc", O_RDWR);
    if (adc < 0) {
        perror("open");
        return 1;
    }

    // Set ADC channel and gain
    struct gpiod_adc_config adc_config = {
        .channel = GPIO_PIN,
        .gain = 1,
    };
    if (ioctl(adc, GPIOD_ADC_SET_CONFIG, &adc_config) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set ADC clock
    struct gpiod_adc_clock_config adc_clock_config = {
        .clock = 1,
    };
    if (ioctl(adc, GPIOD_ADC_SET_CLOCK, &adc_clock_config) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set ADC conversion
    struct gpiod_adc_conversion_config adc_conversion_config = {
        .conversion = 1,
    };
    if (ioctl(adc, GPIOD_ADC_SET_CONVERSION, &adc_conversion_config) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set GPIO LED
    gpio = gpio_get(GPIO_LED);
    if (gpio < 0) {
        perror("gpio_get");
        return 1;
    }
    if (gpio_mode(GPIO_LED, GPIO_MODE_OUTPUT) < 0) {
        perror("gpio_mode");
        return 1;
    }

    // Set GPIO LED high
    gpio_write(GPIO_LED, 1);

    // Main loop
    while (1) {
        // Read ADC value
        struct gpiod_adc_value adc_value;
        if (ioctl(adc, GPIOD_ADC_READ, &adc_value) < 0) {
            perror("ioctl");
            return 1;
        }

        // Check for clap event
        if (adc_value.value > 0 && gpio_read(GPIO_PIN) == 0) {
            // Debounce
            struct timespec start_time;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (clock_gettime(CLOCK_MONOTONIC, &start_time)->tv_sec == start_time.tv_sec && clock_gettime(CLOCK_MONOTONIC, &start_time)->tv_nsec < start_time.tv_nsec + CLAP_DEBOUNCE * 1000000) {
                // Do nothing
            }

            // Turn on LED
            gpio_write(GPIO_LED, 1);
            printf("Clap detected at %ld\n", clock_gettime(CLOCK_MONOTONIC)->tv_sec);

            // Turn off LED after LED_ON_TIME
            sleep(LED_ON_TIME);
            gpio_write(GPIO_LED, 0);
        }
    }

    // Clean up
    gpio_close(GPIO_LED);
    gpio_close(GPIO_PIN);
    close(adc);
    pigpio_close(gpio);

    return 0;
}

