#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define GPIO17 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"

// Function to handle errors
void handleError(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    sleep(1);
}

// Function to read the distance sensor
int read_distance(pigpio *gpio) {
    int value = gpio_get_value(GPIO17);
    return value;
}

// Function to log the distance to a file
void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        handleError("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s %d\n", timestamp, distance);
    fclose(log_file);
}

// Function to handle signals
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        gpio_close(GPIO17);
        exit(0);
    }
}

int main() {
    // Initialize the GPIO library
    pigpio *gpio = new pigpio();
    if (gpio == NULL) {
        handleError("Failed to initialize GPIO");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int distance = read_distance(gpio);
        if (distance == 1) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }
        log_distance(distance);
        sleep(0.1);
    }

    // Clean up
    gpio_close(GPIO17);
    delete gpio;
    return 0;
}

