#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <signal.h>

#define SPI_CE0 17
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define ADC_CHANNEL 0
#define RELAY_PIN 17
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define LOG_FILE "soil_moisture.log"

// Define the threshold for the moisture level
#define MOISTURE_THRESHOLD 20

// Define the SPI interface
void init_spi() {
    int fd = pigpio_open(SPI_CE0, PI_SPI, 0);
    if (fd < 0) {
        perror("Failed to open SPI interface");
        exit(1);
    }
    pigpio_delay(1000); // Wait for the SPI interface to settle
}

// Define the ADC interface
void init_adc() {
    int fd = pigpio_open(SPI_MISO, PI_SPI, 0);
    if (fd < 0) {
        perror("Failed to open ADC interface");
        exit(1);
    }
    pigpio_delay(1000); // Wait for the ADC interface to settle
}

// Define the relay interface
void init_relay() {
    int fd = pigpio_open(RELAY_PIN, PI_GPIO, 0);
    if (fd < 0) {
        perror("Failed to open relay interface");
        exit(1);
    }
}

// Define the log file interface
void init_log() {
    int fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        exit(1);
    }
}

// Define the main function
int main() {
    // Initialize the SPI interface
    init_spi();

    // Initialize the ADC interface
    init_adc();

    // Initialize the relay interface
    init_relay();

    // Initialize the log file interface
    init_log();

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read the ADC value
        int adc_value = pigpio_read(ADC_CHANNEL);
        if (adc_value < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        // Validate the ADC reading
        if (adc_value < 0 || adc_value > 1023) {
            printf("Invalid ADC reading: %d\n", adc_value);
            continue;
        }

        // Calculate the moisture percentage
        float moisture_percentage = (adc_value / 1023.0) * 100;

        // Check if the moisture level is below the threshold
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            // Turn on the relay
            pigpio_write(RELAY_PIN, RELAY_HIGH);
            printf("Relay ON\n");
        } else {
            // Turn off the relay
            pigpio_write(RELAY_PIN, RELAY_LOW);
            printf("Relay OFF\n");
        }

        // Log the moisture level and relay status
        char log_message[256];
        strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S %f", time(NULL));
        sprintf(log_message + strlen(log_message), "Moisture level: %.2f%%, Relay: %s\n", moisture_percentage, moisture_percentage < MOISTURE_THRESHOLD ? "ON" : "OFF");
        write(fd, log_message, strlen(log_message));

        // Wait for 60 seconds before taking the next reading
        pigpio_delay(60000);
    }

    // Clean up
    pigpio_close(RELAY_PIN);
    pigpio_close(SPI_MISO);
    pigpio_close(SPI_CE0);
    pigpio_close(ADC_CHANNEL);
    close(fd);
    exit(0);
}

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Turn off the relay
    pigpio_write(RELAY_PIN, RELAY_LOW);
    printf("Relay OFF\n");

    // Close the log file
    close(fd);

    // Release all GPIO resources
    pigpio_close(RELAY_PIN);
    pigpio_close(SPI_MISO);
    pigpio_close(SPI_CE0);
    pigpio_close(ADC_CHANNEL);

    // Exit the program
    exit(0);
}

