#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define SPI_CE0 9
#define SPI_MOSI 10
#define SPI_MISO 11
#define SPI_SCK 8
#define GPIO_LED 21
#define GPIO_LOG 22
#define ADC_CHANNEL 0
#define LOG_FILE "magnetic_log.txt"
#define LOG_THRESHOLD 10.0
#define SAMPLE_INTERVAL 100

// Define the SPI structure
struct spi {
    pigpio *gpio;
    int ce, mosi, miso, sck;
};

// Define the LED structure
struct led {
    int gpio;
};

// Define the log structure
struct log {
    time_t timestamp;
    float value;
};

// Function to initialize the SPI interface
struct spi* spi_init() {
    struct spi *spi = malloc(sizeof(struct spi));
    if (!spi) {
        return NULL;
    }

    spi->gpio = pigpio_init();
    if (!spi->gpio) {
        free(spi);
        return NULL;
    }

    spi->ce = gpio_get(spi->gpio, SPI_CE0);
    if (spi->ce < 0) {
        pigpio_close(spi->gpio);
        free(spi);
        return NULL;
    }

    spi->mosi = gpio_get(spi->gpio, SPI_MOSI);
    if (spi->mosi < 0) {
        pigpio_close(spi->gpio);
        free(spi);
        return NULL;
    }

    spi->miso = gpio_get(spi->gpio, SPI_MISO);
    if (spi->miso < 0) {
        pigpio_close(spi->gpio);
        free(spi);
        return NULL;
    }

    spi->sck = gpio_get(spi->gpio, SPI_SCK);
    if (spi->sck < 0) {
        pigpio_close(spi->gpio);
        free(spi);
        return NULL;
    }

    if (gpio_mode(spi->gpio, SPI_MODE0) < 0) {
        pigpio_close(spi->gpio);
        free(spi);
        return NULL;
    }

    if (gpio_pull_up_down(spi->gpio, SPI_CE0, PUD_UP) < 0) {
        pigpio_close(spi->gpio);
        free(spi);
        return NULL;
    }

    return spi;
}

// Function to read the ADC value
float read_adc(struct spi *spi) {
    unsigned int value;
    if (spi->gpio) {
        if (spi->gpio->adc_read(spi->gpio, spi->mosi, spi->miso, spi->sck, spi->ce, 1, &value) < 0) {
            return -1.0;
        }
    }
    return (float)value / 4096.0;
}

// Function to log the reading
void log_reading(struct log *log, float value) {
    log->timestamp = time(NULL);
    log->value = value;
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%f %f\n", log->timestamp, log->value);
        fclose(file);
    }
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    struct spi *spi = spi_init();
    if (spi) {
        gpio_close(spi->gpio);
        free(spi);
    }
    exit(0);
}

int main() {
    struct spi *spi = spi_init();
    if (!spi) {
        printf("Failed to initialize SPI interface\n");
        return 1;
    }

    struct led *led = malloc(sizeof(struct led));
    if (!led) {
        free(spi);
        return 1;
    }

    led->gpio = gpio_get(spi->gpio, GPIO_LED);
    if (led->gpio < 0) {
        gpio_close(spi->gpio);
        free(spi);
        free(led);
        return 1;
    }

    if (gpio_mode(spi->gpio, GPIO_MODE_OUTPUT) < 0) {
        gpio_close(spi->gpio);
        free(spi);
        free(led);
        return 1;
    }

    if (gpio_pull_up_down(spi->gpio, led->gpio, PUD_DOWN) < 0) {
        gpio_close(spi->gpio);
        free(spi);
        free(led);
        return 1;
    }

    struct log *log = malloc(sizeof(struct log));
    if (!log) {
        gpio_close(spi->gpio);
        free(spi);
        free(led);
        return 1;
    }

    while (1) {
        float value = read_adc(spi);
        if (value < 0) {
            printf("Failed to read ADC value\n");
            break;
        }

        if (value > LOG_THRESHOLD) {
            gpio_write(spi->gpio, led->gpio, 1);
        } else {
            gpio_write(spi->gpio, led->gpio, 0);
        }

        log_reading(log, value);

        sleep(SAMPLE_INTERVAL);
    }

    gpio_close(spi->gpio);
    free(spi);
    free(led);
    free(log);

    return 0;
}

