#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/mount.h>
#include <sys/statvfs.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>

#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 17
#define SPI_SCK 18
#define SPI_MOSI 23
#define SPI_MISO 24
#define FILE_NAME "moisture_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI interface
    if (gpioSetup(SPI_SCK, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetup(SPI_SCK)");
        gpioTerminate();
        return 1;
    }
    if (gpioSetup(SPI_MOSI, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetup(SPI_MOSI)");
        gpioTerminate();
        return 1;
    }
    if (gpioSetup(SPI_MISO, GPIO_MODE_INPUT) < 0) {
        perror("gpioSetup(SPI_MISO)");
        gpioTerminate();
        return 1;
    }
    if (gpioSetup(SPI_CS, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetup(SPI_CS)");
        gpioTerminate();
        return 1;
    }

    // Configure SPI interface
    if (gpioSetLevel(SPI_CS, 0) < 0) {
        perror("gpioSetLevel(SPI_CS)");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI_SCK, 1) < 0) {
        perror("gpioSetLevel(SPI_SCK)");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI_MOSI, 0) < 0) {
        perror("gpioSetLevel(SPI_MOSI)");
        gpioTerminate();
        return 1;
    }

    // Open SPI interface
    struct spi_ioc_transfer tr;
    tr.tx { .tx_buf = NULL, .tx_len = 0, .rx_buf = NULL, .rx_len = 0 };
    if (spidev_open(SPI_CHANNEL, &tr) < 0) {
        perror("spidev_open");
        gpioTerminate();
        return 1;
    }

    // Set up SPI interface
    if (spidev_set_bits(SPI_CHANNEL, SPI_MODE, SPI_SPEED) < 0) {
        perror("spidev_set_bits");
        spidev_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    if ((fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("open");
        spidev_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Mount file system
    if (mount(NULL, "/mnt", "/dev/sda1", MS_NOSUID, NULL) < 0) {
        perror("mount");
        close(fd);
        spidev_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Read ADC value
    unsigned char adc_value;
    while (1) {
        if (spidev_read(SPI_CHANNEL, &adc_value, 1) < 0) {
            perror("spidev_read");
            close(fd);
            spidev_close(SPI_CHANNEL);
            gpioTerminate();
            return 1;
        }

        // Convert ADC value to voltage
        float voltage = (adc_value * 3.3f) / 1024.0f;

        // Append to file
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        char value_str[10];
        sprintf(value_str, "%f", voltage);
        if (write(fd, timestamp, strlen(timestamp)) < 0) {
            perror("write");
            close(fd);
            spidev_close(SPI_CHANNEL);
            gpioTerminate();
            return 1;
        }
        if (write(fd, value_str, strlen(value_str)) < 0) {
            perror("write");
            close(fd);
            spidev_close(SPI_CHANNEL);
            gpioTerminate();
