int main(int argc, char *argv[]) {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open SPI device
    int spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd == -1) {
        perror("spidev_open");
        return 1;
    }

    // Configure GPIO pin
    int gpio_fd = gpio_get_fd(GPIO_PIN);
    if (gpio_fd == -1) {
        perror("gpio_get_fd");
        return 1;
    }
    gpio_set_mode(gpio_fd, GPIO_MODE_OUTPUT);
    gpio_set_level(gpio_fd, 0);
    sleep(1); // Debounce
    gpio_set_level(gpio_fd, 1);

    // Open log file
    int log_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        return 1;
    }

    // Main loop
    while (1) {
        // Read from SPI device
        unsigned char data[3];
        if (spidev_read(spi_fd, data, 3, 1000) == -1) {
            perror("spidev_read");
            break;
        }

        // Check if sensor is present
        if (data[0] == 0x00) {
            printf("Sensor not found\n");
            break;
        }

        // Convert ADC reading to amperes
        float current = (data[0] * 1000.0 / 65535.0) * 0.1;

        // Append to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%f\n", timestamp, current);
    }

    // Clean up
    close(log_fd);
    close(spi_fd);
    gpio_close(gpio_fd);

    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    close(log_fd);
    close(spi_fd);
    gpio_close(gpio_fd);
    exit(0);
}

