// Define the SPI MOSI pin function
int spi_mosi_pin(void) {
    // Check if the SPI MOSI pin is already set
    if (spi_mosi_pin == SPI_MOSI_PIN) {
        return 0;
    }

    // Set the SPI MOSI pin
    spi_mosi_pin = SPI_MOSI_PIN;
    return spi_mosi_pin;
}

// Define the SPI CE pin function
int spi_ce_pin(void) {
    // Check if the SPI CE pin is already set
    if (spi_ce_pin == SPI_CE_PIN) {
        return 0;
    }

    // Set the SPI CE pin
    spi_ce_pin = SPI_CE_PIN;
    return spi_ce_pin;
}

// Define the log file function
int log_file(void) {
    // Check if the log file is already open
    if (file_handle >= 0) {
        return 0;
    }

    // Open the log file
    file_handle = open(log_file, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_handle < 0) {
        file_open_error = 1;
        return -1;
    }

    return file_handle;
}

// Define the log format function
int log_format(void) {
