    if (strlen(log_format) > 0) {
        return 0;
    }

    // Set the log format
    sprintf(log_format, "%04d-%02d-%02d %02d:%02d:%02d %.2fA", 
            1900 + 2000 + time(NULL) / 86400, 
            100 + (time(NULL) % 86400) / 3600, 
            100 + (time(NULL) % 3600) / 60, 
            time(NULL) % 60, 
            (float)time(NULL), 
            (float)time(NULL));
    return 0;
}

// Define the current value function
float current_value(void) {
    // Check if the current value is already calculated
    if (current_value != 0.0) {
        return current_value;
    }

    // Calculate the current value
    current_value = (spi_transfer() * 5.0 / 1024.0) * 1000.0;

    return current_value;
}

// Define the previous voltage value function
float previous_voltage(void) {
    // Check if the previous voltage value is already calculated
    if (previous_voltage != 0.0) {
        return previous_voltage;
    }

    // Calculate the previous voltage value
    previous_voltage = current_value;

    return previous_voltage;
}

// Define the previous time function
time_t previous_time(void) {
    // Check if the previous time is already calculated
    if (previous_time != 0) {
        return previous_time;
    }

    // Calculate the previous time
    previous_time = time(NULL);

    return previous_time;
}

