#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define GPIO4 4
#define GPIO17 17
#define DEBOUNCE_TIME 2
#define LOG_INTERVAL 1000 // 1 second

// Structure to hold sensor states
typedef struct {
    int sensor1;
    int sensor2;
} SensorStates;

// Function to read sensor values
int readSensorValues(pigpio *gpio, SensorStates *states) {
    int sensor1, sensor2;
    int i;

    // Read sensor values
    sensor1 = gpio_get_value(gpio, GPIO4);
    sensor2 = gpio_get_value(gpio, GPIO17);

    // Debounce
    for (i = 0; i < 5; i++) {
        usleep(DEBOUNCE_TIME * 1000);
        sensor1 = gpio_get_value(gpio, GPIO4);
        sensor2 = gpio_get_value(gpio, GPIO17);
    }

    // Determine majority value
    states->sensor1 = (sensor1 == 0) ? 1 : 0;
    states->sensor2 = (sensor2 == 0) ? 1 : 0;

    return 0;
}

// Function to log sensor states
void logSensorStates(SensorStates states) {
    if (states.sensor1 == 1 && states.sensor2 == 1) {
        printf("ALERT: Both sensors detect object\n");
    } else {
        printf("%d\n", states.sensor1);
    }
}

// Function to handle SIGINT signal
void sigintHandler(int sig) {
    printf("Exiting...\n");
    gpio_close(GPIO4);
    gpio_close(GPIO17);
    exit(0);
}

int main() {
    pigpio *gpio;
    SensorStates states;
    struct timespec last_log_time;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO modes
    gpio_set_mode(GPIO4, PI_INPUT);
    gpio_set_mode(GPIO17, PI_INPUT);

    // Read initial sensor values
    readSensorValues(gpio, &states);

    // Log initial sensor states
    logSensorStates(states);

    // Install SIGINT handler
    signal(SIGINT, sigintHandler);

    while (1) {
        // Log sensor states every LOG_INTERVAL milliseconds
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - last_log_time.tv_sec > LOG_INTERVAL / 1000) {
            logSensorStates(states);
            last_log_time = now;
        }

        // Read sensor values
        readSensorValues(gpio, &states);
    }

    // Release GPIO resources
    gpio_close(GPIO4);
    gpio_close(GPIO17);
    pigpio_cleanup();
    return 0;
}

