#include <driver.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t stop = 0;

void signal_handler(int signal) {
    spi_close(SPI_HANDLE);
    driver_close();
    exit(0);
}

void log_data(double moisture_level) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s,%f\n", timestamp, moisture_level);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(log_file, "%f\n", moisture_level);
    fclose(log_file);
}

void calculate_moisture_level(int adc_value) {
    return (adc_value - MIN_ADC) / (double) (MAX_ADC - MIN_ADC) * 100;
}

int read_mcp3008(int channel) {
    spi_config_t config = { .mode = SPI_MODE_MASTER, .baud = SPI_BAUD, .bits = 8, .phase = SPI_PHASE_EDGE_RISING, . polarity = SPI_POLARITY_NONE };
    int ret = spi_setup(&config);
    if (ret != 0) {
        printf("Error initializing SPI\n");
        return ret;
    }
    spi_handle_t handle = spi_open(SPI_CHANNEL, SPI_HANDLE);
    if (handle == NULL) {
        printf("Error opening SPI handle\n");
        spi_close(SPI_HANDLE);
        return -1;
    }
    uint8_t data[3] = { 0 };
    ret = spi_transfer(handle, &data, 1, NULL, 0);
    if (ret != 0) {
        printf("Error transferring data from MCP3008\n");
        spi_close(SPI_HANDLE);
        return ret;
    }
    spi_close(handle);
    return data[MCP3008_CHANNEL];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        printf("Error setting signal handler\n");
        return -1;
    }
    while (!stop) {
        int adc_value = read_mcp3008(SPI_CHANNEL);
        if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
            printf("Invalid ADC value\n");
            continue;
        }
        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);
        sleep(READ_DELAY);
    }
    return 0;
}

