```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pigpio.h>
#include <libcamera.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 200
#define CAPTURE_DELAY 200
#define CAPTURE_INTERVAL 50
#define LOG_FILE "/var/log/security_cam.log"

int main() {
    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(gpio, GPIO_IN_PUD_DOWN);
    gpioSetPullUpDowntime(gpio, 100);

    // Construct output path
    char output_path[256];
    snprintf(output_path, sizeof(output_path), "/home/pi/security_cam/%s_%s.jpg", __FILE__, ctime(NULL));

    // Create output directory if it doesn't exist
    mkdir("/home/pi/security_cam", 0777);
    if (mkdir(output_path, 0777) < 0) {
        syslog(LOG_ERR, "Failed to create output directory");
        gpioTerminate();
        return 1;
    }

    // Initialize libcamera
    int camera = cameraInit();
    if (camera < 0) {
        syslog(LOG_ERR, "Failed to initialize libcamera");
        gpioTerminate();
        return 1;
    }

    // Set camera parameters
    cameraSetFormat(camera, CAMERA_FORMAT_JPEG);
    cameraSetResolution(camera, 640, 480);
    cameraSetFramerate(camera, 30);

    // Main loop
    while (1) {
        // Read GPIO17
        int value = gpioRead(gpio);
        if (value == 1) {
            // Debounce delay
            usleep(DEBOUNCE_DELAY * 1000);

            // Read GPIO17 again to confirm motion
            value = gpioRead(gpio);
            if (value == 1) {
                // Capture image
                int pid = fork();
                if (pid < 0) {
                    syslog(LOG_ERR, "Failed to fork");
                    continue;
                } else if (pid == 0) {
                    // Child process
                    execl("/usr/bin/libcamera-still", "libcamera-still", output_path, NULL);
                    syslog(LOG_ERR, "Failed to execute libcamera-still");
                    _exit(1);
                } else {
                    // Parent process
                    int status;
                    waitpid(pid, &status, 0);
                    if (WIFEXITED(status)) {
                        if (WEXITSTATUS(status) != 0) {
                            syslog(LOG_ERR, "Capture failed");
                        }
                    } else {
                        syslog(LOG_ERR, "Capture failed");
                    }
                }
            }
        }

        // Log event
        syslog(LOG_INFO, "Motion detected at %d", time(NULL));
    }

    // Clean up
    gpioTerminate();
    cameraTerminate();
    return 0;
}
