#include <unistd.h>
#include <sys/select.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/ioctl.h>

#define BUFFER_SIZE 1024
#define FILE_NAME "frame_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the video device
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Create a memory-mapped buffer
    void* buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up the MJPEG format
    struct v4l2_mjpeg_control control;
    memset(&control, 0, sizeof(control));
    control.width = 640;
    control.height = 480;
    control.frame_rate = 30;
    control.format = V4L2_MJPEG;
    if (ioctl(fd, V4L2_CTRL, &control) < 0) {
        perror("ioctl");
        munmap(buffer, BUFFER_SIZE);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    int log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        munmap(buffer, BUFFER_SIZE);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up the select loop
    fd_set read_fds;
    FD_ZERO(&read_fds);
    FD_SET(fd, &read_fds);
    FD_SET(log_fd, &read_fds);
    struct timeval timeout = { 0, 0 };
    while (1) {
        int r = select(fd + 1, &read_fds, NULL, NULL, &timeout);
        if (r < 0) {
            perror("select");
            munmap(buffer, BUFFER_SIZE);
            close(fd);
            close(log_fd);
            gpioTerminate();
            return 1;
        }

        if (FD_ISSET(fd, &read_fds)) {
            // Read a frame from the video device
            ssize_t bytes_read = read(fd, buffer, BUFFER_SIZE);
            if (bytes_read < 0) {
                perror("read");
                munmap(buffer, BUFFER_SIZE);
                close(fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }

            // Write the timestamp to the log file
            char timestamp[20];
            sprintf(timestamp, "%d.%06d", (int)(time(NULL) / 1000000), (int)(time(NULL) % 1000000));
            write(log_fd, timestamp, strlen(timestamp));
            write(log_fd, "\n", 1);
        }
    }

    // Clean up
    munmap(buffer, BUFFER_SIZE);
    close(fd);
    close(log_fd);
    gpioTerminate();

    return 0;
}

