#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <pigpio.h>

#define BUFFER_SIZE 4096
#define FRAGMENT_SIZE 65000
#define FRAGMENT_COUNT 4

void usage() {
    printf("Usage: %s <api_call> <target_ip> <target_port>\n", argv[0]);
    exit(1);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        usage();
    }

    const char *api_call = argv[1];
    const char *target_ip = argv[2];
    const char *target_port = argv[3];

    int fd;
    struct v4l2_buffer buffer;
    struct v4l2_frms buffer_frms[FRAGMENT_COUNT];
    struct sockaddr_in server_addr;
    struct iovec iov;
    struct msghdr msg;
    char header[16];
    char *buffer_ptr;
    size_t buffer_size;
    int ret;

    // Initialize pigpio
    if (pi_init() < 0) {
        perror("pi_init");
        return 1;
    }

    // Open the CSI camera
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Configure the camera
    ret = ioctl(fd, V4L2_CTRL, V4L2_CTRL_CSI_CSI_MODE, 0x10000000);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Get the buffer size
    ret = ioctl(fd, V4L2_CTRL, V4L2_CTRL_CSI_CSI_BURST_COUNT);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    buffer_frms[0].count = ret;

    // Get the buffer format
    ret = ioctl(fd, V4L2_CTRL, V4L2_CTRL_CSI_CSI_FORMAT);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    buffer_frms[0].type = buffer_frms[0].fmt = V4L2_FMT_YUYV422;

    // Get the buffer size
    ret = ioctl(fd, V4L2_CTRL, V4L2_CTRL_CSI_CSI_BURST_SIZE);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    buffer_size = ret;

    // Create a socket
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, target_ip, &server_addr.sin_addr);
    server_addr.sin_port = htons(strtol(target_port, NULL, 10));
    server_addr.sin_zero = 0;
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if ((ret = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        close(fd);
        return 1;
    }

    if ((ret = bind(server_addr, (struct sockaddr *)&server_addr, sizeof(server_addr))) < 0) {
        perror("bind");
        close(fd);
        close(server_addr.s_addr);
        return 1;
    }

    // Create a message
    msg.msg_name = (struct sockaddr *)&server_addr;
    msg.msg_namelen = sizeof(server_addr);
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = header;
    msg.msg_controllen = sizeof(header);
    msg.msg_flags = 0;

    // Map the buffer
    buffer_ptr = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer_ptr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        close(server_addr.s_addr);
        return 1;
    }

    // Set up the message
    memset(header, 0, sizeof(header));
    header[0] = 'F';
    header[1] = 'R';
    header[2] = 'A';
    header[3] = 'M';
    header[4] = 'E';
    header[5] = ' ';
    header[6] = 'I';
    header[7] = 'N';
    header[8] = 'G';
    header[9] = ' ';
    header[10] = 'F';
    header[11] = 'R';
    header[12] = 'A';
    header[13] = 'G';
    header[14] = 'M';
    header[15] = '\0';

    while (1) {
        // Read a frame
        ret = read(fd, buffer_ptr, buffer_size);
        if (ret < 0) {
            perror("read");
            break;
        }

        // Fragment the frame
        for (int i = 0; i < FRAGMENT_COUNT; i++) {
            buffer_frms[i].iov_base = buffer_ptr + i * buffer_size;
            buffer_frms[i].iov_len = buffer_size / FRAGMENT_COUNT;
        }

        // Send the fragments
        for (int i = 0; i < FRAGMENT_COUNT; i++) {
            iov.iov_base = buffer_frms[i].iov_base;
            iov.iov_len = buffer_frms[i].iov_len;
            msg.msg_iov = &iov;
            msg.msg_iovlen = 1;
            msg.msg_control = header;
            msg.msg_controllen = sizeof(header);
            msg.msg_flags = 0;

            if ((ret = sendto(server_addr, &msg, sizeof(msg), 0, (struct sockaddr *)&server_addr, sizeof(server_addr))) < 0) {
                perror("sendto");
                break;
            }
        }

        // Unmap the buffer
        if (munmap(buffer_ptr, buffer_size) < 0) {
            perror("munmap");
            break;
        }
    }

    // Close the socket
    if (close(server_addr.s_addr) < 0) {
        perror("close");
    }

    // Close the camera
    if (close(fd) < 0) {
        perror("close");
    }

    // Clean up pigpio
    if (pi_close() < 0) {
        perror("pi_close");
    }

    return 0;
}

