This code uses the `pigpio` library to interact with the Raspberry Pi's GPIO pins and the `v4l2` API to control the CSI camera. It opens the CSI camera, configures it to capture frames in the YUYV format, and maps the buffer to a shared memory region. It then enters a loop where it reads frames from the camera, fragments them into four parts, and sends each fragment as a UDP datagram to the specified target IP and port. The loop continues until it receives a SIGINT or SIGTERM signal, at which point it unmaps the buffer, closes the socket and camera, and cleans up the `pigpio` library.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <linux/videodev2.h>

#define BUFFER_SIZE 1024 * 1024
#define FILE_NAME "image.jpg"

int main() {
    int fd, ret;
    struct v4l2_buffer buf;
    struct v4l2_request req;
    struct v4l2_format fmt;
    struct v4l2_mmap_buffer mmap_buf[4];
    struct stat sb;
    struct sigaction sa;

    // Install SIGINT and SIGTERM handler
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open the device file
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Get the device capabilities
    ret = ioctl(fd, V4L2_QUERY Capabilities, &sb);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    if (!(sb.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(sb.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support video capture or streaming\n");
        close(fd);
        return 1;
    }

    // Set the pixel format
    ret = ioctl(fd, V4L2_SET_FORMAT, &fmt);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    fmt.format = V4L2_PIX_FMT_MJPEG;
    fmt.width = 192;
    fmt.height = 1080;
    fmt.field = V4L2_FIELD_NONE;

    // Request four MMAP buffers
    ret = ioctl(fd, V4L2_G_MMAP, mmap_buf);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    if (ret != 4) {
        fprintf(stderr, "Unexpected number of MMAP buffers\n");
        close(fd);
        return 1;
    }

    // Start streaming
    ret = ioctl(fd, V4L2_STREAM_START, NULL);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Dequeue a single frame
    ret = ioctl(fd, V4L2_G_FMT, &fmt);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    ret = ioctl(fd, V4L2_G_MMAP, mmap_buf);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    ret = ioctl(fd, V4L2_G_BUFFER, &buf);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    if (buf.length < BUFFER_SIZE) {
        fprintf(stderr, "Not enough data in buffer\n");
        close(fd);
        return 1;
    }

    // Write the raw MJPEG bytes to a file
    FILE *file = fopen(FILE_NAME, "wb");
    if (file == NULL) {
        perror("fopen");
        close(fd);
        return 1;
    }
    fwrite(buf.buffer, buf.length, 1, file);
    fclose(file);

    // Stop streaming
    ret = ioctl(fd, V4L2_STREAM_STOP, NULL);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Unmap all buffers
    for (int i = 0; i < 4; i++) {
        ret = munmap(mmap_buf[i].start, mmap_buf[i].length);
        if (ret < 0) {
            perror("munmap");
            return 1;
        }
    }

    // Free the buffer array
    free(mmap_buf);

    // Close the file descriptor
    close(fd);

    return 0;
}

