#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"

int main() {
    int fd, ret;
    struct v4l2_frmsize_range frmsize_range;
    struct v4l2_frameinterval interval;
    struct v4l2_control control;
    struct v4l2_querycap querycap;
    struct v4l2_capability capability;
    char buffer[1024];

    // Open the CSI camera device node
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open video device");
        return 1;
    }

    // Check if the device node exists and can be opened
    if (ioctl(fd, VIDIOC_QUERYCAP, &querycap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return 1;
    }

    // Check if the device supports frame-size and interval enumeration
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize_range) < 0) {
        perror("VIDIOC_ENUM_FRAMESIZES");
        close(fd);
        return 1;
    }

    // Iterate over all supported frame sizes
    for (int i = 0; i < frmsize_range.count; i++) {
        // Get the current frame size
        struct v4l2_frmsize_range frmsize = frmsize_range.frmsizes[i];

        // Check if the frame size is supported
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &interval, frmsize) < 0) {
            perror("VIDIOC_ENUM_FRAMEINTERVALS");
            close(fd);
            return 1;
        }

        // Iterate over all frame intervals for the current frame size
        for (int j = 0; j < interval.count; j++) {
            // Get the current frame interval
            struct v4l2_frameinterval interval_val = interval.intervals[j];

            // Print the current resolution and frame rate
            printf("Resolution: %dx%d, Frame Rate: %d FPS\n", frmsize.width, frmsize.height, interval_val.framerate);

            // Check if autofocus is supported
            memset(&control, 0, sizeof(control));
            control.id = V4L2_CID_FOCUS_AUTO;
            ret = ioctl(fd, VIDIOC_QUERYCTRL, &control);
            if (ret < 0) {
                perror("VIDIOC_QUERYCTRL");
                close(fd);
                return 1;
            }

            if (control.capability & V4L2_CAP_AUTOFOCUS) {
                printf("Autofocus supported\n");
            } else {
                printf("Autofocus not supported\n");
            }
        }
    }

    // Close the device file
    close(fd);

    return 0;
}

