#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO_PAN 4
#define SERVO_TILT 5
#define BUTTON_UP 6
#define BUTTON_DOWN 7
#define BUTTON_LEFT 8
#define BUTTON_RIGHT 9

int main() {
    int pan, tilt, up, down, left, right;
    int pin;
    int err;
    int center = 1500;

    // Initialize the GPIO library
    if ((err = pi_init()) != 0) {
        fprintf(stderr, "Error initializing GPIO: %d\n", err);
        return 1;
    }

    // Set up the pin modes
    if ((err = pi_set_mode(SERVO_PAN, PI_OUTPUT) != 0) || (err = pi_set_mode(SERVO_TILT, PI_OUTPUT) != 0)) {
        fprintf(stderr, "Error setting pin modes: %d\n", err);
        pi_cleanup();
        return 1;
    }

    // Set the initial servo pulse widths
    if ((err = pi_servo(SERVO_PAN, center) != 0) || (err = pi_servo(SERVO_TILT, center) != 0)) {
        fprintf(stderr, "Error setting servo pulse widths: %d\n", err);
        pi_cleanup();
        return 1;
    }

    // Set up the button handlers
    if ((err = pi_set_active_low(BUTTON_UP, 1) != 0) || (err = pi_set_active_low(BUTTON_DOWN, 1) != 0) || (err = pi_set_active_low(BUTTON_LEFT, 1) != 0) || (err = pi_set_active_low(BUTTON_RIGHT, 1) != 0)) {
        fprintf(stderr, "Error setting button handlers: %d\n", err);
        pi_cleanup();
        return 1;
    }

    // Install the SIGINT/SIGTERM handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        // Read the button states
        up = pi_read(BUTTON_UP);
        down = pi_read(BUTTON_DOWN);
        left = pi_read(BUTTON_LEFT);
        right = pi_read(BUTTON_RIGHT);

        // Adjust the servo pulse widths based on the button states
        if (up == 0) {
            if (pi_servo(SERVO_PAN, center - 100) != 0) {
                fprintf(stderr, "Error adjusting servo pan: %d\n", err);
                pi_cleanup();
                return 1;
            }
            if (pi_servo(SERVO_TILT, center + 100) != 0) {
                fprintf(stderr, "Error adjusting servo tilt: %d\n", err);
                pi_cleanup();
                return 1;
            }
        } else if (down == 0) {
            if (pi_servo(SERVO_PAN, center + 100) != 0) {
                fprintf(stderr, "Error adjusting servo pan: %d\n", err);
                pi_cleanup();
                return 1;
            }
            if (pi_servo(SERVO_TILT, center - 100) != 0) {
                fprintf(stderr, "Error adjusting servo tilt: %d\n", err);
                pi_cleanup();
                return 1;
            }
        } else if (left == 0) {
            if (pi_servo(SERVO_PAN, center - 500) != 0) {
                fprintf(stderr, "Error adjusting servo pan: %d\n", err);
                pi_cleanup();
                return 1;
