#define GPIO_PIN 17
#define GPIO_MODE_INPUT
#define GPIO Pull_UP_DOWN
#define GPIO_INT_EDGE_FALLING
#define GPIO_INT_EDGE_RISING
#define HTTP_PORT 8080
#define HTTP_HOST "http://localhost"
#define JPEG_QUALITY 85
#define JSON_PATH "/home/pi/motion_captures"
#define JSON_FILE "motion_capture.json"

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return 1;
    }

    char *ip = argv[1];
    int port = atoi(argv[2]);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return 1;
    }

    int gpio = gpioInitialise();
    if (gpio < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        curl_easy_cleanup(curl);
        return 1;
    }

    if (gpioSetupMode(gpio, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    if (gpioCfgPin(gpio, GPIO_PIN, GPIO Pull_UP_DOWN) < 0) {
        fprintf(stderr, "Failed to configure GPIO pin\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    if (gpioSetEdge(gpio, GPIO_INT_EDGE_FALLING) < 0) {
        fprintf(stderr, "Failed to set GPIO edge\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    if (gpioRead(gpio) < 0) {
        fprintf(stderr, "Failed to read GPIO value\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    struct stat sb;
    if (stat(JSON_PATH, &sb) != 0) {
        mkdir(JSON_PATH, 0755);
    }

    char filename[256];
    sprintf(filename, "%s/%s", JSON_PATH, time(NULL));
    if (mkdir(filename, 0755) < 0) {
        fprintf(stderr, "Failed to create directory\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    char jpeg_path[256];
    sprintf(jpeg_path, "%s/%s.jpg", filename, time(NULL));
    if (system("raspistill -q %d -o %s", JPEG_QUALITY, jpeg_path) < 0) {
        fprintf(stderr, "Failed to capture JPEG image\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "Content-Disposition: attachment; filename=\"%s\"\r\n", jpeg_path);
    headers = curl_slist_append(headers, "Date: %s\r\n", time(NULL));
    headers = curl_slist_append(headers, "Motion: true\r\n");
    headers = curl_slist_append(headers, "GPIO: %d\r\n", GPIO_PIN);

    char *url = curl_easy_escape(curl, HTTP_HOST, port, HTTP_HOST);
    if (!url) {
        fprintf(stderr, "Failed to escape URL\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    char *json = curl_easy_escape(curl, JSON_FILE, strlen(JSON_FILE));
    if (!json) {
        fprintf(stderr, "Failed to escape JSON file path\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    char *data = curl_easy_escape(curl, json, strlen(json));
    if (!data) {
        fprintf(stderr, "Failed to escape JSON file path\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    char *payload = curl_easy_escape(curl, headers, strlen(headers));
    if (!payload) {
        fprintf(stderr, "Failed to escape headers\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    char *url_with_data = curl_easy_escape(curl, url, strlen(url));
    if (!url_with_data) {
        fprintf(stderr, "Failed to escape URL with data\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url_with_data);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);

    if (curl_easy_perform(curl) != 0) {
        fprintf(stderr, "Failed to upload JSON payload\n");
        gpioTerminate(gpio);
        curl_easy_cleanup(curl);
        return 1;
    }

    gpioTerminate(gpio);
    curl_easy_cleanup(curl);

    return 0;
}

static size_t write_memory_callback(void *ptr, size_t size, size_t nmemb, void *data) {
    fprintf(stderr, "%.*s", size * nmemb, (char *)ptr);
    return size * nmemb;
}

void cleanup() {
    curl_global_cleanup();
    gpioTerminate(gpio);
}

