#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <syslog.h>

#define GPIO17 17
#define DEBOUNCE_TIME 50
#define CAPTURE_TIMEOUT 2000
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_Q 85
#define CAPTURE_TIMEOUT_MS 2000
#define CAPTURE_FORMAT "jpg"
#define CAPTURE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

int main() {
    // Initialize GPIO
    int gpio = 0;
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Claim GPIO17 as input with edge-falling detection
    if (gpioSetupMode(GPIO17, PI_INPUT) < 0) {
        perror("gpioSetupMode");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for a falling edge on GPIO17
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = DEBOUNCE_TIME * 1000000;
        int result = gpioWaitEdge(GPIO17, PI_FALLING, &timeout);
        if (result < 0) {
            perror("gpioWaitEdge");
            continue;
        }

        // Capture image
        char filename[32];
        time_t now = time(NULL);
        strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%b.jpg", localtime(&now));
        char command[256];
        sprintf(command, "raspistill -o %s -w %d -h %d -q %d -t %d -n -p", CAPTURE_DIR, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_Q, CAPTURE_TIMEOUT_MS, filename);
        int ret = system(command);
        if (ret < 0) {
            fprintf(log_file, "%s: %s\n", filename, strerror(errno));
            continue;
        }

        // Log success
        fprintf(log_file, "%s: Image captured successfully\n", filename);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);
    return 0;
}

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    gpioTerminate();
    exit(0);
}

