#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define SERVO1_PIN 17
#define SERVO2_PIN 18
#define SERVO_MIN 0
#define SERVO_MAX 180
#define SERVO_STEP 5
#define SERVO_FREQ 50
#define DELAY 100

// Define signal handlers
void sigint_handler(int sig) {
    gpioStop(SERVO1_PIN);
    gpioStop(SERVO2_PIN);
    pigpio_close();
    exit(1);
}

void cleanup() {
    gpioStop(SERVO1_PIN);
    gpioStop(SERVO2_PIN);
    pigpio_close();
}

int main() {
    // Initialize the GPIO driver
    if (pigpio_init() < 0) {
        printf("Error initializing GPIO driver\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);

    // Initialize servos
    if (gpioSetup(SERVO1_PIN, PI_OUTPUT) < 0 || gpioSetup(SERVO2_PIN, PI_OUTPUT) < 0) {
        printf("Error initializing servos\n");
        cleanup();
        return 1;
    }

    // Set initial servo positions
    if (gpioWrite(SERVO1_PIN, SERVO_MIN) < 0 || gpioWrite(SERVO2_PIN, SERVO_MIN) < 0) {
        printf("Error setting servo positions\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        char c;
        if (read(0, &c, 1) != 1) {
            printf("Error reading from stdin\n");
            cleanup();
            return 1;
        }

        if (c == 'q') {
            break;
        }

        int pan = 0;
        int tilt = 0;

        if (c == 'A' || c == 'a') {
            pan += SERVO_STEP;
            if (pan > SERVO_MAX) {
                pan = SERVO_MAX;
            }
        } else if (c == 'D' || c == 'd') {
            pan -= SERVO_STEP;
            if (pan < SERVO_MIN) {
                pan = SERVO_MIN;
            }
        }

        if (c == 'W' || c == 'w') {
            tilt += SERVO_STEP;
            if (tilt > SERVO_MAX) {
                tilt = SERVO_MAX;
            }
        } else if (c == 'S' || c == 's') {
            tilt -= SERVO_STEP;
            if (tilt < SERVO_MIN) {
                tilt = SERVO_MIN;
            }
        }

        // Update servo positions
        if (gpioWrite(SERVO1_PIN, pan) < 0 || gpioWrite(SERVO2_PIN, tilt) < 0) {
            printf("Error updating servo positions\n");
            cleanup();
            return 1;
        }

        // Delay
        usleep(DELAY * 1000);
    }

    // Cleanup
    cleanup();

    return 0;
}

