int main() {
    // Initialize the GPIO driver
    if (pigpio_init() < 0) {
        printf("Error initializing GPIO driver\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);

    // Initialize servos
    if (gpioSetup(SERVO1_PIN, PI_OUTPUT) < 0 || gpioSetup(SERVO2_PIN, PI_OUTPUT) < 0) {
        printf("Error initializing servos\n");
        cleanup();
        return 1;
    }

