    if (gpioWrite(SERVO1_PIN, SERVO_MIN) < 0 || gpioWrite(SERVO2_PIN, SERVO_MIN) < 0) {
        printf("Error setting servo positions\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        char c;
        if (read(0, &c, 1) != 1) {
            printf("Error reading from stdin\n");
            cleanup();
            return 1;
        }

        if (c == 'q') {
            break;
        }

        int pan = 0;
        int tilt = 0;

        if (c == 'A' || c == 'a') {
            pan += SERVO_STEP;
            if (pan > SERVO_MAX) {
                pan = SERVO_MAX;
            }
        } else if (c == 'D' || c == 'd') {
            pan -= SERVO_STEP;
            if (pan < SERVO_MIN) {
                pan = SERVO_MIN;
            }
        }

        if (c == 'W' || c == 'w') {
            tilt += SERVO_STEP;
            if (tilt > SERVO_MAX) {
                tilt = SERVO_MAX;
            }
        } else if (c == 'S' || c == 's') {
            tilt -= SERVO_STEP;
            if (tilt < SERVO_MIN) {
                tilt = SERVO_MIN;
            }
        }

        // Update servo positions
        if (gpioWrite(SERVO1_PIN, pan) < 0 || gpioWrite(SERVO2_PIN, tilt) < 0) {
