#include <wiringPiI2C.h>
#include <time.h>
#include <syslog.h>

#define GPIO_PIN 17
#define I2C_ADDRESS 0x27
#define I2C Bus 1

// Structure to hold flow rate and total volume
typedef struct {
    double flow_rate;
    double total_volume;
} flow_data_t;

// Function to initialize GPIO pin
int init_gpio(void) {
    int gpio = wiringPiSetupGpio();
    if (gpio < 0) {
        perror("wiringPiSetupGpio");
        return -1;
    }
    if (wiringPiIOPinMode(gpio, INPUT) < 0) {
        perror("wiringPiIOPinMode");
        return -1;
    }
    return gpio;
}

// Function to read pulse width from GPIO pin
double read_pulse_width(int gpio, int timeout) {
    struct timespec start, end;
    double pulse_width = 0.0;
    int fd = wiringPiIOPinRead(gpio);
    if (fd < 0) {
        perror("wiringPiIOPinRead");
        return -1.0;
