// Function to initialize GPIO pin as output
void init_gpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
    if (gpioMode(GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    gpioPullUpDn(GPIO_PIN, GPIO_PUD_OFF);
}

// Function to set up I2C bus
void init_i2c() {
    int fd = wiringPiI2CSetup(1);
    if (fd < 0) {
        perror("wiringPiI2CSetup");
        exit(1);
    }
}

// Function to write to LCD
void write_lcd(char *str) {
    int fd = wiringPiI2CSetup(1);
    if (fd < 0) {
        perror("wiringPiI2CSetup");
        exit(1);
    }
    char buffer[20];
    sprintf(buffer, "%s", str);
    if (wiringPiI2CWrite(fd, LCD_ADDRESS, LCD_DATA, buffer, strlen(buffer)) < 0) {
        perror("wiringPiI2CWrite");
        exit(1);
    }
    wiringPiI2CWrite(fd, LCD_ADDRESS, LCD_EN, 0x00);
    usleep(1000);
    wiringPiI2CWrite(fd, LCD_ADDRESS, LCD_EN, 0x01);
    usleep(1000);
    wiringPiI2CWrite(fd, LCD_ADDRESS, LCD_EN, 0x00);
}

// Function to measure water flow rate
void measure_flow_rate() {
    int fd = wiringPiI2CSetup(1);
    if (fd < 0) {
        perror("wiringPiI2CSetup");
        exit(1);
    }
    int pulses = 0;
    int prev_time = 0;
    int interval = 1000; // 1 second interval
    while (1) {
        int current_time = time(NULL);
        if (current_time - prev_time >= interval) {
            pulses = wiringPiI2CRead(fd, LCD_ADDRESS, LCD_DATA);
            if (pulses == 0) {
                // No pulses detected, wait for 1 second
                usleep(1000000);
                continue;
            }
            double flow_rate = (double)pulses / interval * 3.6; // 3.6 cm^3 per pulse
            char buffer[20];
            sprintf(buffer, "Flow Rate: %.2f L/min", flow_rate);
            write_lcd(buffer);
            prev_time = current_time;
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa);
    sigaddset(&sa, SIGINT);
    sigaddset(&sa, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    init_gpio();
    init_i2c();
    measure_flow_rate();
    return 0;
}

