#include <pigpio.h>

#define GPIO_BASE 17
#define GPIO_BASE2 5
#define ROWS 8
#define COLS 8
#define DELAY 800

int main(int argc, char **argv) {
    int gpio_fd[ROWS];
    int gpio_fd2[COLS];
    int i, j;
    struct termios oldt, newt;
    struct sigaction sa;
    int ret;

    // Initialize GPIO
    if ((ret = pigpio_init()) != 0) {
        fprintf(stderr, "pigpio_init() failed: %d\n", ret);
        return 1;
    }

    // Set up GPIO pins
    for (i = 0; i < ROWS; i++) {
        gpio_fd[i] = pigpio_get_input(GPIO_BASE + i);
        if (gpio_fd[i] == -1) {
            fprintf(stderr, "pigpio_get_input() failed for row %d\n", i);
            return 1;
        }
        pigpio_set_mode(GPIO_BASE + i, PI_INPUT);
    }
    for (i = 0; i < COLS; i++) {
        gpio_fd2[i] = pigpio_get_input(GPIO_BASE2 + i);
        if (gpio_fd2[i] == -1) {
            fprintf(stderr, "pigpio_get_input() failed for column %d\n", i);
            return 1;
        }
        pigpio_set_mode(GPIO_BASE2 + i, PI_INPUT);
    }

    // Set up terminal
    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);

    // Set up signal handler
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction() failed\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Clear LEDs
        for (i = 0; i < ROWS; i++) {
            pigpio_write(GPIO_BASE + i, 0);
        }
        for (i = 0; i < COLS; i++) {
            pigpio_write(GPIO_BASE2 + i, 0);
        }

        // Draw wave-like animation
        for (i = 0; i < ROWS; i++) {
            for (j = 0; j < COLS; j++) {
                if (i == 0) {
                    pigpio_write(GPIO_BASE + i, 1);
                } else {
                    pigpio_write(GPIO_BASE + i, 0);
                }
                if (j == 0) {
                    pigpio_write(GPIO_BASE2 + j, 1);
                } else {
                    pigpio_write(GPIO_BASE2 + j, 0);
                }
                usleep(DELAY);
            }
            pigpio_write(GPIO_BASE + i, 0);
            pigpio_write(GPIO_BASE2 + j, 0);
            usleep(DELAY);
        }

        for (i = 0; i < ROWS; i++) {
            for (j = COLS - 1; j >= 0; j--) {
                if (i == 0) {
                    pigpio_write(GPIO_BASE + i, 1);
                } else {
                    pigpio_write(GPIO_BASE + i, 0);
                }
                if (j == COLS - 1) {
                    pigpio_write(GPIO_BASE2 + j, 1);
                } else {
                    pigpio_write(GPIO_BASE2 + j, 0);
                }
                usleep(DELAY);
            }
            pigpio_write(GPIO_BASE + i, 0);
            pigpio_write(GPIO_BASE2 + j, 0);
            usleep(DELAY);
        }
    }

    // Cleanup
    for (i = 0; i < ROWS; i++) {
        pigpio_close(gpio_fd[i]);
    }
    for (i = 0; i < COLS; i++) {
        pigpio_close(gpio_fd2[i]);
    }
    pigpio_close(GPIO_BASE);
    pigpio_close(GPIO_BASE2);
    pigpio_cleanup();
    return 0;
