#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ROWS 8
#define COLS 8
#define DELAY 150

// Define GPIO pin numbers
#define ROW_ANODES {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_CATHODES {14, 15, 18, 23, 24, 25, 8, 7}

// Define GPIO mode and pin configuration
#define GPIO_MODE_OUTPUT
#define GPIO_FLOATING

// Define signal handlers
void sigint_handler(int sig) {
    gpioCleanse();
    exit(0);
}

void sigterm_handler(int sig) {
    gpioCleanse();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up GPIO pins
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            gpioSetMode(ROW_ANODES[i], GPIO_FLOATING);
            gpioSetLevel(ROW_ANODES[i], 0);
        }
        for (int j = 0; j < COLS; j++) {
            gpioSetMode(COL_CATHODES[j], GPIO_FLOATING);
            gpioSetLevel(COL_CATHODES[j], 1);
        }
    }

    while (1) {
        // Clear columns
        for (int j = 0; j < COLS; j++) {
            gpioSetLevel(COL_CATHODES[j], 0);
            for (int i = 0; i < ROWS; i++) {
                gpioSetLevel(ROW_ANODES[i], 0);
            }
            usleep(DELAY * 1000);
        }

        // Light columns
        for (int j = 0; j < COLS; j++) {
            gpioSetLevel(COL_CATHODES[j], 0);
            for (int i = 0; i < ROWS; i++) {
                gpioSetLevel(ROW_ANODES[i], 1);
            }
            usleep(DELAY * 1000);
        }
    }

    // Clean up GPIO
    gpioCleanse();
    gpioTerminate();
    return 0;
}
```

This code uses the `pigpio` library to control the GPIO pins on the Raspberry Pi. It initializes the GPIO, sets up signal handlers for SIGINT and SIGTERM, sets up the GPIO pins, and then enters an infinite loop where it clears the columns, lights the columns, and waits for a delay before repeating. The `gpioCleanse` function is used to clean up the GPIO pins when the program exits.

