code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x5A
#define I2C Bus 1
#define FILE_NAME "depth_log.csv"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if (gpioSetMode(I2C Bus, PI_MODE PullUp) < 0) {
        perror("gpioSetMode");
        return 1;
    }

    // Set up I2C clock
    if (gpioSetClock(I2C Bus, 400000) < 0) {
        perror("gpioSetClock");
        return 1;
    }

    // Open I2C handle
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Open log file
    int log_fd = open(FILE_NAME, O_RDWR | O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Check if file exists and create header row
    struct stat sb;
    if (fstat(log_fd, &sb) < 0) {
        perror("fstat");
        return 1;
    }
    if (sb.st_size == 0) {
        fprintf(log_fd, "timestamp,distance\n");
        fflush(log_fd);
    }

    // Main loop
    while (1) {
        // Read distance
        uint16_t distance = 0;
        if (read(fd, &distance, sizeof(distance)) < sizeof(distance)) {
            printf("read failed\n");
            continue;
        }

        // Convert distance to meters
        distance /= 1000;

        // Write to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%f\n", timestamp, distance);
        fflush(log_fd);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(log_fd);
    close(fd);
    gpioTerminate();
    return 0;
}

