#include <errno.h>

#define I2C_ADDRESS 0x4E
#define I2C_TIMEOUT 100
#define FILE_NAME "biometric_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C handle
    int i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        gpioTerminate();
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read sensor data
        unsigned char data[3];
        if (pigpio_i2c_read(i2c_fd, data, 3, I2C_TIMEOUT) < 0) {
            perror("pigpio_i2c_read");
            continue;
        }

        // Check sensor data
        if (data[0] == 0x00) {
            fprintf(stderr, "Sensor not found or initialization failed\n");
            pigpio_i2c_close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Append to log file
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s %d %d %d\n", timestamp, data[0], data[1], data[2]);
        fflush(log_fd);

        // Sleep for 500ms
        sleep(0.5);
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    gpioTerminate();
    close(log_fd);
    return 0;
}

void sigint_handler(int sig) {
    pigpio_i2c_close(1);
    close(FILE_NAME);
    exit(0);
}

