        return 1;
    }

    // Open GPIO chip
    if (gpiochip_open(&gpio, NULL) < 0) {
        printf("gpiochip_open() failed: %s\n", strerror(errno));
        pigpio_close(gpio);
        return 1;
    }

    // Set up GPIO pin 4 as input with pull-up resistor
    if (gpio_mode(GPIO_PIN_BCM, GPIO_IN_PUD_UP) < 0) {
        printf("gpio_mode() failed: %s\n", strerror(errno));
        gpiochip_close(gpio);
        pigpio_close(gpio);
        return 1;
    }

    // Set up GPIO pin 17 as output
    if (gpio_mode(GPIO_PIN_BCM_LED, GPIO_MODE_OUTPUT) < 0) {
        printf("gpio_mode() failed: %s\n", strerror(errno));
        gpiochip_close(gpio);
        pigpio_close(gpio);
        return 1;
    }

    // Set initial state of GPIO pin 17 to LOW
    if (gpio_write(GPIO_PIN_BCM_LED, 0) < 0) {
        printf("gpio_write() failed: %s\n", strerror(errno));
        gpiochip_close(gpio);
        pigpio_close(gpio);
        return 1;
    }

    // Open file for writing
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        printf("open() failed: %s\n", strerror(errno));
        gpiochip_close(gpio);
        pigpio_close(gpio);
        return 1;
    }

    // Main loop
    while (1) {
        // Read GPIO pin 4
        int value = gpio_read(GPIO_PIN_BCM);
        if (value == 0) {
            // Object detected, write to file and blink LED
            time_t now = time(NULL);
            struct tm *timeinfo;
            timeinfo = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            char log_message[128];
            sprintf(log_message, "%s Object detected", timestamp);
            write(fd, log_message, strlen(log_message));
            gpio_write(GPIO_PIN_BCM_LED, 1);
            usleep(100000);
            gpio_write(GPIO_PIN_BCM_LED, 0);
        }
        usleep(100000);
    }

    // Close file and GPIO chip
    close(fd);
    gpiochip_close(gpio);
    pigpio_close(gpio);

    return 0;
}

