#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>

#define I2C_ADDRESS 0x54
#define I2C Bus 1

// Structure to hold sensor data
typedef struct {
    uint16_t proximity;
    uint16_t ambient_light;
} sensor_data_t;

// Function to initialize the sensor
int init_sensor(pigpio_t *gpio, int i2c_fd) {
    if (gpio->i2c_open(i2c_fd, I2C_ADDRESS, 1000) != 0) {
        return -1;
    }
    if (gpio->i2c_write(i2c_fd, 0x00, 1) != 0) {
        gpio->i2c_close(i2c_fd);
        return -1;
    }
    if (gpio->i2c_write(i2c_fd, 0x01, 1) != 0) {
        gpio->i2c_close(i2c_fd);
        return -1;
    }
    if (gpio->i2c_read(i2c_fd, 0x02, sizeof(sensor_data_t), (void *)&sensor_data) != 0) {
        gpio->i2c_close(i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor(pigpio_t *gpio, int i2c_fd) {
    if (gpio->i2c_read(i2c_fd, 0x02, sizeof(sensor_data_t), (void *)&sensor_data) != 0) {
        return -1;
    }
    return 0;
}

// Function to log sensor data
void log_data(sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_fd, "%s,%d,%d\n", timestamp, data->proximity, data->ambient_light);
    fflush(log_fd);
}

int main() {
    pigpio_t *gpio;
    int i2c_fd;
    int ret;
    sensor_data_t sensor_data;
    FILE *log_fd;

    // Initialize GPIO and I2C
    gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C bus
    i2c_fd = gpio->i2c_open(I2C Bus, 1000);
    if (i2c_fd == -1) {
        perror("i2c_open");
        pigpio_close(gpio);
        return 1;
    }

    // Initialize sensor
    ret = init_sensor(gpio, i2c_fd);
    if (ret != 0) {
        perror("init_sensor");
        pigpio_close(gpio);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fd = fopen("biometric_data.log", "a");
    if (log_fd == NULL) {
        perror("fopen");
        pigpio_close(gpio);
        close(i2c_fd);
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        pigpio_close(gpio);
        close(i2c_fd);
        fclose(log_fd);
        return 1;
    }

    while (1) {
        // Read sensor data
        ret = read_sensor(gpio, i2c_fd);
        if (ret != 0) {
            perror("read_sensor");
            break;
        }

        // Log data
        log_data(&sensor_data);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C and log file
    close(i2c_fd);
    fclose(log_fd);

    // Clean up sensor
    ret = gpio->i2c_write(i2c_fd, 0x01, 1);
    if (ret != 0) {
        perror("i2c_write");
    }
    ret = gpio->i2c_write(i2c_fd, 0x00, 1);
    if (ret != 0) {
        perror("i2c_write");
    }
    ret = gpio->i2c_close(i2c_fd);
    if (ret != 0) {
        perror("i2c_close");
    }

    // Clean up GPIO
    pigpio_close(gpio);

    // Call sensor's API call for cleanup
    ret = sensor_api_call();
    if (ret != 0) {
        perror("sensor_api_call");
    }

    return 0;
}

