#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define VOLTAGE_DIVIDER 1000
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define LOG_FILE "distance_log.txt"
#define LOG_INTERVAL 60

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Create log file
    if (access(LOG_FILE, F_OK) == -1) {
        if (mkdir(LOG_FILE, 0755) < 0) {
            perror("mkdir");
            gpioTerminate();
            return 1;
        }
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up voltage divider
    int voltage_divider_fd = open("/sys/class/gpio/gpio17/value", O_RDWR);
    if (voltage_divider_fd < 0) {
        perror("open");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (write(voltage_divider_fd, &VOLTAGE_DIVIDER, sizeof(VOLTAGE_DIVIDER)) < 0) {
        perror("write");
        close(voltage_divider_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    close(voltage_divider_fd);

    // Main loop
    while (1) {
        // Trigger pulse
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        // Wait for echo rise
        struct timespec start_time;
        struct timespec end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);
