            if (echo_value == 1) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                double echo_duration = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
                double distance = (echo_duration * 34300) / 2;
                if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
