#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x6A
#define I2C Bus 1
#define PROXIMITY_THRESHOLD 200
#define CSV_FILE "color_proximity_log.csv"

int main() {
    // Initialize the GPIO library
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Initialize the I2C library
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        gpio_uninit();
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpiod_exit();
        return 1;
    }

    // Set the I2C bus parameters
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Initialize the APDS9960 sensor
    if (gpiod_device_open(&gpiod_device, &gpiod_device_handle, NULL) < 0) {
        perror("gpiod_device_open");
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Set the sensor to read proximity and color data
    if (gpiod_device_set_property(&gpiod_device, "apds9960.proximity", &gpiod_value_bool, NULL, NULL, 1) < 0) {
        perror("gpiod_device_set_property");
        gpiod_device_close(&gpiod_device);
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }
    if (gpiod_device_set_property(&gpiod_device, "apds9960.color", &gpiod_value_bool, NULL, NULL, 1) < 0) {
        perror("gpiod_device_set_property");
        gpiod_device_close(&gpiod_device);
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Open the CSV file
    FILE *file = fopen(CSV_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        gpiod_device_close(&gpiod_device);
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Set the I2C timeout
    if (ioctl(i2c_fd, I2C_SET_TIMEOUT, 100) < 0) {
        perror("ioctl");
        fclose(file);
        gpiod_device_close(&gpiod_device);
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the proximity and color data
        gpiod_value_t value;
        if (gpiod_device_get_value(&gpiod_device, &value) < 0) {
            perror("gpiod_device_get_value");
            gpiod_device_close(&gpiod_device);
            close(i2c_fd);
            gpiod_exit();
            return 1;
        }

        // Check if the proximity reading exceeds the threshold
        if (value.proximity > PROXIMITY_THRESHOLD) {
            // Append the data to the CSV file
            fprintf(file, "%d,%d,%d,%d\n", (int)time(NULL), value.red, value.green, value.blue);
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    // Close the CSV file
    fclose(file);

    // Finalize the CSV file
    if (flock(file, LOCK_EX | LOCK_NB) == -1) {
        perror("flock");
        return 1;
    }

    // Close the CSV file
    fclose(file);

    // Release the lock
    flock(file, LOCK_UN);

    // Close the GPIO library
    gpio_uninit();

    // Exit
    return 0;
}

