#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x29
#define GPIO_PIN 17
#define I2C_TIMEOUT 100
#define LOG_FILE "distance_log.txt"

int main() {
    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() == -1) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Check if I2C bus is available
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin
    if (gpioMode(GPIO_PIN, GPIO_MODE_INPUT) == -1) {
        perror("gpioMode");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioPullUpDn(GPIO_PIN, PUD_UP) == -1) {
        perror("gpioPullUpDn");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Wait for falling edge
    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);
    while (1) {
        int status = gpioRead(GPIO_PIN);
        if (status == 0) {
            // Trigger distance measurement
            if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
                perror("ioctl");
                close(fd);
                gpioTerminate();
                return 1;
            }
            if (ioctl(fd, VL53L0X_I2C_READ_RESULT_INTERRUPT_STATUS, NULL) == -1) {
                perror("ioctl");
                close(fd);
                gpioTerminate();
                return 1;
            }
            struct timespec end_time;
            clock_gettime(CLOCK_REALTIME, &end_time);
            double delay = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
            if (delay > I2C_TIMEOUT) {
                continue;
            }
            int result = ioctl(fd, VL53L0X_I2C_READ_RESULT, NULL);
            if (result == -1) {
                perror("ioctl");
                close(fd);
                gpioTerminate();
                return 1;
            }
            int distance = (result >> 16) & 0xFF;
            printf("%f,%d\n", (double)start_time.tv_sec + (double)start_time.tv_nsec / 1e9, distance);
            // Flush and close log file
            if (flock(fd, LOCK_EX | LOCK_NB) == -1) {
                perror("flock");
                close(fd);
                gpioTerminate();
                return 1;
            }
            if (ftruncate(fd, 0) == -1) {
                perror("ftruncate");
                flock(fd, UNLOCK);
                close(fd);
                gpioTerminate();
                return 1;
            }
            if (close(fd) == -1) {
                perror("close");
                flock(fd, UNLOCK);
                gpioTerminate();
                return 1;
            }
            // Release I2C handle
            if (ioctl(fd, I2C_SLAVE, 0) == -1) {
                perror("ioctl");
                return 1;
            }
            break;
        }
        usleep(100000);
    }

    // Flush and close log file
    if (flock(fd, LOCK_EX | LOCK_NB) == -1) {
        perror("flock");
        return 1;
    }
    if (ftruncate(fd, 0) == -1) {
        perror("ftruncate");
        flock(fd, UNLOCK);
        return 1;
    }
    if (close(fd) == -1) {
        perror("close");
        flock(fd, UNLOCK);
        return 1;
    }
    flock(fd, UNLOCK);

    // Release GPIO pin
    if (gpioMode(GPIO_PIN, GPIO_MODE_INPUT) == -1) {
        perror("gpioMode");
        return 1;
    }
    if (gpioPullUpDn(GPIO_PIN, PUD_DN) == -1) {
        perror("gpioPullUpDn");
        return 1;
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

