#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define BUFFER_SIZE 10
#define I2C_ADDRESS 0x38
#define I2C Bus 1
#define SAMPLE_INTERVAL 200
#define WAIT_TIME 50
#define LOG_FILE "distance_log.txt"

int main(int argc, char **argv) {
    int i, j;
    int fd;
    int ret;
    int i2c_fd;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec time_diff;
    char timestamp[BUFFER_SIZE];
    char log_line[BUFFER_SIZE * 2 + 10];
    char buffer[BUFFER_SIZE];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    if ((fd = open(LOG_FILE, O_RDWR | O_CREAT | O_WRONLY, 0644)) < 0) {
        perror("open");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(i2c_fd);
        close(fd);
        return 1;
    }

    // Initialize timestamp
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        // Wait for signal
        if (kill(0, SIGINT) == 0) {
            break;
        }

        // Trigger sensor
        if (ioctl(i2c_fd, I2C_WRITE, (void *) &I2C_ADDRESS) < 0) {
            perror("ioctl");
            continue;
        }

        // Wait for sensor to stabilize
        usleep(WAIT_TIME * 1000);

        // Read sensor
        if (ioctl(i2c_fd, I2C_READ, (void *) &I2C_ADDRESS) < 0) {
            perror("ioctl");
            continue;
        }

        // Read distance
        ret = read(i2c_fd, buffer, BUFFER_SIZE);
        if (ret < 0) {
            perror("read");
            continue;
        }

        // Convert distance to millimeters
        int distance = (buffer[0] << 8) | buffer[1];

        // Calculate time difference
        clock_gettime(CLOCK_REALTIME, &end_time);
        time_diff.tv_sec = end_time.tv_sec - start_time.tv_sec;
        time_diff.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;
        time_diff.tv_nsec += (time_diff.tv_sec * 1000000000);

        // Format timestamp
        strftime(timestamp, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", localtime(&start_time));

        // Format log line
        sprintf(log_line, "%s, %d", timestamp, distance);

        // Write to log file
        if (write(fd, log_line, strlen(log_line)) < 0) {
            perror("write");
            continue;
        }

        // Print to stdout
        printf("%s\n", log_line);

        // Update start time
        start_time = end_time;
    }

    // Close I2C handle
    close(i2c_fd);

    // Close log file
    close(fd);

    // Shutdown GPIO
    gpioCleanUp();

    return 0;
}

