#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO17 17
#define GPIO18 18
#define LOG_FILE "obstacle_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file for writing
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetup(GPIO17, GPIO_MODE_INPUT) < 0) {
        perror("gpioSetup");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetup(GPIO18, GPIO_MODE_INPUT) < 0) {
        perror("gpioSetup");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistors
    if (gpioPullUpDowntime(GPIO17, GPIO_FLOATING) < 0) {
        perror("gpioPullUpDowntime");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioPullUpDowntime(GPIO18, GPIO_FLOATING) < 0) {
        perror("gpioPullUpDowntime");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read sensor values
        int sensor1 = gpioGet(GPIO17);
        int sensor2 = gpioGet(GPIO18);

        // Log sensor values
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s %d %d\n", timestamp, sensor1, sensor2);

        // Wait 100ms
        usleep(100000);
    }

    // Clean up
    close(log_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    // Release resources
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    close(log_fd);

    // Terminate pigpio
    gpioTerminate();

    // Exit
    exit(0);
}

