#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>

#define I2C_ADDRESS 0x1E
#define I2C Bus 1
#define FILE_NAME "biometric_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the log file
    int log_fd = open(FILE_NAME, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Map the log file
    struct stat sb;
    if (fstat(log_fd, &sb) < 0) {
        perror("fstat");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    void* log_ptr = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, log_fd, 0);
    if (log_ptr == MAP_FAILED) {
        perror("mmap");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (i2c_init(I2C Bus, I2C_ADDRESS) < 0) {
        perror("i2c_init");
        close(log_fd);
        munmap(log_ptr, sb.st_size);
        gpioTerminate();
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(log_fd);
        munmap(log_ptr, sb.st_size);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read proximity and ambient light data
        int ret = i2c_read(I2C Bus, I2C_ADDRESS, 0x00, 2, NULL, 0);
        if (ret < 0) {
            if (ret == -EBUSY) {
                // Sensor is busy, wait and retry
                usleep(100000);
                ret = i2c_read(I2C Bus, I2C_ADDRESS, 0x00, 2, NULL, 0);
                if (ret < 0) {
                    perror("i2c_read");
                    break;
                }
            } else {
                perror("i2c_read");
                break;
            }
        }

        // Unpack data
        uint16_t proximity = (ret >> 8) & 0xFF;
        uint16_t ambient_light = ret & 0xFF;

        // Append to log file
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        char log_str[64];
        sprintf(log_str, "%s %d %d\n", timestamp, proximity, ambient_light);
        write(log_ptr, log_str, strlen(log_str));

        // Wait 500ms
        usleep(500000);
    }

    // Clean up
    close(log_fd);
