        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (i2c_init(I2C Bus, I2C_ADDRESS) < 0) {
        perror("i2c_init");
        close(log_fd);
        munmap(log_ptr, sb.st_size);
        gpioTerminate();
