#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x34
#define GPIO_PIN 17
#define LOG_FILE "tof_log.txt"

int main(int argc, char *argv[]) {
    int i2c_fd = -1;
    int gpio_fd = -1;
    int threshold = 100;
    struct timespec last_read_time;
    struct timespec sleep_time;
    struct timespec sleep_interval;
    bool initialized = false;
    bool error = false;

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set up GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    // Open I2C device
    i2c_fd = i2cOpen(I2C_ADDRESS, 0, 100);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        error = true;
    }

    // Check WHO_AM_I register
    uint8_t whoami;
    if (i2cRead(i2c_fd, &whoami, 1) < 0) {
        perror("i2cRead");
        error = true;
    }
    if (whoami != 0x55) {
        fprintf(stderr, "Invalid WHO_AM_I register value\n");
        error = true;
    }

    // Set up logging
    if (!error) {
        if (access(LOG_FILE, F_OK) == -1) {
            mkdir(LOG_FILE, 0777);
        }
        if (access(LOG_FILE, F_OK) == -1) {
            perror("mkdir");
            error = true;
        }
        if (access(LOG_FILE, W_OK) == -1) {
            perror("access");
            error = true;
        }
    }

    while (true) {
        // Read distance measurement
        uint16_t distance;
        if (i2cRead(i2c_fd, &distance, 2) < 0) {
            perror("i2cRead");
            error = true;
        }

        // Check if distance is below threshold
        if (distance < threshold) {
            // Log reading
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                error = true;
            } else {
                fprintf(log_file, "%s %d\n", timestamp, distance);
                fclose(log_file);
            }

            // Light LED
            gpioWrite(GPIO_PIN, 1);
        } else {
            // Turn off LED
            gpioWrite(GPIO_PIN, 0);
        }

        // Sleep for 50ms
        clock_gettime(CLOCK_MONOTONIC, &last_read_time);
        sleep_time.tv_sec = last_read_time.tv_sec + 50;
        sleep_time.tv_nsec = last_read_time.tv_nsec + 500000;
        if (nanosleep(&sleep_time, NULL) < 0) {
            perror("nanosleep");
            error = true;
        }

        // Check for SIGINT
        if (killpg(0, SIGINT) == -1) {
            perror("killpg");
            error = true;
        }
    }

    // Clean up
    if (!error) {
        if (i2cClose(i2c_fd) < 0) {
            perror("i2cClose");
        }
        if (gpioClose(gpio_fd) < 0) {
            perror("gpioClose");
        }
        if (gpioReset(gpio_fd) < 0) {
            perror("gpioReset");
        }
    }

    return 0;
}

