#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x50
#define COMMAND_FRAME 0x01
#define HEADER 0x00
#define DISTANCE_BYTES 2
#define DISTANCE_OFFSET 11
#define DISTANCE_SIZE 2
#define LOG_FILE "intrusion_log.txt"

void sigint_handler(int sig) {
    close(i2c_fd);
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(0);
}

int main() {
    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C file descriptor
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C file descriptor");
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C clock speed");
        return 1;
    }

    // Send command frame
    if (write(i2c_fd, &COMMAND_FRAME, 1) < 1) {
        perror("Failed to send command frame");
        return 1;
    }

    // Wait for 10ms
    usleep(10000);

    // Read response
    if (read(i2c_fd, response, 15) < 15) {
        perror("Failed to read response");
        return 1;
    }

    // Verify header
    if (response[0] != HEADER) {
        printf("Invalid header\n");
        return 1;
    }

    // Extract distance
    uint16_t distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
    distance >>= 1; // Divide by 2 to get 16-bit big-endian distance

    // Initialize log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize average distance
    double average_distance = 0.0;

    // Sample sensor ten times
    for (int i = 0; i < 10; i++) {
        // Send command frame
        if (write(i2c_fd, &COMMAND_FRAME, 1) < 1) {
            perror("Failed to send command frame");
            return 1;
        }

        // Wait for 100ms
        usleep(100000);

        // Read response
        if (read(i2c_fd, response, 15) < 15) {
            perror("Failed to read response");
            return 1;
        }

        // Verify header
        if (response[0] != HEADER) {
            printf("Invalid header\n");
            return 1;
        }

        // Extract distance
        uint16_t distance_sample = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
        distance_sample >>= 1; // Divide by 2 to get 16-bit big-endian distance

        // Update average distance
        average_distance += distance_sample;
    }

    // Calculate average distance
    average_distance /= 10;

    // Log average distance
    if (average_distance < 1000) {
        fprintf(log_fd, "%d %f\n", (int)time(NULL), average_distance);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    // Close log file
    if (log_fd >= 0) {
        close(log_fd);
    }

    return 0;
}

