#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>
#include <sys/times.h>

#define I2C_ADDRESS 0x29
#define I2C_TIMEOUT 100
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define RESULT_INTERRUPT_STATUS 0x00
#define RESULT_DISTANCE 0x01

int main() {
    int i, j;
    struct timespec start;
    struct timespec end;
    struct tms tms_before, tms_after;
    struct sigaction sa;
    int i2c_fd;
    int ret;
    char buffer[3];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize I2C
    if ((i2c_fd = i2cOpen(I2C_ADDRESS, I2C_TIMEOUT)) < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    ret = i2cWrite(i2c_fd, RESULT_INTERRUPT_STATUS, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Error writing to sensor\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    ret = i2cRead(i2c_fd, buffer, 3);
    if (ret < 0) {
        fprintf(stderr, "Error reading from sensor\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (strcmp(buffer, "VL53L0X") != 0) {
        fprintf(stderr, "Sensor model ID mismatch\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Start timer
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Main loop
    while (1) {
        // Check for SIGINT and SIGTERM
        sa.sa_handler = SIG_IGN;
        sigemptyset(&sa);
        sigaddset(&sa, SIGINT);
        sigaddset(&sa, SIGTERM);
        if (sigaction(SIGINT, &sa, NULL) < 0) {
            perror("sigaction");
            continue;
        }
        if (sigaction(SIGTERM, &sa, NULL) < 0) {
            perror("sigaction");
            continue;
        }

        // Poll sensor
        ret = i2cRead(i2c_fd, buffer, 3);
        if (ret < 0) {
            fprintf(stderr, "Error reading from sensor\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (buffer[0] != RESULT_INTERRUPT_STATUS) {
            fprintf(stderr, "Sensor interrupt status mismatch\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Read distance
        ret = i2cRead(i2c_fd, buffer, 3);
        if (ret < 0) {
            fprintf(stderr, "Error reading from sensor\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (buffer[1] != RESULT_DISTANCE) {
            fprintf(stderr, "Sensor distance register mismatch\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        ret = i2cRead(i2c_fd, buffer, 4);
        if (ret < 0) {
            fprintf(stderr, "Error reading from sensor\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        int distance = (buffer[2] << 8) | buffer[3];
        printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
               (int)time(NULL) / 1000, (int)(start.tv_sec % 100), (int)(start.tv_nsec / 1000000),
               (int)(time(NULL) / 1000) % 100, (int)(time(NULL) / 1000) % 100, (int)(time(NULL) / 1000) % 100, distance);

        // Sleep for 500ms
        nanosleep(&start, &end);
    }

    // Cleanup
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

