void i2c_callback(pigpio_i2c_event_t event, void *user_data) {
    if (event == pigpio_i2c_event_start) {
        printf("I2C start\n");
    } else if (event == pigpio_i2c_event_stop) {
        printf("I2C stop\n");
    } else if (event == pigpio_i2c_event_read) {
        printf("I2C read\n");
    } else if (event == pigpio_i2c_event_write) {
        printf("I2C write\n");
    }
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up the I2C pins
    if (gpioSetupGPIO(1, GPIO_MODE_IN, GPIO pull_up_down) < 0) {
        perror("gpioSetupGPIO");
        return 1;
    }

    // Set up the I2C handle
    pigpio_i2c_t i2c;
    if (pigpio_i2c_init(&i2c, GPIO_SDA, GPIO_SCL, I2C_MODE, I2C_SPEED, i2c_callback) < 0) {
        perror("pigpio_i2c_init");
        return 1;
    }

    // Check if the sensor is present
    if (pigpio_i2c_write(&i2c, I2C_ADDRESS, 0x00, 1) < 0) {
        if (pigpio_i2c_get_error(&i2c) == pigpio_i2c_error_nack) {
            printf("Sensor not found\n");
        } else {
            perror("pigpio_i2c_write");
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Read the 16-bit proximity data
        uint16_t data;
        if (pigpio_i2c_read(&i2c, I2C_ADDRESS, 0x00, 2, &data) < 0) {
            perror("pigpio_i2c_read");
            return 1;
        }

        // Log the data
        printf("Proximity: %d\n", data);

        // Sleep for 500ms
        sleep(0.5);
    }

    // Clean up
    pigpio_i2c_close(&i2c);
    gpioCleanUpGPIO(1);
    gpioTerminate();

    return 0;
}

