#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_ADDRESS 0x5A
#define I2C_SLAVE 1

int main() {
    int fd;
    int ret;
    unsigned char buf[2];
    struct sigaction sa;

    // Install SIGINT and SIGTERM handler
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_SLAVE);
    if (ret == -1) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Check if device is present
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret == -1) {
        fprintf(stderr, "MLX75030 Time-of-Flight sensor not found\n");
        close(fd);
        return 1;
    }

    while (1) {
        // Read distance measurement
        ret = read(fd, buf, 2);
        if (ret == -1) {
            perror("read");
            continue;
        }

        // Check if read failed
        if (ret != 2) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Convert distance measurement to millimeters
        int distance = (buf[0] << 8) | buf[1];

        // Print distance
        printf("Distance: %d mm\n", distance);

        // Sleep for 500ms
        nanosleep((const struct timespec[]){{0, 500000}}, NULL);
    }

    close(fd);
    return 0;
}

