#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define I2C_ADDRESS 0x1A
#define I2C_CHANNEL 0
#define I2C_TIMEOUT 100
#define I2C_BUFFER_SIZE 2

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus 1
    int fd = pigpioOpen(1, PIOPWMOUT, 0);
    if (fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(fd, I2C_SET_CLOCK, 400000) < 0) {
        perror("I2C_SET_CLOCK");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    fd = pigpioOpen(0, PIOMEMMAP, 0);
    if (fd < 0) {
        perror("pigpioOpen");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Map I2C device
    void *map = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        pigpioClose(fd);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Define I2C buffer
    unsigned char i2c_buffer[I2C_BUFFER_SIZE];

    // Define I2C command
    unsigned char i2c_command = 0x00;

    while (1) {
        // Send I2C command
        if (pigpioWrite(fd, I2C_ADDRESS, &i2c_command, 1) < 0) {
            perror("pigpioWrite");
            break;
        }

        // Read I2C response
        if (pigpioRead(fd, I2C_ADDRESS, i2c_buffer, I2C_BUFFER_SIZE, I2C_TIMEOUT) < 0) {
            perror("pigpioRead");
            break;
        }

        // Check for error flags
        if (i2c_buffer[0] & 0x80) {
            printf("Error: %d\n", i2c_buffer[0]);
            break;
        }

        // Calculate distance
        float distance = (i2c_buffer[0] & 0x7F) * 0.01f;

        // Calculate ambient light
        float ambient_light = (i2c_buffer[1] & 0xFF) / 255.0f;

        // Print data
        printf("Distance: %.2f cm, Ambient Light: %.2f\n", distance, ambient_light);

        // Sleep for 500ms
        sleep(0.5);
    }

    // Unmap I2C device
    if (munmap(map, 256) < 0) {
        perror("munmap");
    }

    // Close I2C device
    pigpioClose(fd);
    pigpioClose(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

