#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_DURATION_US 10
#define MAX_ECHO_DURATION_US 20000
#define MAX_ECHO_DURATIONS 38
#define MEASUREMENT_INTERVAL_MS 1000

// Define the HC-SR04 library API
typedef struct {
    int pin;
    int resistor;
} hc_sr04_t;

// Define the HC-SR04 library API functions
int hc_sr04_init(hc_sr04_t *self, int pin, int resistor) {
    self->pin = pin;
    self->resistor = resistor;
    return 0;
}

int hc_sr04_trigger(hc_sr04_t *self) {
    gpio_set_high(self->pin);
    usleep(TRIGGER_DURATION_US * 1000);
    gpio_set_low(self->pin);
    return 0;
}

int hc_sr04_wait_for_echo(hc_sr04_t *self) {
    int start_time = clock_gettime_ns();
    while (1) {
        int echo_level = gpio_get(self->pin);
        if (echo_level == 0) {
            int duration = clock_gettime_ns() - start_time;
            if (duration > MAX_ECHO_DURATION_US * 1000) {
                return -1; // echo duration too long
            }
            if (duration < TRIGGER_DURATION_US * 1000) {
                return -1; // echo duration too short
            }
            return duration;
        }
        usleep(10);
    }
}

int hc_sr04_get_distance(hc_sr04_t *self, int duration) {
    if (duration < 0) {
        return -1; // invalid duration
    }
    int distance = (duration / 2) * 34300 / 1000; // speed of sound in cm/s
    return distance;
}

// Define the main function
int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize the HC-SR04 library
    hc_sr04_t hc;
    if (hc_sr04_init(&hc, TRIGGER_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to initialize HC-SR04 library\n");
        gpioTerminate();
        return 1;
    }

    // Set up the GPIO pins
    if (gpioSetMode(TRIGGER_PIN, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", TRIGGER_PIN);
        hc_sr04_close(&hc);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", ECHO_PIN);
        hc_sr04_close(&hc);
        gpioTerminate();
        return 1;
    }

    // Set up the resistor
    if (gpioSetPullUp(ECHO_PIN, PULL_UP_RESISTOR_1K) < 0) {
        fprintf(stderr, "Failed to set up resistor on GPIO pin %d\n", ECHO_PIN);
        hc_sr04_close(&hc);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger the HC-SR04
        if (hc_sr04_trigger(&hc) < 0) {
            fprintf(stderr, "Failed to trigger HC-SR04\n");
            break;
        }

        // Wait for the echo
        int duration = hc_sr04_wait_for_echo(&hc);
        if (duration < 0) {
            fprintf(stderr, "Failed to wait for echo\n");
            break;
        }

        // Get the distance
        int distance = hc_sr04_get_distance(&hc, duration);
        if (distance < 0) {
            fprintf(stderr, "Failed to get distance\n");
            break;
        }

        // Log the measurement
        time_t now = time(NULL);
        printf("%ld %d cm\n", now, distance);

        // Sleep for the measurement interval
        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    // Clean up
    hc_sr04_close(&hc);
    gpioTerminate();

    return 0;
}

// Define the signal handlers
void sigint_handler(int sig) {
    hc_sr04_close(&hc);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    hc_sr04_close(&hc);
    gpioTerminate();
    exit(0);
}

// Register the signal handlers
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler for SIGINT\n");
        exit(1);
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler for SIGTERM\n");
        exit(1);
