// Function to decode range profile data
bool decode_range_profile(uint8_t* data, int size) {
    if (size < 8) {
        return false;
    }
    uint32_t magic_word = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    if (magic_word != MAGIC_WORD) {
        return false;
    }
    for (int i = 4; i < size; i += 2) {
