#define MAGIC_WORD 0x12345678
#define DISTANCE_BINS 64
#define DISTANCE_THRESHOLD 1.0
#define GPIO_LED 17
#define INTRUSION_LOG_FILE "intrusion_log.csv"

// Structure to hold intrusion data
typedef struct {
    time_t timestamp;
    double distance;
} Intrusion;

// Function to initialize UART
int init_uart(int fd) {
    struct termios options;
    tcgetattr(fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    tcsetattr(fd, TCSANOW, &options);
    return 0;
}

// Function to read UART data
int read_uart(int fd, char* buffer, size_t size) {
    int bytes_read = read(fd, buffer, size);
    if (bytes_read < 0) {
        return -1;
    }
    return bytes_read;
}

// Function to decode range profile data
bool decode_range_profile(uint8_t* data, int size) {
    if (size < 8) {
        return false;
    }
    uint32_t magic_word = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    if (magic_word != MAGIC_WORD) {
        return false;
    }
    for (int i = 4; i < size; i += 2) {
        uint16_t distance = (data[i] << 8) | data[i + 1];
        if (distance < DISTANCE_THRESHOLD) {
            return true;
        }
    }
    return false;
}

// Function to log intrusion data
void log_intrusion(Intrusion* intrusion) {
    FILE* file = fopen(INTRUSION_LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%s,%f\n", ctime(&intrusion->timestamp), intrusion->distance);
    fclose(file);
}

// Function to activate LED
void activate_led(pigpio* gpio) {
    gpio_set_high(gpio, GPIO_LED);
    sleep(2);
    gpio_set_low(gpio, GPIO_LED);
}

