#include <errno.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PIN 17
#define GPIO_Buzzer 18
#define OBSTACLE_THRESHOLD 10
#define LOG_FILE "obstacle_log.txt"

// Structure to hold the GPIO handle and file descriptor
typedef struct {
    pigpio gpioHandle;
    int fd;
} gpio_t;

// Function to initialize the GPIO and open the log file
gpio_t* init_gpio() {
    gpio_t* gpio = malloc(sizeof(gpio_t));
    if (gpio == NULL) {
        perror("malloc");
        exit(1);
    }

    gpio->gpioHandle = pigpio_init();
    if (gpioHandle == -1) {
        perror("pigpio_init");
        free(gpio);
        exit(1);
    }

    gpio->fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (gpio->fd == -1) {
        perror("open");
        pigpio_close(gpioHandle);
        free(gpio);
        exit(1);
    }

    return gpio;
}

// Function to read the obstacle detection data from the IR sensor
int read_obstacle(gpio_t* gpio) {
    int value = gpio->gpioHandle.get(GPIO_PIN, GPIO_INPUT);
    if (value == -1) {
        perror("gpio_get");
        return -1;
    }

    return value;
}

// Function to write to the log file
void write_log(gpio_t* gpio, int value, time_t timestamp) {
    char log_message[256];
    strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S.%6N", localtime(&timestamp));
    log_message[24] = '\0';

    if (write(gpio->fd, log_message, strlen(log_message) + 1) == -1) {
        perror("write");
        return;
    }

    if (write(gpio->fd, "\n", 1) == -1) {
        perror("write");
        return;
    }

    if (write(gpio->fd, (value ? "1" : "0"), 1) == -1) {
        perror("write");
        return;
    }
}

// Function to handle the SIGINT signal
void sigint_handler(int signal) {
    gpio_t* gpio = init_gpio();
    if (gpio == NULL) {
        return;
    }

    gpio->gpioHandle.set(GPIO_Buzzer, GPIO_HIGH);
    close(gpio->fd);
    pigpio_close(gpio->gpioHandle);
    free(gpio);
    exit(0);
}

// Function to handle the SIGTERM signal
void sigterm_handler(int signal) {
    gpio_t* gpio = init_gpio();
    if (gpio == NULL) {
        return;
    }

    gpio->gpioHandle.set(GPIO_Buzzer, GPIO_LOW);
    close(gpio->fd);
    pigpio_close(gpio->gpioHandle);
    free(gpio);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    gpio_t* gpio = init_gpio();
    if (gpio == NULL) {
        return 1;
    }

    while (1) {
        int value = read_obstacle(gpio);
        if (value == -1) {
            continue;
        }

        time_t timestamp = time(NULL);
        write_log(gpio, value, timestamp);

        if (value) {
            gpio->gpioHandle.set(GPIO_Buzzer, GPIO_HIGH);
        } else {
            gpio->gpioHandle.set(GPIO_Buzzer, GPIO_LOW);
        }

        usleep(100000);
    }

    return 0;
}

