#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <libgpiod.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x20
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"

int main(int argc, char **argv) {
    // Initialize libgpiod
    gpiod_init();

    // Initialize GPIO pin 17 as an output
    gpioInitialise(gpio_get(), GPIO_MODE_OUTPUT, GPIO_FLOATING, GPIO_PIN_17);

    // Open the log file for writing
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Open I2C bus 1
    int i2c_fd = i2c_open(1, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        gpioTerminate(gpio_get());
        return 1;
    }

    // Read the sensor's ID
    uint8_t sensor_id;
    if (i2c_read(i2c_fd, &sensor_id, 1) != 1) {
        perror("Failed to read sensor ID");
        i2c_close(i2c_fd);
        fclose(log_file);
        gpioTerminate(gpio_get());
        return 1;
    }

    // Check if the sensor is the TDK Chirp ICU-20201
    if (sensor_id != 0x01) {
        perror("Invalid sensor ID");
        i2c_close(i2c_fd);
        fclose(log_file);
        gpioTerminate(gpio_get());
        return 1;
    }

    // Enable the sensor
    if (i2c_write(i2c_fd, 0x00, 1) != 1) {
        perror("Failed to enable sensor");
        i2c_close(i2c_fd);
        fclose(log_file);
        gpioTerminate(gpio_get());
        return 1;
    }

    // Read the sensor's distance measurement every 100ms
    struct timespec start_time;
    struct timespec end_time;
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        // Read the distance measurement
        uint16_t distance;
        if (i2c_read(i2c_fd, &distance, 2) != 2) {
            perror("Failed to read distance measurement");
            i2c_close(i2c_fd);
            fclose(log_file);
            gpioTerminate(gpio_get());
            return 1;
        }

        // Convert the distance to centimeters
        distance /= 2;

        // Log the distance with an ISO 8601 timestamp
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", localtime(&start_time));
        fprintf(log_file, "%s %f\n", timestamp, distance);

        // Check if the distance is below 10cm
        if (distance < 10.0) {
            gpioWrite(gpio_get(), GPIO_PIN_17, 1);
        } else {
            gpioWrite(gpio_get(), GPIO_PIN_17, 0);
        }

        // Sleep for 100ms
        sleep(0.1);
    }

    // Cleanly release resources
    gpioTerminate(gpio_get());
    i2c_close(i2c_fd);
    fclose(log_file);

    return 0;
}

