#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <errno.h>

#define I2C_ADDRESS 0x29
#define I2C_TIMEOUT 100
#define FILE_NAME "distance_log.csv"

// Structure to hold the sensor data
typedef struct {
    uint32_t timestamp;
    uint16_t distance_mm;
} sensor_data_t;

// Function to initialize the sensor
int init_sensor(pigpio_t *gpio, int i2c_fd) {
    if (gpio->i2c_open(i2c_fd, I2C_ADDRESS, I2C_TIMEOUT) < 0) {
        printf("Error opening I2C device\n");
        return -1;
    }
    if (gpio->i2c_write(i2c_fd, 0x00, 0x00, 1) < 0) {
        printf("Error writing to I2C device\n");
        gpio->i2c_close(i2c_fd);
        return -1;
    }
    if (gpio->i2c_read(i2c_fd, 0x00, 0x00, 1, NULL, 0) < 0) {
        printf("Error reading from I2C device\n");
        gpio->i2c_close(i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read the sensor data
int read_sensor(pigpio_t *gpio, int i2c_fd) {
    uint8_t data[3];
    if (gpio->i2c_read(i2c_fd, 0x00, 0x00, 3, data, I2C_TIMEOUT) < 0) {
        printf("Error reading from I2C device\n");
        return -1;
    }
    return data[0];
}

// Function to calculate the distance
int calculate_distance(uint8_t data) {
    return (data & 0xFF) * 2;
}

// Function to write to the log file
int write_to_log(sensor_data_t *data) {
    FILE *log_file = fopen(FILE_NAME, "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return -1;
    }
    fprintf(log_file, "%d,%d\n", data->timestamp, data->distance_mm);
    fclose(log_file);
    return 0;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    gpio_close(gpio);
    close(i2c_fd);
    exit(0);
}

int main() {
    pigpio_t gpio;
    int i2c_fd = -1;
    sensor_data_t data;

    // Initialize the GPIO library
    if (gpio_init() < 0) {
        printf("Error initializing GPIO library\n");
        return -1;
    }

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        printf("Error opening I2C device\n");
        gpio_close(gpio);
        return -1;
    }

    // Initialize the sensor
    if (init_sensor(&gpio, i2c_fd) < 0) {
        return -1;
    }

    // Create the log file if it does not exist
    struct stat sb;
    if (stat(FILE_NAME, &sb) == -1) {
        touch(FILE_NAME);
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Read the sensor data
        int data_value = read_sensor(&gpio, i2c_fd);
        if (data_value < 0) {
            continue;
        }

        // Calculate the distance
        data.timestamp = time(NULL);
        data.distance_mm = calculate_distance(data_value);

        // Write to the log file
        if (write_to_log(&data) < 0) {
            continue;
        }

        // Print the parking guidance message
        if (data.distance_mm < 300) {
            printf("STOP\n");
        } else if (data.distance_mm < 600) {
            printf("APPROACH\n");
        } else if (data.distance_mm < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // De-initialize the sensor
    if (init_sensor(&gpio, i2c_fd) < 0) {
        return -1;
    }

    // Close the I2C device
    if (close(i2c_fd) < 0) {
        printf("Error closing I2C device\n");
        return -1;
    }

    // Close the GPIO library
    gpio_close(gpio);

    return 0;
}

