#include <sys/types.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define I2C_ADDRESS 0x29
#define LED_PIN 18
#define LED_RESISTOR 330
#define LED_ON 0
#define LED_OFF 1
#define I2C_DELAY 10
#define I2C_RETRY 3

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up LED pin as output
    if (gpioMode(LED_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Set up I2C
    if (i2cInit(1) < 0) {
        perror("i2cInit");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    int i2cHandle = i2cOpen(I2C_ADDRESS, 0);
    if (i2cHandle < 0) {
        perror("i2cOpen");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigtermHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read distance from sensor
        uint8_t data[3];
        int retry = 0;
        while (retry < I2C_RETRY) {
            if (i2cRead(i2cHandle, data, 3, 100) < 0) {
                if (errno == EIO) {
                    retry++;
                    usleep(I2C_DELAY * 1000);
                } else {
                    perror("i2cRead");
                    i2cClose(1);
                    gpioTerminate();
                    return 1;
                }
            } else {
                break;
            }
        }
        if (retry >= I2C_RETRY) {
            continue;
        }

        // Calculate distance
        uint16_t distance = (data[0] << 8) | data[1];

        // Calculate LED blink frequency
        uint32_t blinkFrequency = 1000 / distance;

        // Blink LED
        gpioWrite(LED_PIN, LED_OFF);
        usleep(blinkFrequency);
        gpioWrite(LED_PIN, LED_ON);
        usleep(blinkFrequency);
    }

    // Clean up
    i2cClose(1);
    gpioTerminate();
    return 0;
}

void sigintHandler(int sig) {
    i2cClose(1);
    gpioWrite(LED_PIN, LED_OFF);
    gpioTerminate();
    exit(0);
}

void sigtermHandler(int sig) {
    i2cClose(1);
    gpioWrite(LED_PIN, LED_OFF);
    gpioTerminate();
    exit(0);
}

