#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <errno.h>

#define I2C_ADDRESS 0x5A
#define I2C_SPEED 100000
#define I2C_TIMEOUT 10
#define FILE_NAME "distance_log.csv"

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open file for writing
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Map file to memory
    struct stat sb;
    if (fstat(fd, &sb) < 0) {
        perror("fstat");
        close(fd);
        gpioTerminate();
        return 1;
    }
    void *map = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // I2C configuration
    if (gpioSetMode(1, PI_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        munmap(map, sb.st_size);
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(1, 0x00) < 0) {
        perror("gpioWrite");
        munmap(map, sb.st_size);
        close(fd);
        gpioTerminate();
        return 1;
    }
    usleep(100000); // 100ms delay

    // I2C read configuration
    if (gpioSetMode(1, PI_MODE_INPUT) < 0) {
        perror("gpioSetMode");
        munmap(map, sb.st_size);
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read I2C data
        int status = gpioGet(1, &map, I2C_TIMEOUT);
        if (status < 0) {
            if (errno == ETIMEDOUT) {
                // Retry
                usleep(100000);
                status = gpioGet(1, &map, I2C_TIMEOUT);
                if (status < 0) {
                    perror("gpioGet");
                    munmap(map, sb.st_size);
                    close(fd);
                    gpioTerminate();
                    return 1;
                }
            } else {
                perror("gpioGet");
                munmap(map, sb.st_size);
                close(fd);
                gpioTerminate();
                return 1;
            }
        }

        // Read 2-byte distance value
        unsigned char data[2];
        if (read(map, data, 2) < 2) {
            perror("read");
            munmap(map, sb.st_size);
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Convert distance to centimeters
        int distance = (data[0] << 8) | data[1];

        // Append to file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        char buffer[256];
        sprintf(buffer, "%s,%d\n", timestamp, distance);
        write(fd, buffer, strlen(buffer));

        // Wait for 100ms before next measurement
        usleep(100000);
    }

    // Clean up
    munmap(map, sb.st_size);
    close(fd);
    gpioTerminate();

    return 0;
}

