#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <syslog.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define DEBOUNCE_TIME 50
#define LOG_FILE "proximity_log.txt"

int main(int argc, char *argv[]) {
    int gpio = 0;
    int sensor1, sensor2;
    int state1, state2;
    struct timespec last_state1, last_state2;
    struct timespec now;
    struct stat log_file_stat;
    int log_fd = -1;
    int ret;

    // Initialize the GPIO library
    if (gpio = pigpio_init(), gpio == -1) {
        perror("pigpio_init");
        return 1;
    }

    // Open the log file for writing
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644), log_fd == -1) {
        perror("open");
        return 1;
    }

    // Set up the GPIO pins
    if (gpio = pigpio_set_mode(GPIO_PIN_17, PI_INPUT), gpio == -1) {
        perror("pigpio_set_mode");
        return 1;
    }
    if (gpio = pigpio_set_mode(GPIO_PIN_27, PI_INPUT), gpio == -1) {
        perror("pigpio_set_mode");
        return 1;
    }

    // Set up the debouncing
    if (gpio = pigpio_set_pull_up_downtime(GPIO_PIN_17, PI_PUD_DOWN), gpio == -1) {
        perror("pigpio_set_pull_up_downtime");
        return 1;
    }
    if (gpio = pigpio_set_pull_up_downtime(GPIO_PIN_27, PI_PUD_DOWN), gpio == -1) {
        perror("pigpio_set_pull_up_downtime");
        return 1;
    }

    while (1) {
        // Read the sensor states
        if (gpio = pigpio_read(GPIO_PIN_17, &state1), gpio == -1) {
            perror("pigpio_read");
            continue;
        }
        if (gpio = pigpio_read(GPIO_PIN_27, &state2), gpio == -1) {
            perror("pigpio_read");
            continue;
        }

        // Check for state transitions
        if (state1 != state2) {
            if (state1 == 1) {
                // Sensor 1 detected an obstacle
                if (time(&now) > last_state1 + (timespec){0, DEBOUNCE_TIME}) {
                    last_state1 = now;
                    if (fwrite(log_fd, "%Y-%m-%d %H:%M:%S.%6N %d DETECTED\n", timegm(&now), 1, 1) == -1) {
                        perror("fwrite");
                    }
                }
            } else {
                // Sensor 1 cleared an obstacle
                if (time(&now) > last_state1 + (timespec){0, DEBOUNCE_TIME}) {
                    last_state1 = now;
                    if (fwrite(log_fd, "%Y-%m-%d %H:%M:%S.%6N %d CLEARED\n", timegm(&now), 1, 1) == -1) {
                        perror("fwrite");
                    }
                }
            }
        }

        if (state2 != state1) {
            if (state2 == 1) {
                // Sensor 2 detected an obstacle
                if (time(&now) > last_state2 + (timespec){0, DEBOUNCE_TIME}) {
                    last_state2 = now;
                    if (fwrite(log_fd, "%Y-%m-%d %H:%M:%S.%6N %d DETECTED\n", timegm(&now), 1, 2) == -1) {
                        perror("fwrite");
                    }
                }
            } else {
                // Sensor 2 cleared an obstacle
                if (time(&now) > last_state2 + (timespec){0, DEBOUNCE_TIME}) {
                    last_state2 = now;
                    if (fwrite(log_fd, "%Y-%m-%d %H:%M:%S.%6N %d CLEARED\n", timegm(&now), 1, 2) == -1) {
                        perror("fwrite");
                    }
                }
            }
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up
    if (close(log_fd) == -1) {
        perror("close");
    }
    if (pigpio_close(gpio) == -1) {
        perror("pigpio_close");
    }
    return 0;
}

