#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define I2C_SLAVE_ADDRESS 0x61
#define I2C_TIMEOUT 50
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define MEAS_STATUS 0x00
#define MEAS_STATUS_REG 0x00
#define MEAS_STATUS_DATA 0x01
#define MEAS_STATUS_ERROR 0x02
#define MEAS_STATUS_OK 0x03

void* i2c_helper(int fd, int reg, int value) {
    unsigned char buf[2];
    int ret = write(fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return NULL;
    }
    ret = read(fd, buf, 1);
    if (ret != 1) {
        perror("read");
        return NULL;
    }
    if (buf[0] != value) {
        return NULL;
    }
    return buf;
}

int main() {
    int fd;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Install signal handlers
    sa.sa_handler = SIG_IGN;
    sa_int.sa_handler = SIG_IGN;
    sigemptyset(&sa_int.sa_mask);
    sigaddset(&sa_int.sa_mask, SIGINT);
    sigaction(SIGINT, &sa_int, NULL);
    sigaction(SIGTERM, &sa_int, NULL);

    sa.sa_handler = SIG_DFL;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, &sa_int);
    sigaction(SIGTERM, &sa, &sa_int);

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

