#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

#define I2C_ADDRESS 0x5A
#define I2C_TIMEOUT 1000 // 1 second
#define I2C_RETRY 3
#define I2C_RETRY_DELAY 10 // 10 ms

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the I2C bus
    int fd = pigpioOpen(1, PI_MODE BCM, 0);
    if (fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Map the I2C memory-mapped I/O region
    void *i2c_map = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (i2c_map == MAP_FAILED) {
        perror("mmap");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Check if the sensor is present
    if (i2c_map[I2C_ADDRESS] == 0) {
        printf("Sensor not found\n");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set the sensor to measure distance
    *(volatile unsigned char *)i2c_map[I2C_ADDRESS + 0x00] = 0x00;
    *(volatile unsigned char *)i2c_map[I2C_ADDRESS + 0x01] = 0x00;

    // Set the sensor to start measuring
    *(volatile unsigned char *)i2c_map[I2C_ADDRESS + 0x02] = 0x01;

    // Wait for the sensor to start measuring
    usleep(100000);

    // Main loop
    while (1) {
        // Read the distance measurement
        unsigned char data;
        int retry = 0;
        while (retry < I2C_RETRY) {
            if (i2c_map[I2C_ADDRESS + 0x03] == 0x00) {
                printf("Sensor not responding\n");
                break;
            }
            if (ioctl(fd, I2C Master Read, (void *)(&data, 1, I2C_ADDRESS, I2C_TIMEOUT)) < 0) {
                if (errno == EIO) {
                    usleep(I2C_RETRY_DELAY);
                    retry++;
                } else {
                    perror("ioctl");
                    break;
                }
            } else {
                break;
            }
        }

        if (retry >= I2C_RETRY) {
            printf("Failed to read from sensor\n");
            break;
        }

        // Convert the measurement to distance
        unsigned int distance = (data & 0xFF) * 2;

        // Print the measurement
        time_t now = time(NULL);
        printf("%d.%06d %d\n", now / 1000, (now % 1000) * 100, distance);

        // Wait for the next measurement
        usleep(100);
    }

    // Clean up
    munmap(i2c_map, 256);
    pigpioClose(fd);
    gpioTerminate();

    return 0;
}

