#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDRESS 0x29
#define I2C_REG_STATUS 0x00
#define I2C_REG_DATA 0x04

int main(int argc, char **argv) {
    int fd;
    struct pigpio *gpio;
    struct timeval tv;
    struct timespec ts;
    struct itimerspec it;
    struct i2c_client *client;
    struct i2c_dev *dev;
    int ret;
    int i;

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        pigpio_cleanup();
        return 1;
    }

    // Set I2C address and mode
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        pigpio_cleanup();
        return 1;
    }

    // Set I2C clock speed
    ret = ioctl(fd, I2C_SMBUS_CLOCK, 400000);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        pigpio_cleanup();
        return 1;
    }

    // Initialize I2C client
    client = i2c_get_client(fd);
    if (client == NULL) {
        perror("i2c_get_client");
        close(fd);
        pigpio_cleanup();
        return 1;
    }

    // Initialize I2C device
    dev = i2c_dev_new(client, I2C_ADDRESS);
    if (dev == NULL) {
        perror("i2c_dev_new");
        i2c_client_put(client);
        close(fd);
        pigpio_cleanup();
        return 1;
    }

    // Set up timer
    tv.tv_sec = 0;
    tv.tv_usec = 0;
    it.it_value.tv_sec = tv.tv_sec;
    it.it_value.tv_nsec = tv.tv_usec * 1000;
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_nsec = 500 * 1000;
    if (clock_settime(CLOCK_MONOTONIC, &it) != 0) {
        perror("clock_settime");
        i2c_dev_put(dev);
        i2c_client_put(client);
        close(fd);
        pigpio_cleanup();
        return 1;
    }

    while (1) {
        // Read interrupt status
        ret = i2c_dev_read(dev, I2C_REG_STATUS, 1, NULL, NULL);
        if (ret < 0) {
            perror("i2c_dev_read");
            i2c_dev_put(dev);
            i2c_client_put(client);
            close(fd);
            pigpio_cleanup();
            return 1;
        }

        // Check interrupt status
        if (ret & (1 << 0)) {
            // Read distance data
            ret = i2c_dev_read(dev, I2C_REG_DATA, 4, NULL, NULL);
            if (ret < 0) {
                perror("i2c_dev_read");
                i2c_dev_put(dev);
                i2c_client_put(client);
                close(fd);
                pigpio_cleanup();
                return 1;
            }

            // Convert distance data to millimeters
            uint16_t distance = (ret >> 8) & 0xFF;
            distance *= 10;

            // Format timestamp
            clock_gettime(CLOCK_MONOTONIC, &ts);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%u", localtime(&ts.tv_sec));

            // Log distance measurement
            printf("%s, Distance: %d mm\n", timestamp, distance);

            // Reset interrupt status
            ret = i2c_dev_write(dev, I2C_REG_STATUS, 1);
            if (ret < 0) {
                perror("i2c_dev_write");
                i2c_dev_put(dev);
                i2c_client_put(client);
                close(fd);
                pigpio_cleanup();
                return 1;
            }
        } else {
            // Skip cycle without reporting an error
            printf("No interrupt\n");
        }
    }

    // Clean up
    i2c_dev_put(dev);
    i2c_client_put(client);
    close(fd);
    pigpio_cleanup();
    return 0;
}

void sigint_handler(int sig) {
    i2c_dev_put(dev);
    i2c_client_put(client);
    close(fd);
    pigpio_cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    i2c_dev_put(dev);
    i2c_client_put(client);
    close(fd);
    pigpio_cleanup();
    exit(0);
}

