// Function to initialize the GPIO pin
void init_gpio(pigpio *gpio) {
    if (gpio->set_mode(GPIO_PIN, PI_INPUT) != 0) {
        printf("Error initializing GPIO pin %d\n", GPIO_PIN);
        exit(1);
    }
}

// Function to initialize the I2C bus
void init_i2c(pigpio *gpio) {
    if (gpio->i2c_open(I2C_ADDRESS, 0, 100) != 0) {
        printf("Error opening I2C bus\n");
        exit(1);
    }
}

// Function to read the sensor data
void read_sensor(pigpio *gpio) {
    uint8_t buffer[6];
    if (gpio->i2c_read(I2C_ADDRESS, 0, buffer, 6, 50) != 0) {
        printf("Error reading sensor data\n");
        exit(1);
    }
    uint16_t distance = (buffer[0] << 8) | buffer[1];
    time_t timestamp = time(NULL);
    sensor_data_t data;
    data.distance = distance;
    data.timestamp = timestamp;
    mq_send(MSG_QUEUE_NAME, &data, sizeof(sensor_data_t), 0);
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    gpio_close(GPIO_PIN);
    mq_unlink(MSG_QUEUE_NAME);
    exit(0);
}

int main() {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Error initializing pigpio\n");
        exit(1);
    }

    // Initialize the GPIO pin
    init_gpio(gpio);

    // Initialize the I2C bus
    init_i2c(gpio);

    // Create the message queue
    int mq_fd = mq_open(MSG_QUEUE_NAME, O_RDWR | O_CREAT, 0644, 1);
    if (mq_fd == -1) {
        printf("Error creating message queue\n");
        exit(1);
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    while (1) {
        read_sensor(gpio);
        if (gpio->i2c_read(I2C_ADDRESS, 0, NULL, 0, 50) == 0) {
            if (gpio->i2c_read(I2C_ADDRESS, 0, NULL, 0, 50) == 0) {
                uint8_t buffer[6];
                if (gpio->i2c_read(I2C_ADDRESS, 0, buffer, 6, 50) == 0) {
                    uint16_t distance = (buffer[0] << 8) | buffer[1];
                    if (distance < 100) {
                        gpio->gpio_fsel(GPIO_PIN, PI_OUTPUT);
                        gpio->gpio_write(GPIO_PIN, 1);
                    } else {
                        gpio->gpio_fsel(GPIO_PIN, PI_INPUT);
                        gpio->gpio_write(GPIO_PIN, 0);
                    }
                }
            }
        }
        usleep(50);
    }

    // Clean up
    gpio_close(GPIO_PIN);
    mq_unlink(MSG_QUEUE_NAME);
    pigpio_close(gpio);
    return 0;
}
