        printf("Failed to set GPIO mode\n");
        pigpio_close();
        return 1;
    }

    // Generate a 10 us high pulse on the trigger pin
    gpioWrite(TRIGGER_PIN, 1);
    usleep(10);
    gpioWrite(TRIGGER_PIN, 0);

    // Set the GPIO mode for the echo pin
    if (gpioMode(ECHO_PIN, GPIO_MODE_INPUT) < 0) {
        printf("Failed to set GPIO mode\n");
        pigpio_close();
        return 1;
    }

    // Register the interrupt
    if (gpioInterrupt(TRIGGER_PIN, GPIO_EDGE_RISING, interrupt_handler) < 0) {
        printf("Failed to register interrupt\n");
        pigpio_close();
        return 1;
    }

    // Set the GPIO mode for the buzzer pin
    if (gpioMode(BUZZER_PIN, GPIO_MODE_OUTPUT) < 0) {
