        if (echo_state == 0) {
            // No echo, sensor absent
            printf("Sensor absent\n");
            continue;
        }

        // Calculate the time difference
        int time_diff = gpioRead(TRIGGER_PIN) - gpioRead(TRIGGER_PIN);
        if (time_diff < 0) {
            // 32-bit tick wraparound
            time_diff += 4294967296;
        }

        // Calculate the distance
        int distance = (time_diff * 34300) / 2;

        // Check for invalid readings
        if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
            printf("Invalid reading\n");
            continue;
        }

        // Output the distance
        printf("%d cm\n", distance);

        // Activate the buzzer if the distance is less than 30 cm
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    pigpio_close();
    return 0;
}

