void i2c_init(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS_VL53L1X) < 0) {
        perror("Failed to set I2C address for VL53L1X");
        close(fd);
        exit(1);
    }

    close(fd);
}

void i2c_reset(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS_VL53L1X) < 0) {
        perror("Failed to set I2C address for VL53L1X");
        close(fd);
        exit(1);
    }

    if (ioctl(fd, VL53L1X_RESET, 0) < 0) {
        perror("Failed to reset VL53L1X");
        close(fd);
        exit(1);
    }

    close(fd);
}

void i2c_wait_for_boot(void) {
    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        int status = ioctl(fd, VL53L1X_GET_STATUS, 0);
        if (status & (1 << 0)) {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            if (clock_gettime(CLOCK_MONOTONIC, &start_time)->tv_sec - start_time.tv_sec > 1) {
