            fprintf(log_fd, "%d %d\n", (int)clock_gettime(CLOCK_MONOTONIC).tv_sec, distance);
        }
    }

    // Close I2C bus
    i2c_close();

    // Close GPIO
    gpio_close();

    // Close log file
    close(log_fd);

    return 0;
}

// Signal handler
void sig_handler(int sig) {
    // Clean up
    gpio_close();
    i2c_close();

    // Exit
    exit(0);
}

