#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIG_HIGH 1
#define ECHO_LOW 0
#define PULSE_DURATION_US 10
#define SAMPLE_RATE 200
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define TIMEOUT_US 30000
#define LOG_FILE "distance_log.txt"

// Define structures
typedef struct {
    uint32_t rising_tick;
    uint32_t falling_tick;
} Pulse;

// Define the alert callback
void alert_callback(pigpio_t *gpio, int gpio_num, int level, void *user_data) {
    Pulse *pulse = (Pulse *)user_data;
    pulse->rising_tick = gpio_get_tick(gpio);
    gpio_set_level(gpio, gpio_num, level);
    gpio_get_edge(gpio, gpio_num, GPIO_EDGE_BOTH, 0, 0, &pulse->falling_tick);
}

// Define the main function
int main(int argc, char **argv) {
    // Initialize the GPIO driver
    pigpio_t *gpio = pigpio_init();
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Set up the GPIO pins
    if (gpio_set_mode(gpio, TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG pin mode\n");
        pigpio_close(gpio);
        return 1;
    }
    if (gpio_set_level(gpio, TRIG_PIN, ECHO_LOW) != 0) {
        fprintf(stderr, "Failed to set TRIG pin level\n");
        pigpio_close(gpio);
        return 1;
    }
    if (gpio_set_mode(gpio, ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO pin mode\n");
        pigpio_close(gpio);
        return 1;
    }
    if (gpio_set_pull_up_down(gpio, ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set ECHO pin pull-down\n");
        pigpio_close(gpio);
        return 1;
    }

    // Set up the alert callback
    Pulse pulse;
    pulse.rising_tick = 0;
    pulse.falling_tick = 0;
    gpio_set_edge_callback(gpio, TRIG_PIN, GPIO_EDGE_BOTH, alert_callback, &pulse);

    // Set up the timer
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = (long long)(PULSE_DURATION_US * 1000);
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = (long long)(SAMPLE_RATE * 1000);
    if (setitimer(ITIMER_REAL, &timer, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        pigpio_close(gpio);
        return 1;
    }

    // Log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_close(gpio);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for the timer to expire
        struct itimerspec old_timer;
        if (getitimer(ITIMER_REAL, &old_timer) != 0) {
            fprintf(stderr, "Failed to get timer\n");
            pigpio_close(gpio);
            fclose(log_file);
            return 1;
        }

        // Check for a valid echo
        if (gpio_get_level(gpio, ECHO_PIN) == ECHO_LOW) {
            // Wait for the echo to return
            struct timespec start_time;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (gpio_get_level(gpio, ECHO_PIN) == ECHO_LOW) {
                // Wait for the echo to return
            }
            struct timespec end_time;
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            uint32_t echo_duration_us = (end_time.tv_sec * 1000000 + end_time.tv_nsec) - (start_time.tv_sec * 1000000 + start_time.tv_nsec);
            if (echo_duration_us < MIN_PULSE_WIDTH_US || echo_duration_us > MAX_PULSE_WIDTH_US) {
                fprintf(stderr, "Invalid echo duration: %u us\n", echo_duration_us);
                fprintf(log_file, "%s Invalid echo duration: %u us\n", ctime(&start_time), echo_duration_us);
                continue;
            }

            // Calculate the distance
            uint32_t distance_cm = (echo_duration_us / 2) / 29.1;

            // Log the distance
            fprintf(log_file, "%s Distance: %.2f cm\n", ctime(&start_time), distance_cm);
            fprintf(stdout, "Distance: %.2f cm\n", distance_cm);

            // Check for a timeout
            if (echo_duration_us > TIMEOUT_US) {
                fprintf(stderr, "Timeout\n");
