#define GPIO_PIN_19 19
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "gate_events.log"

int main(int argc, char **argv) {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (ioctl(fd, VL53L1X_Init, 0) < 0) {
        perror("VL53L1X_Init");
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(fd, VL53L1X_SetTimingBudget, 0x00000000) < 0) {
        perror("VL53L1X_SetTimingBudget");
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(fd, VL53L1X_StartRanging, 0) < 0) {
        perror("VL53L1X_StartRanging");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open GPIO pins
    if (gpioMode(GPIO_PIN_18, GPIO_MODE_OUTPUT);
    if (gpioMode(GPIO_PIN_19, GPIO_MODE_OUTPUT);
    if (gpioPullUpDn(GPIO_PIN_18, PUD_UP);
    if (gpioPullUpDn(GPIO_PIN_19, PUD_UP);

    // Main loop
    while (1) {
        // Read distance measurement
        unsigned char status;
        unsigned short distance;
        if (ioctl(fd, VL53L1X_GetDistance, &status) < 0) {
            perror("VL53L1X_GetDistance");
            continue;
        }

        if (status & (1 << 0)) {
            // Object detected
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(GPIO_PIN_18, 1);
                gpioWrite(GPIO_PIN_19, 0);
                printf("%s %d\n", ctime(NULL), distance);
                fflush(stdout);
            } else {
                gpioWrite(GPIO_PIN_18, 0);
                gpioWrite(GPIO_PIN_19, 1);
                printf("%s %d\n", ctime(NULL), distance);
                fflush(stdout);
            }
        } else {
            gpioWrite(GPIO_PIN_18, 0);
            gpioWrite(GPIO_PIN_19, 0);
            printf("%s %d\n", ctime(NULL), distance);
            fflush(stdout);
        }

        // Sleep for 500ms
        sleep(0.5);
    }

    // Clean up
    gpioTerminate();
    close(fd);
    return 0;
}

