#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x5A
#define ELE0 0
#define ELE11 11
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22
#define GPIO3 3
#define GPIO2 2
#define DELAY 50

int main() {
    int fd;
    int i;
    int status;
    struct timespec ts;
    struct timespec last_ts;
    struct timespec interval;
    struct itimerspec timer;
    struct sigaction sa;
    struct sigaction sa_int;
    struct sigaction sa_term;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Open I2C
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }

    // Set GPIO as output
    gpioModeSetup(GPIO3, GPIO_MODE_OUTPUT);
    gpioModeSetup(GPIO2, GPIO_MODE_OUTPUT);

    // Set GPIO as output
    gpioWrite(GPIO3, 0);
    gpioWrite(GPIO2, 0);

    // Set up timer
    clock_gettime(CLOCK_MONOTONIC, &last_ts);
    interval.tv_sec = 0;
    interval.tv_nsec = DELAY * 1000000;
    timer.it_value.tv_sec = interval.tv_sec;
    timer.it_value.tv_nsec = interval.tv_nsec;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = interval.tv_nsec;
    if (tcsettime(&timer, TCO_NANOSEC) < 0) {
        perror("tcsettime");
        exit(1);
    }

    // Set up signal handlers
    sa.sa_handler = sigalrm;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGALRM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    sa_int.sa_handler = sigalrm;
    sa_int.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa_int, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    sa_term.sa_handler = SIG_IGN;
    sa_term.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa_term, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    while (1) {
        // Poll I2C
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("ioctl");
            break;
        }

        // Read touch status
        unsigned char status;
        if (read(fd, &status, 1) < 1) {
            perror("read");
            break;
        }

        // Check if sensor is present
        if (status & 0x80) {
            // Read all electrodes
            unsigned char ele[12];
            if (read(fd, ele, 12) < 12) {
                perror("read");
                break;
            }

            // Check for proximity
            for (i = 0; i < 12; i++) {
                if (ele[i] & 0x01) {
                    // Set GPIO
                    gpioWrite(GPIO17, (i & 0x04) ? 1 : 0);
                    gpioWrite(GPIO18, (i & 0x02) ? 1 : 0);
                    gpioWrite(GPIO27, (i & 0x01) ? 1 : 0);
                    gpioWrite(GPIO22, (i & 0x08) ? 1 : 0);

                    // Log event
                    clock_gettime(CLOCK_MONOTONIC, &ts);
                    fprintf(stderr, "%ld: %d\n", ts.tv_sec, i);
                }
            }
        }

        // Check for timer expiration
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec != last_ts.tv_sec || ts.tv_nsec != last_ts.tv_nsec) {
            last_ts = ts;
            if (tcsettime(&timer, TCO_NANOSEC) < 0) {
                perror("tcsettime");
                break;
            }
        }
    }

    // Release resources
    gpioCleanUp();
    close(fd);
    return 0;
}

