#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SOUND_SPEED 343
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioMode(TRIGGER_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    if (gpioMode(ECHO_PIN, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    usleep(5000);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    usleep(10000);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    struct timespec start;
    struct timespec end;
    struct timespec timeout;

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("clock_gettime");
        gpioTerminate();
        return 1;
    }

    if (gpioWaitRead(ECHO_PIN, &timeout, 30000) < 0) {
        perror("gpioWaitRead");
        gpioTerminate();
        return 1;
    }

    if (timeout.tv_sec > 0) {
        printf("Timeout waiting for echo rising edge\n");
        gpioTerminate();
        return 1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        perror("clock_gettime");
        gpioTerminate();
        return 1;
    }

    double pulse_width = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    double distance = pulse_width * SOUND_SPEED / 2;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Distance out of range: %f cm\n", distance);
        continue;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", localtime(&start.tv_sec));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "%s %f\n", timestamp, distance);
    fclose(log_file);

    sleep(1);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    gpioTerminate();
    close(log_file);
    exit(0);
}

