#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define VOLTAGE_DIVIDER 1000
#define PULSE_WIDTH_MIN 58
#define PULSE_WIDTH_MAX 25000
#define PULSE_WIDTH_TOLERANCE 1000
#define LOG_FILE "distance_log.txt"

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up the voltage divider
    gpioSetMode(ECHO_GPIO, PI_INPUT);
    gpioPullUp(ECHO_GPIO, PI_HIGH);
    gpioSetMode(TRIG_GPIO, PI_OUTPUT);
    gpioSetLevel(TRIG_GPIO, 0);

    // Set up the timer
    struct itimer it;
    it.it_value.tv_sec = 1;
    it.it_value.tv_usec = 0;
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_usec = 0;
    if (gpioSetTimer(&it) < 0) {
        perror("gpioSetTimer");
        return 1;
    }

    // Set up the interrupt handler
    gpioAddCallback(TRIG_GPIO, PI_RISING, distanceCallback, NULL);

    // Open the log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Set up the interrupt handler
    struct sigaction sa;
    sa.sa_handler = distanceHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Wait for the timer to expire
        if (gpioWaitTimer(&it) < 0) {
            perror("gpioWaitTimer");
            return 1;
        }

        // Generate a trigger pulse
        gpioWrite(TRIG_GPIO, 1);
        usleep(10);

        // Wait for the echo pulse
        struct timespec start_time;
        struct timespec end_time;
        gpioGetTimestamp(&start_time);
        gpioWaitEdge(ECHO_GPIO, PI_RISING, &end_time);
        gpioGetTimestamp(&end_time);

        // Calculate the pulse width
        double pulse_width = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_usec - start_time.tv_usec) / 1000000.0;
        if (pulse_width < PULSE_WIDTH_MIN || pulse_width > PULSE_WIDTH_MAX) {
            printf("Invalid pulse width: %f\n", pulse_width);
            continue;
        }

        // Calculate the distance
        double distance = pulse_width * 34300 / 2;

        // Append the reading to the log file
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL));
        fprintf(log_fd, "%s %f\n", timestamp, distance);
    }

    // Clean up
    gpioCleanUp();
    close(log_fd);
    return 0;
}

void distanceCallback(int gpio, int level, void *arg) {
    if (level == PI_HIGH) {
        // Trigger the echo pulse
        gpioWrite(ECHO_GPIO, 0);
        usleep(10);
        gpioWrite(ECHO_GPIO, 1);
    }
}

void distanceHandler(int sig) {
    // Clean up
    gpioDisableCallback(TRIG_GPIO, distanceCallback, NULL);
    gpioCleanUp();
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    close(STDIN_FILENO);
    close(log_fd);
    exit(0);
}

