#define GPIO_LEVEL_HIGH
#define GPIO_LEVEL_LOW
#define READ_INTERVAL 100
#define LOG_INFO 0x01
#define LOG_ERR 0x02

int main(int argc, char *argv[]) {
    int i2c_fd;
    int gpio_fd;
    int ret;
    struct pigpio *gpio;
    struct pigpio_config config;
    struct vl53l1x_config config_vl53l1x;
    struct vl53l1x_data data;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec time_diff;

    // Initialize the pigpio library
    gpio = pigpio_init();
    if (gpio == NULL) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

