int main(int argc, char **argv) {
    int i2c_fd, gpio_fd;
    struct pigpio gpio;
    struct i2c_client *client;
    struct i2c_dev *dev;
    unsigned char reg;
    unsigned int distance;
    int state = 0;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec time_diff;
    struct sigaction sa;

    // Initialize the GPIO library
    if (gpio_init(&gpio) < 0) {
        perror("gpio_init");
        return 1;
    }

    // Set up the GPIO pin as an output
    if (gpio_set_mode(GPIO_PIN, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        gpio_close(&gpio);
        return 1;
    }

    // Open the I2C interface
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpio_close(&gpio);
        return 1;
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpio_close(&gpio);
        return 1;
    }

    // Initialize the VL53L1X sensor
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_byte, &reg) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpio_close(&gpio);
        return 1;
    }

    // Read the sensor data
    if (ioctl(i2c_fd, I2C_SMBUS_READ_byte_data, &reg) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpio_close(&gpio);
        return 1;
    }

    // Convert the 16-bit register value to centimeters
    distance = (unsigned int) ((unsigned char) ioctl(i2c_fd, I2C_SMBUS_READ_byte_data, &reg) >> 8);

    // Log the initial distance reading
    if (access(LOG_FILE, F_OK) == -1) {
        if (mkdir(LOG_FILE, 0777) < 0) {
            perror("mkdir");
            close(i2c_fd);
            gpio_close(&gpio);
            return 1;
        }
    }
    if (fopen(LOG_FILE, "a") == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpio_close(&gpio);
        return 1;
    }
    fprintf(LOG_FILE, "Initial distance: %d cm\n", distance);
    fclose(LOG_FILE);

    // Main loop
    while (1) {
        // Record the start time
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Read the sensor data
        if (ioctl(i2c_fd, I2C_SMBUS_READ_byte_data, &reg) < 0) {
            perror("ioctl");
            close(i2c_fd);
            gpio_close(&gpio);
            return 1;
        }

        // Convert the 16-bit register value to centimeters
        distance = (unsigned int) ((unsigned char) ioctl(i2c_fd, I2C_SMBUS_READ_byte_data, &reg) >> 8);

        // Log the distance reading
        if (access(LOG_FILE, F_OK) == -1) {
            if (mkdir(LOG_FILE, 0777) < 0) {
                perror("mkdir");
                close(i2c_fd);
                gpio_close(&gpio);
                return 1;
            }
        }
        if (fopen(LOG_FILE, "a") == NULL) {
            perror("fopen");
            close(i2c_fd);
            gpio_close(&gpio);
            return 1;
        }
        fprintf(LOG_FILE, "Distance: %d cm\n", distance);
        fclose(LOG_FILE);

        // Check if the distance is less than 20 cm
        if (distance < 20) {
            // Open the gate
            if (gpio_get_level(GPIO_PIN) == 0) {
                gpio_write(GPIO_PIN, 1);
                state = 1;
            }
        } else {
            // Close the gate
            if (gpio_get_level(GPIO_PIN) == 1) {
                gpio_write(GPIO_PIN, 0);
                state = 0;
            }
        }

        // Log the gate state
        if (access(LOG_FILE, F_OK) == -1) {
            if (mkdir(LOG_FILE, 0777) < 0) {
                perror("mkdir");
                close(i2c_fd);
                gpio_close(&gpio);
                return 1;
            }
        }
        if (fopen(LOG_FILE, "a") == NULL) {
            perror("fopen");
            close(i2c_fd);
            gpio_close(&gpio);
            return 1;
        }
        fprintf(LOG_FILE, "Gate state: %d\n", state);
        fclose(LOG_FILE);

        // Record the end time
        clock_gettime(CLOCK_MONOTONIC, &end_time);

        // Calculate the time difference
        clock_gettime(CLOCK_MONOTONIC, &time_diff);
        time_diff.tv_sec -= start_time.tv_sec;
        time_diff.tv_nsec -= start_time.tv_nsec;
        if (time_diff.tv_nsec < 0) {
            time_diff.tv_sec--;
            time_diff.tv_nsec += 1000000000;
        }

        // Log the time difference
        if (access(LOG_FILE, F_OK) == -1) {
            if (mkdir(LOG_FILE, 0777) < 0) {
                perror("mkdir");
                close(i2c_fd);
                gpio_close(&gpio);
                return 1;
            }
        }
        if (fopen(LOG_FILE, "a") == NULL) {
            perror("fopen");
            close(i2c_fd);
            gpio_close(&gpio);
            return 1;
        }
        fprintf(LOG_FILE, "Time difference: %d.%09ld\n", time_diff.tv_sec, time_diff.tv_nsec);
        fclose(LOG_FILE);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    gpio_close(&gpio);

    return 0;
}

