#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define PI 3.14159265359
#define SERVO_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SAMPLES 5
#define AVG_WINDOW 100
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define SERVO_MIN 90
#define SERVO_MAX 270
#define SERVO_STEP 1

volatile sig_atomic_t new_pulse = 0;
volatile sig_atomic_t running = 1;

void servo_callback(pigpio *gpio, int gpio_num, int level, void *user_data) {
    if (level == 1) {
        volatile sig_atomic_t *pulse_width = (volatile sig_atomic_t *)user_data;
        *pulse_width += 1;
        new_pulse = 1;
    }
}

void distance_callback(pigpio *gpio, int gpio_num, int level, void *user_data) {
    if (level == 1) {
        volatile sig_atomic_t *pulse_width = (volatile sig_atomic_t *)user_data;
        *pulse_width += 1;
        new_pulse = 1;
    }
}

int main() {
    pigpio *gpio = pigpio_init();
    if (gpio == -1) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    if (gpio_claim_input(TRIGGER_PIN, PI_INPUT_PULL_UP) == -1) {
        printf("Failed to claim input on TRIGGER_PIN\n");
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_claim_input(ECHO_PIN, PI_INPUT_PULL_UP) == -1) {
        printf("Failed to claim input on ECHO_PIN\n");
        gpio_release(TRIGGER_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_claim_output(SERVO_PIN, PI_OUTPUT_PWM) == -1) {
        printf("Failed to claim output on SERVO_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_set_mode(SERVO_PIN, PI_OUTPUT_PWM) == -1) {
        printf("Failed to set mode on SERVO_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MIN) == -1) {
        printf("Failed to set servo pulse width\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_interrupt_enable(gpio, TRIGGER_PIN, distance_callback, &new_pulse) == -1) {
        printf("Failed to enable interrupt on TRIGGER_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_interrupt_enable(gpio, ECHO_PIN, distance_callback, &new_pulse) == -1) {
        printf("Failed to enable interrupt on ECHO_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    int pulse_width = 0;
    int distance = 0;
    int prev_distance = 0;
    int prev_distance_count = 0;
    int prev_distance_time = 0;
    FILE *log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        pigpio_close(gpio);
        return 1;
    }

    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        if (new_pulse) {
            new_pulse = 0;
            if (gpio_get_pulsewidth(SERVO_PIN, &pulse_width) == -1) {
                printf("Failed to get pulse width\n");
                continue;
            }
            if (pulse_width > 1000) {
                printf("Invalid pulse width\n");
                continue;
            }
            if (gpio_get_level(TRIGGER_PIN) == 0) {
                if (gpio_get_level(ECHO_PIN) == 0) {
                    distance = -1;
                } else {
                    int echo_time = (pulse_width / 2) * 29.12;
                    distance = (echo_time / 29.12) * 100;
                    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                        distance = -1;
                    }
                }
            }
        }

        if (distance != prev_distance) {
            if (prev_distance != -1) {
                prev_distance_count++;
                if (prev_distance_count >= SAMPLES) {
                    prev_distance_count = 0;
                    prev_distance = (prev_distance + distance) / 2;
                }
            } else {
                prev_distance = distance;
                prev_distance_count = 1;
            }
        }

        if (prev_distance != -1) {
            double avg_distance = (prev_distance * SAMPLES) / SAMPLES;
            printf("%.2f,%.2f\n", clock_gettime(CLOCK_MONOTONIC.tv_sec + (clock_gettime(CLOCK_MONOTONIC.tv_nsec / 1000000000.0) - start_time.tv_sec) * 1000, avg_distance);
            fprintf(log_file, "%.2f,%.2f\n", clock_gettime(CLOCK_MONOTONIC.tv_sec + (clock_gettime(CLOCK_MONOTONIC.tv_nsec / 1000000000.0) - start_time.tv_sec) * 1000, avg_distance);
        }

        if (distance != -1) {
            if (distance < prev_distance) {
                if (distance < SERVO_MIN) {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MIN);
                } else {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MIN + (SERVO_MAX - SERVO_MIN) * (distance - SERVO_MIN) / (MAX_DISTANCE - MIN_DISTANCE));
                }
            } else if (distance > prev_distance) {
                if (distance > SERVO_MAX) {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MAX);
                } else {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MAX - (SERVO_MAX - SERVO_MIN) * (distance - SERVO_MIN) / (MAX_DISTANCE - MIN_DISTANCE));
                }
            }
        }

        if (gpio_get_level(ECHO_PIN) == 0) {
            if (gpio_get_level(TRIGGER_PIN) == 0) {
                running = 0;
            }
        }
    }

    fclose(log_file);
