volatile sig_atomic_t new_pulse = 0;
volatile sig_atomic_t running = 1;

void servo_callback(pigpio *gpio, int gpio_num, int level, void *user_data) {
    if (level == 1) {
        volatile sig_atomic_t *pulse_width = (volatile sig_atomic_t *)user_data;
        *pulse_width += 1;
        new_pulse = 1;
    }
}

void distance_callback(pigpio *gpio, int gpio_num, int level, void *user_data) {
    if (level == 1) {
        volatile sig_atomic_t *pulse_width = (volatile sig_atomic_t *)user_data;
        *pulse_width += 1;
        new_pulse = 1;
    }
}

