    pigpio *gpio = pigpio_init();
    if (gpio == -1) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    if (gpio_claim_input(TRIGGER_PIN, PI_INPUT_PULL_UP) == -1) {
        printf("Failed to claim input on TRIGGER_PIN\n");
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_claim_input(ECHO_PIN, PI_INPUT_PULL_UP) == -1) {
        printf("Failed to claim input on ECHO_PIN\n");
        gpio_release(TRIGGER_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_claim_output(SERVO_PIN, PI_OUTPUT_PWM) == -1) {
        printf("Failed to claim output on SERVO_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_set_mode(SERVO_PIN, PI_OUTPUT_PWM) == -1) {
        printf("Failed to set mode on SERVO_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MIN) == -1) {
        printf("Failed to set servo pulse width\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_interrupt_enable(gpio, TRIGGER_PIN, distance_callback, &new_pulse) == -1) {
        printf("Failed to enable interrupt on TRIGGER_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    if (gpio_interrupt_enable(gpio, ECHO_PIN, distance_callback, &new_pulse) == -1) {
        printf("Failed to enable interrupt on ECHO_PIN\n");
        gpio_release(TRIGGER_PIN);
        gpio_release(ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }

