    int distance = 0;
    int prev_distance = 0;
    int prev_distance_count = 0;
    int prev_distance_time = 0;
    FILE *log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        pigpio_close(gpio);
        return 1;
