        if (new_pulse) {
            new_pulse = 0;
            if (gpio_get_pulsewidth(SERVO_PIN, &pulse_width) == -1) {
                printf("Failed to get pulse width\n");
                continue;
            }
            if (pulse_width > 1000) {
                printf("Invalid pulse width\n");
                continue;
