            if (gpio_get_level(TRIGGER_PIN) == 0) {
                if (gpio_get_level(ECHO_PIN) == 0) {
                    distance = -1;
                } else {
                    int echo_time = (pulse_width / 2) * 29.12;
                    distance = (echo_time / 29.12) * 100;
