            if (prev_distance != -1) {
                prev_distance_count++;
                if (prev_distance_count >= SAMPLES) {
                    prev_distance_count = 0;
                    prev_distance = (prev_distance + distance) / 2;
                }
            } else {
                prev_distance = distance;
                prev_distance_count = 1;
            }
        }

        if (prev_distance != -1) {
            double avg_distance = (prev_distance * SAMPLES) / SAMPLES;
            printf("%.2f,%.2f\n", clock_gettime(CLOCK_MONOTONIC.tv_sec + (clock_gettime(CLOCK_MONOTONIC.tv_nsec / 1000000000.0) - start_time.tv_sec) * 1000, avg_distance);
            fprintf(log_file, "%.2f,%.2f\n", clock_gettime(CLOCK_MONOTONIC.tv_sec + (clock_gettime(CLOCK_MONOTONIC.tv_nsec / 1000000000.0) - start_time.tv_sec) * 1000, avg_distance);
        }

        if (distance != -1) {
            if (distance < prev_distance) {
                if (distance < SERVO_MIN) {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MIN);
                } else {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MIN + (SERVO_MAX - SERVO_MIN) * (distance - SERVO_MIN) / (MAX_DISTANCE - MIN_DISTANCE));
                }
            } else if (distance > prev_distance) {
                if (distance > SERVO_MAX) {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MAX);
                } else {
                    gpio_set_servo_pulsewidth(SERVO_PIN, SERVO_MAX - (SERVO_MAX - SERVO_MIN) * (distance - SERVO_MIN) / (MAX_DISTANCE - MIN_DISTANCE));
                }
            }
        }

        if (gpio_get_level(ECHO_PIN) == 0) {
            if (gpio_get_level(TRIGGER_PIN) == 0) {
                running = 0;
            }
        }
    }

    fclose(log_file);
    gpio_release(TRIGGER_PIN);
    gpio_release(ECHO_PIN);
    gpio_close(gpio);
