#include <libgpiod-server-async-event-queue-async.h>

#define PROXIMITY_LOG_FILE "proximity.log"

// Define the I2C address and GPIO pin
#define I2C_ADDRESS 0x44
#define GPIO_PIN 27

// Define the threshold value
#define DEFAULT_THRESHOLD 1000

// Define the command-line options
#define OPT_THRESHOLD "t:"
#define OPT_I2C_ADDRESS "a:"

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Close the I2C device
    if (gpiod->i2c->close(gpiod->i2c) < 0) {
        perror("Error closing I2C device");
        exit(1);
    }

    // Close the log file
    if (close(gpiod->log_fd) < 0) {
        perror("Error closing log file");
        exit(1);
    }

    // Terminate the sensor driver
    gpiod->stop();
    gpiod->destroy();
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Parse command-line options
    int threshold = DEFAULT_THRESHOLD;
    int i2c_address = I2C_ADDRESS;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], OPT_THRESHOLD) == 0) {
