#define GPIO_PWM 18
#define PWM_FREQ_MIN 200
#define PWM_FREQ_MAX 2000
#define PWM_DUTY_CYCLE 0.5
#define TRIGGER_PULSE_WIDTH 10
#define ECHO_TIMEOUT 200
#define DISTANCE_MIN 2
#define DISTANCE_MAX 200

// Define structures
typedef struct {
    int freq;
    int prev_freq;
} ThereminState;

// Define the signal handler
void sig_handler(int sig) {
    // Cleanly stop the PWM and terminate the driver
    stop_theremin();
    exit(0);
