// Define the function to read distance from HC-SR04 sensor
int read_distance(pigpio *gpio) {
    int echo_state = gpio_get_input(GPIO_ECHO, gpio);
    if (echo_state == 0) {
        return -1; // Out of range
    }
    int trigger_state = gpio_get_input(GPIO_TRIGGER, gpio);
    if (trigger_state == 0) {
        return -1; // Out of range
    }
    usleep(TRIGGER_PULSE_WIDTH * 1000000);
    int echo_state2 = gpio_get_input(GPIO_ECHO, gpio);
    if (echo_state2 == 0) {
        return -1; // Out of range
    }
    int distance = (echo_state2 - echo_state) * 2;
    return distance;
}

// Define the function to generate PWM
void generate_pwm(pigpio *gpio, int freq) {
    int duty_cycle = (int)(PWM_DUTY_CYCLE * 100);
    int period = 1000000 / freq;
    gpio_set_mode(GPIO_PWM, PI_OUTPUT);
    gpio_set_level(GPIO_PWM, 0);
    usleep(period);
    gpio_set_level(GPIO_PWM, 1);
    usleep(period / 2);
    gpio_set_level(GPIO_PWM, 0);
    usleep(period / 2);
}

// Define the function to stop the PWM
void stop_theremin(pigpio *gpio) {
    gpio_set_mode(GPIO_PWM, PI_OUTPUT);
    gpio_set_level(GPIO_PWM, 0);
}

// Define the function to update the frequency
void update_theremin(ThereminState *state, int distance) {
    if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
        state->freq = state->prev_freq;
    } else {
        int freq = (int)(PWM_FREQ_MIN + log10((double)distance / DISTANCE_MAX) * (PWM_FREQ_MAX - PWM_FREQ_MIN) / log10(DISTANCE_MAX - DISTANCE_MIN));
        if (freq < PWM_FREQ_MIN) {
            freq = PWM_FREQ_MIN;
        } else if (freq > PWM_FREQ_MAX) {
            freq = PWM_FREQ_MAX;
        }
        state->freq = freq;
    }
}

// Define the main function
int main(int argc, char **argv) {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ThereminState state = {0, 0};
    int distance = read_distance(gpio);
    if (distance == -1) {
        printf("Failed to read distance\n");
        stop_theremin(gpio);
        pigpio_close(gpio);
        return 1;
    }
    update_theremin(&state, distance);
    generate_pwm(gpio, state.freq);

    while (1) {
        distance = read_distance(gpio);
        if (distance == -1) {
            printf("Failed to read distance\n");
            stop_theremin(gpio);
            pigpio_close(gpio);
            return 1;
        }
        update_theremin(&state, distance);
        generate_pwm(gpio, state.freq);
        usleep(1000);
    }

    stop_theremin(gpio);
    pigpio_close(gpio);
    return 0;
}

