#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_DURATION 10
#define ECHO_DURATION 50
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define TOO_CLOSE 10

int distance = 0;
int exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set the trigger pin as an output and low
    if (gpioMode(TRIGGER_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    gpioWrite(TRIGGER_PIN, 0);

    // Set the echo pin as an input
    if (gpioMode(ECHO_PIN, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    while (!exit_flag) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        usleep(TRIGGER_DURATION * 1000);

        // Read the echo pin
        int echo_value = gpioRead(ECHO_PIN);
        if (echo_value == 0) {
            // Timeout
            distance = -1;
        } else {
            // Calculate the echo duration
            double echo_duration = (double)usleep(ECHO_DURATION * 1000) / 1000000;
            distance = (echo_duration * 34300) / 2;
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Invalid reading\n");
            } else if (distance < TOO_CLOSE) {
                printf("Too close!\n");
            } else {
                printf("Distance: %.2f cm\n", distance);
            }
        }

        // Release the trigger pin
        gpioWrite(TRIGGER_PIN, 0);

        // Sleep for 500ms
        usleep(500000);
    }

    // Terminate the GPIO driver and exit
    gpioTerminate();
    return 0;
}

