#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/mount.h>

// Define constants
#define SPI_MODE 0
#define SPI_CLOCK 1000000
#define GPIO_CE 8
#define CSV_FILE "distance_log.csv"

// Define error codes
#define ICU_ERROR -1
#define ICU_OK 0

// Define sensor structure
typedef struct {
    int fd;
    pigpio_t *gpio;
    void *mem;
    int mode;
    int clock;
    int ce;
} icu_t;

// Function to initialize the sensor
icu_t* init_icu(int gpio, int clock, int ce) {
    icu_t *icu = malloc(sizeof(icu_t));
    if (icu == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    icu->gpio = pigpio_init();
    if (icu->gpio == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        free(icu);
        return NULL;
    }

    icu->mem = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, -1, 0);
    if (icu->mem == MAP_FAILED) {
        fprintf(stderr, "Failed to map memory\n");
        pigpio_cleanup(&icu->gpio);
        free(icu);
        return NULL;
    }

    icu->mode = SPI_MODE;
    icu->clock = clock;
    icu->ce = ce;

    if (gpioce(icu->gpio, icu->ce, 1) != 0) {
        fprintf(stderr, "Failed to set chip select pin\n");
        munmap(icu->mem, 0);
        pigpio_cleanup(&icu->gpio);
        free(icu);
        return NULL;
    }

    return icu;
}

// Function to read distance from the sensor
int read_distance(icu_t *icu) {
    int ret = spi_xfer(icu->gpio, icu->mem, 0, 2, icu->clock);
    if (ret != 2) {
        fprintf(stderr, "Failed to read from sensor\n");
        return ICU_ERROR;
    }

    return (icu->mem[1] & 0xFF);
}

// Function to write to the CSV file
void write_to_csv(icu_t *icu, int timestamp, int distance) {
    FILE *file = fopen(CSV_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return;
    }

    fprintf(file, "%d,%d\n", timestamp, distance);
    fclose(file);
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    close(icu->fd);
    munmap(icu->mem, 0);
    pigpio_cleanup(&icu->gpio);
    free(icu);
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize the sensor
    icu_t *icu = init_icu(GPIO_CE, SPI_CLOCK, GPIO_CE);
    if (icu == NULL) {
        return 1;
    }

    // Open the CSV file
    icu->fd = open(CSV_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (icu->fd == -1) {
        fprintf(stderr, "Failed to open CSV file\n");
