    int gpio_fd = -1;
    struct gpiod_context *ctx;
    struct gpiod_device *dev;
    struct gpiod_event *event;
    struct gpiod_event_callback *callback;
    struct timespec ts;
    struct tm *timeinfo;
    char timestamp[32];
    uint16_t als_visible;

    // Initialize GPIO
    if (gpio_init() != 0) {
        perror("gpio_init");
        return 1;
    }

    // Open I2C
    if ((i2c_fd = i2c_open(I2C_ADDRESS, 0)) < 0) {
        perror("i2c_open");
        return 1;
    }

    // Create a new gpiod context
    if ((ctx = gpiod_context_new()) == NULL) {
        perror("gpiod_context_new");
        return 1;
    }

    // Create a new gpiod device
    if ((dev = gpiod_device_new(ctx, "als", NULL)) == NULL) {
        perror("gpiod_device_new");
        gpiod_context_free(ctx);
        return 1;
    }

    // Create a new gpiod event
    if ((event = gpiod_event_new(ctx, dev, NULL)) == NULL) {
        perror("gpiod_event_new");
        gpiod_device_free(dev);
        gpiod_context_free(ctx);
        return 1;
    }

    // Create a new gpiod event callback
    if ((callback = gpiod_event_callback_new(event, GPIOD_EVENT_READ, NULL)) == NULL) {
        perror("gpiod_event_callback_new");
        gpiod_event_free(event);
        gpiod_device_free(dev);
        gpiod_context_free(ctx);
        return 1;
    }

    // Set the callback
    if (gpiod_event_callback_set(callback, NULL, NULL)) {
        perror("gpiod_event_callback_set");
        gpiod_event_free(event);
        gpiod_device_free(dev);
        gpiod_context_free(ctx);
        return 1;
    }

    // Set the event to trigger on the ALS visible line
    if (gpiod_event_set_trigger(event, "als_visible", NULL)) {
        perror("gpiod_event_set_trigger");
        gpiod_event_free(event);
        gpiod_device_free(dev);
        gpiod_context_free(ctx);
        return 1;
    }

    // Open the log file
    if ((gpio_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("open");
        gpiod_event_free(event);
        gpiod_device_free(dev);
        gpiod_context_free(ctx);
        return 1;
    }

    // Set the timestamp format
    timeinfo = localtime(&ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Main loop
    while (1) {
        // Read the ALS visible value
        if (i2c_read(i2c_fd, &als_visible, sizeof(als_visible)) < 0) {
            perror("i2c_read");
            break;
        }

        // Write the timestamp and ALS visible value to the log file
        if (write(gpio_fd, timestamp, strlen(timestamp)) < 0) {
            perror("write");
            break;
        }
        if (write(gpio_fd, ",als_visible", 10) < 0) {
            perror("write");
            break;
        }
        if (write(gpio_fd, &als_visible, sizeof(als_visible)) < 0) {
            perror("write");
            break;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    if (close(gpio_fd) < 0) {
        perror("close");
    }
    if (gpiod_event_free(event) < 0) {
        perror("gpiod_event_free");
    }
    if (gpiod_device_free(dev) < 0) {
        perror("gpiod_device_free");
    }
    if (gpiod_context_free(ctx) < 0) {
        perror("gpiod_context_free");
    }
    if (i2c_close(i2c_fd) < 0) {
        perror("i2c_close");
    }

    return 0;
}

