#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"

int main(int argc, char *argv[]) {
    int fd;
    struct i2c_client *client;
    struct i2c_msg msg;
    struct i2c_file *file;
    struct stat sb;
    struct timespec ts;
    struct timespec last_ts;
    uint8_t part_id[3];
    uint16_t measurement_rate;
    uint16_t lux, proximity;
    char log_line[256];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    if ((fd = open(I2C_FILE, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Get I2C file descriptor
    if ((file = i2c_new_file(fd)) < 0) {
        perror("i2c_new_file");
        return 1;
    }

    // Get I2C bus parameters
    if (ioctl(file, I2C_SLAVE, 0) < 0) {
        perror("ioctl");
        return 1;
    }

    // Read part ID
    if (i2c_read(file, 0x00, 3, part_id, 3) < 0) {
        if (errno == EIO) {
            printf("Sensor not found\n");
            close(fd);
            gpioTerminate();
            return 1;
        } else {
            perror("i2c_read");
            return 1;
        }
    }

    // Verify part ID
    if (memcmp(part_id, "SI1182-A-GM", 11) != 0) {
        printf("Invalid part ID\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure measurement rate
    measurement_rate = 0x0000;
    if (i2c_write(file, 0x04, &measurement_rate, 2) < 0) {
        perror("i2c_write");
        return 1;
    }

    // Initialize last timestamp
    clock_gettime(CLOCK_REALTIME, &last_ts);

    while (1) {
        // Read ambient light and proximity data
        if (i2c_read(file, 0x00, 2, &lux, 2) < 0) {
            if (errno == EIO) {
                printf("Sensor not found\n");
                break;
            } else {
                perror("i2c_read");
                break;
            }
        }

        // Read timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Calculate time difference
        timespec_diff(&ts, &last_ts, &ts);
        double time_diff = (double)ts.tv_sec - last_ts.tv_sec + (double)ts.tv_nsec / 1e9 - (double)last_ts.tv_nsec / 1e9;

        // Format timestamp
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S.%3f", localtime(&ts));

        // Log data
        if (file != NULL) {
            sprintf(log_line + strlen(log_line), ",%d,%d", (int)lux, (int)proximity);
            if (write(file, log_line, strlen(log_line)) < 0) {
                perror("write");
                break;
            }
        }

        // Print data
        printf("%s,%d,%d\n", log_line, (int)lux, (int)proximity);

        // Update last timestamp
        last_ts = ts;

        // Sleep for 100ms
        usleep(100000);
    }

    // Close I2C file descriptor
    if (close(fd) < 0) {
        perror("close");
        return 1;
    }

    // Close I2C file
    if (i2c_close(file) < 0) {
        perror("i2c_close");
        return 1;
    }

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

