#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_ADDRESS 0x40
#define I2C_TIMEOUT 100
#define I2C_RETRY 3

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    int log_fd = open("proximity_log.txt", O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    int i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Register I2C callbacks
    pigpio_i2c_set_timeout(i2c_fd, I2C_TIMEOUT);
    pigpio_i2c_set_retry(i2c_fd, I2C_RETRY);

    // Initialize sensor
    if (pigpio_i2c_write(i2c_fd, 0x00, 0x00) < 0) {
        perror("pigpio_i2c_write");
        pigpio_i2c_close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write(i2c_fd, 0x01, 0x00) < 0) {
        perror("pigpio_i2c_write");
        pigpio_i2c_close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_read(i2c_fd, 0x00, 0x00, 0x00, 0x00) < 0) {
        perror("pigpio_i2c_read");
