                int retry = 0;
                while (retry < I2C_RETRY) {
                    if (pigpio_i2c_read(i2c_fd, 0x00, 0x00, 0x00, 0x02, data) < 0) {
                        if (errno == EIO) {
                            retry++;
                            sleep(1);
