                            pigpio_i2c_close(i2c_fd);
                            close(log_fd);
                            gpioTerminate();
                            return 1;
                        }
                    } else {
                        break;
                    }
                }
            } else {
                perror("pigpio_i2c_read");
                pigpio_i2c_close(i2c_fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
        }

        // Combine data
        unsigned int proximity = (data[0] << 8) | data[1];

        // Append to log
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s; %u\n", timestamp, proximity);

        // Flush log
        fflush(log_fd);
    }

    // Cleanup
    pigpio_i2c_close(i2c_fd);
    close(log_fd);
    gpioTerminate();

    return 0;
