#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD 20
#define TRIGGER_PULSE_WIDTH 10
#define MEASUREMENT_INTERVAL 1000 // 1 second

// Define structures for timestamp recording
typedef struct {
    unsigned long start;
    unsigned long end;
} Timestamp;

// Define the interrupt handler function
void interrupt_handler(int signal) {
    // Release the interrupt
    gpioRelease(ECHO_PIN);

    // Record the timestamp of the echo edge
    Timestamp* timestamps = malloc(sizeof(Timestamp));
    timestamps->start = clock_gettime(CLOCK_MONOTONIC);
    gpioEdgeDetect(ECHO_PIN, GPIO_EDGE_RISING, interrupt_handler);
}

// Define the main function
int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Set up the trigger pin as an output
    if (gpioSetMode(TRIGGER_PIN, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up the echo pin as an input with rising edge detection
    if (gpioSetMode(ECHO_PIN, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioEdgeDetect(ECHO_PIN, GPIO_EDGE_RISING, interrupt_handler) < 0) {
        fprintf(stderr, "Failed to set edge detection on echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up the buzzer pin as an output
    if (gpioSetMode(BUZZER_PIN, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Generate a 10 us trigger pulse
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to generate trigger pulse\n");
        gpioTerminate();
        return 1;
    }
    usleep(TRIGGER_PULSE_WIDTH * 1000);

    // Measure the echo pulse width
    Timestamp* timestamps = malloc(sizeof(Timestamp));
    timestamps->start = clock_gettime(CLOCK_MONOTONIC);
    gpioWrite(TRIGGER_PIN, 0);
    gpioEdgeDetect(ECHO_PIN, GPIO_EDGE_FALLING, interrupt_handler);

    // Calculate the distance
    unsigned long pulseWidth = timestamps->end - timestamps->start;
    unsigned long distance = pulseWidth / 2 / 29.1; // 29.1 cm/s

    // Print the distance to stdout every second
    while (1) {
        printf("%f\n", distance);
        sleep(MEASUREMENT_INTERVAL);
        // Set the buzzer pin high if the distance is under 20 cm
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }
    }

    // Clean up
    gpioTerminate();
    free(timestamps);
    return 0;
}

