#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

// Define constants
#define I2C_ADDRESS 0x1D
#define WHO_AM_I 0x00
#define ACCEL_X 0x00
#define ACCEL_Y 0x01
#define ACCEL_Z 0x02
#define GYRO_X 0x03
#define GYRO_Y 0x04
#define GYRO_Z 0x05
#define TEMP 0x06
#define DATA_OFFSET 0x08

// Define structures
typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
    int16_t gx;
    int16_t gy;
    int16_t gz;
    int16_t temp;
} mpu6050_data;

// Define functions
void init_mpu6050(pigpio *gpio) {
    // Initialize I2C
    if (gpio->i2c_open(I2C_BUS1, I2C_ADDRESS, 1000) < 0) {
        printf("I2C open failed\n");
        exit(1);
    }

    // Write WHO_AM_I register
    if (gpio->i2c_write(I2C_BUS1, WHO_AM_I, 0x00) < 0) {
        printf("I2C write failed\n");
        exit(1);
    }

    // Read WHO_AM_I register to verify sensor is present
    uint8_t who_am_i;
    if (gpio->i2c_read(I2C_BUS1, WHO_AM_I, &who_am_i) < 0) {
        printf("I2C read failed\n");
        exit(1);
    }
    if (who_am_i != 0x60) {
        printf("MPU-6050 not found\n");
        exit(1);
    }

    // Reset sensor
    if (gpio->i2c_write(I2C_BUS1, 0x68, 0x00) < 0) {
        printf("I2C write failed\n");
        exit(1);
    }
}

void read_mpu6050(pigpio *gpio) {
    // Read 14-byte data block
    uint8_t data[14];
    if (gpio->i2c_read(I2C_BUS1, DATA_OFFSET, data, 14) < 0) {
        printf("I2C read failed\n");
        exit(1);
    }

    // Parse data
    mpu6050_data data_struct;
    data_struct.ax = (data[ACCEL_X] << 8) | data[ACCEL_X + 1];
    data_struct.ay = (data[ACCEL_Y] << 8) | data[ACCEL_Y + 1];
    data_struct.az = (data[ACCEL_Z] << 8) | data[ACCEL_Z + 1];
    data_struct.gx = (data[GYRO_X] << 8) | data[GYRO_X + 1];
    data_struct.gy = (data[GYRO_Y] << 8) | data[GYRO_Y + 1];
    data_struct.gz = (data[GYRO_Z] << 8) | data[GYRO_Z + 1];
    data_struct.temp = (data[TEMP] << 8) | data[TEMP + 1];

    // Print data
    printf("Accelerometer: %d %d %d\n", data_struct.ax, data_struct.ay, data_struct.az);
    printf("Gyroscope: %d %d %d\n", data_struct.gx, data_struct.gy, data_struct.gz);
    printf("Temperature: %d\n", data_struct.temp);
}

void cleanup(pigpio *gpio) {
    // Close I2C
    gpio->i2c_close(I2C_BUS1);
}

int main() {
    // Initialize GPIO
    pigpio *gpio = pigpio_init();
    if (!gpio) {
        printf("GPIO initialization failed\n");
        exit(1);
    }

    // Initialize I2C
    init_mpu6050(gpio);

    // Read data every 100ms
    while (1) {
        read_mpu6050(gpio);
        sleep(0.1);
    }

    // Clean up
    cleanup(gpio);
    pigpio_close(gpio);
    return 0;
}

