#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x44
#define I2C Bus 1
#define I2C_TIMEOUT 1000
#define I2C_READ_COMMAND 0x00
#define I2C_WRITE_COMMAND 0x01
#define CRC8_POLYNOMINAL 0x31
#define CRC8_INIT_VALUE 0x00

int main(int argc, char *argv[]) {
    int i2c_fd = -1;
    int ret = 0;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Initialize signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }
    sa_int.sa_handler = sigpipe;
    sa_int.sa_mask = sa.sa_mask;
    sa_int.sa_flags = sa.sa_flags;
    if (sigaction(SIGINT, &sa_int, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    sa_term.sa_handler = SIG_IGN;
    sa_term.sa_mask = sa.sa_mask;
    sa_term.sa_flags = sa.sa_flags;
    if (sigaction(SIGTERM, &sa_term, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    // Open I2C bus
    i2c_fd = pigpio_open(I2C Bus, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        perror("pigpio_open");
        return 1;
    }

    while (1) {
        // Trigger high-repeatability measurement
        pigpio_write(i2c_fd, I2C_ADDRESS, I2C_READ_COMMAND);
        usleep(10 * 1000);
        pigpio_write(i2c_fd, I2C_ADDRESS, I2C_WRITE_COMMAND);
        usleep(10 * 1000);

        // Read six-byte response
        uint8_t response[6];
        ret = pigpio_read(i2c_fd, I2C_ADDRESS, response, 6);
        if (ret < 0) {
            perror("pigpio_read");
            continue;
        }

        // Validate CRC-8 checksums
        uint8_t crc8 = (response[5] << 1) | response[4];
        if (crc8 != (crc8 % CRC8_POLYNOMINAL)) {
            fprintf(stderr, "CRC-8 checksum failure\n");
            continue;
        }
        crc8 = (response[1] << 1) | response[0];
        if (crc8 != (crc8 % CRC8_POLYNOMINAL)) {
            fprintf(stderr, "CRC-8 checksum failure\n");
            continue;
        }

        // Extract temperature and humidity
        float temperature = (response[2] + (response[3] << 8)) / 16.0f;
        float humidity = (response[4] + (response[5] << 8)) / 65536.0f;

        // Log readings
        printf("%.2f C, %.2f %% RH\n", temperature, humidity);
        fflush(stdout);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C handle
    pigpio_close(i2c_fd);
    return 0;
}

