#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x5A
#define FILE_NAME "temperature_log.csv"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    int fd = pigpioOpen("/dev/i2c-1", PI_MMAP, 0);
    if (fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    pigpioWrite(fd, I2C_SCL, 100000);
    pigpioWrite(fd, I2C_SDA, 0);

    // Read temperature
    unsigned char temp[2];
    if (pigpioRead(fd, I2C_ADDRESS, 2, temp) < 0) {
        perror("pigpioRead");
        close(log_fd);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Convert temperature to Celsius
    int temp_c = (temp[0] << 8) | temp[1];
    temp_c = (temp_c >> 5) - 40;

    // Append to log file
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_fd, "%s,%d\n", timestamp, temp_c);

    // Sleep for 5 seconds
    sleep(5);

    // Close I2C file descriptor and log file
    close(log_fd);
    pigpioClose(fd);
    gpioTerminate();

    return 0;
}

