#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define I2C_ADDRESS 0x68
#define I2C_ADDRESS_1 0x69
#define MEASUREMENT_COMMAND 0x01
#define CONTINUOUS_MEASUREMENT_COMMAND 0x02
#define CRC_8_POLYNOMIAL 0x31
#define SCALE_FACTOR_SIZE 2
#define MEASUREMENT_SIZE 9
#define FILE_NAME "pressure_log.csv"

// Function to convert raw values to scaled values
float convertRawToScaled(uint8_t rawValue, float scaleFactor) {
    return (float)rawValue * scaleFactor;
}

// Function to validate CRC-8
bool validateCRC8(uint8_t rawValue, uint8_t crcValue) {
    uint8_t polynomial = CRC_8_POLYNOMINAL;
    uint8_t result = 0;
    for (int i = 0; i < 8; i++) {
        result ^= rawValue;
        for (int j = 0; j < 8; j++) {
            if (result & (1 << j)) {
                result ^= polynomial;
            }
        }
    }
    return result == crcValue;
}

// Function to read I2C data
void readI2CData(uint8_t address, uint8_t command, uint8_t* data, int size) {
    int fd = pigpio_i2c_open(I2C_ADDRESS_1, 0);
    if (fd < 0) {
        perror("I2C open");
        exit(1);
    }

    pigpio_i2c_write_byte(fd, address, command);
    pigpio_i2c_read_byte(fd, data, size);
    pigpio_i2c_close(fd);
}

// Function to write to file
void writeToFile(const char* filename, const char* data) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("File open");
        exit(1);
    }

    if (write(fd, data, strlen(data)) < 0) {
        perror("File write");
        exit(1);
    }

    close(fd);
}

// Function to handle SIGINT and SIGTERM signals
void signalHandler(int signal) {
    writeToFile(FILE_NAME, "SIGINT or SIGTERM received. Exiting...\n");
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio init");
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Open file for writing
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("File open");
        exit(1);
    }

    // Initialize I2C bus
    if (pigpio_i2c_init() < 0) {
        perror("I2C init");
        exit(1);
    }

    // Configure sensor for continuous measurement
    uint8_t command = MEASUREMENT_COMMAND;
    uint8_t data[MEASUREMENT_SIZE];
    readI2CData(I2C_ADDRESS, command, data, MEASUREMENT_SIZE);
    if (!validateCRC8(data[MEASUREMENT_SIZE - 1], data[MEASUREMENT_SIZE - 2])) {
        writeToFile(FILE_NAME, "CRC-8 validation failed.\n");
        pigpio_i2c_close();
        close(fd);
        pigpio_i2c_init();
        exit(1);
    }

    // Get scale factors
    uint8_t scaleFactor[SCALE_FACTOR_SIZE];
    readI2CData(I2C_ADDRESS, MEASUREMENT_COMMAND, scaleFactor, SCALE_FACTOR_SIZE);
    if (!validateCRC8(scaleFactor[SCALE_FACTOR_SIZE - 1], scaleFactor[SCALE_FACTOR_SIZE - 2])) {
        writeToFile(FILE_NAME, "CRC-8 validation failed.\n");
        pigpio_i2c_close();
        close(fd);
        pigpio_i2c_init();
        exit(1);
    }

    // Get measurement data
    while (1) {
        // Send continuous measurement command
        command = CONTINUOUS_MEASUREMENT_COMMAND;
        readI2CData(I2C_ADDRESS, command, data, MEASUREMENT_SIZE);
        if (!validateCRC8(data[MEASUREMENT_SIZE - 1], data[MEASUREMENT_SIZE - 2])) {
            writeToFile(FILE_NAME, "CRC-8 validation failed.\n");
            pigpio_i2c_close();
            close(fd);
            pigpio_i2c_init();
            exit(1);
        }

        // Convert raw values to scaled values
        float pressure = convertRawToScaled(data[0], scaleFactor[0]);
        float temperature = convertRawToScaled(data[1], scaleFactor[1]);

        // Append data to file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", localtime(&now));
        char dataToWrite[64];
        sprintf(dataToWrite, "%s,%f,%f\n", timestamp, pressure, temperature);
        writeToFile(FILE_NAME, dataToWrite);

        // Wait at least 1 ms before next measurement
        usleep(1000);
    }

    // Clean up
    pigpio_i2c_close();
    close(fd);
    pigpio_i2c_init();
    exit(0);
}

