#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/statvfs.h>

#define I2C_ADDRESS 0x44
#define I2C_COMMAND_TEMP 0x00
#define I2C_COMMAND_HUMIDITY 0x01
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define I2C_TIMEOUT 20

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    int gpio_fd = -1;
    int retry = 0;
    struct stat sb;
    struct statvfs buf;
    char filename[] = "sensor_data.txt";
    char buffer[2];

    // Initialize GPIO
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Open log file
    if ((log_fd = open(filename, O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        perror("open");
        return 1;
    }

    // Get disk space information
    if (fstat(log_fd, &sb) < 0) {
        perror("fstat");
        return 1;
    }
    if (fstatvfs(log_fd, &buf) < 0) {
        perror("fstatvfs");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, 0)) < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    while (1) {
        // Check if the sensor is present
        if (pigpio_i2c_read(i2c_fd, I2C_ADDRESS, buffer, 1) < 0) {
            if (errno == EIO) {
                retry++;
                usleep(100000);
                continue;
            } else {
                perror("pigpio_i2c_read");
                return 1;
            }
        }

        // Check if the sensor is ready
        if (buffer[0] & 0x80) {
            // Write command
            if (pigpio_i2c_write(i2c_fd, I2C_ADDRESS, I2C_COMMAND_TEMP, 1) < 0) {
                if (errno == EIO) {
                    retry++;
                    usleep(100000);
                    continue;
                } else {
                    perror("pigpio_i2c_write");
                    return 1;
                }
            }

            // Read result
            if (pigpio_i2c_read(i2c_fd, I2C_ADDRESS, buffer, 2) < 0) {
                if (errno == EIO) {
                    retry++;
                    usleep(100000);
                    continue;
                } else {
                    perror("pigpio_i2c_read");
                    return 1;
                }
            }

            // Check if the measurement is ready
            if (buffer[0] & 0x80) {
                // Write command
                if (pigpio_i2c_write(i2c_fd, I2C_ADDRESS, I2C_COMMAND_HUMIDITY, 1) < 0) {
                    if (errno == EIO) {
                        retry++;
                        usleep(100000);
                        continue;
                    } else {
                        perror("pigpio_i2c_write");
                        return 1;
                    }
                }

                // Read result
                if (pigpio_i2c_read(i2c_fd, I2C_ADDRESS, buffer, 2) < 0) {
                    if (errno == EIO) {
                        retry++;
                        usleep(100000);
                        continue;
                    } else {
                        perror("pigpio_i2c_read");
                        return 1;
                    }
                }

                // Log data
                time_t now = time(NULL);
                struct tm *ltm = localtime(&now);
                fprintf(log_fd, "%04d-%02d-%02d %02d:%02d:%02d %f %f\n",
                        ltm->tm_year + 1900, ltm->tm_mon + 1, ltm->tm_mday, ltm->tm_hour, ltm->tm_min, ltm->tm_sec,
                        (double)buffer[0] / 10.0, (double)buffer[1] / 10.0);
                printf("%04d-%02d-%02d %02d:%02d:%02d %f %f\n",
                        ltm->tm_year + 1900, ltm->tm_mon + 1, ltm->tm_mday, ltm->tm_hour, ltm->tm_min, ltm->tm_sec,
                        (double)buffer[0] / 10.0, (double)buffer[1] / 10.0);
            }
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    if (close(log_fd) < 0) {
        perror("close");
        return 1;
    }

    // Close GPIO
    gpio_close(gpio_fd);

    return 0;
}

