        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, 0)) < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    while (1) {
        // Check if the sensor is present
        if (pigpio_i2c_read(i2c_fd, I2C_ADDRESS, buffer, 1) < 0) {
            if (errno == EIO) {
                retry++;
                usleep(100000);
                continue;
            } else {
                perror("pigpio_i2c_read");
                return 1;
            }
        }

        // Check if the sensor is ready
        if (buffer[0] & 0x80) {
            // Write command
            if (pigpio_i2c_write(i2c_fd, I2C_ADDRESS, I2C_COMMAND_TEMP, 1) < 0) {
                if (errno == EIO) {
                    retry++;
                    usleep(100000);
                    continue;
                } else {
                    perror("pigpio_i2c_write");
                    return 1;
                }
            }

            // Read result
            if (pigpio_i2c_read(i2c_fd, I2C_ADDRESS, buffer, 2) < 0) {
                if (errno == EIO) {
                    retry++;
                    usleep(100000);
                    continue;
                } else {
                    perror("pigpio_i2c_read");
                    return 1;
                }
            }

            // Check if the measurement is ready
            if (buffer[0] & 0x80) {
                // Write command
                if (pigpio_i2c_write(i2c_fd, I2C_ADDRESS, I2C_COMMAND_HUMIDITY, 1) < 0) {
                    if (errno == EIO) {
                        retry++;
                        usleep(100000);
                        continue;
                    } else {
                        perror("pigpio_i2c_write");
                        return 1;
                    }
                }

                // Read result
                if (pigpio_i2c_read(i2c_fd, I2C_ADDRESS, buffer, 2) < 0) {
                    if (errno == EIO) {
                        retry++;
                        usleep(100000);
                        continue;
                    } else {
                        perror("pigpio_i2c_read");
                        return 1;
                    }
                }

                // Log data
                time_t now = time(NULL);
                struct tm *ltm = localtime(&now);
                fprintf(log_fd, "%04d-%02d-%02d %02d:%02d:%02d %f %f\n",
                        ltm->tm_year + 1900, ltm->tm_mon + 1, ltm->tm_mday, ltm->tm_hour, ltm->tm_min, ltm->tm_sec,
                        (double)buffer[0] / 10.0, (double)buffer[1] / 10.0);
                printf("%04d-%02d-%02d %02d:%02d:%02d %f %f\n",
                        ltm->tm_year + 1900, ltm->tm_mon + 1, ltm->tm_mday, ltm->tm_hour, ltm->tm_min, ltm->tm_sec,
                        (double)buffer[0] / 10.0, (double)buffer[1] / 10.0);
            }
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    if (close(log_fd) < 0) {
        perror("close");
        return 1;
    }

    // Close GPIO
    gpio_close(gpio_fd);

    return 0;
}
```

This code uses the pigpio library to interact with the I2C bus and the Raspberry Pi's GPIO pins. It initializes the GPIO, opens the log file, and opens the I2C bus. It then enters a loop where it checks if the sensor is present and ready, writes the command, reads the result, and logs the data. If the sensor is not present or a bus error occurs, it retries the operation. If the sensor is ready, it logs the data and sleeps for 5 seconds before repeating the process. Finally, it closes the I2C handle, log file, and GPIO.

