#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_ADDRESS 0x44
#define I2C Bus 1
#define CRC_POLYNOMINAL 0x31
#define CRC_INIT_VALUE 0x00
#define MEASUREMENT_COMMAND 0x00
#define MEASUREMENT_COUNT 3
#define MEASUREMENT_DELAY 15
#define FILE_NAME "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file handles
    int i2c_fd = pigpioOpen(I2C Bus, I2C_ADDRESS, PI_MMAPI);
    if (i2c_fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Open log files
    FILE *log_file = fopen(FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    FILE *error_log = fopen(ERROR_LOG, "a");
    if (error_log == NULL) {
        perror("fopen");
        fclose(log_file);
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up I2C clock
    pigpioWrite(i2c_fd, I2C Bus, PI_I2C_CLOCK, 100000);

    while (1) {
        // Send measurement command
        pigpioWrite(i2c_fd, I2C Bus, PI_I2C_WRITE, MEASUREMENT_COMMAND);
        usleep(MEASUREMENT_DELAY * 1000);

        // Read measurement response
        uint8_t response[MEASUREMENT_COUNT];
        if (pigpioRead(i2c_fd, I2C Bus, response, MEASUREMENT_COUNT) < MEASUREMENT_COUNT) {
            fprintf(stderr, "I2C read error\n");
            pigpioClose(i2c_fd);
            gpioTerminate();
            fclose(log_file);
            fclose(error_log);
            return 1;
        }

        // Validate CRC
        uint8_t crc = response[MEASUREMENT_COUNT - 1];
