#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SENSIRION_I2C_ADDRESS 0x44
#define SENSIRION_COMMAND_READ 0x00
#define SENSIRION_COMMAND_READ_HR 0x01
#define SENSIRION_CRC8_POLYNOMIAL 0x31
#define SENSIRION_CRC8_INIT_VALUE 0x00
#define SENSIRION_CRC8_TABLE 0x00, 0x0A, 0x16, 0x1E, 0x28, 0x34, 0x3A, 0x46, 0x52, 0x60, 0x6E, 0x7C, 0x88, 0x9C, 0xA0, 0xB4, 0xC0, 0xD6, 0xE2, 0xF6, 0x72, 0x80, 0x96, 0xA8, 0xC8, 0xE8, 0xF8, 0x00

#define SENSIRION_DATA_SIZE 6

int main() {
    int fd;
    struct timespec start_time;
    struct timespec elapsed_time;
    struct timespec interval;
    struct sigaction sa;
    char buffer[SENSIRION_DATA_SIZE];
    char log_file_name[] = "sht40_log.txt";
    char log_file_path[256];
    struct stat sb;

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE, SENSIRION_I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set the command
    if (ioctl(fd, SIOCGICSR, &sa) < 0) {
        perror("SIOCGICSR");
        return 1;
    }
    if (sa.iccr & I2C_SLAVE) {
        if (ioctl(fd, SIOCSICSR, &sa) < 0) {
            perror("SIOCSICSR");
            return 1;
        }
    }

    // Open the log file
    sprintf(log_file_path, "%s", log_file_name);
    if (access(log_file_path, F_OK) == -1) {
        if (mkdir(log_file_path, 0777) < 0) {
            perror("mkdir");
            return 1;
        }
    }
    if (open(log_file_path, O_WRONLY | O_CREAT | O_APPEND, 0666) < 0) {
        perror("open");
        return 1;
    }

    // Set up the signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Wait for 5 seconds
        clock_gettime(CLOCK_REALTIME, &start_time);
        while (clock_gettime(CLOCK_REALTIME, &elapsed_time) == 0) {
            usleep(500000);
        }
        interval.tv_sec = elapsed_time.tv_sec - start_time.tv_sec;
        interval.tv_nsec = elapsed_time.tv_nsec - start_time.tv_nsec;
        if (interval.tv_sec < 0) {
            interval.tv_sec += 1000000000;
            interval.tv_nsec -= 100000000;
        }
        if (interval.tv_nsec < 0) {
            interval.tv_nsec += 1000000000;
            interval.tv_sec--;
        }

        // Issue the high-repeatability measurement command
        if (ioctl(fd, SENSIRION_COMMAND_READ_HR, 0) < 0) {
            perror("SENSIRION_COMMAND_READ_HR");
            continue;
        }

        // Wait for at least 8.5 ms
        usleep(850000);

        // Read the six-byte response
        if (read(fd, buffer, SENSIRION_DATA_SIZE) < SENSIRION_DATA_SIZE) {
            perror("read");
            continue;
        }

        // Validate the CRC
        unsigned char crc = (buffer[0] << 8) | buffer[1];
        for (int i = 0; i < SENSIRION_CRC8_TABLE_SIZE; i++) {
            if ((crc ^ SENSIRION_CRC8_TABLE[i]) == buffer[SENSIRION_DATA_SIZE - 1]) {
                break;
            }
        }
        if (i == SENSIRION_CRC8_TABLE_SIZE) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        // Validate the temperature and humidity values
        float temperature = (buffer[2] << 8) | buffer[3];
        float humidity = (buffer[4] << 8) | buffer[5];
        if (temperature < -273.15 || temperature > 1000 || humidity < 0 || humidity > 100) {
            fprintf(stderr, "Invalid temperature or humidity value\n");
            continue;
        }

        // Log the reading
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        fprintf(log_file_path, "%04d-%02d-%02d %02d:%02d:%02d %f %f\n", time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday, time_info->tm_hour, time_info->tm_min, time_info->tm_sec, temperature, humidity);
    }

    // Clean up
    close(fd);
    close(log_file);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    // Close the I2C file descriptor
    close(fd);

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }

    // Exit the program
    exit(0);
}

