#include <time.h>

#define I2C_ADDRESS 0x68
#define I2C_COMMAND 0x00
#define I2C_READ 0x01
#define I2C_WRITE 0x02
#define CRC8_POLYNOM 0x31
#define CRC8_INIT 0x00
#define PRESSURE MSB 0x00
#define PRESSURE_LSB 0x01
#define TEMPERATURE_MSB 0x02
#define TEMPERATURE_LSB 0x03
#define CRC8_CHECK 0x04
#define CRC8_CHECK2 0x05
#define FILE_NAME "airflow_data.txt"

int main() {
    int fd;
    int i2c_fd;
    int ret;
    unsigned char command = I2C_COMMAND;
    unsigned char data[6];
    unsigned char crc8_check;
    unsigned char crc8_check2;
    unsigned char pressure;
    unsigned char temperature;
    struct timespec timestamp;
    struct stat sb;
    struct stat sb2;
    char filename[256];
    char line[256];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (i2c_set_clock_speed(fd, 100000) < 0) {
        perror("i2c_set_clock_speed");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((sb.st_mode = fstat(fileno(stdout), &sb) < 0) {
        perror("fstat");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (sb.st_mode & S_IWUSR) {
        if ((fd = open(FILE_NAME, O_RDWR | O_CREAT | O_WRONLY | O_APPEND, 0644)) < 0) {
            perror("open");
            close(fd);
            gpioTerminate();
            return 1;
        }
    }

    while (1) {
        // Write command to I2C bus
        if (i2c_write(fd, I2C_ADDRESS, &command, 1) < 0) {
            perror("i2c_write");
            break;
        }

        // Wait for 1 ms
        usleep(1000);

        // Read response from I2C bus
        if (i2c_read(fd, I2C_ADDRESS, data, 6, 1000) < 0) {
            perror("i2c_read");
            break;
        }

        // Validate CRC-8 checks
        crc8_check = data[5];
        crc8_check2 = data[4];
        if ((crc8_check != (crc8_check2 ^ (crc8_check2 << 1))) || (crc8_check2 != (crc8_check2 ^ (crc8_check2 << 2)))) {
            printf("CRC-8 check failed\n");
            break;
        }

        // Extract pressure and temperature
        pressure = data[0];
        temperature = data[2];

        // Convert pressure and temperature to pascals and degrees Celsius
        unsigned long long pressure_value = (pressure << 8) | data[1];
        unsigned long long temperature_value = (temperature << 8) | data[3];

        // Create timestamp
        clock_gettime(CLOCK_REALTIME, &timestamp);

        // Append to log file
        if (snprintf(line, sizeof(line), "%ld,%llu,%llu", timestamp.tv_sec, pressure_value, temperature_value) < 0) {
            perror("snprintf");
            break;
        }
        if (write(fd, line, strlen(line)) < 0) {
            perror("write");
            break;
        }

        // Close log file
        if (fclose(fd) < 0) {
            perror("fclose");
            break;
        }
    }

    // Close I2C file descriptor
    if (close(fd) < 0) {
        perror("close");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

