#include <errno.h>

#define BUFFER_SIZE 20
#define BUFFER_ADDRESS 0x20000000
#define I2C_ADDRESS 0x40
#define I2C_REG_CO2 0x00
#define I2C_REG_TEMP 0x01
#define I2C_REG_HUMID 0x02
#define I2C_REG_CHECKSUM 0x03
#define GPIO_LED 17
#define GPIO_DIR 17
#define GPIO_PIN 17

int main() {
    int fd;
    int i;
    unsigned char buffer[BUFFER_SIZE];
    unsigned char co2, temp, humid;
    unsigned char checksum;
    int gpio;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize GPIO
    gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO direction
    gpio = gpioMode GPIO_DIR | GPIO_PIN;
    if (gpio < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Install SIGINT/SIGTERM handler
    sa.sa_handler = sigHandler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    fd = i2cOpen(1, I2C_ADDRESS, 0);
    if (fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Read and validate checksum
    if (i2cRead(fd, I2C_REG_CHECKSUM, &checksum) < 0) {
        perror("i2cRead");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Read CO2, temperature and humidity
    if (i2cRead(fd, I2C_REG_CO2, &co2) < 0) {
        perror("i2cRead");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cRead(fd, I2C_REG_TEMP, &temp) < 0) {
        perror("i2cRead");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cRead(fd, I2C_REG_HUMID, &humid) < 0) {
        perror("i2cRead");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Validate checksum
    if (checksum != (co2 + (temp << 8) + (humid << 16)) & 0xFF) {
        printf("Invalid checksum\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Store reading in circular buffer
    for (i = 0; i < BUFFER_SIZE; i++) {
        if (i == BUFFER_SIZE) {
            i--;
        }
        buffer[i] = co2;
        buffer[i + 1] = temp;
        buffer[i + 2] = humid;
    }

