            i2cClose(fd);
            gpioTerminate();
            return 1;
        }
        if (i2cRead(fd, I2C_REG_HUMID, &humid) < 0) {
            perror("i2cRead");
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }

        // Validate checksum
        if (checksum != (co2 + (temp << 8) + (humid << 16)) & 0xFF) {
            printf("Invalid checksum\n");
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }

        // Store reading in circular buffer
        for (i = 0; i < BUFFER_SIZE; i++) {
