#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define PWM_PIN 7
#define CYCLE_TIMEOUT 50
#define SAMPLE_INTERVAL 5000000 // 5 seconds
#define MIN_TEMP -40
#define MAX_TEMP 150

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up the PWM pin as an output
    if (gpioSetMode(PWM_PIN, GPIO_MODE PWM) < 0) {
        syslog(LOG_ERR, "Failed to set PWM mode");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set the PWM frequency to 100 Hz
    if (gpioPWMWrite(PWM_PIN, 100) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set the PWM duty cycle to 0
    if (gpioPWMWrite(PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set the PWM pin as an output
    if (gpioPWMWrite(PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set PWM pin as output");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Initialize the timestamp
    clock_t start_time = clock();

    int failure_count = 0;
    while (1) {
        // Wait for the PWM edge
        struct timespec wait_time;
        clock_gettime(CLOCK_MONOTONIC, &wait_time);
        while (wait_time.tv_sec != start_time.tv_sec || wait_time.tv_nsec != start_time.tv_nsec) {
            clock_gettime(CLOCK_MONOTONIC, &wait_time);
        }
        if (gpioEdgeRead(PWM_PIN) == 0) {
            // Wait for the next edge
            clock_gettime(CLOCK_MONOTONIC, &wait_time);
            while (wait_time.tv_sec != start_time.tv_sec || wait_time.tv_nsec != start_time.tv_nsec) {
                clock_gettime(CLOCK_MONOTONIC, &wait_time);
            }
            if (gpioEdgeRead(PWM_PIN) == 1) {
                // Calculate the cycle time
                clock_t end_time = clock();
                double cycle_time = (end_time - start_time) / CLOCKS_PER_SEC;
                start_time = end_time;

                // Calculate the high pulse width
                clock_t high_time = clock();
                while (gpioEdgeRead(PWM_PIN) == 0) {
