#include <errno.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x44
#define I2C_CLOCK 1000000
#define I2C_DATA 0
#define CRC_LENGTH 2
#define FILE_NAME "environmental_data.txt"

// Function to calculate CRC-8
uint8_t calculate_crc(uint8_t *data, uint8_t length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc = (crc >> 1);
        if ((crc & 0x80) == 0) {
            crc += data[i];
        }
        crc = (crc & 0xFF);
    }
    return crc;
}

// Function to read temperature and humidity from the SHT35-DIS-B sensor
void read_sensirion_data(uint8_t *temperature, uint8_t *humidity) {
    uint8_t crc_temp, crc_humidity;
    uint8_t result[6];

    // Wait for at least 15 ms for the 6-byte result
    usleep(15000);

    // Read the 6-byte result
    if (gpiod_i2c_read(I2C_ADDRESS, I2C_CLOCK, I2C_DATA, result, 6) != 0) {
        // Retry up to three times with a one-second delay
        for (int i = 0; i < 3; i++) {
            if (gpiod_i2c_read(I2C_ADDRESS, I2C_CLOCK, I2C_DATA, result, 6) != 0) {
                printf("I2C read failed. Retrying...\n");
                usleep(1000);
            } else {
                break;
            }
        }
        if (gpiod_i2c_read(I2C_ADDRESS, I2C_CLOCK, IC_DATA, result, 6) != 0) {
            printf("I2C read failed after retries. Logging NaN values.\n");
            *temperature = 0xFF;
            *humidity = 0xFF;
            return;
        }
    }

    // Validate the 8-bit CRC for both the temperature and humidity words
    crc_temp = result[0];
    crc_humidity = result[1];
    if (calculate_crc(result, 2) != crc_temp || calculate_crc(result + 2, 2) != crc_humidity) {
        printf("CRC validation failed. Logging NaN values.\n");
        *temperature = 0xFF;
        *humidity = 0xFF;
        return;
    }

    // Convert the raw values to degrees Celsius and percent relative humidity
    *temperature = (result[4] * 0.0625) - 273.15;
    *humidity = (result[5] * 0.0625);

    // Add a sinusoidal offset to simulate a greenhouse environment
    *temperature += (sin((time(NULL) / 3600.0) * 2) * 2) + 2;
    *humidity += (sin((time(NULL) / 3600.0) * 5) * 5);

    // Log the reading with an ISO-8601 UTC timestamp
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        printf("Failed to open log file.\n");
        return;
    }
    fprintf(file, "%04d-%02d-%02dT%02d:%02d:%02dZ %f°C %f%% RH\n",
            time(NULL) / 86400, (time(NULL) / 3600) % 24, (time(NULL) / 60) % 60, time(NULL) % 60, time(NULL) % 60, *temperature, *humidity);
    fclose(file);
}

int main() {
    // Initialize the I2C driver
    if (gpiod_i2c_init() != 0) {
        printf("I2C initialization failed.\n");
        return 1;
    }

    // Open the I2C handle
    if (gpiod_i2c_open(I2C_ADDRESS, I2C_CLOCK, I2C_DATA) != 0) {
        printf("I2C open failed.\n");
        gpiod_i2c_cleanup();
        return 1;
    }

    // Read temperature and humidity from the SHT35-DIS-B sensor
    uint8_t temperature, humidity;
    while (1) {
        read_sensirion_data(&temperature, &humidity);
        usleep(5000);
    }

    // Close the I2C handle and log file
    gpiod_i2c_close(I2C_ADDRESS);
    fclose(FILE_NAME);

    // Clean up
    gpiod_i2c_cleanup();
    return 0;
}

