#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x44
#define I2C_CLOCK_STRETCH 0x00
#define I2C_READ_COMMAND 0x00
#define I2C_WRITE_COMMAND 0x01
#define CRC8_POLYNOMINAL 0x31
#define CRC8_INIT_VALUE 0x00

#define CSV_FILE "environment.csv"

int main() {
    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() == -1) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Check if file exists and create it if not
    struct stat sb;
    if (stat(CSV_FILE, &sb) == -1) {
        if (mkdir(CSV_FILE, 0644) == -1) {
            perror("mkdir");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Open CSV file for writing
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Send single-shot high-repeatability measurement command
        uint8_t command = I2C_READ_COMMAND;
        uint8_t crc8 = crc8(command, CRC8_POLYNOMINAL);
        if (write(i2c_fd, &command, 1) != 1) {
            perror("write");
            continue;
        }
        if (write(i2c_fd, &crc8, 1) != 1) {
            perror("write");
            continue;
        }
        usleep(15 * 1000); // wait for 15ms

        // Read six-byte result
        uint8_t result[6];
        if (read(i2c_fd, result, 6) != 6) {
            perror("read");
            continue;
        }

        // Validate CRC-8 checksum
        uint8_t crc8_calculated = crc8(result, CRC8_POLYNOMINAL);
        if (crc8_calculated != result[5]) {
            fprintf(stderr, "CRC-8 checksum error\n");
            continue;
        }

        // Validate initial value
        if (result[0] != I2C_ADDRESS) {
            fprintf(stderr, "Invalid initial value\n");
            continue;
        }

        // Extract temperature and humidity
        float temperature = (result[1] << 8) | result[2];
        float humidity = (result[3] << 8) | result[4];

        // Log reading to CSV file
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(fp, "%s,%f,%f\n", timestamp, temperature, humidity);
        fflush(fp);

        // Wait for 5 seconds before taking the next reading
        usleep(5 * 1000 * 1000);
    }

    // Clean up
    fclose(fp);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    gpioTerminate();
    exit(0);
}

uint8_t crc8(uint8_t data, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < 8; i++) {
        crc = (crc >> 1);
        if ((crc & 1) && polynomial) {
            crc ^= polynomial;
        }
        crc = (crc ^ data);
    }
    return crc;
}

