    if (fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    int csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (csv_fd < 0) {
        perror("open");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up I2C pins
    gpioSetMode(2, PI_INPUT);
    gpioSetMode(3, PI_INPUT);
    gpioPullUpDn(2, PI_PUD_UP);
    gpioPullUpDn(3, PI_PUD_UP);

    struct timespec start_time;
    struct timespec last_time;
    struct timeval tv;
    struct tm *timeinfo;
    char timestamp[32];
    int temperature, humidity, crc8;
    bool error = false;

    while (1) {
        // Get current time
        gettimeofday(&tv, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read I2C data
        if (pigpioI2CWrite(1, I2C_ADDRESS, 0x00, 1) < 0) {
            error = true;
            printf("I2C open failed\n");
            break;
        }
        if (pigpioI2CRead(1, I2C_ADDRESS, 0x00, 3, &temperature, &humidity, &crc8) < 0) {
            error = true;
            printf("I2C read failed\n");
            pigpioI2CWrite(1, I2C_ADDRESS, 0x00, 1);
            sleep(1);
            continue;
        }

        // Verify CRC8 checksum
        if (crc8 != (crc8 & 0x7F) == (crc8 >> 7)) {
            error = true;
            printf("CRC error\n");
            pigpioI2CWrite(1, I2C_ADDRESS, 0x00, 1);
            sleep(1);
            continue;
        }

        // Write to CSV file
        if (error) {
            fprintf(csv_fd, "%s,ERROR,ERROR\n", timestamp);
        } else {
            fprintf(csv_fd, "%s,%d,%d\n", timestamp, temperature, humidity);
        }

        // Reset I2C
        pigpioI2CWrite(1, I2C_ADDRESS, 0x00, 1);

        // Sleep for 5 seconds
        struct timespec sleep_time;
        clock_gettime(CLOCK_REALTIME, &sleep_time);
        sleep_time.tv_sec += 5;
        sleep(sleep_time.tv_sec - sleep_time.tv_sec);
    }

    // Close I2C file descriptor
    pigpioClose(fd);

    // Close CSV file
    close(csv_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
