    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS2) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write command to sensor
    ret = write(i2c_fd, command, 2);
    if (ret < 0) {
        perror("write");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for conversion
    usleep(CONVERSION_TIME * 1000000);

    // Read response from sensor
    ret = read(i2c_fd, response, 9);
    if (ret < 0) {
        perror("read");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Validate CRC-8 for pressure and temperature
    if (response[8] != (response[0] ^ response[1] ^ response[2] ^ response[3] ^ response[4] ^ response[5] ^ response[6] ^ response[7])) {
        perror("CRC-8 error");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Convert raw data to floating-point values
    pressure = (response[0] << 8) | response[1];
    pressure /= 256;
    temperature = (response[6] << 8) | response[7];
    temperature /= 256;

    // Log data
    if (fwrite(&pressure, sizeof(float), 1, fd) < 0) {
        perror("fwrite");
    }
    if (fwrite(&temperature, sizeof(float), 1, fd) < 0) {
        perror("fwrite");
    }

    // Close I2C handle
    close(i2c_fd);

    // Terminate pigpio
    gpioTerminate();

    // Close file
    if (close(fd) < 0) {
        perror("close");
    }

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C handle
    close(1);

    // Terminate pigpio
    gpioTerminate();

    // Close file
    if (close(1) < 0) {
        perror("close");
    }

    // Exit
    exit(0);
}

