#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x68
#define I2C_ADDRESS_1 0x69
#define I2C Bus 1
#define CRC_8_POLYNOMIAL 0x11
#define MEASUREMENT_COMMAND 0x01
#define CONVERSION_TIME 45
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 5

int main() {
    int fd;
    int i2c_fd;
    int status;
    unsigned char buffer[9];
    struct timespec start_time;
    struct timespec end_time;
    struct timespec interval;
    struct stat log_stat;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C
    if ((i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS, 100)) < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    if ((fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("open");
        return 1;
    }

    while (1) {
        // Send measurement command
        if (i2cWrite(i2c_fd, MEASUREMENT_COMMAND, 1) < 0) {
            perror("i2cWrite");
            continue;
        }

        // Wait for conversion
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        usleep(CONVERSION_TIME * 1000);

        // Read response
        if (i2cRead(i2c_fd, buffer, 9, 100) < 0) {
            perror("i2cRead");
            continue;
        }

        // Validate CRC-8
        if (validate_crc_8(buffer, 8, CRC_8_POLYNOMINAL) < 0) {
            perror("validate_crc_8");
            continue;
        }

        // Calculate pressure
        unsigned int pressure = (buffer[0] << 8) | buffer[1];
        unsigned int pressure2 = (buffer[2] << 8) | buffer[3];
        unsigned int pressure3 = (buffer[4] << 8) | buffer[5];
        unsigned int pressure4 = (buffer[6] << 8) | buffer[7];
        unsigned int pressure5 = (buffer[8] << 8) | buffer[9];

        // Calculate mean pressure
        unsigned int mean_pressure = (pressure + pressure2 + pressure3 + pressure4 + pressure5) / 5;

        // Log pressure
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        interval.tv_sec = end_time.tv_sec - start_time.tv_sec;
        interval.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;
        interval.tv_nsec += (interval.tv_sec * 1000000000);
        interval.tv_sec = interval.tv_nsec / 1000000000;
        interval.tv_nsec %= 1000000000;
        if (fstat(fd, &log_stat) < 0) {
            perror("fstat");
            continue;
        }
        if (ftruncate(fd, log_stat.st_size + sizeof(int) + sizeof(int) + sizeof(int) + sizeof(int) + sizeof(int)) < 0) {
            perror("ftruncate");
            continue;
        }
        if (write(fd, &interval, sizeof(interval)) < 0) {
            perror("write");
            continue;
        }
        if (write(fd, &mean_pressure, sizeof(mean_pressure)) < 0) {
            perror("write");
            continue;
        }

        // Sleep before next iteration
        usleep(LOG_INTERVAL * 1000000);
    }

    // Close I2C
    if (i2cClose(i2c_fd) < 0) {
        perror("i2cClose");
    }

    // Close log file
    if (close(fd) < 0) {
        perror("close");
    }

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

int validate_crc_8(unsigned char *data, int length, int polynomial) {
    unsigned char crc = 0;
    for (int i = 0; i < length; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ polynomial;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

