    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Read differential pressure
        unsigned char pressure = 0;
        if (i2c_rdwr(i2c_fd, I2C_ADDRESS, 0x00, &pressure, 1, 0) < 0) {
            perror("i2c_rdwr");
            continue;
        }

        // Compute flow rate
        float pressure_diff = (pressure - 0x00) * 0.01f; // 1 LSB = 0.01 Pa
        float flow_rate = pressure_diff / 0.1f; // 0.1 Pa = 1 L/min

        // Log measurement
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%f\n", timestamp, flow_rate);
        fflush(log_fd);

        // Update PWM duty cycle
        int duty_cycle = (int)(flow_rate * 100);
        if (gpioPWM(FAN_GPIO, PWM_FREQ, duty_cycle) < 0) {
            perror("gpioPWM");
            return 1;
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    gpioPWM(FAN_GPIO, PWM_FREQ, 0);
    close(log_fd);
    close(i2c_fd);
    gpioCleanUp();
    return 0;
}

