#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define BUFFER_SIZE 10
#define LED_GPIO 17
#define I2C_ADDRESS 0x44

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the I2C bus
    int fd = pigpioOpen(I2C_ADDRESS, PI_MMAP, 0);
    if (fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Create a circular buffer to store temperature readings
    void* buffer = mmap(NULL, BUFFER_SIZE * sizeof(float), PROT_READ | PROT_WRITE, MAP_SHARED, -1, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize the buffer with zeros
    memset(buffer, 0, BUFFER_SIZE * sizeof(float));

    // Initialize the running average
    float sum = 0.0;

    // Initialize the index of the next free slot in the buffer
    int index = 0;

    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Read a temperature from the sensor
        int bytes_read = pigpioI2CRead(fd, BUFFER_SIZE, 0x00, 0x00);
        if (bytes_read < 0) {
            continue;
        }

        // Convert the temperature to a float
        float temperature = (bytes_read > 0) ? (float) (buffer[0] << 8 | buffer[1]) / 16.0 : 0.0;

        // Add the temperature to the running average
        sum += temperature;
        index = (index + 1) % BUFFER_SIZE;

        // Update the buffer
        buffer[index] = temperature;

        // Check if the average temperature exceeds 28.0°C
        if (sum / BUFFER_SIZE > 28.0) {
            gpioWrite(LED_GPIO, HIGH);
        } else {
            gpioWrite(LED_GPIO, LOW);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpioClose(fd);
    munmap(buffer, BUFFER_SIZE * sizeof(float));
    gpioTerminate();

    return 0;
}

void sigintHandler(int sig) {
    // Turn off the LED
    gpioWrite(LED_GPIO, LOW);

    // Close the I2C handle
    pigpioClose(0);

    // Clean up
    gpioTerminate();

    // Exit
    exit(0);
}

