#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <inttypes.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x5A
#define I2C_TIMEOUT 100
#define LOG_FILE "air_quality.log"

// Define the states for ventilation control
enum ventilation_state {
    OFF,
    LOW,
    HIGH
};

// Define the sensor data structure
typedef struct {
    uint32_t timestamp;
    uint16_t co2;
    float temperature;
    uint16_t humidity;
} sensor_data_t;

// Define the ventilation control function
void ventilation_control(uint16_t co2) {
    if (co2 < 800) {
        gpio_set_mode(17, GPIO_MODE_OUTPUT);
        gpio_write(17, 0);
    } else if (co2 < 1200) {
        gpio_set_mode(17, GPIO_MODE_OUTPUT);
        gpio_write(17, 1);
    } else {
        gpio_set_mode(17, GPIO_MODE_OUTPUT);
        gpio_write(17, 2);
    }
}

// Define the I2C callback function
void i2c_callback(gpio_i2c_t *i2c, gpio_i2c_event_t event, void *user_data) {
    sensor_data_t *data = (sensor_data_t *)user_data;
    switch (event) {
        case GPIO_I2C_EVENT_READ:
            if (gpio_i2c_read(i2c, I2C_ADDRESS, 6, (uint8_t *)data, 6) == 0) {
                data->timestamp = time(NULL);
                data->co2 = data[0];
                data->temperature = (data[1] << 8) | data[2];
                data->humidity = (data[3] << 8) | data[4];
                ventilation_control(data->co2);
                printf("%" PRIdU " %d %f %d\n", data->timestamp, data->co2, data->temperature, data->humidity);
                fflush(stdout);
                fflush(stdout);
            } else {
                printf("I2C read error: %s\n", strerror(errno));
            }
            break;
        case GPIO_I2C_EVENT_WRITE:
            if (gpio_i2c_write(i2c, I2C_ADDRESS, 6, (uint8_t *)data, 6) == 0) {
                printf("I2C write error: %s\n", strerror(errno));
            } else {
                printf("I2C write error: %s\n", strerror(errno));
            }
            break;
        case GPIO_I2C_EVENT_NOT_READY:
            printf("Sensor not ready\n");
            break;
        case GPIO_I2C_EVENT_CRC_MISMATCH:
            printf("CRC mismatch\n");
            break;
        default:
            printf("Unknown I2C event\n");
            break;
    }
}

int main() {
    // Initialize the GPIO library
    if (gpio_init() != 0) {
        printf("GPIO initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the I2C library
