#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

// Define constants
#define I2C_ADDRESS 0x68
#define I2C_TIMEOUT 100
#define I2C_BUFFER_SIZE 9
#define SAMPLE_INTERVAL 1000

// Define structures
typedef struct {
    uint8_t pressureMSB;
    uint8_t pressureLSB;
    uint8_t pressureCRC8;
    uint8_t temperatureMSB;
    uint8_t temperatureLSB;
    uint8_t temperatureCRC8;
    uint8_t scaleFactorMSB;
    uint8_t scaleFactorLSB;
    uint8_t scaleFactorCRC8;
} sensorData;

// Define signal handlers
void sigintHandler(int sig) {
    printf("Received SIGINT, exiting...\n");
    exit(0);
}

void sigtermHandler(int sig) {
    printf("Received SIGTERM, exiting...\n");
    exit(1);
}

// Function to read sensor data
sensorData readSensorData(pigpio *gpio) {
    sensorData data;
    uint8_t buffer[I2C_BUFFER_SIZE];

    // Initialize I2C bus
    gpio_i2c_setClock(gpio, I2C_ADDRESS, 100000);

    // Read sensor data
    if (gpio_i2c_read(gpio, I2C_ADDRESS, buffer, I2C_BUFFER_SIZE, I2C_TIMEOUT) != I2C_OK) {
        printf("I2C read error: %d\n", gpio_i2c_getError(gpio));
        return data;
    }

    // Verify CRC-8 for pressure, temperature, and scale-factor words
    if (verifyCRC8(buffer, I2C_BUFFER_SIZE, &data.pressureMSB, &data.pressureLSB, &data.pressureCRC8) != 0) {
        printf("CRC-8 verification error for pressure\n");
        return data;
    }
    if (verifyCRC8(buffer, I2C_BUFFER_SIZE, &data.temperatureMSB, &data.temperatureLSB, &data.temperatureCRC8) != 0) {
        printf("CRC-8 verification error for temperature\n");
        return data;
    }
    if (verifyCRC8(buffer, I2C_BUFFER_SIZE, &data.scaleFactorMSB, &data.scaleFactorLSB, &data.scaleFactorCRC8) != 0) {
        printf("CRC-8 verification error for scale-factor\n");
        return data;
    }

    // Convert pressure, temperature, and scale-factor to float
    float pressure = (float)((data.pressureMSB << 8) | data.pressureLSB) * data.scaleFactorMSB * data.scaleFactorLSB;
    float temperature = (float)((data.temperatureMSB << 8) | data.temperatureLSB) * data.scaleFactorMSB * data.scaleFactorLSB;
    float scaleFactor = (float)((data.scaleFactorMSB << 8) | data.scaleFactorLSB) * data.scaleFactorCRC8;

    // Update sensor data
    data.pressure = pressure;
    data.temperature = temperature;
    data.scaleFactor = scaleFactor;

    return data;
}

// Function to verify CRC-8
bool verifyCRC8(const uint8_t *buffer, size_t size, uint8_t *msb, uint8_t *lsb, uint8_t *crc8) {
    uint8_t crc = 0;
    for (size_t i = 0; i < size; i++) {
        crc = crc8(crc, buffer[i]);
    }
    *msb = (crc >> 8);
    *lsb = crc & 0xFF;
    *crc8 = crc;
    return crc == 0;
}

// Function to print sensor data
void printSensorData(const sensorData *data) {
    time_t now = time(NULL);
    printf("%ld %f %f %f\n", now, data->pressure, data->temperature, data->scaleFactor);
}

int main(int argc, char **argv) {
    // Install signal handlers
    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigtermHandler);

    // Initialize GPIO
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Parse command-line argument for sampling interval
    int sampleInterval = 1000;
    if (argc > 1) {
        sampleInterval = atoi(argv[1]);
    }

    // Main loop
    while (1) {
        // Read sensor data
        sensorData data = readSensorData(gpio);

        // Print sensor data
        printSensorData(&data);

        // Sleep for sampling interval
        sleep(sampleInterval / 1000.0);
    }

    // Release resources
    pigpio_close(gpio);
    return 0;
}

