#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define I2C_ADDRESS 0x44
#define I2C_TIMEOUT 0x0000
#define I2C_DELAY 20
#define I2C_READ 0x00
#define I2C_WRITE 0x01

int main() {
    int fd;
    int i;
    int ret;
    char buffer[5];
    struct timespec delay;
    struct timespec start;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(2, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(3, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C address and timeout
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C timeout
    if (ioctl(fd, I2C_TIMEOUT, I2C_TIMEOUT) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set DRDYn pin as input
    if (gpioSetMode(5, PI_INPUT) < 0) {
        perror("gpioSetMode");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Wait for DRDYn to go high
        struct timespec end;
        clock_gettime(CLOCK_REALTIME, &start);
        while (1) {
            if (gpioRead(5) == 1) {
                break;
            }
            nanosleep(&delay, &end);
        }

        // Wait for conversion to finish
        clock_gettime(CLOCK_REALTIME, &start);
        while (1) {
            if (clock_gettime(CLOCK_REALTIME, &end) < start) {
                nanosleep(&delay, &end);
                continue;
            }
            if (end.tv_sec - start.tv_sec > I2C_DELAY) {
                break;
            }
        }

        // Read temperature and humidity
        ret = read(fd, buffer, 5);
        if (ret < 0) {
            perror("read");
            continue;
        }
        if (ret != 5) {
            fprintf(stderr, "Error reading from I2C device\n");
            continue;
        }

        // Convert temperature and humidity
        int temp = (buffer[0] << 8) | buffer[1];
        int humidity = (buffer[2] << 8) | buffer[3];

        // Log temperature and humidity
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", (temp / 100.0), (humidity / 10.0));

        // Wait 5 seconds before next reading
        sleep(5);
    }

    // Close I2C file descriptor
    close(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

