#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x44
#define I2C_TIMEOUT 1000 // 1 second
#define I2C_READ 0x00
#define I2C_WRITE 0x01

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    if (gpiod_init() != 0) {
        perror("gpiod_init");
        return 1;
    }

    // Initialize pigpio
    if (gpio_init() != 0) {
        perror("gpio_init");
        gpiod_exit();
        return 1;
    }

    // Set up I2C pins
    if (gpio_set_mode(2, PI_INPUT) != 0 || gpio_set_mode(3, PI_INPUT) != 0) {
        perror("gpio_set_mode");
        gpio_exit();
        gpiod_exit();
        return 1;
    }

    // Open I2C device
    int fd = pigpio_open(1, PI_I2C, I2C_ADDRESS, I2C_TIMEOUT);
    if (fd < 0) {
        perror("pigpio_open");
        gpio_exit();
        gpiod_exit();
        return 1;
    }

    // Register I2C callback
    struct gpiod_device *dev = gpiod_device_new("si7051");
    if (dev == NULL) {
        perror("gpiod_device_new");
        pigpio_close(fd);
        gpio_exit();
        gpiod_exit();
        return 1;
    }
    gpiod_device_set_callback(dev, I2C_READ, si7051_read);
    gpiod_device_register(dev);

    // Main loop
    while (1) {
        // Read temperature
        int ret = pigpio_read(fd, I2C_ADDRESS, I2C_READ, 2);
        if (ret < 0) {
            perror("pigpio_read");
            break;
        }

        // Check if temperature is valid
        if (ret < 2) {
            printf("Invalid temperature read\n");
            continue;
        }

        // Convert temperature to Celsius
        int temperature = (ret & 0xFF) << 8 | (ret >> 8);
        temperature >>= 1;

        // Log temperature
        printf("Temperature: %.2f°C\n", temperature);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_device_unregister(dev);
    pigpio_close(fd);
    gpio_exit();
    gpiod_exit();

    return 0;
}

// I2C read callback
static int si7051_read(struct gpiod_device *dev, struct gpiod_request *req, void *data) {
    int temperature = 0;
    int ret = pigpio_read(dev->fd, I2C_ADDRESS, I2C_READ, 2);
    if (ret < 0) {
        return -1;
    }
    temperature = (ret & 0xFF) << 8 | (ret >> 8);
    temperature >>= 1;
    return temperature;
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    printf("Received signal %d, exiting...\n", sig);
    gpiod_exit();
    gpio_exit();
    exit(0);
}

// Signal handler registration
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        perror("sigaction");
    }
}

