#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>
#include <stdint.h>
#include <inttypes.h>
#include <errno.h>

#define I2C_ADDRESS 0x69
#define I2C_TIMEOUT 100
#define I2C_BUFFER_SIZE 2

int main(int argc, char **argv) {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C handle
    int fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
    if (fd < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    // Read temperature and pressure
    uint8_t buffer[I2C_BUFFER_SIZE];
    while (1) {
        // Trigger measurement
        if (pigpio_i2c_write(fd, 0x00, 0x01) < 0) {
            if (errno == EIO) {
                // Sensor absent
                fprintf(stderr, "I2C error: Sensor not found\n");
            } else {
                perror("pigpio_i2c_write");
            }
            break;
        }
        usleep(7000);

        // Read results
        if (pigpio_i2c_read(fd, buffer, I2C_BUFFER_SIZE) < 0) {
            if (errno == EIO) {
                // Sensor absent
                fprintf(stderr, "I2C error: Sensor not found\n");
            } else if (errno == EAGAIN) {
                // Timeout
                fprintf(stderr, "I2C error: Timeout\n");
            } else {
                perror("pigpio_i2c_read");
            }
            break;
        }

        // Check for default values
        if (buffer[0] == 0x00 && buffer[1] == 0x00) {
            fprintf(stderr, "I2C error: Default values detected\n");
            break;
        }

        // Parse results
        uint16_t temperature = (buffer[0] << 8) | buffer[1];
        uint32_t pressure = (buffer[2] << 16) | (buffer[3] << 8) | buffer[4];

        // Print result
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", ltm);
        printf("%s - Temperature: %.2f°C, Pressure: %d Pa\n", timestamp, temperature / 10.0, pressure);
    }

    // Close I2C handle
    pigpio_i2c_close(fd);

    // Clean up
    pigpio_cleanup();

    return 0;
}

