#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x5A
#define I2C_SPEED 100000

int main() {
    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open I2C device
    int fd = pigpio_open("/dev/i2c-1", O_RDWR, 0);
    if (fd < 0) {
        perror("pigpio_open");
        return 1;
    }

    // Set I2C speed
    if (pigpio_i2c_set_speed(fd, I2C_SPEED) < 0) {
        perror("pigpio_i2c_set_speed");
        return 1;
    }

    // Open I2C device
    if (pigpio_i2c_open(fd, I2C_ADDRESS, 0) < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    // Read pressure from sensor
    while (1) {
        struct timespec start;
        clock_gettime(CLOCK_MONOTONIC, &start);
        int bytes_read = pigpio_i2c_read(fd, 0, 2);
        if (bytes_read < 0) {
            perror("pigpio_i2c_read");
            continue;
        }
        if (bytes_read != 2) {
            fprintf(stderr, "Unexpected number of bytes read from sensor\n");
            continue;
        }
        int pressure = (bytes_read > 0) ? (bytes_read - 1) * 256 : 0;
        fprintf(stderr, "%ld %d\n", (long)clock_gettime(CLOCK_MONOTONIC, &start).tv_sec, pressure);
    }

    // Close I2C device
    pigpio_i2c_close(fd);
    pigpio_close(fd);

    return 0;
}

