// Function to calculate CRC8
uint8_t calculate_crc8(uint8_t data, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < 8; i++) {
        crc = (crc >> 1);
        if ((crc & 0x80) && (data & 0x80)) {
            crc ^= polynomial;
        }
        data >>= 1;
    }
    return crc;
}

// Function to read I2C data
int read_i2c_data(uint8_t address, uint8_t *data, int size) {
    int fd = pigpio_i2c_open(1, address, 1000);
    if (fd < 0) {
        return -1;
    }

    uint8_t crc = 0xFF;
    for (int i = 0; i < size; i++) {
        uint8_t word = 0;
        pigpio_i2c_read(fd, &word, 1);
        if (word & 0x80) {
            crc ^= pigpio_i2c_read(fd, &crc, 1);
        }
        data[i] = word;
    }

    pigpio_i2c_close(fd);
    return 0;
}

// Function to write I2C data
int write_i2c_data(uint8_t address, uint8_t *data, int size) {
    int fd = pigpio_i2c_open(1, address, 1000);
    if (fd < 0) {
        return -1;
    }

    for (int i = 0; i < size; i++) {
        pigpio_i2c_write(fd, data + i, 1);
    }

    pigpio_i2c_close(fd);
    return 0;
}

// Function to read temperature and pressure from the sensor
void read_sensor_data() {
    uint8_t data[I2C_READ_DATA_SIZE];
    if (read_i2c_data(I2C_ADDRESS, data, I2C_READ_DATA_SIZE) < 0) {
        printf("Error reading from sensor\n");
        return;
    }

    uint8_t crc = data[I2C_READ_DATA_SIZE - 1];
    uint8_t expected_crc = calculate_crc8(data[I2C_READ_DATA_SIZE - 1], I2C_CRC8_POLYNOMINAL);
    if (crc != expected_crc) {
        printf("CRC mismatch\n");
        return;
    }

    uint16_t pressure = (data[I2C_READ_DATA_SIZE - 3] << 8) | data[I2C_READ_DATA_SIZE - 2];
    uint8_t temperature = data[I2C_READ_DATA_SIZE - 1];

    printf("%d,%d,%d\n", time(NULL), pressure, temperature);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        return -1;
    }

    // Set up I2C pins
    if (gpioSetMode(2, PI_INPUT) < 0) {
        printf("Error setting up I2C pin 2\n");
        return -1;
    }
    if (gpioSetMode(3, PI_INPUT) < 0) {
        printf("Error setting up I2C pin 3\n");
        return -1;
    }

    // Open log file
    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return -1;
    }

    while (1) {
        // Trigger measurement
        if (write_i2c_data(I2C_ADDRESS, &I2C_DATA, 1) < 0) {
            printf("Error triggering measurement\n");
            continue;
        }

        // Wait for 45ms
        usleep(45000);

        // Read data
        read_sensor_data();
    }

    // Close log file
    fclose(log_file);

    // Release GPIO
    gpioCleanUp();

    return 0;
}
