#define SDP800_DATA_SIZE 3
#define SDP800_CRC_SIZE 1
#define SDP800_DATA_OFFSET 0
#define SDP800_CRC_OFFSET SDP800_DATA_SIZE

// Function to calculate the CRC-8
uint8_t calculate_crc8(uint8_t data[], size_t size) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < size; i++) {
        crc = (crc >> 1);
        if ((crc & 0x80) && data[i]) {
            crc = (crc ^ 0x31);
        }
        crc = (crc ^ data[i]);
    }
    return crc;
}

// Function to read the SDP800 sensor
void read_sdp800(pigpio_t *gpio, uint8_t *data, size_t size) {
    uint8_t crc;
    uint8_t response[SDP800_DATA_SIZE + SDP800_CRC_SIZE];

    // Wait for the sensor to be ready
    usleep(8000);

    // Read the three-byte response
    if (gpio->i2c_read(I2C_ADDRESS, response, SDP800_DATA_SIZE + SDP800_CRC_SIZE, 1000) != SDP800_DATA_SIZE + SDP800_CRC_SIZE) {
        printf("I2C read error\n");
        return;
    }

    // Calculate the expected CRC-8
    uint8_t expected_crc = calculate_crc8(response + SDP800_CRC_OFFSET, SDP800_CRC_SIZE);

    // Check the CRC-8
    if (response[SDP800_CRC_OFFSET] != expected_crc) {
        printf("CRC-8 error\n");
        return;
    }

    // Copy the data to the user-provided buffer
    memcpy(data, response + SDP800_DATA_OFFSET, size);
}

