        if (fstat(fd, &sb) == -1) {
            printf("Failed to get file stats\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
        if (ftruncate(fd, sb.st_size + SDP800_DATA_SIZE) == -1) {
            printf("Failed to truncate file\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
        if (fseek(fd, 0, SEEK_END) == -1) {
            printf("Failed to seek file\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
        if (fwrite(data, SDP800_DATA_SIZE, 1, fd) != 1) {
            printf("Failed to write measurement\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }

        // Log the timestamp
        now = time(NULL);
        if (strftime(&now, sizeof(now), "%Y-%m-%d %H:%M:%S", localtime(&now)) == NULL) {
            printf("Failed to format timestamp\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
        if (fstat(fd, &sb) == -1) {
            printf("Failed to get file stats\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
        if (ftruncate(fd, sb.st_size + 1) == -1) {
            printf("Failed to truncate file\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
        if (fseek(fd, 0, SEEK_SET) == -1) {
            printf("Failed to seek file\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
        if (fprintf(fd, "%s,%d\n", now, data[0]) != 1) {
            printf("Failed to write timestamp\n");
            close(fd);
            pigpio_close(gpio);
            return 1;
        }
    }

    // Clean up
