#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>

#define I2C_ADDRESS 0x60
#define I2C_TIMEOUT 100
#define CSV_FILE "pressure_log.csv"

int main() {
    int i2c_fd = -1;
    int csv_fd = -1;
    int ret = 0;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Initialize signal handlers
    sa.sa_handler = sigpipe;
    sa_int.sa_handler = sigpipe;
    sa_term.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa_term, NULL);
    sigaction(SIGALRM, &sa_int, NULL);

    // Open I2C handle
    i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    // Open log file
    struct stat sb;
    if (stat(CSV_FILE, &sb) == -1) {
        if (mkdir(CSV_FILE, 0644) == -1) {
            perror("mkdir");
            return 1;
        }
        csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT, 0644);
        if (csv_fd < 0) {
            perror("open");
            return 1;
        }
    } else if (sb.st_size == 0) {
        csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT, 0644);
        if (csv_fd < 0) {
            perror("open");
            return 1;
        }
    }

    // Initialize Melexis MLX90821 library
    ret = pigpio_i2c_read(i2c_fd, 0x00, 2, NULL, NULL);
    if (ret < 0) {
        pigpio_i2c_close(i2c_fd);
        i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
        if (i2c_fd < 0) {
            perror("pigpio_i2c_open");
            return 1;
        }
        ret = pigpio_i2c_read(i2c_fd, 0x00, 2, NULL, NULL);
        if (ret < 0) {
            pigpio_i2c_close(i2c_fd);
            i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
            if (i2c_fd < 0) {
                perror("pigpio_i2c_open");
                return 1;
            }
            ret = pigpio_i2c_read(i2c_fd, 0x00, 2, NULL, NULL);
            if (ret < 0) {
                pigpio_i2c_close(i2c_fd);
                return 1;
            }
        }
    }

    while (1) {
        // Read pressure from sensor
        ret = pigpio_i2c_read(i2c_fd, 0x00, 2, NULL, NULL);
        if (ret < 0) {
            pigpio_i2c_close(i2c_fd);
            i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
            if (i2c_fd < 0) {
                perror("pigpio_i2c_open");
                return 1;
            }
            ret = pigpio_i2c_read(i2c_fd, 0x00, 2, NULL, NULL);
            if (ret < 0) {
                pigpio_i2c_close(i2c_fd);
                return 1;
            }
        }

        // Check if I2C read was successful
        if (ret < 0) {
            continue;
        }

        // Convert pressure to kPa
        unsigned char pressure = (ret >> 8) & 0xFF;
        float pressure_kPa = pressure / 10.0;

        // Check if pressure is within safe range
        if (pressure_kPa < 200 || pressure_kPa > 250) {
            fprintf(stderr, "Warning: Pressure out of range (%f kPa)\n", pressure_kPa);
        }

        // Append to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(csv_fd, "%s,%f\n", timestamp, pressure_kPa);
    }

    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    if (csv_fd >= 0) {
        close(csv_fd);
    }

    return 0;
}

