        ret = pigpio_i2c_read(i2c_fd, 0x00, 2, NULL, NULL);
        if (ret < 0) {
            pigpio_i2c_close(i2c_fd);
            i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
            if (i2c_fd < 0) {
                perror("pigpio_i2c_open");
                return 1;
            }
            ret = pigpio_i2c_read(i2c_fd, 0x00, 2, NULL, NULL);
            if (ret < 0) {
                pigpio_i2c_close(i2c_fd);
                return 1;
            }
        }

        // Check if I2C read was successful
        if (ret < 0) {
            continue;
        }

        // Convert pressure to kPa
        unsigned char pressure = (ret >> 8) & 0xFF;
        float pressure_kPa = pressure / 10.0;

        // Check if pressure is within safe range
        if (pressure_kPa < 200 || pressure_kPa > 250) {
            fprintf(stderr, "Warning: Pressure out of range (%f kPa)\n", pressure_kPa);
        }

        // Append to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(csv_fd, "%s,%f\n", timestamp, pressure_kPa);
    }

    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    if (csv_fd >= 0) {
        close(csv_fd);
    }

    return 0;
}
```

This code initializes the Melexis MLX90821 library, opens the I2C bus, and reads the pressure from the sensor every second. It checks if the pressure is within the safe range of 200-250 kPa and appends the result to a log file named `pressure_log.csv`. If the log file does not exist, it creates it with a header row. The code also handles errors and retries opening the I2C handle if it fails. The signal handlers are installed to close the I2C handle and flush the log file on SIGINT and SIGTERM signals.

