#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <time.h>

#define SENT_PROTOCOL_VERSION 0x01
#define SENT_STATUS_NIBBLE 0x00
#define SENT_DATA_NIBBLE 0x01
#define SENT_CHECKSUM_NIBBLE 0x02
#define SENT_PULSE_WIDTH_MIN 12
#define SENT_PULSE_WIDTH_MAX 271
#define SENT_SYNCHRONIZATION_PULSE 56
#define SENT_PULSE_WIDTH_TOLERANCE 5

int main(int argc, char *argv[]) {
    int gpio = 4;
    int gpio_fd = -1;
    int error = 0;
    int sync_pulse = 0;
    int status_nibble = 0;
    int data_nibble1 = 0;
    int data_nibble2 = 0;
    int data_nibble3 = 0;
    int checksum_nibble = 0;
    int pulse_width = 0;
    int sync_pulse_count = 0;
    int sync_pulse_start = 0;
    int sync_pulse_end = 0;
    int data_nibble1_count = 0;
    int data_nibble2_count = 0;
    int data_nibble3_count = 0;
    int checksum_nibble_count = 0;
    int checksum = 0;
    struct timespec start_time;
    struct timespec end_time;
    struct stat file_stat;
    char log_file_path[256];
    char log_message[256];

    // Initialize GPIO
    if (gpio_fd = pigpio_open(gpio, PI INPUT, PI_INT_EDGE_RISING)) {
        if (gpio_fd < 0) {
            perror("pigpio_open");
            return 1;
        }
    }

    // Create log file
    sprintf(log_file_path, "/home/pi/pressure_log.txt");
    if (mkdir(log_file_path, 0777) == -1) {
        perror("mkdir");
        return 1;
    }
    if ((file_stat.st_mode = fstat(log_file_path, &file_stat)) == -1) {
        perror("fstat");
        return 1;
    }
    if (fchmod(log_file_path, file_stat.st_mode | 0666) == -1) {
        perror("fchmod");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    while (1) {
        // Wait for synchronization pulse
        while (sync_pulse_count < SENT_SYNCHRONIZATION_PULSE) {
            usleep(1000);
            sync_pulse_count++;
            if (gpio_fd >= 0) {
                pigpio_read(gpio_fd, &sync_pulse);
            }
        }
        sync_pulse_count = 0;
        sync_pulse_start = pigpio_get_tick_count();

        // Wait for data nibbles
        while (data_nibble1_count < 3) {
            usleep(1000);
            data_nibble1_count++;
            if (gpio_fd >= 0) {
                pigpio_read(gpio_fd, &data_nibble1);
            }
        }
        data_nibble1_count = 0;
        data_nibble2_count = 0;
        data_nibble3_count = 0;
        checksum_nibble_count = 0;

        // Wait for checksum nibble
        while (checksum_nibble_count < 1) {
            usleep(1000);
            checksum_nibble_count++;
            if (gpio_fd >= 0) {
                pigpio_read(gpio_fd, &checksum_nibble);
            }
        }
        checksum_nibble_count = 0;

        // Calculate checksum
        checksum = (data_nibble1 << 2) | (data_nibble2 << 1) | data_nibble3;

        // Check checksum
        if (checksum != (checksum_nibble >> 1)) {
            fprintf(stderr, "Checksum mismatch\n");
            continue;
        }

        // Check pulse width
        pulse_width = sync_pulse_end - sync_pulse_start;
        if (pulse_width < SENT_PULSE_WIDTH_MIN || pulse_width > SENT_PULSE_WIDTH_MAX) {
            fprintf(stderr, "Invalid pulse width\n");
            continue;
        }

        // Calculate status nibble
        status_nibble = (pulse_width >> 1) & 0x0F;

        // Log reading
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S, Pressure: %.2f Pa", time_info);
        FILE *log_file = fopen(log_file_path, "a");
        if (log_file == NULL) {
            perror("fopen");
            continue;
        }
        fprintf(log_file, "%s %d\n", log_message, status_nibble);
        fclose(log_file);

        // Release resources
        pigpio_close(gpio_fd);
        gpio_fd = -1;
    }

    return 0;
}

