#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <syslog.h>

#define GREENHOUSE_TEMP_FILE "greenhouse_temps.dat"
#define GREENHOUSE_TEMP_ADDRESS 0x44
#define GREENHOUSE_TEMP_REG 0x00

int main(int argc, char **argv) {
    int i2c_fd = -1;
    int ret = 0;
    float temp = 0.0f;
    struct stat sb;
    struct sigaction sa;

    // Initialize the signal handler
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the file for writing
    if ((ret = open(GREENHOUSE_TEMP_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("open");
        return 1;
    }

    // Check if the file is a regular file
    if (fstat(ret, &sb) < 0) {
        perror("fstat");
        return 1;
    }

    // Initialize the I2C interface
    if ((ret = pigpio_init()) < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Check if the I2C bus is available
    if ((ret = pigpio_i2c_check_bus(0)) < 0) {
        perror("pigpio_i2c_check_bus");
        pigpio_cleanup();
        return 1;
    }

    // Open the I2C interface
    if ((ret = pigpio_i2c_open(0, GREENHOUSE_TEMP_ADDRESS, 100000)) < 0) {
        perror("pigpio_i2c_open");
        pigpio_cleanup();
        return 1;
    }

    // Read the device ID
    if ((ret = pigpio_i2c_read(0, GREENHOUSE_TEMP_ADDRESS, 1)) < 0) {
        perror("pigpio_i2c_read");
        pigpio_i2c_close(0);
