        sleep(5);

        // Read the CRC value
        uint8_t crc = 0;
        if (sht40_read(pi, SHT40_ADDRESS, &crc) < 0) {
            perror("sht40_read");
            return 1;
        }

        // Read the temperature
        uint16_t temp = 0;
        if (sht40_read(pi, SHT40_ADDRESS, &temp) < 0) {
            perror("sht40_read");
            return 1;
