        uint8_t temp_crc = 0;
        if (sht40_read(pi, SHT40_ADDRESS, &temp_crc) < 0) {
            perror("sht40_read");
            return 1;
        }

        // Validate the temperature CRC
        if (temp_crc != (temp_crc & 0x1E) ^ SHT40_INIT_VALUE) {
            printf("Invalid temperature CRC\n");
            continue;
        }

        // Read the humidity
        uint16_t humid = 0;
        if (sht40_read(pi, SHT40_ADDRESS, &humid) < 0) {
            perror("sht40_read");
            return 1;
