        // Validate the humidity CRC
        if (humid_crc != (humid_crc & 0x1E) ^ SHT40_INIT_VALUE) {
            printf("Invalid humidity CRC\n");
            continue;
        }

        // Write the data to the log file
        fprintf(log_file, "%d %d %d %d\n", (int)time(NULL), (int)temp, (int)humid);
        fflush(log_file);
    }

    // Close the log file
    fclose(log_file);

    // Clean up
    sht40_close(pi);
    pigpio_close();
    return 0;
