// Structure to hold temperature data
typedef struct {
    uint16_t timestamp;
    float temperature;
} TemperatureData;

// Function to initialize the I2C interface
void init_i2c(pigpio_t *gpio) {
    if (gpio->i2c_open(gpio, 0x44, 0) < 0) {
        printf("Failed to open I2C interface\n");
        exit(1);
    }
}

// Function to read temperature from the TMP117 sensor
int read_temperature(pigpio_t *gpio) {
    uint8_t reg = 0x00;
    uint16_t data = 0;
    int ret = gpio->i2c_read(gpio, 0x44, &reg, 1, &data);
    if (ret < 0) {
        printf("Failed to read from I2C interface\n");
        return -1;
    }
    return data;
}

// Function to write data to the I2C interface
int write_temperature(pigpio_t *gpio, uint8_t reg, uint16_t data) {
    return gpio->i2c_write(gpio, 0x44, reg, 1, &data);
}

// Function to add temperature data to the buffer
void add_to_buffer(TemperatureData *buffer, int *head, int *tail) {
    if (*tail == BUFFER_SIZE) {
        *tail = 0;
    }
    buffer[*tail].timestamp = time(NULL);
    buffer[*tail].temperature = (float)read_temperature(gpio);
    (*tail)++;
}

// Function to flush the buffer to disk
void flush_buffer(TemperatureData *buffer, int size) {
    FILE *file = fopen(BUFFER_NAME, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        fwrite(&buffer[i].timestamp, sizeof(uint16_t), 1, file);
        fwrite(&buffer[i].temperature, sizeof(float), 1, file);
    }
    fclose(file);
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    flush_buffer(buffer, BUFFER_SIZE);
    exit(0);
}

int main() {
