#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define I2C_ADDRESS 0x1E
#define I2C_SPEED 400000
#define FILE_NAME "mag_temp_log.csv"

// Structure to hold sensor data
typedef struct {
    float speed;
    float temperature;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(pigpio_t *gpio) {
    if (gpio->i2c_open(I2C_ADDRESS, I2C_SPEED) < 0) {
        printf("I2C initialization failed\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor(pigpio_t *gpio) {
    uint8_t data[2];
    if (gpio->i2c_read(I2C_ADDRESS, 0x00, data, 2) < 0) {
        printf("Sensor read failed\n");
        return -1;
    }
    return 0;
}

// Function to calculate rotational speed
float calculate_speed(float temperature) {
    // Assuming the sensor data is in the format: (speed, temperature)
    // where speed is in revolutions per minute (RPM) and temperature is in degrees Celsius
    return (data[0] * 1000.0f / 60.0f);
}

// Function to write to log file
int write_to_log(pigpio_t *gpio, sensor_data_t data) {
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }
    fprintf(file, "%f,%f\n", data.speed, data.temperature);
    fclose(file);
    return 0;
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    pigpio_t *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize GPIO\n");
        return;
    }
    gpio_close(gpio);
    exit(0);
}

int main() {
    pigpio_t *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize GPIO\n");
        return -1;
    }

    // Create log file if it does not exist
    struct stat info;
    if (stat(FILE_NAME, &info) == -1) {
        if (mkdir(FILE_NAME, 0777) == -1) {
            printf("Failed to create log file directory\n");
            return -1;
        }
    }

    // Initialize I2C
    if (init_i2c(gpio) < 0) {
        return -1;
    }

    // Read sensor data
    sensor_data_t data;
    while (1) {
        if (read_sensor(gpio) < 0) {
            data.speed = NAN;
            data.temperature = NAN;
        } else {
            data.speed = calculate_speed(data.temperature);
        }
        if (write_to_log(gpio, data) < 0) {
            data.speed = NAN;
            data.temperature = NAN;
        }
        sleep(1);
    }

    // Clean up
    pigpio_close(gpio);
    return 0;
}

