#include <sys/wait.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x44
#define I2C_CLOCK_SPEED 100000

int main(int argc, char *argv[]) {
    int fd;
    int i2c_fd;
    int ret;
    struct timespec t;
    struct timespec last_time;
    struct tm *time_info;
    char buffer[20];
    char filename[] = "temperature_log.txt";
    char timestamp[20];
    char temperature_str[10];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file
    fd = open(filename, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Create I2C handle
    i2c_fd = i2cOpen(I2C_ADDRESS, I2C_CLOCK_SPEED);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        close(fd);
        return 1;
    }

    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &t);
        time_info = localtime(&t.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Read temperature
        ret = i2cRead(i2c_fd, 0x00, 2, NULL, NULL);
        if (ret < 0) {
            if (errno == EIO) {
                // Attempt to re-initialize I2C handle
                if (i2cReinit(i2c_fd) < 0) {
                    if (i2cReinit(i2c_fd) < 0) {
                        if (i2cReinit(i2c_fd) < 0) {
                            perror("i2cReinit");
                            break;
                        }
                    }
                }
                continue;
            } else {
                perror("i2cRead");
                break;
            }
        }

        // Check for sensor-absent condition
        if (ret < 2) {
            continue;
        }

        // Read temperature value
        ret = i2cRead(i2c_fd, 0x00, 2, NULL, NULL);
        if (ret < 0) {
            perror("i2cRead");
            break;
        }

        // Convert temperature value to Celsius
        int temperature = (ret[0] << 8) | ret[1];
        if (temperature < 0) {
            temperature += 0x10000;
        }

        // Append to file
        sprintf(buffer, "%s, Temperature: %d C\n", timestamp, temperature);
        write(fd, buffer, strlen(buffer));

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C handle and file
    i2cClose(i2c_fd);
    close(fd);

    // Clean up GPIO
    gpioTerminate();

    return 0;
}

