#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_ADDRESS 0x40
#define I2C_TIMEOUT 100
#define I2C_BUFFER_SIZE 4

int main() {
    int i2c_fd;
    int ret;
    struct pigpio *gpio;
    struct timespec ts;
    char buffer[I2C_BUFFER_SIZE];
    char filename[] = "flow_log.txt";

    // Initialize pigpio
    gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C device
    i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        pigpio_close(gpio);
        return 1;
    }

    // Wait for I2C bus to settle
    usleep(100000);

    // Initialize I2C handle
    ret = pigpio_i2c_init(i2c_fd, I2C_TIMEOUT);
    if (ret < 0) {
        perror("pigpio_i2c_init");
        pigpio_close(gpio);
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    // Read flow and temperature data
    while (1) {
        // Read 4 bytes from sensor
        ret = pigpio_i2c_read(i2c_fd, buffer, I2C_BUFFER_SIZE);
        if (ret < 0) {
            perror("pigpio_i2c_read");
            pigpio_i2c_close(i2c_fd);
            pigpio_close(gpio);
            return 1;
        }

        // Extract flow and temperature values
        uint16_t flow = (buffer[0] << 12) | (buffer[1] << 4) | (buffer[2] >> 4);
        uint16_t temperature = (buffer[2] & 0x0F) | (buffer[3] << 4);

        // Handle first two reads after power-up which may return stale data
        if (flow < 0x1000 || temperature < 0x00) {
            printf("Ignoring stale data\n");
            continue;
        }

        // Write timestamped measurement to log file
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(filename, "%ld %d %d\n", ts.tv_sec, flow, temperature);

        // Check for I2C communication failures
        if (pigpio_i2c_get_error(i2c_fd) != 0) {
            printf("I2C error\n");
            pigpio_i2c_close(i2c_fd);
            pigpio_close(gpio);
            return 1;
        }
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    pigpio_close(gpio);
    close(filename);
    return 0;
}

