#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x44
#define I2C_ADDRESS2 0x45

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to read sensor data
sensor_data_t read_sensor_data(uint8_t address) {
    sensor_data_t data;
    uint8_t buffer[2];

    if (i2c_smbus_read(address, 0x00, 2, buffer) != 0) {
        fprintf(stderr, "Error reading from sensor %d\n", address);
        return (sensor_data_t){0, 0, 0};
    }

    data.red = (buffer[0] << 8) | buffer[1];
    data.green = (buffer[1] << 8) | buffer[2];
    data.blue = (buffer[2] << 8) | buffer[3];

    return data;
}

// Function to calculate correlated color temperature (CCT)
float calculate_cct(sensor_data_t data) {
    float r = data.red / 65535.0;
    float g = data.green / 65535.0;
    float b = data.blue / 65535.0;

    float x = 0.412453 * r + 0.6077 * g;
    float y = 0.212671 * r + 0.715160 * g;
    float z = 0.079433 * r + 0.015139 * g + 0.060556 * b;

    return 10000.0 / (x + y + z);
}

int main(int argc, char **argv) {
    // Initialize libgpiod
    gpiod_init();

    // Open I2C file
    int fd = open("cct_log.csv", O_RDWR | O_CREAT | O_WRONLY, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) != 0) {
        perror("Error setting I2C clock speed");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS2) != 0) {
        perror("Error setting I2C clock speed");
        return 1;
    }

    // Read sensor data
    sensor_data_t data1 = read_sensor_data(I2C_ADDRESS);
    sensor_data_t data2 = read_sensor_data(I2C_ADDRESS2);

    // Calculate average CCT
    float cct = (calculate_cct(data1) + calculate_cct(data2)) / 2.0;

    // Log average CCT
    if (fprintf(fd, "%d,%f\n", time(NULL), cct) != 0) {
        perror("Error writing to log file");
        return 1;
    }

    // Clean up
    close(i2c_fd);
    close(fd);

    // Handle SIGINT and SIGTERM signals
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error handling SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error handling SIGTERM");
        return 1;
    }

    return 0;
}

