#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_ADDRESS 0x60
#define FILE_NAME "pressure_log.txt"

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the log file
    int log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = i2cOpen(I2C_ADDRESS, 100000);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Register the I2C callback
    i2cRegisterCallback(i2c_fd, i2cCallback);

    // Read the sensor data
    while (1) {
        struct timespec start_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        int status = i2cRead(i2c_fd, 0x00, 6, NULL, NULL);
        if (status < 0) {
            if (errno == EIO) {
                // Sensor not found or bus error
                struct timespec end_time;
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                fprintf(log_fd, "Error: Sensor not found or bus error at %ld\n", (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec));
            } else {
                perror("i2cRead");
            }
            continue;
        }

        // Extract the pressure and temperature values
        uint16_t pressure = (status & 0xFF00) >> 8;
        uint16_t temperature = status & 0x00FF;

        // Convert the temperature to Celsius
        float temperature_celsius = (temperature * 0.01);

        // Append the measurement to the log file
        struct timespec end_time;
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06d", localtime(&end_time));
        fprintf(log_fd, "%s,%.2f,%.2f\n", timestamp, pressure / 100.0, temperature_celsius);

        // Clean up
        i2cClose(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 0;
    }
}

void i2cCallback(int fd, void *user_data) {
    // Empty callback function
}

