                clock_gettime(CLOCK_MONOTONIC, &end_time);
                fprintf(log_fd, "Error: Sensor not found or bus error at %ld\n", (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec));
            } else {
                perror("i2cRead");
            }
            continue;
        }

        // Extract the pressure and temperature values
        uint16_t pressure = (status & 0xFF00) >> 8;
        uint16_t temperature = status & 0x00FF;

        // Convert the temperature to Celsius
        float temperature_celsius = (temperature * 0.01);

        // Append the measurement to the log file
        struct timespec end_time;
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06d", localtime(&end_time));
        fprintf(log_fd, "%s,%.2f,%.2f\n", timestamp, pressure / 100.0, temperature_celsius);

        // Clean up
        i2cClose(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 0;
    }
}

void i2cCallback(int fd, void *user_data) {
    // Empty callback function
}
