    int gpio_pin = 18;
    int gpio_level = 0;
    unsigned char buffer[BUFFER_SIZE];
    unsigned char reg;
    unsigned int sum = 0;
    unsigned int count = 0;
    unsigned int avg = 0;
    unsigned int prev_avg = 0;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec sleep_time;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize GPIO
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Set GPIO pin as output
    if (gpio_mode(gpio_pin, GPIO_MODE_OUTPUT) < 0) {
        perror("gpio_mode");
        return 1;
    }

    // Set GPIO pin as high
    if (gpio_write(gpio_pin, 1) < 0) {
        perror("gpio_write");
        return 1;
    }

    // Initialize I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR) < 0) {
        perror("open");
        return 1;
    }

