    if (read(i2c_fd, &reg, 1) < 0) {
        perror("read");
        return 1;
    }

    // Compute running average
    avg = (reg & 0x0F) * 0.25 + (reg >> 4) * 0.0625;
    avg = (avg * count + prev_avg) / (count + 1);

    // Check if average exceeds threshold
    if (avg > AVG_THRESHOLD + AVG_HYST) {
        gpio_level = 1;
    } else {
        gpio_level = 0;
    }

    // Set GPIO pin level
    if (gpio_write(gpio_pin, gpio_level) < 0) {
        perror("gpio_write");
        return 1;
    }

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }

    // Main loop
    while (1) {
        // Record current time
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Read temperature
        if (read(i2c_fd, &reg, 1) < 0) {
            perror("read");
            continue;
        }

        // Compute running average
        sum += reg & 0x0F;
        count++;
        avg = (sum * 0.25 + prev_avg * 0.75) / (count + 1);
        prev_avg = avg;

        // Check if average exceeds threshold
        if (avg > AVG_THRESHOLD + AVG_HYST) {
            gpio_level = 1;
        } else {
            gpio_level = 0;
        }

        // Set GPIO pin level
        if (gpio_write(gpio_pin, gpio_level) < 0) {
            perror("gpio_write");
            continue;
        }

        // Sleep for SAMPLE_RATE seconds
        sleep_time.tv_sec = SAMPLE_RATE;
        sleep_time.tv_nsec = 0;
        if (nanosleep(&sleep_time, NULL) < 0) {
            perror("nanosleep");
            continue;
        }

        // Check if SIGINT or SIGTERM was received
        if (sigaction(SIGINT, &sa, &old_sa) < 0) {
            perror("sigaction");
            continue;
        }
    }

    // Clean up
    gpio_close(gpio_pin);
    close(i2c_fd);
    gpio_uninit();
    return 0;
}

void sigint_handler(int sig) {
    // Stop fan
    gpio_write(gpio_pin, 0);

    // Close I2C handle
    close(i2c_fd);

    // Uninitialize GPIO
    gpio_uninit();

    // Exit
    exit(0);
}

