#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_ADDRESS 0x44
#define LED_GPIO 17
#define LED_HYST 1

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    int led_state = 0;
    int temperature;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read temperature
        if (ioctl(i2c_fd, I2C_READ, NULL) < 0) {
            if (errno == EIO) {
                perror("I2C_READ");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            } else {
                perror("ioctl");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
        }

        temperature = (i2c_fd) >> 8;

        // Update LED state
        if (temperature > 28) {
            led_state = 1;
        } else if (temperature < 27) {
            led_state = 0;
        }

        // Set LED
        if (gpioWrite(LED_GPIO, led_state) < 0) {
            perror("gpioWrite");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Log temperature
        printf("%d\n", temperature);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    close(i2c_fd);
    return 0;
}

