#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define I2C_ADDRESS 0x68
#define I2C_TIMEOUT 0x10
#define CRC8_POLYNOMINAL 0x31
#define CRC8_INIT_VALUE 0x00
#define SCALE_FACTOR_SIZE 3
#define MEASUREMENT_SIZE 9

// Function to calculate CRC-8
uint8_t crc8(uint8_t data, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc ^ polynomial) ^ (crc << 1);
        } else {
            crc = crc << 1;
        }
        crc &= 0xFF;
    }
    return crc;
}

// Function to read from the sensor
void read_sensor(pigpio_t *gpio, uint8_t *data) {
    uint8_t crc8 = 0xFF;
    uint8_t temp = 0xFF;
    uint8_t scale_factor[SCALE_FACTOR_SIZE] = {0};

    // Wait for the sensor to be ready
    usleep(45000);

    // Read the differential pressure
    gpio_write(gpio, I2C_ADDRESS, 0x00);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x01);
    usleep(100);
    gpio_read(gpio, I2C_ADDRESS, 0x02, 2, data);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x03);
    usleep(100);
    gpio_read(gpio, I2C_ADDRESS, 0x04, 1, &crc8);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x05);
    usleep(100);
    gpio_read(gpio, I2C_ADDRESS, 0x06, 2, &temp);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x07);
    usleep(100);
    gpio_read(gpio, I2C_ADDRESS, 0x08, SCALE_FACTOR_SIZE, scale_factor);

    // Validate the CRC-8
    if (crc8 != crc8) {
        printf("CRC-8 error\n");
        return;
    }

    // Validate the temperature
    if (temp != 0xFF) {
        printf("Temperature error\n");
        return;
    }

    // Validate the scale factor
    for (int i = 0; i < SCALE_FACTOR_SIZE; i++) {
        if (scale_factor[i] != 0xFF) {
            printf("Scale factor error\n");
            return;
        }
    }
}

// Function to write to the sensor
