    uint8_t crc8 = crc8(data[0], CRC8_POLYNOMINAL);
    uint8_t temp = data[2];
    uint8_t scale_factor[SCALE_FACTOR_SIZE] = {data[3], data[4], data[5]};

    // Write the differential pressure
