    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x01);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x02);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x03);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x04);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x05);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x06);
    usleep(100);
    gpio_write(gpio, I2C_ADDRESS, 0x07);
