#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/mount.h>
#include <sys/statvfs.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS 0x40
#define I2C_TIMEOUT 1000 // 1 second
#define I2C_BUFFER_SIZE 2
#define LOG_FILE "enviro_log.txt"

int main() {
    int i2c_fd = -1;
    int gpio_fd = -1;
    int ret;
    struct i2c_msg msg;
    struct i2c_msg msg2;
    char buffer[I2C_BUFFER_SIZE];
    char timestamp[20];
    char temperature[10];
    char humidity[10];
    struct stat sb;
    struct statvfs st;

    // Initialize GPIO
    gpio_init();
    gpio_set_mode(17, PI_INPUT);
    gpio_pull_up_down(17, PI_PUD_UP);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Check if I2C bus is available
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    if ((ret = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read temperature and humidity
        msg.msg_type = I2C_MSG_READ;
        msg.msg_dir = I2C_READ;
        msg.addr = I2C_ADDRESS;
        msg.len = 2;
        msg.buf = buffer;
        ret = i2c_transfer(i2c_fd, &msg, 1);
        if (ret < 0) {
            perror("Failed to read from I2C bus");
            continue;
        }

        // Wait for conversion to complete
        usleep(2000000);

        // Check if conversion was successful
        if (msg.err) {
            continue;
        }

        // Extract temperature and humidity
        temperature[0] = buffer[0];
        temperature[1] = buffer[1];
        humidity[0] = buffer[2];
        humidity[1] = buffer[3];

        // Convert temperature and humidity to Celsius and percentage
        temperature[0] -= 40;
        temperature[1] /= 10;
        humidity[0] /= 10;
        humidity[1] *= 100;

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));

        // Append log entry
        if (write(i2c_fd, timestamp, strlen(timestamp)) < 0) {
            perror("Failed to write to I2C bus");
            continue;
        }
        if (write(i2c_fd, temperature, strlen(temperature)) < 0) {
            perror("Failed to write to I2C bus");
            continue;
        }
        if (write(i2c_fd, humidity, strlen(humidity)) < 0) {
            perror("Failed to write to I2C bus");
            continue;
        }

        // Check if log file is writable
        if (fstat(i2c_fd, &sb) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (fstatvfs(i2c_fd, &st) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (st.f_frsize != sb.st_size) {
            perror("File size mismatch");
            continue;
        }

        // Flush log file
        if (fflush(i2c_fd) < 0) {
            perror("Failed to flush log file");
            continue;
        }

        // Check if log file is full
        if (fstat(i2c_fd, &sb) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (sb.st_blocks == 0) {
            continue;
        }

        // Check if log file is writable
        if (fstatvfs(i2c_fd, &st) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (st.f_frsize != sb.st_size) {
            perror("File size mismatch");
            continue;
        }

        // Check if log file is full
        if (st.f_frsize == sb.st_blocks * st.f_frsize) {
            continue;
        }

        // Close log file
        if (close(i2c_fd) < 0) {
            perror("Failed to close log file");
            continue;
        }
    }

    // Close I2C bus
    if (close(i2c_fd) < 0) {
        perror("Failed to close I2C bus");
    }

    // Close GPIO
    if (gpio_close(gpio_fd) < 0) {
        perror("Failed to close GPIO");
    }

    return 0;
}

