            perror("Failed to write to I2C bus");
            continue;
        }
        if (write(i2c_fd, temperature, strlen(temperature)) < 0) {
            perror("Failed to write to I2C bus");
            continue;
        }
        if (write(i2c_fd, humidity, strlen(humidity)) < 0) {
            perror("Failed to write to I2C bus");
            continue;
        }

        // Check if log file is writable
        if (fstat(i2c_fd, &sb) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (fstatvfs(i2c_fd, &st) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (st.f_frsize != sb.st_size) {
            perror("File size mismatch");
            continue;
        }

        // Flush log file
        if (fflush(i2c_fd) < 0) {
            perror("Failed to flush log file");
            continue;
        }

        // Check if log file is full
        if (fstat(i2c_fd, &sb) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (sb.st_blocks == 0) {
            continue;
        }

        // Check if log file is writable
        if (fstatvfs(i2c_fd, &st) < 0) {
            perror("Failed to get file status");
            continue;
        }
        if (st.f_frsize != sb.st_size) {
            perror("File size mismatch");
            continue;
        }

        // Check if log file is full
        if (st.f_frsize == sb.st_blocks * st.f_frsize) {
            continue;
        }

        // Close log file
        if (close(i2c_fd) < 0) {
            perror("Failed to close log file");
            continue;
        }
    }

    // Close I2C bus
    if (close(i2c_fd) < 0) {
        perror("Failed to close I2C bus");
    }

    // Close GPIO
    if (gpio_close(gpio_fd) < 0) {
        perror("Failed to close GPIO");
    }

    return 0;
}
