    struct timespec sleep_time;
    struct timespec interval;
    struct sigaction sa;
    int ret;

    // Install signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Open log file
    ret = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (ret < 0) {
        perror("open");
        close(fd);
        return 1;
    }

    // Set up sleep interval
    clock_gettime(CLOCK_REALTIME, &start_time);
    clock_gettime(CLOCK_REALTIME, &sleep_time);
    interval.tv_sec = 5;
    interval.tv_nsec = 0;

    while (1) {
        // Wait for sleep interval
        clock_gettime(CLOCK_REALTIME, &sleep_time);
        if (sleep_time.tv_sec != start_time.tv_sec || sleep_time.tv_nsec != start_time.tv_nsec) {
            clock_nanosleep(&interval, NULL);
            continue;
        }

        // Read I2C data
        ret = read(fd, &i2c_fd, 3);
        if (ret < 0) {
            perror("read");
            continue;
        }

        // Verify CRC8
        uint8_t crc8 = i2c_fd & 0xFF;
        uint8_t data[3] = {i2c_fd >> 8, i2c_fd & 0xFF, crc8};
        uint8_t calculated_crc8 = 0;
        for (int i = 0; i < 8; i++) {
            calculated_crc8 = (calculated_crc8 << 1) | (data[i] & 1);
            if (i < 7) {
                calculated_crc8 ^= CRC8_POLYNOMINAL;
            }
        }
        if (calculated_crc8 != crc8) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        // Log temperature reading
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", localtime(&now));
        fprintf(LOG_FILE, "%s %d\n", timestamp, i2c_fd & 0xFF);
    }

    // Clean up
    close(fd);
    close(i2c_fd);
    close(ret);
    return 0;
}

