#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <inttypes.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS 0x68
#define I2C_CLOCK_SPEED 100000
#define I2C_TIMEOUT 10
#define CRC8_POLYNOM 0x31
#define SDP810 CRC8_POLYNOM 0x1D
#define SDP810_SCALE_FACTOR 0x8000
#define SDP810_TEMPERATURE_OFFSET 0x1000
#define SDP810_PRESSURE_OFFSET 0x2000
#define SDP810_MAX_READ_SIZE 9

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("hvac_pressure_log.txt", "w");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (i2cInit(I2C_ADDRESS, I2C_CLOCK_SPEED, I2C_TIMEOUT) < 0) {
        perror("i2cInit");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize SDP810
    if (sdp810Init(I2C_ADDRESS, SDP810_CRC8_POLYNOM, SDP810_SCALE_FACTOR, SDP810_TEMPERATURE_OFFSET, SDP810_PRESSURE_OFFSET) < 0) {
        perror("sdp810Init");
        i2cClose(I2C_ADDRESS);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Trigger measurement
        if (sdp810Trigger() < 0) {
            fprintf(log_file, "Error triggering measurement\n");
            continue;
        }

        // Wait at least 50ms
        usleep(50000);

        // Read result
        uint8_t result[SDP810_MAX_READ_SIZE];
        if (sdp810Read(result, SDP810_MAX_READ_SIZE) < 0) {
            fprintf(log_file, "Error reading result\n");
            continue;
        }

        // Validate CRC-8
        uint8_t crc8 = (result[0] << 1) ^ (result[1] >> 7);
        if (crc8 != (result[2] & 0x7F)) {
            fprintf(log_file, "CRC-8 error\n");
            continue;
        }

        // Validate CRC-8 (again)
        crc8 = (result[3] << 1) ^ (result[4] >> 7);
        if (crc8 != (result[5] & 0x7F)) {
            fprintf(log_file, "CRC-8 error\n");
            continue;
        }

        // Validate scale factor
        if (result[6] != (result[7] >> 3)) {
            fprintf(log_file, "Scale factor error\n");
            continue;
        }

        // Validate temperature
        float temperature = (result[7] >> 4) * 0.01f;
        if (temperature < -273.15f || temperature > 1000.0f) {
            fprintf(log_file, "Temperature out of range\n");
            continue;
        }

        // Validate pressure
        uint16_t pressure = (result[7] & 0x3F) * SDP810_SCALE_FACTOR;
        if (pressure < 0 || pressure > 50000) {
            fprintf(log_file, "Pressure out of range\n");
            continue;
        }

        // Log data
        time_t now = time(NULL);
        fprintf(log_file, "%d,%d,%d\n", now, pressure, temperature);
    }

    // Cleanup
    sdp810Cleanup();
    i2cClose(I2C_ADDRESS);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

