#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SCD40_I2C_ADDRESS 0x40
#define SCD40_I2C_CLOCK 1
#define SCD40_I2C_DATA 0
#define SCD40_START_MEASUREMENT 0x01
#define SCD40_STOP_MEASUREMENT 0x00
#define SCD40_READ_DATA 0x02
#define SCD40_WRITE_DATA 0x03
#define SCD40_CRC8_POLYNOMIAL 0x31
#define SCD40_CRC8_INIT_VALUE 0x00
#define SCD40_BUFFER_SIZE 100
#define SCD40_LOG_FILE "/var/log/scd40_data/scd40_data.csv"
#define SCD40_ERROR_LOG "/var/log/scd40_error.log"

volatile sig_atomic_t running = 1;

struct SCD40_data {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    time_t timestamp;
};

struct SCD40_data buffer[SCD40_BUFFER_SIZE];
int buffer_index = 0;
int log_index = 0;

void* log_thread(void* arg) {
    while (running) {
        struct SCD40_data* data;
        char filename[256];
        char timestamp[32];

        sprintf(filename, "%s_%d.csv", SCD40_LOG_FILE, time(NULL));
        if (access(filename, F_OK) == -1) {
            mkdir("/var/log", 0777);
        }

        while (running) {
            pthread_mutex_lock(&log_mutex);
            while (buffer_index == SCD40_BUFFER_SIZE) {
                pthread_cond_wait(&log_cond, &log_mutex);
            }
            data = &buffer[buffer_index];
            pthread_mutex_unlock(&log_mutex);

            sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d", 
                   (int)time(NULL) / 86400, 
                   (int)time(NULL) / 3600 % 24, 
                   (int)time(NULL) / 60 % 60, 
                   (int)time(NULL) % 60, 
                   (int)time(NULL) % 60);

            fprintf(filename, "%s,CO2:%04x,Temp:%04x,Humidity:%04x\n", timestamp, data->co2, data->temperature, data->humidity);
            log_index++;
            buffer_index = (buffer_index + 1) % SCD40_BUFFER_SIZE;
        }

        pthread_mutex_lock(&log_mutex);
        pthread_cond_signal(&log_cond);
        pthread_mutex_unlock(&log_mutex);
    }

    return NULL;
}

void* main_thread(void* arg) {
    int i2c_fd;
    int ret;
    uint8_t crc8;
    uint16_t co2, temperature, humidity;
    struct SCD40_data* data;
    char filename[256];
    char timestamp[32];

    i2c_fd = pigpio_open(SCD40_I2C_ADDRESS, I2C_MODE_READ_WRITE);
    if (i2c_fd < 0) {
        fprintf(SCD40_ERROR_LOG, "Failed to open I2C device\n");
        return NULL;
    }

    pigpio_delay(1000); // wait for I2C bus to settle

    while (running) {
        pigpio_write(i2c_fd, SCD40_START_MEASUREMENT, 0);
        pigpio_delay(10);
        pigpio_write(i2c_fd, SCD40_STOP_MEASUREMENT, 0);
        pigpio_delay(10);

        pigpio_write(i2c_fd, SCD40_READ_DATA, 0);
        ret = pigpio_read(i2c_fd, &crc8, 1);
        if (ret < 0) {
            fprintf(SCD40_ERROR_LOG, "I2C read error\n");
            continue;
        }

        pigpio_write(i2c_fd, SCD40_READ_DATA, 0);
        ret = pigpio_read(i2c_fd, &co2, 2);
        if (ret < 0) {
            fprintf(SCD40_ERROR_LOG, "I2C read error\n");
            continue;
        }

        pigpio_write(i2c_fd, SCD40_READ_DATA, 0);
        ret = pigpio_read(i2c_fd, &temperature, 2);
        if (ret < 0) {
            fprintf(SCD40_ERROR_LOG, "I2C read error\n");
            continue;
        }

        pigpio_write(i2c_fd, SCD40_READ_DATA, 0);
        ret = pigpio_read(i2c_fd, &humidity, 2);
        if (ret < 0) {
            fprintf(SCD40_ERROR_LOG, "I2C read error\n");
            continue;
        }

        crc8 = (crc8 << 8) | co2;
        crc8 = (crc8 << 8) | temperature;
        crc8 = (crc8 << 8) | humidity;

        for (i = 0; i < 8; i++) {
            if ((crc8 >> i) & 1) {
                crc8 ^= SCD40_CRC8_POLYNOMINAL;
            }
        }

        if (crc8 != SCD40_CRC8_INIT_VALUE) {
            fprintf(SCD40_ERROR_LOG, "CRC error\n");
            continue;
        }

        data = &buffer[buffer_index];
        data->co2 = co2;
        data->temperature = temperature;
        data->humidity = humidity;
        data->timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % SCD40_BUFFER_SIZE;

        pthread_mutex_lock(&log_mutex);
        pthread_cond_signal(&log_cond);
        pthread_mutex_unlock(&log_mutex);
    }

    pigpio_close(i2c_fd);
    return NULL;
}

int main() {
    pthread_t log_thread_id;
    pthread_t main_thread_id;

    pthread_mutex_init(&log_mutex, NULL);
    pthread_cond_init(&log_cond, NULL);

    pthread_create(&log_thread_id, NULL, log_thread, NULL);
    pthread_create(&main_thread_id, NULL, main_thread, NULL);

    pthread_join(log_thread_id, NULL);
    pthread_join(main_thread_id, NULL);

    return 0;
}

