    int i2c_fd = -1;
    int i2c_result = -1;
    int crc8_result = -1;
    int scale_factor = -1;
    int temperature = -1;
    int differential_pressure = -1;
    int log_fd = -1;
    struct timespec last_trigger = {0, 0};
    struct timespec current_time;
    struct stat sb;
    struct sigaction sa;

