        clock_gettime(CLOCK_REALTIME, &current_time);
        if (current_time.tv_sec - last_trigger.tv_sec >= 0.045) {
            last_trigger = current_time;

            // Read differential pressure
            i2c_result = pigpio_i2c_read(i2c_fd, SDP810_ADDRESS, SDP810_REG_Differential_PRESSURE, 2, &differential_pressure);
            if (i2c_result < 0) {
                perror("pigpio_i2c_read");
                continue;
            }

            // Read temperature
            i2c_result = pigpio_i2c_read(i2c_fd, SDP810_ADDRESS, SDP810_REG_TEMPERATURE, 2, &temperature);
            if (i2c_result < 0) {
                perror("pigpio_i2c_read");
                continue;
            }

            // Read scale factor
            i2c_result = pigpio_i2c_read(i2c_fd, SDP810_ADDRESS, SDP810_REG_SCALE_FACTOR, 2, &scale_factor);
            if (i2c_result < 0) {
                perror("pigpio_i2c_read");
                continue;
            }

            // Read CRC
            i2c_result = pigpio_i2c_read(i2c_fd, SDP810_ADDRESS, SDP810_REG_CRC, 2, &crc8_result);
            if (i2c_result < 0) {
                perror("pigpio_i2c_read");
                continue;
            }

            // Validate CRC
            if (crc8_result != (crc8_result ^ (crc8_result >> 1))) {
                fprintf(stderr, "CRC error\n");
                continue;
            }

            // Validate temperature
            if (temperature < 0 || temperature > 100) {
                fprintf(stderr, "Invalid temperature\n");
                continue;
            }

            // Validate scale factor
            if (scale_factor < 0 || scale_factor > 100) {
                fprintf(stderr, "Invalid scale factor\n");
                continue;
            }

            // Calculate pressure
            differential_pressure = (differential_pressure << 8) | temperature;

            // Write to log file
            fprintf(log_fd, "%f,%d,%d\n", (double)last_trigger.tv_sec + last_trigger.tv_nsec / 1e9, differential_pressure / scale_factor, temperature);

            // Close I2C handle
            pigpio_i2c_close(i2c_fd);
            i2c_fd = -1;
        }
    }

    // Close log file
    if (log_fd >= 0) {
        close(log_fd);
    }

    // Terminate
    return 0;
}

void sigint_handler(int sig) {
    // Close I2C handle
    if (i2c_fd >= 0) {
        pigpio_i2c_close(i2c_fd);
        i2c_fd = -1;
    }

    // Terminate
    exit(0);
}

