    int i2c_fd = -1;
    int ret;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec interval;
    struct timespec sleep_time;
    int exit_flag = 0;
    char buffer[3];

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open the I2C bus
    i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_CLOCK_SPEED);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up the I2C clock
    pigpio_i2c_set_clock(i2c_fd, I2C_CLOCK_SPEED);

    // Set up the I2C data direction
    pigpio_i2c_set_data_direction(i2c_fd, I2C_ADDRESS, I2C_READ);

    while (!exit_flag) {
        // Get the current time
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Wait for 10ms
        sleep_time.tv_sec = start_time.tv_sec + 10;
        sleep_time.tv_nsec = start_time.tv_nsec;
        nanosleep(&sleep_time, NULL);

        // Read the pressure and temperature
        ret = pigpio_i2c_read(i2c_fd, I2C_ADDRESS, 6, buffer, 6);
        if (ret < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Convert the data to integers
        int pressure = (buffer[0] << 8) | buffer[1];
        int temperature = (buffer[2] << 8) | buffer[3];

        // Create a timestamp
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06d", localtime(&start_time));

        // Append the data to the file
        FILE *file = fopen("environmental_data.txt", "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file\n");
            continue;
        }
        fprintf(file, "%s %d %d\n", timestamp, pressure, temperature);
        fclose(file);

        // Print the data to stdout
        printf("%s %d %d\n", timestamp, pressure, temperature);

        // Check for SIGINT
        if (gpioGetSignalLevel(17) == 1) {
            exit_flag = 1;
        }
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    gpioTerminate();
    return 0;
}

