#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define I2C_ADDRESS 0x69
#define GPIO_PIN 17
#define GPIO_MODE_OUTPUT
#define GPIO_LEVEL_LOW 0
#define GPIO_LEVEL_HIGH 1
#define DELAY_MS 20
#define POLL_INTERVAL_MS 1000
#define PRESSURE_THRESHOLD 95000

int main() {
    int i2c_fd, gpio_fd;
    struct i2c_client *client;
    struct i2c_dev *dev;
    struct gpio_action *action;
    struct gpio_value value;
    struct sigaction sa;
    struct sigaction sa_int;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set GPIO pin as output
    if (gpioSetMode(GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        exit(1);
    }

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &sa_int) < 0) {
        perror("sigaction");
        exit(1);
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }

    // Check if I2C device is present
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        if (errno == ENODEV) {
            printf("I2C device not found\n");
            exit(1);
        } else {
            perror("ioctl");
            exit(1);
        }
    }

    // Map I2C device memory
    dev = i2c_get_clientdata(i2c_fd);
    if (dev == NULL) {
        perror("i2c_get_clientdata");
        exit(1);
    }

    // Create I2C client
    client = i2c_new_client(i2c_fd, I2C_ADDRESS, NULL, NULL);
    if (client == NULL) {
        perror("i2c_new_client");
        exit(1);
    }

    // Map I2C device memory
    void *mem = mmap(NULL, 6, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }

    while (1) {
        // Read I2C data
        if (i2c_read(client, mem, 6, NULL) < 0) {
            if (errno == EIO) {
                printf("I2C error\n");
            } else {
                perror("i2c_read");
                exit(1);
            }
        }

        // Verify CRC
        if (mem[4] != (mem[5] << 8 | mem[6])) {
            printf("CRC error\n");
            continue;
        }

        // Extract pressure and temperature
        int pressure = (mem[0] << 8 | mem[1]);
        int temperature = (mem[2] << 8 | mem[3]);

        // Check if pressure is valid
        if (pressure < 0 || pressure > 104000) {
            printf("Invalid pressure\n");
            continue;
        }

        // Blink LED
        if (pressure < PRESSURE_THRESHOLD) {
            gpio_value_t level = GPIO_LEVEL_HIGH;
            gpioWrite(GPIO_PIN, level);
        } else {
            gpio_value_t level = GPIO_LEVEL_LOW;
            gpioWrite(GPIO_PIN, level);
        }

        // Delay
        usleep(DELAY_MS * 1000);

        // Poll I2C device
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpioWrite(GPIO_PIN, GPIO_LEVEL_LOW);
    gpioCleanse(GPIO_PIN);
    gpioDestroy();
    close(i2c_fd);
    munmap(mem, 6);
    i2c_free_client(client);
    i2c_close(i2c_fd);

    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(GPIO_PIN, GPIO_LEVEL_LOW);
    gpioCleanse(GPIO_PIN);
    gpioDestroy();
    close(i2c_fd);
    munmap(NULL, 6);
    i2c_free_client(NULL);
    i2c_close(i2c_fd);
    exit(0);
}

