    void *i2c_map = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (i2c_map == MAP_FAILED) {
        perror("mmap");
        close(log_fd);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Define the fan pin configuration
    gpioSetMode(FAN_PIN, GPIO_MODE_OUTPUT);
    gpioToggle(FAN_PIN);

    while (1) {
        // Read the ambient temperature
        int retry = 0;
        int temp_ambient = 0;
        while (retry < 3) {
            int status = i2cRead(i2c_fd, 0x00, 2, &temp_ambient);
            if (status < 0) {
                if (errno == EIO) {
                    usleep(10);
                    retry++;
                } else {
                    perror("i2cRead");
                    retry = 3;
                }
            } else {
                break;
            }
        }

        if (retry == 3) {
            continue;
        }

        // Read the object temperature
        int temp_object = 0;
        while (retry < 3) {
            int status = i2cRead(i2c_fd, 0x01, 2, &temp_object);
            if (status < 0) {
                if (errno == EIO) {
                    usleep(10);
                    retry++;
                } else {
                    perror("i2cRead");
                    retry = 3;
                }
            } else {
                break;
            }
        }

        if (retry == 3) {
            continue;
        }

        // Calculate the average temperature
        int temp_average = (temp_ambient + temp_object) / 2;

        // Log the temperature
        char log_line[20];
        sprintf(log_line, "%d %d %d\n", (int)time(NULL), temp_ambient, temp_object);
        write(log_fd, log_line, strlen(log_line));

        // Control the fan
        if (temp_average > 30) {
            gpioToggle(FAN_PIN);
        } else if (temp_average < 28) {
            gpioToggle(FAN_PIN);
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Close the I2C handle
    i2cClose(i2c_fd);
    close(log_fd);

    // Terminate the GPIO library
    gpioTerminate();

    return 0;
}

