#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x44
#define I2C_ADDRESS_SHT40 0x44
#define I2C Bus 1
#define BUFFER_SIZE 6

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize gpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        gpioTerminate();
        return 1;
    }

    // Create a socket for HTTP server
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    // Create socket for HTTP server
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        return 1;
    }

    printf("Server listening on port 8080...\n");

    while (1) {
        // Wait for a connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        // Read data from client
        read(new_socket, buffer, BUFFER_SIZE);
        printf("Received message from client: %s\n", buffer);

        // Read temperature and humidity from SHT40 sensor
        int retry = 0;
        while (retry < 3) {
            if (gpiod_i2c_open(Bus 1, I2C_ADDRESS_SHT40, &gpiod_i2c_handle) < 0) {
                perror("gpiod_i2c_open");
                retry++;
                sleep(10);
                continue;
            }

            if (gpiod_i2c_write(gpiod_i2c_handle, I2C_ADDRESS_SHT40, 0x44, 1) < 0) {
                perror("gpiod_i2c_write");
                retry++;
                sleep(10);
                continue;
            }

            if (gpiod_i2c_read(gpiod_i2c_handle, I2C_ADDRESS_SHT40, 0x00, BUFFER_SIZE, 1) < 0) {
                perror("gpiod_i2c_read");
                retry++;
                sleep(10);
                continue;
            }

            gpiod_i2c_close(gpiod_i2c_handle);
            break;
        }

        if (retry >= 3) {
            perror("Failed to read from SHT40 sensor");
            continue;
        }

        // Parse temperature and humidity from buffer
        int temperature = (BUFFER_SIZE - 2) * 2;
        int humidity = BUFFER_SIZE - 2;

        // Clamp humidity to range 0-100
        if (humidity > 100) {
            humidity = 100;
        } else if (humidity < 0) {
            humidity = 0;
        }

        // Send response to client
        char response[256];
        sprintf(response, "Temperature: %.2f°C, Humidity: %.2f%%", temperature / 10.0, humidity / 10.0);
        send(new_socket, response, strlen(response), 0);

        // Close socket
        close(new_socket);
    }

    // Clean up
    gpioTerminate();
    close(server_fd);
    return 0;
}

