// Define the I2C address of the TMP102
#define TMP102_ADDRESS 0x68

// Define the I2C bus number
#define I2C_BUS 1

// Define the file name for the temperature log
#define LOG_FILE "temperature_log.csv"

// Define the interval for reading temperature (in seconds)
#define INTERVAL 5

// Define the number of retries for I2C read
#define RETRIES 3

// Define the buffer size for I2C read
#define BUFFER_SIZE 2

// Define the format string for the log file
#define LOG_FORMAT "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n"

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Close the I2C handle
    if (gpioClose(I2C_HANDLE) < 0) {
        perror("gpioClose");
    }
    // Terminate the driver library
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
    }
    // Exit the program
    exit(1);
}

int main() {
    // Initialize the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the I2C handle
    I2C_HANDLE = gpioInit(I2C_BUS);
    if (I2C_HANDLE < 0) {
        perror("gpioInit");
        return 1;
    }

    // Open the log file for writing
    if (access(LOG_FILE, F_OK) == -1) {
        if (mkdir(LOG_FILE, 0755) < 0) {
            perror("mkdir");
            return 1;
        }
    }
    if (fopen(LOG_FILE, "w") == NULL) {
        perror("fopen");
        return 1;
    }

    // Open the log file for appending
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    // Initialize the last timestamp
    last_timestamp = time(NULL);

    while (1) {
        // Read the temperature
        int ret = i2cRead(I2C_HANDLE, TMP102_ADDRESS, BUFFER_SIZE, &buffer[0]);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                // Log the read failure and continue to the next iteration
                fprintf(stderr, "I2C read timed out\n");
                continue;
            } else if (errno == EIO) {
                // Log the read failure and continue to the next iteration
                fprintf(stderr, "I2C read error: %s\n", strerror(errno));
                continue;
            } else {
                // Log the read failure and exit the program
                fprintf(stderr, "I2C read error: %s\n", strerror(errno));
                return 1;
            }
        }

        // Convert the temperature to Celsius
        float temperature = (buffer[0] << 8) | buffer[1];

        // Calculate the current timestamp
        time_t current_timestamp = time(NULL);
        if (current_timestamp - last_timestamp >= INTERVAL) {
            // Format the timestamp
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime(&current_timestamp));

            // Append the temperature to the log file
            fprintf(log_file, "%s,%.2f\n", timestamp, temperature);

            // Update the last timestamp
            last_timestamp = current_timestamp;
        }
    }

    // Close the log file
    if (fclose(log_file) < 0) {
        perror("fclose");
        return 1;
    }

    // Close the I2C handle
    if (gpioClose(I2C_HANDLE) < 0) {
        perror("gpioClose");
        return 1;
    }

    return 0;
}

