        }

        // Convert the temperature to Celsius
        float temperature = (buffer[0] << 8) | buffer[1];

        // Calculate the current timestamp
        time_t current_timestamp = time(NULL);
        if (current_timestamp - last_timestamp >= INTERVAL) {
            // Format the timestamp
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime(&current_timestamp));

            // Append the temperature to the log file
            fprintf(log_file, "%s,%.2f\n", timestamp, temperature);

            // Update the last timestamp
            last_timestamp = current_timestamp;
        }
    }

    // Close the log file
    if (fclose(log_file) < 0) {
        perror("fclose");
        return 1;
    }

    // Close the I2C handle
    if (gpioClose(I2C_HANDLE) < 0) {
        perror("gpioClose");
        return 1;
    }

    return 0;
}
