        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);

    while (!shutdown) {
        // Wait for MEASUREMENT_CONFIG to clear
        start = times(&tms_before);
        for (i = 0; i < MAX_RETRIES; i++) {
            if (i2cWrite(1, MEASUREMENT_CONFIG, 0x00) < 0) {
                if (i2cGetError() != 0) {
                    if (i < MAX_RETRIES - 1) {
                        usleep(100000);
                    } else {
                        printf("I2C error: %d\n", i2cGetError());
                        break;
                    }
                } else {
                    printf("I2C error: No response from sensor\n");
                    break;
                }
            } else {
                usleep(I2C_TIMEOUT);
            }
            if (i2cRead(1, MEASUREMENT_DATA, &measurement_config) < 0) {
                if (i2cGetError() != 0) {
                    if (i < MAX_RETRIES - 1) {
                        usleep(100000);
                    } else {
                        printf("I2C error: %d\n", i2cGetError());
                        break;
                    }
                } else {
                    printf("I2C error: No response from sensor\n");
                    break;
                }
            } else {
                break;
            }
        }

        if (i == MAX_RETRIES) {
            printf("Timeout: Could not read from sensor\n");
            break;
        }

        // Read measurement data
        if (i2cRead(1, MEASUREMENT_DATA, &measurement_config) < 0) {
            if (i2cGetError() != 0) {
                printf("I2C error: %d\n", i2cGetError());
            } else {
                printf("I2C error: No response from sensor\n");
            }
            continue;
        }

        // Extract temperature and humidity
        temperature = (measurement_config >> 8) & 0xFF;
        humidity = measurement_config & 0xFF;

        // Print readings
        printf("Temperature: %d°C, Humidity: %d%%\n", temperature, humidity);

        // Wait for 5 seconds
        times(&tms_after);
        nanosleep(&tms_after - tms_before, NULL);
    }

    // Clean up
    i2cClose(1);
    gpioTerminate();
    return 0;
}

