#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

#define I2C_ADDRESS 0x68
#define I2C Bus 1
#define I2C_TIMEOUT 45
#define I2C_READ_SIZE 6
#define I2C_CRC8_POLYNOMIAL 0x31
#define I2C_CRC8_INIT_VALUE 0x00

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, uint8_t len) {
    uint8_t crc = I2C_CRC8_INIT_VALUE;
    for (uint8_t i = 0; i < len; i++) {
        crc = (crc >> 1);
        if ((crc & 0x80) && (data[i] ^ crc)) {
            crc = (crc ^ 0x31);
        }
    }
    return crc;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    if (gpioI2COpen(I2C Bus, I2C_ADDRESS, 100) < 0) {
        perror("gpioI2COpen");
        return 1;
    }

    // Set I2C clock speed
    if (gpioI2CSetClock(I2C Bus, 100000) < 0) {
        perror("gpioI2CSetClock");
        return 1;
    }

    // Set I2C mode
    if (gpioI2CSetMode(I2C Bus, I2C_MODE_MASTER) < 0) {
        perror("gpioI2CSetMode");
        return 1;
    }

    // Set I2C address
    if (gpioI2CSlaveAddress(I2C Bus, I2C_ADDRESS) < 0) {
        perror("gpioI2CSlaveAddress");
        return 1;
    }

    // Main loop
    while (1) {
        // Read from sensor
        uint8_t data[I2C_READ_SIZE];
        if (gpioI2CRead(I2C Bus, data, I2C_READ_SIZE, I2C_TIMEOUT) < 0) {
            perror("gpioI2CRead");
            continue;
        }

        // Validate CRC8 checksum
        if (crc8(data, I2C_READ_SIZE) != data[I2C_READ_SIZE - 1]) {
            printf("CRC8 error\n");
            continue;
        }

        // Validate temperature CRC8 checksum
        if (crc8(&data[I2C_READ_SIZE - 2], 2) != data[I2C_READ_SIZE - 2]) {
            printf("Temperature CRC8 error\n");
            continue;
        }

        // Validate pressure CRC8 checksum
        if (crc8(&data[I2C_READ_SIZE - 4], 2) != data[I2C_READ_SIZE - 4]) {
            printf("Pressure CRC8 error\n");
            continue;
        }

        // Print raw pressure and temperature values
        printf("Pressure: %d Pa\n", (data[0] << 8) | data[1]);
        printf("Temperature: %d mK\n", (data[2] << 8) | data[3]);

        // Wait for 500 ms
        usleep(500000);
    }

    // Clean up
    gpioI2CClose(I2C Bus);
    gpioTerminate();
    return 0;
}

