#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define MAX_LOG_LINES 1000
#define MAX_PROFILE_LINES 1000
#define MAX_PROFILE_SIZE (MAX_PROFILE_LINES * 3)

// Define the SPI device and GPIO pins
#define SPI_DEVICE SPI0
#define GPIO_PIN 17
#define GPIO_CE0 18
#define GPIO_CE1 19

// Define the thermocouple and relay pins
#define TC_PIN 22
#define RELAY_PIN GPIO_PIN

// Define the PID parameters
#define PID_Kp 0.1
#define PID_Ki 0.01
#define PID_Kd 0.05

// Define the SPI mode and clock speed
#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000

// Define the file paths
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"

// Define the PID structure
typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double error;
    double integral;
    double previous_error;
    double previous_integral;
    double output;
} pid_t;

// Define the thermocouple structure
typedef struct {
    int fd;
    void* mem;
    size_t size;
} thermocouple_t;

// Define the relay structure
typedef struct {
    int fd;
    void* mem;
    size_t size;
} relay_t;

// Define the SPI context
typedef struct {
    pigpio_t* gpio;
    void* mem;
    size_t size;
} spi_context_t;

// Define the PID context
typedef struct {
    pid_t* pid;
    double target_temp;
    double setpoint;
    double error;
    double integral;
    double previous_error;
    double previous_integral;
    double output;
} pid_context_t;

// Function to initialize the SPI context
void init_spi_context(spi_context_t* ctx) {
    ctx->gpio = pigpio_init();
    if (ctx->gpio == -1) {
        printf("Error initializing GPIO\n");
        exit(1);
    }
    ctx->mem = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->gpio, 0);
    if (ctx->mem == MAP_FAILED) {
        printf("Error mapping memory\n");
        exit(1);
    }
    ctx->size = pigpio_get_mem_size(ctx->gpio);
}

// Function to initialize the thermocouple context
void init_thermocouple(thermocouple_t* ctx) {
    ctx->fd = pigpio_open(SPI_DEVICE, GPIO_CE0, pigpio inputs, pigpio pulls_up_down);
    if (ctx->fd == -1) {
        printf("Error opening thermocouple\n");
        exit(1);
    }
    ctx->mem = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, 0);
    if (ctx->mem == MAP_FAILED) {
        printf("Error mapping thermocouple memory\n");
        exit(1);
    }
    ctx->size = pigpio_get_mem_size(ctx->fd);
}

// Function to initialize the relay context
void init_relay(relay_t* ctx) {
    ctx->fd = pigpio_open(GPIO_PIN, pigpio outputs, pigpio pulls_up_down);
    if (ctx->fd == -1) {
        printf("Error opening relay\n");
        exit(1);
    }
    ctx->mem = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, 0);
    if (ctx->mem == MAP_FAILED) {
        printf("Error mapping relay memory\n");
        exit(1);
    }
    ctx->size = pigpio_get_mem_size(ctx->fd);
}

// Function to read the thermocouple value
double read_thermocouple(thermocouple_t* ctx) {
    uint8_t data[3];
    pigpio_write(ctx->fd, 0x00, 0x00);
    pigpio_read(ctx->fd, data, 3);
    return (data[0] * 0.01) - 273.15;
}

// Function to update the PID output
void update_pid(pid_context_t* ctx) {
    double error = ctx->setpoint - ctx->error;
    ctx->integral += error * PID_Ki;
    ctx->previous_integral += ctx->integral;
    ctx->error = error;
    ctx->output = ctx->Kp * error + ctx->integral + ctx->previous_integral * PID_Kd;
    ctx->output = constrain(ctx->output, 0.0, 1.0);
}

// Function to update the relay duty cycle
void update_relay(relay_t* ctx, double output) {
    pigpio_write(ctx->fd, 0x00, output * 255);
}

// Function to log the temperature reading
void log_temperature(pid_context_t* ctx, double temp) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Error opening log file\n");
        exit(1);
    }
    fprintf(file, "%f,%f\n", time(NULL), temp);
    fclose(file);
}

// Function to load the target temperature profile
void load_profile(pid_context_t* ctx, char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening profile file\n");
        exit(1);
    }
    char line[256];
    int line_count = 0;
    while (fgets(line, 256, file)) {
        if (line_count >= MAX_PROFILE_LINES) {
            break;
        }
        char* token = strtok(line, ",");
        if (token == NULL) {
            break;
        }
        double time_seconds = atof(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            break;
        }
        double target_temp = atof(token);
        ctx->setpoint = target_temp;
        line_count++;
    }
    fclose(file);
}

// Function to main
int main(int argc, char** argv) {
    // Initialize the signal handler
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        printf("Error setting signal handler\n");
        exit(1);
    }

    // Initialize the SPI context
    spi_context_t ctx;
    init_spi_context(&ctx);

    // Initialize the thermocouple context
    thermocouple_t thermocouple;
    init_thermocouple(&thermocouple);

    // Initialize the relay context
    relay_t relay;
    init_relay(&relay);

    // Initialize the PID context
    pid_context_t pid;
    pid.pid = malloc(sizeof(pid_t));
    pid.pid->Kp = PID_Kp;
    pid.pid->Ki = PID_Ki;
    pid.pid->Kd = PID_Kd;
    pid.pid->error = 0.0;
    pid.pid->integral = 0.0;
    pid.pid->previous_error = 0.0;
    pid.pid->previous_integral = 0.0;
    pid.pid->output = 0.0;
    pid.target_temp = 0.0;

    // Load the target temperature profile
    load_profile(&pid, PROFILE_FILE);

    // Main loop
    while (1) {
        // Read the thermocouple value
        double temp = read_thermocouple(&thermocouple);

        // Update the PID output
        update_pid(&pid);

        // Update the relay duty cycle
        update_relay(&relay, pid.pid->output);

        // Log the temperature reading
        log_temperature(&pid, temp);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    free(pid.pid);
    pigpio_close(thermocouple.fd);
    pigpio_close(relay.fd);
    pigpio_close(ctx.gpio);
    munmap(ctx.mem, ctx.size);
    munmap(thermocouple.mem, thermocouple.size);
    munmap(relay.mem, relay.size);
    return 0;
}

