        printf("Error mapping thermocouple memory\n");
        exit(1);
    }
    ctx->size = pigpio_get_mem_size(ctx->fd);
}

// Function to initialize the relay context
void init_relay(relay_t* ctx) {
    ctx->fd = pigpio_open(GPIO_PIN, pigpio outputs, pigpio pulls_up_down);
    if (ctx->fd == -1) {
        printf("Error opening relay\n");
        exit(1);
    }
    ctx->mem = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, 0);
    if (ctx->mem == MAP_FAILED) {
        printf("Error mapping relay memory\n");
        exit(1);
    }
    ctx->size = pigpio_get_mem_size(ctx->fd);
}

// Function to read the thermocouple value
double read_thermocouple(thermocouple_t* ctx) {
    uint8_t data[3];
    pigpio_write(ctx->fd, 0x00, 0x00);
    pigpio_read(ctx->fd, data, 3);
    return (data[0] * 0.01) - 273.15;
}

// Function to update the PID output
void update_pid(pid_context_t* ctx) {
    double error = ctx->setpoint - ctx->error;
    ctx->integral += error * PID_Ki;
    ctx->previous_integral += ctx->integral;
    ctx->error = error;
    ctx->output = ctx->Kp * error + ctx->integral + ctx->previous_integral * PID_Kd;
    ctx->output = constrain(ctx->output, 0.0, 1.0);
}

// Function to update the relay duty cycle
void update_relay(relay_t* ctx, double output) {
    pigpio_write(ctx->fd, 0x00, output * 255);
}

// Function to log the temperature reading
void log_temperature(pid_context_t* ctx, double temp) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Error opening log file\n");
        exit(1);
    }
    fprintf(file, "%f,%f\n", time(NULL), temp);
    fclose(file);
}

// Function to load the target temperature profile
void load_profile(pid_context_t* ctx, char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening profile file\n");
        exit(1);
    }
    char line[256];
    int line_count = 0;
    while (fgets(line, 256, file)) {
        if (line_count >= MAX_PROFILE_LINES) {
            break;
        }
        char* token = strtok(line, ",");
        if (token == NULL) {
            break;
        }
        double time_seconds = atof(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            break;
        }
        double target_temp = atof(token);
        ctx->setpoint = target_temp;
        line_count++;
    }
    fclose(file);
}

// Function to main
int main(int argc, char** argv) {
    // Initialize the signal handler
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        printf("Error setting signal handler\n");
        exit(1);
    }

    // Initialize the SPI context
    spi_context_t ctx;
    init_spi_context(&ctx);

    // Initialize the thermocouple context
    thermocouple_t thermocouple;
    init_thermocouple(&thermocouple);

    // Initialize the relay context
    relay_t relay;
    init_relay(&relay);

    // Initialize the PID context
    pid_context_t pid;
    pid.pid = malloc(sizeof(pid_t));
    pid.pid->Kp = PID_Kp;
    pid.pid->Ki = PID_Ki;
    pid.pid->Kd = PID_Kd;
    pid.pid->error = 0.0;
    pid.pid->integral = 0.0;
    pid.pid->previous_error = 0.0;
    pid.pid->previous_integral = 0.0;
    pid.pid->output = 0.0;
    pid.target_temp = 0.0;

    // Load the target temperature profile
    load_profile(&pid, PROFILE_FILE);

    // Main loop
    while (1) {
        // Read the thermocouple value
        double temp = read_thermocouple(&thermocouple);

        // Update the PID output
        update_pid(&pid);

        // Update the relay duty cycle
        update_relay(&relay, pid.pid->output);

        // Log the temperature reading
        log_temperature(&pid, temp);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    free(pid.pid);
    pigpio_close(thermocouple.fd);
    pigpio_close(relay.fd);
    pigpio_close(ctx.gpio);
    munmap(ctx.mem, ctx.size);
    munmap(thermocouple.mem, thermocouple.size);
    munmap(relay.mem, relay.size);
    return 0;
}
