#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <w1-gpio.h>
#include <pigpio.h>
#include <syslog.h>

#define LOG_FILE "greenhouse.log"

// Define the DS18B20 sensor and relay constants
#define DS18B20_PIN 4
#define RELAY_PIN 17
#define PWM_PIN 18

// Define the PID constants
#define PID_Kp 2.0
#define PID_Ki 0.5
#define PID_Kd 0.1

// Define the temperature units (Celsius)
#define TEMPERATURE_UNIT C

// Define the temperature conversion factor
#define TEMPERATURE_FACTOR 1.0 / 1000.0

// Define the relay and PWM states
#define RELAY_OFF 0
#define RELAY_ON 1

// Define the PID output range
#define PID_OUTPUT_MIN 0.0
#define PID_OUTPUT_MAX 100.0

// Define the temperature range
#define TEMPERATURE_MIN -50.0
#define TEMPERATURE_MAX 50.0

// Define the temperature step
#define TEMPERATURE_STEP 0.1

// Define the log format
#define LOG_FORMAT "%s %f %f %f %f %d\n"

// Define the signal handlers
void sigint_handler(int sig) {
    // Cleanly release resources
    close(RELAY_FILE);
    close(PWM_FILE);
    close(LOG_FILE);
    pigpio_close(RELAY_PIN);
    pigpio_close(PWM_PIN);
    exit(0);
}

void sigterm_handler(int sig) {
    // Cleanly release resources
    close(RELAY_FILE);
    close(PWM_FILE);
    close(LOG_FILE);
    pigpio_close(RELAY_PIN);
    pigpio_close(PWM_PIN);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the log file
    LOG_FILE = fopen(LOG_FILE, "a");
    if (LOG_FILE == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize the w1-gpio kernel module
    w1_gpio_init();
    if (w1_gpio_init() != 0) {
        perror("Failed to initialize w1-gpio kernel module");
        return 1;
    }

    // Open the relay file
    RELAY_FILE = fopen("/sys/class/relay/relay0/enable", "w");
    if (RELAY_FILE == NULL) {
        perror("Failed to open relay file");
        return 1;
    }

    // Open the PWM file
    PWM_FILE = fopen("/sys/class/pwm/pwm0/pwm", "w");
    if (PWM_FILE == NULL) {
        perror("Failed to open PWM file");
        return 1;
    }

    // Open the DS18B20 device
    int ds18b20_fd = w1_gpio_open(DS18B20_PIN);
    if (ds18b20_fd < 0) {
        perror("Failed to open DS18B20 device");
        return 1;
    }

    // Set the DS18B20 device to scan mode
    w1_gpio_set_bit(ds18b20_fd, W1_Gpio_DQ);

    // Read the DS18B20 temperature
    int ds18b20_crc = w1_gpio_read(ds18b20_fd);
    if (ds18b20_crc != 0) {
        fprintf(LOG_FILE, "DS18B20 CRC error\n");
        fclose(RELAY_FILE);
        fclose(PWM_FILE);
        close(ds18b20_fd);
        close(LOG_FILE);
        pigpio_close(RELAY_PIN);
        pigpio_close(PWM_PIN);
        exit(1);
    }

    double temperature = (ds18b20_crc == 0) ? w1_gpio_read(ds18b20_fd) * TEMPERATURE_FACTOR : -1.0;

    // Validate the temperature
    if (temperature < TEMPERATURE_MIN || temperature > TEMPERATURE_MAX) {
        fprintf(LOG_FILE, "Invalid temperature reading\n");
        fclose(RELAY_FILE);
        fclose(PWM_FILE);
        close(ds18b20_fd);
        close(LOG_FILE);
        pigpio_close(RELAY_PIN);
        pigpio_close(PWM_PIN);
        exit(1);
    }

    // Initialize the PID variables
    double pid_output = 0.0;
    double pid_error = 0.0;
    double pid_integral = 0.0;

    while (1) {
        // Read the DS18B20 temperature
        ds18b20_crc = w1_gpio_read(ds18b20_fd);
        if (ds18b20_crc != 0) {
            temperature = (ds18b20_crc == 0) ? w1_gpio_read(ds18b20_fd) * TEMPERATURE_FACTOR : -1.0;
        } else {
            temperature = pid_output;
        }

        // Calculate the PID error
        pid_error = temperature - TEMPERATURE_SETPOINT;

        // Calculate the PID output
        pid_output = PID_Kp * pid_error + PID_Ki * pid_integral + PID_Kd * (pid_error - pid_integral);

        // Limit the PID output
        pid_output = (pid_output < PID_OUTPUT_MIN) ? PID_OUTPUT_MIN : (pid_output > PID_OUTPUT_MAX) ? PID_OUTPUT_MAX : pid_output;

        // Set the relay state
        if (pid_output > 0) {
            pigpio_write(RELAY_PIN, RELAY_ON);
        } else {
            pigpio_write(RELAY_PIN, RELAY_OFF);
        }

        // Set the PWM duty cycle
        pigpio_write(PWM_PIN, (int) (pid_output * 100));

        // Log the data
        fprintf(LOG_FILE, LOG_FORMAT, "%s %f %f %f %f %d\n", localtime(NULL)->tm_year + 1900, temperature, TEMPERATURE_SETPOINT, pid_output, (int) (pid_output * 100));

        // Update the PID integral
        pid_integral += pid_error;

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanly release resources
    fclose(RELAY_FILE);
    fclose(PWM_FILE);
    close(ds18b20_fd);
    close(LOG_FILE);
    pigpio_close(RELAY_PIN);
    pigpio_close(PWM_PIN);

    return 0;
}

