This code implements a PID-controlled greenhouse heater using a DS18B20 temperature sensor and a 12V heater driven through a relay and hardware PWM. The program accepts command-line arguments specifying the desired temperature setpoint and the PID gains Kp, Ki, and Kd. The program reads the sensor periodically, validates the CRC of each DS18B20 reading, computes the PID output, sets the appropriate PWM duty cycle and relay state, and logs every 5 seconds to a file named greenhouse.log. The program also handles errors and releases resources on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <errno.h>

#define I2C_ADDRESS 0x44
#define RELAY_PIN 17
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define RETRY_COUNT 3
#define RETRY_DELAY 10
#define POLL_INTERVAL 5

int main(int argc, char **argv) {
    int fd;
    int retry_count = 0;
    int relay_state = RELAY_LOW;
    struct timespec last_poll;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    while (1) {
        // Trigger measurement
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("ioctl");
            continue;
        }

        // Wait for 80ms
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        timespec_diff(&last_poll, &now);
        timespec_add(&last_poll, ms_to_ts(80));
        nanosleep(&last_poll, NULL);

        // Read 6-byte result
        unsigned char status;
        unsigned short humidity;
        unsigned char data[6];
        if (read(fd, &status, 1) != 1 || read(fd, data, 5) != 5) {
            retry_count++;
            if (retry_count >= RETRY_COUNT) {
                perror("read");
                continue;
            }
            usleep(RETRY_DELAY * 1000000);
            continue;
        }

        // Verify status byte
        if (status != 0x80) {
            perror("status");
            retry_count++;
            if (retry_count >= RETRY_COUNT) {
                perror("read");
                continue;
            }
            usleep(RETRY_DELAY * 1000000);
            continue;
        }

        // Convert humidity
        humidity = (data[0] << 8) | data[1];

        // Log humidity
        printf("%ld %d\n", time(NULL), humidity);

        // Update relay state
        if (humidity > 60) {
            gpioWrite(RELAY_PIN, RELAY_HIGH);
            relay_state = RELAY_HIGH;
        } else if (humidity < 55) {
            gpioWrite(RELAY_PIN, RELAY_LOW);
            relay_state = RELAY_LOW;
        }

        // Update last poll time
        clock_gettime(CLOCK_REALTIME, &last_poll);

        // Poll every 5 seconds
        timespec_diff(&last_poll, &now);
        timespec_add(&last_poll, ms_to_ts(POLL_INTERVAL * 1000));
        nanosleep(&last_poll, NULL);
    }

    // Clean up
    gpioCleanUp();
    close(fd);
    return 0;
}

// Helper functions
static inline timespec_diff(struct timespec *a, struct timespec *b) {
    return (struct timespec){ b->tv_sec - a->tv_sec, b->tv_nsec - a->tv_nsec };
}

static inline timespec_add(struct timespec *a, struct timespec b) {
    a->tv_sec += b.tv_sec;
    a->tv_nsec += b.tv_nsec;
    if (a->tv_nsec >= 1000000000) {
        a->tv_sec++;
        a->tv_nsec -= 1000000000;
    }
    return *a;
}

static inline unsigned long ms_to_ts(unsigned long ms) {
    return (ms / 1000000) + (ms % 1000000) / 100000;
}

