    a->tv_nsec += b.tv_nsec;
    if (a->tv_nsec >= 1000000000) {
        a->tv_sec++;
        a->tv_nsec -= 1000000000;
    }
    return *a;
}

static inline unsigned long ms_to_ts(unsigned long ms) {
    return (ms / 1000000) + (ms % 1000000) / 100000;
}
