#include <sys/stat.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_ADDRESS 0x76
#define I2C Bus 1
#define BUFFER_SIZE 32

int main(int argc, char *argv[]) {
    int fd;
    i2c_t i2c;
    int retry = 0;
    int retry_count = 0;
    int status;
    unsigned char buf[BUFFER_SIZE];
    struct timespec start_time;
    struct timespec end_time;
    struct timespec interval;
    struct timespec sleep_time;
    struct sigaction sa;

    // Initialize signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    fd = i2c_open(I2C Bus, I2C_ADDRESS, 0);
    if (fd < 0) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    // Initialize I2C
    i2c_init(&i2c, fd, 100000);

    while (1) {
        // Wait for 2 seconds
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Trigger I2C read
        i2c_trigger(&i2c, I2C Bus, I2C_ADDRESS, 0x00, 1, buf, BUFFER_SIZE);

        // Wait for conversion completion
        do {
            clock_gettime(CLOCK_REALTIME, &end_time);
            sleep_time.tv_sec = end_time.tv_sec + 10;
            sleep_time.tv_nsec = end_time.tv_nsec;
            nanosleep(&sleep_time, NULL);
            clock_gettime(CLOCK_REALTIME, &end_time);
        } while (end_time.tv_sec != start_time.tv_sec || end_time.tv_nsec < start_time.tv_nsec);

        // Read pressure data
        status = i2c_read(&i2c, I2C Bus, I2C_ADDRESS, 0x00, 1, buf, BUFFER_SIZE);
        if (status < 0) {
            retry++;
            if (retry > 2) {
                printf("Failed to read from I2C bus\n");
                break;
            }
            retry = 0;
            continue;
        }

        // Apply Bosch compensation formulas
        int pressure = (buf[0] << 8) | buf[1];
        pressure = (pressure & 0xFF00) >> 4;
        pressure = (pressure << 2) | (buf[2] & 0x3);
        pressure = (pressure << 2) | (buf[3] & 0x3);
        pressure = (pressure << 2) | (buf[4] & 0x3);
        pressure = (pressure << 2) | (buf[5] & 0x3);
        pressure = (pressure << 2) | (buf[6] & 0x3);
        pressure = (pressure << 2) | (buf[7] & 0x3);

        // Check if pressure is valid
        if (pressure < 0x8000 || pressure > 0xFFFF) {
            printf("Invalid pressure value: %d\n", pressure);
            continue;
        }

        // Check if pressure exceeds or falls below threshold
        if (pressure > 1020 || pressure < 980) {
            // Record pressure value to file
            FILE *file = fopen("pressure_log.txt", "a");
            if (file == NULL) {
                printf("Failed to open log file\n");
                continue;
            }
            fprintf(file, "%ld %d\n", time(NULL), pressure);
            fclose(file);
        }

        // Close I2C handle
        i2c_close(&i2c);
        i2c = NULL;
    }

    // Close I2C handle
    if (fd >= 0) {
        i2c_close(&i2c);
    }

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C handle
    if (i2c != NULL) {
        i2c_close(&i2c);
        i2c = NULL;
    }
    // Call library's call() function
    call();
    exit(0);
}

