#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <syslog.h>

#define TMP117_ADDRESS 0x40
#define AHT20_ADDRESS 0x00
#define PIR_ADDRESS 17
#define GPIO_PIN 17

int main(int argc, char *argv[]) {
    int i2c_fd_tmp117, i2c_fd_aht20;
    int gpio_fd;
    int retry = 0;
    int retry_count = 0;
    int status;
    char buffer[256];
    struct timespec start_time;
    struct timespec end_time;
    struct stat file_stat;
    struct stat log_file_stat;
    char log_file[256];
    char log_line[256];

    // Initialize GPIO
    gpio_init();
    gpio_set_mode(GPIO_PIN, GPIO_IN);

    // Open I2C devices
    i2c_fd_tmp117 = i2c_open(TMP117_ADDRESS, I2C_MODE_READ);
    if (i2c_fd_tmp117 < 0) {
        perror("i2c_open TMP117");
        return 1;
    }

    i2c_fd_aht20 = i2c_open(AHT20_ADDRESS, I2C_MODE_READ);
    if (i2c_fd_aht20 < 0) {
        perror("i2c_open AHT20");
        i2c_close(i2c_fd_tmp117);
        return 1;
    }

    // Open log file
    time_t now = time(NULL);
    strftime(log_file, sizeof(log_file), "/var/log/pi_logger_%Y-%m-%d.log", localtime(&now));
    if (access(log_file, F_OK) == -1) {
        mkdir(log_file, 0755);
    }
    log_file[strlen(log_file) - 1] = '\0';

    while (1) {
        // Read temperature from TMP117
        retry = 0;
        while (retry < 3) {
            status = i2c_read(i2c_fd_tmp117, buffer, 2, 0x00);
            if (status == 0) {
                break;
            }
            usleep(10);
            retry++;
        }
        if (retry >= 3) {
            syslog(LOG_WARNING, "Failed to read temperature from TMP117");
            continue;
        }
        float temperature = (buffer[0] << 8) | buffer[1];
        syslog(LOG_INFO, "Temperature: %.2f°C", temperature);

        // Read humidity from AHT20
        retry = 0;
        while (retry < 3) {
            status = i2c_read(i2c_fd_aht20, buffer, 2, 0x00);
            if (status == 0) {
                break;
            }
            usleep(10);
            retry++;
        }
        if (retry >= 3) {
            syslog(LOG_WARNING, "Failed to read humidity from AHT20");
            continue;
        }
        float humidity = (buffer[0] << 8) | buffer[1];
        syslog(LOG_INFO, "Humidity: %.2f%%", humidity);

        // Read motion from PIR sensor
        status = gpio_get_level(gpio_fd);
        if (status == 0) {
            syslog(LOG_INFO, "Motion detected");
        } else {
            syslog(LOG_INFO, "No motion detected");
        }

        // Log data
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", localtime(&start_time);
        strcat(log_line, ",");
        sprintf(log_line + strlen(log_line) - 1, "%.2f,", temperature);
        strcat(log_line + strlen(log_line) - 1, "%.2f", humidity);
        strcat(log_line + strlen(log_line) - 1, (status == 0 ? "1" : "0"));
        strcat(log_line + strlen(log_line) - 1, "\n");
        FILE *log_file_ptr = fopen(log_file, "a");
        if (log_file_ptr == NULL) {
            syslog(LOG_WARNING, "Failed to open log file");
            continue;
        }
        fwrite(log_line, strlen(log_line), 1, log_file_ptr);
        fclose(log_file_ptr);

        // Update start time
        clock_gettime(CLOCK_REALTIME, &end_time);
        start_time = end_time;

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C devices
    i2c_close(i2c_fd_tmp117);
    i2c_close(i2c_fd_aht20);

    // Close GPIO
    gpio_close(gpio_fd);

    // Clean up log file
    if (remove(log_file) == -1) {
        syslog(LOG_WARNING, "Failed to remove log file");
    }

    return 0;
}

