#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define LED_RED 17
#define LED_GREEN 22
#define LED_BLUE 27
#define SAMPLE_INTERVAL 500
#define MAX_LOAD 100

int main(int argc, char *argv[]) {
    // Initialize the GPIO driver
    int gpio = 0;
    if (gpio = pigpio_init()) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Set up the LED pins as output
    if (gpiowm_set_mode(LED_RED, PIWMODE PWM) == -1) {
        fprintf(stderr, "Failed to set up LED pin %d as PWM\n", LED_RED);
        pigpio_close(gpio);
        return 1;
    }
    if (gpiowm_set_mode(LED_GREEN, PIWMODE PWM) == -1) {
        fprintf(stderr, "Failed to set up LED pin %d as PWM\n", LED_GREEN);
        pigpio_close(gpio);
        return 1;
    }
    if (gpiowm_set_mode(LED_BLUE, PIWMODE PWM) == -1) {
        fprintf(stderr, "Failed to set up LED pin %d as PWM\n", LED_BLUE);
        pigpio_close(gpio);
        return 1;
    }

    // Set the initial PWM values
    if (gpiowm_set(LED_RED, 0) == -1) {
        fprintf(stderr, "Failed to set PWM value for LED pin %d\n", LED_RED);
        pigpio_close(gpio);
        return 1;
    }
    if (gpiowm_set(LED_GREEN, 0) == -1) {
        fprintf(stderr, "Failed to set PWM value for LED pin %d\n", LED_GREEN);
        pigpio_close(gpio);
        return 1;
    }
    if (gpiowm_set(LED_BLUE, 0) == -1) {
        fprintf(stderr, "Failed to set PWM value for LED pin %d\n", LED_BLUE);
        pigpio_close(gpio);
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler for SIGINT\n");
        pigpio_close(gpio);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler for SIGTERM\n");
        pigpio_close(gpio);
        return 1;
    }

    // Read the initial CPU load
    struct stat statbuf;
    if (fstat(0, &statbuf) == -1) {
        fprintf(stderr, "Failed to read CPU load\n");
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        // Read the CPU load
        struct stat statbuf;
        if (fstat(0, &statbuf) == -1) {
            fprintf(stderr, "Failed to read CPU load\n");
            pigpio_close(gpio);
            return 1;
        }

        // Calculate the load percentage
        float load = (statbuf.st_ruid + statbuf.st_wuid) / (float) sysconf(_SC_NPROCESSORS_ONLN) * 100;

        // Map the load to a color
        int red = (int) (load * 255);
        int green = 255;
        int blue = (int) (255 - load * 255);

        // Clamp the color values
        red = (red < 0) ? 0 : (red > 255) ? 255 : red;
        green = (green < 0) ? 0 : (green > 255) ? 255 : green;
        blue = (blue < 0) ? 0 : (blue > 255) ? 255 : blue;

        // Set the PWM values
        if (gpiowm_set(LED_RED, red) == -1) {
            fprintf(stderr, "Failed to set PWM value for LED pin %d\n", LED_RED);
            pigpio_close(gpio);
            return 1;
        }
        if (gpiowm_set(LED_GREEN, green) == -1) {
            fprintf(stderr, "Failed to set PWM value for LED pin %d\n", LED_GREEN);
            pigpio_close(gpio);
            return 1;
        }
        if (gpiowm_set(LED_BLUE, blue) == -1) {
            fprintf(stderr, "Failed to set PWM value for LED pin %d\n", LED_BLUE);
            pigpio_close(gpio);
            return 1;
        }

        // Sleep for the sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    pigpio_close(gpio);
    return 0;
}

