#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <json-c/json.h>

#define I2C_ADDRESS 0x76
#define I2C_ADDRESS_BMP280 0x77
#define GPIO_SDA I2C1
#define GPIO_SCL I2C1
#define BUFFER_SIZE 1024
#define BUFFER_FORMAT "temperature: {\"value\": %f}, pressure: {\"value\": %f}\n"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(GPIO_SDA, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_SCL, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Create I2C handle
    int i2cHandle = i2cOpen(GPIO_SDA, GPIO_SCL, I2C_MODE_READ, I2C_SPEED_100KHZ100);
    if (i2cHandle < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    int udpSocket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udpSocket < 0) {
        perror("socket");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(5000);
    inet_pton(AF_INET, "192.168.1.100", &serverAddress.sin_addr);

    // Install signal handlers
    struct sigaction sigAction;
    sigAction.sa_handler = sigintHandler;
    sigAction.sa_flags = SA_RESTART;
    sigAction.sa_restorer = NULL;
    if (sigaction(SIGINT, &sigAction, NULL) < 0) {
        perror("sigaction");
        close(udpSocket);
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }
    sigAction.sa_handler = sigtermHandler;
    sigaction(SIGTERM, &sigAction, NULL);

    while (1) {
        // Read temperature and pressure from BMP280
        uint8_t temperatureBuffer[2];
        uint8_t pressureBuffer[3];
        if (i2cRead(i2cHandle, I2C_ADDRESS_BMP280, 6, temperatureBuffer, pressureBuffer) < 0) {
            perror("i2cRead");
            continue;
        }

        // Wait for measurement to complete
        usleep(100000);

        // Convert temperature and pressure to float
        float temperature = (temperatureBuffer[0] << 8) | temperatureBuffer[1];
        float pressure = (pressureBuffer[0] << 8) | (pressureBuffer[1] << 4) | pressureBuffer[2];

        // Format temperature and pressure into JSON string
        char buffer[BUFFER_SIZE];
        sprintf(buffer, BUFFER_FORMAT, temperature / 10.0, pressure / 100.0);

        // Send JSON string via UDP
        if (sendto(udpSocket, buffer, strlen(buffer), 0, (struct sockaddr *)&serverAddress, sizeof(serverAddress)) < 0) {
            perror("sendto");
            continue;
        }

        // Sleep for 5 seconds before taking next measurement
        sleep(5);
    }

    // Clean up
    close(udpSocket);
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

void sigintHandler(int signal) {
    // Clean up
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    close(udpSocket);
    i2cClose(i2cHandle);
    gpioTerminate();
    exit(0);
}

void sigtermHandler(int signal) {
    // Clean up
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    close(udpSocket);
    i2cClose(i2cHandle);
    gpioTerminate();
    exit(0);
}

