#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <time.h>

#define BMP180_I2C_ADDRESS 0x77
#define GPIO_PIN 2
#define GPIO_MODE GPIO_MODE_INPUT
#define GPIO_INT_EDGE GPIO_EDGE_FALLING
#define GPIO_INT_EDGE_PULLUP GPIO_PULLUP_ENABLE
#define I2C_SPEED 100000
#define I2C_TIMEOUT 100
#define LOG_FILE "altitude_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Configure GPIO2 as a falling-edge interrupt
    if (gpioMode(GPIO_PIN, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        return 1;
    }
    if (gpioSetPullUpDnLevel(GPIO_PIN, GPIO_PULLUP_ENABLE) < 0) {
        perror("gpioSetPullUpDnLevel");
        return 1;
    }
    if (gpioEdgeDetect(GPIO_PIN, GPIO_EDGE_FALLING) < 0) {
        perror("gpioEdgeDetect");
        return 1;
    }

    // Open I2C handle
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C speed and timeout
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SET_SPEED, I2C_SPEED) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SET_TIMEOUT, I2C_TIMEOUT) < 0) {
        perror("ioctl");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Main loop
    while (1) {
        // Check for interrupt
        if (gpioRead(GPIO_PIN) < 0) {
            perror("gpioRead");
            return 1;
        }

        // Read calibration data
        unsigned char calib[8];
        if (read(i2c_fd, calib, 8) < 8) {
            perror("read");
            continue;
        }

        // Check calibration data
        if (calib[0] != 0x55) {
            printf("Invalid calibration data\n");
            continue;
        }

        // Read temperature and pressure
        unsigned char temp[2], pres[2];
        if (read(i2c_fd, temp, 2) < 2) {
            perror("read");
            continue;
        }
        if (read(i2c_fd, pres, 2) < 2) {
            perror("read");
            continue;
        }

        // Convert temperature and pressure
        float temp_c = (temp[0] << 8) | temp[1];
        float pres_pascals = (pres[0] << 8) | pres[1];

        // Append to log file
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%f,%f\n", timestamp, temp_c, pres_pascals);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C handle
    close(i2c_fd);

    // Close log file
    close(log_fd);

    // Release GPIO
    gpioRelease(GPIO_PIN);

    // Clean up
    gpioTerminate();
    return 0;
}

