#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define MAX_LOG_LINES 1000
#define LOG_FILE "rtd_log.csv"

// Define the MAX31865 RTD configuration
#define RTD_ADDRESS 0x44
#define RTD_E 0x00
#define RTD_T 0x01
#define RTD_O 0x02
#define RTD_CE 0x03
#define RTD_DE 0x04
#define RTD_BIAS 0x05
#define RTD_FAULT 0x06

// Define the SPI configuration
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 8

// Define the Callendar-Van Dusen equation constants
#define CVD_A 0.003392143
#define CVD_B 0.000298501
#define CVD_C 0.000000903

// Function to read the temperature from the MAX31865 RTD
float read_rtd(pigpio_t *gpio, int cs, int speed) {
    int status;
    unsigned char data[2];
    float temperature;

    // Set the chip enable pin high
    gpio_write(cs, 1);

    // Send the read command
    gpio_write(RTD_CE, 0);
    usleep(speed);
    gpio_write(RTD_CE, 1);

    // Read the data
    status = gpio_read(RTD_DE, data, 2);
    if (status != 0) {
        printf("SPI read error\n");
        return -1.0;
    }

    // Check the fault status
    if (data[0] & (1 << 7)) {
        printf("Fault detected\n");
        return -1.0;
    }

    // Compute the temperature using the Callendar-Van Dusen equation
    temperature = (data[0] * CVD_A + data[1] * CVD_B + data[2] * CVD_C);

    // Set the chip enable pin low
    gpio_write(RTD_CE, 0);

    return temperature;
}

// Function to log the temperature to a file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *time_info;
    char timestamp[20];

    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }

    fprintf(log_file, "%s,%f\n", timestamp, temperature);
    fclose(log_file);
}

// Function to handle the SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Shutting down...\n");
    gpio_close(SPI_CS);
    fclose(LOG_FILE);
    exit(0);
}

int main() {
    pigpio_t *gpio;
    int cs, status;
    float temperature;

    // Initialize the GPIO library
    gpio_init();
    gpio_set_mode(SPI_CS, PI_INPUT);

    // Open the SPI device file descriptor
    cs = gpio_get_fd(SPI_CS);
    if (cs < 0) {
        printf("Error opening SPI device file descriptor\n");
        return 1;
    }

    // Open the log file
    status = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (status < 0) {
        printf("Error opening log file\n");
        return 1;
    }

    // Set the chip enable pin as an output
    gpio_set_mode(RTD_CE, PI_OUTPUT);

    while (1) {
        // Read the temperature
        temperature = read_rtd(gpio, cs, SPI_SPEED);

        // Log the temperature
        if (temperature >= 0) {
            log_temperature(temperature);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Handle the SIGINT and SIGTERM signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Close the SPI device file descriptor
    close(cs);

    // Close the log file
    fclose(LOG_FILE);

    // Clean up
    gpio_close(SPI_CS);
    gpioTerminate();
    return 0;
}

