#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/timer.h>
#include <sys/select.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define BUFFER_SIZE 60
#define BUFFER_TIMEOUT 60
#define I2C_ADDRESS 0x77
#define GPIO_PIN 24
#define GPIO_BASE 17

int main() {
    int fd;
    int i;
    int buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_size = 0;
    int timer_fd;
    struct itimerspec timer;
    struct sigaction sa;
    struct sigaction old_sa;
    int gpio;
    int ret;
    int i2c_ret;
    int pressure;
    int pressure_avg;
    int pressure_diff;

    // Initialize GPIO
    gpio = gpioGetConsecutive(0);
    if (gpio < 0) {
        perror("gpioGetConsecutive");
        return 1;
    }
    gpio = gpioSetMode(gpio, GPIO_MODE_OUTPUT);
    if (gpio < 0) {
        perror("gpioSetMode");
        return 1;
    }
    gpio = gpioWrite(gpio, 0);
    if (gpio < 0) {
        perror("gpioWrite");
        return 1;
    }

    // Initialize I2C
    fd = i2cOpen(1, I2C_ADDRESS, I2C_MODE_READ);
    if (fd < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Set up timer
    timer_fd = timerCreate(0, &timer);
    if (timer_fd < 0) {
        perror("timerCreate");
        return 1;
    }
    timer.tv_sec = 0;
    timer.tv_nsec = 50000;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = 0;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 50000;
    if (timerSet(timer_fd, &timer) < 0) {
        perror("timerSet");
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Read from I2C
        i2c_ret = i2cRead(fd, 0x00, 2, 0, NULL);
        if (i2c_ret < 0) {
            perror("i2cRead");
            continue;
        }
        pressure = (i2cRead(fd, 0x00, 2, 0, NULL)[0] << 8) | i2cRead(fd, 0x00, 2, 0, NULL)[1];
        if (pressure < 0) {
            perror("i2cRead");
            continue;
        }

        // Update buffer
        if (buffer_index >= BUFFER_SIZE) {
            buffer_size = (buffer_index - 1) % BUFFER_SIZE;
            buffer[buffer_size] = pressure;
            buffer_index = BUFFER_SIZE;
        } else {
            buffer[buffer_index] = pressure;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }

        // Compute average
        if (buffer_size > 0) {
            pressure_avg = 0;
            for (i = 0; i < buffer_size; i++) {
                pressure_avg += buffer[i];
            }
            pressure_avg /= buffer_size;
        }

        // Check for alert
        if (buffer_size > 0) {
            pressure_diff = pressure - pressure_avg;
            if (abs(pressure_diff) > 5) {
                gpio = gpioGetConsecutive(0);
                if (gpio < 0) {
                    perror("gpioGetConsecutive");
                    continue;
                }
                gpio = gpioWrite(gpio, 1);
                if (gpio < 0) {
                    perror("gpioWrite");
                    continue;
                }
                printf("Pressure alert: %d hPa\n", pressure);
                fflush(stdout);
            }
        }

        // Sleep
        struct timeval tv;
        gettimeofday(&tv, NULL);
        timer.tv_sec = tv.tv_sec;
        timer.tv_usec = tv.tv_usec;
        if (timerSet(timer_fd, &timer) < 0) {
            perror("timerSet");
            continue;
        }
    }

    // Clean up
    if (timer_fd >= 0) {
        timerDelete(timer_fd);
    }
    if (gpio >= 0) {
        gpioWrite(gpio, 0);
    }
    if (fd >= 0) {
        i2cClose(fd);
    }
    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    if (timer_fd >= 0) {
        timerDelete(timer_fd);
    }
    if (gpio >= 0) {
        gpioWrite(gpio, 0);
    }
    if (fd >= 0) {
        i2cClose(fd);
    }
    exit(0);
}

