#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define PWM_MIN 0
#define PWM_MAX 255
#define TEMPERATURE_MIN 40
#define TEMPERATURE_MAX 70

int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver");
        return 1;
    }

    // Set up the PWM pin
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set PWM mode");
        gpioTerminate();
        return 1;
    }

    // Set the PWM frequency
    if (gpioPWMSetFrequency(GPIO_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        return 1;
    }

    // Set the PWM duty cycle
    if (gpioPWMSetDuty(GPIO_PIN, PWM_MIN) < 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("fan_log.txt", "w");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read the temperature
        char temp_str[20];
        ssize_t bytes_read = readlink("/sys/class/thermal/thermal_zone0/temp", temp_str, sizeof(temp_str));
        if (bytes_read < 0) {
            syslog(LOG_ERR, "Failed to read temperature");
            continue;
        }
        temp_str[bytes_read] = '\0';
        int temperature = atoi(temp_str);
        if (temperature < TEMPERATURE_MIN || temperature > TEMPERATURE_MAX) {
            syslog(LOG_ERR, "Invalid temperature value");
            continue;
        }

        // Calculate the duty cycle
        int duty_cycle = (temperature - TEMPERATURE_MIN) * (PWM_MAX - PWM_MIN) / (TEMPERATURE_MAX - TEMPERATURE_MIN) + PWM_MIN;

        // Clamp the duty cycle
        duty_cycle = (duty_cycle < PWM_MIN) ? PWM_MIN : (duty_cycle > PWM_MAX) ? PWM_MAX : duty_cycle;

        // Set the PWM duty cycle
        if (gpioPWMSetDuty(GPIO_PIN, duty_cycle) < 0) {
            syslog(LOG_ERR, "Failed to set PWM duty cycle");
            continue;
        }

        // Log the temperature and duty cycle
        fprintf(log_file, "%d %d %d\n", time(NULL), temperature, duty_cycle);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT");
    gpioPWMSetDuty(GPIO_PIN, PWM_MIN);
    exit(0);
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Received SIGTERM");
    gpioPWMSetDuty(GPIO_PIN, PWM_MIN);
    exit(0);
}

