// Function to initialize the I2C bus
int init_i2c() {
    int fd = pigpio_open(I2C Bus, I2C_ADDRESS, PI_MMAP);
    if (fd < 0) {
        perror("pigpio_open");
        return -1;
    }
    pigpio_close(fd);
    return 0;
}

// Function to read from the LM75 sensor
int read_lm75(int fd) {
    unsigned char data[2];
    if (pigpio_i2c_read(fd, data, 2) < 0) {
        perror("pigpio_i2c_read");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Function to update the running average
void update_average(int* average, int value) {
    *average = (*average * 59 + value) / 60;
}

// Function to check if the temperature exceeds the threshold
int check_threshold(int temperature) {
    return temperature > 28.0;
}

// Function to drive the alert LED
void drive_led(int gpio, int state) {
    pigpio_write(gpio, state);
}

// Function to handle the background thread
void* background_thread(void* arg) {
    int buffer[BUFFER_SIZE];
    int average = 0;
    int mutex = pigpio_mutex_new();
    if (mutex == NULL) {
        perror("pigpio_mutex_new");
        return NULL;
    }

    while (1) {
        int temperature = read_lm75(init_i2c());
        if (temperature < 0) {
            continue;
        }

        pthread_mutex_lock(mutex);
        buffer[0] = temperature;
        update_average(&average, temperature);
        pthread_mutex_unlock(mutex);

        if (check_threshold(average)) {
            drive_led(LED_GPIO, 1);
        } else {
            drive_led(LED_GPIO, 0);
        }

        usleep(1000000);
    }
}

