    int fd = init_i2c();
    if (fd < 0) {
        return 1;
    }

    int gpio = pigpio_open(LED_GPIO, PI_INPUT, PI_FLOATING);
    if (gpio < 0) {
        perror("pigpio_open");
        return 1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, background_thread, NULL);

    int i;
    for (i = 0; i < BUFFER_SIZE; i++) {
        usleep(1000000);
    }

    pthread_mutex_lock(mutex);
    pthread_mutex_unlock(mutex);

    pigpio_close(gpio);
    pigpio_close(fd);
    pigpio_mutex_destroy(mutex);

    pthread_join(thread, NULL);

    return 0;
}

