#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define MAX_LOG_LINES 1000
#define MAX_LOG_FILE "heater_log.csv"

// Define constants
#define SPI_SPEED 2000000
#define SPI_MODE SPI_MODE0
#define SPI_CS GPIO_8
#define SPI_MISO GPIO_9
#define SPI_MOSI GPIO_10
#define SPI_SCLK GPIO_11
#define RELAY_PIN GPIO_17
#define RELAY_MAX_DUTY 80
#define RELAY_MIN_DUTY 0
#define RELAY_DEFAULT_DUTY 50

// Define structures
typedef struct {
    int fd;
    char filename[MAX_LOG_FILE + 1];
} log_file_t;

// Define functions
void init_spi(pigpio_t *gpio, int cs, int speed, int mode);
void read_temp(pigpio_t *gpio, log_file_t *log);
void set_duty(pigpio_t *gpio, int duty);
void log_entry(log_file_t *log, int duty, int error);
void cleanup(pigpio_t *gpio, log_file_t *log);

int main(int argc, char **argv) {
    pigpio_t *gpio;
    log_file_t log;
    int cs = GPIO_8;
    int speed = SPI_SPEED;
    int mode = SPI_MODE;
    int relay_pin = GPIO_17;
    int relay_duty = RELAY_DEFAULT_DUTY;
    int error = 0;
    int log_fd = -1;
    int log_line = 0;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Error initializing GPIO\n");
        return 1;
    }

    // Initialize SPI
    init_spi(gpio, cs, speed, mode);

    // Open log file
    log.fd = open(MAX_LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log.fd == -1) {
        printf("Error opening log file\n");
        return 1;
    }

    // Set up relay pin
    gpio_set_mode(relay_pin, GPIO_MODE_OUTPUT);
    gpio_pull_up_down(relay_pin, GPIO_PUD_DOWN);

    // Set up SPI
    gpio_set_mode(SPI_MISO, GPIO_MODE_INPUT);
    gpio_set_mode(SPI_SCLK, GPIO_MODE_OUTPUT);
    gpio_set_mode(SPI_MOSI, GPIO_MODE_OUTPUT);
    gpio_set_mode(SPI_CS, GPIO_MODE_OUTPUT);
    gpio_set_level(SPI_CS, 0);

    // Set up relay
    gpio_set_level(relay_pin, 0);

    // Main loop
    while (1) {
        // Read temperature
        read_temp(gpio, &log);

        // Calculate duty cycle
        int duty = (int)((float)log.duty * 100 / RELAY_MAX_DUTY);

        // Set duty cycle
        set_duty(gpio, duty);

        // Log entry
        log_entry(&log, duty, error);

        // Check for errors
        if (error) {
            log_entry(&log, 0, error);
            error = 0;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup(gpio, &log);

    return 0;
}

void init_spi(pigpio_t *gpio, int cs, int speed, int mode) {
    gpio_set_mode(SPI_MISO, GPIO_MODE_INPUT);
    gpio_set_mode(SPI_SCLK, GPIO_MODE_OUTPUT);
    gpio_set_mode(SPI_MOSI, GPIO_MODE_OUTPUT);
    gpio_set_mode(SPI_CS, GPIO_MODE_OUTPUT);
    gpio_set_speed(SPI_MISO, speed);
    gpio_set_speed(SPI_SCLK, speed);
    gpio_set_speed(SPI_MOSI, speed);
    gpio_set_mode(SPI_CS, mode);
    gpio_write(SPI_CS, 0);
}

