#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <json-c/json.h>

#define DHT22_PIN 4
#define DHT22_CHECKSUM 0x07
#define DHT22_CHECKSUM_LENGTH 8
#define DHT22_DATA_LENGTH 5
#define DHT22_START_PIN 0x40
#define DHT22_START_PIN_MS 1000
#define DHT22_RETRY_COUNT 3
#define DHT22_RETRY_DELAY 1000

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO pin as input with pull-up resistor
    if (gpioMode(DHT22_PIN, GPIO_IN_PUD_UP) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Set up socket for HTTP request
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    inet_pton(AF_INET, "http://yourserver.com/api/humidity", &server_addr.sin_addr);
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sock);
        gpioTerminate();
        return 1;
    }

    // Send start signal to DHT22 sensor
    gpioWrite(DHT22_PIN, DHT22_START_PIN);
    usleep(DHT22_START_PIN_MS * 1000);
    gpioWrite(DHT22_PIN, 0);

    // Read DHT22 data
    uint8_t data[DHT22_DATA_LENGTH];
    int bytes_read = 0;
    while (bytes_read < DHT22_DATA_LENGTH) {
        int bytes_available = gpioRead(DHT22_PIN);
        if (bytes_available < 1) {
            break;
        }
        memcpy(data + bytes_read, (void *) &bytes_available, 1);
        bytes_read++;
    }

    // Check checksum
    uint8_t checksum = 0;
    for (int i = 0; i < DHT22_DATA_LENGTH; i++) {
        checksum ^= data[i];
    }
    if (checksum != DHT22_CHECKSUM) {
        printf("Checksum mismatch\n");
        gpioTerminate();
        return 1;
    }

    // Send data to server
    char payload[1024];
    sprintf(payload, "{\"temperature\": %d, \"humidity\": %d}", data[0], data[1]);
    send(sock, payload, strlen(payload), 0);
    if (send(sock, data + 2, DHT22_DATA_LENGTH - 2, 0) < 0) {
        perror("send");
        close(sock);
        gpioTerminate();
        return 1;
    }

    // Handle errors
    for (int retry = 0; retry < DHT22_RETRY_COUNT; retry++) {
        if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("connect");
            close(sock);
            sock = 0;
            if (retry < DHT22_RETRY_COUNT - 1) {
                sleep(DHT22_RETRY_DELAY);
            } else {
                printf("Failed to connect to server\n");
                gpioTerminate();
                return 1;
            }
        }
    }

    // Close socket and terminate pigpio
    if (sock > 0) {
        close(sock);
    }
    gpioTerminate();

    return 0;
}

