#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <json-c/json.h>

#define PI_GPIO 4
#define PI_PIN 7
#define PI_MODE 0
#define PI_DIR 0
#define PI_INPUT 1
#define PI_PULL_UP 1
#define PI_HIGH 1
#define PI_LOW 0
#define PI_DELAY 1000
#define PI_CHECKSUM 0x3E
#define PI_BACKOFF 2
#define PI_MAX_RETRIES 3
#define PI_MAX_DELAY 2
#define PI_URL "http://your-library’s-API-call.com/api/humidity"

int main(int argc, char *argv[]) {
    int pin;
    int retries = 0;
    int backoff = 0;
    int retry_count = 0;
    int status;
    char *url = PI_URL;
    json_object *data;
    json_object *humidity;
    json_object *error;
    char *response;
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers;
    struct curl_slist *header_list;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Set up GPIO pin
    if (gpioSetMode(PI_GPIO, PI_MODE) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetDirection(PI_GPIO, PI_DIR) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO direction");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUp(PI_GPIO, PI_PULL_UP) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO pull-up");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullDown(PI_GPIO, PI_LOW) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO pull-down");
        gpioTerminate();
        return 1;
    }

    // Set up curl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        headers = NULL;
        header_list = NULL;
        curl_slist_append(header_list, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, header_list);
    } else {
        syslog(LOG_ERR, "Failed to initialize curl");
        return 1;
    }

    // Main loop
    while (1) {
        // Read from DHT22 sensor
        status = dht22Read(PI_GPIO, PI_PIN, &humidity);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to read from DHT22 sensor");
            continue;
        }

        // Validate checksum
        if (humidity->humidity < 0 || humidity->humidity > 100) {
            syslog(LOG_ERR, "Invalid humidity value");
            continue;
        }

        // Format data as JSON
        data = json_object_new_object();
        json_object_object_add(data, "humidity", json_object_new_int(humidity->humidity));

        // Post data to API
        retry_count = 0;
        while (retry_count < PI_MAX_RETRIES) {
            retry_count++;
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_object_to_json_string(data));
            res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                return 0;
            } else if (res == CURLE_OPERATION_TIMEDOUT) {
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                if (retry_count < PI_MAX_RETRIES) {
                    usleep(PI_DELAY * 1000);
                    backoff = 0;
                } else {
                    syslog(LOG_ERR, "Failed to post data to API");
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 1;
                }
            } else if (res == CURLE_COULDNT_CONNECT) {
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                if (retry_count < PI_MAX_RETRIES) {
                    usleep(PI_DELAY * 1000);
                    backoff = 0;
                } else {
                    syslog(LOG_ERR, "Failed to connect to API");
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 1;
                }
            } else if (res == CURLE_HTTP_RETURNED_ERROR) {
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                if (retry_count < PI_MAX_RETRIES) {
                    usleep(PI_DELAY * 1000);
                    backoff = 0;
                } else {
                    syslog(LOG_ERR, "Failed to post data to API");
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 1;
                }
            } else {
                syslog(LOG_ERR, "API error %d", res);
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                return 1;
            }
        }

        // Sleep for 10 seconds
        sleep(10);
    }

    // Cleanup
    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

void write_memory(void *ptr, size_t size, size_t nmemb, void *data) {
    char *str = (char *)data;
    for (size_t i = 0; i < size; i++) {
        str[i] = ptr[i];
    }
}

void sigint_handler(int sig) {
    curl_global_cleanup();
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    curl_global_cleanup();
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set SIGINT handler");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler");
        return 1;
    }

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0) {
            if (i + 1 >= argc) {
                syslog(LOG_ERR, "Missing URL");
                return 1;
            }
            url = argv[i + 1];
            i++;
        }
    }

    // Run main loop
    return main();
}

