            continue;
        }

        // Check if the temperature has changed
        if (temperature != last_temperature) {
            last_temperature = temperature;

            // Apply the tiered speed map
            for (int i = 0; i < 4; i++) {
                if (temperature < temp_thresholds[i]) {
                    fan_state = fan_speed_map[i];
                    break;
                }
            }

            // Check if the fan state has changed
            if (fan_state != last_fan_state) {
                last_fan_state = fan_state;

                // Set the fan state
                if (set_fan_state(fan_state) == -1) {
                    syslog(LOG_ERR, "Failed to set fan state");
                }

                // Log the fan state change
                log_message("Fan state: %d", fan_state);
            }
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpioTerminate();
    close(log_fd);
    return 0;
}

