// Function to map temperature to PWM duty cycle
int map_temperature(int temperature) {
    if (temperature <= TEMPERATURE_THRESHOLD) {
        return PWM_MIN;
    } else if (temperature >= TEMPERATURE_THRESHOLD2) {
        return PWM_MAX;
    } else {
        return (int)((temperature - TEMPERATURE_THRESHOLD) * (PWM_MAX - PWM_MIN) / (TEMPERATURE_THRESHOLD2 - TEMPERATURE_THRESHOLD) + PWM_MIN);
    }
}

// Function to log temperature and PWM duty cycle to file
void log_temperature(int temperature, int duty_cycle) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        return;
    }
    fprintf(log_file, "%s,%d,%d\n", timestamp, temperature, duty_cycle);
    fclose(log_file);
}

