    int pwm_pin = gpioGetPin(GPIO_PIN);
    if (pwm_pin < 0) {
        syslog(LOG_ERR, "Failed to get PWM pin number");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetMode(pwm_pin, GPIO_MODE PWM) < 0) {
        syslog(LOG_ERR, "Failed to set PWM mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWM(pwm_pin, PWM_FREQ, PWM_MIN) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        return 1;
    }

    // Set PWM duty cycle
    if (gpioSetPWM(pwm_pin, PWM_FREQ, map_temperature(getcpu_temp())) < 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler");
        gpioTerminate();
        return 1;
    }

    // Main loop
