        // Poll CPU temperature
        int temperature = getcpu_temp();
        if (temperature < 0) {
            syslog(LOG_ERR, "Failed to get CPU temperature");
            break;
        }

        // Log temperature and PWM duty cycle
        log_temperature(temperature, map_temperature(temperature));

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpioStop(pwm_pin);
    gpioCleanUp();
    return 0;
}

