#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_A 17
#define GPIO_B 18
#define FILE_NAME "encoder_log.txt"

// Structure to hold the encoder state
typedef struct {
    int state;
    int last_state;
    time_t last_update;
} EncoderState;

// Function to initialize the GPIO pins
void init_gpio(pigpio *gpio) {
    if (gpio->initialise(GPIO_A, PI_OUTPUT) != 0) {
        printf("Error initializing GPIO A\n");
        exit(1);
    }
    if (gpio->initialise(GPIO_B, PI_OUTPUT) != 0) {
        printf("Error initializing GPIO B\n");
        exit(1);
    }
    if (gpio->setmode(GPIO_A, PI_INPUT) != 0) {
        printf("Error setting GPIO A to input mode\n");
        exit(1);
    }
    if (gpio->setmode(GPIO_B, PI_INPUT) != 0) {
        printf("Error setting GPIO B to input mode\n");
        exit(1);
    }
    if (gpio->pull_up_downtime(GPIO_A, PI_HIGH) != 0) {
        printf("Error setting GPIO A pull-up resistor\n");
        exit(1);
    }
    if (gpio->pull_up_downtime(GPIO_B, PI_HIGH) != 0) {
        printf("Error setting GPIO B pull-up resistor\n");
        exit(1);
    }
}

// Function to read the encoder state
void read_encoder(pigpio *gpio, EncoderState *state) {
    int a = gpio->read(GPIO_A);
    int b = gpio->read(GPIO_B);
    if (a == 0 && b == 0) {
        state->state = 0;
    } else if (a == 1 && b == 0) {
        state->state = 1;
    } else if (a == 0 && b == 1) {
        state->state = 2;
    } else if (a == 1 && b == 1) {
        state->state = 3;
    }
    if (state->state != state->last_state) {
        state->last_update = time(NULL);
        printf("Encoder state: %d\n", state->state);
        FILE *file = fopen(FILE_NAME, "a");
        if (file == NULL) {
            printf("Error opening file for writing\n");
            exit(1);
        }
        fprintf(file, "%d %d\n", state->last_update, state->state);
        fclose(file);
    }
    state->last_state = state->state;
}

// Function to handle the SIGINT and SIGTERM signals
void sig_handler(int sig) {
    pigpio *gpio = pigpio_get();
    EncoderState state;
    state.last_state = 0;
    state.last_update = 0;
    if (gpio != NULL) {
        gpio->close(gpio);
        gpio = NULL;
    }
    exit(0);
}

int main() {
    pigpio *gpio = pigpio_get();
    if (gpio == NULL) {
        printf("Error getting pigpio instance\n");
        exit(1);
    }
    init_gpio(gpio);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);
    while (1) {
        EncoderState state;
        read_encoder(gpio, &state);
        sleep(0.1);
    }
    return 0;
}

