    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus parameters
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("adpd144ri_log.txt", "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pin for LED
    if (gpioMode(GPIO_LED, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pin as active-high
    if (gpioWrite(GPIO_LED, 1) < 0) {
        perror("gpioWrite");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        uint8_t red, ir;
        if (i2cRead(i2c_fd, &red, 1, I2C_TIMEOUT) < 0) {
            perror("i2cRead");
            continue;
        }

        if (i2cRead(i2c_fd, &ir, 1, I2C_TIMEOUT) < 0) {
            perror("i2cRead");
            continue;
        }

        // Log data
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        fprintf(log_file, "%d,%d,%d\n", now, red, ir);

        // Check IR value
        if (ir > IR_THRESHOLD) {
            gpioWrite(GPIO_LED, 0);
            printf("IR value exceeded threshold\n");
        } else {
            gpioWrite(GPIO_LED, 1);
        }
    }

    // Clean up
    gpioWrite(GPIO_LED, 1); // Ensure LED is high before closing
    gpioTerminate();
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

