#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18
#define GPIO_MODE_INPUT
#define GPIO_PULLUP
#define RPM_LOG_FILE "rpm_log.txt"

// Structure to hold the RPM data
typedef struct {
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    FILE *log_file;
} rpm_data_t;

// Global variables
rpm_data_t rpm_data;
int gpio_fd;
int gpio_value;

// Interrupt Service Routine (ISR)
void isr(void *arg) {
    pthread_mutex_lock(&rpm_data.mutex);
    rpm_data.count++;
    pthread_cond_signal(&rpm_data.cond);
    pthread_mutex_unlock(&rpm_data.mutex);
}

// Main function
int main(int argc, char *argv[]) {
    // Initialize GPIO
    if (gpio_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Set GPIO pin mode and pull-up
    if (gpio_mode(GPIO_PIN, GPIO_MODE_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO pin mode");
        gpio_close(gpio_fd);
        return 1;
    }
    if (gpio_pullup_dig(GPIO_PIN, GPIO_PULLUP) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO pull-up");
        gpio_close(gpio_fd);
        return 1;
    }

    // Create a mutex and condition variable for synchronization
    rpm_data.mutex = PTHREAD_MUTEX_INITIALIZER;
    rpm_data.cond = PTHREAD_COND_INITIALIZER;
    rpm_data.log_file = fopen(RPM_LOG_FILE, "a");
    if (rpm_data.log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpio_close(gpio_fd);
        return 1;
    }

    // Register the interrupt service routine
    gpio_isr_handler_setup(GPIO_PIN, isr, NULL);
    gpio_isr_handler_enable(GPIO_PIN);

    // Initialize the RPM counter
    rpm_data.count = 0;

    // Main loop
    struct timespec start_time;
    struct timespec end_time;
    clock_gettime(CLOCK_REALTIME, &start_time);
    while (1) {
        // Wait for a pulse
        pthread_mutex_lock(&rpm_data.mutex);
        pthread_cond_wait(&rpm_data.cond, &rpm_data.mutex);
        pthread_mutex_unlock(&rpm_data.mutex);

        // Calculate RPM
        if (rpm_data.count > 0) {
            clock_gettime(CLOCK_REALTIME, &end_time);
            double elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
            rpm_data.count = 0;
            start_time = end_time;
            double rpm = 60 / elapsed_time;
            fprintf(rpm_data.log_file, "%.2f RPM\n", rpm);
        } else {
            // Log 0.00 RPM if no pulses are detected
            fprintf(rpm_data.log_file, "0.00 RPM\n");
        }
    }

    // Clean up
    gpio_close(gpio_fd);
    fclose(rpm_data.log_file);
    pthread_mutex_destroy(&rpm_data.mutex);
    pthread_cond_destroy(&rpm_data.cond);

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    // Terminate the driver library
    gpioTerminate();
    // Close the log file
    fclose(rpm_data.log_file);
    // Destroy the mutex and condition variable
    pthread_mutex_destroy(&rpm_data.mutex);
    pthread_cond_destroy(&rpm_data.cond);
    // Exit the program
    exit(0);
}

// Register the signal handler
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register signal handler");
        exit(1);
    }
}

int main(int argc, char *argv[]) {
    // Register the signal handler
    sigaction_handler(SIGINT);
    sigaction_handler(SIGTERM);
    return main(argc, argv);
}

