#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <libgen.h>

#define I2C_ADDRESS 0x44
#define I2C Bus 1
#define GPIO_PIN 17
#define LOG_FILE "adpd144ri_log.txt"
#define LOG_INTERVAL 100
#define THRESHOLD 2000

int main(int argc, char *argv[]) {
    // Initialize GPIO
    int gpio = 17;
    if (gpio = gpioInitialise()) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        printf("Failed to set I2C address\n");
        close(log_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    if (gpioMode(gpio, GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set GPIO pin as output\n");
        close(log_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as high
    if (gpioWrite(gpio, 1) < 0) {
        printf("Failed to set GPIO pin high\n");
        close(log_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read I2C data
        unsigned char data[2];
        if (read(i2c_fd, data, 2) < 2) {
            printf("Failed to read I2C data\n");
            close(log_fd);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Check if sensor is present
        if (data[0] == 0x00) {
            printf("Sensor not present\n");
            close(log_fd);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Check if infrared reading exceeds threshold
        if (data[1] > THRESHOLD) {
            printf("Infrared reading exceeds threshold\n");
            gpioWrite(gpio, 0);
        } else {
            gpioWrite(gpio, 1);
        }

        // Log data
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        fprintf(log_fd, "%s,%d\n", timestamp, data[1]);

        // Sleep for LOG_INTERVAL ms
        usleep(LOG_INTERVAL * 1000);
    }

    // Clean up
    close(log_fd);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

