#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x10
#define I2C_ADDRESS2 0x11
#define CRC_POLYNOMINAL 0x1D
#define CRC_INIT_VALUE 0x00
#define I2C_TIMEOUT 10
#define I2C_READ_SIZE 3
#define LOG_FILE "flow_log.csv"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus 1
    int i2c_fd = pigpioOpen(1, PI_I2C, 100000);
    if (i2c_fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Open log file
    struct stat sb;
    if (stat(LOG_FILE, &sb) != 0) {
        if (mkdir(LOG_FILE, 0755) != 0) {
            perror("mkdir");
            pigpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }
    if (fopen(LOG_FILE, "a") == NULL) {
        perror("fopen");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize CRC
    uint8_t crc = 0;
    for (int i = 0; i < 8; i++) {
        crc = (crc << 1) ^ (crc & 1 ? CRC_POLYNOMINAL : 0);
    }

    while (1) {
        // Read from I2C
        uint8_t data[3];
        if (pigpioI2cWrite(i2c_fd, I2C_ADDRESS, &CRC_INIT_VALUE, 1) < 0) {
            fprintf(stderr, "I2C write failed\n");
            continue;
        }
        if (pigpioI2cRead(i2c_fd, I2C_ADDRESS, data, I2C_READ_SIZE, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }
        if (data[0] != 0x00 || data[1] != 0x00 || data[2] != crc) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        // Calculate flow rate
        uint32_t flow_rate = (data[0] << 16) | (data[1] << 8) | data[2];
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stdout, "%s,%u\n", timestamp, flow_rate);

        // Write to log file
        if (fwrite(&flow_rate, sizeof(flow_rate), 1, stdout) != 1) {
            perror("fwrite");
        }
        if (fflush(stdout) != 0) {
            perror("fflush");
        }
        if (ferror(stdout)) {
            perror("ferror");
        }

        // Sleep for 1000ms
        sleep(1);
    }

    // Close I2C and log file
    pigpioClose(i2c_fd);
    fclose(stdout);
    pigpioTerminate();
    return 0;
}

