#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x40
#define I2C Bus 1

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
    uint16_t iaq;
} sensor_data_t;

// Function to read sensor data
sensor_data_t read_sensor_data(pigpio_t gpio, int timeout) {
    sensor_data_t data;
    int ret = pigpio_i2c_read(gpio, I2C_ADDRESS, &data.tvoc, sizeof(data.tvoc), timeout);
    if (ret != 0) {
        printf("I2C read error: %d\n", ret);
        return (sensor_data_t){0, 0, 0};
    }
    ret = pigpio_i2c_read(gpio, I2C_ADDRESS, &data.eco2, sizeof(data.eco2), timeout);
    if (ret != 0) {
        printf("I2C read error: %d\n", ret);
        return (sensor_data_t){0, 0, 0};
    }
    return data;
}

// Function to compute IAQ index
int compute_iaq(sensor_data_t data) {
    return (int)((data.tvoc + data.eco2) / 100);
}

// Function to log data to CSV file
void log_data(sensor_data_t data) {
    FILE *log_file = fopen("air_quality_log.csv", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(log_file, "%d,%d,%d\n", data.tvoc, data.eco2, data.iaq);
    fclose(log_file);
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    pigpio_close(gpio);
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    pigpio_t gpio;
    if (pigpio_init(&gpio) != 0) {
        printf("Error initializing pigpio\n");
        return 1;
    }

    // Open I2C interface
    if (pigpio_i2c_open(&gpio, I2C Bus, I2C_ADDRESS) != 0) {
        printf("I2C open error\n");
        pigpio_close(&gpio);
        return 1;
    }

    // Create log file if it doesn't exist
    struct stat sb;
    if (stat("air_quality_log.csv", &sb) != 0 || !S_ISREG(sb.st_mode)) {
        if (mkdir("air_quality_log", 0777) != 0) {
            printf("Error creating log directory\n");
            pigpio_close(&gpio);
            return 1;
        }
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        sensor_data_t data = read_sensor_data(&gpio, 100);
        int iaq = compute_iaq(data);
        log_data(data);
        sleep(5);
    }

    // Clean up
    pigpio_close(&gpio);
    return 0;
}

