#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO4 4
#define GPIO18 18
#define DEBOUNCE 50
#define PWM_FREQ 100
#define LOG_FILE "flame_log.txt"

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        return 1;
    }

    // Set up GPIO4 as an input with a 50ms debouncing period
    if (gpioMode(GPIO4, GPIO_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO4 as input");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO18 as an output with PWM
    if (gpioMode(GPIO18, GPIO_MODE PWM) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO18 as PWM output");
        gpioTerminate();
        return 1;
    }

    // Set the PWM frequency
    if (gpioPWM(GPIO18, PWM_FREQ, 0) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        return 1;
    }

    // Open the log file for writing
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up a timer to read the sensor every 50ms
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = 50 * 1000000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 50 * 1000000;
    if (clock_settime(CLOCK_MONOTONIC, &timer) < 0) {
        syslog(LOG_ERR, "Failed to set timer");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read the sensor value
        int sensor_value = gpioRead(GPIO4);
        if (sensor_value == -1) {
            syslog(LOG_ERR, "Failed to read sensor value");
            continue;
        }

        // Debounce the sensor value
        int debounce_value = 0;
        for (int i = 0; i < DEBOUNCE; i++) {
            usleep(50 * 1000000);
            sensor_value = gpioRead(GPIO4);
            if (sensor_value == 0) {
                debounce_value = 1;
                break;
            }
        }

        // Log the sensor value
        if (debounce_value == 1) {
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char log_message[256];
            strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", time_info);
