#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>
#include <sys/time.h>

#define I2C_ADDRESS 0x44
#define I2C Bus 1
#define CONVERSION_TIME 100
#define FILE_NAME "light_data.txt"

int main(int argc, char **argv) {
    int i2c_fd;
    struct timespec start_time;
    struct timespec end_time;
    struct timeval tv;
    struct tm *timeinfo;
    struct stat file_stat;
    struct stat file_stat2;
    char filename[256];
    char buffer[256];
    int retry_count = 0;
    int retry_delay = 100;
    int retry_max = 5;
    int i2c_retry = 0;
    int i2c_result;
    int sensor_value;
    int sensor_value2;
    int status;
    int gpio_fd;
    int gpio_pin;
    int gpio_value;

    // Initialize GPIO
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = i2c_open(I2C Bus, I2C_ADDRESS, 0)) < 0) {
        perror("i2c_open");
        return 1;
    }

    // Configure I2C bus for continuous conversion mode
    if (i2c_set_mode(i2c_fd, I2C_MODE_CONTINUOUS_CONVERSION) < 0) {
        perror("i2c_set_mode");
        return 1;
    }

    // Configure I2C bus for automatic full-scale range
    if (i2c_set_address(i2c_fd, I2C_ADDRESS, I2C_ADDRESS) < 0) {
        perror("i2c_set_address");
        return 1;
    }

    // Open file for writing
    if ((file_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("open");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Get current time
        gettimeofday(&tv, NULL);
        timeinfo = localtime(&tv);
        strftime(filename, sizeof(filename), "%Y-%m-%d %H:%M:%S", timeinfo);
        sprintf(buffer, "%s %d\n", filename, timeinfo->tm_sec);

        // Read sensor value
        i2c_retry = 0;
        while (i2c_retry < retry_max) {
            i2c_retry = 0;
            if ((i2c_result = i2c_read(i2c_fd, buffer, sizeof(buffer), 0)) < 0) {
                if (errno == EIO) {
                    usleep(retry_delay * 1000);
                    i2c_retry++;
                } else {
                    perror("i2c_read");
                    return 1;
                }
            } else {
                break;
            }
        }

        if (i2c_result < 0) {
            perror("i2c_read");
            return 1;
        }

        // Convert sensor value to lux
        sensor_value = atoi(buffer);
        sensor_value2 = sensor_value;

        // Write sensor value to file
        if (write(file_fd, buffer, strlen(buffer)) < 0) {
            perror("write");
            return 1;
        }

        // Sleep for CONVERSION_TIME
        usleep(CONVERSION_TIME * 1000);
    }

    // Clean up
    close(file_fd);
    i2c_close(i2c_fd);
    gpio_close(gpio_fd);
    gpio_release(gpio_pin);
    gpio_cleanup();

    return 0;
}

void sigint_handler(int sig) {
    printf("Received SIGINT, shutting down...\n");
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, shutting down...\n");
    exit(0);
}

