#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define GPIO_MODE_INPUT
#define GPIO_PULLED_UP

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    int fd;
    int ret;
    struct gpio_config config;
    struct gpio_request req;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open chip
    fd = pigpio_open("/dev/pi-bcm2708", O_RDWR);
    if (fd < 0) {
        perror("pigpio_open");
        return 1;
    }

    // Set GPIO pin mode and pull-up
    ret = pigpio_set_mode(fd, GPIO_PIN, GPIO_MODE_INPUT, GPIO_PULLED_UP);
    if (ret < 0) {
        perror("pigpio_set_mode");
        pigpio_close(fd);
        return 1;
    }

    // Create request
    memset(&req, 0, sizeof(req));
    req.gpio = GPIO_PIN;
    req.mode = GPIO_IN;
    req.pull = GPIO_PULLED_UP;

    // Request line
    ret = pigpio_request(fd, &req);
    if (ret < 0) {
        perror("pigpio_request");
        pigpio_close(fd);
        return 1;
    }

    while (!stop) {
        // Read line
        ret = pigpio_read(fd, &req);
        if (ret < 0) {
            perror("pigpio_read");
            pigpio_release_request(fd, &req);
            pigpio_close(fd);
            return 1;
        }

        // Log status
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s Flame Detected: %s\n", timestamp, (req.value == 0) ? "YES" : "NO");

        // Sleep for 1 second
        sleep(1);
    }

    // Release request and close chip
    pigpio_release_request(fd, &req);
    pigpio_close(fd);

    return 0;
}

