#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define CHIP_ADDRESS 0x40
#define NUM_CHANNELS 8
#define POLL_INTERVAL 100

// Structure to hold the chip and line handles
typedef struct {
    pigpio gpiohandle chip;
    pigpio gpiohandle lines[NUM_CHANNELS];
} TTP226;

// Function to initialize the chip and lines
TTP226* init_chip() {
    TTP226* chip = malloc(sizeof(TTP226));
    if (!chip) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize the chip
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        exit(1);
    }

    // Configure the chip for direct GPIO output
    if (gpioSetMode(chip->chip, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        exit(1);
    }

    // Configure the lines for output
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetup(chip->lines[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetup failed for line %d\n", i);
            exit(1);
        }
        gpioWrite(chip->lines[i], 1); // Set all lines high to configure for output
    }

    // Set the chip address
    if (gpioWrite(chip->chip, CHIP_ADDRESS) < 0) {
        fprintf(stderr, "gpioWrite failed to set chip address\n");
        exit(1);
    }

    return chip;
}

// Function to read the chip and print the line states
void read_chip(TTP226* chip) {
    // Read the chip
    if (gpioRead(chip->chip, CHIP_ADDRESS) < 0) {
        fprintf(stderr, "gpioRead failed to read chip\n");
        exit(1);
    }

    // Read the line states
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioRead(chip->lines[i]) < 0) {
            fprintf(stderr, "gpioRead failed for line %d\n", i);
            exit(1);
        }
        printf("%06d %d ", time(NULL), gpioRead(chip->lines[i]));
    }
    printf("\n");
}

// Function to handle SIGINT
void sigint_handler(int sig) {
    // Release the chip and lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioWrite(chip->lines[i], 0); // Set all lines low to release
    }
    gpioWrite(chip->chip, CHIP_ADDRESS); // Release the chip
    gpioTerminate(); // Terminate the GPIO library
    exit(0);
}

int main() {
    // Register the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize the chip
    TTP226* chip = init_chip();

    // Main loop
    while (1) {
        read_chip(chip);
        sleep(POLL_INTERVAL / 1000.0); // Sleep for 100ms
    }

    // Release the chip and lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioWrite(chip->lines[i], 0); // Set all lines low to release
    }
    gpioWrite(chip->chip, CHIP_ADDRESS); // Release the chip
    gpioTerminate(); // Terminate the GPIO library
    free(chip);
    return 0;
}

