#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <errno.h>

#define GPIO4 4
#define GPIO5 5
#define BAUD 9600
#define DELAY 500

int main(int argc, char *argv[]) {
    int gpio4, gpio5, fd;
    struct termios oldt, newt;
    struct sigaction sa;
    int state1, state2;
    int i;

    // Initialize GPIO
    gpio_init();
    gpio_set_mode(GPIO4, PI_BCM, PI_OUTPUT);
    gpio_set_mode(GPIO5, PI_BCM, PI_OUTPUT);
    gpio_pull_up_down(GPIO4, PI_PUD_UP);
    gpio_pull_up_down(GPIO5, PI_PUD_UP);

    // Set GPIO4 and GPIO5 as output
    gpio_write(GPIO4, 0);
    gpio_write(GPIO5, 0);

    // Set up signal handler for SIGINT
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);

    // Open serial port for logging
    fd = open("/dev/ttyUSB0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set up terminal settings
    tcgetattr(fd, &oldt);
    newt = oldt;
    newt.c_cflag = BAUD;
    newt.c_cflag &= ~CSIZE;
    newt.c_cflag |= CS8;
    newt.c_lflag = 0;
    newt.c_oflag = 0;
    newt.c_cc[VMIN] = 0;
    newt.c_cc[VTIME] = DELAY;
    tcsetattr(fd, TCSANOW, &newt);

    // Read sensor states every 500ms
    while (1) {
        // Read sensor states
        state1 = gpio_read(GPIO4);
        state2 = gpio_read(GPIO5);

        // Log sensor states
        if (state1 == 0) {
            printf("Sensor 1: HIGH\n");
        } else {
            printf("Sensor 1: LOW\n");
        }
        if (state2 == 0) {
            printf("Sensor 2: HIGH\n");
        } else {
            printf("Sensor 2: LOW\n");
        }

        // Wait for 500ms
        usleep(500000);

        // Check for SIGINT
        if (killpg(0, SIGINT) == -1) {
            break;
        }
    }

    // Clean up
    gpio_write(GPIO4, 1);
    gpio_write(GPIO5, 1);
    gpio_close(GPIO4);
    gpio_close(GPIO5);
    close(fd);
    gpioTerminate();
    return 0;
}

