#include <unistd.h>

// Define constants
#define GPIO_PIN 4  // GPIO pin for the Omron D7E-1 tilt sensor
#define POLL_INTERVAL 100  // Polling interval in milliseconds
#define SIGINT_handler SIG_IGN  // Signal handler for SIGINT

// Initialize the pigpio library
void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        exit(1);
    }
}

// Define a function to handle SIGINT
void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    init_pigpio();

    // Configure the GPIO pin as an input with internal pull-up resistor
    if (gpioMode(GPIO_PIN, GPIO_IN) < 0) {
        fprintf(stderr, "Error configuring GPIO pin %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Set the GPIO pin as an input with internal pull-up resistor
    if (gpioPullUpDn(GPIO_PIN, GPIO_PULLUP_DISABLE) < 0) {
        fprintf(stderr, "Error setting GPIO pin %d as input with internal pull-up resistor: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Print the startup banner
    printf("Omron D7E-1 Tilt Sensor Reader\n");

    // Enter the main loop
    while (1) {
        // Read the GPIO pin
        int value = gpioRead(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO pin %d: %s\n", GPIO_PIN, strerror(errno));
            gpioTerminate();
            exit(1);
        }

        // Check if the tilt state has changed
        if (value == 0) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        // Flush stdout
        fflush(stdout);

        // Sleep for the polling interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}

