#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <sys/time.h>

#define I2C_ADDRESS 0x6A
#define CSV_FILE "uv_als_log.csv"

// Structure to hold sensor data
typedef struct {
    uint8_t uv_index;
    uint16_t als_visible;
    time_t timestamp;
} sensor_data_t;

// Function to read sensor data from Si1145
int read_sensor_data(pigpio_t gpio, sensor_data_t *data) {
    int status = pigpio_i2c_read(gpio, I2C_ADDRESS, 2, data, 2);
    if (status != 0) {
        printf("I2C read error: %d\n", status);
        return -1;
    }
    return 0;
}

// Function to write data to CSV file
int write_to_csv(int fd, sensor_data_t data) {
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&data.timestamp));
    char line[256];
    sprintf(line, "%s,%d,%d\n", timestamp, data.uv_index, data.als_visible);
    if (write(fd, line, strlen(line)) != strlen(line)) {
        printf("Write to CSV error\n");
        return -1;
    }
    return 0;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    printf("Exiting...\n");
    close(CSV_FILE);
    pigpio_close(gpio);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_init() != 0) {
        printf("pigpio init error\n");
        return 1;
    }

    // Open I2C file descriptor
    int i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        printf("I2C open error\n");
        pigpio_close(gpio);
        return 1;
    }

    // Open log file
    int log_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        printf("Log file open error\n");
        pigpio_close(gpio);
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create sensor data structure
    sensor_data_t data;
    memset(&data, 0, sizeof(data));

    while (1) {
        // Read sensor data
        if (read_sensor_data(gpio, &data) != 0) {
            continue;
        }

        // Convert UV index to integer
        data.uv_index = (data.uv_index >> 8) & 0xFF;

        // Write data to CSV file
        if (write_to_csv(log_fd, data) != 0) {
            continue;
        }

        // Print data to console
        printf("UV Index: %d, ALS Visible: %d\n", data.uv_index, data.als_visible);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_close(gpio);
    pigpio_i2c_close(i2c_fd);
    close(log_fd);

    return 0;
}

