#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x10
#define GPIO_PIN 17
#define POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0x7E
#define LOG_FILE "flow_log.txt"

// Structure to hold sensor data
typedef struct {
    uint16_t crc;
    float flow_rate;
} sensor_data_t;

// Function to calculate CRC
uint8_t calculate_crc(uint8_t data, uint8_t crc) {
    uint8_t result = crc;
    for (int i = 0; i < 8; i++) {
        if (data & (1 << i)) {
            result ^= 0x31;
        }
        result = (result >> 1) ^ (result & 0x01);
    }
    return result;
}

// Function to read sensor data
sensor_data_t read_sensor(int fd) {
    uint8_t data[2];
    int ret = read(fd, data, 2);
    if (ret != 2) {
        return (sensor_data_t){0, 0.0};
    }
    uint8_t crc = data[1];
    uint8_t calculated_crc = calculate_crc(data[0], CRC_INIT_VALUE);
    if (crc != calculated_crc) {
        return (sensor_data_t){0, 0.0};
    }
    return (sensor_data_t){crc, (float)data[0] / 100.0};
}

int main() {
    // Initialize GPIO
    pigpio = gpio_init();
    if (pigpio == -1) {
        perror("gpio_init");
        return 1;
    }
    gpio_mode(GPIO_PIN, PI_INPUT);
    gpio_pull_up_down(GPIO_PIN);

    // Open I2C file descriptor
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd == -1) {
        perror("open");
        return 1;
    }

    // Initialize sensor data
    sensor_data_t sensor1, sensor2;
    float sum_flow_rate = 0.0;
    int cycle = 0;

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        // Wait for start command from both sensors
        if (wait_for_start(i2c_fd, 100) == -1) {
            continue;
        }

        // Read sensor data
        sensor1 = read_sensor(i2c_fd);
        sensor2 = read_sensor(i2c_fd);

        // Check if both sensors are valid
        if (sensor1.flow_rate == 0.0 || sensor2.flow_rate == 0.0) {
            continue;
        }

        // Calculate average flow rate
        sum_flow_rate += sensor1.flow_rate + sensor2.flow_rate;
        cycle++;

        // Check if average flow rate is below threshold
        if (sum_flow_rate / cycle < 0.5) {
            gpio_write(GPIO_PIN, 1);
        } else {
            gpio_write(GPIO_PIN, 0);
        }

        // Log average flow rate
        fprintf(log_fd, "%f\n", sum_flow_rate / cycle);

        // Wait for 1 second
        sleep(1);

        // Reset sum flow rate
        sum_flow_rate = 0.0;
        cycle = 0;
    }

    // Clean up
    gpio_write(GPIO_PIN, 0);
    close(i2c_fd);
    close(log_fd);
    gpio_cleanup();
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    gpio_write(GPIO_PIN, 0);
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

// Function to wait for start command from both sensors
int wait_for_start(int fd, int timeout) {
    struct timeval tv;
    tv.tv_sec = timeout;
    tv.tv_usec = 0;
    select(fd, NULL, NULL, NULL, &tv);
    return (select(fd, NULL, NULL, NULL, NULL) == 0) ? 0 : -1;
}

