        cycle = 0;
    }

    // Clean up
    gpio_write(GPIO_PIN, 0);
    close(i2c_fd);
    close(log_fd);
    gpio_cleanup();
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    gpio_write(GPIO_PIN, 0);
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

// Function to wait for start command from both sensors
int wait_for_start(int fd, int timeout) {
    struct timeval tv;
    tv.tv_sec = timeout;
    tv.tv_usec = 0;
    select(fd, NULL, NULL, NULL, &tv);
    return (select(fd, NULL, NULL, NULL, NULL) == 0) ? 0 : -1;
}
