#define GPIO Pull_UP

int main(int argc, char **argv) {
    int pin;
    int gpio_fd;
    struct timespec last_sample;
    struct timespec now;
    struct timespec buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int detected = 0;
    int error = 0;

    // Initialize GPIO
    gpio_fd = pigpio_open("/dev/piyo", O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    // Set GPIO mode and pull-up resistor
    if (gpio_fd == -1) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }
    if (gpio_fd = gpio_mode(GPIO_PIN, GPIO_MODE_INPUT, GPIO Pull_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        return 1;
    }

