        buffer[buffer_index].tv_nsec = now.tv_nsec;
        buffer[buffer_index].detected = detected;
        buffer_index++;

        // Print buffer
        if (buffer_index > 0) {
            for (int i = 0; i < buffer_index; i++) {
                printf("%ld.%09ld %d\n", buffer[i].tv_sec, buffer[i].tv_nsec / 1000000, buffer[i].detected);
            }
        }

        // Sleep
        struct timespec sleep_time;
        sleep_time.tv_sec = now.tv_sec + (SAMPLE_INTERVAL_MS / 1000000.0);
        sleep_time.tv_nsec = (SAMPLE_INTERVAL_MS - (sleep_time.tv_sec * 1000000) * 1000) * 1000;
        if (nanosleep(&sleep_time, NULL) < 0) {
            fprintf(stderr, "Failed to sleep\n");
            return 1;
        }
    }

