#include <pigpio.h>
#include <time.h>

// Define constants
#define GPIO17 17
#define GPIO18 18
#define STALL_THRESHOLD 2  // seconds
#define LOG_FILE "stall_log.txt"

// Function to initialize the GPIO pins
void init_gpio(pigpio *gpio) {
    if (gpio->initialise(gpio, GPIO_MODE_INPUT, GPIO pull_up_down=GPIO_PUD_DOWN) != 0) {
        perror("gpio_init");
        exit(1);
    }
    gpio->gpio_fsel(gpio, GPIO17, GPIO_FSEL_OUT);
    gpio->gpio_fsel(gpio, GPIO18, GPIO_FSEL_OUT);
}

// Function to read sensor values
int read_sensor(pigpio *gpio) {
    int sensor1 = gpio->gpio_get_value(gpio, GPIO17);
    int sensor2 = gpio->gpio_get_value(gpio, GPIO18);
    if (sensor1 == 0 && sensor2 == 0) {
        return 1;  // Both sensors are LOW
    } else {
        return 0;  // Not a stall
    }
}

// Function to write to log file
void write_to_log(pigpio *gpio) {
    struct stat sb;
    if (stat(LOG_FILE, &sb) != 0) {
        if (mkdir(LOG_FILE, 0777) != 0) {
            perror("mkdir");
            exit(1);
        }
    }
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    pigpio *gpio = pigpio_get();
    if (gpio != NULL) {
        gpio->close(gpio);
        exit(0);
    }
}

int main() {
    pigpio *gpio = pigpio_get();
    if (gpio == NULL) {
        perror("pigpio_get");
        exit(1);
    }

    // Initialize GPIO pins
    init_gpio(gpio);

    // Check if the program is running in a non-interactive environment
    if (isatty(STDIN_FILENO) == 0) {
        printf("This program must be run in a non-interactive environment.\n");
        return 1;
    }

    // Initialize log file
    write_to_log(gpio);

    // Main loop
    int stall_count = 0;
    int last_stall_time = 0;
    while (1) {
        int sensor_value = read_sensor(gpio);
        if (sensor_value == 1) {
            if (time(NULL) - last_stall_time >= STALL_THRESHOLD) {
                write_to_log(gpio);
                stall_count++;
                last_stall_time = time(NULL);
            }
        } else {
            last_stall_time = 0;
            stall_count = 0;
        }
        if (stall_count >= 2) {
            write_to_log(gpio);
            stall_count = 0;
        }
        usleep(100000);  // 100ms delay
    }

    // Cleanly exit
    return 0;
}

