#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <sys/time.h>

#define I2C_ADDRESS 0x1D
#define I2C Bus 1
#define CSV_FILE "magnetic_log.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file
    int fd = open(CSV_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set up I2C
    if (gpioI2CSetup(I2C Bus, I2C_ADDRESS) < 0) {
        perror("gpioI2CSetup");
        return 1;
    }

    // Configure sensor
    if (gpioI2CSlaveMode(I2C Bus, I2C_ADDRESS, 0x00) < 0) {
        perror("gpioI2CSlaveMode");
        return 1;
    }
    if (gpioI2CWrite(I2C Bus, I2C_ADDRESS, 0x00, 0x01) < 0) {
        perror("gpioI2CWrite");
        return 1;
    }
    if (gpioI2CWrite(I2C Bus, I2C_ADDRESS, 0x00, 0x02) < 0) {
        perror("gpioI2CWrite");
        return 1;
    }
    if (gpioI2CWrite(I2C Bus, I2C_ADDRESS, 0x00, 0x03) < 0) {
        perror("gpioI2CWrite");
        return 1;
    }

    // Read sensor values
    struct timeval tv;
    struct tm timeinfo;
    time_t now;
    struct stat sb;
    char filename[256];
    char line[256];
    int x, y, z;

    while (1) {
        gettimeofday(&tv, &timeinfo);
        now = tv.tv_sec;
        strftime(filename, sizeof(filename), "%Y-%m-%d %H:%M:%S", &timeinfo);
        sprintf(line, "%s,%d,%d,%d\n", filename, x, y, z);
        if (fwrite(fd, line, strlen(line), 1) < 0) {
            perror("fwrite");
            continue;
        }

        // Read sensor values
        if (gpioI2CRead(I2C Bus, I2C_ADDRESS, 0x00, 0x00, &x, sizeof(x)) < 0) {
            if (errno == EIO) {
                perror("gpioI2CRead");
            } else {
                perror("gpioI2CRead");
            }
            continue;
        }
        if (gpioI2CRead(I2C Bus, I2C_ADDRESS, 0x00, 0x01, &y, sizeof(y)) < 0) {
            if (errno == EIO) {
                perror("gpioI2CRead");
            } else {
                perror("gpioI2CRead");
            }
            continue;
        }
        if (gpioI2CRead(I2C Bus, I2C_ADDRESS, 0x00, 0x02, &z, sizeof(z)) < 0) {
            if (errno == EIO) {
                perror("gpioI2CRead");
            } else {
                perror("gpioI2CRead");
            }
            continue;
        }

        // Check sensor values
        if (x < 0 || x > 1000 || y < 0 || y > 1000 || z < 0 || z > 1000) {
            fprintf(stderr, "Invalid sensor values: x=%d, y=%d, z=%d\n", x, y, z);
            continue;
        }
    }

    // Clean up
    gpioTerminate();
    close(fd);
    return 0;
}

