#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <time.h>
#include <errno.h>

#define GPIO_PIN 4
#define GPIO_MODE_INPUT
#define GPIO Pull_UP
#define GPIO_INT_EDGE_RISING
#define FILE_NAME "rpm_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO pin
    if (gpioSetup(GPIO_PIN, GPIO_MODE_INPUT, GPIO Pull_UP) < 0) {
        perror("gpioSetup");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO interrupt
    if (gpioBindInterrupt(GPIO_PIN, GPIO_INT_EDGE_RISING, gpioCallback) < 0) {
        perror("gpioBindInterrupt");
        gpioTerminate();
        return 1;
    }

    // Initialize pulse counter
    unsigned long long pulseCount = 0;
    struct timespec start;

    // Open log file
    int logFile = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logFile < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up timer
    struct itimerspec timer;
    timer.it_value.tv_sec = 1;
    timer.it_value.tv_nsec = 0;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 0;
    if (clock_nanosleep(CLOCK_REALTIME, 0, &timer, NULL) < 0) {
        perror("clock_nanosleep");
        close(logFile);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read GPIO pin
        int value = gpioGet(GPIO_PIN);
        if (value == 0) {
            // Increment pulse counter
            atomicAdd(&pulseCount, 1);
        }

        // Check for SIGINT and SIGTERM
        struct sigaction sa;
        sa.sa_handler = SIG_IGN;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;
        if (sigaction(SIGINT, &sa, NULL) < 0) {
            perror("sigaction");
            close(logFile);
            gpioTerminate();
            return 1;
        }
        if (sigaction(SIGTERM, &sa, NULL) < 0) {
            perror("sigaction");
            close(logFile);
            gpioTerminate();
            return 1;
        }

        // Log RPM
        struct timespec currentTime;
        clock_gettime(CLOCK_REALTIME, &currentTime);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&currentTime));
        char rpmStr[10];
        sprintf(rpmStr, "%llu", pulseCount);
        if (write(logFile, timestamp, strlen(timestamp)) < 0) {
            perror("write");
            close(logFile);
            gpioTerminate();
            return 1;
