        if (write(logFile, rpmStr, strlen(rpmStr)) < 0) {
            perror("write");
            close(logFile);
            gpioTerminate();
            return 1;
        }
        if (write(logFile, "\n", 1) < 0) {
            perror("write");
            close(logFile);
            gpioTerminate();
            return 1;
        }

        // Flush log file
        if (fflush(logFile) < 0) {
            perror("fflush");
            close(logFile);
            gpioTerminate();
            return 1;
        }

        // Check for sensor presence and rotation
        if (gpioRead(GPIO_PIN) == 1) {
            // Sensor is not rotating
            char rpmStr[10];
            sprintf(rpmStr, "0");
            if (write(logFile, timestamp, strlen(timestamp)) < 0) {
                perror("write");
                close(logFile);
                gpioTerminate();
                return 1;
            }
            if (write(logFile, rpmStr, strlen(rpmStr)) < 0) {
                perror("write");
                close(logFile);
                gpioTerminate();
                return 1;
            }
            if (write(logFile, "\n", 1) < 0) {
