#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <libgpiod.h>

#define GPIO_A 17
#define GPIO_B 27
#define GPIO_PU_A 18
#define GPIO_PU_B 19
#define LOG_FILE "rotation_log.txt"

// Structure to hold the quadrature state
typedef struct {
    int a_prev;
    int b_prev;
    int a_curr;
    int b_curr;
    int direction;
} QuadratureState;

// Mutex for protecting shared state
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for synchronization
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        // Flush and close the log file
        if (gpiod_open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644) == -1) {
            perror("gpiod_open");
            exit(1);
        }
        gpiod_close(LOG_FILE);
        // Terminate the driver library
        gpiod_close_all();
        exit(0);
    }
}

int main() {
    // Initialize the GPIO pins
    if (gpioInitialise() == -1) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set up the GPIO pins as input with pull-up resistors
    if (gpioSetMode(GPIO_A, GPIO_IN_PU) == -1 || gpioSetMode(GPIO_B, GPIO_IN_PU) == -1) {
        perror("gpioSetMode");
        exit(1);
    }

    // Set the GPIO pins as edge-triggered interrupts
    if (gpioEdgeTriggered(GPIO_A, GPIO_EDGE_RISING) == -1 || gpioEdgeTriggered(GPIO_B, GPIO_EDGE_RISING) == -1) {
        perror("gpioEdgeTriggered");
        exit(1);
    }

    // Create a mutex and condition variable for synchronization
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Create a file for logging
    if (gpiod_open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644) == -1) {
        perror("gpiod_open");
        exit(1);
    }

    // Create a quadrature state structure
    QuadratureState state = {0, 0, 0, 0, 0};

    // Set up the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Acquire the mutex
        pthread_mutex_lock(&mutex);

        // Read the GPIO values
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        // Update the quadrature state
        if (a == 1 && b == 0) {
            state.a_curr = 1;
            state.b_curr = 0;
            state.direction = 1;
        } else if (a == 0 && b == 1) {
            state.a_curr = 0;
            state.b_curr = 1;
            state.direction = -1;
        } else if (a == 1 && b == 1) {
            state.a_curr = 0;
            state.b_curr = 0;
            state.direction = 0;
        } else if (a == 0 && b == 0) {
            state.a_curr = 0;
            state.b_curr = 0;
            state.direction = 0;
        }

        // Check the direction
        if (state.direction != 0) {
            // Log the event
            time_t now = time(NULL);
            struct tm* ltm = localtime(&now);
            char log_str[20];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S.%3d", ltm);
            if (state.direction > 0) {
                fprintf(LOG_FILE, "%s CW\n", log_str);
            } else {
                fprintf(LOG_FILE, "%s CCW\n", log_str);
            }
        }

        // Release the mutex
        pthread_mutex_unlock(&mutex);

        // Wait on the condition variable
        pthread_cond_wait(&cond, &mutex);
    }

    // Terminate the driver library
    gpiod_close_all();
    exit(0);
}

