            state.b_curr = 0;
            state.direction = 1;
        } else if (a == 0 && b == 1) {
            state.a_curr = 0;
            state.b_curr = 1;
            state.direction = -1;
        } else if (a == 1 && b == 1) {
            state.a_curr = 0;
            state.b_curr = 0;
            state.direction = 0;
        } else if (a == 0 && b == 0) {
            state.a_curr = 0;
            state.b_curr = 0;
            state.direction = 0;
        }

        // Check the direction
        if (state.direction != 0) {
            // Log the event
            time_t now = time(NULL);
            struct tm* ltm = localtime(&now);
            char log_str[20];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S.%3d", ltm);
            if (state.direction > 0) {
                fprintf(LOG_FILE, "%s CW\n", log_str);
            } else {
                fprintf(LOG_FILE, "%s CCW\n", log_str);
            }
        }

        // Release the mutex
        pthread_mutex_unlock(&mutex);

        // Wait on the condition variable
        pthread_cond_wait(&cond, &mutex);
    }

    // Terminate the driver library
    gpiod_close_all();
    exit(0);
}
```

This code uses the `libgpiod` library to interact with the GPIO pins and the `pthread` library for synchronization. It sets up the GPIO pins as input with pull-up resistors and edge-triggered interrupts, and creates a mutex and condition variable for synchronization. The main loop reads the GPIO values, updates the quadrature state, checks the direction, logs the event, and waits on the condition variable. The signal handler is set up to perform a graceful shutdown by flushing and closing the log file and terminating the driver library.

