#include <signal.h>

#define GPIO_PIN 23
#define GPIO_PIN_LED 18
#define CAPACITIVE_PIN GPIO_PIN
#define CAPACITIVE_VALUE 1000
#define LED_VALUE 1
#define DELAY 50

int main() {
    int gpio;
    int capacitive;
    int led;
    int status;
    int last_touch = 0;

    // Initialize logging
    openlog("touch_led", LOG_PID, LOG_AUTH);

    // Install signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open GPIO chip
    gpio = gpio_open();
    if (gpio < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(1);
    }

    // Request GPIO lines
    capacitive = gpio_get_input(GPIO_PIN);
    if (capacitive < 0) {
        syslog(LOG_ERR, "Failed to request capacitive input line");
        gpio_close(gpio);
        exit(1);
    }

    led = gpio_get_output(GPIO_PIN_LED);
    if (led < 0) {
        syslog(LOG_ERR, "Failed to request LED output line");
        gpio_close(gpio);
        exit(1);
    }

    // Set up current-limiting resistor
    gpio_set_mode(GPIO_PIN_LED, PI_INPUT);
    gpio_set_pull_up_down(GPIO_PIN_LED, PI_PUD_DOWN);

    while (1) {
        // Read capacitive value
        int value = gpio_get_input_value(GPIO_PIN);
        if (value > last_touch) {
            // LED is touched
            gpio_write(GPIO_PIN_LED, LED_VALUE);
            syslog(LOG_INFO, "LED is touched");
            last_touch = value;
        } else {
            // LED is not touched
            gpio_write(GPIO_PIN_LED, 0);
            syslog(LOG_INFO, "LED is not touched");
        }

        // Wait for 50ms
        usleep(DELAY * 1000);

        // Check for GPIO chip unavailability
        if (gpio == -1) {
            syslog(LOG_ERR, "GPIO chip is unavailable");
            break;
        }
    }

    // Release resources
    gpio_close(gpio);
    syslog(LOG_INFO, "GPIO chip closed");

    // Wait for 1 second before exiting
    sleep(1);

    return 0;
}

void handle_sigint(int sig) {
    gpio_write(GPIO_PIN_LED, 0);
    syslog(LOG_INFO, "SIGINT received, shutting down");
    gpio_close(gpio);
    exit(0);
}

void handle_sigterm(int sig) {
    gpio_write(GPIO_PIN_LED, 0);
    syslog(LOG_INFO, "SIGTERM received, shutting down");
    gpio_close(gpio);
    exit(0);
}

