#include <pigpio.h>
#include <time.h>

#define BUFFER_SIZE 100
#define LED1_GPIO 27
#define LED2_GPIO 22
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define LOG_FILE "/var/log/touch_log.txt"

int log_buffer[BUFFER_SIZE][3];
int log_index = 0;
int overflow = 0;

void cleanup() {
    pigpio_close(SENSOR1_GPIO);
    pigpio_close(SENSOR2_GPIO);
    pigpio_close(LED1_GPIO);
    pigpio_close(LED2_GPIO);
    close(LOG_FILE);
}

void log_event(int sensor, int state) {
    if (log_index >= BUFFER_SIZE) {
        overflow++;
        log_index = 0;
    }
    log_buffer[log_index][0] = sensor;
    log_buffer[log_index][1] = time(NULL);
    log_buffer[log_index][2] = state;
    log_index++;
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pigpio_init() < 0) {
        perror("pigpio_init");
        exit(1);
    }

    if (pigpio_mode(SENSOR1_GPIO, PI_INPUT) < 0) {
        perror("pigpio_mode");
        exit(1);
    }
    if (pigpio_mode(SENSOR2_GPIO, PI_INPUT) < 0) {
        perror("pigpio_mode");
        exit(1);
    }
    if (pigpio_mode(LED1_GPIO, PI_OUTPUT) < 0) {
        perror("pigpio_mode");
        exit(1);
    }
    if (pigpio_mode(LED2_GPIO, PI_OUTPUT) < 0) {
        perror("pigpio_mode");
        exit(1);
    }

    if (pigpio_pullup(SENSOR1_GPIO, PI_PUD_OFF) < 0) {
        perror("pigpio_pullup");
        exit(1);
    }
    if (pigpio_pullup(SENSOR2_GPIO, PI_PUD_OFF) < 0) {
        perror("pigpio_pullup");
        exit(1);
    }

    while (1) {
        int sensor1_state = pigpio_read(SENSOR1_GPIO);
        int sensor2_state = pigpio_read(SENSOR2_GPIO);
        if (sensor1_state == 1) {
            log_event(SENSOR1_GPIO, 1);
            pigpio_write(LED1_GPIO, 1);
        } else {
            pigpio_write(LED1_GPIO, 0);
        }
        if (sensor2_state == 1) {
            log_event(SENSOR2_GPIO, 1);
            pigpio_write(LED2_GPIO, 1);
        } else {
            pigpio_write(LED2_GPIO, 0);
        }
        usleep(50 * 1000);
    }

    cleanup();
    FILE *log_file = fopen(LOG_FILE, "r");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    for (int i = 0; i < log_index; i++) {
        fprintf(stderr, "%d %d %d\n", log_buffer[i][0], log_buffer[i][1], log_buffer[i][2]);
    }
    fprintf(stderr, "Overflow: %d\n", overflow);
    fclose(log_file);
    return 0;
}

