int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Enable the internal pull-up resistor on GPIO17
    if (gpioMode(GPIO_PIN, GPIO_IN_PUD_UP) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Open the log file for writing
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Set up the signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Poll the GPIO pin
        int value = gpioGet(GPIO_PIN);
        if (value == 0) {
            // Write to log file
            fprintf(log_file, "%s\n", "Rain Detected");
        } else {
            // Write to log file
            fprintf(log_file, "%s\n", "No Rain");
        }

        // Flush the log buffer
        fflush(log_file);

        // Sleep for 500ms
        usleep(500000);
    }

    // Close the log file
    fclose(log_file);

    // Release the GPIO resources
    gpioTerminate();

    return 0;
}

