#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x1E
#define I2C_DATA_SIZE 2

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the log file
    int log_fd = open("biometric_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Install the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, 100000);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    while (1) {
        // Read the heart rate and SpO2 data
        uint8_t data[I2C_DATA_SIZE];
        if (pigpio_i2c_read(i2c_fd, data, I2C_DATA_SIZE) < I2C_DATA_SIZE) {
            perror("pigpio_i2c_read");
            continue;
        }

        // Check the data
        if (data[0] & 0x80) {
            printf("Communication error\n");
            continue;
        }

        uint16_t heart_rate = (data[0] & 0x7F) << 8 | data[1];
        uint8_t sp_o2 = data[1] & 0x3F;

        // Format the log message
        char log_message[64];
        strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S, Heart Rate: %d BPM, SpO2: %d%%", localtime(NULL), heart_rate, sp_o2);

        // Write to the log file
        if (write(log_fd, log_message, strlen(log_message)) < strlen(log_message)) {
            perror("write");
            continue;
        }

        // Flush the log file
        if (fflush(log_fd) < 0) {
            perror("fflush");
            continue;
        }

        // Pause for one second
        sleep(1);
    }

    // Close the I2C handle
    pigpio_i2c_close(i2c_fd);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_close");
    }

    // Close the log file
    if (close(log_fd) < 0) {
        perror("close");
    }

    // Terminate the GPIO library
    gpioTerminate();
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
    }

    return 0;
}

