#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define LOG_FILE "bridge_integrity.log
#define LOG_LEVEL LOG_INFO
#define THRESHOLD 2

// Initialize the GPIO library
void init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }
}

// Clean up GPIO resources
void cleanup_gpio() {
    gpioCleanUp();
}

// Log a message to the log file
void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        return;
    }
    fprintf(log_file, "%s %s\n", ctime_r(time(NULL), NULL), message);
    fclose(log_file);
}

// Check if the alarm is active
int is_alarm_active() {
    return gpioRead(GPIO27) == 1;
}

// Check if a sensor is HIGH
int is_sensor_high(int gpio) {
    return gpioRead(gpio) == 1;
}

// Check if a sensor has exceeded the threshold
int has_exceeded_threshold(int gpio, int threshold) {
    return is_sensor_high(gpio) && (time(NULL) - last_tilt_start) > threshold * 1000;
}

// Main loop
void main_loop() {
    int sensor1_high = 0;
    int sensor2_high = 0;
    int last_tilt_start = 0;
    int alarm_active = 0;

    init_gpio();

    while (1) {
        // Read sensor values
        sensor1_high = is_sensor_high(GPIO17);
        sensor2_high = is_sensor_high(GPIO18);

        // Log events
        if (sensor1_high && !sensor2_high) {
            log_message("tilt-start");
            last_tilt_start = time(NULL);
        } else if (!sensor1_high && !sensor2_high && last_tilt_start != 0) {
            log_message("tilt-end");
            last_tilt_start = 0;
        } else if (has_exceeded_threshold(GPIO17, THRESHOLD) || has_exceeded_threshold(GPIO18, THRESHOLD)) {
            if (!alarm_active) {
                alarm_active = 1;
                log_message("threshold-exceeded");
                gpioWrite(GPIO27, 1);
            }
        } else if (alarm_active) {
            log_message("threshold-recovered");
            alarm_active = 0;
            gpioWrite(GPIO27, 0);
        }

        // Sleep for 100ms
        usleep(100000);
    }

    cleanup_gpio();
    exit(0);
}

// Signal handlers
void sigint_handler(int sig) {
    cleanup_gpio();
    exit(0);
}

void sigterm_handler(int sig) {
    cleanup_gpio();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    log_message("Starting bridge integrity monitor");

    main_loop();

    return 0;
}

