#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <syslog.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x10
#define I2C_TIMEOUT 100
#define VIBRATION_THRESHOLD 500
#define LED_PIN 17
#define LOG_FILE "seismic_events.log"

int main() {
    // Initialize GPIO
    int gpio = 2; // SDA
    int gpio2 = 3; // SCL
    int gpio3 = 17; // LED
    int gpio4 = 18; // Power-down
    int gpio5 = 22; // Reset

    if (gpioInitialise() == -1) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO as output for LED and power-down
    gpioWrite(gpio3, 1);
    gpioWrite(gpio4, 1);

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        return 1;
    }

    // Initialize I2C
    int i2c_fd = i2cOpen(I2C_ADDRESS, 0, I2C_MODE_MASTER, I2C_SPEED_100KHZ);
    if (i2c_fd == -1) {
        perror("i2cOpen");
        return 1;
    }

    // Initialize sensor
    uint8_t ctrl1 = 0x00;
    uint8_t data = 0x00;
    uint8_t retry = 0;
    while (retry < 3) {
        if (i2cRead(i2c_fd, &ctrl1, 1, I2C_TIMEOUT) == -1) {
            perror("i2cRead");
            retry++;
        } else if (ctrl1 & 0x80) {
            // Power-down bit is set
            ctrl1 = 0x01;
            if (i2cWrite(i2c_fd, &ctrl1, 1, I2C_TIMEOUT) == -1) {
                perror("i2cWrite");
                retry++;
            } else {
                retry = 0;
            }
        } else {
            break;
        }
    }

    if (retry >= 3) {
        perror("Failed to initialize sensor");
        return 1;
    }

    // Set up I2C
    i2cSetClock(i2c_fd, I2C_SPEED_100KHZ);
    i2cSetMode(i2c_fd, I2C_MODE_MASTER);

    // Main loop
    struct timespec ts;
    while (1) {
        // Read sensor data
        if (i2cRead(i2c_fd, &data, 1, I2C_TIMEOUT) == -1) {
            perror("i2cRead");
            continue;
        }

        // Calculate Euclidean vibration magnitude
        double magnitude = sqrt(data & 0xFF) * 0.1;

        // Check for threshold
        if (magnitude > VIBRATION_THRESHOLD) {
            // Log event
            time_t now = time(NULL);
            struct tm* ltm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
            fprintf(log_fd, "%s %f\n", timestamp, magnitude);
            fflush(log_fd);

            // Turn on LED
            gpioWrite(gpio3, 0);
            usleep(1000000);
            gpioWrite(gpio3, 1);

            // Reset sensor
            ctrl1 = 0x00;
            if (i2cWrite(i2c_fd, &ctrl1, 1, I2C_TIMEOUT) == -1) {
                perror("i2cWrite");
                continue;
            }
        }

        // Sleep
        clock_gettime(CLOCK_MONOTONIC, &ts);
        usleep(100000);
    }

    // Clean up
    gpioWrite(gpio4, 0);
    gpioWrite(gpio3, 0);
    gpioClose(gpio3);
    gpioClose(gpio4);
    gpioTerminate();
    i2cClose(i2c_fd);
    close(log_fd);

    return 0;
}

