// Define constants
#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define GPIO18 18
#define POLL_INTERVAL 50
#define NUM_SENSORS 4

// Define a structure to hold sensor data
typedef struct {
    int pin;
    int value;
} sensor_t;

// Function to initialize GPIO pins
void init_gpio(pigpio *gpio) {
    if (gpio->init(gpio->gpio_fd, GPIO_MODE_INPUT, GPIO pull_up_down=GPIO_PUD_DOWN) < 0) {
        perror("gpio_init");
        exit(1);
    }

    gpio->gpio_fd[GPIO4] = gpio->init(gpio->gpio_fd, GPIO_MODE_INPUT, GPIO pull_up_down=GPIO_PUD_DOWN);
    if (gpio->gpio_fd[GPIO4] < 0) {
        perror("gpio_init GPIO4");
        exit(1);
    }

    gpio->gpio_fd[GPIO17] = gpio->init(gpio->gpio_fd, GPIO_MODE_INPUT, GPIO pull_up_down=GPIO_PUD_DOWN);
    if (gpio->gpio_fd[GPIO17] < 0) {
        perror("gpio_init GPIO17");
        exit(1);
    }

    gpio->gpio_fd[GPIO27] = gpio->init(gpio->gpio_fd, GPIO_MODE_INPUT, GPIO pull_up_down=GPIO_PUD_DOWN);
    if (gpio->gpio_fd[GPIO27] < 0) {
        perror("gpio_init GPIO27");
        exit(1);
    }

    gpio->gpio_fd[GPIO22] = gpio->init(gpio->gpio_fd, GPIO_MODE_INPUT, GPIO pull_up_down=GPIO_PUD_DOWN);
    if (gpio->gpio_fd[GPIO22] < 0) {
        perror("gpio_init GPIO22");
        exit(1);
    }

    gpio->gpio_fd[GPIO18] = gpio->init(gpio->gpio_fd, GPIO_MODE_OUTPUT, GPIO pull_up_down=GPIO_PUD_DOWN);
    if (gpio->gpio_fd[GPIO18] < 0) {
        perror("gpio_init GPIO18");
        exit(1);
    }
}

// Function to read sensor data
void read_sensors(pigpio *gpio) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        int value = gpio->read(gpio->gpio_fd[i]);
        if (value == 0) {
            printf("Sensor %d detected an object\n", i);
            gpio->write(gpio->gpio_fd[GPIO18], 1);
        } else {
            gpio->write(gpio->gpio_fd[GPIO18], 0);
        }
    }
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    printf("Received signal %d, cleaning up...\n", sig);
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpio->close(gpio->gpio_fd[i]);
    }
    exit(0);
}

int main() {
    // Initialize GPIO pins
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        exit(1);
    }

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize GPIO pins
    init_gpio(gpio);

    // Read sensor data in a loop
    while (1) {
        read_sensors(gpio);
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up GPIO resources
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpio->close(gpio->gpio_fd[i]);
    }
    gpio->close(gpio->gpio_fd[GPIO18]);
    pigpio_free(gpio);

    return 0;
