#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>
#include <pigpio.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME 50
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

void sigterm_handler(int sig) {
    exit_flag = 1;
}

int main() {
    int i, sensor_id, pin;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    struct gpiod_line_request *requests[NUM_SENSORS];
    struct gpiod_line *line;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec interval;
    struct tm *time_info;
    char timestamp[32];
    char sensor_id_str[10];
    char pin_str[10];
    char event_str[100];

    // Initialize the signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the chip
    chip = gpiod_chip_open("ky026", 0);
    if (!chip) {
        syslog(LOG_USER, "Error opening chip");
        return 1;
    }

    // Create the lines
    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_line_create(chip, "ky026", i, 0);
        if (!lines[i]) {
            syslog(LOG_USER, "Error creating line %d", i);
            return 1;
        }
        requests[i] = gpiod_line_request_create(lines[i], "debounce", DEBOUNCE_TIME);
        if (!requests[i]) {
            syslog(LOG_USER, "Error creating request %d", i);
            gpiod_line_destroy(lines[i]);
            return 1;
        }
    }

    // Create the interval
    interval.tv_sec = 1;
    interval.tv_nsec = 0;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (!exit_flag) {
        // Get the current time
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        time_info = localtime(&end_time.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", time_info);
        sprintf(sensor_id_str, "%d", end_time.tv_nsec / 1000000000);
        sprintf(pin_str, "%d", end_time.tv_nsec % 1000000000);

        // Read the lines
        for (i = 0; i < NUM_SENSORS; i++) {
            line = gpiod_line_request_get_request(requests[i]);
            if (!line) {
                syslog(LOG_USER, "Error getting request %d", i);
                continue;
            }
            if (gpiod_line_request_get_value(line, &end_time, NULL)) {
                syslog(LOG_USER, "Error reading line %d", i);
                gpiod_line_request_destroy(requests[i]);
                gpiod_line_destroy(lines[i]);
                continue;
            }
            if (gpiod_line_get_value(line, &end_time, NULL)) {
                syslog(LOG_USER, "Error getting value of line %d", i);
                gpiod_line_request_destroy(requests[i]);
                gpiod_line_destroy(lines[i]);
                continue;
            }
            if (gpiod_line_get_value(line, &end_time, NULL) == 0) {
                // Debounce
                struct timespec debounce_start;
                gpiod_line_request_get_debounce_start(requests[i], &debounce_start);
                struct timespec debounce_end;
                gpiod_line_request_get_debounce_end(requests[i], &debounce_end);
                if (debounce_start.tv_sec != debounce_end.tv_sec || debounce_start.tv_nsec != debounce_end.tv_nsec) {
                    continue;
                }
            }
            sprintf(event_str, "%s - Sensor %d (GPIO %s) - Flame Detected", timestamp, sensor_id_str, pin_str);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                syslog(LOG_USER, "Error opening log file");
                continue;
            }
            fprintf(log_file, "%s\n", event_str);
            fclose(log_file);
            syslog(LOG_USER, "Flame detected on line %d", i);
        }

        // Sleep for the next interval
        nanosleep(&interval, NULL);
    }

    // Release the lines
    for (i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_destroy(lines[i]);
        gpiod_line_request_destroy(requests[i]);
    }

    // Close the chip
    gpiod_chip_close(chip);

    // Close the log file
    fclose(LOG_FILE);

    // Close the syslog
    closelog();

    return 0;
}

