#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

#define GPIO_PIN 5
#define GPIO_PIN_2 6
#define GPIO_PIN_3 13
#define GPIO_PIN_4 19
#define GPIO_PIN_5 26
#define GPIO_PIN_6 12
#define GPIO_PIN_7 16
#define GPIO_PIN_8 20

#define TOUCH_PIN 0
#define TOUCH_PIN_2 1
#define TOUCH_PIN_3 2
#define TOUCH_PIN_4 3
#define TOUCH_PIN_5 4
#define TOUCH_PIN_6 5
#define TOUCH_PIN_7 6
#define TOUCH_PIN_8 7

#define TOUCH_STATE_CHANGED 0
#define TOUCH_DETECTED 1
#define TOUCH_RELEASED 2

int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_line_t lines[8];
    gpiod_line_request_t requests[8];
    gpiod_line_event_t events[8];
    gpiod_event_t event;
    struct timespec last_update;
    struct timespec now;
    int i, j, ret, pin, state, pin2, state2;
    char buffer[64];

    // Initialize GPIO context
    ret = gpiod_context_new(&ctx);
    if (ret < 0) {
        fprintf(stderr, "gpiod_context_new: %d\n", errno);
        return 1;
    }

    // Create lines
    for (i = 0; i < 8; i++) {
        gpiod_line_new(&lines[i], ctx, GPIO_PIN + i);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_line_new: %d\n", errno);
            gpiod_context_free(ctx);
            return 1;
        }
    }

    // Create requests
    for (i = 0; i < 8; i++) {
        gpiod_line_request_new(&requests[i], lines[i]);
        if (requests[i] == NULL) {
            fprintf(stderr, "gpiod_line_request_new: %d\n", errno);
            for (j = 0; j < i; j++) {
                gpiod_line_free(lines[j]);
            }
            gpiod_context_free(ctx);
            return 1;
        }
    }

    // Create events
    for (i = 0; i < 8; i++) {
        gpiod_line_event_new(&events[i], requests[i]);
        if (events[i] == NULL) {
            fprintf(stderr, "gpiod_line_event_new: %d\n", errno);
            for (j = 0; j < i; j++) {
                gpiod_line_free(lines[j]);
                gpiod_line_request_free(requests[j]);
            }
            gpiod_context_free(ctx);
            return 1;
        }
    }

    // Set up event handlers
    gpiod_line_event_set_handler(events[TOUCH_PIN], TOUCH_STATE_CHANGED, handle_touch_state_changed);
    gpiod_line_event_set_handler(events[TOUCH_PIN_2], TOUCH_STATE_CHANGED, handle_touch_state_changed);
    gpiod_line_event_set_handler(events[TOUCH_PIN_3], TOUCH_STATE_CHANGED, handle_touch_state_changed);
    gpiod_line_event_set_handler(events[TOUCH_PIN_4], TOUCH_STATE_CHANGED, handle_touch_state_changed);
    gpiod_line_event_set_handler(events[TOUCH_PIN_5], TOUCH_STATE_CHANGED, handle_touch_state_changed);
    gpiod_line_event_set_handler(events[TOUCH_PIN_6], TOUCH_STATE_CHANGED, handle_touch_state_changed);
    gpiod_line_event_set_handler(events[TOUCH_PIN_7], TOUCH_STATE_CHANGED, handle_touch_state_changed);
    gpiod_line_event_set_handler(events[TOUCH_PIN_8], TOUCH_STATE_CHANGED, handle_touch_state_changed);

    // Set up bulk line requests
    for (i = 0; i < 8; i++) {
        gpiod_line_request_set_bulk_request(requests[i], TOUCH_PIN + i);
    }

    // Set up initial state
    for (i = 0; i < 8; i++) {
        gpiod_line_get_state(lines[i], &state);
        if (state == 0) {
            gpiod_line_set_state(lines[i], TOUCH_RELEASED);
        } else {
            gpiod_line_set_state(lines[i], TOUCH_DETECTED);
        }
    }

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &now);

        // Check for events
        for (i = 0; i < 8; i++) {
            gpiod_line_get_state(lines[i], &state);
            if (state != last_update[i]) {
                last_update[i] = state;
                gpiod_line_event_get(&event, events[i]);
                if (event.type == TOUCH_STATE_CHANGED) {
                    pin = event.line->line->id - TOUCH_PIN;
                    pin2 = event.line->line->id - TOUCH_PIN_2;
                    state2 = event.state;
                    if (state2 == TOUCH_DETECTED) {
                        printf("%Y-%m-%d %H:%M:%S.%06d %d %d TOUCH_DETECTED\n",
                               now.tv_sec, now.tv_nsec / 1000000000, pin, pin2);
                    } else if (state2 == TOUCH_RELEASED) {
                        printf("%Y-%m-%d %H:%M:%S.%06d %d %d TOUCH_RELEASED\n",
                               now.tv_sec, now.tv_nsec / 1000000000, pin, pin2);
                    }
                }
            }
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    for (i = 0; i < 8; i++) {
        gpiod_line_free(lines[i]);
        gpiod_line_request_free(requests[i]);
        gpiod_line_event_free(events[i]);
    }
    gpiod_context_free(ctx);

    return 0;
}

void handle_touch_state_changed(gpiod_line_event_t *event) {
    gpiod_line_event_get(event->line, &pin, &state);
    gpiod_line_event_get(event->line, &pin2, &state2);
    if (state == TOUCH_DETECTED) {
        printf("%d %d TOUCH_DETECTED\n", pin, pin2);
    } else if (state == TOUCH_RELEASED) {
        printf("%d %d TOUCH_RELEASED\n", pin, pin2);
    }
}

