#include <pigpio.h>
#include <time.h>

// Define constants
#define TOUCH_LOG_FILE "touch_log.txt"
#define LED_PIN 17
#define TOUCH_PIN 2
#define TOUCH_PUD 0x00  // Pull-down resistor
#define TOUCH Channels 8

// Function to initialize the GPIO driver
int init_gpio(pigpio *gpio) {
    if (gpio_init(gpio) < 0) {
        fprintf(stderr, "Error initializing GPIO driver\n");
        exit(1);
    }
    if (gpio_set_mode(gpio, TOUCH_PIN, GPIO_IN, TOUCH_PUD) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        exit(1);
    }
    return 0;
}

// Function to read a touch channel
int read_touch(pigpio *gpio, int channel) {
    int value = gpio_get_value(gpio, channel);
    if (value == 0) {
        return 1;  // Touch detected
    } else {
        return 0;  // Not touched
    }
}

// Function to write to the log file
void write_log(pigpio *gpio, int channel, int touched) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char log_message[64];
    sprintf(log_message, "%04d-%02d-%02d %02d:%02d:%02d – Channel %d Touched", 
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday, 
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec, channel + 1);
    FILE *log_file = fopen(TOUCH_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        exit(1);
    }
    if (fputs(log_message, log_file) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(log_file);
        exit(1);
    }
    fclose(log_file);
}

// Function to handle the SIGINT and SIGTERM signals
void signal_handler(int sig) {
    pigpio *gpio = pigpio_get();
    if (gpio) {
        gpio_close(gpio);
        exit(0);
    }
}

int main() {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        fprintf(stderr, "Error initializing pigpio\n");
        exit(1);
    }

    // Initialize GPIO
    if (init_gpio(gpio) < 0) {
        pigpio_close(gpio);
        exit(1);
    }

    // Set up the alert LED
    if (gpio_set_mode(gpio, LED_PIN, GPIO_OUT) < 0) {
        pigpio_close(gpio);
        exit(1);
    }
    gpio_write(gpio, LED_PIN, 0);

    // Set up the touch channels
    for (int i = 1; i <= TOUCH_CHANNELS; i++) {
        if (gpio_set_mode(gpio, TOUCH_PIN + i, GPIO_IN, TOUCH_PUD) < 0) {
            pigpio_close(gpio);
            exit(1);
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        for (int i = 1; i <= TOUCH_CHANNELS; i++) {
            int touched = read_touch(gpio, i);
            if (touched) {
                write_log(gpio, i, 1);
                gpio_write(gpio, LED_PIN, 1);
            } else {
                gpio_write(gpio, LED_PIN, 0);
            }
        }
        usleep(50000);
    }

    pigpio_close(gpio);
    return 0;
}

