#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <libgpiod.h>

// Define constants
#define I2C_ADDRESS 0x44
#define I2C_TIMEOUT 100
#define FILE_NAME "light_data.txt"

// Define structure for OPT3001 sensor data
typedef struct {
    uint16_t lux;
} opt3001_data_t;

// Define function prototypes
void opt3001_config(gpio_fd_t i2c_fd, uint8_t config);
void opt3001_read(gpio_fd_t i2c_fd, opt3001_data_t *data);
void opt3001_cleanup(gpio_fd_t i2c_fd);

// Define signal handler for SIGINT
void sigint_handler(int sig) {
    opt3001_cleanup(gpio_fd);
    exit(0);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, sigint_handler);

    // Initialize libgpiod
    if (libgpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    gpio_fd_t i2c_fd = libgpiod_open("/dev/i2c-1", I2C_RDWR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        libgpiod_cleanup();
        return 1;
    }

    // Configure OPT3001 sensor
    opt3001_config(i2c_fd, 0x01); // Configure for lux measurement

    // Open log file
    int log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        libgpiod_close(i2c_fd);
        libgpiod_cleanup();
        return 1;
    }

    // Set up timer to read data every 1 second
    struct itimerval timer;
    timer.it_value.tv_sec = 1;
    timer.it_value.tv_usec = 0;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 100;
    if (setitimer(ITIMER_REAL, &timer, sizeof(timer)) != 0) {
        fprintf(stderr, "Error setting timer: %s\n", strerror(errno));
        libgpiod_close(i2c_fd);
        libgpiod_cleanup();
        close(log_fd);
        return 1;
    }

    while (1) {
        // Read data from OPT3001 sensor
        opt3001_data_t data;
        if (opt3001_read(i2c_fd, &data) != 0) {
            fprintf(stderr, "Error reading data from OPT3001 sensor: %s\n", strerror(errno));
            continue;
        }

        // Byte-swap data (big-endian to little-endian)
        data.lux = (data.lux >> 8) | (data.lux & 0xFF);

        // Format data as string
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL));
