#define GPIO_PIN 4
#define GPIO_ALERT 17
#define LOG_FILE "fire_events.log"

int main(int argc, char *argv[]) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        return 1;
    }

    // Open the log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up the GPIO pins
    if (gpioSetMode(GPIO_PIN, GPIO_MODE_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_ALERT, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO_ALERT, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO alert pin");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the sensor value
        int sensor_value = gpioRead(GPIO_PIN);
        if (sensor_value < 0) {
            syslog(LOG_ERR, "Failed to read sensor value");
            continue;
        }

        // Log the sensor value
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time(NULL));
        fprintf(log_fd, "%s %d\n", timestamp, sensor_value);

        // Check if the sensor is reporting a flame
        if (sensor_value == 0) {
            // Set the alert pin high
            if (gpioWrite(GPIO_ALERT, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO alert pin");
                continue;
            }
            usleep(1000000); // Wait for 1 second
            gpioWrite(GPIO_ALERT, 0);
        }

        usleep(500000); // Wait for 500ms
    }

    // Cleanup
    close(log_fd);
    gpioWrite(GPIO_ALERT, 0); // Reset the alert pin
    gpioTerminate();
    return 0;
}

