#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "touch_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO4 as input with pull-down bias
    if (gpioMode(GPIO_PIN, GPIO_IN) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read GPIO4
        int value = gpioRead(GPIO_PIN);
        if (value == 0) {
            // Touch detected
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s: Touch Detected\n", timestamp);
            fflush(log_fd);
        } else {
            // Touch released
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s: Touch Released\n", timestamp);
            fflush(log_fd);
        }

        // Debounce
        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    // Clean up
    close(log_fd);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(GPIO_PIN, 0);
    close(LOG_FILE);
    exit(0);
}

void sigterm_handler(int sig) {
    gpioWrite(GPIO_PIN, 0);
    close(LOG_FILE);
    exit(0);
}

