#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x10
#define I2C_TIMEOUT 100
#define I2C_READ_SIZE 5
#define CRC_POLYNOMINAL 0x31
#define CRC_INIT_VALUE 0xFF

// Function to calculate CRC-8
uint8_t calculate_crc(uint8_t data[], uint8_t size) {
    uint8_t crc = CRC_INIT_VALUE;
    for (uint8_t i = 0; i < size; i++) {
        crc = (crc >> 1);
        if ((crc & 1) == 0) {
            crc = (crc ^ CRC_POLYNOMINAL);
        }
        crc = (crc ^ data[i]);
    }
    return crc;
}

// Function to read from I2C
int read_i2c(uint8_t* data, uint8_t size) {
    int fd = pigpio_open(I2C_BUS, I2C_ADDRESS, I2C_TIMEOUT);
    if (fd < 0) {
        return -1;
    }

    pigpio_delay(2);
    pigpio_write(fd, I2C_SDA, 0);
    pigpio_write(fd, I2C_SCL, 1);
    pigpio_delay(1);
    pigpio_write(fd, I2C_SDA, 1);
    pigpio_delay(1);
    pigpio_write(fd, I2C_SCL, 0);
    pigpio_delay(1);

    int bytes_read = 0;
    for (uint8_t i = 0; i < size; i++) {
        pigpio_read(fd, I2C_SDA, &data[i], 1);
        pigpio_delay(1);
    }

    pigpio_write(fd, I2C_SCL, 0);
    pigpio_delay(1);
    pigpio_read(fd, I2C_SDA, &data[size], 1);
    pigpio_delay(1);
    pigpio_close(fd);
    return bytes_read;
}

// Function to check flow rate
bool check_flow_rate(float flow_rate) {
    return flow_rate >= 0.0 && flow_rate <= 100.0;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open file for writing
    int file_fd = open("cooling_log.csv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_fd < 0) {
        perror("open");
        return 1;
    }

    // Check if file exists and write header
    struct stat sb;
    if (fstat(file_fd, &sb) == 0 && !S_ISREG(sb.st_mode)) {
        fprintf(file_fd, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    while (1) {
        // Read from I2C
        uint8_t data[I2C_READ_SIZE];
        int bytes_read = read_i2c(data, I2C_READ_SIZE);
        if (bytes_read < 0) {
            pigpio_close(I2C_BUS);
            close(file_fd);
            return 1;
        }

        // Check CRC
        uint8_t crc = calculate_crc(data, I2C_READ_SIZE - 1);
        if (crc != data[I2C_READ_SIZE - 1]) {
            pigpio_close(I2C_BUS);
            close(file_fd);
            return 1;
        }

        // Extract flow rate
        int16_t flow_value = (int16_t)((data[0] << 8) | data[1]);
        float flow_rate = (float)flow_value / 100.0;

        // Check flow rate
        bool status = check_flow_rate(flow_rate);
        if (!status) {
            fprintf(file_fd, "%f,INVALID", flow_rate);
        } else {
            fprintf(file_fd, "%f,%f,%s", time(NULL), flow_rate, status ? "VALID" : "INVALID");
        }

        // Log to file
        if (ferror(file_fd)) {
            perror("fprintf");
            pigpio_close(I2C_BUS);
            close(file_fd);
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_close(I2C_BUS);
    close(file_fd);
    return 0;
}

