        if (bytes_read < 0) {
            pigpio_close(I2C_BUS);
            close(file_fd);
            return 1;
        }

        // Check CRC
        uint8_t crc = calculate_crc(data, I2C_READ_SIZE - 1);
        if (crc != data[I2C_READ_SIZE - 1]) {
            pigpio_close(I2C_BUS);
            close(file_fd);
            return 1;
        }

        // Extract flow rate
        int16_t flow_value = (int16_t)((data[0] << 8) | data[1]);
        float flow_rate = (float)flow_value / 100.0;

        // Check flow rate
        bool status = check_flow_rate(flow_rate);
        if (!status) {
            fprintf(file_fd, "%f,INVALID", flow_rate);
        } else {
            fprintf(file_fd, "%f,%f,%s", time(NULL), flow_rate, status ? "VALID" : "INVALID");
        }

        // Log to file
        if (ferror(file_fd)) {
            perror("fprintf");
            pigpio_close(I2C_BUS);
            close(file_fd);
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_close(I2C_BUS);
    close(file_fd);
    return 0;
}
