#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <syslog.h>

#define GPIO_chip 4
#define GPIO_line 23
#define GPIO_led 24
#define LOG_FILE "touch_log.txt"

int main(int argc, char *argv[]) {
    int gpio;
    int log_fd;
    struct timespec last_event;
    struct timespec sleep_time;
    struct timespec sleep_interval;
    struct timespec sleep_start;
    int ret;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        pigpio_close(gpio);
        return 1;
    }

    // Set up GPIO lines
    ret = pigpio_request_gpio(GPIO_chip, GPIO_line, GPIO_INPUT);
    if (ret < 0) {
        perror("pigpio_request_gpio");
        close(log_fd);
        pigpio_close(gpio);
        return 1;
    }

    ret = pigpio_request_gpio(GPIO_chip, GPIO_led, GPIO_OUTPUT);
    if (ret < 0) {
        perror("pigpio_request_gpio");
        pigpio_close(gpio);
        close(log_fd);
        return 1;
    }

    // Set GPIO line as active-high input
    ret = pigpio_set_mode(GPIO_chip, GPIO_line, PI_INPUT_PULL_UP);
    if (ret < 0) {
        perror("pigpio_set_mode");
        pigpio_close(gpio);
        close(log_fd);
        return 1;
    }

    // Set GPIO line as active-high output
    ret = pigpio_set_mode(GPIO_chip, GPIO_led, PI_OUTPUT);
    if (ret < 0) {
        perror("pigpio_set_mode");
        pigpio_close(gpio);
        close(log_fd);
        return 1;
    }

    ret = pigpio_set_level(GPIO_chip, GPIO_led, 0);
    if (ret < 0) {
        perror("pigpio_set_level");
        pigpio_close(gpio);
        close(log_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &last_event);

        // Wait for a rising edge on the GPIO line
        ret = pigpio_wait_for_edge(GPIO_chip, GPIO_line, PI_RISING, 1000);
        if (ret < 0) {
            perror("pigpio_wait_for_edge");
            pigpio_close(gpio);
            close(log_fd);
            return 1;
        }

        // Toggle the LED
        ret = pigpio_set_level(GPIO_chip, GPIO_led, 1);
        if (ret < 0) {
            perror("pigpio_set_level");
            pigpio_close(gpio);
            close(log_fd);
            return 1;
        }

        // Log the event
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char log_message[256];
        strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", time_info);
        log_message[ strlen(log_message) - 1 ] = '\n';
        log_message[ strlen(log_message) - 1 ] = '\0';
        ret = write(log_fd, log_message, strlen(log_message));
        if (ret < 0) {
            perror("write");
            pigpio_close(gpio);
            close(log_fd);
            return 1;
        }

        // Sleep for 1 second
        sleep_time.tv_sec = last_event.tv_sec + 1;
        sleep_time.tv_nsec = last_event.tv_nsec;
        ret = nanosleep(&sleep_time, NULL);
        if (ret < 0) {
            perror("nanosleep");
            pigpio_close(gpio);
            close(log_fd);
            return 1;
        }
    }

    // Clean up
    pigpio_close(gpio);
    close(log_fd);
    return 0;
}

