    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen() failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins
    ret = gpioSetupPullUpDowntime(GPIO17, PUD_DOWN);
    if (ret < 0) {
        fprintf(stderr, "gpioSetupPullUpDowntime() failed: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    ret = gpioSetupPullUpDowntime(GPIO18, PUD_DOWN);
    if (ret < 0) {
        fprintf(stderr, "gpioSetupPullUpDowntime() failed: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    ret = gpioModeGPIOOutput(GPIO17);
    if (ret < 0) {
        fprintf(stderr, "gpioModeGPIOOutput() failed: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    ret = gpioModeGPIOOutput(GPIO18);
    if (ret < 0) {
        fprintf(stderr, "gpioModeGPIOOutput() failed: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll the sensor
        ret = gpioRead(GPIO17);
        if (ret < 0) {
            fprintf(stderr, "gpioRead() failed: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
        if (ret == 0) {
            // Log entry
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
            // Buzzer on
            ret = gpioWrite(GPIO18, 1);
            if (ret < 0) {
                fprintf(stderr, "gpioWrite() failed: %s\n", strerror(errno));
                gpioTerminate();
                return 1;
            }
            // Wait for 2 seconds
            sleep(2);
            // Buzzer off
            ret = gpioWrite(GPIO18, 0);
            if (ret < 0) {
                fprintf(stderr, "gpioWrite() failed: %s\n", strerror(errno));
                gpioTerminate();
                return 1;
        } else {
            // Buzzer off
            ret = gpioWrite(GPIO18, 0);
            if (ret < 0) {
                fprintf(stderr, "gpioWrite() failed: %s\n", strerror(errno));
                gpioTerminate();
                return 1;
            }
        }
        // Wait for 500ms
        sleep(0.5);
    }

    // Log exit
    fclose(log_file);
    gpioTerminate();
    return 0;
}
