#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define GPIO4 4
#define GPIO17 17
#define DEBOUNCE_MS 200
#define LOG_FILE "touch_log.txt"

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO library\n");
        return 1;
    }

    // Set up GPIO4 as an input with a pull-up resistor
    if (gpioMode(GPIO4, GPIO_IN) < 0) {
        fprintf(stderr, "Error setting GPIO4 as input\n");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO17 as an output
    if (gpioMode(GPIO17, GPIO_OUT) < 0) {
        fprintf(stderr, "Error setting GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as a low
    if (gpioWrite(GPIO17, 0) < 0) {
        fprintf(stderr, "Error setting GPIO17 as low\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file for writing
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up a signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler for SIGINT\n");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler for SIGTERM\n");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read GPIO4
        int value = gpioRead(GPIO4);
        if (value == 0) {
            // Debounce
            struct timespec start_time;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (clock_gettime(CLOCK_MONOTONIC, &start_time).tv_sec == start_time.tv_sec && clock_gettime(CLOCK_MONOTONIC, &start_time).tv_nsec < start_time.tv_nsec + DEBOUNCE_MS * 1000000) {
                // Do nothing
            }
            if (clock_gettime(CLOCK_MONOTONIC, &start_time).tv_sec == start_time.tv_sec && clock_gettime(CLOCK_MONOTONIC, &start_time).tv_nsec >= start_time.tv_nsec + DEBOUNCE_MS * 1000000) {
                // Write to log file
                struct tm* now = localtime(&clock_gettime(CLOCK_MONOTONIC).tv_sec);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now);
                char log_line[256];
                sprintf(log_line, "%s %s\n", timestamp, "TOUCH");
                if (write(log_fd, log_line, strlen(log_line)) < 0) {
                    fprintf(stderr, "Error writing to log file %s\n", LOG_FILE);
                }
            }
        }
        // Toggle GPIO17
        gpioWrite(GPIO17, !value);
    }

    // Clean up
    gpioTerminate();
    close(log_fd);
    return 0;
}

void sigint_handler(int sig) {
    // Turn off the LED
    gpioWrite(GPIO17, 0);
    // Close the log file
    close(LOG_FILE);
    // Exit
    exit(0);
}

