#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "magnet_log.txt"
#define POLL_INTERVAL 100
#define MAX_LOG_LINES 1000

// Define structures
typedef struct {
    int pin;
    int pull_up;
    int last_state;
} sensor_t;

// Define the sensors
sensor_t sensors[] = {
    {GPIO4, PI_INPUT_PUD_UP, -1},
    {GPIO17, PI_INPUT_PUD_UP, -1},
    {GPIO27, PI_INPUT_PUD_UP, -1}
};

// Define the log file
FILE *log_file;

// Define the signal handlers
void sigint_handler(int sig) {
    fclose(log_file);
    pigpio_close_all();
    exit(0);
}

void sigterm_handler(int sig) {
    fclose(log_file);
    pigpio_close_all();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (pigpio_init() < 0) {
        fprintf(stderr, "Error initializing GPIO library\n");
        return 1;
    }

    // Set up the sensors
    for (int i = 0; i < 3; i++) {
        if (pigpio_mode(sensors[i].pin, sensors[i].pull_up) < 0) {
            fprintf(stderr, "Error setting GPIO mode for sensor %d\n", sensors[i].pin);
            return 1;
        }
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize the sensors
    for (int i = 0; i < 3; i++) {
        int state = pigpio_read(sensors[i].pin);
        if (state == -1) {
            fprintf(stderr, "Error reading sensor %d\n", sensors[i].pin);
            return 1;
        }
        if (sensors[i].last_state == -1) {
            sensors[i].last_state = state;
        }
    }

    // Main loop
    while (1) {
        // Poll the sensors
        for (int i = 0; i < 3; i++) {
            int state = pigpio_read(sensors[i].pin);
            if (state == -1) {
                fprintf(stderr, "Error reading sensor %d\n", sensors[i].pin);
                continue;
            }
            if (sensors[i].last_state == -1) {
                sensors[i].last_state = state;
                continue;
            }
            if (state != sensors[i].last_state) {
                // Log the state change
                time_t now = time(NULL);
                struct tm *time_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
                fprintf(log_file, "%s %d %s\n", timestamp, sensors[i].pin, state == 0 ? "magnet-present" : "magnet-removed");
                sensors[i].last_state = state;
            }
        }
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    pigpio_close_all();
    fclose(log_file);
    return 0;
}

