#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/statvfs.h>

// Define constants
#define GPIO_PIN 17
#define GPIO_MODE_INPUT
#define GPIO Pull_UP
#define FILE_NAME "flame_log.txt"

// Define the signal handler
void sigint_handler(int sig) {
    gpioClose(GPIO);
    close(gpio_fd);
    close(log_fd);
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the log file
    log_fd = open(FILE_NAME, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioClose(GPIO);
        return 1;
    }

    // Set up the GPIO pin
    gpio_fd = gpioGetFd(GPIO_PIN);
    if (gpio_fd < 0) {
        perror("gpioGetFd");
        close(log_fd);
        gpioClose(GPIO);
        return 1;
    }

    // Set the GPIO pin as input with internal pull-up
    if (gpioMode(GPIO_PIN, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        close(log_fd);
        gpioClose(GPIO);
        return 1;
    }

    // Set the GPIO pin as an interrupt
    if (gpioSetActiveEdge(GPIO_PIN, GPIO_EDGE_FALLING) < 0) {
        perror("gpioSetActiveEdge");
        close(log_fd);
        gpioClose(GPIO);
        return 1;
    }

    // Install the signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Poll the GPIO pin
        int value = gpioRead(GPIO_PIN);
        if (value == 0) {
            // Write to the log file
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s FLAME DETECTED\n", timestamp);
            fflush(log_fd);
        }
        usleep(100000);
    }

    // Clean up
    gpioClose(GPIO);
    close(log_fd);
    return 0;
}

