#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_BASE 17
#define GPIO_OUTPUT 24
#define GPIO_INPUTS 8
#define DELAY 200
#define POLL_INTERVAL 10
#define LOG_FILE "touch_log.txt"

int main() {
    int gpio;
    int i;
    int status;
    struct timespec delay;
    struct timespec start;
    struct timespec end;
    struct timespec sleep;
    struct stat sb;
    struct stat sb_log;
    char log_file_path[256];
    char log_line[256];
    char channel[10];
    char counter[10];
    char output[10];

    // Initialize GPIO
    gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO 17 as output
    gpio = gpioSetupMode(GPIO_BASE, GPIO_OUTPUT);
    if (gpio < 0) {
        perror("gpioSetupMode");
        gpioTerminate();
        return 1;
    }

    // Set GPIO 24 as output
    gpio = gpioSetupMode(GPIO_BASE + GPIO_OUTPUT, GPIO_OUTPUT);
    if (gpio < 0) {
        perror("gpioSetupMode");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file_path[0] = '\0';
    if (snprintf(log_file_path, sizeof(log_file_path), "%s", LOG_FILE) < 0) {
        perror("snprintf");
        gpioTerminate();
        return 1;
    }
    if (stat(log_file_path, &sb) != 0) {
        if (mkdir(log_file_path, S_IRUSR | S_IWUSR) < 0) {
            perror("mkdir");
            gpioTerminate();
            return 1;
        }
    }
    if (fopen(log_file_path, "a") < 0) {
        warn("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Start timer
    clock_gettime(CLOCK_REALTIME, &start);

    while (1) {
        // Delay
        sleep(&delay);
        delay.tv_sec = DELAY;
        delay.tv_nsec = 0;

        // Wait for stabilization
        clock_gettime(CLOCK_REALTIME, &end);
        while (end.tv_sec != start.tv_sec || end.tv_nsec != start.tv_nsec) {
            sleep(&delay);
            clock_gettime(CLOCK_REALTIME, &end);
        }

        // Reset GPIO 17
        gpio = gpioSetupMode(GPIO_BASE, GPIO_INPUT);
        if (gpio < 0) {
            perror("gpioSetupMode");
            gpioTerminate();
            return 1;
        }

        // Read GPIO inputs
        for (i = 0; i < GPIO_INPUTS; i++) {
            gpio = gpioRead(GPIO_BASE + i);
            if (gpio < 0) {
                perror("gpioRead");
                gpioTerminate();
                return 1;
            }
            if (gpio == 0) {
                // Increment counter
                gpio = gpioWrite(GPIO_BASE, 255);
                if (gpio < 0) {
                    perror("gpioWrite");
                    gpioTerminate();
                    return 1;
                }
                sprintf(channel, "%d", i + 1);
                sprintf(counter, "%d", (gpioRead(GPIO_BASE + GPIO_OUTPUT) & 0xFF) + 1);
