#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define LOG_FILE "/var/log/tilt_events.log"
#define DEBOUNCE_WINDOW_MS 50
#define POLL_INTERVAL_MS 100

// Structure to hold sensor information
typedef struct {
    int gpio;
    int pull_up;
    int debounce;
    int last_state;
} sensor_t;

// Global variables
sensor_t sensors[2];
int log_fd;

// Function to initialize the GPIO pins
void init_gpio() {
    int ret;
    for (int i = 0; i < 2; i++) {
        sensors[i].gpio = gpioGetConsecutive(i);
        if (sensors[i].gpio == -1) {
            syslog(LOG_ERR, "Failed to get GPIO %d\n", i);
            exit(1);
        }
        gpioSetMode(sensors[i].gpio, GPIO_IN);
        gpioSetPullUpDnLevel(sensors[i].gpio, GPIO_PUD_DOWN);
    }
}

// Function to read sensor values
void read_sensors() {
    int ret;
    for (int i = 0; i < 2; i++) {
        ret = gpioRead(sensors[i].gpio);
        if (ret == -1) {
            syslog(LOG_ERR, "Failed to read GPIO %d\n", sensors[i].gpio);
            continue;
        }
        if (sensors[i].last_state == 0 && ret == 1) {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            syslog(LOG_INFO, "%s, Sensor %d tilted\n", timestamp, i + 1);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                syslog(LOG_ERR, "Failed to open log file\n");
                continue;
            }
            fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, i + 1);
            fclose(log_file);
        }
        sensors[i].last_state = ret;
    }
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    for (int i = 0; i < 2; i++) {
        gpioWrite(sensors[i].gpio, 0);
    }
    close(log_fd);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGINT handler\n");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler\n");
        exit(1);
    }

    init_gpio();

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file\n");
        exit(1);
    }

    while (1) {
        read_sensors();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

