#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define LOG_FILE "obstacle_log.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO17, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO27, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO22, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO22, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up timer
    struct itimerval timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 100;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 100;
    if (setitimer(ITIMER_REAL, &timer, &timer) < 0) {
        perror("setitimer");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read sensor values
        int sensor1 = gpioGet(GPIO17);
        int sensor2 = gpioGet(GPIO27);

        // Check for obstacles
        if (sensor1 == 0 && sensor2 == 0) {
            gpioWrite(GPIO22, 1);
        } else {
            gpioWrite(GPIO22, 0);
        }

        // Log data
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, gpioRead(GPIO22));
        fflush(log_fd);

        // Check for SIGINT
        if (killpg(0, SIGINT) == -1) {
            break;
        }
    }

    // Clean up
    close(log_fd);
    gpioTerminate();
    return 0;
}

