#define GPIO_PIN 4  // GPIO pin for ICS-40180 analog MEMS microphone
#define GPIO_LED 17  // GPIO pin for LED
#define LED_RESISTOR 1k  // Current-limiting resistor value (1kΩ)
#define SAMPLE_RATE 8000  // Sampling rate in Hz
#define SAMPLE_PERIOD 125  // Sampling period in microseconds
#define LED_DURATION 100  // LED duration in milliseconds
#define LED_BRIGHTNESS 0.5  // LED brightness (0.0 to 1.0)

// Define volatile sig_atomic_t flag
volatile sig_atomic_t peak_detected = 0;

// Define signal handler
void signal_handler(int sig) {
    // Cleanly stop the sampling loop
    gpioWrite(GPIO_LED, 0);
    gpioCleanse(GPIO_LED);
    pigpio_shutdown();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (pigpioInit() < 0) {
        fprintf(stderr, "Error initializing GPIO library\n");
        exit(1);
    }

    // Set up the GPIO pin as an input with a pull-up resistor
    if (gpioMode(GPIO_PIN, GPIO_INPUT) < 0) {
        fprintf(stderr, "Error setting up GPIO pin %d as input\n", GPIO_PIN);
        exit(1);
    }
    if (gpioPullUpDn(GPIO_PIN, GPIO_PULLUP_DISABLE) < 0) {
        fprintf(stderr, "Error disabling pull-up resistor on GPIO pin %d\n", GPIO_PIN);
        exit(1);
    }

    // Set up the LED pin as an output
    if (gpioMode(GPIO_LED, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting up GPIO pin %d as output\n", GPIO_LED);
        exit(1);
    }
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Error setting up GPIO pin %d as output\n", GPIO_LED);
        exit(1);
    }

    // Set the LED brightness
    if (gpioWrite(GPIO_LED, (uint32_t)(LED_BRIGHTNESS * 1000)) < 0) {
        fprintf(stderr, "Error setting LED brightness\n");
        exit(1);
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);

    // Start the sampling loop
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = (long long)(SAMPLE_PERIOD * 1000);
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = (long long)(SAMPLE_PERIOD * 1000);
    if (nanosleep(&timer, NULL) < 0) {
        fprintf(stderr, "Error starting sampling loop\n");
        exit(1);
    }

    while (1) {
        // Read the GPIO pin value
        int value = gpioRead(GPIO_PIN);
        if (value == 1) {
            // Detect a peak
            printf("%d\n", (long long)times(NULL));
            peak_detected = 1;
        }

        // Turn on the LED if a peak is detected
        if (peak_detected) {
            if (gpioWrite(GPIO_LED, 1) < 0) {
                fprintf(stderr, "Error turning on LED\n");
                exit(1);
            }
            sleep_ms(LED_DURATION);
            if (gpioWrite(GPIO_LED, 0) < 0) {
                fprintf(stderr, "Error turning off LED\n");
                exit(1);
            }
        }

        // Sleep for the sampling period
        if (nanosleep(&timer, NULL) < 0) {
            fprintf(stderr, "Error sleeping\n");
            exit(1);
        }
    }

    // Cleanly shut down the GPIO library
    gpioCleanse(GPIO_LED);
    pigpio_shutdown();
    exit(0);
}

