#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_ADDRESS 0x4A
#define I2C_CLOCK_SPEED 100000
#define I2C_BUFFER_SIZE 2

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(17, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(23, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open I2C interface
    if (i2cInit(1, I2C_CLOCK_SPEED) < 0) {
        perror("i2cInit");
        gpioTerminate();
        return 1;
    }

    // Register I2C callbacks
    i2cRegisterCallback(1, i2cCallback);

    // Main loop
    while (1) {
        // Read ALS data
        uint8_t data[2];
        if (i2cRead(I2C_ADDRESS, 0x00, data, I2C_BUFFER_SIZE) < 0) {
            perror("i2cRead");
            continue;
        }

        // Combine LSB and MSB into a single 16-bit raw value
        uint16_t raw_value = (data[0] << 8) | data[1];

        // Log raw sensor reading
        printf("Raw ALS reading: 0x%04x\n", raw_value);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    i2cClose(1);
    gpioTerminate();
    return 0;
}

void i2cCallback(int fd, void *user_data) {
    struct i2c_callback_data *data = (struct i2c_callback_data *)user_data;
    if (data->error) {
        printf("I2C error: %s\n", data->error);
    }
}

