    // Close all GPIO devices
    gpioClose(GPIO_LEFT);
    gpioClose(GPIO_MIDDLE);
    gpioClose(GPIO_RIGHT);

    // Exit the program
    exit(0);
}

int main() {
    // Install the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Open the GPIO devices
    if (gpioSetup(GPIO_LEFT, GPIO_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", GPIO_LEFT);
        gpioTerminate();
        return 1;
    }
    if (gpioSetup(GPIO_MIDDLE, GPIO_INPUT) < 0) {
