        gpioClose(GPIO_LEFT);
        gpioTerminate();
        return 1;
    }
    if (gpioSetup(GPIO_RIGHT, GPIO_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", GPIO_RIGHT);
        gpioClose(GPIO_MIDDLE);
        gpioClose(GPIO_LEFT);
        gpioTerminate();
        return 1;
