            printf("%s:%d | %s:%d | %s:%d\n", LEFT_NAME, left_value, MIDDLE_NAME, middle_value, RIGHT_NAME, right_value);
        } else {
            printf("Unknown sensor value\n");
        }

        // Sleep for 100ms
        usleep(100000);
