#include <pigpio.h>
#include <sys/types.h>
#include <signal.h>

#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define NUM_STEPS 50
#define TRANSITION_TIME 5

int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver");
        return 1;
    }

    // Set up the LED pins as output
    if (gpioSetMode(LED_RED, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set LED pin as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_GREEN, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set LED pin as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_BLUE, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set LED pin as output");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set up the PWM
    if (gpioPWM(LED_RED, GPIO PWM_MODE PWM, 1000, 0, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM on LED pin");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(LED_GREEN, GPIO PWM_MODE PWM, 1000, 0, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM on LED pin");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(LED_BLUE, GPIO PWM_MODE PWM, 1000, 0, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM on LED pin");
        gpioTerminate();
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handler");
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handler");
        gpioTerminate();
        return 1;
    }

    // Main loop
    int hue = rand() % 256;
    int step = 0;
    int start_time = time(NULL);
    while (time(NULL) - start_time < TRANSITION_TIME) {
        int red = (hue + step * (255 / NUM_STEPS)) % 256;
        int green = (hue + step * (255 / NUM_STEPS)) % 256;
        int blue = (hue + step * (255 / NUM_STEPS)) % 256;
        gpioPWM(LED_RED, GPIO PWM_SET, red);
        gpioPWM(LED_GREEN, GPIO PWM_SET, green);
        gpioPWM(LED_BLUE, GPIO PWM_SET, blue);
        step++;
        usleep(10000);
    }

    // Clean up
    gpioTerminate();
    syslog(LOG_INFO, "LED transition complete");
    return 0;
}

void sigint_handler(int sig) {
    gpioPWM(LED_RED, GPIO PWM_SET, 0);
    gpioPWM(LED_GREEN, GPIO PWM_SET, 0);
    gpioPWM(LED_BLUE, GPIO PWM_SET, 0);
    syslog(LOG_INFO, "Received SIGINT, shutting down");
    exit(0);
}

void sigterm_handler(int sig) {
    gpioPWM(LED_RED, GPIO PWM_SET, 0);
    gpioPWM(LED_GREEN, GPIO PWM_SET, 0);
    gpioPWM(LED_BLUE, GPIO PWM_SET, 0);
    syslog(LOG_INFO, "Received SIGTERM, shutting down");
    exit(0);
}

