#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x23
#define LED_COUNT 60
#define LED_DATA_SIZE (LED_COUNT * 3)
#define LED_FRAME_SIZE (LED_DATA_SIZE + 4)
#define SPI_SPEED 1000000
#define DELAY 120

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open SPI device
    int spidev_fd = open("/dev/spidev0.0", O_RDWR | O_NONBLOCK);
    if (spidev_fd < 0) {
        perror("open");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spidev_fd, SPI_IOC_SET_MODE, SPI_MODE0) < 0) {
        perror("ioctl");
        close(i2c_fd);
        close(spidev_fd);
        gpioTerminate();
        return 1;
    }
    if (ioctl(spidev_fd, SPI_IOC_SETClock, SPI_CLOCK_PCLK1) < 0) {
        perror("ioctl");
        close(i2c_fd);
        close(spidev_fd);
        gpioTerminate();
        return 1;
    }

    // Open APA102 LED strip
    int led_fd = open("/dev/spidev0.0", O_RDWR | O_NONBLOCK);
    if (led_fd < 0) {
        perror("open");
        close(i2c_fd);
        close(spidev_fd);
        gpioTerminate();
        return 1;
    }

    // Set APA102 mode
    if (ioctl(led_fd, SPI_IOC_SET_MODE, SPI_MODE0) < 0) {
        perror("ioctl");
        close(i2c_fd);
        close(spidev_fd);
        close(led_fd);
        gpioTerminate();
        return 1;
    }

    // Set APA102 clock
    if (ioctl(led_fd, SPI_IOC_SETClock, SPI_CLOCK_PCLK1) < 0) {
        perror("ioctl");
        close(i2c_fd);
        close(spidev_fd);
        close(led_fd);
        gpioTerminate();
        return 1;
    }

    // Read ambient light level
    uint16_t light_level;
    if (read(i2c_fd, &light_level, sizeof(light_level)) != sizeof(light_level)) {
        perror("read");
        close(i2c_fd);
        close(spidev_fd);
        close(led_fd);
        gpioTerminate();
        return 1;
    }

    // Scale brightness
    float brightness = (light_level / 4096.0f) * 255.0f;

    // Create APA102 frame
    uint8_t frame[LED_FRAME_SIZE];
    memset(frame, 0, LED_FRAME_SIZE);

    // Set LED data
    for (int i = 0; i < LED_COUNT; i++) {
        int led_fd = open("/dev/spidev0.0", O_RDWR | O_NONBLOCK);
        if (led_fd < 0) {
            perror("open");
            close(i2c_fd);
            close(spidev_fd);
            close(led_fd);
            gpioTerminate();
            return 1;
        }

        // Set LED data
        if (write(led_fd, &frame[i * 3], 3) != 3) {
            perror("write");
            close(i2c_fd);
            close(spidev_fd);
            close(led_fd);
            gpioTerminate();
            return 1;
        }

        // Wait for SPI transfer to complete
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 1000000;
        nanosleep(&delay, NULL);
    }

    // Set end frame
    if (write(led_fd, &frame[LED_COUNT * 3], 4) != 4) {
        perror("write");
        close(i2c_fd);
        close(spidev_fd);
        close(led_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for SPI transfer to complete
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 1000000;
    nanosleep(&delay, NULL);

    // Clean up
    close(i2c_fd);
    close(spidev_fd);
    close(led_fd);
    gpioTerminate();

    return 0;
