#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/signal.h>
#include <unistd.h>

#define I2C_ADDRESS_1 0x38
#define I2C_ADDRESS_2 0x39
#define I2C_ADDRESS_3 0x3A
#define LED_PIN MOSI 10
#define LED_CLOCK 11
#define LED_COUNT 16
#define LED_BRIGHTNESS 255

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(LED_PIN, PI_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioSetClock(LED_CLOCK, PI_HIGH) < 0) {
        perror("gpioSetClock");
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open I2C handles
    int i2c1 = i2cOpen(1, I2C_ADDRESS_1, 0);
    int i2c2 = i2cOpen(1, I2C_ADDRESS_2, 0);
    int i2c3 = i2cOpen(1, I2C_ADDRESS_3, 0);

    if (i2c1 < 0) {
        printf("Failed to open I2C handle 1\n");
        i2c1 = -1;
    }
    if (i2c2 < 0) {
        printf("Failed to open I2C handle 2\n");
        i2c2 = -1;
    }
    if (i2c3 < 0) {
        printf("Failed to open I2C handle 3\n");
        i2c3 = -1;
    }

    // Main loop
    while (1) {
        int sum = 0;
        int count = 0;

        // Read from I2C handles
        if (i2c1 >= 0) {
            uint16_t result1 = i2cRead(i2c1, 0x00, 2);
            if (result1 == 0xFFFF) {
                printf("BH1750 sensor 1 not found\n");
            } else {
                sum += result1;
                count++;
            }
        }
        if (i2c2 >= 0) {
            uint16_t result2 = i2cRead(i2c2, 0x00, 2);
            if (result2 == 0xFFFF) {
                printf("BH1750 sensor 2 not found\n");
            } else {
                sum += result2;
                count++;
            }
        }
        if (i2c3 >= 0) {
            uint16_t result3 = i2cRead(i2c3, 0x00, 2);
            if (result3 == 0xFFFF) {
                printf("BH1750 sensor 3 not found\n");
            } else {
                sum += result3;
                count++;
            }
        }

        // Calculate average
        if (count > 0) {
            float average = (float)sum / count;
            int brightness = (int)(average * LED_BRIGHTNESS);
