#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define I2C_ADDRESS 0x5A
#define GPIO_PIN 18
#define LED_PIN GPIO_PIN
#define LED_COUNT 60
#define I2C_TIMEOUT 100
#define MAX_RETRIES 3
#define LED_BRIGHTNESS_MAX 255
#define LED_BRIGHTNESS_MIN 0

int main() {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C file descriptor
    int fd = pigpio_i2c_open(I2C_ADDRESS, 0, 100);
    if (fd < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    // Set up GPIO pin as output
    if (pigpio_mode(GPIO_PIN, PI_OUTPUT) < 0) {
        perror("pigpio_mode");
        return 1;
    }

    // Set up LED pin as output
    if (pigpio_mode(LED_PIN, PI_OUTPUT) < 0) {
        perror("pigpio_mode");
        return 1;
    }

    while (1) {
        // Read ambient light from VEML7700
        unsigned char data[2];
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (pigpio_i2c_read(fd, data, 2, I2C_TIMEOUT) < 0) {
                if (retries < MAX_RETRIES - 1) {
                    usleep(100000);
                    retries++;
                } else {
                    perror("pigpio_i2c_read");
                    break;
                }
            } else {
                break;
            }
        }

        if (retries >= MAX_RETRIES) {
            printf("Failed to read from I2C device\n");
            continue;
        }

        // Extract lux value from data
        unsigned int lux = (data[0] << 8) | data[1];

        // Apply gamma-corrected scaling
        unsigned int brightness = (lux / 1000) * LED_BRIGHTNESS_MAX;

        // Limit brightness to valid range
        brightness = (brightness < LED_BRIGHTNESS_MIN) ? LED_BRIGHTNESS_MIN : (brightness > LED_BRIGHTNESS_MAX) ? LED_BRIGHTNESS_MAX : brightness;

        // Bit-bang LED strip
        unsigned char led_data[LED_COUNT];
        for (int i = 0; i < LED_COUNT; i++) {
            led_data[i] = (brightness >> (LED_COUNT - 1 - i)) & 1;
        }
        pigpio_write(LED_PIN, led_data, LED_COUNT);

        // Print current lux reading and brightness value
        printf("%u %u\n", lux, brightness);

        // Pause for 200ms
        usleep(200000);
    }

    // Release resources
    pigpio_close(fd);
    pigpio_i2c_close(fd);
    pigpio_cleanup();
    return 0;
}

void sigint_handler(int sig) {
    pigpio_close(GPIO_PIN);
    pigpio_close(LED_PIN);
    exit(0);
}

void sigterm_handler(int sig) {
    pigpio_close(GPIO_PIN);
    pigpio_close(LED_PIN);
    pigpio_i2c_close(I2C_ADDRESS);
    exit(0);
}

