#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-registers.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <string.h>

#define BUFFER_SIZE 60
#define LED_GPIO 17
#define I2C_ADDRESS 0x38
#define I2C_FILE "/dev/i2c-1"

int main() {
    int fd, i, j, ret, lux;
    unsigned long sum = 0;
    unsigned long min = 0;
    unsigned long max = 0;
    unsigned long min_index = 0;
    unsigned long max_index = 0;
    struct timespec start;
    struct timespec end;
    struct timespec interval;
    struct timespec sleep_time;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize GPIO
    if (gpio_export(LED_GPIO) < 0) {
        perror("gpio_export");
        return 1;
    }
    if (gpio_mode(LED_GPIO, GPIO_MODE_OUTPUT) < 0) {
        perror("gpio_mode");
        return 1;
    }
    if (gpio_firmata(LED_GPIO) < 0) {
        perror("gpio_firmata");
        return 1;
    }

    // Initialize I2C
    if ((fd = open(I2C_FILE, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        ret = i2c_read(fd, 0x00, 2, NULL, NULL);
        if (ret < 0) {
            perror("i2c_read");
            continue;
        }
        lux = (ret >> 8) & 0xFF;
        if (lux > 1000) {
            lux = 1000;
        }
        if (lux < 0) {
            lux = 0;
        }

        // Update buffer
        if (sum >= BUFFER_SIZE) {
            sum -= min;
            min_index = (min_index + 1) % BUFFER_SIZE;
            sum = sum - min;
            max = max - min;
            max_index = (max_index + 1) % BUFFER_SIZE;
            min = sum;
            max = sum + lux;
            max_index = (max_index + 1) % BUFFER_SIZE;
        } else {
            sum += lux;
            min = min < lux ? lux : min;
            max = max > lux ? lux : max;
            min_index = min_index < BUFFER_SIZE - 1 ? min_index + 1 : 0;
            max_index = max_index < BUFFER_SIZE - 1 ? max_index + 1 : 0;
        }

        // Update interval
        if (sum > 0) {
            interval.tv_sec = (unsigned long)(time(NULL) - start.tv_sec);
            interval.tv_nsec = (unsigned long)(time(NULL) - start.tv_sec) * 1e9 - start.tv_nsec;
            if (interval.tv_sec < 0) {
                interval.tv_sec = 0;
                interval.tv_nsec = 0;
            }
            interval.tv_sec = interval.tv_sec < 1 ? 1 : interval.tv_sec;
            interval.tv_nsec = interval.tv_nsec < 100000000 ? interval.tv_nsec : 100000000;
        } else {
            interval.tv_sec = 0;
            interval.tv_nsec = 0;
        }

        // Sleep
        nanosleep(&interval, NULL);

        // Update LED
        if (interval.tv_sec > 0) {
            gpio_write(LED_GPIO, 1);
            sleep_time.tv_sec = interval.tv_sec;
            sleep_time.tv_nsec = interval.tv_nsec;
            nanosleep(&sleep_time, NULL);
            gpio_write(LED_GPIO, 0);
            sleep_time.tv_sec = interval.tv_sec;
            sleep_time.tv_nsec = interval.tv_nsec;
            nanosleep(&sleep_time, NULL);
        } else {
            gpio_write(LED_GPIO, 0);
        }

        // Print average
        if (sum > 0) {
            printf("%.2f lux\n", (double)sum / BUFFER_SIZE);
        }

        // Check for dark
        if (lux < 100) {
            interval.tv_sec = 0;
            interval.tv_nsec = 0;
            nanosleep(&interval, NULL);
            gpio_write(LED_GPIO, 0);
            sleep_time.tv_sec = interval.tv_sec;
            sleep_time.tv_nsec = interval.tv_nsec;
            nanosleep(&sleep_time, NULL);
            gpio_write(LED_GPIO, 1);
            sleep_time.tv_sec = interval.tv_sec;
            sleep_time.tv_nsec = interval.tv_nsec;
            nanosleep(&sleep_time, NULL);
        }
    }

    // Clean up
    gpio_firmata(LED_GPIO);
    close(fd);
    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    gpio_firmata(LED_GPIO);
    close(fd);
    exit(0);
}

