    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO17, GPIO18, and GPIO27 as outputs
    if (gpioMode(GPIO17, GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(GPIO18, GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set GPIO18 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(GPIO27, GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set GPIO27 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO22 and GPIO23 as inputs
    if (gpioMode(GPIO22, GPIO_MODE_INPUT) < 0) {
        printf("Failed to set GPIO22 as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(GPIO23, GPIO_MODE_INPUT) < 0) {
        printf("Failed to set GPIO23 as input\n");
        gpioTerminate();
        return 1;
    }

    // Define the 74HC595 segment mapping
    const uint8_t segments[] = {0b01100000, 0b11010010, 0b11011010, 0b11110010, 0b11100101, 0b01101101, 0b01101100, 0b01100111};

    // Define the 74HC595 latch mapping
    const uint8_t latch[] = {0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000};

    // Define the 74HC595 display pattern for digit '5'
    const uint8_t pattern[] = {0b01111001};

    // Main loop
    while (1) {
        // Clear the latch
        if (gpioWrite(GPIO27, 0) < 0) {
            printf("Failed to clear latch\n");
            break;
        }

        // Shift out the pattern
        uint8_t shift = 0;
        for (int i = 0; i < 8; i++) {
            // Set the data line
            if (gpioWrite(GPIO17, (pattern[shift] >> (7 - i)) & 1) < 0) {
                printf("Failed to set data line\n");
                break;
            }

            // Set the clock line
            if (gpioWrite(GPIO18, 1) < 0) {
                printf("Failed to set clock line\n");
                break;
            }

            // Wait for the clock pulse
            usleep(10);

            // Latch the data
            if (gpioWrite(GPIO27, 1) < 0) {
                printf("Failed to latch data\n");
                break;
            }

            // Wait for the latch pulse
            usleep(10);

            shift++;
        }

        // Wait for the next period
        usleep(500000);

        // Clear the latch
        if (gpioWrite(GPIO27, 0) < 0) {
            printf("Failed to clear latch\n");
            break;
        }

        // Shift out the pattern
        shift = 0;
        for (int i = 0; i < 8; i++) {
            // Set the data line
            if (gpioWrite(GPIO17, (pattern[shift] >> (7 - i)) & 1) < 0) {
                printf("Failed to set data line\n");
                break;
            }

            // Set the clock line
            if (gpioWrite(GPIO18, 1) < 0) {
                printf("Failed to set clock line\n");
                break;
            }

            // Wait for the clock pulse
            usleep(10);

            // Latch the data
            if (gpioWrite(GPIO27, 1) < 0) {
                printf("Failed to latch data\n");
                break;
            }

            // Wait for the latch pulse
            usleep(10);

            shift++;
        }

        // Wait for the next period
        usleep(500000);
    }

    // Release GPIO lines
    if (gpioWrite(GPIO17, 0) < 0) {
        printf("Failed to release GPIO17\n");
    }
    if (gpioWrite(GPIO18, 0) < 0) {
        printf("Failed to release GPIO18\n");
    }
    if (gpioWrite(GPIO27, 0) < 0) {
        printf("Failed to release GPIO27\n");
    }
    if (gpioWrite(GPIO22, 0) < 0) {
        printf("Failed to release GPIO22\n");
    }
    if (gpioWrite(GPIO23, 0) < 0) {
        printf("Failed to release GPIO23\n");
    }

    // Clean up
    gpioTerminate();
    return 0;
}

