#include <pigpio.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define LED_VALUE_HIGH 1
#define LED_VALUE_LOW 0
#define DELAY_MS 500

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the LED pin as an output
    if (gpioMode(LED_PIN, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Set the initial LED value to low
    if (gpioWrite(LED_PIN, LED_VALUE_LOW) < 0) {
        fprintf(stderr, "Failed to set up LED pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up the button pin as an input with pull-down
    if (gpioMode(BUTTON_PIN, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "Failed to set up button pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPullUp(BUTTON_PIN, PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set up button pin with pull-down\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the button state
        int button_state = gpioRead(BUTTON_PIN);
        if (button_state == 0) {
            // Button is pressed
            gpioWrite(LED_PIN, LED_VALUE_HIGH);
            sleep(DELAY_MS / 1000.0);
            gpioWrite(LED_PIN, LED_VALUE_LOW);
        } else {
            // Button is released
            gpioWrite(LED_PIN, LED_VALUE_LOW);
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

