#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>

#define I2C_ADDRESS 0x1D
#define I2C Bus 1
#define GPIO_PIN 17
#define THRESHOLD 2.0

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    struct timespec last_read;
    struct timespec interval;
    struct timespec sleep_time;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec duration;
    struct timespec interval_time;
    int threshold;
    int ret;
    int i;
    int error;
    int status;
    char filename[256];

    // Initialize GPIO
    gpio_init();
    gpio_set_mode(GPIO_PIN, PI_OUTPUT);

    // Set up I2C
    i2c_init(I2C Bus, I2C_ADDRESS);

    // Set up logging
    syslog_setlogmask(LOG_PID);
    syslog_openlog("impact_logger", LOG_PID, LOG_INFO);

    // Parse command-line argument
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            syslog(LOG_ERR, "Invalid threshold value");
            return 1;
        }
    } else {
        threshold = THRESHOLD;
    }

    // Initialize variables
    last_read.tv_sec = 0;
    last_read.tv_nsec = 0;
    interval.tv_sec = 0;
    interval.tv_nsec = 0;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 0;
    start_time.tv_sec = 0;
    start_time.tv_nsec = 0;
    end_time.tv_sec = 0;
    end_time.tv_nsec = 0;
    duration.tv_sec = 0;
    duration.tv_nsec = 0;
    interval_time.tv_sec = 0;
    interval_time.tv_nsec = 0;

    // Main loop
    while (1) {
        // Read accelerometer data
        ret = i2c_read(I2C Bus, I2C_ADDRESS, 6, NULL, NULL);
        if (ret < 0) {
            syslog(LOG_ERR, "I2C read error");
            break;
        }
        if (ret != 6) {
            syslog(LOG_ERR, "Unexpected number of bytes read");
            break;
        }
        uint8_t data[6];
        memcpy(data, NULL, ret);
        if (data[0] != 0x0D) {
            syslog(LOG_ERR, "Invalid accelerometer data");
            break;
        }
        uint16_t x = (data[1] << 8) | data[2];
        uint16_t y = (data[3] << 8) | data[4];
        uint16_t z = (data[5] << 8) | data[6];

        // Calculate G-force magnitude
        double g_force = sqrt((double)x * x + (double)y * y + (double)z * z) / 16384.0;

        // Check if threshold exceeded
        if (g_force > threshold) {
            // Trigger impact interrupt
            gpio_fd = gpio_get_fd(GPIO_PIN);
            if (gpio_fd < 0) {
                syslog(LOG_ERR, "Failed to get GPIO file descriptor");
                break;
            }
            if (gpio_write(gpio_fd, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO pin high");
                break;
            }
            usleep(50 * 1000);
            if (gpio_write(gpio_fd, 0) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO pin low");
                break;
            }
        }

        // Log data
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", localtime(&start_time));
        FILE *log_file = fopen("impact_log.txt", "a");
        if (log_file == NULL) {
            syslog(LOG_ERR, "Failed to open log file");
            break;
        }
        fprintf(log_file, "%s %f %f %f %f\n", timestamp, x, y, z, g_force);
        fclose(log_file);

        // Update last read time
        last_read.tv_sec = start_time.tv_sec;
        last_read.tv_nsec = start_time.tv_nsec;

        // Calculate interval
        interval.tv_sec = last_read.tv_sec - start_time.tv_sec;
        interval.tv_nsec = last_read.tv_nsec - start_time.tv_nsec;
        if (interval.tv_nsec < 0) {
            interval.tv_sec--;
            interval.tv_nsec += 1000000000;
        }
        if (interval.tv_sec < 0) {
            interval.tv_sec += 1;
            interval.tv_nsec = 0;
        }

        // Sleep
        sleep_time.tv_sec = interval.tv_sec;
        sleep_time.tv_nsec = interval.tv_nsec;
        nanosleep(&sleep_time, &interval_time);

        // Update start time
        start_time = clock_gettime(CLOCK_REALTIME);
    }

    // Clean up
    syslog_closelog();
    syslog_setlogmask(0);
    i2c_close(I2C Bus);
    gpio_close(gpio_fd);
    return 0;
}

