#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/types.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>
#include <errno.h>
#include <time.h>
#include <stdint.h>

#define I2C_ADDRESS 0x40
#define I2C_TIMEOUT 100
#define LED_GPIO 18
#define CSV_FILE "color_log.csv"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C parameters
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Open CSV file
    int csv_fd = open(CSV_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("open");
        return 1;
    }

    // Map CSV file to memory
    struct stat sb;
    if (fstat(csv_fd, &sb) < 0) {
        perror("fstat");
        return 1;
    }
    void *csv_map = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, csv_fd, 0);
    if (csv_map == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Set up LED
    if (gpioMode(LED_GPIO, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        return 1;
    }
    if (gpioWrite(LED_GPIO, 0) < 0) {
        perror("gpioWrite");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        uint8_t data[2];
        if (i2cRead(fd, data, 2, I2C_TIMEOUT) < 2) {
            fprintf(stderr, "I2C error\n");
            sleep(0.1);
            continue;
        }

        // Combine ALS and color data
        uint16_t als = (data[0] << 8) | data[1];
        uint8_t red = (data[0] >> 3) & 0x0F;
        uint8_t green = (data[0] >> 4) & 0x0F;
        uint8_t blue = (data[0] >> 5) & 0x0F;

        // Log data
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        fprintf(csv_map, "%s,%d,%d,%d\n", timestamp, als, red, green, blue);

        // Adjust LED brightness
        uint8_t brightness = (als / 100) * 255;
        if (gpioWrite(LED_GPIO, brightness) < 0) {
            perror("gpioWrite");
            return 1;
        }
    }

    // Clean up
    munmap(csv_map, sb.st_size);
    close(csv_fd);
    close(fd);
    gpioCleanUp();
    return 0;
}

