#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x1D
#define I2C_ADDRESS_MAG 0x1E
#define I2C Bus 1
#define SAMPLE_INTERVAL 100
#define SAMPLE_RATE 100
#define CSV_HEADER "timestamp,heading,acceleration_x,acceleration_y,acceleration_z,magnetic_field_x,magnetic_field_y,magnetic_field_z\n"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file
    int fd = open("compass_log.txt", O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Create I2C file descriptor
    int i2c_fd = pigpio_i2c_open(I2C Bus, I2C_ADDRESS, 100);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C file descriptor for magnetometer
    int mag_fd = pigpio_i2c_open(I2C Bus, I2C_ADDRESS_MAG, 100);
    if (mag_fd < 0) {
        pigpio_i2c_close(i2c_fd);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Read accelerometer data
    unsigned char acc_data[6];
    while (1) {
        if (pigpio_i2c_read(i2c_fd, acc_data, 6) < 6) {
            perror("pigpio_i2c_read");
            pigpio_i2c_close(i2c_fd);
            pigpio_i2c_close(mag_fd);
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Compute tilt-compensated heading
        float ax = (acc_data[0] * 16384.0 / 1024.0) / 9.81;
        float ay = (acc_data[1] * 16384.0 / 1024.0) / 9.81;
        float az = (acc_data[2] * 16384.0 / 1024.0) / 9.81;
        float gx = (acc_data[3] * 16384.0 / 1024.0) / 1560.0;
        float gy = (acc_data[4] * 16384.0 / 1024.0) / 1560.0;
        float gz = (acc_data[5] * 16384.0 / 1024.0) / 1560.0;
        float heading = atan2(gx, gy) + atan2(gz, sqrt(gx * gx + gy * gy));

        // Read magnetometer data
        unsigned char mag_data[6];
        if (pigpio_i2c_read(mag_fd, mag_data, 6) < 6) {
            pigpio_i2c_close(i2c_fd);
            pigpio_i2c_close(mag_fd);
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Compute magnetic field
        float mx = (mag_data[0] * 16.0 / 1024.0);
        float my = (mag_data[1] * 16.0 / 1024.0);
        float mz = (mag_data[2] * 16.0 / 1024.0);

        // Log data
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        fprintf(fd, "%s,%f,%f,%f,%f,%f,%f,%f\n", timestamp, heading, ax, ay, az, mx, my, mz);
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    pigpio_i2c_close(mag_fd);
    close(fd);
    gpioTerminate();

    return 0;
}

