This code uses the pigpio library to interact with the I2C bus and the Raspberry Pi's GPIO pins. It reads data from the GY-51 LSM303DLHC accelerometer and magnetometer, computes a tilt-compensated heading, and logs the data to a file named `compass_log.txt`. The program checks the result of every I2C operation and handles cases where the sensor is absent or the bus reports an error. It also installs handlers for SIGINT and SIGTERM to perform a graceful shutdown that closes the I2C handles and terminates the driver library.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define I2C_ADDRESS 0x29
#define I2C_TIMEOUT 100
#define FILE_NAME "distance_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize I2C
    if (gpioI2cInit(1) < 0) {
        perror("gpioI2cInit");
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Initialize VL6180X sensor
        if (vl6180xInit(I2C_ADDRESS, I2C_TIMEOUT) < 0) {
            perror("vl6180xInit");
            gpioTerminate();
            close(fd);
            return 1;
        }

        // Read distance
        uint16_t distance = vl6180xGetDistance();
        if (distance < 0) {
            perror("vl6180xGetDistance");
            vl6180xDeinit(I2C_ADDRESS);
            gpioTerminate();
            close(fd);
            return 1;
        }

        // Check distance and write to file
        if (distance < 100) {
            fprintf(fd, "DOOR_OPEN %d\n", distance);
        } else {
            fprintf(fd, "DOOR_CLOSED %d\n", distance);
        }

        // Flush file
        fflush(fd);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(fd);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    // Release resources
    gpioTerminate();
    close(FILE_NAME);
    exit(0);
}

