#define SPI_MODE_3  0x01
#define SPI_CPOL    0x01
#define SPI_CPHA    0x01
#define SPI_SPEED    1000000
#define SPI_CS      8
#define SPI_CS_PIN   17
#define SPI_CS_GPIO  GPIO_NUM_17
#define SPI_CS_MODE  GPIO_MODE_OUTPUT
#define SPI_CS_HIGH  1
#define SPI_CS_LOW   0
#define SPI_STALL_TIME 40
#define SAMPLE_RATE  10
#define SAMPLE_INTERVAL 100
#define SAMPLE_COUNT  100
#define CSV_FILE_NAME "imu_data.csv"

// Gyroscope sensitivity in deg/sec/LSB
#define GYRO_SENSITIVITY 0.005
// Accelerometer sensitivity in g/LSB
#define ACC_SENSITIVITY 0.00025

// Register addresses
#define GYRO_REG1  0x00
#define GYRO_REG2  0x01
#define GYRO_REG3  0x02
#define GYRO_REG4  0x03
#define GYRO_REG5  0x04
