#define GYRO_REG8  0x07
#define GYRO_REG9  0x08
#define GYRO_REG10 0x09
#define GYRO_REG11 0x0A
#define GYRO_REG12 0x0B
#define GYRO_REG13 0x0C
#define GYRO_REG14 0x0D
#define GYRO_REG15 0x0E
#define GYRO_REG16 0x0F

#define ACC_REG1  0x10
#define ACC_REG2  0x11
#define ACC_REG3  0x12
#define ACC_REG4  0x13
#define ACC_REG5  0x14
#define ACC_REG6  0x15
#define ACC_REG7  0x16
#define ACC_REG8  0x17
#define ACC_REG9  0x18
#define ACC_REG10 0x19
#define ACC_REG11 0x1A
#define ACC_REG12 0x1B
#define ACC_REG13 0x1C
#define ACC_REG14 0x1D
#define ACC_REG15 0x1E
#define ACC_REG16 0x1F

// Gyroscope and accelerometer data structures
typedef struct {
    uint16_t timestamp;
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data;

// Helper function to convert raw data to degrees
float convert_to_degrees(float raw_value) {
    return raw_value * 57.29577951308232;
}

// Helper function to convert raw data to g
float convert_to_g(float raw_value) {
    return raw_value / 16384.0;
}

// Helper function to convert raw data to ms
float convert_to_ms(float raw_value) {
    return raw_value * 1000.0;
}

// Helper function to read data from the IMU
int read_imu_data(pigpio_t *gpio, imu_data *data) {
    // Set the SPI mode
    gpio->spi_set_mode(SPI_CS_PIN, SPI_MODE_3);
    gpio->spi_set_speed(SPI_SPEED);
    gpio->spi_set_bits(SPI_CPOL);
    gpio->spi_set_bits(SPI_CPHA);

    // Send the command word
    uint8_t command_word = 0x00;
    gpio->spi_write(SPI_CS_PIN, &command_word, 1);

    // Wait for the stall time
    usleep(SPI_STALL_TIME * 1000);

    // Read the data
    uint16_t data_word = gpio->spi_read(SPI_CS_PIN, 2);

    // Convert the data to degrees
    data->gyro_x = convert_to_degrees((float)data_word >> 8);
    data->gyro_y = convert_to_degrees((float)data_word & 0xFF);
    data->gyro_z = convert_to_degrees((float)data_word & 0xFF);

    // Read the next data word
    data_word = gpio->spi_read(SPI_CS_PIN, 2);

    // Convert the data to g
    data->accel_x = convert_to_g((float)data_word >> 8);
    data->accel_y = convert_to_g((float)data_word & 0xFF);
    data->accel_z = convert_to_g((float)data_word & 0xFF);

    // Return 0 on success
    return 0;
}

