#include <stdint.h>

#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define CS_PIN 8
#define CS_HIGH 1
#define CS_LOW 0
#define SPI_CS 0

int main() {
    int spi_fd, gpio_fd;
    struct pigpio gpio;
    struct spi_ioc_transfer transfers[] = {
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
        { .tx { .buf = (uint8_t *) &0x00, .len = 1, .flags = SPI_CSB },
    };
    uint8_t gyro_scale = 0x02;
    uint8_t accel_scale = 0x00;
    uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Initialize pigpio
    if (gpio_init(&gpio) < 0) {
        perror("gpio_init");
        return 1;
    }

    // Set up GPIO pin 8 as an output
    if (gpio_mode(SPI_CS, GPIO_MODE_OUTPUT) < 0) {
        perror("gpio_mode");
        gpio_close(&gpio);
        return 1;
    }
    gpio_write(SPI_CS, CS_HIGH);

    // Open SPI device
    if ((spi_fd = spi_open(0, SPI_MODE_3, SPI_SPEED, CS_PIN)) < 0) {
        perror("spi_open");
        gpio_close(&gpio);
        return 1;
    }

    // Set up SPI transfer
    if (ioctl(spi_fd, SPI_IOC_SETTXBUFSIZE, sizeof(transfers)) < 0) {
        perror("ioctl");
        close(spi_fd);
        gpio_close(&gpio);
        return 1;
    }

    while (1) {
        // Set chip select high
        gpio_write(SPI_CS, CS_HIGH);

        // Send register address with bit 7 set
        gpio_write(SPI_CS, CS_LOW);
        gpio_write(SPI_CS, CS_HIGH);

        // Read 16-bit data
        if (ioctl(spi_fd, SPI_IOC_READ, transfers) < 0) {
            perror("ioctl");
            close(spi_fd);
            gpio_close(&gpio);
            return 1;
        }

        // Read gyro and accel values
        gyro_x = (transfers[0].tx[0] & 0x3F) * gyro_scale;
        gyro_y = (transfers[1].tx[0] & 0x3F) * gyro_scale;
        gyro_z = (transfers[2].tx[0] & 0x3F) * gyro_scale;
        accel_x = (transfers[3].tx[0] & 0x3F) * accel_scale;
        accel_y = (transfers[4].tx[0] & 0x3F) * accel_scale;
        accel_z = (transfers[5].tx[0] & 0x3F) * accel_scale;

        // Log values
        printf("Gyro X: %f, Gyro Y: %f, Gyro Z: %f, Accel X: %f, Accel Y: %f, Accel Z: %f\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Wait 100ms
        usleep(100000);

        // Set chip select low
        gpio_write(SPI_CS, CS_LOW);
    }

    // Clean up
    close(spi_fd);
    gpio_close(&gpio);

    return 0;
}

