#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/select.h>
#include <signal.h>

#define PI_GPIO_CE0 8
#define PI_GPIO_MOSI 10
#define PI_GPIO_MISO 11
#define PI_GPIO_SCK 12
#define PI_GPIO_SDA 13
#define ADIS16448_CMD_READ 0x00
#define ADIS16448_DUMMY 0xFFFF
#define ADIS16448_GYRO Scale 0.05
#define ADIS16448_ACCEL Scale 0.00025

void adis16448_init(pigpio_t *gpio) {
    if (gpio->init(gpio->CE0, PI_GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to initialize GPIO CE0\n");
        exit(1);
    }
    if (gpio->mode(gpio->CE0, PI_GPIO_MODE_HIGH) < 0) {
        printf("Failed to set CE0 high\n");
        exit(1);
    }
    if (gpio->mode(gpio->MOSI, PI_GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set MOSI high\n");
        exit(1);
    }
    if (gpio->mode(gpio->MISO, PI_GPIO_MODE_INPUT) < 0) {
        printf("Failed to set MISO low\n");
        exit(1);
    }
    if (gpio->mode(gpio->SCK, PI_GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set SCK high\n");
        exit(1);
    }
    if (gpio->mode(gpio->SDA, PI_GPIO_MODE_INPUT) < 0) {
        printf("Failed to set SDA low\n");
        exit(1);
    }
}

void adis16448_close(pigpio_t *gpio) {
    gpio->close(gpio->CE0);
    gpio->close(gpio->MOSI);
    gpio->close(gpio->MISO);
    gpio->close(gpio->SCK);
    gpio->close(gpio->SDA);
}

void adis16448_read(pigpio_t *gpio, uint16_t *data) {
    uint8_t cmd = (ADIS16448_CMD_READ | 0x80);
    uint8_t dummy = ADIS16448_DUMMY;
    uint8_t data[2] = {cmd, dummy};

    if (gpio->transfer(gpio->CE0, data, 2, 40) < 0) {
        printf("Failed to transfer data\n");
        exit(1);
    }

    uint16_t gyro = (data[0] << 8) | data[1];
    uint16_t accel = (data[0] << 8) | data[1];

    *data = (uint16_t)((gyro * ADIS16448_GYRO * ADIS16448_Scale) + (accel * ADIS16448_ACCEL * ADIS16448_Scale));
}

int main() {
    pigpio_t gpio;
    struct sigaction sa;

    if (pigpio_init() < 0) {
        printf("Failed to initialize pigpio\n");
        exit(1);
    }

    adis16448_init(&gpio);

    sa.sa_handler = SIGINT;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        printf("Failed to set signal handler\n");
        exit(1);
    }

    while (1) {
        fd_set set;
        struct timeval tv;
        FD_ZERO(&set);
        FD_SET(STDIN_FILENO, &set);
        tv.tv_sec = 0;
        tv.tv_usec = 100;
        if (select(STDIN_FILENO + 1, &set, NULL, NULL, &tv) < 0) {
            printf("Failed to select\n");
            exit(1);
        }

        if (FD_ISSET(STDIN_FILENO, &set)) {
            break;
        }

        adis16448_read(&gpio, NULL);
        printf("Gyro: %f, Accel: %f\n", (double)gpio.gyro / 1000, (double)gpio.accel / 1000);
    }

    adis16448_close(&gpio);
    pigpio_cleanup();
    return 0;
}

