    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        printf("Failed to set signal handler\n");
        exit(1);
    }

    while (1) {
        fd_set set;
        struct timeval tv;
        FD_ZERO(&set);
        FD_SET(STDIN_FILENO, &set);
        tv.tv_sec = 0;
        tv.tv_usec = 100;
        if (select(STDIN_FILENO + 1, &set, NULL, NULL, &tv) < 0) {
            printf("Failed to select\n");
            exit(1);
        }

        if (FD_ISSET(STDIN_FILENO, &set)) {
            break;
        }

        adis16448_read(&gpio, NULL);
        printf("Gyro: %f, Accel: %f\n", (double)gpio.gyro / 1000, (double)gpio.accel / 1000);
    }

    adis16448_close(&gpio);
    pigpio_cleanup();
    return 0;
}
```

This code initializes the GPIO pins for the ADIS16448 IMU, sets up the SPI interface, and reads the gyroscope and accelerometer data every 100ms. It also handles the Ctrl+C interrupt cleanly by closing the SPI handle and invoking the pigpio API call() before exit.

