#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_ADDRESS 0x1D
#define I2C Bus 1
#define LED_GPIO 17
#define SCALE_FACTOR 256
#define THRESHOLD 2.5
#define LOG_FILE "impact_log.txt"

int main() {
    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up LED pin as output
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Read device ID
    unsigned char device_id[3];
    if (i2cRead(i2c_fd, device_id, 3, 0x00) < 0) {
        perror("i2cRead");
        return 1;
    }
    if (device_id[0] != 0x00 || device_id[1] != 0x00 || device_id[2] != 0x01) {
        printf("Device ID mismatch\n");
        return 1;
    }

    // Set up I2C mode
    i2cSetMode(i2c_fd, I2C_MODE_READ_WRITE);
    i2cSetClock(i2c_fd, 100000);

    while (1) {
        // Read acceleration data
        unsigned char data[6];
        if (i2cRead(i2c_fd, data, 6, 0x32) < 0) {
            perror("i2cRead");
            continue;
        }

        // Calculate total acceleration magnitude
        float magnitude = sqrtf((data[0] * 2.0f / SCALE_FACTOR) * 9.81f);
        if (magnitude > THRESHOLD) {
            // Turn on LED
            gpioWrite(gpio, 1);
            sleep(0.5);
            gpioWrite(gpio, 0);
        }

        // Log event
        time_t now = time(NULL);
        struct tm* ltm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        fprintf(log_fd, "%s %f %f %f\n", timestamp, data[0] * 2.0f / SCALE_FACTOR, data[1] * 2.0f / SCALE_FACTOR, data[2] * 2.0f / SCALE_FACTOR);
        fflush(log_fd);

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up
    close(log_fd);
    i2cClose(i2c_fd);
    gpioCleanUp(gpio);
    return 0;
}

