#include <sys/ioctl.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_ADDRESS 0x1D
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read sensor ID
    uint8_t sensor_id;
    if (read(i2c_fd, &sensor_id, 1) != 1) {
        perror("read");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (sensor_id != 0x00) {
        printf("Invalid sensor ID: 0x%02x\n", sensor_id);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pin for LED
    if (gpioMode(LED_GPIO, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_WRONLY, 0644);
    if (log_fd < 0) {
        perror("open");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        uint16_t ax, ay, az;
        if (read(i2c_fd, &ax, 2) != 2) {
            perror("read");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (read(i2c_fd, &ay, 2) != 2) {
            perror("read");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (read(i2c_fd, &az, 2) != 2) {
            perror("read");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate magnitude
        double magnitude = sqrt(ax * ax + ay * ay + az * az) / 16384.0;

        // Check if magnitude exceeds threshold
        if (magnitude > 2.0) {
            gpioWrite(LED_GPIO, 1);
            sleep(0.5);
            gpioWrite(LED_GPIO, 0);
        }

        // Log reading
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        fprintf(log_fd, "%s %f\n", timestamp, magnitude);
    }

    // Clean up
    close(log_fd);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

