    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(fd, I2C_SMBUS_WRITEByte, (void*)I2C_ADDRESS, 0x00) < 0) {
        fprintf(stderr, "Error setting I2C clock speed\n");
        return 1;
    }

    // Sample magnetic field data
    while (1) {
        // Read I2C data
        unsigned char data[I2C_BUFFER_SIZE];
        if (read(fd, data, I2C_BUFFER_SIZE) < I2C_BUFFER_SIZE) {
            perror("read");
            continue;
        }

        // Check if I2C read failed
        if (data[0] & 0x80) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Convert data to magnetic field strength
        float magnetic_field = (data[0] << 8) | data[1];

        // Get current time
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write to CSV file
        if (fprintf(fd, "%s,%f\n", timestamp, magnetic_field) < 0) {
            perror("fprintf");
            return 1;
        }
    }

    // Close I2C file
    if (close(fd) < 0) {
        perror("close");
        return 1;
    }

    // Close CSV file
    if (close(fd) < 0) {
        perror("close");
        return 1;
    }

    // Clean up
    gpioTerminate();
    return 0;
}
