    status = gpio_set_mode(ADXL345_INT1_GPIO, PI_INPUT);
    if (status != 0) {
        perror("gpio_set_mode");
        close(i2c_fd);
        pigpio_close(gpio);
        i2c_close(adxl345_client);
        return 1;
    }

