        // Check for SIGINT or SIGTERM
        if (killpg(0, SIGINT) == 0 || killpg(0, SIGTERM) == 0) {
            break;
        }

        // Check for I2C errors
        if (i2c_get_err(i2c_fd) != 0) {
            perror("i2c_get_err");
            break;
        }

        // Check for GPIO errors
        if (gpio_get_err(gpio) != 0) {
            perror("gpio_get_err");
            break;
        }

        // Read sensor data
        status = i2c_read(i2c_fd, ADXL345_I2C_ADDRESS, 6, buffer, 6);
        if (status != 0) {
            perror("i2c_read");
            break;
        }

        // Check for free-fall
        if (buffer[0] & 0x80) {
            // Read timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Read acceleration
            x = (buffer[1] << 8) | buffer[2];
            y = (buffer[3] << 8) | buffer[4];
            z = (buffer[5] << 8) | buffer[6];

            // Write to log file
            sprintf(buffer, "%04d-%02d-%02d %02d:%02d:%02d.%03d,%d,%d,%d\n",
                    ts.tv_sec, ts.tv_usec / 1000000, ts.tv_sec % 100, ts.tv_sec % 60, ts.tv_sec / 60 % 60, ts.tv_sec / 3600, ts.tv_usec % 1000, x, y, z);
            fprintf(fd, buffer);
            fflush(fd);
        }
    }

    // Close log file
    close(fd);

    // Disable interrupts
    status = gpio_get_value(ADXL345_INT1_GPIO);
    if (status == 0) {
        status = gpio_set_value(ADXL345_INT1_GPIO, 1);
    }
    if (status != 0) {
        perror("gpio_set_value");
    }

    // Close I2C file descriptor
    close(i2c_fd);

    // Close sensor device
    i2c_close(adxl345_client);

    // Close GPIO file descriptor
    close(gpio_fd = gpio_fd);

    // Close pigpio
    pigpio_close(gpio);

    return 0;
}

