#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_CE 17
#define WHO_AM_I 0x00
#define WHO_AM_I_RESPONSE 0x01
#define GYRO_X 0x00
#define GYRO_Y 0x01
#define GYRO_Z 0x02
#define GYRO_SCALE 0.0305

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_CS, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI_CS, 1) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    if (gpioSetLevel(SPI_CE, 0) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_CE, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetLevel(SPI_CE, 1) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_CE, GPIO_MODE_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open log file
    char logFile[] = "gyro_log.csv";
    if (access(logFile, F_OK) == -1) {
        if (mkdir(logFile, 0644) < 0) {
            perror("mkdir");
            gpioTerminate();
            return 1;
        }
    }
    if (fopen(logFile, "w") < 0) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(stderr, "gyro_log.csv:timestamp,x,y,z\n");
    fclose(stdin);

    // Check WHO_AM_I register
    uint8_t whoAmIResponse;
    if (spiTransfer(SPI_CS, SPI_SPEED, SPI_MODE, 0x00, &whoAmIResponse, 1) < 0) {
        perror("spiTransfer");
        gpioTerminate();
        return 1;
    }
    if (whoAmIResponse != WHO_AM_I_RESPONSE) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI handle
    int spiHandle = spiOpen(SPI_CS, SPI_SPEED, SPI_MODE, SPI_CPOL, SPI_CPHA);
    if (spiHandle < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Sample angular rate
    struct timespec start;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        // Read WHO_AM_I register
        uint8_t whoAmIResponse;
        if (spiTransfer(SPI_CS, SPI_SPEED, SPI_MODE, 0x00, &whoAmIResponse, 1) < 0) {
            perror("spiTransfer");
            gpioTerminate();
            return 1;
        }

        // Read gyro registers
        uint16_t gyroX, gyroY, gyroZ;
        if (spiTransfer(SPI_CS, SPI_SPEED, SPI_MODE, 0x00, &gyroX, 2) < 0) {
            perror("spiTransfer");
            gpioTerminate();
            return 1;
        }
        if (spiTransfer(SPI_CS, SPI_SPEED, SPI_MODE, 0x01, &gyroY, 2) < 0) {
            perror("spiTransfer");
            gpioTerminate();
            return 1;
        }
        if (spiTransfer(SPI_CS, SPI_SPEED, SPI_MODE, 0x02, &gyroZ, 2) < 0) {
            perror("spiTransfer");
            gpioTerminate();
            return 1;
        }

        // Convert raw values to degrees
        double gyroXDeg = (gyroX * GYRO_SCALE);
        double gyroYDeg = (gyroY * GYRO_SCALE);
        double gyroZDeg = (gyroZ * GYRO_SCALE);

        // Append to log file
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3d", localtime(&start.tv_sec) + (start.tv_nsec / 1000000000));
        fprintf(stderr, "%s,%f,%f,%f\n", timestamp, gyroXDeg, gyroYDeg, gyroZDeg);
        if (ferror(stdin)) {
            perror("ferror");
            gpioTerminate();
            return 1;
        }

        // Sleep for 10ms
        struct timespec sleepTime;
        sleepTime.tv_sec = 0;
        sleepTime.tv_nsec = 10000;
        nanosleep(&sleepTime, NULL);

        // Check for SIGINT
        if (kill(getpid(), SIGINT) == 0) {
            break;
        }
    }

    // Close log file
    if (fclose(stdin) < 0) {
        perror("fclose");
        gpioTerminate();
        return 1;
    }

    // Close SPI handle
    if (spiclose(spiHandle) < 0) {
        perror("spiclose");
        gpioTerminate();
        return 1;
    }

    // Close GPIO
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
        return 1;
    }

    return 0;
}

