    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio == -1) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO17 as output with internal pull-up resistor
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPullUpDnLevel(GPIO_PIN, PI_PUD_UP);

    // Open log file
    int log_fd = open(LOG_FILE, LOG_MODE);
    if (log_fd == -1) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Set up polling loop
    while (1) {
        // Read GPIO17
        int value = gpioRead(GPIO_PIN);
        if (value == 0) {
            // Log flame detected
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s – %s\n", timestamp, FLAME_DETECTED);
