#include <sys/mman.h>
#include <sys/statvfs.h>
#include <sys/time.h>
#include <sys/select.h>
#include <signal.h>

#define I2C_ADDRESS 0x10
#define I2C_FILE "/dev/i2c-1"
#define CSV_FILE "vibration_log.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    int fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read acceleration data
        unsigned char data[6];
        if (read(fd, data, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device\n");
            continue;
        }

        // Check for sensor-absent condition
        if (data[0] == 0x00) {
            fprintf(stderr, "Sensor absent\n");
            continue;
        }

        // Convert data to floats
        float x = (data[1] << 8) | data[2];
        float y = (data[3] << 8) | data[4];
        float z = (data[5] << 8) | data[6];

        // Get current time
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", ltm);

        // Write to CSV file
        fprintf(fp, "%s,%f,%f,%f\n", timestamp, x, y, z);
        fflush(fp);
    }

    // Close I2C file descriptor
    close(fd);

    // Close CSV file
    fclose(fp);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

