#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>

// Define constants
#define GPIO17 17
#define GPIO27 27
#define FILE_NAME "conveyor_log.txt"
#define FILE_MODE O_RDWR | O_CREAT | O_APPEND
#define FILE_PERMS 0644
#define LOG_INTERVAL 50
#define LOG_SIZE 1024

// Define structures
typedef struct {
    int fd;
    pigpio gpio;
} gpio_t;

// Function to initialize GPIO
gpio_t* gpio_init(int gpio_num) {
    gpio_t* gpio = malloc(sizeof(gpio_t));
    if (gpio == NULL) {
        perror("malloc");
        exit(1);
    }

    gpio->fd = pigpio_open(gpio_num);
    if (gpio->fd < 0) {
        perror("pigpio_open");
        free(gpio);
        exit(1);
    }

    gpio->gpio = pigpio_init(gpio_num);
    if (gpio->gpio < 0) {
        pigpio_close(gpio->fd);
        free(gpio);
        exit(1);
    }

    return gpio;
}

// Function to configure GPIO
void gpio_config(gpio_t* gpio, int mode, int pull_up) {
    if (pigpio_mode(gpio->gpio, mode) < 0) {
        perror("pigpio_mode");
        pigpio_close(gpio->fd);
        free(gpio);
        exit(1);
    }

    if (pigpio_pull_up(gpio->gpio, pull_up) < 0) {
        perror("pigpio_pull_up");
        pigpio_close(gpio->fd);
        free(gpio);
        exit(1);
    }
}

// Function to read GPIO value
int gpio_read(gpio_t* gpio) {
    int value;
    if (pigpio_read(gpio->gpio, &value) < 0) {
        perror("pigpio_read");
        pigpio_close(gpio->fd);
        free(gpio);
        exit(1);
    }
    return value;
}

// Function to write to file
void file_write(int fd, const char* str) {
    if (write(fd, str, strlen(str)) < 0) {
        perror("write");
        exit(1);
    }
}

// Function to log data
void log_data(gpio_t* gpio1, gpio_t* gpio2, int timestamp) {
    char log_str[LOG_SIZE];
    sprintf(log_str, "%d %d %d\n", timestamp, gpio_read(gpio1), gpio_read(gpio2));
    file_write(gpio1->fd, log_str);
    file_write(gpio2->fd, log_str);
}

// Function to handle SIGINT and SIGTERM
void sig_handler(int sig) {
    pigpio_close(gpio1->fd);
    pigpio_close(gpio2->fd);
    free(gpio1);
    free(gpio2);
    exit(0);
}

int main() {
    // Initialize GPIO
    gpio_t* gpio1 = gpio_init(GPIO17);
    gpio_t* gpio2 = gpio_init(GPIO27);

    // Configure GPIO
    gpio_config(gpio1, PI_INPUT, PI Internal);
    gpio_config(gpio2, PI_INPUT, PI Internal);

    // Open file for writing
    int fd = open(FILE_NAME, FILE_MODE, FILE_PERMS);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        int timestamp = time(NULL);
        log_data(gpio1, gpio2, timestamp);
        if (gpio_read(gpio1) == 1 && gpio_read(gpio2) == 1) {
            printf("Halt!\n");
            break;
        }
        usleep(LOG_INTERVAL * 1000);
    }

    // Close file and GPIO
    close(fd);
    pigpio_close(gpio1->gpio);
    pigpio_close(gpio2->gpio);
    pigpio_close(gpio1->fd);
    pigpio_close(gpio2->fd);
    free(gpio1);
    free(gpio2);

    return 0;
}

