#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_ADDRESS 0x1D
#define WHO_AM_I 0x00
#define CONTROL 0x01
#define STANDBY 0x02
#define DATA_RATE 0x03
#define DATA_FORMAT 0x04
#define DATA_REG 0x05
#define DATA_REG2 0x06
#define DATA_REG3 0x07
#define DATA_REG4 0x08
#define DATA_REG5 0x09
#define DATA_REG6 0x0A

#define FALL_THRESHOLD 45

int main() {
    int fd;
    int i;
    int status;
    uint8_t whoami;
    uint8_t control;
    uint8_t data[6];
    int log_fd;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    fd = pigpio_open("/dev/i2c-1", O_RDWR, 0);
    if (fd < 0) {
        perror("pigpio_open");
        return 1;
    }

    // Check sensor identity
    if (pigpio_write(fd, WHO_AM_I, 1) < 0) {
        perror("pigpio_write");
        pigpio_close(fd);
        return 1;
    }
    pigpio_read(fd, &whoami, 1);
    if (whoami != 0x55) {
        fprintf(stderr, "Invalid sensor identity\n");
        pigpio_close(fd);
        return 1;
    }

    // Initialize device
    pigpio_write(fd, CONTROL, STANDBY);
    pigpio_write(fd, DATA_RATE, 0x01);
    pigpio_write(fd, DATA_FORMAT, 0x00);
    pigpio_write(fd, DATA_REG, 0x00);
    pigpio_write(fd, DATA_REG2, 0x00);
    pigpio_write(fd, DATA_REG3, 0x00);
    pigpio_write(fd, DATA_REG4, 0x00);
    pigpio_write(fd, DATA_REG5, 0x00);
    pigpio_write(fd, DATA_REG6, 0x00);

    // Open log file
    log_fd = open("fall_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        pigpio_close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data
        if (pigpio_read(fd, data, 6) < 0) {
            perror("pigpio_read");
            pigpio_close(fd);
            close(log_fd);
            return 1;
        }

        // Combine MSB and LSB of each axis
        uint16_t x = (data[0] << 4) | data[1];
        uint16_t y = (data[2] << 4) | data[3];
        uint16_t z = (data[4] << 4) | data[5];

        // Compute absolute tilt
        float tilt = sqrt(x * x + y * y + z * z);

        // Check for fall
        if (tilt > FALL_THRESHOLD) {
            time_t now = time(NULL);
            fprintf(log_fd, "%d %d %d\n", now, x, y);
            fflush(log_fd);
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Close log file
    close(log_fd);

    // Close I2C device
    pigpio_close(fd);

    return 0;
}

void sigint_handler(int sig) {
    close(log_fd);
    pigpio_close(fd);
    exit(0);
}

