#define SPI_MODE_0 0
#define SPI_MODE_1 1
#define SPI_MSB 0
#define SPI_LSB 1
#define SPI_CS 0
#define SPI_SCK 5
#define SPI_MOSI 9
#define SPI_MISO 10
#define SPI_SPEED 1000000
#define SPI_CS_PIN 8
#define SPI_RESET_PIN 11
#define SPI_LOG_FILE "vibration_log.txt"

int main(int argc, char **argv) {
    int spi_fd, spi_cs, spi_sck, spi_mosi, spi_miso;
    struct pigpio *gpio;
    struct spi_iodev spi_dev;
    struct spi_ioremap spi_map;
    struct timeval tv;
    struct timespec tv_sec, tv_nsec;
    struct stat sb;
    char log_file[1024];
    int retry = 0;
    int retry_count = 0;
    int status = 0;

    // Initialize pigpio
    gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        return 1;
    }

    // Open SPI device
    spi_fd = spi_open(gpio, SPI_CS_PIN, SPI_MODE_0, SPI_SPEED, SPI_MSB, SPI_LSB);
    if (spi_fd < 0) {
        perror("spi_open");
        pigpio_close(gpio);
        return 1;
    }

    // Open SPI device for ioremap
    spi_dev.io_base = spi_fd;
    spi_dev.io_size = sizeof(spi_dev);
    if (ioctl(spi_dev.io_base, SPI_IOC_SETGMAP, &spi_map) < 0) {
        perror("ioctl");
        close(spi_fd);
        pigpio_close(gpio);
        return 1;
    }

    // Configure SPI pins
    spi_cs = gpio_get(gpio, SPI_CS_PIN);
    spi_sck = gpio_get(gpio, SPI_SCK);
    spi_mosi = gpio_get(gpio, SPI_MOSI);
    spi_miso = gpio_get(gpio, SPI_MISO);

    // Configure SPI pins as output
    gpio_set_mode(spi_cs, PI_OUTPUT);
    gpio_set_mode(spi_sck, PI_OUTPUT);
    gpio_set_mode(spi_mosi, PI_OUTPUT);
    gpio_set_mode(spi_miso, PI_INPUT);

    // Configure SPI clock
    gpio_set_level(spi_sck, 1);
    usleep(1000);
    gpio_set_level(spi_sck, 0);
    usleep(1000);
    gpio_set_level(spi_sck, 1);

    // Reset sequence
    gpio_set_level(spi_cs, 0);
    usleep(1);
    gpio_set_level(spi_cs, 1);
    usleep(1);
    gpio_set_level(spi_cs, 0);
    usleep(1);
    gpio_set_level(spi_cs, 1);

    // Wait for STABLE bit to be set
    while (1) {
        gpio_get_value(spi_miso, &status);
        if (status & (1 << 7)) {
            break;
        }
        usleep(100);
    }

    // Set RUN bit
    gpio_set_level(spi_cs, 0);
    usleep(1);
    gpio_set_level(spi_cs, 1);

