#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>

#define IMU_ADDRESS 0x1D
#define IMU_DATA_SIZE 2
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SPI_CE 8
#define SPI_CS 10
#define SPI_DATA 11
#define DELAY 10

void sigint_handler(int sig) {
    gpio_close(SPI_CE);
    gpio_close(SPI_CS);
    close(SPI_HANDLE);
    fclose(log_file);
    pigpio_cleanup();
    exit(0);
}

int main() {
    // Initialize the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize the pigpio library
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Set up the SPI pins
    if (gpio_set_mode(SPI_CE, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        return 1;
    }
    if (gpio_set_mode(SPI_CS, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        return 1;
    }
    if (gpio_set_level(SPI_CE, 1) < 0) {
        perror("gpio_set_level");
        return 1;
    }
    if (gpio_set_level(SPI_CS, 0) < 0) {
        perror("gpio_set_level");
        return 1;
    }

    // Open the SPI device
    SPI_HANDLE = spi_open(SPI_CS, SPI_MODE, SPI_SPEED);
    if (SPI_HANDLE < 0) {
        perror("spi_open");
        return 1;
    }

    // Open the log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    // Write the header to the log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    while (1) {
        // Send the address byte with the MSB set
        uint8_t address = IMU_ADDRESS | 0x80;
        uint8_t dummy = 0x00;
        uint16_t data[IMU_DATA_SIZE];
        if (spi_xfer(SPI_HANDLE, &address, &dummy, data, IMU_DATA_SIZE) < 0) {
            perror("spi_xfer");
            continue;
        }

        // Scale the gyroscope output
        float gyro_x = (data[0] * 0.05) / 65536.0;
        float gyro_y = (data[1] * 0.05) / 65536.0;
        float gyro_z = (data[2] * 0.05) / 65536.0;

        // Scale the accelerometer output
        float accel_x = (data[3] * 0.0025) / 65536.0;
        float accel_y = (data[4] * 0.0025) / 65536.0;
        float accel_z = (data[5] * 0.0025) / 65536.0;

        // Log the measurements
        time_t now = time(NULL);
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp = ts.tv_sec * 1e9 + ts.tv_nsec;
        fprintf(log_file, "%llu,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Insert a 10ms delay
        usleep(10000);

        // Check for SIGINT
        if (sigaction(SIGINT, NULL, NULL) < 0) {
            perror("sigaction");
            return 1;
        }
    }

    // Close the SPI device
    if (spi_close(SPI_HANDLE) < 0) {
        perror("spi_close");
        return 1;
    }

    // Close the log file
    if (fclose(log_file) < 0) {
        perror("fclose");
        return 1;
    }

    // Clean up
    if (gpio_close(SPI_CE) < 0) {
        perror("gpio_close");
        return 1;
    }
    if (gpio_close(SPI_CS) < 0) {
        perror("gpio_close");
        return 1;
    }
    pigpio_cleanup();
    return 0;
}

