        perror("spi_open");
        return 1;
    }

    // Open the log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    // Write the header to the log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    while (1) {
        // Send the address byte with the MSB set
        uint8_t address = IMU_ADDRESS | 0x80;
        uint8_t dummy = 0x00;
        uint16_t data[IMU_DATA_SIZE];
        if (spi_xfer(SPI_HANDLE, &address, &dummy, data, IMU_DATA_SIZE) < 0) {
            perror("spi_xfer");
            continue;
        }

        // Scale the gyroscope output
        float gyro_x = (data[0] * 0.05) / 65536.0;
        float gyro_y = (data[1] * 0.05) / 65536.0;
        float gyro_z = (data[2] * 0.05) / 65536.0;

        // Scale the accelerometer output
        float accel_x = (data[3] * 0.0025) / 65536.0;
        float accel_y = (data[4] * 0.0025) / 65536.0;
        float accel_z = (data[5] * 0.0025) / 65536.0;

        // Log the measurements
        time_t now = time(NULL);
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp = ts.tv_sec * 1e9 + ts.tv_nsec;
        fprintf(log_file, "%llu,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Insert a 10ms delay
        usleep(10000);

        // Check for SIGINT
        if (sigaction(SIGINT, NULL, NULL) < 0) {
            perror("sigaction");
            return 1;
        }
    }

    // Close the SPI device
    if (spi_close(SPI_HANDLE) < 0) {
        perror("spi_close");
        return 1;
    }

    // Close the log file
    if (fclose(log_file) < 0) {
        perror("fclose");
        return 1;
    }

    // Clean up
    if (gpio_close(SPI_CE) < 0) {
        perror("gpio_close");
        return 1;
    }
    if (gpio_close(SPI_CS) < 0) {
        perror("gpio_close");
        return 1;
    }
    pigpio_cleanup();
    return 0;
}
