#define ADIS16266_SCALE 0.02

void init_spi(void) {
    int fd;
    int ret;

    // Initialize SPI
    fd = spi_open(SPI_DEVICE, SPI_MODE, MSB_FIRST);
    if (fd < 0) {
        perror("spi_open");
        exit(1);
    }

    // Set SPI clock speed
    ret = spi_set_speed(fd, SPI_SPEED);
    if (ret < 0) {
        perror("spi_set_speed");
        exit(1);
    }

    // Set SPI mode
    ret = spi_set_mode(fd, SPI_MODE);
    if (ret < 0) {
        perror("spi_set_mode");
        exit(1);
    }

    // Set SPI chip select
    ret = spi_set_chip_select(fd, GPIO_CE0);
    if (ret < 0) {
        perror("spi_set_chip_select");
        exit(1);
    }

    // Set SPI MOSI, MISO, and SCK pins
    ret = gpio_set_mode(GPIO_MOSI, PI_OUTPUT);
    if (ret < 0) {
        perror("gpio_set_mode");
        exit(1);
    }
    ret = gpio_set_mode(GPIO_MISO, PI_INPUT);
    if (ret < 0) {
        perror("gpio_set_mode");
        exit(1);
    }
    ret = gpio_set_mode(GPIO_SCK, PI_OUTPUT);
    if (ret < 0) {
        perror("gpio_set_mode");
        exit(1);
    }
}

