    ret = spi_xfer(fd, &address, &data, 1, SPI_MSGBFIRST);
    if (ret < 0) {
        perror("spi_xfer");
        exit(1);
    }

    // Read 2 bytes
    ret = spi_xfer(fd, NULL, &data, 2, SPI_MSGBFIRST);
    if (ret < 0) {
        perror("spi_xfer");
        exit(1);
    }

    // Extract data
    x = data[0];
    y = data[1];

    // Apply scale factor
    ax = (x * ADIS16266_SCALE);
    ay = (y * ADIS16266_SCALE);
    az = (x * ADIS16266_SCALE);

    // Log data
    printf("X: %.2f, Y: %.2f, Z: %.2f\n", ax, ay, az);

    // Delay
    usleep(100000);
}

