void i2c_callback(pigpio_i2c_t *i2c, void *user_data) {
    // Get the I2C handle
    pigpio_i2c_t *i2c_handle = (pigpio_i2c_t *)user_data;

    // Read the WHO_AM_I register
    uint8_t whoami = 0;
    if (i2c_read(i2c, I2C_ADDRESS, WHO_AM_I, &whoami, 1) != 0) {
        fprintf(stderr, "I2C read WHO_AM_I failed\n");
        exit(1);
    }

    // Check if the WHO_AM_I register value matches the expected value
    if (whoami != 0x71) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        exit(1);
    }

    // Read the accelerometer and gyroscope values
    uint16_t ax = 0, ay = 0, az = 0, gx = 0, gy = 0, gz = 0;
    if (i2c_read(i2c, I2C_ADDRESS, GYRO_X, &gx, 2) != 0) {
        fprintf(stderr, "I2C read GYRO_X failed\n");
        exit(1);
    }
    if (i2c_read(i2c, I2C_ADDRESS, GYRO_Y, &gy, 2) != 0) {
        fprintf(stderr, "I2C read GYRO_Y failed\n");
        exit(1);
    }
    if (i2c_read(i2c, I2C_ADDRESS, GYRO_Z, &gz, 2) != 0) {
        fprintf(stderr, "I2C read GYRO_Z failed\n");
        exit(1);
    }
    if (i2c_read(i2c, I2C_ADDRESS, ACC_X, &ax, 2) != 0) {
        fprintf(stderr, "I2C read ACC_X failed\n");
        exit(1);
    }
    if (i2c_read(i2c, I2C_ADDRESS, ACC_Y, &ay, 2) != 0) {
        fprintf(stderr, "I2C read ACC_Y failed\n");
        exit(1);
    }
    if (i2c_read(i2c, I2C_ADDRESS, ACC_Z, &az, 2) != 0) {
        fprintf(stderr, "I2C read ACC_Z failed\n");
        exit(1);
    }

    // Print the values
    printf("%d %d %d %d %d %d\n", ax, ay, az, gx, gy, gz);
}

int main() {
    // Initialize the GPIO library
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        exit(1);
    }

    // Initialize the I2C library
    if (pigpio_i2c_init(I2C_BUS) != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        exit(1);
    }

    // Install the I2C callback function
    pigpio_i2c_set_callback(I2C_BUS, i2c_callback, NULL);

    // Open the I2C handle
    pigpio_i2c_t *i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle == NULL) {
        fprintf(stderr, "I2C open failed\n");
        exit(1);
    }

    // Set the I2C clock speed
    if (pigpio_i2c_set_clock(i2c_handle, 100000) != 0) {
        fprintf(stderr, "I2C clock set failed\n");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the I2C values
        i2c_callback(i2c_handle, NULL);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    pigpio_i2c_cleanup(I2C_BUS);
    gpio_cleanup();
    return 0;
}
