#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 17
#define SAMPLE_RATE 1000 // 1ms
#define WINDOW_SIZE 5
#define THRESHOLD 10

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        return 1;
    }

    struct timespec start_time;
    struct timespec end_time;
    int count = 0;
    int high_count = 0;
    int gpio = -1;

    // Initialize GPIO
    if (gpio = gpioInitialise()) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set initial state to low
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error setting GPIO state\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Start timer
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Sample GPIO17 every SAMPLE_RATE ms
        for (int i = 0; i < SAMPLE_RATE; i++) {
            // Read GPIO17
            int value = gpioRead(GPIO_PIN);
            if (value == 1) {
                high_count++;
            } else {
                high_count = 0;
            }
            // Check for SIGINT and SIGTERM
            if (gpioGetSignal(GPIO_PIN) != 0) {
                gpioTerminate();
                return 0;
            }
        }

        // Check if threshold is exceeded
        if (high_count > threshold) {
            fprintf(stderr, "%ld ALERT\n", (long) (end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec / 1000000));
        } else {
            fprintf(stderr, "%ld OK\n", (long) (end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec / 1000000));
        }

        // Update end time
        clock_gettime(CLOCK_MONOTONIC, &end_time);

        // Wait for WINDOW_SIZE seconds
        sleep(WINDOW_SIZE);

        // Reset high count
        high_count = 0;
    }

    gpioTerminate();
    return 0;
}

