#define RELAY_CODE_PIN 8
#define RELAY_LOCK_PIN 9
#define RELAY_UNLOCK_PIN 10
#define RELAY_CODE_LENGTH 6
#define RELAY_CODE_MAX 999999
#define RELAY_CODE_MIN 100000
#define RELAY_CODE_BUFFER_SIZE 7
#define RELAY_CODE_BUFFER 0x00
#define RELAY_LOCK 0x01
#define RELAY_UNLOCK 0x02
#define RELAY_CODE 0x03
#define RELAY_CODE_PIN 0x04
#define RELAY_PIN 0x05
#define RELAY_LOCK_PIN 0x06
#define RELAY_UNLOCK_PIN 0x07

// Define structures
typedef struct {
    gpiod_async_context_t ctx;
    gpiod_async_event_t event;
    gpiod_async_event_t event_lock;
    gpiod_async_event_t event_unlock;
    gpiod_async_event_t event_code;
    gpiod_async_event_t event_code_pin;
    gpiod_async_event_t event_pin;
    gpiod_async_event_t event_unlock_pin;
} door_access_t;

// Define functions
void init_door_access(door_access_t *door_access);
void lock_door(door_access_t *door_access);
void unlock_door(door_access_t *door_access);
void generate_code(door_access_t *door_access);
void read_code(door_access_t *door_access);
void handle_input(door_access_t *door_access);
void sig_handler(int sig);
void cleanup(door_access_t *door_access);

int main() {
    // Initialize random number generator
    srand(time(NULL));

    // Initialize GPIO
    if (gpiod_async_init(&door_access->ctx) != 0) {
        fprintf(stderr, "gpiod_async_init failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (gpiod_async_pin_init(&door_access->event, GPIO_A, gpiod_async_direction_OUTPUT, gpiod_async_value_HIGH) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for GPIO_A\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (gpiod_async_pin_init(&door_access->event_lock, GPIO_B, gpiod_async_direction_OUTPUT, gpiod_async_value_HIGH) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for GPIO_B\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (gpiod_async_pin_init(&door_access->event_unlock, RELAY_PIN, gpiod_async_direction_OUTPUT, gpiod_async_value_HIGH) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for RELAY_PIN\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (gpiod_async_pin_init(&door_access->event_unlock_pin, RELAY_UNLOCK_PIN, gpiod_async_direction_OUTPUT, gpiod_async_value_HIGH) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for RELAY_UNLOCK_PIN\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (gpiod_async_pin_init(&door_access->event_code, RELAY_CODE_PIN, gpiod_async_direction_INPUT, gpiod_async_value_LOW) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for RELAY_CODE_PIN\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (gpiod_async_pin_init(&door_access->event_code_pin, RELAY_CODE_PIN, gpiod_async_direction_INPUT, gpiod_async_value_LOW) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for RELAY_CODE_PIN\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (gpiod_async_pin_init(&door_access->event_pin, GPIO_A, gpiod_async_direction_INPUT, gpiod_async_value_LOW) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for GPIO_A\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (gpiod_async_pin_init(&door_access->event_unlock_pin, GPIO_B, gpiod_async_direction_INPUT, gpiod_async_value_LOW) != 0) {
        fprintf(stderr, "gpiod_async_pin_init failed for GPIO_B\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }

    // Initialize door access structure
    door_access->ctx = gpiod_async_context_new(&gpiod_async_context_options_default);
    if (door_access->ctx == NULL) {
        fprintf(stderr, "gpiod_async_context_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    door_access->event = gpiod_async_event_new(door_access->ctx, "door_access_event");
    if (door_access->event == NULL) {
        fprintf(stderr, "gpiod_async_event_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    door_access->event_lock = gpiod_async_event_new(door_access->ctx, "door_access_lock_event");
    if (door_access->event_lock == NULL) {
        fprintf(stderr, "gpiod_async_event_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    door_access->event_unlock = gpiod_async_event_new(door_access->ctx, "door_access_unlock_event");
    if (door_access->event_unlock == NULL) {
        fprintf(stderr, "gpiod_async_event_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
