    door_access->event_code = gpiod_async_event_new(door_access->ctx, "door_access_code_event");
    if (door_access->event_code == NULL) {
        fprintf(stderr, "gpiod_async_event_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    door_access->event_code_pin = gpiod_async_event_new(door_access->ctx, "door_access_code_pin_event");
