        fprintf(stderr, "gpiod_async_event_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    door_access->event_pin = gpiod_async_event_new(door_access->ctx, "door_access_pin_event");
    if (door_access->event_pin == NULL) {
        fprintf(stderr, "gpiod_async_event_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    door_access->event_unlock_pin = gpiod_async_event_new(door_access->ctx, "door_access_unlock_pin_event");
    if (door_access->event_unlock_pin == NULL) {
        fprintf(stderr, "gpiod_async_event_new failed\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed for SIGINT\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed for SIGTERM\n");
        gpiod_async_cleanup(&door_access->ctx);
        return 1;
    }

    // Initialize door access
    init_door_access(door_access);

    // Main loop
    while (1) {
        // Generate random code
        generate_code(door_access);

        // Read user input
        read_code(door_access);

        // Handle input
        handle_input(door_access);
    }

    // Cleanup
    cleanup(door_access);

    return 0;
}

void init_door_access(door_access_t *door_access) {
    // Set GPIO pins to HIGH
    gpiod_async_pin_set_value(&door_access->event, gpiod_async_value_HIGH);
    gpiod_async_pin_set_value(&door_access->event_lock, gpiod_async_value_HIGH);
    gpiod_async_pin_set_value(&door_access->event_unlock, gpiod_async_value_HIGH);
    gpiod_async_pin_set_value(&door_access->event_unlock_pin, gpiod_async_value_HIGH);
    gpiod_async_pin_set_value(&door_access->event_code_pin, gpiod_async_value_HIGH);
    gpiod_async_pin_set_value(&door_access->event_pin, gpiod_async_value_HIGH);

    // Set up event handlers
    gpiod_async_event_set_callback(&door_access->event, door_access->event_lock, door_access->event_lock_handler);
    gpiod_async_event_set_callback(&door_access->event, door_access->event_unlock, door_access->event_unlock_handler);
    gpiod_async_event_set_callback(&door_access->event, door_access->event_code, door_access->event_code_handler);
    gpiod_async_event_set_callback(&door_access->event, door_access->event_pin, door_access->event_pin_handler);
    gpiod_async_event_set_callback(&door_access->event, door_access->event_unlock_pin, door_access->event_unlock_pin_handler);
}

void lock_door(door_access_t *door_access) {
    // Set GPIO pin to LOW
    gpiod_async_pin_set_value(&door_access->event_lock, gpiod_async_value_LOW);
}

void unlock_door(door_access_t *door_access) {
    // Set GPIO pin to HIGH
    gpiod_async_pin_set_value(&door_access->event_unlock, gpiod_async_value_HIGH);
}

void generate_code(door_access_t *door_access) {
    // Generate random code
    unsigned int code = rand() % (RELAY_CODE_MAX - RELAY_CODE_MIN + 1) + RELAY_CODE_MIN;
    sprintf(door_access->event_code->data, "%06u", code);
    gpiod_async_event_send(&door_access->event_code);
}

void read_code(door_access_t *door_access) {
    // Read user input
    char buffer[RELAY_CODE_BUFFER_SIZE];
    ssize_t bytes_read = read(0, buffer, RELAY_CODE_BUFFER_SIZE);
    if (bytes_read < 0) {
        fprintf(stderr, "read failed\n");
        return;
    }
    buffer[bytes_read] = '\0';
    if (strcmp(buffer, door_access->event_code->data) == 0) {
        // Log successful access
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char log_message[20];
        sprintf(log_message, "%04d-%02d-%02d %02d:%02d:%02d, %06u", time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday, time_info->tm_hour, time_info->tm_min, time_info->tm_sec, code);
        FILE *log_file = fopen("access_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "fopen failed\n");
            return;
        }
        fprintf(log_file, "%s\n", log_message);
        fclose(log_file);
        // Unlock door
        unlock_door(door_access);
    } else {
        // Print access denied message
        printf("Access denied\n");
    }
}

void handle_input(door_access_t *door_access) {
    // Handle input
}

void sig_handler(int sig) {
    // Set volatile flag
    volatile sig_atomic_t flag = 1;
    // Exit main loop
    exit(0);
}

void event_lock_handler(door_access_t *door_access) {
    // Lock door
    lock_door(door_access);
}

void event_unlock_handler(door_access_t *door_access) {
    // Unlock door
    unlock_door(door_access);
}

void event_code_handler(door_access_t *door_access) {
    // Generate new code
    generate_code(door_access);
}

void event_pin_handler(door_access_t *door_access) {
    // Read user input
    read_code(door_access);
}

void event_unlock_pin_handler(door_access_t *door_access) {
    // Unlock door
    unlock_door(door_access);
}

void cleanup(door_access_t *door_access) {
    // Cleanup GPIO pins
    gpiod_async_pin_release(&door_access->event);
    gpiod_async_pin_release(&door_access->event_lock);
    gpiod_async_pin_release(&door_access->event_unlock);
    gpiod_async_pin_release(&door_access->event_unlock_pin);
    gpiod_async_pin_release(&door_access->event_code_pin);
    gpiod_async_pin_release(&door_access->event_pin);

    // Cleanup events
    gpiod_async_event_release(&door_access->event);
    gpiod_async_event_release(&door_access->event_lock);
    gpiod_async_event_release(&door_access->event_unlock);
    gpiod_async_event_release(&door_access->event_code);
    gpiod_async_event_release(&door_access->event_code_pin);
    gpiod_async_event_release(&door_access->event_pin);
    gpiod_async_event_release(&door_access->event_unlock_pin);

    // Cleanup context
    gpiod_async_context_destroy(&door_access->ctx);
}

