    // Set up I2C clock
    if (gpioSetClock(I2C_Bus, 100000) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }

    // Set up I2C address
    if (gpioSetI2CAddress(I2C_Bus, I2C_ADDRESS, 0) < 0) {
        perror("gpioSetI2CAddress");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pin as output
    if (gpioMode(GPIO2, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pin as output
    if (gpioWrite(GPIO2, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read from I2C
        uint8_t data[3];
        if (gpioI2CRead(I2C_Bus, I2C_ADDRESS, data, 3, I2C_TIMEOUT) < 0) {
            perror("gpioI2CRead");
            continue;
