        if (data[0] == 0x55) {
            // Calculate lux value
            uint16_t lux = (data[1] << 8) | data[2];

            // Log reading
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s, %d\n", timestamp, lux);

            // Turn off GPIO pin
            gpioWrite(GPIO2, 1);
        } else {
            // Turn off GPIO pin
            gpioWrite(GPIO2, 1);
        }
    }

    // Clean up
    close(log_fd);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    // Close log file
    close(FILE_NAME);

    // Terminate pigpio
    gpioTerminate();

    // Exit
    exit(0);
}

