#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define I2C_ADDRESS 0x5A
#define I2C Bus 1
#define GPIO_PIN 18
#define PWM_FREQ 440
#define PWM_DUTY 0.5
#define SAMPLE_RATE 20
#define BUFFER_SIZE 100
#define FILE_NAME "frequency_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize MPR121
    if (gpioSetupI2C(I2C Bus, I2C_ADDRESS) < 0) {
        perror("gpioSetupI2C");
        return 1;
    }
    if (gpioSetMode(I2C Bus, I2C_ADDRESS, GPIO_MODE_INPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioPullUp(I2C Bus, I2C_ADDRESS, GPIO_PIN) < 0) {
        perror("gpioPullUp");
        return 1;
    }
    if (gpioSetLevel(I2C Bus, I2C_ADDRESS, GPIO_PIN) < 0) {
        perror("gpioSetLevel");
        return 1;
    }
    if (gpioSoftReset(I2C Bus, I2C_ADDRESS) < 0) {
        perror("gpioSoftReset");
        return 1;
    }
    if (gpioSetConfig(I2C Bus, I2C_ADDRESS, MPR121_CONFIG_2ELECTRODES) < 0) {
        perror("gpioSetConfig");
        return 1;
    }

    // Create socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        return 1;
    }
    if (listen(sock, 3) < 0) {
        perror("listen");
        return 1;
    }

    printf("Listening for incoming connections...\n");

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            perror("accept");
            continue;
        }

        char buffer[BUFFER_SIZE];
        if (recv(client_sock, buffer, BUFFER_SIZE, 0) < 0) {
            perror("recv");
            close(client_sock);
            continue;
        }
        buffer[BUFFER_SIZE - 1] = '\0';
        if (strcmp(buffer, "MOTION_DETECTED:MySecretKey") != 0) {
            close(client_sock);
            continue;
        }

        // Initialize PWM
        if (gpioSetupPWM(GPIO_PIN, PWM_FREQ, PWM_DUTY) < 0) {
            perror("gpioSetupPWM");
            close(client_sock);
            continue;
        }

        // Read touch values
        int touch_values[BUFFER_SIZE];
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (gpioRead(I2C Bus, I2C_ADDRESS, GPIO_PIN, &touch_values[i]) < 0) {
                perror("gpioRead");
                close(client_sock);
                continue;
            }
        }

        // Play tone
        for (int i = 0; i < SAMPLE_RATE; i++) {
            gpioWrite(GPIO_PIN, 1);
            usleep(1000);
            gpioWrite(GPIO_PIN, 0);
            usleep(1000);
        }

        // Log frequency
        FILE *file = fopen(FILE_NAME, "a");
        if (file == NULL) {
            perror("fopen");
            close(client_sock);
            continue;
        }
        fprintf(file, "%d\n", PWM_FREQ);
        fclose(file);

        // Clean up
        gpioCleanUpPWM(GPIO_PIN);
        close(client_sock);
    }

    gpioCleanUp();
    return 0;
}

