#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <syslog.h>
#include <errno.h>

#define I2C_ADDRESS 0x3C
#define I2C_FILE "/dev/i2c-1"
#define LED_GPIO 17
#define LED_PIN 17
#define SAMPLE_INTERVAL 100
#define SAMPLE_SIZE 6

int main(int argc, char **argv) {
    int i2c_fd, gpio_fd;
    int led_gpio;
    int sample_count = 0;
    int sample_value;
    int error = 0;
    struct sigaction sa;

    // Initialize GPIO
    gpio_init();
    gpio_set_mode(LED_PIN, GPIO_MODE_OUTPUT);
    gpio_set_level(LED_PIN, 0);

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGTERM);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C file descriptor
    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C file");
        return 1;
    }

    while (1) {
        // Read from I2C
        if (i2c_read(i2c_fd, I2C_ADDRESS, SAMPLE_SIZE, SAMPLE_SIZE) < SAMPLE_SIZE) {
            error = 1;
            syslog(LOG_ERR, "I2C read error");
            continue;
        }

        // Extract Z-axis magnitude
        sample_value = (i2c_read(i2c_fd, I2C_ADDRESS, 2, 2)[0] << 8) | i2c_read(i2c_fd, I2C_ADDRESS, 2, 2)[1];
        sample_value >>= 2;

        // Update LED brightness
        gpio_write(led_gpio, sample_value);

        // Increment sample count
        sample_count++;

        // Sleep for SAMPLE_INTERVAL ms
        usleep(SAMPLE_INTERVAL * 1000);

        // Check for error
        if (error) {
            break;
        }
    }

    // Clean up
    gpio_close(gpio_fd);
    close(i2c_fd);
    syslog(LOG_INFO, "Exiting");

    return 0;
}

void sigint_handler(int sig) {
    gpio_close(gpio_fd);
    close(i2c_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_close(gpio_fd);
    close(i2c_fd);
    exit(0);
}

