#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

// Define constants
#define I2C_ADDRESS 0x1E
#define SAMPLES 100
#define DELAY 500

// Define structures
typedef struct {
    int32_t x, y, z;
} MagData;

// Function to read raw magnetic field data from HMC5883L
MagData readMagData(pigpio_t *gpio) {
    MagData data;
    uint8_t buffer[6];

    // Read raw data from I2C bus 1
    if (gpio_i2c_read(gpio, I2C_ADDRESS, 0x00, 6, buffer, 0) < 0) {
        fprintf(stderr, "I2C read error\n");
        exit(1);
    }

    // Extract raw data
    data.x = (buffer[0] << 8) | buffer[1];
    data.y = (buffer[2] << 8) | buffer[3];
    data.z = (buffer[4] << 8) | buffer[5];

    return data;
}

// Function to calculate hard-iron offsets
void calculateOffsets(MagData *data, double *offsets) {
    double sumX = 0, sumY = 0, sumZ = 0;
    int count = 0;

    // Calculate running average of last 100 samples
    for (int i = 0; i < SAMPLES; i++) {
        sumX += data[i].x;
        sumY += data[i].y;
        sumZ += data[i].z;
        count++;
    }

    offsets[0] = sumX / count;
    offsets[1] = sumY / count;
    offsets[2] = sumZ / count;
}

// Function to correct magnetic field data with hard-iron offsets
void correctData(MagData *data, double *offsets) {
    data->x -= offsets[0];
    data->y -= offsets[1];
    data->z -= offsets[2];
}

int main() {
    // Initialize GPIO
    pigpio_t *gpio = pigpio_init();
    if (gpio == NULL) {
        fprintf(stderr, "GPIO initialization failed\n");
        exit(1);
    }

    // Initialize I2C
    if (gpio_i2c_init(gpio, 1) < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        exit(1);
    }

    // Allocate memory for offsets
    double offsets[3];
    if (malloc(sizeof(double) * 3) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

