        fprintf(stderr, "I2C initialization failed\n");
        exit(1);
    }

    // Allocate memory for offsets
    double offsets[3];
    if (malloc(sizeof(double) * 3) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize offsets
    calculateOffsets(NULL, offsets);

    // Main loop
    while (1) {
