#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define RELAY1_GPIO 17
#define RELAY2_GPIO 27
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define UART0_PORT 14
#define UART1_PORT 15
#define BAUD 9600
#define READ_TIMEOUT 5
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    // Set relay pins as output
    if (gpioMode(RELAY1_GPIO, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay 1 pin as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(RELAY2_GPIO, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay 2 pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Set relay pins as HIGH
    if (gpioWrite(RELAY1_GPIO, RELAY_HIGH) < 0) {
        fprintf(stderr, "Error setting relay 1 pin HIGH\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY2_GPIO, RELAY_HIGH) < 0) {
        fprintf(stderr, "Error setting relay 2 pin HIGH\n");
        gpioTerminate();
        return 1;
    }

    // Open UART ports
    struct pigpio *uart0 = pigpioOpen(UART0_PORT, PI_RTS, PI_CTS);
    if (uart0 == NULL) {
        fprintf(stderr, "Error opening UART 0\n");
        gpioTerminate();
        return 1;
    }
    struct pigpio *uart1 = pigpioOpen(UART1_PORT, PI_RTS, PI_CTS);
    if (uart1 == NULL) {
        fprintf(stderr, "Error opening UART 1\n");
        pigpioClose(uart0);
        gpioTerminate();
        return 1;
    }

    // Set baud rate and read timeout
    if (uartSetBaud(uart0, BAUD) < 0) {
        fprintf(stderr, "Error setting baud rate for UART 0\n");
        pigpioClose(uart0);
        pigpioClose(uart1);
        gpioTerminate();
        return 1;
    }
    if (uartSetBaud(uart1, BAUD) < 0) {
        fprintf(stderr, "Error setting baud rate for UART 1\n");
        pigpioClose(uart0);
        pigpioClose(uart1);
        gpioTerminate();
        return 1;
    }

    // Set read timeout
    if (uartSetReadTimeout(uart0, READ_TIMEOUT) < 0) {
        fprintf(stderr, "Error setting read timeout for UART 0\n");
        pigpioClose(uart0);
        pigpioClose(uart1);
        gpioTerminate();
        return 1;
    }
    if (uartSetReadTimeout(uart1, READ_TIMEOUT) < 0) {
        fprintf(stderr, "Error setting read timeout for UART 1\n");
        pigpioClose(uart0);
        pigpioClose(uart1);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler\n");
        pigpioClose(uart0);
        pigpioClose(uart1);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigtermHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler\n");
        pigpioClose(uart0);
        pigpioClose(uart1);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        char code0[CODE_LENGTH + 1];
        char code1[CODE_LENGTH + 1];
        int ret0 = uartRead(uart0, code0, CODE_LENGTH + 1, READ_TIMEOUT);
        if (ret0 < 0) {
            fprintf(stderr, "Error reading from UART 0\n");
            break;
        }
        code0[CODE_LENGTH] = '\0';
        int ret1 = uartRead(uart1, code1, CODE_LENGTH + 1, READ_TIMEOUT);
        if (ret1 < 0) {
            fprintf(stderr, "Error reading from UART 1\n");
            break;
        }
        code1[CODE_LENGTH] = '\0';

        // Reset input buffer on non-digit character
        for (int i = 0; i < CODE_LENGTH; i++) {
            if (!isdigit(code0[i])) {
                code0[i] = '\0';
                break;
            }
            if (!isdigit(code1[i])) {
                code1[i] = '\0';
                break;
            }
        }

        // Check if both codes match and are equal to the expected code
        if (strcmp(code0, EXPECTED_CODE) == 0 && strcmp(code1, EXPECTED_CODE) == 0) {
            // Drive both relays HIGH
            gpioWrite(RELAY1_GPIO, RELAY_HIGH);
            gpioWrite(RELAY2_GPIO, RELAY_HIGH);
            usleep(2000000);
            gpioWrite(RELAY1_GPIO, RELAY_LOW);
            gpioWrite(RELAY2_GPIO, RELAY_LOW);
        }
    }

    // Clean up
    pigpioClose(uart0);
    pigpioClose(uart1);
    gpioTerminate();

    return 0;
}

void sigintHandler(int sig) {
    // Force both relays LOW
    gpioWrite(RELAY1_GPIO, RELAY_LOW);
    gpioWrite(RELAY2_GPIO, RELAY_LOW);
    // Close UART ports
    pigpioClose(uart0);
    pigpioClose(uart1);
    // Terminate GPIO
    gpioTerminate();
    // Exit
    exit(0);
}

void sigtermHandler(int sig) {
    // Force both relays LOW
    gpioWrite(RELAY1_GPIO, RELAY_LOW);
    gpioWrite(RELAY2_GPIO, RELAY_LOW);
    // Close UART ports
    pigpioClose(uart0);
    pigpioClose(uart1);
    // Terminate GPIO
    gpioTerminate();
    // Exit
    exit(0);
}

