#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define GPIO_RELAY 17
#define PIR_PIN 0
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define LOG_INFO "Motion detected"
#define LOG_WARNING "Potential malfunction: PIR signal remains HIGH for more than 10 seconds"

int main(int argc, char **argv) {
    int gpio;
    int relay;
    int pir;
    int relay_state = RELAY_LOW;
    int pir_state = 0;
    int last_pir_state = 0;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Initialize GPIO
    if (gpio = pigpio_init()) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %d", gpio);
        return 1;
    }

    // Open GPIO lines
    if (gpio_claim_input(GPIO_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to claim GPIO %d as input: %d", GPIO_PIN, gpio_claim_input(GPIO_PIN));
        pigpio_close(gpio);
        return 1;
    }
    if (gpio_claim_output(GPIO_RELAY, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to claim GPIO %d as output: %d", GPIO_RELAY, gpio_claim_output(GPIO_RELAY));
        pigpio_close(gpio);
        return 1;
    }

    // Set relay initial state
    if (gpio_write(GPIO_RELAY, RELAY_LOW) != 0) {
        syslog(LOG_ERR, "Failed to set relay %d to LOW: %d", GPIO_RELAY, gpio_write(GPIO_RELAY));
        pigpio_close(gpio);
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = motion_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up SIGINT handler: %d", sigaction(SIGINT, &sa, NULL));
        pigpio_close(gpio);
        return 1;
    }
    if (sigaction(SIGTERM, &sa_term, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up SIGTERM handler: %d", sigaction(SIGTERM, &sa_term, NULL));
        pigpio_close(gpio);
        return 1;
    }
    sa_term.sa_handler = shutdown_handler;
    sigemptyset(&sa_term.sa_mask);
    if (sigaction(SIGTERM, &sa_term, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up SIGTERM handler: %d", sigaction(SIGTERM, &sa_term, NULL));
        pigpio_close(gpio);
        return 1;
    }

    // Main loop
    while (1) {
        // Read PIR signal
        if (gpio_read(PIR_PIN) == 1) {
            if (pir_state == 0) {
                pir_state = 1;
                syslog(LOG_INFO, LOG_INFO);
            }
            if (pir_state == 1 && last_pir_state == 0) {
                // Failsafe: de-energize relay
                if (gpio_write(GPIO_RELAY, RELAY_LOW) != 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay %d: %d", GPIO_RELAY, gpio_write(GPIO_RELAY));
                }
                syslog(LOG_WARNING, LOG_WARNING);
                syslog(LOG_INFO, "Shutting down...");
                shutdown_handler();
                return 0;
            }
        } else {
            if (pir_state == 1) {
                pir_state = 0;
                syslog(LOG_INFO, LOG_INFO);
            }
        }
        last_pir_state = pir_state;

        // Activate relay
        if (pir_state == 1) {
            if (gpio_write(GPIO_RELAY, RELAY_HIGH) != 0) {
                syslog(LOG_ERR, "Failed to activate relay %d: %d", GPIO_RELAY, gpio_write(GPIO_RELAY));
            }
            syslog(LOG_INFO, LOG_INFO);
            sleep(1);
            if (gpio_write(GPIO_RELAY, RELAY_LOW) != 0) {
                syslog(LOG_ERR, "Failed to de-energize relay %d: %d", GPIO_RELAY, gpio_write(GPIO_RELAY));
            }
        }

        // Sleep for 50ms
        usleep(50000);
    }

