#define RELAY3_GPIO 27
#define RELAY4_GPIO 22
#define RELAY_COUNT 4
#define RELAY_STATE_OFF 0
#define RELAY_STATE_ON 1
#define RELAY_STATE_ACTIVE 2
#define RELAY_STATE_INACTIVE 3
#define RELAY_STATE_ERROR 4
#define RELAY_STATE_UNKNOWN 5
#define RELAY_STATE Cycling 6
#define RELAY_STATE_ERROR Cycling 7

volatile sig_atomic_t running = 0;

void init_relay(pigpio *gpio) {
    int i;
    for (i = 0; i < RELAY_COUNT; i++) {
        gpio_set_mode(gpio, RELAY_GPIO[i], PI_OUTPUT);
        gpio_set_level(gpio, RELAY_GPIO[i], RELAY_STATE_OFF);
    }
}

void activate_relay(pigpio *gpio, int relay) {
    gpio_set_level(gpio, RELAY_GPIO[relay], RELAY_STATE_ON);
}

void deactivate_relay(pigpio *gpio, int relay) {
    gpio_set_level(gpio, RELAY_GPIO[relay], RELAY_STATE_OFF);
}

