    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
    syslog(LOG_INFO, "irrigation_system: Relay %d: %s", relay, state == RELAY_STATE_ON ? "ON" : "OFF");
}

