    gpio_set_mode(gpio, RELAY_GPIO[2], PI_INPUT);
    gpio_set_mode(gpio, RELAY_GPIO[3], PI_INPUT);
    syslog(LOG_INFO, "irrigation_system: Error");
    exit(1);
}

int main() {
    pigpio *gpio;
    struct itimerval timer;
    struct sigaction sa;

