    if (gpio == NULL) {
        syslog(LOG_ERR, "pigpio_init failed");
        exit(1);
    }

    sa.sa_handler = error_handler;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_relay(gpio);

    timer.it_value.tv_sec = 60;
    timer.it_value.tv_usec = 0;
    timer.it_interval.tv_sec = 60;
    timer.it_interval.tv_usec = 0;
    setitimer(ITIMER_REAL, &timer, NULL);

    while (running) {
        int i;
        for (i = 0; i < RELAY_COUNT; i++) {
            log_state(gpio, i, gpio_get_level(gpio, RELAY_GPIO[i]));
        }
        sleep(1);
    }

    deactivate_relay(gpio, 0);
    deactivate_relay(gpio, 1);
    deactivate_relay(gpio, 2);
    deactivate_relay(gpio, 3);
    gpio_set_mode(gpio, RELAY_GPIO[0], PI_INPUT);
    gpio_set_mode(gpio, RELAY_GPIO[1], PI_INPUT);
    gpio_set_mode(gpio, RELAY_GPIO[2], PI_INPUT);
    gpio_set_mode(gpio, RELAY_GPIO[3], PI_INPUT);
    syslog(LOG_INFO, "irrigation_system: Exit");
    pigpio_close(gpio);
    syslog_close();
    exit(0);
}

