#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/timer.h>
#include <sys/eintrio.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define BUFFER_SIZE 100
#define BUFFER_NAME "/dev/shm/mpu6050_accel"
#define I2C_ADDRESS 0x1D
#define I2C_FILE "/dev/i2c-1"
#define TIMER_NAME "/tmp/mpu6050_timer"
#define SIGEV_SIGNAL SIGEV_SIGNAL

int main() {
    int fd;
    struct mpu6050 *mpu;
    struct mpu6050_config config;
    struct timer *timer;
    void *buffer;
    struct sigaction sa;
    struct sigevent sev;
    int i, j;
    int error;

    // Initialize the I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Initialize the I2C device
    error = i2c_set_frequency(fd, 100000);
    if (error) {
        perror("i2c_set_frequency");
        close(fd);
        return 1;
    }

    // Initialize the MPU6050
    error = i2c_master_start(fd, I2C_ADDRESS);
    if (error) {
        perror("i2c_master_start");
        close(fd);
        return 1;
    }

    // Read the MPU6050 configuration
    error = i2c_master_read(fd, &config);
    if (error) {
        perror("i2c_master_read");
        close(fd);
        return 1;
    }

    // Create a new timer
    timer = timer_create(CLOCK_MONOTONIC, NULL, NULL);
    if (!timer) {
        perror("timer_create");
        close(fd);
        return 1;
    }

    // Set the timer to run every 10 milliseconds
    timer_settime(timer, 0, NULL, NULL);

    // Create a new signal handler for SIGINT and SIGTERM
    sa.sa_handler = sigEV_SIGNAL;
    sa.sa_flags = SA_SIGINFO;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        timer_destroy(timer);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        timer_destroy(timer);
        return 1;
    }

    // Create a new shared memory region
    error = mmap(NULL, BUFFER_SIZE * sizeof(float), PROT_READ | PROT_WRITE, MAP_SHARED, -1, 0);
    if (error) {
        perror("mmap");
        close(fd);
        timer_destroy(timer);
        return 1;
    }

    // Initialize the shared memory region
    buffer = mmap(NULL, BUFFER_SIZE * sizeof(float), PROT_READ | PROT_WRITE, MAP_SHARED, -1, BUFFER_NAME);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        timer_destroy(timer);
        return 1;
    }

    // Initialize the MPU6050
    error = i2c_master_stop(fd);
    if (error) {
        perror("i2c_master_stop");
        munmap(buffer, BUFFER_SIZE * sizeof(float));
        close(fd);
        timer_destroy(timer);
        return 1;
    }

    // Start the timer
    timer_settime(timer, 0, NULL, NULL);

    while (1) {
        // Wait for the timer to trigger
        struct itimerspec ts;
        ts.it_value.tv_sec = 0;
        ts.it_value.tv_nsec = 10000000;
        if (timer_settime(timer, 0, &ts, NULL) < 0) {
            perror("timer_settime");
            break;
        }

        // Read the MPU6050 data
        error = i2c_master_read(fd, &mpu);
        if (error) {
            perror("i2c_master_read");
            break;
        }

        // Store the data in the shared memory region
        for (i = 0; i < BUFFER_SIZE; i++) {
            buffer[i] = mpu->data[i];
        }

        // Update the MPU6050
        error = i2c_master_write(fd, &config, sizeof(mpu6050_config));
        if (error) {
            perror("i2c_master_write");
            break;
        }
    }

    // Clean up
    munmap(buffer, BUFFER_SIZE * sizeof(float));
    close(fd);
    timer_destroy(timer);

    return 0;
}

