#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define GPIO17 17
#define GPIO27 27
#define RELAY_PIN GPIO27
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define DEBOUNCE_TIME 100  // ms
#define LOG_FILE "alarm_log.txt"

// Function to initialize GPIO and relay
void init_gpio_relay() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set GPIO17 as input with pull-up resistor
    if (gpioMode(GPIO17, GPIO_IN) < 0) {
        perror("gpioMode");
        exit(1);
    }

    // Set GPIO27 as output
    if (gpioMode(GPIO27, GPIO_OUT) < 0) {
        perror("gpioMode");
        exit(1);
    }

    // Set GPIO27 as high to ensure relay is off initially
    if (gpioWrite(GPIO27, RELAY_HIGH) < 0) {
        perror("gpioWrite");
        exit(1);
    }
}

// Function to debounce relay activation
void debounce_relay() {
    int debounce_counter = 0;
    int last_state = 0;

    while (1) {
        int current_state = gpioRead(GPIO17);
        if (current_state != last_state) {
            if (current_state == RELAY_HIGH) {
                // Relay is activated, wait for debounce time
                usleep(DEBOUNCE_TIME * 1000);
            } else {
                // Relay is deactivated, reset debounce counter
                debounce_counter = 0;
            }
            last_state = current_state;
        }

        // Check if relay is still activated after debounce time
        if (debounce_counter >= DEBOUNCE_TIME) {
            // Relay is still activated, activate relay
            gpioWrite(GPIO27, RELAY_HIGH);
            debounce_counter = 0;
            // Log timestamp
            time_t now = time(NULL);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                exit(1);
            }
            fprintf(log_file, "%ld\n", now);
            fclose(log_file);
        }
    }
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Turn off relay
    gpioWrite(GPIO27, RELAY_LOW);
    // Deinitialize GPIO
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and relay
    init_gpio_relay();

    // Start debouncing
    debounce_relay();

    return 0;
}

