#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <pigpio.h>
#include <stdint.h>

#define BUFFER_SIZE 100
#define I2C_ADDRESS 0x6B
#define I2C_SPEED 100000

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(2, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(3, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C speed
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create circular buffer
    void* buffer = mmap(NULL, BUFFER_SIZE * sizeof(float), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize buffer
    memset(buffer, 0, BUFFER_SIZE * sizeof(float));

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        munmap(buffer, BUFFER_SIZE * sizeof(float));
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read data from MPU-6050
        unsigned char data[6];
        if (read(fd, data, 6) < 6) {
            perror("read");
            munmap(buffer, BUFFER_SIZE * sizeof(float));
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Convert data to floats
        float x = (data[0] << 8) | data[1];
        float y = (data[2] << 8) | data[3];
        float z = (data[4] << 8) | data[5];

        // Calculate absolute angular velocity
        float vx = sqrt(x * x + y * y + z * z);
        float vy = sqrt(x * x + y * y + z * z);
        float vz = sqrt(x * x + y * y + z * z);

        // Check if absolute angular velocity exceeds 50 degrees/second
        if (vx > 50.0 || vy > 50.0 || vz > 50.0) {
            printf("Angular velocity exceeds 50 degrees/second: %f, %f, %f\n", vx, vy, vz);
        }

        // Write to buffer
        if (write(fd, &vx, sizeof(float)) < 1) {
            perror("write");
            munmap(buffer, BUFFER_SIZE * sizeof(float));
            close(fd);
            gpioTerminate();
            return 1;
        }
        if (write(fd, &vy, sizeof(float)) < 1) {
            perror("write");
            munmap(buffer, BUFFER_SIZE * sizeof(float));
            close(fd);
            gpioTerminate();
            return 1;
        }
        if (write(fd, &vz, sizeof(float)) < 1) {
            perror("write");
            munmap(buffer, BUFFER_SIZE * sizeof(float));
            close(fd);
            gpioTerminate();
            return 1;
        }
    }

    return 0;
}

void sigint_handler(int sig) {
    munmap(buffer, BUFFER_SIZE * sizeof(float));
    close(fd);
    gpioTerminate();
    exit(0);
}

