#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BUFFER_SIZE 100
#define BUFFER_OFFSET 0
#define BUFFER_MAX 100
#define I2C_ADDRESS 0x1D
#define I2C Bus 1
#define GPIO_PIN 17
#define DEVIATION_THRESHOLD 10
#define TARGET_HEADING 90.0

struct buffer {
    float data[BUFFER_MAX];
    int head;
    int tail;
};

struct buffer buffer;

void init_buffer() {
    buffer.head = BUFFER_OFFSET;
    buffer.tail = BUFFER_OFFSET;
}

void write_to_buffer(float value) {
    if (buffer.tail == BUFFER_MAX) {
        buffer.tail = BUFFER_OFFSET;
    }
    buffer.data[buffer.tail] = value;
    buffer.tail++;
}

float read_from_buffer() {
    if (buffer.head == BUFFER_MAX) {
        buffer.head = BUFFER_OFFSET;
    }
    return buffer.data[buffer.head];
}

void handle_i2c_error(int fd) {
    printf("I2C error occurred\n");
    sleep(1);
    return;
}

void handle_sigint(int sig) {
    printf("SIGINT received, exiting\n");
    cleanup();
    exit(0);
}

void handle_sigterm(int sig) {
    printf("SIGTERM received, exiting\n");
    cleanup();
    exit(0);
}

void cleanup() {
    close(I2C_FILE);
    pigpio_close(GPIO_PIN);
    munmap((void *)I2C_MAP, I2C_SIZE);
    close(I2C_FILE);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    sa.sa_handler = handle_sigterm;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    if ((I2C_FILE = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(I2C_FILE, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    if (mmap(I2C_MAP, I2C_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, I2C_FILE, 0) == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    init_buffer();

    while (1) {
        int status;
        unsigned char data[6];
        float x, y, z;
        float sum = 0;
        int count = 0;

        if (read(I2C_FILE, data, 6) < 6) {
            handle_i2c_error(I2C_FILE);
            continue;
        }

        x = (data[0] << 8) | data[1];
        y = (data[2] << 8) | data[3];
        z = (data[4] << 8) | data[5];

        x -= 100;
        y -= -50;

        sum += x;
        sum += y;

        if (sum > 0) {
            sum = 0;
        }

        if (sum > 0) {
            sum = 0;
        }

        x = (sum / 2) * 180 / (x * 0.00024414);

        if (x > 360) {
            x -= 360;
        }

        if (x < 0) {
            x += 360;
        }

        if (abs(x - TARGET_HEADING) > DEVIATION_THRESHOLD) {
            pigpio_write(GPIO_PIN, 1);
        } else {
            pigpio_write(GPIO_PIN, 0);
        }

        write_to_buffer(x);

        sleep(0.1);
    }

    cleanup();

    return 0;
}

