#define BH1750_ADDRESS 0x23
#define RELAY_RED 17
#define RELAY_GREEN 27
#define RELAY_BLUE 22
#define RELAY_ON 1
#define RELAY_OFF 0
#define DELAY 120
#define LOG_FILE "lighting_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus parameters
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Read BH1750 register
    unsigned char data[3];
    if (read(fd, data, 3) != 3) {
        perror("read");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Check if sensor is present
    if (data[0] != 0xFF) {
        perror("BH1750 sensor not found");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Wait for 120ms
    usleep(120 * 1000);

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read BH1750 register
        if (read(fd, data, 3) != 3) {
            perror("read");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Check if sensor is present
        if (data[0] != 0xFF) {
            perror("BH1750 sensor not found");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Calculate lux value
        unsigned int lux = (data[1] << 8) | data[2];

        // Log data
        fprintf(log_fd, "%d %d %d %d %d %d\n",
                (unsigned long)time(NULL),
                lux,
                (lux < 50 ? RELAY_RED : (lux < 150 ? RELAY_GREEN : RELAY_BLUE)),
                (lux < 50 ? RELAY_OFF : (lux < 150 ? RELAY_OFF : RELAY_OFF)),
                (lux < 50 ? RELAY_OFF : (lux < 150 ? RELAY_OFF : RELAY_OFF)),
                (lux < 50 ? RELAY_OFF : (lux < 150 ? RELAY_OFF : RELAY_OFF)));

        // Set relay states
        gpioWrite(RELAY_RED, lux < 50 ? RELAY_ON : RELAY_OFF);
        gpioWrite(RELAY_GREEN, lux < 150 ? RELAY_ON : RELAY_OFF);
        gpioWrite(RELAY_BLUE, lux < 300 ? RELAY_ON : RELAY_OFF);

        // Wait for 1 second
        sleep(1);

        // Wait for 120ms
        usleep(120 * 1000);
    }

    // Close log file
    close(log_fd);

    // Release I2C file descriptor
    close(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

