// Define constants
#define DISTANCE_MIN 10
#define DISTANCE_MAX 100
#define PWM_FREQ 1000
#define PWM_MAX 255
#define PWM_MIN 0

// Define motor pins
#define MOTOR_A_IN1 GPIO_BCM_17
#define MOTOR_A_IN2 GPIO_BCM_18
#define MOTOR_A_IN3 GPIO_BCM_22
#define MOTOR_A_IN4 GPIO_BCM_23
#define MOTOR_B_IN1 GPIO_BCM_17
#define MOTOR_B_IN2 GPIO_BCM_18
#define MOTOR_B_IN3 GPIO_BCM_22
#define MOTOR_B_IN4 GPIO_BCM_23

// Define motor driver
#define L298N_BASE 0x06

// Define motor control functions
void motor_control(int motor, int direction, int pwm_value) {
    int reg = L298N_BASE;
    int in1 = (motor == 0) ? MOTOR_A_IN1 : MOTOR_B_IN1;
    int in2 = (motor == 0) ? MOTOR_A_IN2 : MOTOR_B_IN2;
    int in3 = (motor == 0) ? MOTOR_A_IN3 : MOTOR_B_IN3;
    int in4 = (motor == 0) ? MOTOR_A_IN4 : MOTOR_B_IN4;

    // Set direction
    if (direction == 0) {
        gpioWrite(in1, 1);
        gpioWrite(in3, 1);
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in3, 0);
    }

    // Set PWM
    gpioWrite(in2, 1);
    gpioWrite(in4, 1);
    gpioWrite(in2, pwm_value);
    gpioWrite(in4, pwm_value);
}

// Define main function
int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set PWM frequency
    gpioSetMode(MOTOR_A_IN2, PI_REVEY);
    gpioSetMode(MOTOR_A_IN4, PI_REVEY);
    gpioSetMode(MOTOR_B_IN2, PI_REVEY);
    gpioSetMode(MOTOR_B_IN4, PI_REVEY);
    gpioSet PWM(MOTOR_A_IN2, PWM_FREQ, PWM_MAX);
    gpioSet PWM(MOTOR_A_IN4, PWM_FREQ, PWM_MAX);
    gpioSet PWM(MOTOR_B_IN2, PWM_FREQ, PWM_MAX);
    gpioSet PWM(MOTOR_B_IN4, PWM_FREQ, PWM_MAX);

    // Define signal handlers
    signal(SIGINT, motor_stop);
    signal(SIGTERM, motor_stop);

    // Define main loop
    while (1) {
        // Read distance values
        int distance_a = 50;
        int distance_b = 50;
        if (gpioRead(MOTOR_A_IN1) == 0 && gpioRead(MOTOR_A_IN3) == 0) {
            distance_a = 100;
        }
        if (gpioRead(MOTOR_B_IN1) == 0 && gpioRead(MOTOR_B_IN3) == 0) {
            distance_b = 100;
        }

        // Calculate PWM values
        int pwm_a = (distance_a - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * PWM_MAX;
        int pwm_b = (distance_b - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * PWM_MAX;

        // Control motors
        motor_control(0, (distance_a < DISTANCE_MIN) ? 0 : 1, pwm_a);
        motor_control(1, (distance_b < DISTANCE_MIN) ? 0 : 1, pwm_b);

        // Sleep
        usleep(100000);
    }

    // Clean up
    gpioCleanse();
    gpioTerminate();
    return 0;
}

// Define signal handler
void motor_stop(int sig) {
    // Clean up
    gpioCleanse();
    gpioTerminate();

    // Stop motors
    motor_control(0, 0, 0);
    motor_control(1, 0, 0);

    // Exit
    exit(0);
}

