    // Set PWM
    gpioWrite(in2, 1);
    gpioWrite(in4, 1);
    gpioWrite(in2, pwm_value);
    gpioWrite(in4, pwm_value);
}

// Define main function
int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set PWM frequency
    gpioSetMode(MOTOR_A_IN2, PI_REVEY);
    gpioSetMode(MOTOR_A_IN4, PI_REVEY);
    gpioSetMode(MOTOR_B_IN2, PI_REVEY);
    gpioSetMode(MOTOR_B_IN4, PI_REVEY);
    gpioSet PWM(MOTOR_A_IN2, PWM_FREQ, PWM_MAX);
    gpioSet PWM(MOTOR_A_IN4, PWM_FREQ, PWM_MAX);
    gpioSet PWM(MOTOR_B_IN2, PWM_FREQ, PWM_MAX);
    gpioSet PWM(MOTOR_B_IN4, PWM_FREQ, PWM_MAX);

    // Define signal handlers
    signal(SIGINT, motor_stop);
    signal(SIGTERM, motor_stop);

    // Define main loop
    while (1) {
        // Read distance values
        int distance_a = 50;
        int distance_b = 50;
        if (gpioRead(MOTOR_A_IN1) == 0 && gpioRead(MOTOR_A_IN3) == 0) {
            distance_a = 100;
        }
        if (gpioRead(MOTOR_B_IN1) == 0 && gpioRead(MOTOR_B_IN3) == 0) {
            distance_b = 100;
        }

        // Calculate PWM values
        int pwm_a = (distance_a - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * PWM_MAX;
        int pwm_b = (distance_b - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * PWM_MAX;

        // Control motors
        motor_control(0, (distance_a < DISTANCE_MIN) ? 0 : 1, pwm_a);
        motor_control(1, (distance_b < DISTANCE_MIN) ? 0 : 1, pwm_b);

        // Sleep
        usleep(100000);
    }

    // Clean up
    gpioCleanse();
    gpioTerminate();
    return 0;
}

// Define signal handler
void motor_stop(int sig) {
    // Clean up
    gpioCleanse();
    gpioTerminate();

    // Stop motors
    motor_control(0, 0, 0);
    motor_control(1, 0, 0);

    // Exit
    exit(0);
}
