#define I2C_ADDRESS 0x6B
#define I2C_ADDRESS2 0x68
#define GPIO_SDA 2
#define GPIO_SCL 3
#define GPIO_PWM 18
#define PWM_CHANNEL 0
#define PWM_FREQ 50
#define PWM_MIN 0
#define PWM_MAX 100
#define LOG_FILE "solar_tracker.log"

// Structure to hold MPU6050 data
typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
    int16_t gx;
    int16_t gy;
    int16_t gz;
} mpu6050_data;

// Function to read MPU6050 data
mpu6050_data read_mpu6050_data(int fd) {
    mpu6050_data data;
    char buf[6];
    int ret = ioctl(fd, I2C_RDWR, (void*)buf, sizeof(buf));
    if (ret < 0) {
        if (errno == EIO) {
            // Exponential backoff for I2C errors
            usleep(1000);
            return read_mpu6050_data(fd);
        } else {
            perror("ioctl");
            exit(1);
        }
    }
    memcpy(&data, buf, sizeof(data));
    return data;
}

// Function to compute pitch and roll
void compute_pitch_roll(mpu6050_data data) {
    float pitch = atan2(data.ay, sqrt(pow(data.ax, 2) + pow(data.az, 2)));
    float roll = atan2(data.ax, sqrt(pow(data.ay, 2) + pow(data.az, 2)));
    printf("%f,%f,%f\n", pitch, roll, data.gy);
}

// Function to adjust servo motor angle
void adjust_servo_angle(pigpio *gpio) {
    int ret = gpio_set PWM(gpio, PWM_CHANNEL, PWM_FREQ, PWM_MIN + (PWM_MAX - PWM_MIN) * data.gy / 100);
    if (ret < 0) {
        perror("gpio_set PWM");
        exit(1);
    }
}

int main(int argc, char **argv) {
    // Initialize pigpio
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        exit(1);
    }

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Set I2C address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        exit(1);
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS2);
    if (ret < 0) {
        perror("ioctl");
        exit(1);
    }

    // Read MPU6050 data
    mpu6050_data data = read_mpu6050_data(fd);

    // Compute pitch and roll
    compute_pitch_roll(data);

    // Adjust servo motor angle
    adjust_servo_angle(gpio);

    // Log data to file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(log_file, "%d,%d,%d,%d\n", (int)data.ax, (int)data.ay, (int)data.az, (int)data.gy);
    fclose(log_file);

    // Clean up
    close(fd);
    pigpio_close(gpio);

    return 0;
}

