#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22
#define FADE_TIME 1800  // 30 minutes
#define FADE_RATE 100  // 100 Hz
#define RELAY_ON 1
#define RELAY_OFF 0

// Define a structure to hold the schedule
typedef struct {
    int hour;
    int minute;
    int second;
    int relay;
    int on;
} ScheduleEntry;

// Function to read the schedule file
ScheduleEntry* read_schedule(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening schedule file");
        return NULL;
    }

    ScheduleEntry* schedule = malloc(sizeof(ScheduleEntry));
    if (schedule == NULL) {
        fclose(file);
        return NULL;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, ":;");
        if (token == NULL) {
            fclose(file);
            free(schedule);
            return NULL;
        }

        char* time_str = strtok(NULL, ":;");
        if (time_str == NULL) {
            fclose(file);
            free(schedule);
            return NULL;
        }

        int hour = atoi(token);
        int minute = atoi(strtok(NULL, ";"));
        int second = atoi(strtok(NULL, ";"));
        int relay = atoi(strtok(NULL, ";"));
        int on = atoi(strtok(NULL, ";"));

        schedule->hour = hour;
        schedule->minute = minute;
        schedule->second = second;
        schedule->relay = relay;
        schedule->on = on;

        if (schedule->hour < 0 || schedule->hour > 23 || schedule->minute < 0 || schedule->minute > 59 || schedule->second < 0 || schedule->second > 59) {
            fclose(file);
            free(schedule);
            return NULL;
        }
    }

    fclose(file);
    return schedule;
}

// Function to fade a relay
void fade_relay(int relay, int on) {
    int duty_cycle = (on ? FADE_RATE : 0);
    int prev_duty_cycle = 0;

    while (duty_cycle != prev_duty_cycle) {
        int current_duty_cycle = (int)((duty_cycle + prev_duty_cycle) / 2);
        if (current_duty_cycle < FADE_RATE) {
            gpio_set PWM(relay, current_duty_cycle, FADE_RATE);
        } else {
            gpio_set PWM(relay, FADE_RATE, current_duty_cycle);
        }

        prev_duty_cycle = current_duty_cycle;
        usleep(100000); // 100 ms
    }

    gpio_set PWM(relay, on ? FADE_RATE : 0, FADE_RATE);
}

// Function to turn on a relay
void turn_on_relay(int relay) {
    gpio_set PWM(relay, FADE_RATE, FADE_RATE);
}

// Function to turn off a relay
void turn_off_relay(int relay) {
    gpio_set PWM(relay, 0, FADE_RATE);
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    turn_off_relay(RELAY1);
    turn_off_relay(RELAY2);
    turn_off_relay(RELAY3);
    turn_off_relay(RELAY4);
    gpio.cleanup();
    exit(0);
}

// Function to handle the SIGTERM signal
void sigterm_handler(int sig) {
    turn_off_relay(RELAY1);
    turn_off_relay(RELAY2);
    turn_off_relay(RELAY3);
    turn_off_relay(RELAY4);
    gpio.cleanup();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Error initializing GPIO");
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Read the schedule
    ScheduleEntry* schedule = read_schedule("lighting_schedule.txt");
    if (schedule == NULL) {
        printf("Error reading schedule file\n");
        return 1;
    }

    // Set up GPIO for relays
    if (gpioSetMode(RELAY1, GPIO_MODE PWM) < 0) {
        perror("Error setting GPIO mode");
        return 1;
    }
    if (gpioSetMode(RELAY2, GPIO_MODE PWM) < 0) {
        perror("Error setting GPIO mode");
        return 1;
    }
    if (gpioSetMode(RELAY3, GPIO_MODE PWM) < 0) {
        perror("Error setting GPIO mode");
        return 1;
    }
    if (gpioSetMode(RELAY4, GPIO_MODE PWM) < 0) {
        perror("Error setting GPIO mode");
        return 1;
    }

    // Main loop
    while (1) {
        time_t now = time(NULL);
        int hour = now % 24;
        int minute = now % 60;
        int second = now % 60;

        for (int i = 0; i < 4; i++) {
            if (schedule->hour == hour && schedule->minute == minute && schedule->second == second) {
                if (schedule->on) {
                    turn_on_relay(i + 1);
                } else {
                    turn_off_relay(i + 1);
                }
            } else {
                turn_off_relay(i + 1);
            }
        }

        // Check if it's time to fade
        if (hour != schedule->hour || minute != schedule->minute || second != schedule->second) {
            fade_relay(RELAY1, schedule->on);
            fade_relay(RELAY2, schedule->on);
            fade_relay(RELAY3, schedule->on);
            fade_relay(RELAY4, schedule->on);
        }

        usleep(1000000); // 1 second
    }

    // Clean up
    gpioCleanup();
    free(schedule);
    return 0;
}

