// Define constants
#define TRIGGER_PIN BCM_23
#define ECHO_PIN BCM_24
#define BUZZER_PIN BCM_18
#define MIN_BUZZER_FREQ 100
#define MAX_BUZZER_FREQ 20000
#define TRIGGER_DURATION_US 10
#define MEASUREMENT_INTERVAL_MS 60
#define MAX_MEASUREMENT_INTERVAL_MS 1000

// Define the structure for the HC-SR04 driver
typedef struct {
    pigpio *gpio;
    int trigger_pin;
    int echo_pin;
    int buzzer_pin;
} hc_sr04_t;

// Function to initialize the HC-SR04 driver
hc_sr04_t* hc_sr04_init(pigpio *gpio) {
    hc_sr04_t *driver = malloc(sizeof(hc_sr04_t));
    if (!driver) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    driver->gpio = gpio;
    driver->trigger_pin = gpio_get_pin(TRIGGER_PIN);
    driver->echo_pin = gpio_get_pin(ECHO_PIN);
    driver->buzzer_pin = gpio_get_pin(BUZZER_PIN);

    if (gpio_initialise(driver->trigger_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to initialize trigger pin %d\n", driver->trigger_pin);
        free(driver);
        return NULL;
    }

    if (gpio_initialise(driver->echo_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to initialize echo pin %d\n", driver->echo_pin);
        gpio_destroy(driver->trigger_pin);
        free(driver);
        return NULL;
    }

    if (gpio_initialise(driver->buzzer_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to initialize buzzer pin %d\n", driver->buzzer_pin);
        gpio_destroy(driver->trigger_pin);
        gpio_destroy(driver->echo_pin);
        free(driver);
        return NULL;
    }

    return driver;
}

// Function to deinitialize the HC-SR04 driver
void hc_sr04_destroy(hc_sr04_t *driver) {
    if (driver) {
        gpio_destroy(driver->buzzer_pin);
        gpio_destroy(driver->echo_pin);
        gpio_destroy(driver->trigger_pin);
        free(driver);
    }
}

// Function to measure the distance using the HC-SR04 driver
float hc_sr04_measure(hc_sr04_t *driver) {
    int state = gpio_get_level(driver->echo_pin);
    if (state != 0) {
        return -1; // Error: no echo detected
    }

    gpio_trigger(driver->trigger_pin, PI_HIGH, TRIGGER_DURATION_US);
    usleep(TRIGGER_DURATION_US * 1000);
    state = gpio_get_level(driver->echo_pin);
    if (state == 0) {
        return -1; // Error: no echo detected
    }

    int duration = gpio_get_level(driver->echo_pin) == 0 ? 0 : gpio_get_level(driver->echo_pin) * 1000;
    return duration / 2.0;
}

// Function to generate a PWM signal on the buzzer pin
void hc_sr04_buzz(hc_sr04_t *driver, float frequency) {
    int duty_cycle = (int)(frequency * 1000);
    int value = (duty_cycle > MAX_BUZZER_FREQ) ? MAX_BUZZER_FREQ : (duty_cycle < MIN_BUZZER_FREQ) ? MIN_BUZZER_FREQ : duty_cycle;
    gpio_set_level(driver->buzzer_pin, value);
}

int main(int argc, char **argv) {
    pigpio *gpio = pigpio_init();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    hc_sr04_t *driver = hc_sr04_init(gpio);
    if (!driver) {
        pigpio_destroy(gpio);
        return 1;
    }

    float last_measurement = 0;
    float last_buzz_frequency = 0;
    int measurement_interval = MEASUREMENT_INTERVAL_MS;

    signal(SIGINT, SIG_IGN);

    while (1) {
        float measurement = hc_sr04_measure(driver);
        if (measurement < 0) {
            fprintf(stderr, "Error: measurement failed\n");
            continue;
        }

        float frequency = 1 / (measurement / 2.0 / 1000.0);
        if (frequency < MIN_BUZZER_FREQ || frequency > MAX_BUZZER_FREQ) {
            fprintf(stderr, "Error: invalid frequency %f\n", frequency);
            continue;
        }

        if (frequency != last_buzz_frequency) {
            last_buzz_frequency = frequency;
            hc_sr04_buzz(driver, frequency);
        }

        float current_time = time(NULL);
        if (current_time - last_measurement > measurement_interval) {
            last_measurement = current_time;
            measurement_interval = (int)(current_time % 1000) > 500 ? MAX_MEASUREMENT_INTERVAL_MS : MEASUREMENT_INTERVAL_MS;
        }

        usleep(measurement_interval * 1000);
    }

    hc_sr04_destroy(driver);
    pigpio_destroy(gpio);
    return 0;
}

