// Define the GPIO pins for the RGB LED
#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

// Define the PWM frequency
#define PWM_FREQ 1000

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Turn off the LED and release the PWM resources
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    pigpio_close(RED_PIN);
    pigpio_close(GREEN_PIN);
    pigpio_close(BLUE_PIN);
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (pigpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpio_geterror());
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Set up the PWM for the red, green, and blue channels
    if (pigpio_pwm_open(RED_PIN, PWM_FREQ, PI_RISING, NULL) < 0) {
        fprintf(stderr, "Error opening PWM for red channel: %s\n", pigpio_geterror());
        pigpio_close(RED_PIN);
        return 1;
    }
    if (pigpio_pwm_open(GREEN_PIN, PWM_FREQ, PI_RISING, NULL) < 0) {
        fprintf(stderr, "Error opening PWM for green channel: %s\n", pigpio_geterror());
        pigpio_close(RED_PIN);
        pigpio_close(GREEN_PIN);
        return 1;
    }
    if (pigpio_pwm_open(BLUE_PIN, PWM_FREQ, PI_RISING, NULL) < 0) {
        fprintf(stderr, "Error opening PWM for blue channel: %s\n", pigpio_geterror());
        pigpio_close(RED_PIN);
        pigpio_close(GREEN_PIN);
        pigpio_close(BLUE_PIN);
        return 1;
    }

    // Define the time step for the simulation
    const int TIME_STEP = 100;

    // Define the maximum and minimum values for the color
    const float MAX_VALUE = 1.0f;
    const float MIN_VALUE = 0.0f;

    // Define the current color value
    float current_value = MIN_VALUE;

    while (1) {
        // Update the color value
        current_value = sinf((float)time(NULL) * 2 * 3.14159265359f / TIME_STEP) * (MAX_VALUE - MIN_VALUE) + MIN_VALUE;

        // Set the PWM values for the red, green, and blue channels
        if (pigpio_pwm_write(RED_PIN, (uint32_t)(current_value * 255)) < 0) {
            fprintf(stderr, "Error writing PWM for red channel: %s\n", pigpio_geterror());
            pigpio_close(RED_PIN);
            pigpio_close(GREEN_PIN);
            pigpio_close(BLUE_PIN);
            return 1;
        }
        if (pigpio_pwm_write(GREEN_PIN, (uint32_t)(current_value * 255)) < 0) {
            fprintf(stderr, "Error writing PWM for green channel: %s\n", pigpio_geterror());
            pigpio_close(RED_PIN);
            pigpio_close(GREEN_PIN);
            pigpio_close(BLUE_PIN);
            return 1;
        }
        if (pigpio_pwm_write(BLUE_PIN, (uint32_t)(current_value * 255)) < 0) {
            fprintf(stderr, "Error writing PWM for blue channel: %s\n", pigpio_geterror());
            pigpio_close(RED_PIN);
            pigpio_close(GREEN_PIN);
            pigpio_close(BLUE_PIN);
            return 1;
        }

        // Sleep for the time step
        usleep(TIME_STEP * 1000);
    }

    // Turn off the LED and release the PWM resources
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    pigpio_close(RED_PIN);
    pigpio_close(GREEN_PIN);
    pigpio_close(BLUE_PIN);

    // Clean up
    pigpio_close(RED_PIN);
    pigpio_close(GREEN_PIN);
    pigpio_close(BLUE_PIN);
    pigpioTerminate();
    return 0;
}

