volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main(int argc, char *argv[]) {
    int gpio_fd;
    int poll_timeout = DEFAULT_POLL_TIMEOUT;
    struct timespec last_event[MAX_EVENTS];
    int num_events = 0;
    int event_count = 0;
    struct timespec current_time;

    // Install SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open log file
    int log_fd = open(LOG_FILE, LOG_FILE_MODE, LOG_FILE_PERMS);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Open GPIO pin
    gpio_fd = gpioGetConsequentFd(GPIO_PIN);
    if (gpio_fd < 0) {
        perror("gpioGetConsequentFd");
        return 1;
    }

    // Set GPIO pin as output
    if (gpioMode(GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        return 1;
    }

    // Set GPIO pin high
    if (gpioWrite(GPIO_PIN, 1) < 0) {
        perror("gpioWrite");
        return 1;
    }

    while (!exit_flag) {
        // Poll for edge events
        struct timespec start_time = clock_gettime(CLOCK_MONOTONIC);
        int result = gpioGetEdge(GPIO_PIN, GPIO_EDGE_BOTH, poll_timeout, &last_event[num_events], &num_events);
        if (result < 0) {
            perror("gpioGetEdge");
            continue;
        }

        // Check for three or more consecutive events
        for (int i = 0; i < num_events; i++) {
            if (last_event[i] > start_time) {
                event_count++;
                if (event_count >= 3) {
                    printf("EARTHQUAKE ALERT\n");
                    printf("%s\n", ctime(&current_time));
                    for (int j = 0; j < num_events; j++) {
                        fprintf(log_fd, "%ld %d\n", current_time.tv_sec, last_event[j]);
                    }
                    fflush(log_fd);
                    event_count = 0;
                }
            } else {
                event_count = 0;
            }
        }

        // Log each event
        for (int i = 0; i < num_events; i++) {
            if (last_event[i] > start_time) {
                fprintf(log_fd, "%ld %d\n", current_time.tv_sec, last_event[i]);
                fflush(log_fd);
            }
        }

        // Sleep for a short period to avoid busy-waiting
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000;
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    if (close(log_fd) < 0) {
        perror("close");
    }

    // Release GPIO pin
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        perror("gpioWrite");
    }

    // Close GPIO pin
    if (gpioClose(gpio_fd) < 0) {
        perror("gpioClose");
    }

    return 0;
}

