    gpioSetMode(GPIO_PIN, GPIO_MODE_INPUT);
    gpioPullUpDowntime(GPIO_PIN, GPIO_FLOATING);
}

// Initialize the relay
void init_relay() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }
    if (gpioSetMode(GPIO_RELAY, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set relay mode");
        exit(1);
    }
    gpioSetLevel(GPIO_RELAY, 0);
}

// Read the touch sensor
int read_touch() {
    int value = gpioGet(GPIO_PIN);
    if (value == 1) {
        return 1;
    } else {
        return 0;
    }
}

// Debounce the touch sensor
void debounce() {
    time_t now = time(NULL);
    if (now - relay_state.last_touch > DEBOUNCE_TIME) {
        relay_state.last_touch = now;
        return;
    }
}

// Toggle the relay
void toggle_relay() {
    gpioSetLevel(GPIO_RELAY, !relay_state.relay_state);
    relay_state.relay_state = !relay_state.relay_state;
}

// Log the relay state
void log_relay_state() {
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
    char json[1024];
    json_cJSONAddString(json, "relay_state", relay_state.relay_state ? "ON" : "OFF");
    json_cJSONAddString(json, "timestamp", timestamp);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(1);
    }
    fwrite(json, strlen(json), 1, log_file);
    fclose(log_file);
}

// Handle SIGINT
void sigint_handler(int sig) {
    gpioSetLevel(GPIO_RELAY, 0);
    log_relay_state();
    gpioCleanUp();
    exit(0);
}

int main() {
    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO and relay
    init_gpio();
    init_relay();

    // Initialize the relay state
    relay_state.last_touch = time(NULL);

    while (1) {
        // Read the touch sensor
        int touch = read_touch();
        debounce();

        // Toggle the relay if the touch sensor is pressed
        if (touch == 1) {
            toggle_relay();
        }

        // Log the relay state
        log_relay_state();
    }

    // Log the final relay state
    log_relay_state();

    // Clean up
    gpioCleanUp();

    return 0;
}
