#include <pigpio.h>

#define VALVE_SERVO_GPIO 17
#define NOZZLE_SERVO_GPIO 18
#define VALVE_SERVO_ANGLE 90
#define NOZZLE_SERVO_ANGLES 5
#define VALVE_SERVO_PULSE_WIDTH 1500
#define NOZZLE_SERVO_PULSES 5
#define VALVE_SERVO_MIN_PULSE_WIDTH 500
#define NOZZLE_SERVO_MAX_PULSE_WIDTH 2500
#define VALVE_SERVO_MAX_ERROR 100
#define NOZZLE_SERVO_MAX_ERROR 100
#define VALVE_SERVO CycleTime 1
#define NOZZLE_SERVO_HOLD_TIME 5
#define VALVE_SERVO_CLOSE_PULSE_WIDTH 500

volatile sig_atomic_t sig_atomic_val = 0;

void sig_handler(int sig) {
    gpioStop(VALVE_SERVO_GPIO);
    gpioStop(NOZZLE_SERVO_GPIO);
    pigpio_cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    pigpio = gpioInit();
    if (pigpio == -1) {
        perror("gpioInit");
        exit(1);
    }

    gpioModeSetup(VALVE_SERVO_GPIO, PI_OUTPUT);
    gpioModeSetup(NOZZLE_SERVO_GPIO, PI_OUTPUT);

    int moisture = 20;
    while (1) {
        if (moisture < 50) {
            int valveOpen = gpioGet(VALVE_SERVO_GPIO);
            if (valveOpen == -1) {
                perror("gpioGet");
                continue;
            }
            if (valveOpen != 0) {
                printf("Error opening valve\n");
                syslog(LOG_CRIT, "Error opening valve");
                continue;
            }

            int nozzleOpen = gpioGet(NOZZLE_SERVO_GPIO);
            if (nozzleOpen == -1) {
                perror("gpioGet");
                continue;
            }
            if (nozzleOpen != 0) {
                printf("Error opening nozzle\n");
                syslog(LOG_CRIT, "Error opening nozzle");
                continue;
            }

            for (int i = 0; i < NOZZLE_SERVO_ANGLES; i++) {
                int pulseWidth = VALVE_SERVO_PULSE_WIDTH + (VALVE_SERVO_PULSE_WIDTH * i / (NOZZLE_SERVO_ANGLES - 1));
                if (gpioWrite(NOZZLE_SERVO_GPIO, pulseWidth) == -1) {
                    perror("gpioWrite");
                    continue;
                }
                usleep(VALVE_SERVO CycleTime * 1000000);
                usleep(NOZZLE_SERVO_HOLD_TIME * 1000000);
            }

            int pulseWidth = VALVE_SERVO_CLOSE_PULSE_WIDTH;
            if (gpioWrite(NOZZLE_SERVO_GPIO, pulseWidth) == -1) {
                perror("gpioWrite");
                continue;
            }
            usleep(VALVE_SERVO CycleTime * 1000000);
        }

        moisture = (moisture + 20) % 100;
        usleep(VALVE_SERVO CycleTime * 1000000);
    }

    gpioStop(VALVE_SERVO_GPIO);
    gpioStop(NOZZLE_SERVO_GPIO);
    pigpio = NULL;

    return 0;
}

