#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x1D
#define I2C Bus 1
#define GPIO_SDA 2
#define GPIO_SCL 3
#define SAMPLE_RATE 10
#define FILE_NAME "gyro_log.txt"

// Install signal handlers
void sigint_handler(int sig) {
    close(gpioGetFd());
    close(i2cGetFd());
    exit(0);
}

void sigterm_handler(int sig) {
    close(gpioGetFd());
    close(i2cGetFd());
    exit(0);
}

// Initialize GPIO and I2C
int gpioInit() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
    if (gpioSetMode(GPIO_SDA, GPIO_MODE_INPUT) < 0) {
        perror("gpioSetMode");
        exit(1);
    }
    if (gpioSetMode(GPIO_SCL, GPIO_MODE_INPUT) < 0) {
        perror("gpioSetMode");
        exit(1);
    }
    return 0;
}

int i2cInit() {
    int fd = i2cGetFd(I2C Bus);
    if (fd < 0) {
        perror("i2cGetFd");
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        exit(1);
    }
    return fd;
}

// Read data from the MPU-6050
void readData(int fd) {
    unsigned char data[6];
    if (read(fd, data, 6) != 6) {
        perror("read");
        return;
    }
    unsigned short ax = (data[0] << 8) | data[1];
    unsigned short ay = (data[2] << 8) | data[3];
    unsigned short az = (data[4] << 8) | data[5];
    printf("%f,%f,%f\n", (double)ax / 16384.0, (double)ay / 16384.0, (double)az / 16384.0);
}

// Main loop
int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    if (gpioInit() < 0) {
        perror("gpioInit");
        exit(1);
    }
    if (i2cInit() < 0) {
        perror("i2cInit");
        exit(1);
    }

    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("fopen");
        exit(1);
    }

    struct timespec start;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        readData(i2cGetFd());
        clock_gettime(CLOCK_MONOTONIC, &start);
        usleep(1000000 / SAMPLE_RATE);
    }

    fclose(file);
    return 0;
}

