    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("fopen");
        exit(1);
    }

    struct timespec start;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        readData(i2cGetFd());
        clock_gettime(CLOCK_MONOTONIC, &start);
        usleep(1000000 / SAMPLE_RATE);
    }

    fclose(file);
    return 0;
}
