#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <errno.h>

#define GPIO17 17
#define GPIO18 18
#define TRIGGER_PIN GPIO17
#define ECHO_PIN GPIO18
#define TRIGGER_LEVEL 3.3
#define ECHO_LEVEL 0.5
#define SAMPLE_INTERVAL 1000
#define TIMEOUT 50
#define DELAY 60
#define LOG_FILE "distance_log.txt"

int main() {
    int fd;
    int gpio;
    int trigger_state;
    int echo_state;
    unsigned long last_sample;
    struct timespec start;
    struct timespec end;
    struct timespec sleep_time;
    struct stat sb;
    struct sigaction sa;
    int ret;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    // Set up GPIO pins
    ret = gpio_set_mode(TRIGGER_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return 1;
    }
    ret = gpio_set_level(TRIGGER_PIN, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO level\n");
        return 1;
    }
    ret = gpio_set_mode(ECHO_PIN, PI_INPUT, PI_INPUT_PULSE, PI_INPUT_ACTIVE_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return 1;
    }

    // Open log file
    fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error setting signal handler\n");
        return 1;
    }
    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error setting signal handler\n");
        return 1;
    }

    while (1) {
        // Trigger pulse
        ret = gpio_write(TRIGGER_PIN, 1);
        if (ret < 0) {
            fprintf(stderr, "Error sending trigger pulse\n");
            continue;
        }
        usleep(10);

        // Wait for echo
        ret = gpio_read(ECHO_PIN, &echo_state);
        if (ret < 0) {
            fprintf(stderr, "Error reading echo state\n");
            continue;
        }
        if (echo_state == 0) {
            // No echo, skip this sample
            continue;
        }
        ret = gpio_read(ECHO_PIN, &echo_state);
        if (ret < 0) {
            fprintf(stderr, "Error reading echo state\n");
            continue;
        }
        if (echo_state == 1) {
            // Echo, calculate distance
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            end = now;
            start = end;
            sleep_time.tv_sec = DELAY;
            sleep_time.tv_nsec = 0;
            nanosleep(&sleep_time, NULL);
            ret = gpio_read(ECHO_PIN, &echo_state);
            if (ret < 0) {
                fprintf(stderr, "Error reading echo state\n");
                continue;
            }
            if (echo_state == 0) {
                // No echo, skip this sample
                continue;
            }
            ret = gpio_read(ECHO_PIN, &echo_state);
            if (ret < 0) {
                fprintf(stderr, "Error reading echo state\n");
                continue;
            }
            if (echo_state == 1) {
                // Echo, calculate distance
                double distance = (TRIGGER_LEVEL - ECHO_LEVEL) / (2 * ECHO_LEVEL) * 0.034 / 2;
                ret = write(fd, "%f\n", distance);
                if (ret < 0) {
                    fprintf(stderr, "Error writing to log file\n");
                }
            }
        }
    }

    // Clean up
    close(fd);
    pigpio_close(gpio);
    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    close(fd);
    pigpio_close(gpio);
    exit(0);
}

