#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>

#define I2C_ADDRESS 0x29
#define RELAY_PIN 18
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define POLL_INTERVAL 100
#define MAX_DISTANCE 200

int main(int argc, char *argv[]) {
    int fd;
    int relay_state = RELAY_LOW;
    int i;
    struct pigpio gpio;
    struct vl53l1x_config config;
    struct vl53l1x_distance measurement;
    struct timeval tv;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("pigpio initialisation failed");
        return 1;
    }

    // Open I2C interface
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("I2C interface open failed");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("I2C address set failed");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure VL53L1X sensor
    if (ioctl(fd, VL53L1X_CONFIG, &config) < 0) {
        perror("VL53L1X configuration failed");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Enable sensor
    if (ioctl(fd, VL53L1X_ENABLE, &config) < 0) {
        perror("VL53L1X enable failed");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Start measurement
    if (ioctl(fd, VL53L1X_START, &config) < 0) {
        perror("VL53L1X start failed");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for measurement
        if (ioctl(fd, VL53L1X_GET_DISTANCE, &measurement) < 0) {
            perror("VL53L1X get distance failed");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Check if measurement is valid
        if (measurement.status != VL53L1X_STATUS_OK) {
            perror("VL53L1X measurement invalid");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Update relay state
        if (measurement.distance <= 50) {
            relay_state = RELAY_HIGH;
        } else {
            relay_state = RELAY_LOW;
        }

        // Update relay pin
        if (gpioWrite(RELAY_PIN, relay_state) < 0) {
            perror("relay pin write failed");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Print distance
        printf("%d\n", measurement.distance);

        // Sleep
        tv.tv_sec = 0;
        tv.tv_usec = POLL_INTERVAL;
        select(0, NULL, NULL, NULL, &tv);
    }

    // Clean up
    gpioWrite(RELAY_PIN, RELAY_LOW);
    gpioTerminate();
    close(fd);
    return 0;
}

