#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x1D
#define I2C_ADDRESS_MPU6050 0x68

int main(int argc, char *argv[]) {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(2, PI_INPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioSetMode(3, PI_INPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Map I2C memory
    void *mem = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    // Read and log data
    while (1) {
        // Read data from I2C device
        if (ioctl(fd, I2C_RDWR, I2C_ADDRESS_MPU6050) < 0) {
            perror("ioctl");
            break;
        }
        unsigned char data[6];
        if (read(fd, data, 6) != 6) {
            perror("read");
            break;
        }

        // Extract data
        unsigned short ax = (data[0] << 8) | data[1];
        unsigned short ay = (data[2] << 8) | data[3];
        unsigned short az = (data[4] << 8) | data[5];

        // Log data
        printf("ax: %d, ay: %d, az: %d\n", ax, ay, az);

        // Delay
        usleep(100000);
    }

    // Clean up
    munmap(mem, 256);
    close(fd);
    gpioCleanUp();
    return 0;
}

