#define RELAY_PIN_2 18
#define RELAY_PIN_3 27
#define RELAY_PIN_4 22
#define RELAY_HIGH 0
#define RELAY_LOW 1
#define CYCLE_TIME 86000 // 24 hours in milliseconds
#define LOG_FILE "watering_log.txt"

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the GPIO chip
    if (gpioChipOpen(&gpio, GPIO_I2C) < 0) {
        perror("gpioChipOpen");
        gpioTerminate();
        return 1;
    }

    // Set all lines as outputs with active-low semantics
    if (gpioSetupOutputArray(gpio, 4, RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4) < 0) {
        perror("gpioSetupOutputArray");
        gpioChipClose(gpio);
        gpioTerminate();
        return 1;
    }

    // Set all lines HIGH (inactive)
    if (gpioWrite(gpio, RELAY_PIN_1, RELAY_HIGH) < 0) {
        perror("gpioWrite");
        gpioSetupOutputArray(gpio, 4, RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4);
        gpioChipClose(gpio);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(gpio, RELAY_PIN_2, RELAY_HIGH) < 0) {
        perror("gpioWrite");
        gpioSetupOutputArray(gpio, 4, RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4);
        gpioChipClose(gpio);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(gpio, RELAY_PIN_3, RELAY_HIGH) < 0) {
        perror("gpioWrite");
        gpioSetupOutputArray(gpio, 4, RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4);
        gpioChipClose(gpio);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(gpio, RELAY_PIN_4, RELAY_HIGH) < 0) {
        perror("gpioWrite");
        gpioSetupOutputArray(gpio, 4, RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4);
        gpioChipClose(gpio);
        gpioTerminate();
        return 1;
    }

    // Main loop
    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);
    while (1) {
        // Activate relay 1
        gpioWrite(gpio, RELAY_PIN_1, RELAY_LOW);
        sleep(5);
        gpioWrite(gpio, RELAY_PIN_1, RELAY_HIGH);

        // Activate relay 2
        gpioWrite(gpio, RELAY_PIN_2, RELAY_LOW);
        sleep(5);
        gpioWrite(gpio, RELAY_PIN_2, RELAY_HIGH);

        // Activate relay 3
        gpioWrite(gpio, RELAY_PIN_3, RELAY_LOW);
        sleep(5);
        gpioWrite(gpio, RELAY_PIN_3, RELAY_HIGH);

