    gpioSetupOutputArray(gpio, 4, RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4);
    gpioWrite(gpio, RELAY_PIN_1, RELAY_HIGH);
    gpioWrite(gpio, RELAY_PIN_2, RELAY_HIGH);
    gpioWrite(gpio, RELAY_PIN_3, RELAY_HIGH);
    gpioWrite(gpio, RELAY_PIN_4, RELAY_HIGH);

    // Close the GPIO chip
    gpioChipClose(gpio);

    // Terminate the GPIO library
    gpioTerminate();

    return 0;
}

void sig_handler(int sig) {
    // Release GPIO lines
    gpioSetupOutputArray(gpio, 4, RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4);
    gpioWrite(gpio, RELAY_PIN_1, RELAY_HIGH);
    gpioWrite(gpio, RELAY_PIN_2, RELAY_HIGH);
    gpioWrite(gpio, RELAY_PIN_3, RELAY_HIGH);
    gpioWrite(gpio, RELAY_PIN_4, RELAY_HIGH);

    // Close the GPIO chip
    gpioChipClose(gpio);

    // Terminate the GPIO library
    gpioTerminate();

    // Exit cleanly
    exit(0);
}

