#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define RELAY_PINS { GPIO17, GPIO18, GPIO27, GPIO22 }
#define RELAY_COUNT 4
#define RELAY_PIN_MAP { 0, 1, 2, 3 }
#define RELAY_PWM_PIN GPIO17
#define RELAY_PWM_CHANNEL 0
#define RELAY_PWM_FREQ 1000
#define RELAY_PWM_MAX 255
#define RELAY_PWM_MIN 0
#define RELAY_PWM_STEP 5
#define RELAY_LOG_FILE "smart_lighting.log"
#define RELAY_LOG_LEVEL LOG_INFO

int main(int argc, char **argv) {
    int i, j, k, ret;
    struct timespec start, end;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;
    pigpio *gpio;
    int relays[RELAY_COUNT];

    // Initialize logging
    openlog("smart_lighting", LOG_PID, LOG_USER);
    setlogmask(LOG_UPTO_DATE | LOG_LPM | LOG_PID | LOG_INFO | LOG_DEBUG);
    syslog(LOG_INFO, "Starting smart lighting program");

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio == -1) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Set up relay pins
    for (i = 0; i < RELAY_COUNT; i++) {
        ret = gpio_mode(RELAY_PIN_MAP[i], GPIO_MODE_OUTPUT);
        if (ret != 0) {
            syslog(LOG_ERR, "Failed to set relay pin mode %d", RELAY_PIN_MAP[i]);
            return 1;
        }
    }

    // Set up PWM
    ret = gpio_pwm_config(RELAY_PWM_PIN, RELAY_PWM_CHANNEL, RELAY_PWM_FREQ, RELAY_PWM_MAX, RELAY_PWM_MIN);
    if (ret != 0) {
        syslog(LOG_ERR, "Failed to configure PWM");
        return 1;
    }

    // Set up relays
    for (i = 0; i < RELAY_COUNT; i++) {
        ret = gpio_pwm_set_duty(RELAY_PWM_PIN, RELAY_PWM_CHANNEL, RELAY_PWM_MIN);
        if (ret != 0) {
            syslog(LOG_ERR, "Failed to set relay %d duty cycle", RELAY_PIN_MAP[i]);
            return 1;
        }
        relays[i] = RELAY_PWM_MIN;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set signal handler for SIGINT");
        return 1;
    }
    sa_int.sa_handler = sigterm_handler;
    sa_int.sa_flags = SA_RESTART;
    sigemptyset(&sa_int.sa_mask);
    if (sigaction(SIGTERM, &sa_int, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set signal handler for SIGTERM");
        return 1;
    }

    // Main loop
    clock_gettime(CLOCK_REALTIME, &start);
    while (clock_gettime(CLOCK_REALTIME, &end) == 0) {
        for (i = 0; i < RELAY_COUNT; i++) {
            ret = gpio_pwm_set_duty(RELAY_PWM_PIN, RELAY_PWM_CHANNEL, relays[i]);
            if (ret != 0) {
                syslog(LOG_ERR, "Failed to set relay %d duty cycle", RELAY_PIN_MAP[i]);
                return 1;
            }
            relays[i] += RELAY_PWM_STEP;
            if (relays[i] > RELAY_PWM_MAX) {
                relays[i] = RELAY_PWM_MIN;
            }
        }
        syslog(LOG_INFO, "Relay duty cycles: %d %d %d %d", relays[0], relays[1], relays[2], relays[3]);
        sleep(1);
    }

    // Clean up
    for (i = 0; i < RELAY_COUNT; i++) {
        gpio_pwm_set_duty(RELAY_PWM_PIN, RELAY_PWM_CHANNEL, RELAY_PWM_MIN);
        gpio_mode(RELAY_PIN_MAP[i], GPIO_MODE_INPUT);
    }
    pigpio_close(gpio);
    close(logfd(LOG_FILE));

    return 0;
}

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT");
    exit(0);
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Received SIGTERM");
    exit(0);
}

