#include <string.h>
#include <pigpio.h>
#include <sys/timer.h>
#include <signal.h>
#include <unistd.h>

#define BUFFER_SIZE 100
#define BUFFER_INDEX 0
#define BUFFER_MAX_VALUE 250
#define I2C_ADDRESS 0x6B
#define I2C Bus 1
#define GPIO_LED 17
#define GPIO_SDA 2
#define GPIO_SCL 3

int main() {
    int i, j;
    int buffer[BUFFER_SIZE];
    int i2c_fd;
    int led_state = 0;
    struct itimerspec timer;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO for LED
    if (gpioMode(GPIO_LED, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        return 1;
    }
    if (gpioWrite(GPIO_LED, 0) < 0) {
        perror("gpioWrite");
        return 1;
    }

    // Set up I2C
    if ((i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS, 100)) < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Set up timer
    timer.tv_sec = 0;
    timer.tv_nsec = 500000; // 500ms
    if (tcsettime(&timer) < 0) {
        perror("tcsettime");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize buffer
    memset(buffer, 0, sizeof(buffer));

    while (1) {
        // Read from I2C
        if (i2cRead(i2c_fd, buffer, BUFFER_SIZE, 0) < 0) {
            if (i2cGetError(i2c_fd) == -2) {
                // I2C initialization failed, try to re-initialize
                if (i2cClose(i2c_fd) < 0) {
                    perror("i2cClose");
                    return 1;
                }
                if ((i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS, 100)) < 0) {
                    perror("i2cOpen");
                    return 1;
                }
            } else {
                // Read failed, exit
                perror("i2cRead");
                return 1;
            }
        }

        // Check for errors
        if (i2cGetError(i2c_fd) != 0) {
            perror("i2cGetError");
            return 1;
        }

        // Update LED state
        for (i = 0; i < BUFFER_SIZE; i++) {
            if (abs(buffer[i].x) > BUFFER_MAX_VALUE || abs(buffer[i].y) > BUFFER_MAX_VALUE || abs(buffer[i].z) > BUFFER_MAX_VALUE) {
                led_state = 1;
            } else {
                led_state = 0;
            }
        }
        if (led_state) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        // Store timestamped readings in buffer
        if (BUFFER_INDEX >= BUFFER_SIZE) {
            BUFFER_INDEX = 0;
        }
        buffer[BUFFER_INDEX].timestamp = time(NULL);
        buffer[BUFFER_INDEX].x = buffer[BUFFER_INDEX].y = buffer[BUFFER_INDEX].z = 0;
        buffer[BUFFER_INDEX].timestamp = time(NULL);
        BUFFER_INDEX++;

        // Sleep for 50ms
        nanosleep(&timer, NULL);
    }

    // Clean up
    gpioCleanUp();
    i2cClose(i2c_fd);
    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(GPIO_LED, 0);
    i2cClose(i2c_fd);
    gpioCleanUp();
    exit(0);
}

void sigterm_handler(int sig) {
    gpioWrite(GPIO_LED, 0);
    i2cClose(i2c_fd);
    gpioCleanUp();
    exit(0);
}

