#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/mount.h>
#include <sys/statvfs.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <signal.h>

#define SPI Bus 0
#define CS 8
#define CS_GPIO GPIO8
#define CS_GPIO BCM GPIO8
#define CS_PIN 17
#define CS_HIGH 0
#define CS_LOW 1
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BIT 8
#define SPI_MSB 1
#define CSV_FILE "gyro_log.txt"

int main() {
    int spi_fd, gpio_fd;
    struct spi_iomanage spi_m;
    struct gpio_iomanage gpio_m;
    struct timespec ts;
    struct stat sb;
    struct statvfs st;
    char filename[256];
    char buffer[256];
    int retry = 0;
    int rate[3];

    // Initialize libgpiod
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Initialize SPI
    if (gpiochip_init(SPI, &gpio_m) < 0) {
        perror("gpiochip_init");
        return 1;
    }

    // Configure SPI
    if (gpiochip_set_mode(SPI, CS_GPIO, CS_MODE, CS_HIGH) < 0) {
        perror("gpiochip_set_mode");
        return 1;
    }

    // Open SPI device
    if ((spi_fd = spi_open(SPI, CS_GPIO, SPI_SPEED, SPI_MODE, SPI_BIT, SPI_MSB)) < 0) {
        perror("spi_open");
        return 1;
    }

    // Open log file
    if ((gpio_fd = open(CSV_FILE, O_RDWR | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("open");
        return 1;
    }

    while (1) {
        // Read from SPI
        if (retry > 0) {
            retry--;
            continue;
        }

        if (spi_read(spi_fd, buffer, 6) < 0) {
            perror("spi_read");
            retry++;
            continue;
        }

        // Parse data
        if (sscanf(buffer, "%d %d %d", &rate[0], &rate[1], &rate[2]) != 3) {
            perror("sscanf");
            retry++;
            continue;
        }

        // Create timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(filename, sizeof(filename), "%Y-%m-%d %H:%M:%S.%N", localtime(&ts.tv_sec));

        // Write to log file
        if (write(gpio_fd, filename, strlen(filename)) < 0) {
            perror("write");
            retry++;
            continue;
        }
        if (write(gpio_fd, "\n", 1) < 0) {
            perror("write");
            retry++;
            continue;
        }
        if (write(gpio_fd, &rate[0], sizeof(rate[0])) < 0) {
            perror("write");
            retry++;
            continue;
        }
        if (write(gpio_fd, ",", 1) < 0) {
            perror("write");
            retry++;
            continue;
        }
        if (write(gpio_fd, &rate[1], sizeof(rate[1])) < 0) {
            perror("write");
            retry++;
            continue;
        }
        if (write(gpio_fd, ",", 1) < 0) {
            perror("write");
            retry++;
            continue;
        }
        if (write(gpio_fd, &rate[2], sizeof(rate[2])) < 0) {
            perror("write");
            retry++;
            continue;
        }
        if (write(gpio_fd, "\n", 1) < 0) {
            perror("write");
            retry++;
            continue;
        }

        // Deassert chip select
        gpiochip_set_mode(SPI, CS_GPIO, CS_MODE, CS_LOW);
    }

    // Clean up
    gpiochip_close(SPI);
    close(gpio_fd);
    close(spi_fd);
    unlink(CSV_FILE);
    return 0;
}

