#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define BUFFER_SIZE 64
#define BUFFER_NAME "/dev/spidev0.0"
#define SPI_CE GPIO_BCM_8
#define SPI_MOSI GPIO_BCM_10
#define SPI_MISO GPIO_BCM_9
#define LED_GPIO GPIO_BCM_17
#define LED_PIN 11
#define THRESHOLD 200
#define CSV_FILE "mpu6050_data.csv"

int main() {
    // Initialize GPIO
    int gpio = 0;
    if (gpioInitialise() == -1) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_CE, PI_MODE_OUTPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClock(SPI_CE, 3900000) == -1) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MOSI, PI_MODE_OUTPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MISO, PI_MODE_INPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open SPI device
    int fd = open(BUFFER_NAME, O_RDWR);
    if (fd == -1) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Create circular buffer
    void* buffer = mmap(NULL, BUFFER_SIZE * sizeof(float), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize timestamp
    time_t timestamp = time(NULL);

    // Initialize LED
    gpio = gpioGet(GPIO_BCM_17);
    if (gpio == -1) {
        perror("gpioGet");
        gpioTerminate();
        return 1;
    }
    gpio = gpioGetValue(GPIO_BCM_17);
    if (gpio != 0) {
        gpio = 0;
        gpio = gpioWrite(GPIO_BCM_17, 0);
    }

    while (1) {
        // Read from SPI
        unsigned char data[6];
        if (read(fd, data, 6) != 6) {
            perror("read");
            break;
        }
        if (data[0] == 0x60) {
            // Invalid data
            continue;
        }
        float x = (data[1] << 8) | data[2];
        float y = (data[3] << 8) | data[4];
        float z = (data[5] << 8) | data[6];
        float dt = (float)clock() - timestamp;
        timestamp = clock();

        // Check for threshold
        if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
            gpio = gpioWrite(GPIO_BCM_17, 1);
            sleep(0.5);
            gpio = gpioWrite(GPIO_BCM_17, 0);
            sleep(0.5);
        }

        // Store in buffer
        if (buffer % BUFFER_SIZE == 0) {
            // Shift data
            for (int i = BUFFER_SIZE - 1; i > 0; i--) {
                buffer[i] = buffer[i - 1];
            }
        }
        buffer[0] = x;
        buffer[BUFFER_SIZE - 1] = y;
        buffer[BUFFER_SIZE - 2] = z;
        buffer[BUFFER_SIZE - 3] = dt;

        // Print buffer
        if (buffer % BUFFER_SIZE == 0) {
            FILE* file = fopen(CSV_FILE, "a");
            if (file == NULL) {
                perror("fopen");
                break;
            }
            fprintf(file, "%f,%f,%f,%f\n", buffer[0], buffer[1], buffer[2], buffer[BUFFER_SIZE - 3]);
            fclose(file);
        }
    }

    // Clean up
    munmap(buffer, BUFFER_SIZE * sizeof(float));
    close(fd);
    gpioTerminate();
    return 0;
}

