#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x5A
#define GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"

int main() {
    // Initialize GPIO
    int gpio = 17;
    if (gpio = gpioInitialise()) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO17 as output
    if (gpioMode(gpio, GPIO_MODE_OUTPUT) != 0) {
        printf("Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C file descriptor
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        printf("Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        printf("Failed to set I2C address\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        printf("Failed to open log file\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        printf("Failed to set SIGINT handler\n");
        close(fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa2;
    sa2.sa_handler = sigterm_handler;
    sigemptyset(&sa2.sa_mask);
    sa2.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa2, NULL) == -1) {
        printf("Failed to set SIGTERM handler\n");
        close(fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read from I2C
        unsigned char data[2];
        if (read(fd, data, 2) != 2) {
            printf("Failed to read from I2C\n");
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Retry
                usleep(10);
                continue;
            } else {
                printf("Failed to read from I2C: %s\n", strerror(errno));
                break;
            }
        }

        // Parse data
        int ambient_light = (data[0] & 0xFF);
        int proximity = (data[1] & 0xFF);

        // Write to log file
        time_t now = time(NULL);
        char log_line[32];
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S,AmbientLight:%d,Proximity:%d", localtime(&now));
        if (write(log_fd, log_line, strlen(log_line) + 1) != strlen(log_line) + 1) {
            printf("Failed to write to log file\n");
            break;
        }

        // Set GPIO17 based on proximity
        if (proximity > 100) {
            gpio = 1;
        } else {
            gpio = 0;
        }
        if (gpio = gpioWrite(gpio, gpio) != 0) {
            printf("Failed to set GPIO17\n");
            break;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(fd);
    close(log_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    close(fd);
    close(log_fd);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    close(fd);
    close(log_fd);
    gpioTerminate();
    exit(0);
}

