#include <stdbool.h>

#define SPI_MODE 0
#define SPI_CPOL 0
#define SPI_CPHA 0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_CS_GPIO 8
#define SPI_CS_PIN GPIO_PIN_18
#define SPI_CS_PORT GPIO_PORT_1
#define SPI_CS_BIT GPIO_BIT_0
#define SPI_READ_BIT 0x80
#define SPI_DUMMY 0x00

#define CSV_FILE "gyro_data.csv"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_CS_GPIO, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    gpioSetLevel(SPI_CS_GPIO, 1);

    if (gpioInitialiseSPI(SPI_CS_GPIO, SPI_SPEED, SPI_MODE, SPI_CPOL, SPI_CPHA) < 0) {
        perror("gpioInitialiseSPI");
        return 1;
    }

    // Open CSV file
    int fd = open(CSV_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Map file to memory
    struct stat sb;
    if (fstat(fd, &sb) < 0) {
        perror("fstat");
        return 1;
    }
    void* map = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    // Set up SPI read bit
    uint8_t readBit = SPI_READ_BIT;

    // Set up SPI dummy byte
    uint8_t dummy = SPI_DUMMY;

    // Set up SPI data
    uint8_t data[2] = {readBit, dummy};

    // Set up SPI clock
    gpioSetClock(SPI_CS_GPIO, SPI_SPEED);

    // Set up SPI data
    gpioSetLevel(SPI_CS_GPIO, 0);

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Main loop
    while (1) {
        // Read gyro data
        if (gpioTransfer(SPI_CS_GPIO, data, 2, 100) < 0) {
            if (gpioTransfer(SPI_CS_GPIO, data, 2, 100) < 0) {
                if (gpioTransfer(SPI_CS_GPIO, data, 2, 100) < 0) {
                    // Re-initialize SPI
                    if (gpioInitialiseSPI(SPI_CS_GPIO, SPI_SPEED, SPI_MODE, SPI_CPOL, SPI_CPHA) < 0) {
                        perror("gpioInitialiseSPI");
                        return 1;
                    }
                }
            }
        }

        // Read gyro data
        uint16_t xRate = (data[0] & 0xFF00) >> 8;
        uint16_t yRate = data[1] & 0x00FF;

        // Write to CSV file
        time_t now = time(NULL);
        struct tm* ltm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06d", ltm);
        char line[256];
        sprintf(line, "%s,%d,%d\n", timestamp, xRate, yRate);
        if (write(fd, line, strlen(line)) < 0) {
            perror("write");
            return 1;
        }

        // Delay
        usleep(10000);
    }

    // Clean up
    if (munmap(map, sb.st_size) < 0) {
        perror("munmap");
        return 1;
    }
    close(fd);
    gpioSetLevel(SPI_CS_GPIO, 1);
    gpioTerminateSPI(SPI_CS_GPIO);
    gpioTerminate();
    return 0;
}

void sigintHandler(int sig) {
    // Clean up
    gpioSetLevel(SPI_CS_GPIO, 1);
    gpioTerminateSPI(SPI_CS_GPIO);
    gpioTerminate();
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    exit(0);
}

