}

// Function to read the gyroscope data
int read_gyroscope(void) {
    int ret;
    uint8_t data[2];
    ret = gpiod_line_read(spi_miso, data, 2);
    if (ret != 0) {
        printf("Failed to read gyroscope data\n");
        return ret;
