        gpiod_line_write(spi_ce, 0);
        return ret;
    }

    ret = gpiod_line_write(spi_mosi, address);
    if (ret != 0) {
        printf("Failed to write address\n");
        gpiod_line_write(spi_sclk, 0);
        gpiod_line_write(spi_ce, 0);
        return ret;
    }

    ret = gpiod_line_write(spi_sclk, 1);
    if (ret != 0) {
        printf("Failed to set SCLK\n");
        gpiod_line_write(spi_ce, 0);
        gpiod_line_write(spi_mosi, address);
        return ret;
    }

    ret = gpiod_line_write(spi_mosi, 0);
    if (ret != 0) {
        printf("Failed to write data\n");
        gpiod_line_write(spi_sclk, 0);
        gpiod_line_write(spi_ce, 0);
        gpiod_line_write(spi_mosi, address);
        return ret;
    }

    ret = gpiod_line_write(spi_sclk, 0);
    if (ret != 0) {
        printf("Failed to set SCLK\n");
        gpiod_line_write(spi_ce, 0);
        gpiod_line_write(spi_mosi, address);
        return ret;
    }

    ret = gpiod_line_read(spi_miso, data, 2);
    if (ret != 0) {
        printf("Failed to read data\n");
        gpiod_line_write(spi_ce, 0);
        gpiod_line_write(spi_sclk, 0);
        gpiod_line_write(spi_mosi, address);
        return ret;
    }

    uint32_t rate = (data[0] << 16) | data[1];

    pthread_mutex_lock(&buffer_mutex);
    buffer[buffer_index].timestamp = clock_gettime(CLOCK_MONOTONIC);
    buffer[buffer_index].rate = rate;
    buffer_size = (buffer_size + 1) % BUFFER_SIZE;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);

    return 0;
}

// Function to check the rate against the threshold
void check_rate(void) {
    pthread_mutex_lock(&buffer_mutex);
    float rate = buffer[buffer_index].rate;
    pthread_mutex_unlock(&buffer_mutex);

    if (rate > THRESHOLD) {
        gpiod_line_write(led, 1);
    } else {
        gpiod_line_write(led, 0);
    }
}

int main(int argc, char **argv) {
    int ret;
    struct sigaction sa;

    // Initialize the LED pin
    ret = gpiod_line_open(&led, "LED", GPIO_MODE_OUTPUT, GPIO_FLOATING, 0);
    if (ret != 0) {
        printf("Failed to open LED line\n");
        return ret;
    }

    // Initialize the SPI interface
    ret = init_spi();
    if (ret != 0) {
        printf("Failed to initialize SPI interface\n");
        gpiod_line_close(led);
        return ret;
    }

    // Set up signal handlers
    sa.sa_handler = SIGINT;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret != 0) {
        printf("Failed to set signal handler\n");
        gpiod_device_close(spi_device);
        gpiod_line_close(led);
        return ret;
    }

    sa.sa_handler = SIGTERM;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret != 0) {
        printf("Failed to set signal handler\n");
        gpiod_device_close(spi_device);
        gpiod_line_close(led);
        return ret;
    }

    // Start the thread
    pthread_t thread;
    pthread_create(&thread, NULL, check_rate, NULL);

    while (1) {
        ret = read_gyroscope();
        if (ret != 0) {
            printf("Failed to read gyroscope data\n");
        }
        check_rate();
        usleep(100000);
    }

    // Clean up
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < buffer_size; i++) {
        BufferEntry temp = buffer[i];
        buffer[i] = buffer[(i + 1) % BUFFER_SIZE];
    }
    buffer[buffer_size] = BufferEntry();
    buffer_size = 0;
    pthread_mutex_unlock(&buffer_mutex);

    gpiod_device_close(spi_device);
    gpiod_line_close(led);
    pthread_join(thread, NULL);

    return 0;
}

