#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_ADDRESS 0x5A
#define RELAY_PIN 17
#define DEBOUNCE_DELAY 100
#define TOUCH_STATUS_DELAY 10

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    struct i2c_client *client;
    struct i2c_dev *dev;
    struct gpio_action action;
    struct timespec delay;
    struct timespec last_touch;
    struct timespec last_debounce;
    int touch_status;
    int relay_state;

    // Initialize logging
    openlog("touch_relay", LOG_PID, LOG_USER);
    setlogmask(LOG_UPTIME | LOG_AUTH);

    // Initialize GPIO
    gpio_init();
    gpio_set_mode(RELAY_PIN, GPIO_MODE_OUTPUT);
    gpio_set_level(RELAY_PIN, 0);

    // Initialize I2C
    i2c_dev_open(&dev, I2C_ADDRESS, 1);
    if (i2c_dev_open(&dev, I2C_ADDRESS, 1) < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        exit(1);
    }

    while (1) {
        // Read touch status
        i2c_dev_read(&dev, I2C_ADDRESS, 0x00, 1, &touch_status);
        if (i2c_dev_read(&dev, I2C_ADDRESS, 0x00, 1, &touch_status) < 0) {
            syslog(LOG_ERR, "Failed to read touch status");
            exit(1);
        }

        // Debounce touch events
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        if (now.tv_sec - last_touch.tv_sec > TOUCH_STATUS_DELAY) {
            last_touch = now;
            if (touch_status & (1 << 0)) {
                // Electrode 0 touched
                gpio_action_init(&action, RELAY_PIN, GPIO_HIGH);
                if (gpio_action(&action) < 0) {
                    syslog(LOG_ERR, "Failed to toggle relay");
                    exit(1);
                }
                last_debounce = now;
            } else if (now.tv_sec - last_debounce.tv_sec > DEBOUNCE_DELAY) {
                // Electrode 0 released
                gpio_action_init(&action, RELAY_PIN, GPIO_LOW);
                if (gpio_action(&action) < 0) {
                    syslog(LOG_ERR, "Failed to toggle relay");
                    exit(1);
                }
            }
        }

        // Sleep for 10ms
        nanosleep(&delay, NULL);
        delay.tv_sec = 0;
        delay.tv_nsec = TOUCH_STATUS_DELAY * 1000000;
    }

    // Clean up
    gpio_close(gpio_fd);
    i2c_dev_close(&dev);
    close(i2c_fd);
    exit(0);
}

