#define FLAME_DETECTED "Flame Detected"
#define FLAME_DETECTED_INTERVAL 50
#define FLAME_DETECTED_THRESHOLD 3

// Define a function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Release GPIO lines
    if (gpioRelease(GPIO17) != 0) {
        perror("gpioRelease(GPIO17)");
        exit(1);
    }
    if (gpioRelease(GPIO18) != 0) {
        perror("gpioRelease(GPIO18)");
        exit(1);
    }
    if (gpioRelease(GPIO23) != 0) {
        perror("gpioRelease(GPIO23)");
        exit(1);
    }

    // Close log file
    if (close(log_fd) != 0) {
        perror("close(log_fd)");
        exit(1);
    }

    // Exit with error code
    exit(1);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() != 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd == -1) {
        perror("open");
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO modes
    if (gpioMode(GPIO17, GPIO_MODE_INPUT) != 0) {
        perror("gpioMode(GPIO17)");
        exit(1);
    }
    if (gpioMode(GPIO18, GPIO_MODE_OUTPUT) != 0) {
        perror("gpioMode(GPIO18)");
        exit(1);
    }
    if (gpioMode(GPIO23, GPIO_MODE_OUTPUT) != 0) {
        perror("gpioMode(GPIO23)");
        exit(1);
    }

    // Set GPIO pull-up resistor
    if (gpioPullUpDowntime(GPIO17, GPIO PullUpDowntime) != 0) {
        perror("gpioPullUpDowntime(GPIO17)");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read GPIO17
        int value = gpioRead(GPIO17);
        if (value == 0) {
            // Check for flame detection
            int count = 0;
            struct timespec start_time;
            struct timespec end_time;
            struct timespec sleep_time;

            // Read GPIO17 three times spaced 50ms apart
            for (int i = 0; i < FLAME_DETECTED_THRESHOLD; i++) {
                // Record start time
                clock_gettime(CLOCK_MONOTONIC, &start_time);

                // Wait for 50ms
                sleep_time.tv_sec = 0;
                sleep_time.tv_nsec = 50 * 1000000;
                nanosleep(&sleep_time, NULL);

                // Read GPIO17 again
                value = gpioRead(GPIO17);
                if (value == 0) {
                    // Increment count
                    count++;
                } else {
                    // Reset count
                    count = 0;
                }
            }

            // Check if flame detected
            if (count >= FLAME_DETECTED_THRESHOLD) {
                // Log message
                char log_message[256];
                strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
                fprintf(log_fd, "%s %s\n", log_message, FLAME_DETECTED);

                // Activate buzzer and LED
                gpioWrite(GPIO18, 1);
                gpioWrite(GPIO23, 1);
            } else {
                // Deactivate buzzer and LED
                gpioWrite(GPIO18, 0);
                gpioWrite(GPIO23, 0);
            }
        }
    }

    // Release GPIO lines
    if (gpioRelease(GPIO17) != 0) {
        perror("gpioRelease(GPIO17)");
        exit(1);
    }
    if (gpioRelease(GPIO18) != 0) {
        perror("gpioRelease(GPIO18)");
        exit(1);
    }
    if (gpioRelease(GPIO23) != 0) {
        perror("gpioRelease(GPIO23)");
        exit(1);
    }

    // Close log file
    if (close(log_fd) != 0) {
        perror("close(log_fd)");
        exit(1);
    }

    // Finalize GPIO
    if (gpioFinalise() != 0) {
        perror("gpioFinalise");
        exit(1);
    }

    return 0;
}

