#define MAX_MOTOR_SPEED 255
#define MIN_MOTOR_SPEED 0
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define TILT_ERROR_MAX 10.0
#define TILT_ERROR_MIN -10.0
#define LOG_FILE "balance_log.txt"

int main(int argc, char *argv[]) {
    int gpioA = 17;
    int gpioB = 18;
    int gpioFwdA = 22;
    int gpioBwdA = 23;
    int gpioEnA = 24;
