    if (gpioSetMode(gpioA, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpioB, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpioFwdA, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpioBwdA, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpioEnA, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpioEnB, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set up PWM
    if (gpioPWMWrite(gpioEnA, 100) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpioEnB, 100) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((log_fd = fopen(LOG_FILE, "w")) < 0) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // PID control loop
    while (1) {
        // Generate random tilt error and distance
        tilt_error = (float)rand() / RAND_MAX * (TILT_ERROR_MAX - TILT_ERROR_MIN) + TILT_ERROR_MIN;
        distance = (float)rand() / RAND_MAX * (MAX_DISTANCE - MIN_DISTANCE) + MIN_DISTANCE;

        // Calculate motor speeds
        motor_a_speed = (float)rand() / RAND_MAX * (MAX_MOTOR_SPEED - MIN_MOTOR_SPEED) + MIN_MOTOR_SPEED;
        motor_b_speed = (float)rand() / RAND_MAX * (MAX_MOTOR_SPEED - MIN_MOTOR_SPEED) + MIN_MOTOR_SPEED;

        // Clamp motor speeds
        motor_a_speed = (int)max(MIN_MOTOR_SPEED, min(motor_a_speed, MAX_MOTOR_SPEED));
        motor_b_speed = (int)max(MIN_MOTOR_SPEED, min(motor_b_speed, MAX_MOTOR_SPEED));

        // Log data
        if (log_fd >= 0) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
            fprintf(log_fd, "%s %f %f %d %d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        }

        // PID control
        if (pid == 0) {
            pid = pigpio_init();
            if (pid < 0) {
                perror("pigpio_init");
                gpioTerminate();
                return 1;
            }
        }
        if (pid2 == 0) {
            pid2 = pigpio_init();
            if (pid2 < 0) {
                perror("pigpio_init");
                gpioTerminate();
                return 1;
            }
        }

        // Set motor speeds
        if (gpioPWMWrite(gpioEnA, motor_a_speed) < 0) {
            perror("gpioPWMWrite");
            gpioTerminate();
            return 1;
        }
        if (gpioPWMWrite(gpioEnB, motor_b_speed) < 0) {
            perror("gpioPWMWrite");
            gpioTerminate();
            return 1;
        }

        // Obstacle avoidance
        if (distance < MIN_DISTANCE) {
            if (gpioPWMWrite(gpioEnA, 50) < 0) {
                perror("gpioPWMWrite");
                gpioTerminate();
                return 1;
            }
            if (gpioPWMWrite(gpioEnB, 50) < 0) {
                perror("gpioPWMWrite");
                gpioTerminate();
                return 1;
            }
        }

        // Sleep
        nanosleep(&ts, NULL);
        ts.tv_sec = 0;
        ts.tv_nsec = 50 * 1000000;
    }

    // Clean up
    if (log_fd >= 0) {
        fclose(log_fd);
    }
    gpioTerminate();
    pigpio_close(pid);
    pigpio_close(pid2);
    return 0;
