#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define GPIO4 4  // Physical pin 7 (BCM numbering)
#define GPIO17 17  // Physical pin 11 (BCM numbering)
#define RELAY_PIN GPIO17
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define DEBOUNCE_DELAY 50  // ms
#define MAX_RETRIES 5

// Function to initialize GPIO
void init_gpio(pigpio *gpio) {
    if (gpio_init(gpio) < 0) {
        perror("gpio_init");
        exit(1);
    }
    if (gpio_mode(gpio, GPIO_MODE_INPUT, GPIO_PUD_DOWN) < 0) {
        perror("gpio_mode");
        exit(1);
    }
}

// Function to toggle relay
void toggle_relay(pigpio *gpio) {
    if (gpio_get_value(gpio, RELAY_PIN) == RELAY_LOW) {
        if (gpio_set_value(gpio, RELAY_PIN, RELAY_HIGH) < 0) {
            perror("gpio_set_value");
            exit(1);
        }
    } else {
        if (gpio_set_value(gpio, RELAY_PIN, RELAY_LOW) < 0) {
            perror("gpio_set_value");
            exit(1);
        }
    }
}

// Function to check for touch detection
int check_touch(pigpio *gpio) {
    int value = gpio_get_value(gpio, GPIO4);
    if (value == 1) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
    // Initialize GPIO
    pigpio *gpio = new pigpio();
    init_gpio(gpio);

    // Set up signal handlers
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    while (1) {
        // Check for touch detection
        int touch_detected = check_touch(gpio);
        if (touch_detected) {
            // Apply debounce delay
            usleep(DEBOUNCE_DELAY * 1000);

            // Toggle relay
            toggle_relay(gpio);
        }

        // Check for errors
        if (gpio_get_value(gpio, GPIO4) == -1) {
            perror("gpio_get_value");
            exit(1);
        }
    }

    // Clean up
    gpio_close(gpio);
    delete gpio;

    return 0;
}

