#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <libgen.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 200
#define VIDEO_CAPTURE_TIME 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos"

int main() {
    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioToggle(GPIO_PIN);

    // Set up debouncing
    struct timespec debounce_start;
    struct timespec debounce_end;
    int debounce_count = 0;

    // Set up signal handler
    struct sigaction sigint_handler;
    sigemptyset(&sigint_handler);
    sigaddset(&sigint_handler.sa_mask, SIGINT);
    sigint_handler.sa_handler = sigpipe;
    sigaction(SIGINT, &sigint_handler, NULL);

    while (1) {
        // Read GPIO value
        int gpio_value = gpioGet(GPIO_PIN);
        if (gpio_value == 0) {
            // Debounce
            if (debounce_count == 0) {
                debounce_start.tv_sec = time(NULL);
                debounce_start.tv_nsec = 0;
            }
            debounce_count++;
            if (debounce_count >= DEBOUNCE_TIME) {
                debounce_count = 0;
                struct timespec elapsed;
                clock_gettime(CLOCK_MONOTONIC, &elapsed);
                struct timespec timestamp;
                clock_gettime(CLOCK_MONOTONIC, &timestamp);
                char filename[32];
                strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", localtime(&timestamp));
                char log_message[64];
                strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
                FILE *log_file = fopen(LOG_FILE, "a");
                if (log_file == NULL) {
                    perror("fopen");
                    continue;
                }
                fprintf(log_file, "%s\n", log_message);
                fclose(log_file);

                // Start video capture
                char command[128];
                sprintf(command, "raspivid -t %d -o %s/%s -t 0 -o -", VIDEO_CAPTURE_TIME, VIDEO_DIR, filename);
                int ret = system(command);
                if (ret != 0) {
                    perror("system");
                    continue;
                }
            }
        } else {
            debounce_count = 0;
        }
    }

    // Clean up
    gpioTerminate(gpio);
    return 0;
}

