#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants for GPIO pins
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define constants for relay states
#define RELAY_STATE_OFF 0
#define RELAY_STATE_ON 1

// Define constants for log file
#define LOG_FILE "irrigation_log.txt"

// Define a structure to hold relay states
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayStates;

// Function to initialize the GPIO driver
void init_gpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
}

// Function to open the log file
void open_log_file() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
}

// Function to close the log file
void close_log_file() {
    if (fclose(log_file) != 0) {
        perror("fclose");
        exit(1);
    }
}

// Function to handle signal (SIGINT or any error)
void signal_handler(int sig) {
    // Deactivate all relays
    gpioWrite(RELAY1_PIN, RELAY_STATE_OFF);
    gpioWrite(RELAY2_PIN, RELAY_STATE_OFF);
    gpioWrite(RELAY3_PIN, RELAY_STATE_OFF);
    gpioWrite(RELAY4_PIN, RELAY_STATE_OFF);

    // Close the log file
    close_log_file();

    // Terminate the GPIO driver
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO driver
    init_gpio();

    // Open the log file
    open_log_file();

    // Seed the random number generator
    srand(time(NULL));

    // Define the relay states
    RelayStates relays = {RELAY_STATE_OFF, RELAY_STATE_OFF, RELAY_STATE_OFF, RELAY_STATE_OFF};

    while (1) {
        // Generate a random moisture value
        int moisture = rand() % 100;

        // Update the relay states
        if (moisture < 30) {
            relays.relay1 = RELAY_STATE_ON;
            relays.relay2 = RELAY_STATE_ON;
            relays.relay3 = RELAY_STATE_ON;
            relays.relay4 = RELAY_STATE_ON;
        } else {
            relays.relay1 = RELAY_STATE_OFF;
            relays.relay2 = RELAY_STATE_OFF;
            relays.relay3 = RELAY_STATE_OFF;
            relays.relay4 = RELAY_STATE_OFF;
        }

        // Log the relay states and timestamp
        fprintf(log_file, "%d %d %d %d %d\n", moisture, relays.relay1, relays.relay2, relays.relay3, relays.relay4);
        fprintf(log_file, "%d-%d-%d %02d:%02d:%02d\n", 2023, rand() % 12 + 1, rand() % 28 + 1, rand() % 24 + 1, rand() % 60 + 1, rand() % 60 + 1);

        // Update the GPIO states
        gpioWrite(RELAY1_PIN, relays.relay1);
        gpioWrite(RELAY2_PIN, relays.relay2);
        gpioWrite(RELAY3_PIN, relays.relay3);
        gpioWrite(RELAY4_PIN, relays.relay4);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Install the signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

