#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x1D
#define I2C Bus 1
#define GPIO_Buzzer 17
#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define MAX_RETRIES 3

int main(int argc, char *argv[]) {
    int i, retry;
    int fd;
    int ret;
    int bus;
    int gpio;
    int32_t x, y, z;
    bool free_fall = false;
    bool impact = false;
    bool buzzer_on = false;
    struct sigaction sa;

    // Initialize GPIO
    if (gpio = gpioInitialise()) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize I2C
    if ((bus = i2cGetDev()) == -1) {
        printf("Failed to get I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (i2cSetDevAddress(bus, I2C_ADDRESS) == -1) {
        printf("Failed to set I2C address\n");
        i2cRelease(bus);
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (i2cSetClockSpeed(bus, 100000) == -1) {
        printf("Failed to set I2C clock speed\n");
        i2cRelease(bus);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    fd = i2cOpen(bus, I2C_ADDRESS);
    if (fd == -1) {
        printf("Failed to open I2C device\n");
        i2cRelease(bus);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        // Read acceleration data
        ret = i2cRead(fd, &x, sizeof(x), 0);
        if (ret == -1) {
            retry = 0;
            while (retry < MAX_RETRIES) {
                ret = i2cRead(fd, &x, sizeof(x), 0);
                if (ret == 0) {
                    break;
                }
                retry++;
            }
            if (retry == MAX_RETRIES) {
                printf("Failed to read acceleration data\n");
                i2cClose(fd);
                i2cRelease(bus);
                gpioTerminate();
                return 1;
            }
        }

        // Check for free-fall
        if (!free_fall && x < 0) {
            free_fall = true;
        } else if (free_fall && x >= 0) {
            free_fall = false;
        }

        // Check for impact
        if (free_fall && x > 0 && !impact) {
            impact = true;
        } else if (!free_fall && x <= 0 && impact) {
            impact = false;
        }

        // Buzzer
        if (impact && !buzzer_on) {
            gpioWrite(GPIO_Buzzer, 1);
            usleep(1000000);
            gpioWrite(GPIO_Buzzer, 0);
            buzzer_on = true;
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up
    i2cClose(fd);
    i2cRelease(bus);
    gpioTerminate();

    return 0;
}

void sigintHandler(int sig) {
    printf("Received SIGINT\n");
    gpioWrite(GPIO_Buzzer, 0);
    gpioTerminate();
    exit(0);
}

