// Define constants
#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define GPIO5 5
#define GPIO6 6
#define GPIO13 13
#define GPIO19 19
#define GPIO23 23
#define GPIO24 24
#define GPIO26 26
#define GPIO25 25
#define DELAY_US 1000

// Define motor configuration
#define STEPS_PER_REV 2048
#define GEAR_RATIO 64
#define SQUARE_SIZE_MM 50
#define STEPS_PER_STEP (STEPS_PER_REV / GEAR_RATIO)

// Define motor pins
const int motor1_pins[] = {GPIO4, GPIO17, GPIO27, GPIO22};
const int motor2_pins[] = {GPIO5, GPIO6, GPIO13, GPIO19};

// Define wave drive sequence
const int steps[] = {0, 1, 2, 3};

// Define signal handler
void sigint_handler(int sig) {
    // Stop both motors
    stop_motors();

    // Set all GPIO pins low
    for (int i = 0; i < 8; i++) {
        gpioWrite(motor1_pins[i], 0);
        gpioWrite(motor2_pins[i], 0);
    }

    // Release resources
    gpioCleanUp();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Configure motor pins as outputs
    for (int i = 0; i < 4; i++) {
        if (gpioMode(motor1_pins[i], GPIO_OUTPUT) < 0) {
            perror("gpioMode");
            return 1;
        }
        if (gpioMode(motor2_pins[i], GPIO_OUTPUT) < 0) {
            perror("gpioMode");
            return 1;
        }
    }

    // Configure motor pins as outputs
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(motor1_pins[i], 1) < 0) {
            perror("gpioWrite");
            return 1;
        }
        if (gpioWrite(motor2_pins[i], 1) < 0) {
            perror("gpioWrite");
            return 1;
        }
    }

    // Define wave drive sequence
    int steps_per_step = STEPS_PER_STEP;
    int steps_per_rev = STEPS_PER_REV;
    int revs = (SQUARE_SIZE_MM * 4) / (SQUARE_SIZE_MM * 2); // 50mm square, 4 sides
    int total_steps = revs * steps_per_rev;

    // Move motors to home position
    for (int i = 0; i < total_steps; i++) {
        for (int j = 0; j < 4; j++) {
            gpioWrite(motor1_pins[j], 0);
            gpioWrite(motor2_pins[j], 0);
        }
        usleep(DELAY_US * 1000);
    }

    // Move motors in wave drive sequence
    for (int i = 0; i < total_steps; i++) {
        for (int j = 0; j < 4; j++) {
            gpioWrite(motor1_pins[j], steps[i % 4]);
            gpioWrite(motor2_pins[j], steps[i % 4]);
        }
        usleep(DELAY_US * 1000);
    }

    // Stop motors
    stop_motors();

    // Release resources
    gpioCleanUp();
    return 0;
}

void stop_motors() {
    // Stop motor 1
    gpioWrite(motor1_pins[0], 0);
    gpioWrite(motor1_pins[1], 0);
    gpioWrite(motor1_pins[2], 0);
    gpioWrite(motor1_pins[3], 0);

    // Stop motor 2
    gpioWrite(motor2_pins[0], 0);
    gpioWrite(motor2_pins[1], 0);
    gpioWrite(motor2_pins[2], 0);
    gpioWrite(motor2_pins[3], 0);
}

