    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO pins
    gpioSetMode(4, GPIO_INPUT);
    gpioSetMode(17, GPIO_INPUT);
    gpioSetMode(27, GPIO_INPUT);
    gpioSetMode(22, GPIO_OUTPUT);

    // Set up circular buffer
    int buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Poll sensors
        int left = gpioRead(4);
        int center = gpioRead(17);
