#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x1A
#define RELAY_PIN 17
#define RELAY_VALUE_HIGH 1
#define RELAY_VALUE_LOW 0
#define SAMPLE_INTERVAL 100
#define SAMPLE_COUNT 50
#define RELAY_THRESHOLD 5000
#define LOG_FILE "magnetic_events.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize gpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    int i2c_fd = i2cOpen(1, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        gpiodTerminate();
        return 1;
    }

    // Set up relay
    if (gpioSetMode(RELAY_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        i2cClose(i2c_fd);
        gpioTerminate();
        gpiodTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, RELAY_VALUE_LOW) < 0) {
        perror("gpioWrite");
        gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
        i2cClose(i2c_fd);
        gpioTerminate();
        gpiodTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
        i2cClose(i2c_fd);
        gpioTerminate();
        gpiodTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
        i2cClose(i2c_fd);
        gpioTerminate();
        gpiodTerminate();
        return 1;
    }

    while (1) {
        // Read magnetic field data
        unsigned char data[2];
        if (i2cRead(i2c_fd, data, 2, 100) < 0) {
            perror("i2cRead");
            gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
            i2cClose(i2c_fd);
            gpioTerminate();
            gpiodTerminate();
            return 1;
        }

        // Check if register value has cleared
        if (data[0] != 0x00) {
            for (int i = 0; i < SAMPLE_COUNT; i++) {
                if (i2cRead(i2c_fd, data, 2, 100) < 0) {
                    perror("i2cRead");
                    gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
                    i2cClose(i2c_fd);
                    gpioTerminate();
                    gpiodTerminate();
                    return 1;
                }
                if (data[0] == 0x00) {
                    break;
                }
            }
            if (i == SAMPLE_COUNT) {
                fprintf(stderr, "Timeout reading register value\n");
                continue;
            }
        }

        // Check if field exceeds threshold
        if (data[0] > RELAY_THRESHOLD) {
            // Trigger relay
            if (gpioWrite(RELAY_PIN, RELAY_VALUE_HIGH) < 0) {
                perror("gpioWrite");
                gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
                i2cClose(i2c_fd);
                gpioTerminate();
                gpiodTerminate();
                return 1;
            }

            // Log event
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s %d\n", timestamp, data[0]);
            fprintf(log_file, "Relay triggered\n");
        } else {
            // Deactivate relay
            if (gpioWrite(RELAY_PIN, RELAY_VALUE_LOW) < 0) {
                perror("gpioWrite");
                gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
                i2cClose(i2c_fd);
                gpioTerminate();
                gpiodTerminate();
                return 1;
            }
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    // Clean up
    gpioTerminate();
    gpiodTerminate();
    i2cClose(i2c_fd);
    fclose(log_file);
    return 0;
}

void sigint_handler(int sig) {
    gpioSetMode(RELAY_PIN, GPIO_MODE_INPUT);
    i2cClose(-1);
    gpiodTerminate();
    printf("Shutting down...\n");
    exit(0);
}

