#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define GPIO_RAIN_SENSOR 17
#define GPIO_ENA 22
#define GPIO_IN1 23
#define GPIO_IN2 24
#define LOG Facility LOG_USER
#define LOG_ID "rain_window"

// Initialize pigpio
int main() {
    int gpio;
    int rain_sensor_value;
    int motor_ena_value;
    int motor_in1_value;
    int motor_in2_value;
    int poll_count = 0;
    int dry_count = 0;
    int prev_rain_sensor_value = 0;
    struct timespec start_time;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        syslog(LOG_INFO, LOG_ID, "pigpio initialization failed");
        return 1;
    }

    // Configure GPIO pins
    if (gpio_mode(GPIO_RAIN_SENSOR, PI_INPUT) < 0) {
        syslog(LOG_ERR, LOG_ID, "Failed to configure GPIO_RAIN_SENSOR");
        pigpio_close(gpio);
        return 1;
    }
    if (gpio_mode(GPIO_ENA, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, LOG_ID, "Failed to configure GPIO_ENA");
        pigpio_close(gpio);
        return 1;
    }
    if (gpio_mode(GPIO_IN1, PI_INPUT) < 0) {
        syslog(LOG_ERR, LOG_ID, "Failed to configure GPIO_IN1");
        pigpio_close(gpio);
        return 1;
    }
    if (gpio_mode(GPIO_IN2, PI_INPUT) < 0) {
        syslog(LOG_ERR, LOG_ID, "Failed to configure GPIO_IN2");
        pigpio_close(gpio);
        return 1;
    }

    // Set pull-up on GPIO_RAIN_SENSOR
    if (gpio_pull_up_down(GPIO_RAIN_SENSOR, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, LOG_ID, "Failed to set pull-up on GPIO_RAIN_SENSOR");
        pigpio_close(gpio);
        return 1;
    }

    // Main loop
    while (1) {
        // Poll GPIO_RAIN_SENSOR
        if (gpio_read(GPIO_RAIN_SENSOR) < 0) {
            syslog(LOG_ERR, LOG_ID, "Failed to read GPIO_RAIN_SENSOR");
            pigpio_close(gpio);
            return 1;
        }
        rain_sensor_value = gpio_read(GPIO_RAIN_SENSOR);
        if (rain_sensor_value == 0 && prev_rain_sensor_value == 1) {
            // Rain detected, start close window sequence
            syslog(LOG_INFO, LOG_ID, "Rain detected, starting close window sequence");
            motor_ena_value = gpio_get(GPIO_ENA);
            motor_in1_value = gpio_get(GPIO_IN1);
            motor_in2_value = gpio_get(GPIO_IN2);
            if (motor_ena_value == 0) {
                syslog(LOG_ERR, LOG_ID, "ENA is low, cannot start close window sequence");
                continue;
            }
            if (motor_in1_value == 0) {
                syslog(LOG_ERR, LOG_ID, "IN1 is low, cannot start close window sequence");
                continue;
            }
            if (motor_in2_value == 0) {
                syslog(LOG_ERR, LOG_ID, "IN2 is low, cannot start close window sequence");
                continue;
            }
            // Start motor
            if (gpio_write(GPIO_ENA, 1) < 0) {
                syslog(LOG_ERR, LOG_ID, "Failed to set ENA high");
                continue;
            }
            if (gpio_write(GPIO_IN1, 1) < 0) {
                syslog(LOG_ERR, LOG_ID, "Failed to set IN1 high");
                gpio_write(GPIO_ENA, 0);
                gpio_write(GPIO_IN1, 0);
                gpio_write(GPIO_IN2, 0);
                continue;
            }
            if (gpio_write(GPIO_IN2, 0) < 0) {
                syslog(LOG_ERR, LOG_ID, "Failed to set IN2 low");
                gpio_write(GPIO_ENA, 0);
                gpio_write(GPIO_IN1, 0);
                gpio_write(GPIO_IN2, 0);
                continue;
            }
            // Hold motor for 5 seconds
            struct timespec end_time;
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            while (time(NULL) < end_time.tv_sec + 5) {
                // Busy-wait
            }
            // Stop motor
            if (gpio_write(GPIO_ENA, 0) < 0) {
                syslog(LOG_ERR, LOG_ID, "Failed to set ENA low");
                gpio_write(GPIO_IN1, 0);
                gpio_write(GPIO_IN2, 0);
                continue;
            }
            if (gpio_write(GPIO_IN1, 0) < 0) {
                syslog(LOG_ERR, LOG_ID, "Failed to set IN1 low");
                gpio_write(GPIO_ENA, 0);
                gpio_write(GPIO_IN2, 0);
                continue;
            }
            if (gpio_write(GPIO_IN2, 0) < 0) {
                syslog(LOG_ERR, LOG_ID, "Failed to set IN2 low");
                gpio_write(GPIO_ENA, 0);
                gpio_write(GPIO_IN1, 0);
                continue;
            }
        } else if (rain_sensor_value == 1 && prev_rain_sensor_value == 0) {
            // Dry, reset dry count
            dry_count = 0;
        } else {
            // Not rain or dry, increment dry count
            dry_count++;
            if (dry_count >= 3) {
                // Three consecutive dry polls, stop motor
                syslog(LOG_INFO, LOG_ID, "Three consecutive dry polls, stopping motor");
                gpio_write(GPIO_ENA, 0);
                gpio_write(GPIO_IN1, 0);
                gpio_write(GPIO_IN2, 0);
                dry_count = 0;
            }
        }
        prev_rain_sensor_value = rain_sensor_value;
        poll_count++;
        if (poll_count >= 10) {
            poll_count = 0;
            syslog(LOG_INFO, LOG_ID, "Poll count reset");
        }
    }

    // Clean up
    if (gpio_close(gpio) < 0) {
        syslog(LOG_ERR, LOG_ID, "Failed to close pigpio");
        return 1;
    }
    syslog(LOG_INFO, LOG_ID, "Cleaned up");
    return 0;
