#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define constants
#define GPIO_PIN 4
#define GPIO_PIN_RELAY 17
#define RELAY_VOLTAGE 12
#define POLL_INTERVAL 100
#define LOG_FILE "security_log.txt"

// Define a function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpioStop(GPIO_PIN_RELAY);
    gpioCleanUp();
    exit(0);
}

int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Install the signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the log file for writing
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioStop(GPIO_PIN_RELAY);
        gpioCleanUp();
        return 1;
    }

    // Open the relay pin for output
    if (gpioMode(GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(log_fd);
        gpioStop(GPIO_PIN_RELAY);
        gpioCleanUp();
        return 1;
    }

    // Set the relay pin high to turn off the floodlight
    if (gpioWrite(GPIO_PIN_RELAY, 0) < 0) {
        perror("gpioWrite");
        close(log_fd);
        gpioStop(GPIO_PIN_RELAY);
        gpioCleanUp();
        return 1;
    }

    // Open the log file for writing
    if (flock(log_fd, LOCK_EX | LOCK_NB) < 0) {
        perror("flock");
        gpioStop(GPIO_PIN_RELAY);
        gpioCleanUp();
        return 1;
    }

    // Main loop
    while (1) {
        // Check for rising edge on GPIO 4
        if (gpioRead(GPIO_PIN) < 0) {
            perror("gpioRead");
            flock(log_fd, LOCK_UN);
            close(log_fd);
            gpioStop(GPIO_PIN_RELAY);
            gpioCleanUp();
            return 1;
        }

        // Turn on the relay
        if (gpioWrite(GPIO_PIN_RELAY, 1) < 0) {
            perror("gpioWrite");
            flock(log_fd, LOCK_UN);
            close(log_fd);
            gpioStop(GPIO_PIN_RELAY);
            gpioCleanUp();
            return 1;
        }

        // Record the start time
        time_t start_time = time(NULL);

        // Wait for the specified interval
        usleep(POLL_INTERVAL * 1000);

        // Turn off the relay
        if (gpioWrite(GPIO_PIN_RELAY, 0) < 0) {
            perror("gpioWrite");
            flock(log_fd, LOCK_UN);
            close(log_fd);
            gpioStop(GPIO_PIN_RELAY);
            gpioCleanUp();
            return 1;
        }

        // Record the end time
        time_t end_time = time(NULL);

        // Calculate the duration
        double duration = difftime(end_time, start_time);

        // Append the log entry to the file
        char log_entry[256];
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S.%6fs %s", localtime(&start_time), localtime(&end_time), duration);
        if (fprintf(log_fd, "%s\n", log_entry) < 0) {
            perror("fprintf");
            flock(log_fd, LOCK_UN);
            close(log_fd);
            gpioStop(GPIO_PIN_RELAY);
            gpioCleanUp();
            return 1;
        }

        flock(log_fd, LOCK_UN);
        close(log_fd);
    }

    // Clean up
    gpioStop(GPIO_PIN_RELAY);
    gpioCleanUp();

    return 0;
}

