#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define LOG_FILE "security.log"
#define LOG Facility LOG_USER

int main(int argc, char **argv) {
    int gpio = -1;
    int sock = -1;
    int fd = -1;
    int ret = 0;
    struct sockaddr_in server;
    struct sigaction sa;
    struct sigaction sa_int;
    struct sigaction sa_term;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio < 0) {
        syslog(LOG_USER, "Error initializing GPIO: %s", strerror(errno));
        return 1;
    }

    // Set up servo GPIO
    if (gpio_set_mode(17, PI_OUTPUT) < 0) {
        syslog(LOG_USER, "Error setting servo GPIO mode: %s", strerror(errno));
        pigpio_close(gpio);
        return 1;
    }

    // Set up servo PWM
    if (gpio_pwm_set_frequency(17, 50) < 0) {
        syslog(LOG_USER, "Error setting servo PWM frequency: %s", strerror(errno));
        pigpio_close(gpio);
        return 1;
    }

    // Set up servo duty cycle
    if (gpio_pwm_set_duty(17, 1000) < 0) {
        syslog(LOG_USER, "Error setting servo duty cycle: %s", strerror(errno));
        pigpio_close(gpio);
        return 1;
    }

    // Set up PIR GPIO
    if (gpio_mode(4, PI_INPUT) < 0) {
        syslog(LOG_USER, "Error setting PIR GPIO mode: %s", strerror(errno));
        pigpio_close(gpio);
        return 1;
    }

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        syslog(LOG_USER, "Error creating socket: %s", strerror(errno));
        pigpio_close(gpio);
        return 1;
    }

    // Bind socket
    server.sin_family = AF_INET;
    server.sin_port = htons(5000);
    inet_pton(AF_INET, "127.0.0.1", &server.sin_addr);
    if (bind(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        syslog(LOG_USER, "Error binding socket: %s", strerror(errno));
        close(sock);
        pigpio_close(gpio);
        return 1;
    }

    // Listen for connections
    if (listen(sock, 3) < 0) {
        syslog(LOG_USER, "Error listening for connections: %s", strerror(errno));
        close(sock);
        pigpio_close(gpio);
        return 1;
    }

    // Set up signal handlers
    sa.sa_flags = SA_RESTART;
    sa.sa_handler = SIG_IGN;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_USER, "Error setting SIGINT handler: %s", strerror(errno));
        close(sock);
        pigpio_close(gpio);
        return 1;
    }
    sa_int.sa_flags = SA_RESTART;
    sa_int.sa_handler = SIG_IGN;
    if (sigaction(SIGTERM, &sa_int, NULL) < 0) {
        syslog(LOG_USER, "Error setting SIGTERM handler: %s", strerror(errno));
        close(sock);
        pigpio_close(gpio);
        return 1;
    }

    // Log file setup
    fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        syslog(LOG_USER, "Error opening log file: %s", strerror(errno));
        close(sock);
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        // Accept incoming connection
        struct sockaddr_in client;
        socklen_t client_len = sizeof(client);
        int conn = accept(sock, (struct sockaddr *)&client, &client_len);
        if (conn < 0) {
            syslog(LOG_USER, "Error accepting connection: %s", strerror(errno));
            continue;
        }

        // Read command from client
        char buf[1024];
        ret = read(conn, buf, 1024);
        if (ret < 0) {
            syslog(LOG_USER, "Error reading from client: %s", strerror(errno));
            close(conn);
            continue;
        }
        buf[ret] = '\0';
        syslog(LOG_USER, "Received command: %s", buf);

        // Parse command
        if (strcmp(buf, "PIR") == 0) {
            syslog(LOG_USER, "PIR detected");
            write(conn, "PIR:0", 5);
        } else if (sscanf(buf, "library%s", buf) == 1) {
            int angle = atoi(buf);
            if (angle < 0 || angle > 180) {
                syslog(LOG_USER, "Invalid angle: %d", angle);
                write(conn, "Error: invalid angle", 15);
            } else {
                // Set servo angle
                if (gpio_pwm_set_duty(17, angle) < 0) {
                    syslog(LOG_USER, "Error setting servo angle: %s", strerror(errno));
                    write(conn, "Error: servo angle", 15);
                } else {
                    syslog(LOG_USER, "Servo angle set to %d", angle);
                    write(conn, "OK", 2);
                }
            }
        } else {
            syslog(LOG_USER, "Unknown command: %s", buf);
            write(conn, "Error: unknown command", 15);
        }
    }

    // Close socket and log file
    close(sock);
    close(fd);
    pigpio_close(gpio);

    return 0;
}

