#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define HX711_DOUT 23
#define HX711_SCK 24
#define LOCK_GPIO 25
#define SCALE_FACTOR 0.01  // default scale factor
#define DURATION_MS 500
#define THRESHOLD 1000  // default threshold in grams
#define MAX_RETRIES 3

// HX711 structure
typedef struct {
    int gpio;
    int gain;
    int retries;
} hx711_t;

// Initialize HX711 structure
hx711_t hx711;

// Initialize GPIO
void init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }
    gpioSetMode(HX711_DOUT, GPIO_MODE_INPUT);
    gpioSetMode(HX711_SCK, GPIO_MODE_OUTPUT);
    gpioSetMode(LOCK_GPIO, GPIO_MODE_OUTPUT);
}

// Read HX711
int hx711_read() {
    int retries = 0;
    int result = 0;
    while (retries < MAX_RETRIES) {
        if (gpioRead(HX711_DOUT) == 0) {
            gpioWrite(HX711_SCK, 1);
            for (int i = 0; i < 24; i++) {
                gpioWrite(HX711_SCK, 0);
                usleep(10);
                gpioWrite(HX711_SCK, 1);
                usleep(10);
                result = (result << 1) | (gpioRead(HX711_DOUT) << (i + 1));
            }
            gpioWrite(HX711_SCK, 1); // extra clock pulse
            usleep(10);
            gpioWrite(HX711_SCK, 0);
            if (gpioRead(HX711_DOUT) == 0) {
                return result;
            }
        }
        retries++;
        syslog(LOG_ERR, "Failed to read HX711, retry %d", retries);
    }
    syslog(LOG_ERR, "Failed to read HX711 after %d retries", MAX_RETRIES);
    exit(1);
}

// Tare HX711
void hx711_tare() {
    int result = 0;
    for (int i = 0; i < 10; i++) {
        result += hx711_read();
    }
    result /= 10;
    result = (result & 0xFFFFFFF); // remove sign bit
    result = (result << 16) | (result >> 16); // convert to 24-bit two's complement
    result = result * hx711.gain;
    syslog(LOG_INFO, "Tare result: %d", result);
}

// Main loop
void loop() {
    int weight = 0;
    int scale_factor = SCALE_FACTOR;
    int duration = DURATION_MS;
    int threshold = THRESHOLD;
    int retries = 0;
    while (1) {
        if (gpioRead(LOCK_GPIO) == 0) {
            syslog(LOG_INFO, "Lock activated");
            gpioWrite(LOCK_GPIO, 1);
            usleep(duration);
            gpioWrite(LOCK_GPIO, 0);
            syslog(LOG_INFO, "Lock deactivated");
        }
        if (gpioRead(HX711_DOUT) == 0) {
            weight = hx711_read();
            weight = (weight & 0xFFFFFFF); // remove sign bit
            weight = (weight << 16) | (weight >> 16); // convert to 24-bit two's complement
            weight = weight * scale_factor;
            syslog(LOG_INFO, "Weight: %d", weight);
            if (weight > threshold) {
                syslog(LOG_INFO, "Weight exceeds threshold, activating lock");
                gpioWrite(LOCK_GPIO, 1);
                usleep(duration);
                gpioWrite(LOCK_GPIO, 0);
            }
        }
        usleep(500);
    }
}

int main(int argc, char **argv) {
    int scale_factor = SCALE_FACTOR;
    int duration = DURATION_MS;
    int threshold = THRESHOLD;
    hx711.gain = 128;
    hx711.retries = 0;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--scale") == 0) {
            if (i + 1 < argc) {
                scale_factor = atof(argv[++i]);
            } else {
                syslog(LOG_ERR, "Missing scale factor");
                return 1;
            }
        } else if (strcmp(argv[i], "--duration") == 0) {
            if (i + 1 < argc) {
                duration = atoi(argv[++i]);
            } else {
                syslog(LOG_ERR, "Missing duration");
                return 1;
            }
        } else if (strcmp(argv[i], "--threshold") == 0) {
            if (i + 1 < argc) {
                threshold = atoi(argv[++i]);
            } else {
                syslog(LOG_ERR, "Missing threshold");
                return 1;
            }
        }
    }

    // Initialize GPIO
    init_gpio();

    // Initialize HX711
    if (gpioGetPinMode(HX711_DOUT) != GPIO_MODE_INPUT) {
        syslog(LOG_ERR, "Invalid HX711 DOUT pin mode");
        return 1;
    }
    if (gpioGetPinMode(HX711_SCK) != GPIO_MODE_OUTPUT) {
        syslog(LOG_ERR, "Invalid HX711 SCK pin mode");
        return 1;
    }
    if (gpioGetPinMode(LOCK_GPIO) != GPIO_MODE_OUTPUT) {
        syslog(LOG_ERR, "Invalid LOCK GPIO pin mode");
        return 1;
    }

    // Tare HX711
    hx711_tare();

    // Main loop
    loop();

    // Shutdown GPIO
    gpioCleanUp();
    return 0;
}

