#include <time.h>

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio library\n");
        return 1;
    }

    // Define the GPIO pins for the servos
    const int servo_pins[] = {7, 8, 9, 10, 11};

    // Define the target pulse widths for each servo
    const uint32_t pulse_widths[] = {1000, 1500, 2000, 500, 2500};

    // Define the period of the PWM signal
    const uint32_t period = 20;

    // Define the duration of each servo pulse
    const uint32_t pulse_duration = 3;

    // Define the frequency of the PWM signal
    const uint32_t frequency = 50;

    // Calculate the duty cycle for each servo
    for (int i = 0; i < 5; i++) {
        uint32_t duty_cycle = (pulse_widths[i] * 1000) / period;
        printf("Servo %d: duty cycle = %u\n", i, duty_cycle);
    }

    // Generate PWM signals for each servo
    for (int i = 0; i < 5; i++) {
        // Set the servo pin as an output
        if (gpioMode(servo_pins[i], PI_OUTPUT) < 0) {
            printf("Failed to set servo pin %d as an output\n", servo_pins[i]);
            return 1;
        }

        // Generate a PWM signal for the servo
        if (gpioPWM(servo_pins[i], frequency, duty_cycle, period) < 0) {
            printf("Failed to generate PWM signal for servo %d\n", servo_pins[i]);
            return 1;
        }

        // Hold the pulse for the specified duration
        usleep(pulse_duration * 1000000);

        // Cleanly stop the PWM signal
        if (gpioPWM(servo_pins[i], 0, 0, period) < 0) {
            printf("Failed to stop PWM signal for servo %d\n", servo_pins[i]);
            return 1;
        }
    }

    // Cleanly stop all PWM signals
    for (int i = 0; i < 5; i++) {
        if (gpioPWM(servo_pins[i], 0, 0, period) < 0) {
            printf("Failed to stop PWM signal for servo %d\n", servo_pins[i]);
            return 1;
        }
    }

    // Release all GPIO resources
    for (int i = 0; i < 5; i++) {
        if (gpioMode(servo_pins[i], PI_INPUT) < 0) {
            printf("Failed to set servo pin %d as an input\n", servo_pins[i]);
            return 1;
        }
    }

    // Release the pigpio library
    gpioTerminate();

    return 0;
}

