#include <pthread.h>

#define PI 3.14159265359
#define RPM 50
#define TICKS_PER_REV 64
#define REV_PER_SEC 60
#define SEC_PER_MIN 60
#define TICKS_PER_MIN TICKS_PER_REV * REV_PER_SEC
#define TICKS_PER_HOUR TICKS_PER_MIN * SEC_PER_MIN
#define TICKS_PER_HOUR_TICKS_PER_MIN * SEC_PER_HOUR
#define TICKS_PER_HOUR_TICKS_PER_MIN * SEC_PER_HOUR
#define TICKS_PER_HOUR_TICKS_PER_MIN * SEC_PER_HOUR

#define PWM_FREQ 10000
#define PWM_MIN 0
#define PWM_MAX 255

#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define MAX_STALL_TIME 2

int gpio = -1;
int pwm = -1;
int encoder_a_phase_a = -1;
int encoder_a_phase_b = -1;
int encoder_b_phase_a = -1;
int encoder_b_phase_b = -1;
int motor_a_in1 = -1;
int motor_a_in2 = -1;
int motor_b_in3 = -1;
int motor_b_in4 = -1;

int motor_a_speed = 0;
int motor_b_speed = 0;
int motor_a_pwm = 0;
int motor_b_pwm = 0;
int motor_a_direction = 0;
int motor_b_direction = 0;
int encoder_a_ticks = 0;
int encoder_b_ticks = 0;
int stall_time = 0;
int stall_count = 0;

void* motor_control_thread(void* arg) {
    while (1) {
        if (gpio == -1 || pwm == -1 || encoder_a_phase_a == -1 || encoder_a_phase_b == -1 || encoder_b_phase_a == -1 || encoder_b_phase_b == -1 || motor_a_in1 == -1 || motor_a_in2 == -1 || motor_b_in3 == -1 || motor_b_in4 == -1) {
            printf("Error: GPIO or PWM or encoder or motor pins not initialized\n");
            break;
        }

        if (motor_a_direction == 1) {
            motor_a_pwm = motor_a_speed;
            motor_b_pwm = 0;
        } else {
            motor_a_pwm = 0;
            motor_b_pwm = motor_a_speed;
        }

        if (motor_a_pwm > PWM_MAX) motor_a_pwm = PWM_MAX;
        if (motor_a_pwm < PWM_MIN) motor_a_pwm = PWM_MIN;
        if (motor_b_pwm > PWM_MAX) motor_b_pwm = PWM_MAX;
        if (motor_b_pwm < PWM_MIN) motor_b_pwm = PWM_MIN;

        gpioWrite(motor_a_in1, motor_a_direction);
        gpioWrite(motor_a_in2, motor_a_pwm);
        gpioWrite(motor_b_in3, motor_b_direction);
        gpioWrite(motor_b_in4, motor_b_pwm);

        gpioRead(encoder_a_phase_a, &encoder_a_ticks);
        gpioRead(encoder_a_phase_b, &encoder_a_ticks);
        gpioRead(encoder_b_phase_a, &encoder_b_ticks);
        gpioRead(encoder_b_phase_b, &encoder_b_ticks);

        if (encoder_a_ticks == 0 && encoder_b_ticks == 0) {
            stall_time++;
            if (stall_time > MAX_STALL_TIME) {
                printf("Warning: Encoder stall detected\n");
                stall_count++;
            }
        } else {
            stall_time = 0;
            stall_count = 0;
        }

        printf("Motor A RPM: %.2f, Motor B RPM: %.2f, Motor A PWM: %d, Motor B PWM: %d\n", (encoder_a_ticks / TICKS_PER_REV * RPM / 60.0), (encoder_b_ticks / TICKS_PER_REV * RPM / 60.0), motor_a_pwm, motor_b_pwm);

        usleep(100);
    }

    gpioCleanUp();
    return NULL;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s <GPIO number>\n", argv[0]);
        return 1;
    }

    gpio = pigpioInit();
    if (gpio < 0) {
        printf("Error initializing GPIO\n");
        return 1;
    }

    if (gpioSetupInputPullUpDn(pi, ENCODER_A_PHASE_A, PI_INPUT_PULL_UP);
    if (gpioSetupInputPullUpDn(pi, ENCODER_A_PHASE_B, PI_INPUT_PULL_UP);
    if (gpioSetupInputPullUpDn(pi, ENCODER_B_PHASE_A, PI_INPUT_PULL_UP);
    if (gpioSetupInputPullUpDn(pi, ENCODER_B_PHASE_B, PI_INPUT_PULL_UP);
    if (gpioSetupInputPullUpDn(pi, MOTOR_A_IN1, PI_INPUT_PULL_UP);
    if (gpioSetupInputPullUpDn(pi, MOTOR_A_IN2, PI_INPUT_PULL_UP);
    if (gpioSetupInputPullUpDn(pi, MOTOR_B_IN3, PI_INPUT_PULL_UP);
    if (gpioSetupInputPullUpDn(pi, MOTOR_B_IN4, PI_INPUT_PULL_UP);

    if (gpioSetupPWM(pi, MOTOR_A_IN1, PWM_FREQ, PWM_MIN, PWM_MAX, &motor_a_pwm);
    if (gpioSetupPWM(pi, MOTOR_A_IN2, PWM_FREQ, PWM_MIN, PWM_MAX, &motor_a_pwm);
    if (gpioSetupPWM(pi, MOTOR_B_IN3, PWM_FREQ, PWM_MIN, PWM_MAX, &motor_b_pwm);
    if (gpioSetupPWM(pi, MOTOR_B_IN4, PWM_FREQ, PWM_MIN, PWM_MAX, &motor_b_pwm);

    if (gpioSetupInterrupt(pi, ENCODER_A_PHASE_A, GPIO_EDGE_RISING, motor_control_thread, NULL, NULL);
    if (gpioSetupInterrupt(pi, ENCODER_A_PHASE_B, GPIO_EDGE_RISING, motor_control_thread, NULL, NULL);
    if (gpioSetupInterrupt(pi, ENCODER_B_PHASE_A, GPIO_EDGE_RISING, motor_control_thread, NULL, NULL);
    if (gpioSetupInterrupt(pi, ENCODER_B_PHASE_B, GPIO_EDGE_RISING, motor_control_thread, NULL, NULL);

    signal(SIGINT, SIGINT_handler);

    while (1) {
        usleep(100);
    }

    return 0;
}

void SIGINT_handler(int sig) {
    gpioCleanUp();
    exit(0);
}

