#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define BH1750_ADDRESS 0x23
#define RELAY_PIN 17
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define RELAY_HYSTERESIS 50
#define RELAY_THRESHOLD 200
#define LOG_FILE "chicken_coop_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up I2C
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up relay
    if (gpioMode(RELAY_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set relay to low
    if (gpioWrite(RELAY_PIN, RELAY_LOW) < 0) {
        perror("gpioWrite");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Wait for 180ms
        usleep(180000);

        // Read sensor
        unsigned char data[3];
        if (i2cRead(i2c_fd, data, 3) < 0) {
            perror("i2cRead");
            close(i2c_fd);
            close(log_fd);
            gpioTerminate();
            return 1;
        }

        // Check if sensor is responding
        if (data[0] == 0x00) {
            printf("Sensor not responding\n");
            close(i2c_fd);
            close(log_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate lux
        int lux = (data[0] << 8) | data[1];

        // Check if it's dusk or dawn
        time_t now = time(NULL);
        struct tm *dt = localtime(&now);
        int hour = dt->tm_hour;
        int minute = dt->tm_min;
        if (hour >= 18 && hour < 6) {
            // Dusk
            if (lux < RELAY_THRESHOLD) {
                printf("Dusk: Lux = %d, Relay = ON\n", lux);
                gpioWrite(RELAY_PIN, RELAY_HIGH);
            }
        } else {
            // Dawn
            if (lux > RELAY_THRESHOLD) {
                printf("Dawn: Lux = %d, Relay = OFF\n", lux);
                gpioWrite(RELAY_PIN, RELAY_LOW);
            }
        }

        // Log data
        char log[100];
        sprintf(log, "%04d-%02d-%02d %02d:%02d:%02d: Lux = %d, Relay = %s\n",
                dt->tm_year + 1900, dt->tm_mon + 1, dt->tm_mday, dt->tm_hour, dt->tm_min, dt->tm_sec, lux, (lux < RELAY_THRESHOLD ? "ON" : "OFF"));
        if (write(log_fd, log, strlen(log)) < 0) {
            perror("write");
        }

        // Wait for 5 seconds
        usleep(500000);
    }

    // Clean up
    close(log_fd);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

