#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/times.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define GPIO_PIN_RELAY 17
#define DEBOUNCE_DELAY 50
#define RELAY_PIN 11
#define RELAY_VCC 5

int main(int argc, char *argv[]) {
    struct timespec start_time;
    struct timespec end_time;
    struct timespec sleep_time;
    struct itimerval it;
    struct sigaction sa;
    int gpio;
    int relay_state = 0;
    int last_state = 0;
    int error = 0;

    // Initialize GPIO
    if (gpio = gpioInitialise()) {
        fprintf(stderr, "Error initializing GPIO: %d\n", gpio);
        return 1;
    }

    // Set GPIO 4 as input
    if (gpioMode(GPIO_PIN, GPIO_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input: %d\n", GPIO_PIN, gpio);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    if (gpioMode(GPIO_PIN_RELAY, GPIO_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %d\n", GPIO_PIN_RELAY, gpio);
        gpioTerminate();
        return 1;
    }

    // Set relay VCC to 5V
    if (gpioSetVoltage(RELAY_PIN, RELAY_VCC) != 0) {
        fprintf(stderr, "Error setting relay VCC to %dV: %d\n", RELAY_VCC, gpio);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler for SIGINT: %d\n", errno);
        gpioTerminate();
        return 1;
    }

    // Set up timer
    it.it_value.tv_sec = 0;
    it.it_value.tv_usec = 0;
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_usec = 10000;
    if (setitimer(ITIMER_REAL, &it, &it) == -1) {
        fprintf(stderr, "Error setting up timer: %d\n", errno);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read GPIO 4
        int value = gpioRead(GPIO_PIN);
        if (value == 0) {
            // Debounce
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec != start_time.tv_sec || now.tv_nsec != start_time.tv_nsec) {
                start_time = now;
            }
            if (now.tv_sec != end_time.tv_sec || now.tv_nsec != end_time.tv_nsec) {
                end_time = now;
                if (end_time.tv_sec - start_time.tv_sec >= DEBOUNCE_DELAY) {
                    // Toggle relay
                    if (relay_state == 0) {
                        gpioWrite(GPIO_PIN_RELAY, 1);
                        printf("%s RELAY: ON\n", ctime(&start_time));
                        relay_state = 1;
                    } else {
                        gpioWrite(GPIO_PIN_RELAY, 0);
                        printf("%s RELAY: OFF\n", ctime(&start_time));
                        relay_state = 0;
                    }
                }
            }
        } else {
            // Reset debounce
            start_time.tv_sec = 0;
            start_time.tv_nsec = 0;
            end_time.tv_sec = 0;
            end_time.tv_nsec = 0;
        }

        // Sleep
        sleep_time.tv_sec = 0;
        sleep_time.tv_usec = 0;
        if (nanosleep(&sleep_time, NULL) == -1) {
            fprintf(stderr, "Error sleeping: %d\n", errno);
            gpioTerminate();
            return 1;
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(GPIO_PIN_RELAY, 0);
    printf("%s RELAY: OFF\n", ctime(&times(gettimes()));
    exit(0);
}

