#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_FLOW_SENSOR 17
#define GPIO_SOLENOID 27
#define DEBOUNCE_TIMEOUT 1000 // 1 second
#define LOG_FILE "water_flow.log"
#define LOG_LEVEL LOG_INFO

// Structure to hold log data
typedef struct {
    time_t timestamp;
    int flow_rate;
    int solenoid_state;
} log_entry_t;

// Mutex for protecting the shared pulse counter
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Shared pulse counter
int pulse_count = 0;

// Flag to track solenoid state
int solenoid_state = 1;

// Function to log a log entry
void log_entry(log_entry_t entry) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        exit(1);
    }

    fprintf(log_file, "%ld %d %d\n", entry.timestamp, entry.flow_rate, entry.solenoid_state);
    fclose(log_file);
}

// Function to handle flow sensor events
void *flow_sensor_isr(void *arg) {
    while (1) {
        // Read the flow sensor value
        int flow_value = gpio_get_value(GPIO_FLOW_SENSOR);
        if (flow_value == 0) {
            // Debounce timeout
            usleep(DEBOUNCE_TIMEOUT);
            continue;
        }

        // Increment the pulse counter
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);

        // Check if the flow rate exceeds 5.0 LPM
        if (pulse_count > 300) { // 300 pulses per second = 300 LPM
            solenoid_state = 0;
            log_entry((log_entry_t) {time(NULL), 5.0, solenoid_state});
        } else if (pulse_count > 0) {
            // Check if the flow rate drops below 4.5 LPM
            if (pulse_count < 200) { // 200 pulses per second = 200 LPM
                solenoid_state = 1;
                log_entry((log_entry_t) {time(NULL), 4.5, solenoid_state});
            }
        }

        pulse_count = 0;
    }
}

int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() != 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver: %s", strerror(errno));
        return 1;
    }

    // Set the flow sensor pin as an input with a pull-up resistor
    if (gpioMode(GPIO_FLOW_SENSOR, GPIO_IN) != 0) {
        syslog(LOG_ERR, "Failed to set flow sensor pin mode: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the solenoid pin as an output
    if (gpioMode(GPIO_SOLENOID, GPIO_OUT) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin mode: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the solenoid pin as a high impedance output
    if (gpioSetPullUpDn(GPIO_SOLENOID, GPIO_PUD_OFF) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin pull-up resistor: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the solenoid pin high
    if (gpioWrite(GPIO_SOLENOID, 1) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin high: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Create a thread to handle flow sensor events
    pthread_t flow_sensor_thread;
    if (pthread_create(&flow_sensor_thread, NULL, flow_sensor_isr, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create flow sensor thread: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open the log file
    if (access(LOG_FILE, F_OK) == -1) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        pthread_join(flow_sensor_thread, NULL);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set SIGINT handler: %s", strerror(errno));
        pthread_join(flow_sensor_thread, NULL);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler: %s", strerror(errno));
        pthread_join(flow_sensor_thread, NULL);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pthread_join(flow_sensor_thread, NULL);
    gpioTerminate();
    return 0;
}

