#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>

#define GPIO_PIN 17
#define DEBOUNCE_WINDOW 10
#define CLOCK_INTERVAL 5
#define LOG_FILE "motor_rpm.log"

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", gpioInitialise());
        return 1;
    }

    // Set up GPIO pin
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode: %d\n", gpioSetMode(GPIO_PIN));
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up bias
    if (gpioPullUpDowntime(GPIO_PIN, PI_HIGH) < 0) {
        fprintf(stderr, "Error enabling pull-up bias: %d\n", gpioPullUpDowntime(GPIO_PIN));
        gpioTerminate();
        return 1;
    }

    // Set up debouncing
    struct timespec debounce_start;
    struct timespec debounce_end;
    gpioGetEdge(GPIO_PIN, PI_EDGE_RISING, &debounce_start, &debounce_end);

    // Initialize log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %d\n", log_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize monotonic clock
    clockid_t clock_id = clock_getid(CLOCK_MONOTONIC);
    if (clock_id < 0) {
        fprintf(stderr, "Error getting monotonic clock: %d\n", clock_id);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        struct timespec now;
        clock_gettime(clock_id, &now);

        // Read GPIO pin
        struct timespec read_start;
        struct timespec read_end;
        gpioGetEdge(GPIO_PIN, PI_EDGE_RISING, &read_start, &read_end);
        if (read_start.tv_sec != debounce_start.tv_sec || read_start.tv_nsec != debounce_end.tv_nsec) {
            // Debounce
            struct timespec sleep_start;
            struct timespec sleep_end;
            clock_gettime(clock_id, &sleep_start);
            sleep((debounce_start.tv_sec - sleep_start.tv_sec) * 1000000 + (debounce_start.tv_nsec - sleep_start.tv_nsec));
            clock_gettime(clock_id, &sleep_end);
            if (sleep_end.tv_sec != debounce_start.tv_sec || sleep_end.tv_nsec != debounce_end.tv_nsec) {
                continue;
            }
        }

        // Count pulses
        int pulses = 0;
        struct timespec sleep_start;
        struct timespec sleep_end;
        clock_gettime(clock_id, &sleep_start);
        for (int i = 0; i < CLOCK_INTERVAL; i++) {
            struct timespec read_start;
            struct timespec read_end;
            gpioGetEdge(GPIO_PIN, PI_EDGE_RISING, &read_start, &read_end);
            if (read_start.tv_sec != debounce_start.tv_sec || read_start.tv_nsec != debounce_end.tv_nsec) {
                continue;
            }
            pulses++;
        }
        clock_gettime(clock_id, &sleep_end);

        // Calculate RPM
        double rpm = (double)pulses / (CLOCK_INTERVAL / 1000000000.0);

        // Write to log file
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", localtime(&now));
        fprintf(log_fd, "%s,%f\n", timestamp, rpm);
        fflush(log_fd);

        // Print RPM
        printf("%.2f RPM\n", rpm);
    }

    // Clean up
    close(log_fd);
    gpioTerminate();
    return 0;
}

