#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define RELAY_PIN 5
#define TOUCH_PIN 0
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define TOUCH_TIMEOUT 10000 // 10 seconds

volatile sig_atomic_t exit = 0;

void sigint_handler(int sig) {
    exit = 1;
}

void cleanup() {
    if (gpioWrite(RELAY_GPIO, RELAY_LOW) < 0) {
        fprintf(stderr, "Error releasing relay GPIO %d\n", RELAY_GPIO);
        exit(1);
    }
    gpioCleanUp();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        exit(1);
    }

    if (gpioMode(TOUCH_GPIO, GPIO_INPUT) < 0) {
        fprintf(stderr, "Error setting TOUCH_GPIO mode\n");
        exit(1);
    }

    if (gpioMode(RELAY_GPIO, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting RELAY_GPIO mode\n");
        exit(1);
    }

    if (gpioWrite(RELAY_GPIO, RELAY_LOW) < 0) {
        fprintf(stderr, "Error setting relay GPIO %d to LOW\n", RELAY_GPIO);
        exit(1);
    }

    while (!exit) {
        int touch_state = gpioRead(TOUCH_GPIO);
        if (touch_state == 0) {
            if (gpioRead(RELAY_GPIO) == RELAY_LOW) {
                gpioWrite(RELAY_GPIO, RELAY_HIGH);
            }
        } else {
            if (gpioRead(RELAY_GPIO) == RELAY_HIGH) {
                gpioWrite(RELAY_GPIO, RELAY_LOW);
            }
        }

        if (gpioRead(TOUCH_GPIO) == 0 && gpioRead(RELAY_GPIO) == RELAY_HIGH) {
            if (time(NULL) - gpioGetTimestamp(TOUCH_GPIO) > TOUCH_TIMEOUT) {
                gpioWrite(RELAY_GPIO, RELAY_LOW);
            }
        }

        usleep(50000);
    }

    cleanup();

    return 0;
}

