#include <time.h>

#define LOCK1 GPIO_BCM_17
#define LOCK2 GPIO_BCM_27
#define BUTTON GPIO_BCM_22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define TAG_SIZE 10
#define TAG_VALUE 0x1234567890abcdef

struct tag {
    uint8_t data[10];
};

int main() {
    int fd;
    struct pigpio *gpio;
    struct tag tag;
    struct timespec start, end;
    int lock1, lock2, button, ret, tag_len;
    char log_file[256];

    // Initialize pigpio
    gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        return 1;
    }

    // Set up GPIO pins
    lock1 = gpio_get(GPIO_17);
    lock2 = gpio_get(GPIO_27);
    button = gpio_get(GPIO_22);
    gpio_set_mode(lock1, PI_INPUT);
    gpio_set_mode(lock2, PI_INPUT);
    gpio_set_mode(button, PI_INPUT);
    gpio_pull_up_down(button, PI_PUD_UP);

    // Open log file
    fd = open("/var/log/door_access.log", O_RDWR | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Set up SPI interface
    ret = spi_open(&fd, SPI_CHANNEL, SPI_SPEED);
    if (ret != 0) {
        perror("spi_open");
        close(fd);
        return 1;
    }

    while (1) {
        // Poll RFID reader
        ret = spi_read(&fd, &tag, TAG_SIZE);
        if (ret != TAG_SIZE) {
            if (ret == 0) {
                // No tag present
                syslog(LOG_INFO, "%s: No tag present", ctime(&start));
            } else {
                syslog(LOG_INFO, "%s: RFID read failure", ctime(&start));
            }
            continue;
        }

        // Verify tag
        if (memcmp(tag.data, TAG_VALUE, TAG_SIZE) == 0) {
            syslog(LOG_INFO, "%s: Valid tag", ctime(&start));
            // Require button press
            while (1) {
                // Check button state
                ret = gpio_read(button);
                if (ret == 0) {
                    // Button pressed
                    syslog(LOG_INFO, "%s: Button pressed", ctime(&start));
                    // Disengage locks
                    gpio_write(lock1, 0);
                    gpio_write(lock2, 0);
                    sleep(5);
                    gpio_write(lock1, 1);
                    gpio_write(lock2, 1);
                    break;
                }
                usleep(50 * 1000);
            }
        } else {
            syslog(LOG_INFO, "%s: Invalid tag", ctime(&start));
        }

        // Log access attempt
        syslog(LOG_INFO, "%s", ctime(&start));
        syslog(LOG_INFO, "%s", ctime(&end));
    }

    // Clean up
    close(fd);
    pigpio_close(gpio);
    return 0;
}

