gpiod_line_t *motor1Ena, *motor1In1, *motor1In2, *motor2Enb, *motor2In3, *motor2In4;
gpiod_line_t *encoder1A, *encoder1B, *encoder2A, *encoder2B;
pthread_mutex_t encoderMutex1, encoderMutex2;
FILE *logFile;

// Function to initialize the motor drivers
void initMotors() {
    // Initialize GPIO lines
    motor1.ena = gpiod_get_line(GPIO_MOTOR1_ENA, &motor1Dev);
    motor1.in1 = gpiod_get_line(GPIO_MOTOR1_IN1, &motor1Dev);
    motor1.in2 = gpiod_get_line(GPIO_MOTOR1_IN2, &motor1Dev);
    motor2.enb = gpiod_get_line(GPIO_MOTOR2_ENB, &motor2Dev);
    motor2.in3 = gpiod_get_line(GPIO_MOTOR2_IN3, &motor2Dev);
    motor2.in4 = gpiod_get_line(GPIO_MOTOR2_IN4, &motor2Dev);
    encoder1A = gpiod_get_line(GPIO_ENCODER1_A, &encoder1Dev);
    encoder1B = gpiod_get_line(GPIO_ENCODER1_B, &encoder1Dev);
    encoder2A = gpiod_get_line(GPIO_ENCODER2_A, &encoder2Dev);
    encoder2B = gpiod_get_line(GPIO_ENCODER2_B, &encoder2Dev);

    // Configure encoder lines
    gpiod_line_config(motor1.in1, GPIOD_LINE_EDGE_RISING);
    gpiod_line_config(motor1.in2, GPIOD_LINE_EDGE_RISING);
    gpiod_line_config(motor2.in3, GPIOD_LINE_EDGE_RISING);
    gpiod_line_config(motor2.in4, GPIOD_LINE_EDGE_RISING);
    gpiod_line_config(encoder1A, GPIOD_LINE_EDGE_RISING);
    gpiod_line_config(encoder1B, GPIOD_LINE_EDGE_RISING);
    gpiod_line_config(encoder2A, GPIOD_LINE_EDGE_RISING);
    gpiod_line_config(encoder2B, GPIOD_LINE_EDGE_RISING);

    // Set up log file
    logFile = fopen(GPIO_LOG_FILE, "w");
    if (logFile == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(1);
    }

    // Set up PID
    pid.Kp = 2.0;
    pid.Ki = 0.5;
    pid.Kd = 1.0;
    pid.targetSpeed = 60.0;
    pid.prevError = 0.0;
    pid.prevErrorIntegral = 0.0;
    pid.prevErrorDerivative = 0.0;
    pid.prevOutput = 0.0;
}

// Function to read encoder values
void readEncoders() {
    pthread_mutex_lock(&encoderMutex1);
    encoder1.encA = gpiod_get_value(encoder1A);
    encoder1.encB = gpiod_get_value(encoder1B);
    pthread_mutex_unlock(&encoderMutex1);

    pthread_mutex_lock(&encoderMutex2);
    encoder2.encA = gpiod_get_value(encoder2A);
    encoder2.encB = gpiod_get_value(encoder2B);
    pthread_mutex_unlock(&encoderMutex2);
}

// Function to update PID
void updatePID() {
    double error = pid.targetSpeed - (encoder1.encA - encoder1.encB);
    pid.errorIntegral += error;
    pid.errorDerivative = (error - pid.prevError) / 0.1;
    pid.prevError = error;
    pid.prevErrorIntegral = pid.errorIntegral;
    pid.prevErrorDerivative = pid.errorDerivative;

    double output = pid.Kp * error + pid.Ki * pid.errorIntegral + pid.Kd * pid.errorDerivative;
    output = (output > 1.0) ? 1.0 : (output < -1.0) ? -1.0 : output;

    // Calculate duty cycle
    int dutyCycle = (int)(output * 100);
    if (dutyCycle < 0) {
        dutyCycle = 0;
    } else if (dutyCycle > 100) {
        dutyCycle = 100;
    }

    // Set motor speeds
    gpiod_set_value(motor1.ena, 1);
    gpiod_set_value(motor1.in1, dutyCycle);
    gpiod_set_value(motor1.in2, 0);
    gpiod_set_value(motor2.enb, 1);
    gpiod_set_value(motor2.in3, dutyCycle);
    gpiod_set_value(motor2.in4, 0);

    // Update PID output
    pid.prevOutput = output;
}

// Function to log data
void logData() {
    fprintf(logFile, "%d,%d,%d,%d,%f,%f,%f,%f\n",
            motor1.motor, motor1.ena, motor1.in1, motor1.in2, pid.prevOutput, pid.Kp, pid.Ki, pid.Kd);
    fflush(logFile);
}

// Function to handle SIGINT
void sigintHandler(int sig) {
    // Stop motors
    gpiod_set_value(motor1.ena, 0);
    gpiod_set_value(motor1.in1, 0);
    gpiod_set_value(motor1.in2, 0);
    gpiod_set_value(motor2.enb, 0);
    gpiod_set_value(motor2.in3, 0);
    gpiod_set_value(motor2.in4, 0);

    // Release GPIO lines
    gpiod_line_release(motor1Ena);
    gpiod_line_release(motor1In1);
    gpiod_line_release(motor1In2);
    gpiod_line_release(motor2Enb);
    gpiod_line_release(motor2In3);
    gpiod_line_release(motor2In4);
    gpiod_line_release(encoder1A);
    gpiod_line_release(encoder1B);
    gpiod_line_release(encoder2A);
    gpiod_line_release(encoder2B);

    // Close log file
    fclose(logFile);

    // Exit
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    // Initialize motors
    initMotors();

    // Initialize PID
    pid.Kp = 2.0;
    pid.Ki = 0.5;
    pid.Kd = 1.0;
    pid.targetSpeed = 60.0;
    pid.prevError = 0.0;
    pid.prevErrorIntegral = 0.0;
    pid.prevErrorDerivative = 0.0;
    pid.prevOutput = 0.0;

    // Start encoder monitoring threads
    pthread_t encoderThread1, encoderThread2;
    pthread_create(&encoderThread1, NULL, readEncoders, NULL);
    pthread_create(&encoderThread2, NULL, readEncoders, NULL);

    // Main loop
    while (1) {
        // Update PID
        updatePID();

        // Log data
        logData();

        // Sleep
        usleep(100000);
    }

    // Wait for encoder threads to finish
    pthread_join(encoderThread1, NULL);
    pthread_join(encoderThread2, NULL);

    // Release GPIO lines
    gpiod_line_release(motor1Ena);
    gpiod_line_release(motor1In1);
    gpiod_line_release(motor1In2);
    gpiod_line_release(motor2Enb);
    gpiod_line_release(motor2In3);
    gpiod_line_release(motor2In4);
    gpiod_line_release(encoder1A);
    gpiod_line_release(encoder1B);
    gpiod_line_release(encoder2A);
    gpiod_line_release(encoder2B);

    // Close log file
    fclose(logFile);

    // Close GPIO devices
    gpiod_close(motor1Dev);
    gpiod_close(motor2Dev);

    return 0;
}
