#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define MPR121_ADDRESS 0x5A
#define RELAY_GPIO 17
#define RELAY_LOG_FILE "relay_log.txt"

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus 1
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Perform MPR121 initialization sequence
    if (mpir121_init(i2c_fd, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00) < 0) {
        perror("mpir121_init");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure filtering parameters
    if (mpir121_config(i2c_fd, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00) < 0) {
        perror("mpir121_config");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set touch and release thresholds for each electrode
    for (int i = 0; i < 12; i++) {
        if (mpir121_set_threshold(i, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00) < 0) {
            perror("mpir121_set_threshold");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Enable run mode
    if (mpir121_run(i2c_fd, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00) < 0) {
        perror("mpir121_run");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open relay GPIO
    if (gpioMode(RELAY_GPIO, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(RELAY_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read touch status of all electrodes
        unsigned char touch_status[12];
        if (mpir121_read(i2c_fd, touch_status, 12) < 0) {
            perror("mpir121_read");
            close(i2c_fd);
            gpioTerminate();
            fclose(log_file);
            return 1;
        }

        // Check for touched electrodes
        for (int i = 0; i < 12; i++) {
            if (touch_status[i] & 0x01) {
                // Set relay output HIGH
                gpioWrite(RELAY_GPIO, 1);
                fprintf(log_file, "%d %d\n", time(NULL), i);
            } else {
                // Set relay output LOW
                gpioWrite(RELAY_GPIO, 0);
                fprintf(log_file, "%d %d\n", time(NULL), i);
            }
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    gpioTerminate();
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

