#define VALVE2_GPIO 18
#define VALVE1_RELAY 1
#define VALVE2_RELAY 0
#define VALVE1_FILE "valve1_log.txt"
#define VALVE2_FILE "valve2_log.txt"
#define LOG_FILE "valve_log.txt"

int main() {
    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    // Open log files
    int log_fd1 = open(VALVE1_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd1 < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }
    int log_fd2 = open(VALVE2_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd2 < 0) {
        perror("open");
        close(log_fd1);
        gpioTerminate();
        return 1;
    }
    close(log_fd1);
    close(log_fd2);

    // Set up GPIO pins
    if (gpioSetupInputEdge(VALVE1_GPIO, PI_INPUT_EDGE_RISING) < 0) {
        perror("gpioSetupInputEdge");
        close(log_fd2);
        close(log_fd1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetupInputEdge(VALVE2_GPIO, PI_INPUT_EDGE_RISING) < 0) {
        perror("gpioSetupInputEdge");
        close(log_fd2);
        close(log_fd1);
        gpioTerminate();
        return 1;
    }

    // Set up relay pins
    if (gpioSetupRelay(VALVE1_GPIO, VALVE1_RELAY) < 0) {
        perror("gpioSetupRelay");
        close(log_fd2);
        close(log_fd1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetupRelay(VALVE2_GPIO, VALVE2_RELAY) < 0) {
        perror("gpioSetupRelay");
        close(log_fd2);
        close(log_fd1);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        gpioWrite(VALVE1_GPIO, 1);
        printf("%s\n", ctime(time(NULL));
        if (log_fd1 >= 0) {
            char log_str[256];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", time(NULL));
            write(log_fd1, log_str, strlen(log_str));
        }
        sleep(0.5);

