        sleep(5);

        // Activate Valve 2
        gpioWrite(VALVE2_GPIO, 1);
        printf("%s\n", ctime(time(NULL)));
        if (log_fd2 >= 0) {
            char log_str[256];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", time(NULL));
            write(log_fd2, log_str, strlen(log_str));
        }
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    close(log_fd1);
    close(log_fd2);
    return 0;
}

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
