#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_PIN 17
#define GPIO_PIN_RELAY 18
#define INTERVAL 50
#define UNLOCK_DURATION 500
#define RATE_LIMIT_DURATION 2000
#define LOG_FILE "door_events.log"

int main(int argc, char **argv) {
    int gpio;
    int relay;
    int rate_limit = 0;
    struct timespec last_rate_limit = {0, 0};
    struct timespec last_unlock = {0, 0};
    FILE *log_file;

    // Initialize GPIO
    if (gpio = pigpio_init()) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %d", gpio);
        return 1;
    }

    // Configure GPIO pin as input with pull-down
    if (gpio_mode(GPIO_PIN, GPIO_IN) < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO pin %d as input: %d", GPIO_PIN, gpio);
        pigpio_close(gpio);
        return 1;
    }

    // Configure GPIO pin as output for relay
    if (gpio_mode(GPIO_PIN_RELAY, GPIO_OUT) < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO pin %d as output: %d", GPIO_PIN_RELAY, gpio);
        pigpio_close(gpio);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file %s: %d", LOG_FILE, errno);
        pigpio_close(gpio);
        return 1;
    }

    // Set relay to off
    if (gpio_write(GPIO_PIN_RELAY, 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay pin %d to off: %d", GPIO_PIN_RELAY, gpio);
        fclose(log_file);
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        // Read GPIO pin
        int value = gpio_read(GPIO_PIN);
        if (value == 1) {
            // Check if rate limit has expired
            if (time(NULL) - last_rate_limit.tv_sec > RATE_LIMIT_DURATION) {
                // Reset rate limit
                last_rate_limit = {0, 0};
                // Unlock door
                if (gpio_write(GPIO_PIN_RELAY, 1) < 0) {
                    syslog(LOG_ERR, "Failed to set relay pin %d to on: %d", GPIO_PIN_RELAY, gpio);
                    fclose(log_file);
                    pigpio_close(gpio);
                    return 1;
                }
                // Log event
                fprintf(log_file, "%ld %ld\n", time(NULL), last_unlock.tv_sec);
                last_unlock = {time(NULL), 0};
            } else {
                // Ignore event due to rate limit
                continue;
            }
        } else {
            // Log event
            fprintf(log_file, "%ld %ld\n", time(NULL), last_rate_limit.tv_sec);
            last_rate_limit = {0, 0};
            last_unlock = {0, 0};
        }
        // Wait for interval
        usleep(INTERVAL * 1000000);
    }

    // Clean up
    if (fclose(log_file) < 0) {
        syslog(LOG_ERR, "Failed to close log file %s: %d", LOG_FILE, errno);
    }
    pigpio_close(gpio);
    return 0;
}

