#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/times.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

volatile sig_atomic_t shutdown = 0;

void generate_pattern(pigpio *gpio, int motor1, int motor2) {
    int i, j;
    int duration = rand() % 150 + 50; // random duration between 50ms and 200ms
    int steps = rand() % 7 + 5; // random number of steps between 5 and 12
    int duty_cycle1 = rand() % 256; // random duty cycle between 0 and 255
    int duty_cycle2 = rand() % 256; // random duty cycle between 0 and 255

    for (i = 0; i < steps; i++) {
        gpio_set PWM(gpio, motor1, duty_cycle1, duration);
        gpio_set PWM(gpio, motor2, duty_cycle2, duration);
        usleep(duration * 1000);
        duty_cycle1 = (duty_cycle1 + 1) % 256;
        duty_cycle2 = (duty_cycle2 + 1) % 256;
    }
}

int main(int argc, char **argv) {
    pigpio *gpio;
    struct sigaction sa;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO mode
    if (gpio_set_mode(gpio, 17, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        return 1;
    }
    if (gpio_set_mode(gpio, 27, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO 27 as output\n");
        gpio_close(gpio);
        return 1;
    }

    // Set PWM frequency
    if (gpio_set PWM(gpio, 17, 1000, 0) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO 17\n");
        gpio_close(gpio);
        return 1;
    }
    if (gpio_set PWM(gpio, 27, 1000, 0) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO 27\n");
        gpio_close(gpio);
        return 1;
    }

    // Seed random number generator
    srand(time(NULL));

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpio_close(gpio);
        return 1;
    }

    while (!shutdown) {
        generate_pattern(gpio, 17, 27);
    }

    // Clean up
    gpio_close(gpio);
    return 0;
}

void sigint_handler(int sig) {
    shutdown = 1;
}

