#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <libgpiod.h>

#define GPIO_HX711_DATA 4
#define GPIO_HX711_CLOCK 17
#define GPIO_SOLENOID 27
#define GPIO_LOG_FILE "weight_log.txt"
#define CALIBRATION_FILE "calibration.txt"
#define CALIBRATION_DEFAULT_SCALE 1.0
#define CALIBRATION_DEFAULT_OFFSET 0.0
#define CALIBRATION_READS 100
#define CALIBRATION_TIMEOUT 0.5
#define CALIBRATION_THRESHOLD 10.0

int main() {
    // Initialize GPIO driver
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    int log_fd = open(GPIO_LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Open calibration file
    int calib_fd = open(CALIBRATION_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (calib_fd < 0) {
        perror("open");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Read calibration data from file
    char calib_line[256];
    if (fgets(calib_line, sizeof(calib_line), calib_fd) == NULL) {
        // No calibration data, use defaults
        double scale = CALIBRATION_DEFAULT_SCALE;
        double offset = CALIBRATION_DEFAULT_OFFSET;
    } else {
        // Parse calibration data
        char *ptr = strtok(calib_line, " \t\n");
        if (ptr == NULL || ptr == NULL) {
            // Invalid calibration data, use defaults
            double scale = CALIBRATION_DEFAULT_SCALE;
            double offset = CALIBRATION_DEFAULT_OFFSET;
        } else {
            scale = atof(ptr);
            ptr = strtok(NULL, " \t\n");
            if (ptr == NULL) {
                // Invalid calibration data, use defaults
                double scale = CALIBRATION_DEFAULT_SCALE;
                double offset = CALIBRATION_DEFAULT_OFFSET;
            } else {
                offset = atof(ptr);
            }
        }
    }

    // Perform one-time startup calibration
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_READS; i++) {
        int status = HX711ReadCalibration(gpioGetPin(GPIO_HX711_DATA), gpioGetPin(GPIO_HX711_CLOCK), &sum);
        if (status < 0) {
            perror("HX711ReadCalibration");
            gpioTerminate();
            close(log_fd);
            close(calib_fd);
            return 1;
        }
    }
    double calib_offset = sum / CALIBRATION_READS;
    double calib_scale = 1.0 / calib_offset;

    // Main loop
    while (1) {
        // Read HX711 data
        int status = HX711Read(gpioGetPin(GPIO_HX711_DATA), gpioGetPin(GPIO_HX711_CLOCK), &sum);
        if (status < 0) {
            perror("HX711Read");
            gpioTerminate();
            close(log_fd);
            close(calib_fd);
            return 1;
        }

        // Check for timeout
        if (time(NULL) - time(NULL) > CALIBRATION_TIMEOUT) {
            continue;
        }

        // Compute weight
        double weight = sum * calib_scale;

        // Engage solenoid
        if (weight > CALIBRATION_THRESHOLD) {
            gpioWrite(gpioGetPin(GPIO_SOLENOID), GPIO_HIGH);
        } else {
            gpioWrite(gpioGetPin(GPIO_SOLENOID), GPIO_LOW);
        }

        // Log weight
        char log_line[256];
        sprintf(log_line, "%f\n", weight);
        write(log_fd, log_line, strlen(log_line));

        // Write updated calibration data to file
        char calib_line[256];
        sprintf(calib_line, "%f %f\n", calib_scale, calib_offset);
        write(calib_fd, calib_line, strlen(calib_line));
    }

    // Clean up
    gpioTerminate();
    close(log_fd);
