#include <fcntl.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define GPIO_DT 23
#define GPIO_SCK 24
#define GPIO_LOCK 17
#define FILE_NAME "stock_events.txt"

// HX711 configuration
#define HX711_GND 25
#define HX711_VCC 26
#define HX711_DOUT 27
#define HX711_SCK 28
#define HX711_DIN 29

// GPIO pin configuration
#define GPIO_PIN 17

// Function to initialize GPIO
void init_gpio(pigpio *gpio) {
    if (gpio->init(GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("GPIO init failed");
        exit(1);
    }
    gpio-> pwmSetFrequency(GPIO_PIN, 1000);
}

// Function to read HX711 data
int read_hx711(pigpio *gpio) {
    int fd = open(HX711_DIN, O_RDWR);
    if (fd < 0) {
        perror("HX711 DIN open failed");
        return -1;
    }

    if (ioctl(fd, HX711_READ_DATA, gpio) < 0) {
        perror("HX711 read failed");
        close(fd);
        return -1;
    }

    int weight = (gpio->read(GPIO_DT) << 8) | gpio->read(GPIO_SCK);
    close(fd);
    return weight;
}

// Function to log event
void log_event(char *message) {
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("File open failed");
        return;
    }

    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(file, "%s %s\n", timestamp, message);
    fclose(file);
}

// Function to activate solenoid
void activate_solenoid(pigpio *gpio) {
    gpio->digitalWrite(GPIO_LOCK, 1);
    sleep(5);
    gpio->digitalWrite(GPIO_LOCK, 0);
}

int main(int argc, char **argv) {
    pigpio *gpio = new pigpio();
    if (gpio == NULL) {
        perror("GPIO init failed");
        return 1;
    }

    init_gpio(gpio);

    while (1) {
        int weight = read_hx711(gpio);
        if (weight < 100) {
            activate_solenoid(gpio);
            log_event("Solenoid activated");
        }

        log_event("Weight: %d g", weight);
        sleep(1);
    }

    gpio->cleanUp();
    delete gpio;

    return 0;
}

