#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <time.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_LOCK_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"

// Structure to hold calibration data
typedef struct {
    float calibration_factor;
    time_t last_calibration;
} CalibrationData;

// Function to initialize the GPIO pins
void init_gpio(pigpio *gpio) {
    gpio_set_mode(HX711_DATA_PIN, PI_INPUT);
    gpio_set_mode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpio_set_mode(SOLENOID_LOCK_PIN, PI_OUTPUT);
}

// Function to read the calibration factor from the file
float read_calibration(pigpio *gpio) {
    int fd = open(CALIBRATION_FILE, O_RDONLY);
    if (fd == -1) {
        printf("Error opening calibration file\n");
        exit(1);
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        printf("Error reading file stats\n");
        exit(1);
    }

    float calibration_factor;
    if (fread(&calibration_factor, sizeof(float), 1, fd) != 1) {
        printf("Error reading calibration factor\n");
        exit(1);
    }

    close(fd);
    return calibration_factor;
}

// Function to write the calibration factor to the file
void write_calibration(pigpio *gpio, float calibration_factor) {
    int fd = open(CALIBRATION_FILE, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        printf("Error writing to calibration file\n");
        exit(1);
    }

    if (fwrite(&calibration_factor, sizeof(float), 1, fd) != 1) {
        printf("Error writing calibration factor\n");
        exit(1);
    }

    close(fd);
}

// Function to read the weight from the HX711
int read_weight(pigpio *gpio, float *weight) {
    int fd = open("/dev/hx711_raw", O_RDONLY);
    if (fd == -1) {
        printf("Error opening HX711 device\n");
        exit(1);
    }

    struct iovec iov = { .iov_base = (void *)weight, .iov_len = sizeof(float) };
    struct aio_context ctx;
    struct aio_eventfd abuf;
    abuf.events = AIO_EVENT_READ;
    abuf.data = &iov;
    abuf.size = sizeof(iov);

    if (aio_read(fd, &ctx, &abuf, 1) == -1) {
        printf("Error reading from HX711 device\n");
        exit(1);
    }

    close(fd);
    return 0;
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    printf("Received SIGINT signal, unlocking solenoid and terminating driver\n");
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Error initializing GPIO\n");
        exit(1);
    }

    gpio_write(SOLENOID_LOCK_PIN, 0);
    gpio_close(gpio);
    exit(0);
}

int main() {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Error initializing GPIO\n");
        exit(1);
    }

    init_gpio(gpio);

    float calibration_factor = 0.0;
    time_t last_calibration = 0;

    while (1) {
        // Prompt user to place a known weight
        printf("Please place a known weight on the load cell\n");

        // Read the calibration factor from the file
        calibration_factor = read_calibration(gpio);

        // Prompt user to enter the weight
        float weight;
        printf("Enter the weight (in kg): ");
        scanf("%f", &weight);

        // Write the calibration factor to the file
        write_calibration(gpio, calibration_factor);

        // Read the weight from the HX711
        float raw_weight;
        if (read_weight(gpio, &raw_weight) == -1) {
            printf("Error reading from HX711 device\n");
            continue;
        }

        // Apply calibration factor
        float calibrated_weight = raw_weight * calibration_factor;

        // Check if the weight exceeds the threshold
        if (calibrated_weight > 5.0) {
            // Engage solenoid lock
            gpio_write(SOLENOID_LOCK_PIN, 1);
            printf("Weight exceeds threshold, engaging solenoid lock\n");

            // Log timestamp and weight to security.log
            FILE *log_file = fopen(SECURITY_LOG_FILE, "a");
            if (log_file == NULL) {
                printf("Error opening security log file\n");
                continue;
            }

            fprintf(log_file, "%s %f\n", ctime(&time(NULL)), calibrated_weight);
            fclose(log_file);

            // Release solenoid lock after 5 seconds
            sleep(5);
            gpio_write(SOLENOID_LOCK_PIN, 0);
            printf("Solenoid lock released\n");
        }

        // Check for communication timeout
        if (gpio_get_value(HX711_DATA_PIN) == 1) {
            printf("Communication timeout, skipping weight reading\n");
            continue;
        }

        // Log timestamp and weight to security.log
        FILE *log_file = fopen(SECURITY_LOG_FILE, "a");
        if (log_file == NULL) {
            printf("Error opening security log file\n");
            continue;
        }

        fprintf(log_file, "%s %f\n", ctime(&time(NULL)), calibrated_weight);
        fclose(log_file);
    }

    // Clean up
    pigpio_close(gpio);
    return 0;
}

