#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <time.h>
#include <syslog.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define GPIO16 16
#define GPIO20 20
#define RELAY_PIN GPIO20
#define RELAY_STATE 1
#define RELAY_DIR 0
#define LOG_FILE "relay_events.log"

int main(int argc, char **argv) {
    int gpio;
    int relay_state = 0;
    struct timespec last_state_change;
    struct timespec current_time;
    struct stat log_file_stat;
    int log_file_fd = -1;
    int sensor_fd = -1;
    int ret;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %d", gpio);
        return 1;
    }

    // Open log file
    log_file_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_file_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file: %d", log_file_fd);
        pigpio_close(gpio);
        return 1;
    }

    // Set up relay pin as output
    ret = pigpio_mode(gpio, RELAY_PIN, pigpio.OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set up relay pin: %d", ret);
        close(log_file_fd);
        pigpio_close(gpio);
        return 1;
    }

    // Set initial relay state
    ret = pigpio_write(gpio, RELAY_PIN, relay_state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set initial relay state: %d", ret);
        close(log_file_fd);
        pigpio_close(gpio);
        return 1;
    }

    // Open sensor
    sensor_fd = pigpio_i2c_open(0x4c, 0x11, 1000);
    if (sensor_fd < 0) {
        syslog(LOG_ERR, "Failed to open sensor: %d", sensor_fd);
        close(log_file_fd);
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        // Read sensor value
        ret = pigpio_i2c_read(sensor_fd, 0x00, 1);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read sensor: %d", ret);
            close(log_file_fd);
            pigpio_close(gpio);
            pigpio_i2c_close(sensor_fd);
            return 1;
        }

        // Check for obstacle
        if (ret == 0) {
            // Toggle relay state
            relay_state = !relay_state;
            ret = pigpio_write(gpio, RELAY_PIN, relay_state);
            if (ret < 0) {
                syslog(LOG_ERR, "Failed to toggle relay state: %d", ret);
                close(log_file_fd);
                pigpio_close(gpio);
                pigpio_i2c_close(sensor_fd);
                return 1;
            }

            // Log event
            time(&current_time);
            strftime(log_file_stat.st_mtime, sizeof(log_file_stat.st_mtime), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
            char log_message[256];
            sprintf(log_message, "Relay state changed to %s at %s", relay_state ? "ON" : "OFF", log_file_stat.st_mtime);
            ret = write(log_file_fd, log_message, strlen(log_message));
            if (ret < 0) {
                syslog(LOG_ERR, "Failed to write to log file: %d", ret);
                close(log_file_fd);
                pigpio_close(gpio);
                pigpio_i2c_close(sensor_fd);
                return 1;
            }
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    pigpio_close(gpio);
    pigpio_i2c_close(sensor_fd);
    close(log_file_fd);
    return 0;
}

