#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define GPIO_BCM17 17
#define GPIO_BCM18 18
#define LOG_FILE "motion_log.txt"
#define BUZZER_PIN GPIO_BCM18
#define BUZZER_VOLTAGE 5
#define BUZZER_DURATION 2000000 // 2 seconds in microseconds

// Define a function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Turn off the buzzer
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        perror("gpioWrite");
        exit(1);
    }
    // Close the log file
    if (fclose(FILE*) < 0) {
        perror("fclose");
        exit(1);
    }
    // Release GPIO resources
    if (gpioRelease(BUZZER_PIN) < 0) {
        perror("gpioRelease");
        exit(1);
    }
    exit(0);
}

int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set up the buzzer pin as an output
    if (gpioMode(BUZZER_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        perror("gpioWrite");
        exit(1);
    }

    // Set up the PIR sensor pin as an input
    if (gpioMode(GPIO_BCM17, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }

    // Open the log file for writing
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the PIR sensor value
        int sensor_value = gpioRead(GPIO_BCM17);
        if (sensor_value < 0) {
            perror("gpioRead");
            exit(1);
        }

        // Check if the sensor is active-high
        if (sensor_value == 1) {
            // Turn on the buzzer
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                perror("gpioWrite");
                exit(1);
            }

            // Log the timestamp
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s\n", timestamp);

            // Wait for the buzzer duration
            usleep(BUZZER_DURATION);

            // Turn off the buzzer
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                perror("gpioWrite");
                exit(1);
            }
        }
    }

    // Clean up
    gpioRelease(BUZZER_PIN);
    gpioRelease(GPIO_BCM17);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

