            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                perror("gpioWrite");
                exit(1);
            }
        }
    }

    // Clean up
    gpioRelease(BUZZER_PIN);
    gpioRelease(GPIO_BCM17);
    gpioTerminate();
    fclose(log_file);
    return 0;
}
