#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <syslog.h>

#define LOG_FILE "trace_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%f %d %d %d %d\n"

// Define constants for GPIO pins
#define LEFT_SENSOR_GPIO 4
#define MIDDLE_SENSOR_GPIO 17
#define RIGHT_SENSOR_GPIO 27
#define LEFT_MOTOR_PWM 22
#define RIGHT_MOTOR_PWM 23
#define LEFT_MOTOR_DIR 24
#define RIGHT_MOTOR_DIR 25

// Define constants for motor speeds
#define BASE_SPEED 150
#define MAX_SPEED 255

// Define constants for sensor states
#define LOW 0
#define HIGH 1

// Define constants for motor directions
#define FORWARD 1
#define BACKWARD -1

// Define constants for PWM frequencies
#define PWM_FREQ 1000

// Define constants for logging
#define LOG_INTERVAL 10

// Structure to hold sensor and motor data
typedef struct {
    int left_sensor;
    int middle_sensor;
    int right_sensor;
    int left_motor_speed;
    int right_motor_speed;
} RobotState;

// Function to initialize the GPIO driver
int init_gpio(pigpio *gpio) {
    if (gpio_init(gpio) < 0) {
        perror("gpio_init");
        return -1;
    }
    if (gpio_set_mode(LEFT_SENSOR_GPIO, PI_INPUT) < 0) {
        perror("gpio_set_mode");
        return -1;
    }
    if (gpio_set_mode(MIDDLE_SENSOR_GPIO, PI_INPUT) < 0) {
        perror("gpio_set_mode");
        return -1;
    }
    if (gpio_set_mode(RIGHT_SENSOR_GPIO, PI_INPUT) < 0) {
        perror("gpio_set_mode");
        return -1;
    }
    if (gpio_set_mode(LEFT_MOTOR_PWM, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        return -1;
    }
    if (gpio_set_mode(RIGHT_MOTOR_PWM, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        return -1;
    }
    if (gpio_set_mode(LEFT_MOTOR_DIR, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        return -1;
    }
    if (gpio_set_mode(RIGHT_MOTOR_DIR, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        return -1;
    }
    return 0;
}

// Function to read sensor values
void read_sensors(pigpio *gpio, RobotState *state) {
    int left_value = gpio_get_value(LEFT_SENSOR_GPIO);
    int middle_value = gpio_get_value(MIDDLE_SENSOR_GPIO);
    int right_value = gpio_get_value(RIGHT_SENSOR_GPIO);
    state->left_sensor = left_value;
    state->middle_sensor = middle_value;
    state->right_sensor = right_value;
}

// Function to set motor speeds
void set_motor_speeds(pigpio *gpio, int left_speed, int right_speed) {
    int left_value = left_speed > 0 ? left_speed : 0;
    int right_value = right_speed > 0 ? right_speed : 0;
    gpio_set PWM(LEFT_MOTOR_PWM, left_value, PWM_FREQ);
    gpio_set PWM(RIGHT_MOTOR_PWM, right_value, PWM_FREQ);
}

// Function to log sensor and motor data
void log_data(pigpio *gpio, RobotState *state) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char log_string[LOG_FORMAT];
    sprintf(log_string, LOG_FORMAT, time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday, state->left_sensor, state->middle_sensor, state->right_sensor, state->left_motor_speed, state->right_motor_speed);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }
    if (fputs(log_string, log_file) < 0) {
        perror("fputs");
        fclose(log_file);
        return;
    }
    fclose(log_file);
}

// Function to handle SIGINT signal
void sigint_handler(int signal) {
    pigpio *gpio = pigpio_get();
    if (gpio == NULL) {
        return;
    }
    set_motor_speeds(gpio, 0, 0);
    gpio_close(gpio);
    exit(0);
}

int main() {
    pigpio *gpio = pigpio_get();
    if (gpio == NULL) {
        perror("pigpio_get");
        return -1;
    }
    if (init_gpio(gpio) < 0) {
        perror("init_gpio");
        return -1;
    }
    struct sigaction sigaction;
    sigaction.sa_handler = sigint_handler;
    sigaction.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sigaction, NULL) < 0) {
        perror("sigaction");
        return -1;
    }
    while (1) {
        RobotState state;
        read_sensors(gpio, &state);
        if (state.middle_sensor == LOW) {
            set_motor_speeds(gpio, BASE_SPEED, BASE_SPEED);
        } else if (state.left_sensor == LOW) {
            set_motor_speeds(gpio, BASE_SPEED / 2, BASE_SPEED);
        } else if (state.right_sensor == LOW) {
            set_motor_speeds(gpio, BASE_SPEED, BASE_SPEED / 2);
        } else {
            set_motor_speeds(gpio, 0, 0);
        }
        log_data(gpio, &state);
        usleep(LOG_INTERVAL * 1000000);
    }
    return 0;
}

