#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x23
#define RELAY_PIN 23
#define DELAY 180
#define LOG_FILE "grow_log.txt"

int main() {
    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(gpio, RELAY_PIN, 0);

    // Open I2C file
    int fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Map file to memory
    struct iovec iov;
    iov.iov_base = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (iov.iov_base == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    // Set up I2C
    int i2c = i2cGetDev(1);
    if (i2c < 0) {
        perror("i2cGetDev");
        return 1;
    }

    while (1) {
        // Read illuminance from BH1750 sensor
        uint16_t lux;
        if (i2cWrite(i2c, I2C_ADDRESS, 0x00, 2, &lux) < 0) {
            fprintf(iov.iov_base, "I2C error: %d\n", errno);
            continue;
        }

        // Check if sensor is detected
        if (lux == 0) {
            fprintf(iov.iov_base, "Sensor not detected\n");
            continue;
        }

        // Check if lux reading is below threshold
        if (lux < 150) {
            gpioWrite(gpio, RELAY_PIN, 1);
            fprintf(iov.iov_base, "%d %d\n", (int)time(NULL), lux);
        } else {
            gpioWrite(gpio, RELAY_PIN, 0);
            fprintf(iov.iov_base, "%d %d\n", (int)time(NULL), lux);
        }

        // Delay
        usleep(DELAY * 1000);
    }

    // Clean up
    close(fd);
    munmap(iov.iov_base, sizeof(iov));
    gpioTerminate();
    i2cRelease(i2c);
    return 0;
}

