#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <pigpio.h>

#define SOUND_SENSOR_MODE 1
#define ALARM_NODE_MODE 2
#define SOUND_SENSOR_PIN 17
#define ALARM_PIN 27
#define ZMQ_SOCKET "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [SOUND_SENSOR_MODE|ALARM_NODE_MODE]\n", argv[0]);
        return 1;
    }

    int mode = atoi(argv[1]);
    if (mode != SOUND_SENSOR_MODE && mode != ALARM_NODE_MODE) {
        fprintf(stderr, "Invalid mode\n");
        return 1;
    }

    int gpio = 0;
    if (mode == SOUND_SENSOR_MODE) {
        gpio = 17;
    } else {
        gpio = 27;
    }

    if (gpio < 0) {
        fprintf(stderr, "Invalid GPIO number\n");
        return 1;
    }

    if (gpio != 17 && gpio != 27) {
        fprintf(stderr, "Invalid GPIO pin\n");
        return 1;
    }

    if (gpio == 17) {
        if (gpiochip_init(gpio) < 0) {
            fprintf(stderr, "Failed to initialize GPIO chip\n");
            return 1;
        }
    }

    void *context = zmq_ctx_new();
    if (context == NULL) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return 1;
    }

    void *socket = zmq_socket(context, ZMQ_SUB, 0);
    if (socket == NULL) {
        fprintf(stderr, "Failed to create ZeroMQ socket\n");
        zmq_ctx_destroy(context);
        return 1;
    }

    if (zmq_bind(socket, ZMQ_TOPIC) < 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket\n");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return 1;
    }

    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return 1;
    }

    if (mode == SOUND_SENSOR_MODE) {
        while (1) {
            int value = gpio_get_value(gpio);
            if (value == 0) {
                zmq_send(socket, "", 0);
            }
            usleep(10000);
        }
    } else {
        void *subsocket = zmq_socket(context, ZMQ_SUB, 0);
        if (subsocket == NULL) {
            fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
            zmq_ctx_destroy(context);
            return 1;
        }

        if (zmq_connect(subsocket, ZMQ_TOPIC) < 0) {
            fprintf(stderr, "Failed to connect ZeroMQ subscriber socket\n");
            zmq_close(subsocket);
            zmq_ctx_destroy(context);
            return 1;
        }

        while (1) {
            char message[1024];
            int bytes_received = zmq_recv(subsocket, message, 1024, 0);
            if (bytes_received < 0) {
                fprintf(stderr, "Failed to receive message from ZeroMQ subscriber socket\n");
                zmq_close(subsocket);
                zmq_ctx_destroy(context);
                return 1;
            }
            if (bytes_received == 0) {
                break;
            }
            zmq_send(socket, message, bytes_received, 0);
            usleep(10000);
        }

        zmq_close(subsocket);
    }

    gpio_close(gpio);
    gpiochip_shutdown(gpio);
    zmq_ctx_destroy(context);
    return 0;
}

void sigint_handler(int sig) {
    gpio_close(gpio);
    gpiochip_shutdown(gpio);
    zmq_close(socket);
    zmq_ctx_destroy(context);
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_close(gpio);
    gpiochip_shutdown(gpio);
    zmq_close(socket);
    zmq_ctx_destroy(context);
    exit(0);
}

