#define IR_FRAME_LENGTH 9 + 4.5 + (32 * 560) + 1690 + 560
#define IR_SPACE 560
#define IR_MARK 560
#define IR_CHECKSUM 0x55
#define IR_ADDRESS 0xFF
#define IR_COMMAND 0x00
#define IR_EXTENDED 0x80

// Define structures
typedef struct {
    int pin;
    int mode;
    int callback;
} gpio_config_t;

typedef struct {
    int sock;
    char *host;
    int port;
    char *topic;
} mqtt_config_t;

// Define functions
void init_gpio(gpio_config_t *config);
void init_mqtt(mqtt_config_t *config);
void decode_ir_frame(int pin, int frame);
void publish_mqtt(const char *message);
void handle_signal(int sig);
void cleanup();

int main(int argc, char **argv) {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID, LOG_USER);

    // Initialize GPIO
    gpio_config_t config;
    config.pin = IR_PIN;
    config.mode = GPIO_MODE_INPUT;
    config.callback = NULL;
    init_gpio(&config);

