#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <pigpio.h>
#include <libgen.h>

#define I2C_ADDRESS 0x18
#define CSV_FILE "seismic_data.csv"
#define CSV_ERROR_FILE "seismic_error.log"

int main(int argc, char **argv) {
    int i2c_fd = -1;
    int csv_fd = -1;
    int retry = 0;
    int interval = 1;
    char *output_file = CSV_FILE;
    char *error_file = CSV_ERROR_FILE;

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            if (i + 1 < argc) {
                i2c_fd = open("/dev/i2c-1", O_RDWR);
                if (i2c_fd < 0) {
                    perror("open");
                    return 1;
                }
                i2c_fd = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
                if (i2c_fd < 0) {
                    perror("ioctl");
                    return 1;
                }
            } else {
                fprintf(stderr, "Error: -a option requires a value\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-i") == 0) {
            if (i + 1 < argc) {
                interval = atoi(argv[++i]);
                if (interval <= 0) {
                    fprintf(stderr, "Error: interval must be a positive integer\n");
                    return 1;
                }
            } else {
                fprintf(stderr, "Error: -i option requires a value\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-f") == 0) {
            if (i + 1 < argc) {
                output_file = argv[++i];
                if (access(output_file, W_OK) != 0) {
                    fprintf(stderr, "Error: output file '%s' not found\n", output_file);
                    return 1;
                }
            } else {
                fprintf(stderr, "Error: -f option requires a value\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-e") == 0) {
            if (i + 1 < argc) {
                error_file = argv[++i];
                if (access(error_file, W_OK) != 0) {
                    fprintf(stderr, "Error: error file '%s' not found\n", error_file);
                    return 1;
                }
            } else {
                fprintf(stderr, "Error: -e option requires a value\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Error: unknown option '%s\n", argv[i]);
            return 1;
        }
    }

    // Open CSV file for writing
    csv_fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("open");
        return 1;
    }

    // Open error file for writing
    csv_fd = open(error_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("open");
        return 1;
    }

    // Set up I2C
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: unable to set up I2C\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Main loop
    while (1) {
        // Read from I2C
        if (i2c_fd < 0) {
            perror("i2c_fd");
            return 1;
        }
        unsigned char data[6];
        ssize_t bytes_read = read(i2c_fd, data, 6);
        if (bytes_read < 0) {
            perror("read");
            retry++;
            if (retry > 3) {
                break;
            }
            usleep(10 * 1000);
            continue;
        }
        if (bytes_read != 6) {
            fprintf(stderr, "Error: unexpected number of bytes read from I2C\n");
            retry++;
            if (retry > 3) {
                break;
            }
            usleep(10 * 1000);
            continue;
        }

        // Check for sensor-absent and bus-error conditions
        if (data[0] != 0x55) {
            fprintf(stderr, "Error: sensor-absent\n");
            retry++;
            if (retry > 3) {
                break;
            }
            usleep(10 * 1000);
            continue;
        }
        if (data[1] != 0x55) {
            fprintf(stderr, "Error: bus-error\n");
            retry++;
            if (retry > 3) {
                break;
            }
            usleep(10 * 1000);
            continue;
        }

        // Convert data to g values
        float x_g = (data[2] << 8) | data[3] / 256.0f;
        float y_g = (data[4] << 8) | data[5] / 256.0f;
        float z_g = (data[2] << 16) | (data[3] << 8) | (data[4] << 8) | data[5] / 256.0f;

        // Log data
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        fprintf(csv_fd, "%s,%f,%f,%f\n", timestamp, x_g, y_g, z_g);
        fflush(csv_fd);

        // Sleep for interval
        usleep(interval * 1000000);
    }

    // Close files
    if (csv_fd >= 0) {
        close(csv_fd);
    }
    if (error_fd >= 0) {
        close(error_fd);
    }

    return 0;
}

