#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x23
#define I2C_TIMEOUT 100
#define I2C_BUFFER_SIZE 2
#define UDP_PORT 5000
#define UDP_ADDRESS "239.255.255.250"
#define TTL 1

int main() {
    int i2c_fd, sock, ret;
    struct i2c_msg msg;
    struct i2c_file *file;
    struct sockaddr_in server_addr;
    struct sigaction sa;
    char buffer[I2C_BUFFER_SIZE];

    // Install signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open I2C file descriptor
    file = i2c_open("/dev/i2c-1", O_RDWR, 0);
    if (file == -1) {
        perror("i2c_open");
        exit(1);
    }

    // Set I2C address
    ret = i2c_set_address(file, I2C_ADDRESS);
    if (ret == -1) {
        perror("i2c_set_address");
        i2c_close(file);
        exit(1);
    }

    // Create UDP socket
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("socket");
        i2c_close(file);
        exit(1);
    }

    // Set UDP address and port
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_ADDRESS, &server_addr.sin_addr);

    // Bind UDP socket
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind");
        close(sock);
        i2c_close(file);
        exit(1);
    }

    while (1) {
        // Read I2C data
        ret = i2c_read(file, buffer, I2C_BUFFER_SIZE, I2C_TIMEOUT);
        if (ret == -1) {
            perror("i2c_read");
            sleep(1);
            continue;
        }

        // Check for bus error
        if (ret == -2) {
            perror("i2c_read");
            sleep(1);
            continue;
        }

        // Convert 16-bit big-endian raw value to floating-point lux value
        float lux = (float)htobe16(buffer[0]) * 0.00013195;

        // Broadcast lux value via UDP
        struct sockaddr_in dest_addr;
        dest_addr.sin_family = AF_INET;
        dest_addr.sin_port = htons(UDP_PORT);
        inet_pton(AF_INET, UDP_ADDRESS, &dest_addr.sin_addr);
        ret = sendto(sock, &lux, sizeof(lux), 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
        if (ret == -1) {
            perror("sendto");
            sleep(1);
            continue;
        }

        // Check for error
        if (ret == -1) {
            perror("sendto");
            sleep(1);
            continue;
        }
    }

    // Close I2C file descriptor and UDP socket
    i2c_close(file);
    close(sock);

    return 0;
}

void sigint_handler(int sig) {
    i2c_close(-1);
    close(-1);
    exit(0);
}

