            perror("i2c_read");
            sleep(1);
            continue;
        }

        // Check for bus error
        if (ret == -2) {
            perror("i2c_read");
            sleep(1);
            continue;
        }

        // Convert 16-bit big-endian raw value to floating-point lux value
        float lux = (float)htobe16(buffer[0]) * 0.00013195;

        // Broadcast lux value via UDP
        struct sockaddr_in dest_addr;
        dest_addr.sin_family = AF_INET;
        dest_addr.sin_port = htons(UDP_PORT);
        inet_pton(AF_INET, UDP_ADDRESS, &dest_addr.sin_addr);
        ret = sendto(sock, &lux, sizeof(lux), 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
        if (ret == -1) {
            perror("sendto");
            sleep(1);
            continue;
        }

        // Check for error
        if (ret == -1) {
            perror("sendto");
            sleep(1);
            continue;
        }
    }

    // Close I2C file descriptor and UDP socket
    i2c_close(file);
    close(sock);

    return 0;
}

void sigint_handler(int sig) {
    i2c_close(-1);
    close(-1);
    exit(0);
}
