        fprintf(stderr, "Error reading magic word\n");
        close(uart_fd);
        close(csv_fd);
        gpioTerminate();
        return 1;
    }
    if (memcmp(buffer, &MAGIC_WORD, 8) != 0) {
        fprintf(stderr, "Invalid magic word\n");
        close(uart_fd);
        close(csv_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize variables
    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    int object_index = 0;
    double range_m = 0.0;
    double velocity_mps = 0.0;

    while (1) {
        // Read UART
        bytes_read = read(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("read");
            break;
        }
        if (bytes_read < 8) {
            fprintf(stderr, "Error reading UART\n");
            break;
        }

        // Validate TLV payload
        if (buffer[0] != 0x01 || buffer[1] != 0x00 || buffer[2] != 0x00 || buffer[3] != 0x00 || buffer[4] != 0x00 || buffer[5] != 0x00 || buffer[6] != 0x00 || buffer[7] != 0x00) {
            fprintf(stderr, "Invalid TLV payload\n");
            continue;
        }

        // Extract range and velocity
        range_m = (double)htonl((uint64_t)buffer[8] << 32 | buffer[7]) / 1000.0;
        velocity_mps = (double)htonl((uint64_t)buffer[6] << 32 | buffer[5]) / 1000.0;

        // Append to CSV
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
        fprintf(csv_fd, "%s,%d,%f,%f\n", timestamp, object_index, range_m, velocity_mps);
        object_index++;

        // Sleep for 10ms
        usleep(10000);
    }

    // Close UART
    close(uart_fd);

    // Close CSV file
    if (flock(csv_fd, LOCK_UN) < 0) {
        perror("flock");
    }
    close(csv_fd);

    // Release resources
    gpioTerminate();

    return 0;
}

