#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

#define UART_BAUD 115200
#define UART_TIMEOUT 0.5
#define UART_TIMEOUT_MS (int)(UART_TIMEOUT * 1000)
#define UART_TIMEOUT_SEC 2
#define UART_TIMEOUT_MS_SEC (int)(UART_TIMEOUT_SEC * 1000)

int main() {
    int fd;
    struct termios oldt, newt;
    struct timeval tv;
    struct timeval tv2;
    char line[256];
    char *ptr;
    char *token;
    char timestamp[20];
    char range[10];
    int bytes_read;
    int bytes_read2;
    int result;
    int status;
    int r, w, x, y;
    struct sigaction sa;

    // Install signal handlers
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open UART
    fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        exit(1);
    }

    // Set UART parameters
    tcgetattr(fd, &oldt);
    cfsetispeed(&oldt, UART_BAUD);
    cfsetospeed(&oldt, UART_BAUD);
    tcsetattr(fd, TCSANOW, &oldt);

    // Set UART timeout
    tv.tv_sec = UART_TIMEOUT_SEC;
    tv.tv_usec = 0;
    if (select(fd, NULL, NULL, NULL, &tv) == -1) {
        perror("select");
        exit(1);
    }

    // Set UART inter-byte timeout
    struct termios newt;
    tcgetattr(fd, &oldt);
    cfsetispeed(&newt, UART_BAUD);
    cfsetospeed(&newt, UART_BAUD);
    newt.c_cflag &= ~PARENB;
    newt.c_cflag &= ~CSTOPB;
    newt.c_cflag &= ~CSIZE;
    newt.c_cflag &= ~CS8;
    newt.c_cflag |= (UART_BAUD << CS8);
    newt.c_lflag &= ~ICANON;
    newt.c_lflag &= ~ECHO;
    newt.c_lflag &= ~ECHOE;
    newt.c_lflag &= ~ECHOK;
    newt.c_lflag &= ~ISIG;
    newt.c_cc[VMIN] = 1;
    newt.c_cc[VTIME] = UART_TIMEOUT_MS;
    if (tcsetattr(fd, TCSANOW, &newt) == -1) {
        perror("tcsetattr");
        exit(1);
    }

    // Read and parse data
    while (1) {
        // Read data
        bytes_read = read(fd, line, 256);
        if (bytes_read == -1) {
            perror("read");
            break;
        }
        if (bytes_read == 0) {
            // No data available
            continue;
        }

        // Accumulate partial reads
        if (ptr = memchr(line, '\n', bytes_read)) {
            *ptr = '\0';
        } else {
            // No newline character found
            continue;
        }

        // Parse line
        ptr = strtok(line, "\n");
        if (ptr == NULL) {
            // No valid line found
            continue;
        }

        // Parse timestamp and range
        sscanf(ptr, "%19s,%9s\n", timestamp, range);

        // Log detection
        printf("Timestamp: %s, Range: %s meters\n", timestamp, range);

        // Reset line buffer
        memset(line, 0, 256);
    }

    // Close UART
    close(fd);

    return 0;
}

