#include <unistd.h>
#include <signal.h>

// Define constants
#define GPIO_LEFT 4
#define GPIO_MIDDLE 17
#define GPIO_RIGHT 27
#define BAUD 115200
#define BUFFER_SIZE 256

// Define structures
typedef struct {
    int fd;
    struct termios options;
} uart_t;

// Define functions
void init_uart(uart_t *uart) {
    if (tcgetattr(uart->fd, &uart->options) == -1) {
        perror("tcgetattr");
        exit(1);
    }
    cfsetispeed(&uart->options, BAUD);
    cfsetospeed(&uart->options, BAUD);
    if (tcsetattr(uart->fd, TCSANOW, &uart->options) == -1) {
        perror("tcsetattr");
        exit(1);
    }
}

void close_uart(uart_t *uart) {
    if (tcsetattr(uart->fd, TCSANOW, &uart->options) == -1) {
        perror("tcsetattr");
    }
    close(uart->fd);
}

void send_uart(uart_t *uart, const char *message) {
    if (write(uart->fd, message, strlen(message)) == -1) {
        perror("write");
    }
}

void handle_signal(int sig) {
    close_uart(uart);
    pigpio_close();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_init() == -1) {
        perror("pigpio_init");
        exit(1);
    }

    // Initialize UART
    uart_t uart;
    uart.fd = open("/dev/ttyAMA0", O_RDWR);
    if (uart.fd == -1) {
        perror("open");
        exit(1);
    }
    init_uart(&uart);

    // Configure GPIO pins
    if (pigpio_mode(GPIO_LEFT, PI_INPUT) == -1) {
        perror("pigpio_mode");
        exit(1);
    }
    if (pigpio_mode(GPIO_MIDDLE, PI_INPUT) == -1) {
        perror("pigpio_mode");
        exit(1);
    }
    if (pigpio_mode(GPIO_RIGHT, PI_INPUT) == -1) {
        perror("pigpio_mode");
        exit(1);
    }
    if (pigpio_pull_up(GPIO_LEFT, PI_UPDOWN) == -1) {
        perror("pigpio_pull_up");
        exit(1);
    }
    if (pigpio_pull_up(GPIO_MIDDLE, PI_UPDOWN) == -1) {
        perror("pigpio_pull_up");
        exit(1);
    }
    if (pigpio_pull_up(GPIO_RIGHT, PI_UPDOWN) == -1) {
        perror("pigpio_pull_up");
        exit(1);
    }

    // Main loop
    struct timespec ts;
    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        ts.tv_sec = tv.tv_sec;
        ts.tv_usec = tv.tv_usec;
        ts.tv_sec += 100;
        if (ts.tv_sec >= 100) {
            ts.tv_sec = 0;
            ts.tv_usec = 0;
        }

        int left = pigpio_read(GPIO_LEFT);
        int middle = pigpio_read(GPIO_MIDDLE);
        int right = pigpio_read(GPIO_RIGHT);

